  [8827] = {
    id = 8827,
    title = "Winter's Presents",
    reqLevel = 1,
    questLevel = 1,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Wonderform Operator",
    objectives = "Speak with Greatfather Winter. He is located near the Smokywood Pastures vendor area in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "I hear Greatfather Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Ironforge. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt.\n\nBut you should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.",
    isForever = false,
  },
  [8828] = {
