  [4641] = {
    id = 4641,
    title = "Your Place In The World",
    reqLevel = 1,
    questLevel = 1,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Kaltunk",
    objectives = "Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west.",
    rewards = "40 XP",
    tip = "Finally, you are of age, $N... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.\n\nYes...\n\n<Kaltunk looks you over.>\n\nYou will do nicely.\n\nNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.\n\n<Kaltunk laughs.>\n\nReport to Gornek, he should be able to assign a task better suited to a young $c. You will find Gornek in the Den, to the west.",
    isForever = false,
  },
  [752] = {
    id = 752,
    title = "A Humble Task",
    reqLevel = 1,
    questLevel = 2,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Chief Hawkwind",
    objectives = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.",
    rewards = "85 XP • 17c",
    tip = "All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?",
    isForever = false,
  },
  [170] = {
    id = 170,
    title = "A New Threat",
    reqLevel = 1,
    questLevel = 2,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Balir Frosthammer",
    objectives = "Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.",
    rewards = "170 XP",
    tip = "I hope you're here to lend us a hand, $c. After the last trogg attack, we could use all the help we can get.\n\nI hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception. They've been spotted all over the hills to the southeast and near the frozen lake.\n\nAnd that's not all, just a few nights ago, they attacked and overran our camp to the west! \n\nWe're a bit shorthanded here, $g lad : lass;, and we need strong arms to help drive the troggs back.",
    isForever = false,
  },
  [788] = {
    id = 788,
    title = "Cutting Teeth",
    reqLevel = 1,
    questLevel = 2,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Gornek",
    objectives = "Kill 10 Mottled Boars then return to Gornek at the Den.",
    rewards = "170 XP",
    tip = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you would find a good match with the mottled boars you'll find to the north of here.",
    isForever = false,
  },
  [5261] = {
    id = 5261,
    title = "Eagan Peltskinner",
    reqLevel = 1,
    questLevel = 2,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Deputy Willem",
    objectives = "Speak with Eagan Peltskinner.",
    rewards = "85 XP",
    tip = "Eagan Peltskinner is looking for someone to hunt wolves for him.  That's good news, because we're seeing a lot more wolves in Northshire Valley lately.\n\nIf you're interested then speak with Eagan.  He's around the side of the abbey, to the left.",
    isForever = false,
  },
  [333] = {
    id = 333,
    title = "Harlan Needs a Resupply",
    reqLevel = 1,
    questLevel = 2,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Harlan Bagley",
    objectives = "Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.",
    rewards = "85 XP • 17c",
    tip = "We've been doing a lot of business lately.  It seems like everyone is buying armor and sturdy clothes.  Almost like they expect a cold, harsh season ahead...\n\nBut those are future worries.  My worry today is that I'm running out of knitted clothing to sell.  I need another load from our supplier.\n\nIf you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.",
    isForever = false,
  },
  [7] = {
    id = 7,
    title = "Kobold Camp Cleanup",
    reqLevel = 1,
    questLevel = 2,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Marshal McBride",
    objectives = "Kill 10 Kobold Vermin, then return to Marshal McBride.",
    rewards = "170 XP • 25c",
    tip = "Pro-tip: One of the greatest quest climaxes in Warcraft lore. Let Taelan tank the Scarlet mobs—do not pull aggro from Grand Inquisitor Isillien until Tirion arrives!",
    isForever = false,
  },
  [334] = {
    id = 334,
    title = "Package for Thurman",
    reqLevel = 1,
    questLevel = 2,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Rema Schneider",
    objectives = "Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.",
    rewards = "130 XP",
    tip = "My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter.  He was in a hurry today and forgot his shears and needles.  I know a great $C like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work!\n\nPlease, $N.  Can you take my son's sewing kit to him?  Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.",
    isForever = false,
  },
  [456] = {
    id = 456,
    title = "The Balance of Nature",
    reqLevel = 1,
    questLevel = 2,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Conservator Ilthalaine",
    objectives = "Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.",
    rewards = "170 XP • 35c",
    tip = "Greetings, $N.  I am Conservator Ilthalaine.  My purpose in Shadowglen is to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered.\n\nUnfortunately, the nightsaber and thistle boar populations grew too large.  Shadowglen can only produce so much food for the beasts.  Journey forth, young $c, and thin the boar and saber populations so that nature's harmony will be preserved.",
    isForever = false,
  },
  [376] = {
    id = 376,
    title = "The Damned",
    reqLevel = 2,
    questLevel = 2,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Novice Elreth",
    objectives = "Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.",
    rewards = "170 XP",
    tip = "My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need.\n\nFrom the look of it, you'll be enlisted in his service also... hunting the Mindless Ones, if I know his mind. Well, if you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. I'm running out of paws and wings, and if you bring me some, I'll find some armor for you. You'll find a good number of wolves and bats to the south.",
    isForever = false,
  },
  [747] = {
    id = 747,
    title = "The Hunt Begins",
    reqLevel = 1,
    questLevel = 2,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Grull Hawkwind",
    objectives = "Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.",
    rewards = "170 XP",
    tip = "You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff. But before that can happen you must prove yourself to my father, Chief Hawkwind.\n\nUp here on Red Cloud Mesa we pride ourselves on keen hunting skills. Tauren hunt out of necessity and for sport. Our supply of meats has run low and we require feathers for clothing. Hunt the nearby plainstriders and prove yourself by resupplying the village.",
    isForever = false,
  },
  [364] = {
    id = 364,
    title = "The Mindless Ones",
    reqLevel = 1,
    questLevel = 2,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Shadow Priest Sarvis",
    objectives = "Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies.",
    rewards = "170 XP • 17c",
    tip = "We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres.\n\nThe northern part of the village has become overrun with the Mindless Ones, and they must be destroyed. Destroy them, show them no mercy, our former brothers and sisters as they might be. The Fallen are nothing but The Lich King's slaves.",
    isForever = false,
  },
  [332] = {
    id = 332,
    title = "Wine Shop Advert",
    reqLevel = 1,
    questLevel = 2,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Renato Gallina",
    objectives = "Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.",
    rewards = "130 XP",
    tip = "If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind.  And we're not far, still in the Trade District along the city's lovely canals.\n\nHere, take this pamphlet.  Bring it to my sister Suzetta at our shop for a complimentary bottle of our famous pinot noir.  You won't regret it!",
    isForever = false,
  },
  [33] = {
    id = 33,
    title = "Wolves Across the Border",
    reqLevel = 1,
    questLevel = 2,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Eagan Peltskinner",
    objectives = "Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey.",
    rewards = "170 XP",
    tip = "I hate those nasty timber wolves!  But I sure like eating wolf steaks...  Bring me tough wolf meat and I will exchange it for something you'll find useful.\n\nTough wolf meat is gathered from hunting the timber wolves and young wolves wandering the Northshire countryside.",
    isForever = false,
  },
  [753] = {
    id = 753,
    title = "A Humble Task",
    reqLevel = 1,
    questLevel = 3,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Greatmother Hawkwind",
    objectives = "Take a Water Pitcher from the water well.$b$bReturn the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.",
    rewards = "250 XP • 40c",
    tip = "I have traveled many paths through life and these old legs lack the vigor they once had. I can still perform my duties to the tribe. Sometimes it just takes an old woman a little longer to do the task.\n\nBut you look like an eager $c. Let's put some of that youthful vitality to the test. Take a water pitcher from the well and bring it to my son, the Chief, in Camp Narache.\n\nRemember that even the most humble task can gain the recognition of elders.",
    isForever = false,
  },
  [3361] = {
    id = 3361,
    title = "A Refugee's Quandary",
    reqLevel = 3,
    questLevel = 3,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Felix Whindlebolt",
    objectives = "Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar.",
    rewards = "250 XP • 50c",
    tip = "We drove the troggs out of Gnomeregan, but then it all went so horribly wrong!  Now our home is completely irradiated, and we gnomes have been scattered all over Dun Morogh.\n\nIn my haste to get away from the radiation, I lost all my personal belongings and tools.  It was the trolls that got them.  They stole my chest, my box, and my bucket of bolts!  They took them back to their camps southwest of Anvilmar.\n\nI'm no adventurer - could you find my things and bring them here to me, please?",
    isForever = false,
  },
  [233] = {
    id = 233,
    title = "Coldridge Valley Mail Delivery",
    reqLevel = 1,
    questLevel = 3,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Sten Stoutarm",
    objectives = "Deliver the stack of letters to Talin Keeneye.",
    rewards = "190 XP",
    tip = "Hm, I don't suppose you'd be willing to do a favor for me, $g lad : lass;? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?",
    isForever = false,
  },
  [4402] = {
    id = 4402,
    title = "Galgar's Cactus Apple Surprise",
    reqLevel = 1,
    questLevel = 3,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Galgar",
    objectives = "Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses.",
    rewards = "380 XP • 50c",
    tip = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, $N. If you bring me 10 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.",
    isForever = false,
  },
  [15] = {
    id = 15,
    title = "Investigate Echo Ridge",
    reqLevel = 1,
    questLevel = 3,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Marshal McBride",
    objectives = "Kill 10 Kobold Workers, then report back to Marshal McBride.",
    rewards = "250 XP • 40c",
    tip = "Pro-tip: The unassuming start to the terrifying chain that unleashes Stitches upon Darkshire!",
    isForever = false,
  },
  [1470] = {
    id = 1470,
    title = "Piercing the Veil",
    reqLevel = 1,
    questLevel = 3,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Venya Marthand",
    objectives = "Bring Venya Marthand 3 Rattlecage Skulls.",
    rewards = "190 XP",
    tip = "Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.\n\nAnd you will learn.\n\nThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.\n\nI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.",
    isForever = false,
  },
  [3901] = {
    id = 3901,
    title = "Rattling the Rattlecages",
    reqLevel = 1,
    questLevel = 3,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Shadow Priest Sarvis",
    objectives = "- Rattlecage Skeleton x 12",
    rewards = "250 XP",
    tip = "You've shown your potential to the Forsaken under normal circumstances $N - now let's see you under pressure.\n\nThe Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.",
    isForever = false,
  },
  [755] = {
    id = 755,
    title = "Rites of the Earthmother",
    reqLevel = 1,
    questLevel = 3,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Chief Hawkwind",
    objectives = "Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.",
    rewards = "250 XP",
    tip = "Your willingness to perform a humble task for the tauren of Narache and your eagerness to learn are noble traits, $n. I believe one day you will be heralded in Thunder Bluff as a $c of greatness.\n\nBefore that you must embark on the Rites of the Earthmother, of which there are three.\n\nThe first test is the Rite of Strength. Travel to Seer Graytongue and tell him Chief Hawkwind has sent you.\n\nYou will find the seer's abode directly to the south of Camp Narache, tucked away in the hills.",
    isForever = false,
  },
  [3902] = {
    id = 3902,
    title = "Scavenging Deathknell",
    reqLevel = 2,
    questLevel = 3,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Deathguard Saltain",
    objectives = "Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",
    rewards = "315 XP",
    tip = "You there!  If you're looking for something to make yourself useful, then listen up!\n\nWe need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment.  Most likely, they'll be in stacks of boxes.  We expect more recruits to be rising soon, and unless we want them to stumble about naked we had better get to scavenging!\n\nWell get to work, you miserable bag of bones!  I'm not going to reward those without some hustle.",
    isForever = false,
  },
  [789] = {
    id = 789,
    title = "Sting of the Scorpid",
    reqLevel = 1,
    questLevel = 3,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Gornek",
    objectives = "Get 10 Scorpid Worker Tails for Gornek in the Den.",
    rewards = "250 XP",
    tip = "Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here. Bring me ten of their tails as proof of your prowess in battle.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?",
    isForever = false,
  },
  [457] = {
    id = 457,
    title = "The Balance of Nature",
    reqLevel = 1,
    questLevel = 3,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Conservator Ilthalaine",
    objectives = "Conservator Ilthalaine needs you to kill 7 Mangy Nightsabers and 7 Thistle Boars.",
    rewards = "250 XP • 50c",
    tip = "Thinning the younger population of creatures here in Shadowglen was a good start, $N, but there is still work to be done.\n\nThe resources of the forest will be depleted too quickly if the problem is not addressed.  Killing nature's beasts is a necessary evil for the good of all who share the land.  Venture into the forest and slay mangy nightsabers and thistle boars in the name of balance.",
    isForever = false,
  },
  [183] = {
    id = 183,
    title = "The Boar Hunter",
    reqLevel = 1,
    questLevel = 3,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Talin Keeneye",
    objectives = "Talin Keeneye would like you to kill 12 Small Crag Boars.",
    rewards = "250 XP",
    tip = "Nothing like a day of boar hunting, eh?\n\nThough, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging. They're all angry and ready without any help. In fact, recently, there've been so many boars in the area, it's become dangerous for me to do my daily hunting.\n\nLong story short, if you could help me kill some of the boars, I would appreciate it.",
    isForever = false,
  },
  [750] = {
    id = 750,
    title = "The Hunt Continues",
    reqLevel = 1,
    questLevel = 3,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Grull Hawkwind",
    objectives = "Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.",
    rewards = "250 XP",
    tip = "A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival. You will make quite an impression on the elders if you can bring back some highly valued Mountain Cougar Pelts. You can find the beasts lurking in the hills to the south.\n\nOur children need clothing and our tents need mending.",
    isForever = false,
  },
  [459] = {
    id = 459,
    title = "The Woodland Protector",
    reqLevel = 1,
    questLevel = 3,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Tarindrella",
    objectives = "Collect 8 Fel Moss and bring them to Tarindrella.",
    rewards = "250 XP",
    tip = "Something evil is brewing in the forests of Teldrassil.  Look long the hills to where the peaceful furbolgs used to dwell.  They have deserted their homes and are amassing under the name of the Gnarlpine tribe.\n\nOnly the corruption of wicked Fel Moss could cause such a transformation.  The grells and grellkin have infested the area and are threatening the residents of Shadowglen.  \n\nEngage these grells and grellkin, $N, and see if they are indeed caught under the enchantment of the wicked Fel Mo",
    isForever = false,
  },
  [3519] = {
    id = 3519,
    title = "A Friend in Need",
    reqLevel = 2,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Iverron",
    objectives = "Speak to Dirania Silvershine in Shadowglen.",
    rewards = "90 XP",
    tip = "Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.\n\nPlease tell Dirania Silvershine. She will be able to help me.\n\nHurry... I'm so dizzy...",
    isForever = false,
  },
  [4495] = {
    id = 4495,
    title = "A Good Friend",
    reqLevel = 2,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Dirania Silvershine",
    objectives = "Find Iverron by the cave to the north.",
    rewards = "270 XP",
    tip = "A friend of mine named Iverron usually visits me at the same time every day. The strange thing is that he hasn't been by today at all -- he's several hours late, in fact.\n\nI admit, I am a little worried, $N. Iverron spends a lot of time over by the cave to the north, and I'm sure you know how dangerous it is there -- spiders, everywhere!\n\nIf you happen to be going that way, though, will you keep an eye out for him?",
    isForever = false,
  },
  [781] = {
    id = 781,
    title = "Attack on Camp Narache",
    reqLevel = 1,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Item: Dirt-stained Map",
    objectives = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.",
    rewards = "355 XP",
    tip = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!",
    isForever = false,
  },
  [1599] = {
    id = 1599,
    title = "Beginnings",
    reqLevel = 1,
    questLevel = 4,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Alamar Grimm",
    objectives = "Bring 3 Feather Charms to Alamar Grimm in Anvilmar.",
    rewards = "355 XP",
    tip = "You must be the new warlock everyone's been whispering about. Must be someone's taken a liking to you if they've asked me to take time away from my research to start your training.\n\nDon't worry, I won't hold it against you.\n\nThe simplest of the summoning spells you will learn is that of the imp. Before I impart this to you, however, you must prove that you have the necessary magical and physical ability.\n\nBring me three feather charms from the frostmane novices from the cave to the southwest.",
    isForever = false,
  },
  [18] = {
    id = 18,
    title = "Brotherhood of Thieves",
    reqLevel = 2,
    questLevel = 4,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Deputy Willem",
    objectives = "Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.",
    rewards = "355 XP",
    tip = "Pro-tip: Bring an Elixir of Water Breathing or Swim Speed Potion—gorgon naga inflict long crowd control underwater.",
    isForever = false,
  },
  [1516] = {
    id = 1516,
    title = "Call of Earth",
    reqLevel = 4,
    questLevel = 4,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Canaga Earthcaller",
    objectives = "- Felstalker Hoof x 2",
    rewards = "270 XP",
    tip = "The time is now, young $c. You've grown strong and your spirit endures like the earth. Following the shaman's path shows you have wisdom before even proving yourself.\n\nThe element of earth will guide your destiny, becoming part of you if you are ready. But you must stand before the earth itself. If you are ready, then you will see things only shaman know of.\n\nSeek out the Felstalkers to the north, and take from them two of their hooves. Return to me then, and we shall speak more of your future.",
    isForever = false,
  },
  [1517] = {
    id = 1517,
    title = "Call of Earth",
    reqLevel = 4,
    questLevel = 4,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Canaga Earthcaller",
    objectives = "Find Spirit Rock and drink the Earth Sapta.",
    rewards = "270 XP",
    tip = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a holy place, and never anywhere else--remember that.\n\nSeek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.",
    isForever = false,
  },
  [1518] = {
    id = 1518,
    title = "Call of Earth",
    reqLevel = 4,
    questLevel = 4,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Minor Manifestation of Earth",
    objectives = "Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.",
    rewards = "445 XP",
    tip = "Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.",
    isForever = false,
  },
  [1519] = {
    id = 1519,
    title = "Call of Earth",
    reqLevel = 4,
    questLevel = 4,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Seer Ravenfeather",
    objectives = "Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache.",
    rewards = "270 XP",
    tip = "The time has come, young $c. Your body ages and grows strong, and your spirit endures like the earth. I see it within you-you have wisdom already.\n\nThe earth guides our people, and it speaks to us, as it will to you in time. But you must be tested. If you are ready, then you shall see things only our kind know of.\n\nSeek out the Bristleback shamans in their ravine to the east, and take from them a salve they use in their rituals. Return to me only when you have enough for your own potion.",
    isForever = false,
  },
  [1520] = {
    id = 1520,
    title = "Call of Earth",
    reqLevel = 4,
    questLevel = 4,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Seer Ravenfeather",
    objectives = "Find Kodo Rock and drink the Earth Sapta.",
    rewards = "180 XP",
    tip = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the open minded to see the elements as no one has seen them before. Your spirit will forever be tied to the element the sapta was created for, and only a select few of our kind know the secrets of its creation.\n\nThe sapta is always imbibed in a holy place, and never anywhere else.\n\nSeek out the shaman shrine to the east of here and drink of the sapta.",
    isForever = false,
  },
  [1521] = {
    id = 1521,
    title = "Call of Earth",
    reqLevel = 4,
    questLevel = 4,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Minor Manifestation of Earth",
    objectives = "Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.",
    rewards = "445 XP",
    tip = "Take this rough quartz from me and bring it to Seer Ravenfeather as proof of our meeting. She will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast mountains.\n\nBe patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.",
    isForever = false,
  },
  [234] = {
    id = 234,
    title = "Coldridge Valley Mail Delivery",
    reqLevel = 1,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Talin Keeneye",
    objectives = "Deliver the letter to Grelin Whitebeard.",
    rewards = "270 XP • 7c",
    tip = "If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail.",
    isForever = false,
  },
  [1462] = {
