  [5650] = {
    id = 5650,
    title = "Garments of Darkness",
    reqLevel = 5,
    questLevel = 4,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Dark Cleric Beryl",
    objectives = "Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.",
    rewards = "270 XP",
    tip = "Our power comes from darkness and shadow, $N, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts. This is wise. But before you can know the dark, you must also know the light. And for this, I have a test for you.\n\nNorth of the cemetery is a wounded Deathguard--Deathguard Kel. He has protected us from gnolls for some time, and needs healing. But, you must also fortify his body before he can return to duty. Do both with your spells, and then retur",
    isForever = false,
  },
  [5648] = {
    id = 5648,
    title = "Garments of Spirituality",
    reqLevel = 5,
    questLevel = 4,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Tai'jin",
    objectives = "Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.",
    rewards = "270 XP",
    tip = "You be ready for your first test, $N. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops. She not doin' too well, an' she benefit much if one of our kind could help her. Find her--her name be Kor'ja--heal her wounds, an' give her the blessin' of our ancestors.\n\nYou do this, an' me thinks that be sufficient proof that you ready to move on in our ways.",
    isForever = false,
  },
  [5624] = {
    id = 5624,
    title = "Garments of the Light",
    reqLevel = 5,
    questLevel = 4,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Priestess Josetta",
    objectives = "Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.",
    rewards = "270 XP",
    tip = "Normally I put forth a small challenge to followers of the Light to test their skill. I want to see if they are worthy of wearing their first robes--a sign that the church outwardly approves of the $gpriest:priestess; and supports $ghim:her;.\n\nBut this situation is a bit different. One of Goldshire's citizens saw an injured guard near the lake to the east of here. His name is Roberts. Find him, heal him, fortify his body and return here. If you can do that for me, then I will consider your test ",
    isForever = false,
  },
  [5625] = {
    id = 5625,
    title = "Garments of the Light",
    reqLevel = 5,
    questLevel = 4,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Maxan Anvol",
    objectives = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.",
    rewards = "270 XP",
    tip = "It's usually about this time that one of your power is tested to see if they're worthy of wearing robes denoting their place in the church. But to be honest, I got more pressing matters to look into. Citizen of Kharanos' just came in here and told me 'bout a hurt mountaineer just outside town to the south--name's Dolf.\n\nYou heal Dolf and give him Fortitude, and I'll consider you done with proving yourself. How's that sound?",
    isForever = false,
  },
  [5621] = {
    id = 5621,
    title = "Garments of the Moon",
    reqLevel = 5,
    questLevel = 4,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Laurna Morninglight",
    objectives = "Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.",
    rewards = "270 XP",
    tip = "I need your help, $N. I am needed here to train the other students, but you, you can help one of our injured Sentinels just south of Dolanaar. She was hurt patrolling the town and could use our aid. Her name is Shaya.\n\nWhen you find her, heal her wounds, and then fortify her body with your spells. This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune.",
    isForever = false,
  },
  [3905] = {
    id = 3905,
    title = "Grape Manifest",
    reqLevel = 2,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Milly Osworth",
    objectives = "Bring the Grape Manifest to Brother Neals in Northshire Abbey.",
    rewards = "355 XP",
    tip = "Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.\n\nYou'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.",
    isForever = false,
  },
  [5651] = {
    id = 5651,
    title = "In Favor of Darkness",
    reqLevel = 5,
    questLevel = 4,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Dark Cleric Duesten",
    objectives = "Speak to Dark Cleric Beryl in Tirisfal Glades.",
    rewards = "90 XP",
    tip = "There are many lessons that the Forsaken have learned through experience--things that some races can only begin to fathom. And although our path lies in darkness, you will find that a great many things rely on both the light and the dark. Your lessons shall teach you to use both... and with discretion. But heed my words: never forget we were forged in corruption and left to rot like so much carrion. The Darkness is our home.\n\nSeek out Dark Cleric Beryl in Brill when you're ready to learn more.",
    isForever = false,
  },
  [5622] = {
    id = 5622,
    title = "In Favor of Elune",
    reqLevel = 5,
    questLevel = 4,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Shanda",
    objectives = "Speak to Laurna Morninglight in Teldrassil.",
    rewards = "90 XP",
    tip = "$N, you must travel to Dolanaar when your business here in Shadowglen is done. There, you will find Laurna Morninglight. She will instruct you further in the ways of Elune, and it is with her that you will earn your first garments denoting your station as a $gpriest:priestess; of Elune.\n\nTake care, and may you be protected in your journeys.",
    isForever = false,
  },
  [5649] = {
    id = 5649,
    title = "In Favor of Spirituality",
    reqLevel = 5,
    questLevel = 4,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Ken'jai",
    objectives = "Speak to Tai'jin in Durotar.",
    rewards = "90 XP",
    tip = "Aye, mon. Our kind have joined the Horde because they be good for us. They loyal, and they teach us much 'bout tings like honor. But our old ways die hard. The orcs may not approve of all our traditions, but that not mean we can't continue to practice some them in secret.\n\nYou know this, an' that's why I send you to Tai'jin in Razor Hill. She teach you more 'bout our history. She teach you the ways of our tribe. Go to her when you be ready.",
    isForever = false,
  },
  [5623] = {
    id = 5623,
    title = "In Favor of the Light",
    reqLevel = 5,
    questLevel = 4,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Priestess Anetta",
    objectives = "Speak to Priestess Josetta in Elwynn Forest.",
    rewards = "90 XP",
    tip = "Hello again, young $gpriest:priestess;. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.",
    isForever = false,
  },
  [5626] = {
    id = 5626,
    title = "In Favor of the Light",
    reqLevel = 5,
    questLevel = 4,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Branstock Khalder",
    objectives = "Speak to Maxan Anvol in Dun Morogh.",
    rewards = "90 XP",
    tip = "Hey! $N! Got a minute?!\n\nYa been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a $gpriest:priestess;.\n\nNow get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.",
    isForever = false,
  },
  [3521] = {
    id = 3521,
    title = "Iverron's Antidote",
    reqLevel = 2,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Dirania Silvershine",
    objectives = "Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor for Dirania Silveshine in Shadowglen.",
    rewards = "355 XP",
    tip = "We may be able to help Iverron, as I know of an antidote that should help with the poison. It requires some ingredients, though, before I can make it.\n\nI'll need Hyacinth mushrooms. You can find these growing under trees, or you may collect them from the grell south of here; they seem to have taken a liking to them. I'll also need Moonpetal lilies, which only grow around watery pools.\n\nThe last ingredient may prove the most difficult. From the very spiders that poisoned Iverron, collect Webwood ",
    isForever = false,
  },
  [3522] = {
    id = 3522,
    title = "Iverron's Antidote",
    reqLevel = 2,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Dirania Silvershine",
    objectives = "Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north.",
    rewards = "445 XP",
    tip = "The antidote is ready, $N. Please see that Iverron drinks it.\n\nThere is something that you should know -- the antidote -- it will only remain viable for 5 minutes. You must get it to him in time.\n\nSpeed be with you, $N.",
    isForever = false,
  },
  [5441] = {
    id = 5441,
    title = "Lazy Peons",
    reqLevel = 3,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Foreman Thazz'ril",
    objectives = "Use the Foreman's Blackjack on Lazy Peons when they're sleeping.  Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials.",
    rewards = "445 XP",
    tip = "Cursed peons!  They work hard gathering lumber from the trees of the valley, but they're always taking naps!  I need someone to help keep the peons in line.\n\nYou look like the right $r for my task.  Here, you take this blackjack and use it on any lazy peons you find sleeping on the job.  A good smack will get them right back to work!  Return the blackjack when you're done.\n\nLousy slacking peons...",
    isForever = false,
  },
  [3903] = {
    id = 3903,
    title = "Milly Osworth",
    reqLevel = 2,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Deputy Willem",
    objectives = "Speak with Milly Osworth.",
    rewards = "35 XP",
    tip = "You've shown yourself a dependable $c, $N.  Dependable, and not afraid to get your hands dirty, eh?\n\nI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.",
    isForever = false,
  },
  [3904] = {
    id = 3904,
    title = "Milly's Harvest",
    reqLevel = 2,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Milly Osworth",
    objectives = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.",
    rewards = "180 XP",
    tip = "A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.\n\nPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.\n\nBring me those buckets!  Save my harvest!",
    isForever = false,
  },
  [380] = {
    id = 380,
    title = "Night Web's Hollow",
    reqLevel = 2,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Executor Arren",
    objectives = "Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.",
    rewards = "355 XP",
    tip = "One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power.\n\nThere is a gold mine to the northwest that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, $n.",
    isForever = false,
  },
  [757] = {
    id = 757,
    title = "Rite of Strength",
    reqLevel = 1,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Seer Graytongue",
    objectives = "Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.",
    rewards = "445 XP",
    tip = "The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff.\n\nFirst you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe.\n\nBristlebacks of Brambleblade Ravine to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark.\n\nShow your valor by slaying these villains and return to the Chief in Camp Narache with their belts as proof of your deeds.",
    isForever = false,
  },
  [6394] = {
    id = 6394,
    title = "Thazz'ril's Pick",
    reqLevel = 3,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Foreman Thazz'ril",
    objectives = "Bring Thazz'ril's Pick to Foreman Thazz'ril.",
    rewards = "445 XP • 1s 50c",
    tip = "$N, you are a dependable $r.  Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind.  When I later returned to retrieve it I found the cave was filled with vicious beasts!  Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls.  My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!",
    isForever = false,
  },
  [780] = {
    id = 780,
    title = "The Battleboars",
    reqLevel = 1,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Grull Hawkwind",
    objectives = "Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.",
    rewards = "445 XP",
    tip = "The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war.\n\nGo and slay the vile creatures and bring back some snouts and flanks so that we can make stew for our young.",
    isForever = false,
  },
  [381] = {
    id = 381,
    title = "The Scarlet Crusade",
    reqLevel = 2,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Executor Arren",
    objectives = "Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.",
    rewards = "355 XP",
    tip = "You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts.  We can now turn our eyes to other concerns.\n\nMy scouts have reported that a detachment of the Scarlet Crusade is setting up a camp southeast of here. The Scarlet Crusade is a despicable organization that hunts us, and they will not rest until every undead--Lich King's Scourge or no--is destroyed. We must strike first!\n\nBe careful, their unholy zeal makes them dangerous adversaries.",
    isForever = false,
  },
  [1598] = {
    id = 1598,
    title = "The Stolen Tome",
    reqLevel = 1,
    questLevel = 4,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Drusilla La Salle",
    objectives = "Retrieve the Powers of the Void for Drusilla La Salle.",
    rewards = "355 XP",
    tip = "You there! $n, right?\n\nI hope you're sure about becoming a warlock, because if you can't hold your own, you're likely to get pulled under.\n\nI'm to teach you, but I need to make sure you're strong enough first.\n\nThere was a novice studying at the Abbey who ran off to join the Defias Brotherhood. Why do I care? Well, he stole some important books.\n\nOne of those happens to be a book I've wanted for myself, the Powers of the Void. Steal it for me, they have it hidden at their tent in the Vineyards.",
    isForever = false,
  },
  [182] = {
    id = 182,
    title = "The Troll Cave",
    reqLevel = 1,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Grelin Whitebeard",
    objectives = "Grelin Whitebeard would like you to kill 14 Frostmane Troll Whelps.",
    rewards = "355 XP",
    tip = "My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances.\n\nFrom what I've seen, the trolls aren't well situated here in Coldridge Valley--mostly the southern cave. I'd say that the army will not be necessary. A few strong arms should be more than enough.\n\nPerhaps you'd like to assist in this endeavor? I have the authority to offer compensation for your ",
    isForever = false,
  },
  [792] = {
    id = 792,
    title = "Vile Familiars",
    reqLevel = 2,
    questLevel = 4,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Zureetha Fargaze",
    objectives = "Kill 12 Vile Familiars.\n\nReturn to Zureetha Fargaze outside the Den.",
    rewards = "445 XP",
    tip = "I trust the Valley of Trials will teach you much, young $c.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nA group that calls itself the Burning Blade has a coven here in the Valley of Trials.  They are skulking in a cave to the northeast, and their Vile Familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.",
    isForever = false,
  },
  [1485] = {
    id = 1485,
    title = "Vile Familiars",
    reqLevel = 1,
    questLevel = 4,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Ruzan",
    objectives = "Bring 6 Vile Familiar Heads to Ruzan.",
    rewards = "355 XP",
    tip = "Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.\n\nThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.\n\nBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.",
    isForever = false,
  },
  [1499] = {
    id = 1499,
    title = "Vile Familiars",
    reqLevel = 1,
    questLevel = 4,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Ruzan",
    objectives = "Speak with Zureetha Fargaze.",
    rewards = "35 XP",
    tip = "Zureetha has been sending novices like yourself to help cull the numbers of the creatures in the cave near where you fought the vile familiars.\n\nI think it would be good for you to gain experience by assisting her. Be sure to tell her that you assisted with the imp problem, she'll probably have a reward for you.",
    isForever = false,
  },
  [916] = {
    id = 916,
    title = "Webwood Venom",
    reqLevel = 3,
    questLevel = 4,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Gilshalan Windwalker",
    objectives = "Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.",
    rewards = "355 XP",
    tip = "I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave.  They are cousin to a much smaller variety of spider; I believe the world tree has had a profound effect on them, and I would like specimens to study to confirm this.\n\nFirst, I would like some of their venom.  Gather Webwood venom sacs from the spiders in and around the Shadowthread Cave, to the north.  I can then examine them for similarities with their smaller cousin's venom.",
    isForever = false,
  },
  [2161] = {
    id = 2161,
    title = "A Peon's Burden",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Durotar",
    npc = "Ukor",
    objectives = "Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.",
    rewards = "110 XP",
    tip = "Excuse me?  Can you help me?\n\nI have a load of food here.  I walked along the road and braved scorpids and spiders and worse!  I brought the food to the Valley of Trials because I thought they needed it and I like to help out.  But they don't need any food!  Now I have to take it back to Razor Hill and I'm afraid of all the beasts along the way...\n\nCan you take it for me?  I'm just a peon, but you're a hero.  You fear nothing!\n\nTake it to Innkeeper Grosk at the Razor Hill inn.  Thank you!",
    isForever = false,
  },
  [8] = {
    id = 8,
    title = "A Rogue's Deal",
    reqLevel = 1,
    questLevel = 5,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Calvin Montague",
    objectives = "Deliver the Nondescript Letter to Innkeeper Renee in Tirisfal Glades.",
    rewards = "110 XP",
    tip = "Pro-tip: Bring a full 5-player group. Slay Horgus the Ravager and Marduk the Black to free Captain Joseph Redpath's spirit.",
    isForever = false,
  },
  [590] = {
    id = 590,
    title = "A Rogue's Deal",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Calvin Montague",
    objectives = "Defeat Calvin Montague in Deathknell.",
    rewards = "110 XP • 25c",
    tip = "What?\n\nWhat?!\n\nYou want money? I don't owe you any money.\n\nLetter? What letter? Oh, you wanna fight then? All right, mate... let's do this! Owe you any money...",
    isForever = false,
  },
  [1656] = {
    id = 1656,
    title = "A Task Unfinished",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Antur Fallow",
    objectives = "Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.",
    rewards = "110 XP",
    tip = "$N, please, I beg of you, can you help me? I have not finished my tasks here on the Mesa--I'm in the middle of my Rite of Strength--and my father asked me to deliver these furs to the inn in Bloodhoof.\n\nI'm far from rested enough to complete both my rite and this task for my father. Would you mind going on for me?\n\nThe inn is pleasant and a perfect place to rest during your long travels. I'm sure you'll agree once you see it.",
    isForever = false,
  },
  [6] = {
    id = 6,
    title = "Bounty on Garrick Padfoot",
    reqLevel = 2,
    questLevel = 5,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Deputy Willem",
    objectives = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.",
    rewards = "335 XP",
    tip = "Pro-tip: Windsor's escort in Blackrock Depths requires clearing the entire ring of law and prison block first to avoid aggro wipes.",
    isForever = false,
  },
  [3376] = {
    id = 3376,
    title = "Break Sharptusk!",
    reqLevel = 3,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Brave Windfeather",
    objectives = "Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.",
    rewards = "670 XP",
    tip = "$N - I have heard of you, newcomer.  Perhaps it is you that will help us, where others have failed.\n\nWe tauren have carved a home out of this land, but not without a cost.  The Bristleback quilboars of Brambleblade Ravine, led by Chief Sharptusk Thornmantle, have made our lives difficult with their continued war against us.  I charge you to bring me the chief's head!\n\nHe will be found in the ravine to the east in their makeshift village.",
    isForever = false,
  },
  [3365] = {
    id = 3365,
    title = "Bring Back the Mug",
    reqLevel = 4,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Durnan Furcutter",
    objectives = "Return Nori's Mug to Nori Pridedrift.",
    rewards = "450 XP • 50c",
    tip = "Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go $N - be a pal and take this empty mug back to Nori for me, would ya now.",
    isForever = false,
  },
  [794] = {
    id = 794,
    title = "Burning Blade Medallion",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Zureetha Fargaze",
    objectives = "Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.",
    rewards = "670 XP",
    tip = "Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic.\n\nIt is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven.\n\nBut be wary, for the medallion may be possessed by an agent of the Burning Blade, and if so then the agent's power would be greater than the familiars you have already encountered.\n\nGo, $N.  You will find the coven in a cave, to the north and west.",
    isForever = false,
  },
  [921] = {
    id = 921,
    title = "Crown of the Earth",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Tenaron Stormgrip",
    objectives = "Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil.",
    rewards = "335 XP",
    tip = "It is time for you to set out to seek your destiny, $n. But before you are ready to set out into the world beyond our enchanted forests, there is much you must learn about our recent history.\n\nMuch has changed with our people since the Battle of Mount Hyjal. Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion...\n\nThere is a task you must perform. Go to the moonwell north of Aldrassil and return me a phial of its water.",
    isForever = false,
  },
  [928] = {
    id = 928,
    title = "Crown of the Earth",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Tenaron Stormgrip",
    objectives = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.",
    rewards = "225 XP",
    tip = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, $n. There are dangerous beasts in the forests of l",
    isForever = false,
  },
  [929] = {
    id = 929,
    title = "Crown of the Earth",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Corithras Moonrage",
    objectives = "Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar.",
    rewards = "335 XP",
    tip = "First, let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.\n\nTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. When you have completed your task, I shall continue the story where Tenaron left off...",
    isForever = false,
  },
  [997] = {
    id = 997,
    title = "Denalan's Earth",
    reqLevel = 4,
    questLevel = 5,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Syral Bladeleaf",
    objectives = "Bring the package of Rare Earth to Denalan at Lake Al'Ameth.",
    rewards = "225 XP • 50c",
    tip = "Are you heading to the south?  To Lake Al'Ameth?  If so, then I have a task I might ask of you...\n\nMy colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil.  He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar.\n\nCan you take the package to him?",
    isForever = false,
  },
  [2159] = {
    id = 2159,
    title = "Dolanaar Delivery",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Porthannius",
    objectives = "Bring the Dolanaar Delivery to Innkeeper Keldamyr.",
    rewards = "110 XP",
    tip = "Greetings, young $c.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.\n\nCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.",
    isForever = false,
  },
  [5481] = {
    id = 5481,
    title = "Gordo's Task",
    reqLevel = 5,
    questLevel = 5,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Gordo",
    objectives = "- Gloom Weed x 3",
    rewards = "225 XP",
    tip = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill graveyard.",
    isForever = false,
  },
  [6395] = {
    id = 6395,
    title = "Marla's Last Wish",
    reqLevel = 3,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Novice Elreth",
    objectives = "Bring Samuel Fipps' Remains to Marla's Grave, then return to Novice Elreth.",
    rewards = "450 XP",
    tip = "My friend Marla Fipps lived with her husband Samuel before the plague, but when the plague came Samuel succumbed and joined the Scourge's ranks.\n\nMarla was spared an undeath only to die at the hands of her now mindless husband.  So strong was her love, however, that her last dying wish was to be buried with her beloved Samuel.\n\nSamuel Fipps roams at a ruined camp along the road northeast of Deathknell.  Defeat him and grant Marla's wish: bury him at her grave, in the first row of our graveyard.",
    isForever = false,
  },
  [748] = {
    id = 748,
    title = "Poison Water",
    reqLevel = 4,
    questLevel = 5,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Mull Thunderhorn",
    objectives = "Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof.",
    rewards = "450 XP",
    tip = "Goblins and their servants have tainted our sacred water wells!  We cannot allow this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, $N.",
    isForever = false,
  },
  [54] = {
    id = 54,
    title = "Report to Goldshire",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Marshal McBride",
    objectives = "Take Marshal McBride's Documents to Marshal Dughan in Goldshire.",
    rewards = "225 XP",
    tip = "$N, you are a $c with proven interest in the security of Northshire.  You are now tasked with the protection of the surrounding Elwynn Forest.\n\nIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire.  Goldshire lies along the southern road, past the border gates.",
    isForever = false,
  },
  [805] = {
    id = 805,
    title = "Report to Sen'jin Village",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Zureetha Fargaze",
    objectives = "Speak with Master Gadrin in Sen'jin Village.",
    rewards = "225 XP",
    tip = "Your trials against the Burning Blade are finished... here in the Valley.  But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin.  Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials.  Discover from him if they have yet reached Sen'jin.\n\nGo, $N, and be swift.  I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...",
    isForever = false,
  },
  [2158] = {
    id = 2158,
    title = "Rest and Relaxation",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Falkhaan Isenstrider",
    objectives = "Speak with Innkeeper Farley at the Lion's Pride Inn.",
    rewards = "110 XP",
    tip = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!",
    isForever = false,
  },
  [763] = {
    id = 763,
    title = "Rites of the Earthmother",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Chief Hawkwind",
    objectives = "Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache.",
    rewards = "335 XP",
    tip = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, $n.\n\nTravel to Bloodhoof Village and seek out the Chief, Baine Bloodhoof, son of Cairne. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Baine. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.",
    isForever = false,
  },
  [790] = {
    id = 790,
    title = "Sarkoth",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Hana'zua",
    objectives = "Kill Sarkoth and bring his claw back to Hana'zua.",
    rewards = "450 XP",
    tip = "$C! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.",
    isForever = false,
  },
  [804] = {
    id = 804,
    title = "Sarkoth",
    reqLevel = 1,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Hana'zua",
    objectives = "Bring the news of Hana'zua's plight to Gornek at the Den.",
    rewards = "110 XP",
    tip = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to the Den unassisted. Please, $n, return to the Den and tell Gornek of my situation. Perhaps he can help me.",
    isForever = false,
  },
  [3364] = {
    id = 3364,
    title = "Scalding Mornbrew Delivery",
    reqLevel = 4,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Nori Pridedrift",
    objectives = "Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!",
    rewards = "225 XP",
    tip = "Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I'll never make it to Anvilmar before the brew runs cold!\n\nYou look fast.  Maybe you can make it.  This cup will only stay hot for five more minutes, and Durnan didn't order \"chilly\" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.\n\nThanks, $N, and don't forget to bring me back my mug!",
    isForever = false,
  },
  [282] = {
    id = 282,
    title = "Senir's Observations",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Grelin Whitebeard",
    objectives = "Speak with Mountaineer Thalos.",
    rewards = "335 XP",
    tip = "I was planning on sending my apprentice to my brother Senir with my report, but I would feel much better were it placed in more... reliable hands. That is, of course, if you wouldn't mind?\n\nHmm... you'll have to take the tunnel to get to Kharanos.\n\nSpeak with Mountaineer Thalos before going through the tunnel. It's completely infested with troggs now.\n\nFollow the road back to Anvilmar, then keep heading east to the tunnel, Thalos is stationed nearby.",
    isForever = false,
  },
  [420] = {
    id = 420,
    title = "Senir's Observations",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Mountaineer Thalos",
    objectives = "Deliver Grelin's report to Senir Whitebeard in Kharanos.",
    rewards = "335 XP",
    tip = "The troggs in the tunnel are extremely hostile, and haven't shown any hesitation in attacking travelers through the tunnel. You seem tough enough, though, so you should probably be safe.\n\nDirections? If you're going to speak with Senir, you'll find him in Kharanos.\n\nMake your way through the tunnel, and after you come out on the other side, just keep following the road, it'll run right into Kharanos.",
    isForever = false,
  },
  [21] = {
    id = 21,
    title = "Skirmish at Echo Ridge",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Marshal McBride",
    objectives = "Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.",
    rewards = "450 XP",
    tip = "Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.\n\nWaste no time, $N.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.",
    isForever = false,
  },
  [2160] = {
    id = 2160,
    title = "Supplies to Tannok",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Hands Springsprocket",
    objectives = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.",
    rewards = "110 XP",
    tip = "Hey! You look like a hearty adventurer. If you're planning on braving the pass, do you suppose you could bring a package to the inn in Kharanos?\n\nYou were planning on stopping at the inn, right? If you make it through the pass, you'll definitely want to take a breather there.\n\nAnyways, bring this to Tannok Frosthammer, the innkeeper's assistant. I can't get through the pass myself, and it'll be days until a Mountaineer escort comes through!",
    isForever = false,
  },
  [920] = {
    id = 920,
    title = "Tenaron's Summons",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Gilshalan Windwalker",
    objectives = "Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen.",
    rewards = "45 XP",
    tip = "$n, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil.\n\nWe may live long lives, but it's best you not keep him waiting too long.",
    isForever = false,
  },
  [382] = {
    id = 382,
    title = "The Red Messenger",
    reqLevel = 2,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Executor Arren",
    objectives = "Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.",
    rewards = "670 XP",
    tip = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!\n\nYou're the most qualified person I have to send, $n. Find that messenger and bring me whatever information you can find.",
    isForever = false,
  },
  [218] = {
    id = 218,
    title = "The Stolen Journal",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Grelin Whitebeard",
    objectives = "Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal.",
    rewards = "560 XP",
    tip = "My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that.\n\nYou've had some luck with the trolls, maybe you could go get it back for me?",
    isForever = false,
  },
  [400] = {
    id = 400,
    title = "Tools for Steelgrill",
    reqLevel = 2,
    questLevel = 5,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Tharek Blackstone",
    objectives = "Deliver Steelgrill's Tools to Beldin Steelgrill.",
    rewards = "110 XP • 25c",
    tip = "Beldin Steelgrill owns the local mechanic shop, and he's the best siege engine tech there is!  But he's not forgiving to his tools.  I swear he almost breaks more arclight spanners than we can supply him with!\n\nWe just filled his last order for tools.  If you deliver it to him I'm sure he'll make it worth the effort.\n\nHis shop, Steelgrill's Depot, is just northeast of Kharanos.  And it's a local haunt for veteran siege engine pilots, so keep your ears open for opportunities while you're there.",
    isForever = false,
  },
  [383] = {
    id = 383,
    title = "Vital Intelligence",
    reqLevel = 2,
    questLevel = 5,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Executor Arren",
    objectives = "Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.",
    rewards = "335 XP • 75c",
    tip = "These will need to be taken to my superior, Executor Zygand, in Brill. With this information, we'll be able to deal a decisive blow to the Scarlet Crusade. Your services have been useful here in Deathknell, but I need someone to deliver this to Zygand, and I believe he'll be able to find you more appropriate work.\n\nTake the road north out of Deathknell. Soon after entering Tirisfal proper, you'll hit a crossroads. Take the eastern fork, and keep going east. You'll pass Cold Hearth Manor along th",
    isForever = false,
  },
  [917] = {
    id = 917,
    title = "Webwood Egg",
    reqLevel = 1,
    questLevel = 5,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Gilshalan Windwalker",
    objectives = "Bring a Webwood Egg to Gilshalan in Aldrassil.",
    rewards = "560 XP",
    tip = "Now that I have the spiders' venom, I'd like some live specimens to study.  Unfortunately, capturing a living, giant spider is more than I can ask of you, young $c.  And a giant spider is more than I could handle myself!\n\nBut if you can find an unhatched egg, then delivering specimens will be much easier, and I can then arrange for the unhatched spiders to be contained.\n\nThere must be a nest deep in the Shadowthread Cave.  Please, search for an egg in the nest and return it to me.",
    isForever = false,
  },
  [488] = {
    id = 488,
    title = "Zenn's Bidding",
    reqLevel = 4,
    questLevel = 5,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Zenn Foulhoof",
    objectives = "Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.",
    rewards = "450 XP • 1s",
    tip = "Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling $c to perform my bidding.\n\nYou see, $N, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.\n\nMy business in the forest often requires certain. . .reagents.  Fetch for me 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.\n\nLet's keep this our little secret, $r.",
    isForever = false,
  },
  [367] = {
    id = 367,
    title = "A New Plague",
    reqLevel = 6,
    questLevel = 6,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Apothecary Johaan",
    objectives = "Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.",
    rewards = "540 XP • 1s 25c",
    tip = "Lady Sylvanas has called upon the Royal Apothecary Society. The Dark Lady believes our knowledge coupled with the newfound magic will provide the key to Arthas's demise.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring Arthas's Scourge Army to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Bring to me 5 vials of darkhound blood so I can test my theory.",
    isForever = false,
  },
  [404] = {
    id = 404,
    title = "A Putrid Task",
    reqLevel = 4,
    questLevel = 6,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Deathguard Dillinger",
    objectives = "Bring 7 Putrid Claws to Deathguard Dillinger in Brill.",
    rewards = "405 XP • 1s",
    tip = "Scourge have trickled into Tirisfal Glades and have infested the area west of Brill, near the old bridge.\n\nGo there and beat back the rotting dead and ravaged corpses you find.  Scatter their bones and bring back their putrid claws, and the Deathguards will reward you.",
    isForever = false,
  },
  [475] = {
    id = 475,
    title = "A Troubling Breeze",
    reqLevel = 4,
    questLevel = 6,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Athridas Bearmantle",
    objectives = "Seek out Gaerolas Talvethren in Starbreeze Village.",
    rewards = "270 XP",
    tip = "A troubling breeze blows through the forest.\n\nGaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled.\n\nBut word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.",
    isForever = false,
  },
  [5541] = {
    id = 5541,
    title = "Ammo for Rumbleshot",
    reqLevel = 5,
    questLevel = 6,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Loslor Rudge",
    objectives = "Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.",
    rewards = "540 XP • 1s 25c",
    tip = "Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he's always needing fresh ammunition.\n\nBut... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot's ammo behind!\n\n$N, can you get that ammo and take it to Rumbleshot?  He's been waiting on it and I'm sure he's running low.",
    isForever = false,
  },
  [84] = {
    id = 84,
    title = "Back to Billy",
    reqLevel = 5,
    questLevel = 6,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "\"Auntie\" Bernice Stonefield",
    objectives = "Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards.",
    rewards = "135 XP",
    tip = "Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!",
    isForever = false,
  },
  [310] = {
    id = 310,
    title = "Bitter Rivals",
    reqLevel = 2,
    questLevel = 6,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Marleth Barleybrew",
    objectives = "In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.",
    rewards = "135 XP",
    tip = "I have to admit, those Thunderbrews make some good drinks.  But they need to learn that theirs isn't the only decent brew!  Maybe you can help me teach them that lesson...\n\nHere, take this barrel of Barleybrew Scalder.  Sneak into the basement of the Thunderbrew Distillery in Kharanos and switch it with one of their barrels of Thunder Ale.  Then we'll see how their patrons like my brew over theirs!\n\nAnd if the barrels are guarded, then you might have to distract the guard ...",
    isForever = false,
  },
  [5482] = {
    id = 5482,
    title = "Doom Weed",
    reqLevel = 5,
    questLevel = 6,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Junior Apothecary Holland",
    objectives = "- Doom Weed x 10",
    rewards = "540 XP, 1s 25c",
    tip = "So you can see the predicament that I'm in, $N. That thing is out there collecting the wrong weeds! I'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.\n\nIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.",
    isForever = false,
  },
  [476] = {
    id = 476,
    title = "Gnarlpine Corruption",
    reqLevel = 4,
    questLevel = 6,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Gaerolas Talvethren",
    objectives = "Return to Athridas Bearmantle in Dolanaar.",
    rewards = "540 XP • 1s 25c",
    tip = "The Gnarlpine tribe has been corrupted!\n\nThe once peaceful furbolgs have turned against the protectors of the forest.  They ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village.  Ursal the Mauler, their chieftain, is using the evil powers of the Fel Moss to drive them mad.\n\nI am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young $c.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil y",
    isForever = false,
  },
  [9260] = {
    id = 9260,
    title = "Investigate the Scourge of Stormwind",
    reqLevel = 1,
    questLevel = 6,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Lieutenant Orrin",
    objectives = "Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles nearby their encampment.",
    rewards = "167 XP",
    tip = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Stormwind from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!",
    isForever = false,
  },
  [85] = {
    id = 85,
    title = "Lost Necklace",
    reqLevel = 5,
    questLevel = 6,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "\"Auntie\" Bernice Stonefield",
    objectives = "Speak with Billy Maclure.",
    rewards = "135 XP",
    tip = "I lost my necklace, and think that guttersnipe Billy Maclure took it!  He's usually scuttling like a rat around the Maclure vineyards east of here. \n\nGet my necklace back for me, and you'll warm an old widow's heart.",
    isForever = false,
  },
  [107] = {
    id = 107,
    title = "Note to William",
    reqLevel = 5,
    questLevel = 6,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Gramma Stonefield",
    objectives = "Take Gramma Stonefield's Note to William Pestle.",
    rewards = "135 XP",
    tip = "I bet William Pestle has a potion to unite our two young lovers!\n\nHere, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.",
    isForever = false,
  },
  [86] = {
    id = 86,
    title = "Pie for Billy",
    reqLevel = 5,
    questLevel = 6,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Billy Maclure",
    objectives = "Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.",
    rewards = "405 XP",
    tip = "Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... \n\nMaybe if you gave her some chunks of boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.",
    isForever = false,
  },
  [767] = {
    id = 767,
    title = "Rite of Vision",
    reqLevel = 3,
    questLevel = 6,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Baine Bloodhoof",
    objectives = "Speak with Zarlman Two-Moons in Bloodhoof Village.",
    rewards = "55 XP",
    tip = "The Rite of Vision, one of the Rites of the Earthmother, will help guide you toward earning the respect of the elders of Thunder Bluff.\n\nOur people have learned that the land is our most holy provider. In order to take part in the ritualistic vision, you must speak with the spiritual leader of the village, Zarlman Two-Moons.",
    isForever = false,
  },
  [745] = {
    id = 745,
    title = "Sharing the Land",
    reqLevel = 1,
    questLevel = 6,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Baine Bloodhoof",
    objectives = "Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village.",
    rewards = "540 XP • 1s 25c",
    tip = "$N, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as I have. Yet there is one that I would ask you to seek out. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.",
    isForever = false,
  },
  [111] = {
    id = 111,
    title = "Speak with Gramma",
    reqLevel = 5,
    questLevel = 6,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Tommy Joe Stonefield",
    objectives = "Speak with Gramma Stonefield.",
    rewards = "135 XP",
    tip = "Please, $N, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.\n\nShe's inside our house east of here.",
    isForever = false,
  },
  [317] = {
    id = 317,
    title = "Stocking Jetsteam",
    reqLevel = 2,
    questLevel = 6,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Pilot Bellowfiz",
    objectives = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.",
    rewards = "680 XP • 2s 50c",
    tip = "I'm preparing to start a mission for the Siege Brigade.  It's a long one, and I need to stock Jetsteam with a month's worth of supplies.  So while Steelgrill is working on my tank, can you do some hunting for me?\n\nI'll need some fur for bedding, and boar meat for food.  You can get meat from boars and fur from the bears... you can find them both in the snow fields south of the Grizzled Den.",
    isForever = false,
  },
  [761] = {
    id = 761,
    title = "Swoop Hunting",
    reqLevel = 4,
    questLevel = 6,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Harken Windtotem",
    objectives = "Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village.",
    rewards = "680 XP • 2s 50c",
    tip = "The swoop is a cunning bird, and difficult to find and hunt.  A collection of Swoop Quills is a badge of cleverness and determination for a hunter.\n\nIf you are willing to take up this task, then enter the plains and hunt the swoop.\n\nBring me their quills, and bring honor to your clan.\n\nThe swoops may be found anywhere in Mulgore, but your eyes must be sharp to spot them, and your hooves must be quick to catch them.",
    isForever = false,
  },
  [2438] = {
    id = 2438,
    title = "The Emerald Dreamcatcher",
    reqLevel = 1,
    questLevel = 6,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Tallonkai Swiftroot",
    objectives = "Bring the Emerald Dreamcatcher to Tallonkai Swiftroot in Dolanaar.",
    rewards = "405 XP • 1s",
    tip = "I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it.\n\nSadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there.\n\nPerhaps you would be willing to recover my dreamcatcher, $c?",
    isForever = false,
  },
  [754] = {
    id = 754,
    title = "Winterhoof Cleansing",
    reqLevel = 4,
    questLevel = 6,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Mull Thunderhorn",
    objectives = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn.",
    rewards = "540 XP",
    tip = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  You will find it to the southeast, guarded by foul goblins!\n\nThis will not be an easy task, but you must do it if we are ever to use its waters again.\n\nFortune to you, $N.",
    isForever = false,
  },
  [361] = {
    id = 361,
    title = "A Letter Undelivered",
    reqLevel = 4,
    questLevel = 7,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Item: A Letter to Yvette",
    objectives = "Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.",
    rewards = "475 XP",
    tip = "This is a letter written by Thurman, the eldest son of Gregor Agamand.  It is addressed to an Yvette Farthing, though it does not appear to have reached her...",
    isForever = false,
  },
  [818] = {
    id = 818,
    title = "A Solvent Spirit",
    reqLevel = 5,
    questLevel = 7,
    faction = "Horde",
    zone = "Durotar",
    npc = "Master Vornal",
    objectives = "Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village.",
    rewards = "630 XP • 1s 75c",
    tip = "Although my eyes fail me, I still can see clearly enough. More often I must rely on my alchemical skills to aid me in magics that once came easily. But I refuse to take on an apprentice--no troll or orc worthy enough has ever come forward.\n\nAre you worthy? Yes, of course you are... of course you think you are.\n\nI need a few things. Will you get them for me?\n\nI need intact makrura eyes, and vials of crawler mucus. You can find them on any makrura or crawler in Durotar. We shall speak again soon.",
    isForever = false,
  },
  [384] = {
    id = 384,
    title = "Beer Basted Boar Ribs",
    reqLevel = 5,
    questLevel = 7,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Ragnar Thunderbrew",
    objectives = "Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt.",
    rewards = "630 XP • 1s 75c",
    tip = "Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. \n\nMaybe you can help me out?  If you bring me six crag boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!",
    isForever = false,
  },
  [791] = {
    id = 791,
    title = "Carry Your Weight",
    reqLevel = 4,
    questLevel = 7,
    faction = "Horde",
    zone = "Durotar",
    npc = "Furl Scornbrow",
    objectives = "Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps.",
    rewards = "630 XP",
    tip = "Age has rendered me useless in battle. Now I make myself useful in other ways.\n\nFrom this vantage point I watch for invaders. As our strength here grows, I find myself blowing the signal horn less and less.\n\nTo pass the time I fashion goods to help younger, more able warriors defend our homeland.\n\nFor you, I can fashion you a bag for your belongings. If such an item would be of use to you, bring me some canvas, a material common to the humans and centaurs.",
    isForever = false,
  },
  [112] = {
    id = 112,
    title = "Collecting Kelp",
    reqLevel = 5,
    questLevel = 7,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "William Pestle",
    objectives = "Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire.",
    rewards = "315 XP",
    tip = "I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the Liquor, I need some crystal kelp.\n\nAlthough the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.",
    isForever = false,
  },
  [308] = {
    id = 308,
    title = "Distracting Jarven",
    reqLevel = 1,
    questLevel = 7,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Jarven Thunderbrew",
    objectives = "- Thunder Ale",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [318] = {
    id = 318,
    title = "Evershine",
    reqLevel = 2,
    questLevel = 7,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Pilot Bellowfiz",
    objectives = "Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.",
    rewards = "160 XP",
    tip = "Rejold Barleybrew experiments with his brews.  Some of them taste good, some bad, and some...well, some will lay all but the stoutest dwarf flat.\n\nHe lives at Brewnall Village, west of Kharanos, and one of his drinks, Evershine, is what I want.  It'll help keep me warm while I'm on the cold road.\n\nAnd...the blessed stuff burns so hot I can throw it in Jetsteam's furnace for a burst of power!  That little tactic has gotten me out of more than one tight spot.",
    isForever = false,
  },
  [365] = {
    id = 365,
    title = "Fields of Grief",
    reqLevel = 4,
    questLevel = 7,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Deathguard Simmer",
    objectives = "Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.",
    rewards = "630 XP • 1s 75c",
    tip = "What have we here?  You look like a fledgling $c.  If you hope to prove yourself to The Dark Lady, you need to learn the ways of The Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, take them to Apothecary Johaan in Brill.",
    isForever = false,
  },
  [407] = {
    id = 407,
    title = "Fields of Grief",
    reqLevel = 4,
    questLevel = 7,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Apothecary Johaan",
    objectives = "Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.",
    rewards = "160 XP",
    tip = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat Arthas's advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow's End Tavern.  Take this pumpkin to the ",
    isForever = false,
  },
  [47] = {
    id = 47,
    title = "Gold Dust Exchange",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Remy \"Two Times\"",
    objectives = "Bring 10 Gold Dust to Remy \"Two Times\" in Goldshire.  Gold Dust is gathered from Kobolds in Elwynn Forest.",
    rewards = "630 XP • 1s 75c",
    tip = "The Kobolds in these parts sometimes carry Gold Dust on them.  I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town!\n\nYou can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.",
    isForever = false,
  },
  [60] = {
    id = 60,
    title = "Kobold Candles",
    reqLevel = 3,
    questLevel = 7,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "William Pestle",
    objectives = "Bring 8 Large Candles to William Pestle in Goldshire.",
    rewards = "475 XP • 1s 25c",
    tip = "Hello, $ggood sir:my lady;!  Do you have a moment?\n\nMy brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax.  Can you help me?\n\nYou can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines ... the Fargodeep mine to the south and Jasperlode Mine to the east.  I suggest looking for candles in one of those places.",
    isForever = false,
  },
  [374] = {
    id = 374,
    title = "Proof of Demise",
    reqLevel = 5,
    questLevel = 7,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Deathguard Burgess",
    objectives = "Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.",
    rewards = "630 XP • 1s 75c",
    tip = "Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.\n\nVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.\n\nVenture forth and wage an offensive on the Scarlet Crusade, $c. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lad",
    isForever = false,
  },
  [4161] = {
    id = 4161,
    title = "Recipe of the Kaldorei",
    reqLevel = 1,
    questLevel = 7,
    faction = "Alliance",
    zone = "Cooking",
    npc = "Zarrin",
    objectives = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.",
    rewards = "630 XP • 85c",
    tip = "Long ago, the night elves were called the kaldorei, a name that means \"children of the stars.\" Learning of the past is an important step in your path as a $c, $N, so listen well to what I have to tell you.\n\nThe kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, $N.\n\nGo out and collect seven small spider legs -- no more than that, and return t",
    isForever = false,
  },
  [922] = {
    id = 922,
    title = "Rellian Greenspyre",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Denalan",
    objectives = "Bring a Timberling Seed to Rellian Greenspyre in Darnassus.",
    rewards = "315 XP",
    tip = "$N, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid in Darnassus, and when last we spoke he revealed his interest in my work with the Timberlings.  He had some ideas himself, and he will appreciate a specimen seed to work with.\n\nThank you, $N.  You have been a great help to me.  I hope that, some day, you will see the fruit of my labors.\n\nYou will usually find Rellian walking the pathways of the Cenarion Enclave in Darnassus.",
    isForever = false,
  },
  [823] = {
    id = 823,
    title = "Report to Orgnil",
    reqLevel = 4,
    questLevel = 7,
    faction = "Horde",
    zone = "Durotar",
    npc = "Master Gadrin",
    objectives = "Speak with Orgnil Soulscar in Razor Hill.",
    rewards = "315 XP",
    tip = "We at Sen'jin Village are not without our own troubles, and we thank you for your aid.  But the news you bring regarding the Burning Blade could be trouble for everyone.\n\nThere is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade!  Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials.  He will want to know these things.\n\nRazor Hill lies to the north.",
    isForever = false,
  },
  [311] = {
    id = 311,
    title = "Return to Marleth",
    reqLevel = 2,
    questLevel = 7,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Object: Unguarded Thunder Ale Barrel",
    objectives = "Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.",
    rewards = "630 XP • 1s 75c",
    tip = "Having inserted a barrel of Marleth's Scalder in the Kharanos Distillery's cellar, you grab a barrel of Thunder Ale as proof of the deed...",
    isForever = false,
  },
  [771] = {
    id = 771,
    title = "Rite of Vision",
    reqLevel = 3,
    questLevel = 7,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Zarlman Two-Moons",
    objectives = "Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.",
    rewards = "630 XP",
    tip = "In order to pass through the Rite of Vision, you must gather the reagents needed to make the Water of the Seers.\n\nI will need well stones, which can be found around the water wells in Mulgore. With those I will combine Ambercorn, which fall beneath the mighty trees in our land.\n\nThese reagents contain magical elements, and when brewed and consumed before the tribal fire, will cause you to encounter a vision. Follow it, and it will lead you to the next step of this holy quest.",
    isForever = false,
  },
  [772] = {
    id = 772,
    title = "Rite of Vision",
    reqLevel = 3,
    questLevel = 7,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Zarlman Two-Moons",
    objectives = "Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.",
    rewards = "475 XP",
    tip = "I now present you with the Water of the Seers.\n\nWhen you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire.\n\nAt that point, it is up to you to follow it to your destiny....",
    isForever = false,
  },
  [489] = {
    id = 489,
    title = "Seek Redemption!",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Syral Bladeleaf",
    objectives = "Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.",
    rewards = "630 XP • 1s 75c",
    tip = "The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a $r, you should know better than to defile the forest by killing Nature's creatures.\n\nYou must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil.\n\nTeach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke.\n\nGive some to Foulhoof. He'll think you have brought him a harmless snac",
    isForever = false,
  },
  [61] = {
    id = 61,
    title = "Shipment to Stormwind",
    reqLevel = 3,
    questLevel = 7,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "William Pestle",
    objectives = "Bring William's Shipment to Morgan Pestle in the Stormwind Trade District.",
    rewards = "790 XP • 3s 50c",
    tip = "My brother Morgan is waiting in Stormwind for my shipment of candles.  I don't have enough time to make the trip myself, but if you'd like to take him the shipment, he'll pay you well.\n\nI've packed up the candles, and you can find Morgan in our shop, Pestle's Apothecary, in the Stormwind Trade District.",
    isForever = false,
  },
  [830] = {
    id = 830,
    title = "The Admiral's Orders",
    reqLevel = 1,
    questLevel = 7,
    faction = "Horde",
    zone = "Durotar",
    npc = "Item: Aged Envelope",
    objectives = "Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill.",
    rewards = "630 XP",
    tip = "You open the aged and weathered envelope and discover an official looking document. You recognize the seal of Admiral Proudmoore.\n\nThis looks important. Perhaps Gar'Thok, the commander of Razor Hill, would be interested in having this information.",
    isForever = false,
  },
  [831] = {
    id = 831,
    title = "The Admiral's Orders",
    reqLevel = 1,
    questLevel = 7,
    faction = "Horde",
    zone = "Durotar",
    npc = "Gar'Thok",
    objectives = "Deliver Admiral Proudmoore's Orders to Nazgrel in Thrall's chamber in Orgrimmar.",
    rewards = "630 XP • 1s 75c",
    tip = "Humans cannot be trusted. We fought alongside them with a weary heart, knowing they would betray us one day.\n\nAdmiral Proudmoore's death was not enough to stop his legacy of deceit. The human scum had his plans well laid out before he ever met his demise.\n\nHis reign won't even die with Benedict it seems. Who knows how long it will be before the next waves of Proudmoore's men land upon our shores.\n\nWe need to get these orders to Nazgrel in Orgrimmar immediately! He can be found in Thrall's chambe",
    isForever = false,
  },
  [114] = {
    id = 114,
    title = "The Escape",
    reqLevel = 5,
    questLevel = 7,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "William Pestle",
    objectives = "Take the Invisibility Liquor to Maybell Maclure.",
    rewards = "790 XP",
    tip = "Take this invisibility liquor to young Maybell.  It should last long enough for her to visit Tommy Joe.",
    isForever = false,
  },
  [62] = {
    id = 62,
    title = "The Fargodeep Mine",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Marshal Dughan",
    objectives = "Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.",
    rewards = "475 XP • 1s 25c",
    tip = "The mine in Northshire isn't the only one with problems!  I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds.\n\nExplore the mine and confirm these reports, then return to me.  The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.",
    isForever = false,
  },
  [313] = {
    id = 313,
    title = "The Grizzled Den",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Pilot Stonegear",
    objectives = "Gather 8 Wendigo Manes and bring them to Pilot Stonegear.",
    rewards = "630 XP • 1s 75c",
    tip = "Driving a Siege Engine isn't for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How's your mettle?  Want to prove it to me?\n\nWell...I'm looking to make my engine, Trollplow, a little more cozy.  How about you get me a heap of Wendigo Manes from the Grizzled Den, west of Kharanos.  Those manes would make a great rug for Trollplow's inside deck!",
    isForever = false,
  },
  [756] = {
    id = 756,
    title = "Thunderhorn Totem",
    reqLevel = 4,
    questLevel = 7,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Mull Thunderhorn",
    objectives = "Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn.",
    rewards = "630 XP",
    tip = "To create the Thunderhorn Cleansing Totem, you must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.",
    isForever = false,
  },
  [918] = {
    id = 918,
    title = "Timberling Seeds",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Denalan",
    objectives = "Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth.",
    rewards = "630 XP",
    tip = "The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree.\n\nSo it is disturbing to see how angry the timberlings have become.\n\nI believe it has something to do with the soil.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?",
    isForever = false,
  },
  [919] = {
    id = 919,
    title = "Timberling Sprouts",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Denalan",
    objectives = "Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth.",
    rewards = "790 XP • 3s 50c",
    tip = "Small timberlings are sprouting around the waters of Lake Al'Ameth.  I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble.\n\nWhen you're wandering the lake, if you see any timberling sprouts please take them.  Help keep our land clean!",
    isForever = false,
  },
  [932] = {
    id = 932,
    title = "Twisted Hatred",
    reqLevel = 4,
    questLevel = 7,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Tallonkai Swiftroot",
    objectives = "Kill Lord Melenas and bring his head to Tallonkai Swiftroot in Dolanaar.",
    rewards = "630 XP",
    tip = "I must warn you, $n, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home.\n\nHe is called Lord Melenas. He resides in the nearby cave of Fel Rock where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul.\n\nYou must find him within his nearby cave just to the north of here, and bring me his head.",
    isForever = false,
  },
  [784] = {
    id = 784,
    title = "Vanquish the Betrayers",
    reqLevel = 3,
    questLevel = 7,
    faction = "Horde",
    zone = "Durotar",
    npc = "Gar'Thok",
    objectives = "Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill.",
    rewards = "630 XP • 1s 75c",
    tip = "Led by Admiral Proudmoore, the humans of Kul Tiras encroached on Durotar, violating the Warchief's pact made with Jaina Proudmoore in order to defeat Archimonde years ago.\n\nThe human aggression was repelled and Tiragarde Keep fell. But recently, the Admiral's reserves, led by Lieutenant Benedict, have retaken the keep and once again pose a threat to our homeland. These humans show no respect for diplomacy.\n\nProve your honor and travel south to Tiragarde Keep to eliminate the human invaders.",
    isForever = false,
  },
  [319] = {
    id = 319,
    title = "A Favor for Evershine",
    reqLevel = 2,
    questLevel = 8,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Rejold Barleybrew",
    objectives = "Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.",
    rewards = "530 XP",
    tip = "I have a cask of Evershine handy, but...can you do me a favor?  Brewnall village could use a hand against the wild animals that wander the nearby snows.  Sometimes they wander close.\n\nWe're not afraid of these bears and cats and boars - no self respecting dwarf would be - but if you can take care of those animals for us, then we'd have more time for our crafting and brewing.",
    isForever = false,
  },
  [427] = {
    id = 427,
    title = "At War With The Scarlet Crusade",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Executor Zygand",
    objectives = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.",
    rewards = "700 XP • 2s 25c",
    tip = "The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades.\n\nBut the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warr",
    isForever = false,
  },
  [815] = {
    id = 815,
    title = "Break a Few Eggs",
    reqLevel = 6,
    questLevel = 8,
    faction = "Horde",
    zone = "Durotar",
    npc = "Cook Torka",
    objectives = "Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.",
    rewards = "700 XP • 2s 25c",
    tip = "Bah! I almost forgot I need to get breakfast ready.\n\n$N, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal.\n\nThe Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.",
    isForever = false,
  },
  [743] = {
    id = 743,
    title = "Dangers of the Windfury",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Ruul Eagletalon",
    objectives = "Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village.",
    rewards = "700 XP • 2s 25c",
    tip = "Thank you for taking the time to speak to me, $N. I am Ruul, warrior and teacher.\n\nYou have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore.\n\nIf you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road.\n\nThey are one of our natural enemies here in Mulgore and will be a good gauge of your skill.",
    isForever = false,
  },
  [746] = {
    id = 746,
    title = "Dwarven Digging",
    reqLevel = 6,
    questLevel = 8,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Baine Bloodhoof",
    objectives = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village.",
    rewards = "700 XP",
    tip = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.",
    isForever = false,
  },
  [1581] = {
    id = 1581,
    title = "Elixirs for the Bladeleafs",
    reqLevel = 4,
    questLevel = 8,
    faction = "Both",
    zone = "Alchemy",
    npc = "Syral Bladeleaf",
    objectives = "Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.",
    rewards = "700 XP • 2s 25c",
    tip = "Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other.\n\nCan you help us?\n\nIf you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.",
    isForever = false,
  },
  [2459] = {
    id = 2459,
    title = "Ferocitas the Dream Eater",
    reqLevel = 1,
    questLevel = 8,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Tallonkai Swiftroot",
    objectives = "Tallonkai Swiftroot in Dolanaar wants you to kill 7 Gnarlpine Mystics and find the Missing Jewel.",
    rewards = "880 XP • 4s 50c",
    tip = "The emerald... It is missing! My dreamcatcher has been damaged!\n\nThere is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him.\n\nFind this missing jewel, $N. And, while you're there, clear out some of the corrupted mystics as well.",
    isForever = false,
  },
  [825] = {
    id = 825,
    title = "From The Wreckage....",
    reqLevel = 3,
    questLevel = 8,
    faction = "Horde",
    zone = "Durotar",
    npc = "Gar'Thok",
    objectives = "Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.",
    rewards = "700 XP",
    tip = "One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep.\n\nIt is no secret that the humans, in alliance with those foul little creatures known as gnomes, have an advanced knowledge of mechanics. We must have a complete understanding of all our potential enemies. And our people will benefit from this new knowledge as well.\n\nSwim through the wreckage, $n, and retrieve for me the tools of the Allianc",
    isForever = false,
  },
  [768] = {
    id = 768,
    title = "Gathering Leather",
    reqLevel = 4,
    questLevel = 8,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Veren Tallstrider",
    objectives = "Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.",
    rewards = "880 XP",
    tip = "Greetings, young one.  You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt.  May you bring honor to your clan!\n\nI work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff.\n\nIf you hunt beasts and bring me their skins, then I will fashion something for you.",
    isForever = false,
  },
  [87] = {
    id = 87,
    title = "Goldtooth",
    reqLevel = 5,
    questLevel = 8,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Billy Maclure",
    objectives = "Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm.",
    rewards = "880 XP",
    tip = "I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace.  Don't ask me how it got there...it wasn't me!\n\nWell anyway, I saw this big, gold-toothed kobold pick up the necklace and run into the mine.  Go find that kobold and you'll find the necklace, I swear!",
    isForever = false,
  },
  [358] = {
    id = 358,
    title = "Graverobbers",
    reqLevel = 4,
    questLevel = 8,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Magistrate Sevren",
    objectives = "Kill Rot Hide Graverobbers and Rot Hide Mongrels.  \n\nBring 8 Embalming Ichors to Magistrate Sevren in Brill.",
    rewards = "700 XP • 2s 25c",
    tip = "The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide Gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the Mass Grave and Garren's Haunt, and gather from them the Embalming Ichor that gives them life.",
    isForever = false,
  },
  [9265] = {
    id = 9265,
    title = "Investigate the Scourge of the Undercity",
    reqLevel = 1,
    questLevel = 8,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Lieutenant Rukag",
    objectives = "Collect three Dim Necrotic Stones from the Scourge outside the Undercity and investigate the glowing runic circles nearby their encampment.",
    rewards = "530 XP • 1s 75c",
    tip = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Undercity from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!",
    isForever = false,
  },
  [766] = {
    id = 766,
    title = "Mazzranache",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Maur Raincaller",
    objectives = "Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village.",
    rewards = "700 XP",
    tip = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I will need some hard-to-find animal parts to clean the infection from his bite: a wolf heart, cougar femur, plainstrider scale and swoop gizzard.\n\nHurry, time is of the es",
    isForever = false,
  },
  [817] = {
    id = 817,
    title = "Practical Prey",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Durotar",
    npc = "Vel'rin Fang",
    objectives = "Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village.",
    rewards = "700 XP • 2s 25c",
    tip = "Many of the hides we use come from Durotar tigers, $N. Blankets, armor, tents: there are a great many reasons we hunt the beasts, and many reasons we let them thrive at the same time.\n\nThe time has come for us to cull the flock, so to speak. Our numbers grow, and our needs are beginning to overwhelm our stocks. I need more hides if I'm to prepare suitable goods for our people.\n\nBring me 4 Durotar tiger furs, and I shall reward you. You can find them on the islands south of here.",
    isForever = false,
  },
  [366] = {
    id = 366,
    title = "Return the Book",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Bethor Iceshard",
    objectives = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.",
    rewards = "350 XP",
    tip = "Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free.\n\nWe must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join u",
    isForever = false,
  },
  [320] = {
    id = 320,
    title = "Return to Bellowfiz",
    reqLevel = 2,
    questLevel = 8,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Rejold Barleybrew",
    objectives = "Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.",
    rewards = "880 XP",
    tip = "Here's your cask of Evershine, $N.  And again, thank you for the hunting earlier.",
    isForever = false,
  },
  [375] = {
    id = 375,
    title = "The Chill of Death",
    reqLevel = 7,
    questLevel = 8,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Gretchen Dedmar",
    objectives = "Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.",
    rewards = "700 XP • 2s 25c",
    tip = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The Mindless State will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five Duskbat Pelts and some Coarse Thread I could sew myself a blanket.  Help me, $N, so that I can continue to serve the cause.",
    isForever = false,
  },
  [357] = {
    id = 357,
    title = "The Lich's Identity",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Undercity",
    npc = "Bethor Iceshard",
    objectives = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.",
    rewards = "530 XP • 1s 75c",
    tip = "There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him.\n\nBut because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us.\n\nTo discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me.",
    isForever = false,
  },
  [426] = {
    id = 426,
    title = "The Mills Overrun",
    reqLevel = 6,
    questLevel = 8,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Deathguard Dillinger",
    objectives = "Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.",
    rewards = "880 XP • 4s 50c",
    tip = "The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nGo to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.\n\nTo get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.",
    isForever = false,
  },
  [405] = {
    id = 405,
    title = "The Prodigal Lich",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Magistrate Sevren",
    objectives = "Present Sevren's Orders to Bethor Iceshard in the Undercity.",
    rewards = "175 XP",
    tip = "Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, $N, will be that agent.\n\nPresent these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous.\n\nSo ready yourself, $C.  You must not fail.\n\nYou may find Bethor in the Magic Quarter of the Undercity.",
    isForever = false,
  },
  [749] = {
    id = 749,
    title = "The Ravaged Caravan",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Morin Cloudstalker",
    objectives = "Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.",
    rewards = "530 XP",
    tip = "A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan.\n\nWe left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong.\n\nPerhaps you could go to the caravan and examine the contents of the crates.",
    isForever = false,
  },
  [751] = {
    id = 751,
    title = "The Ravaged Caravan",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Object: Sealed Supply Crate",
    objectives = "Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village.",
    rewards = "530 XP",
    tip = "Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore. On the top of the ore and minerals you remove a tightly bound sheaf of papers.\n\nUp in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.",
    isForever = false,
  },
  [487] = {
    id = 487,
    title = "The Road to Darnassus",
    reqLevel = 5,
    questLevel = 8,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Moon Priestess Amara",
    objectives = "Slay 6 Gnarlpine Ambushers and return to Sentinel Amara Nightwalker outside of Dolanaar.",
    rewards = "700 XP • 2s 25c",
    tip = "The road to Darnassus must be kept safe.  Travelers heading from Dolanaar to Darnassus have been reporting ruthless attacks by corrupted furbolgs from the Gnarlpine tribe.\n\nImportant news and commerce travels to and from Darnassus by way of this road daily.  We cannot afford to have a rogue band of heathens terrorizing people.\n\nTake up arms in the name of the sacred forest, $c.  Their den lies somewhere below this vantage point.  Slay 6 of these Gnarlpine ambushers and report back to me.",
    isForever = false,
  },
  [2541] = {
    id = 2541,
    title = "The Sleeping Druid",
    reqLevel = 3,
    questLevel = 8,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Oben Rageclaw",
    objectives = "Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den.",
    rewards = "700 XP",
    tip = "The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this.\n\nYou must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, $N, bring one to me.",
    isForever = false,
  },
  [758] = {
    id = 758,
    title = "Thunderhorn Cleansing",
    reqLevel = 4,
    questLevel = 8,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Mull Thunderhorn",
    objectives = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.",
    rewards = "700 XP",
    tip = "The totem is ready, $N.  And again, it is your task to perform the ritual of cleansing.\n\nGo to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual.  After you do this, return to me.\n\nMay the spirits guide you.",
    isForever = false,
  },
  [786] = {
    id = 786,
    title = "Thwarting Kolkar Aggression",
    reqLevel = 5,
    questLevel = 8,
    faction = "Horde",
    zone = "Durotar",
    npc = "Lar Prowltusk",
    objectives = "Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.",
    rewards = "700 XP",
    tip = "Lower your voice, $c. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag.\n\nLast night while they were raiding, I snuck into their village and discovered that the dirty beasts have a three-tiered attack planned on the trolls and orcs of Durotar.\n\nWe mustn't let their invasion come to fruition. Perhaps you can muster the might needed to infiltrate Kolkar Crag and destroy their attack plans.\n\nLast I saw, they had divided them up amongst three of their leaders.",
    isForever = false,
  },
  [5545] = {
    id = 5545,
    title = "A Bundle of Trouble",
    reqLevel = 5,
    questLevel = 9,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Supervisor Raelen",
    objectives = "Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.",
    rewards = "780 XP • 3s",
    tip = "I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped.\n\nI've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.",
    isForever = false,
  },
  [368] = {
    id = 368,
    title = "A New Plague",
    reqLevel = 6,
    questLevel = 9,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Apothecary Johaan",
    objectives = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.",
    rewards = "780 XP • 3s",
    tip = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.\n\nI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.",
    isForever = false,
  },
  [370] = {
    id = 370,
    title = "At War With The Scarlet Crusade",
    reqLevel = 5,
    questLevel = 9,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Executor Zygand",
    objectives = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.",
    rewards = "780 XP • 3s",
    tip = "The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill Perrine along with 3 Zealots and 3 Missionaries and report back to me.",
    isForever = false,
  },
  [933] = {
    id = 933,
    title = "Crown of the Earth",
    reqLevel = 1,
    questLevel = 9,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Corithras Moonrage",
    objectives = "Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar.",
    rewards = "780 XP",
    tip = "There is another moonwell southeast of the entrance to Darnassus, on the shores of the Pools of Arlithrien. The Sentinels are having problems patrolling the area because of attacks and the growing ill-temperedness of the Gnarlpine furbolgs.\n\nBe wary as you seek out the well, and keep your weapons close at hand.",
    isForever = false,
  },
  [813] = {
    id = 813,
    title = "Finding the Antidote",
    reqLevel = 7,
    questLevel = 9,
    faction = "Horde",
    zone = "Durotar",
    npc = "Kor'ghan",
    objectives = "Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Venomtails are some of the deadliest scorpids in Durotar. It was unwise for Rhinag to hunt them without having some of the antidote with him, but right now, chastising is the last thing he needs.\n\nBring me a few venomtail poison sacs from any of the venomtails near the entrance of Orgrimmar and I'll make an antidote for him.\n\nMake haste, $N. One of our own needs your help.",
    isForever = false,
  },
  [359] = {
    id = 359,
    title = "Forsaken Duties",
    reqLevel = 6,
    questLevel = 9,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Magistrate Sevren",
    objectives = "Speak with Deathguard Linnea.",
    rewards = "195 XP",
    tip = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.",
    isForever = false,
  },
  [287] = {
    id = 287,
    title = "Frostmane Hold",
    reqLevel = 7,
    questLevel = 9,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Senir Whitebeard",
    objectives = "Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.",
    rewards = "590 XP",
    tip = "I'm behind on my report, and could use your help, $n. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in.\n\nHere's what I need... Go down to the cave, poke around inside, kill a few of the trolls, then come back here.\n\nTake the road north out of Kharanos, when you get to the bridge, follow the frozen river west until you reach Iceflow Lake. You'll find Brewnall Village on the west bank. The Hold is southwest of the village.",
    isForever = false,
  },
  [184] = {
    id = 184,
    title = "Furlbrow's Deed",
    reqLevel = 8,
    questLevel = 9,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Item: Westfall Deed",
    objectives = "Bring Furlbrow's Deed to Farmer Furlbrow.",
    rewards = "590 XP",
    tip = "This is the deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words:\n\n\"We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place.\n\nThe Furlbrows won't give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon.\"\n\nYou think the Furlbrows might want their deed back...",
    isForever = false,
  },
  [808] = {
    id = 808,
    title = "Minshina's Skull",
    reqLevel = 4,
    questLevel = 9,
    faction = "Horde",
    zone = "Durotar",
    npc = "Master Gadrin",
    objectives = "Retrieve Minshina's skull from the circle of power on the Echo Isles.\n\nBring it to Master Gadrin in Sen'jin Village.",
    rewards = "780 XP",
    tip = "I hear the voice of my brother, Minshina, calling to me in my dreams.\n\nHe was taken by Zalazane, the warlock on the Echo Isles to the east. And he is dead.\n\nBut death is not freedom for my brother. Minshina's spirit was trapped within his own skull by Zalazane's magics. In my dreams I see it with other skulls, in a circle of power on the largest Echo Isle. As long as it remains there my brother's soul is doomed.\n\nPlease, $N. Find the circle and retrieve Minshina's skull. Bring it to me.\n\nFree hi",
    isForever = false,
  },
  [812] = {
    id = 812,
    title = "Need for a Cure",
    reqLevel = 7,
    questLevel = 9,
    faction = "Horde",
    zone = "Durotar",
    npc = "Rhinag",
    objectives = "Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.",
    rewards = "980 XP",
    tip = "$N... your timing is perfect. I just hope I can compliment your haste as well.\n\nI was careless while fighting a few of the venomtails nearby, and one of them stung me deeply. I can feel its poison weakening me even as we speak. At this rate, I got maybe an hour left to live. But I'll need your help if I'm to do so...\n\nKor'ghan in Orgrimmar knows how to make the antidote. Find him... and hurry, $N. I won't be able to last much longer. He should be in the Cleft of Shadow.",
    isForever = false,
  },
  [2499] = {
    id = 2499,
    title = "Oakenscowl",
    reqLevel = 4,
    questLevel = 9,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Denalan",
    objectives = "Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.",
    rewards = "980 XP • 6s",
    tip = "In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home.\n\nI dared not get too close, but even from a distance, it is obvious: Oakenscowl is being poisoned by the largest tumor I have ever seen...  I would call it gargantuan, even.\n\n$N, you have already done much to aid my efforts, but I ask of you one more task. Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my ",
    isForever = false,
  },
  [88] = {
    id = 88,
    title = "Princess Must Die!",
    reqLevel = 6,
    questLevel = 9,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Ma Stonefield",
    objectives = "Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm.",
    rewards = "780 XP",
    tip = "The Brackwells have a prize-winning pig, Princess.  The sow is HUGE, and she got that way from sneaking over here and eating my veggies!\n\nSo before she comes to our fields...Princess must die!  Bring me her collar as proof of the deed and I'll give you something for your time!\n\nPrincess is usually over at the Brackwell Pumpkin Patch, to the east and beyond the Maclure farm.  Get her before she gets hungry and comes back here!",
    isForever = false,
  },
  [83] = {
    id = 83,
    title = "Red Linen Goods",
    reqLevel = 4,
    questLevel = 9,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Sara Timberlain",
    objectives = "Bring 6 Red Linen Bandanas to Sara Timberlain at the Eastvale Logging Camp.",
    rewards = "780 XP",
    tip = "The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods.\n\nBring me red linen bandanas and I'll use them to fashion something for you.\n\nDefias gang members have camps pocketed throughout Elwynn.",
    isForever = false,
  },
  [2498] = {
    id = 2498,
    title = "Return to Denalan",
    reqLevel = 4,
    questLevel = 9,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Rellian Greenspyre",
    objectives = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.",
    rewards = "80 XP",
    tip = "I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.\n\nMake haste, $N; he needs our help.",
    isForever = false,
  },
  [360] = {
    id = 360,
    title = "Return to the Magistrate",
    reqLevel = 6,
    questLevel = 9,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Deathguard Linnea",
    objectives = "Return to Magistrate Sevren in Brill.",
    rewards = "390 XP • 1s 50c",
    tip = "Now return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.\n\nAnd if you see any Scourge on your way back, take them down - we can't let them wander our lands unchallenged.",
    isForever = false,
  },
  [315] = {
    id = 315,
    title = "The Perfect Stout",
    reqLevel = 5,
    questLevel = 9,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Rejold Barleybrew",
    objectives = "Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.",
    rewards = "780 XP",
    tip = "I'm on a quest, a quest to make the perfect stout.  I know I can do it -- brewing's in my blood.  I just need to find the right recipe...\n\nThe Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east.  They use it in their strange, tribal rituals.  We dwarves haven't found much use for it, but it has a unique taste...and I want to experiment with it in my brews!\n\nGet me some shimmerweed from Frostmane seers, or swipe it from the trolls' shimmerweed baskets.",
    isForever = false,
  },
  [483] = {
    id = 483,
    title = "The Relics of Wakening",
    reqLevel = 4,
    questLevel = 9,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Athridas Bearmantle",
    objectives = "Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.",
    rewards = "780 XP • 3s",
    tip = "Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west.\n\nThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.\n\nJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.",
    isForever = false,
  },
  [432] = {
    id = 432,
    title = "Those Blasted Troggs!",
    reqLevel = 5,
    questLevel = 9,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Foreman Stonebrow",
    objectives = "Kill 6 Rockjaw Skullthumpers for Foreman Stonebrow at the Gol'Bolar quarry.",
    rewards = "590 XP • 2s",
    tip = "Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder!\n\nOhhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all!\n\nThis can't be good for my health, all this stress and anger... What have they left me with? Nothing!\n\nI'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!",
    isForever = false,
  },
  [923] = {
    id = 923,
    title = "Tumors",
    reqLevel = 4,
    questLevel = 9,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Rellian Greenspyre",
    objectives = "Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus.",
    rewards = "980 XP • 6s",
    tip = "There is a malevolence growing in the timberlings.  We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help.  Those that wander Wellspring Lake in northern Teldrassil are the most tainted.  They must be removed!\n\nDestroy the Timberlings you find there, and gather the mossy tumors growing upon them.  Bring the tumors to me so that they may be burned.",
    isForever = false,
  },
  [834] = {
    id = 834,
    title = "Winds in the Desert",
    reqLevel = 7,
    questLevel = 9,
    faction = "Horde",
    zone = "Durotar",
    npc = "Rezlak",
    objectives = "Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar.",
    rewards = "780 XP • 3s",
    tip = "I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?\n\nThe last shipment--they promised it'd get through!--was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?\n\nI gotta have those supplies or I'll never get anything done! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the w",
    isForever = false,
  },
  [6361] = {
    id = 6361,
    title = "A Bundle of Hides",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Jahan Hawkwing",
    objectives = "Bring the Bundle of Hides to the wind rider master Devrak in the Crossroads.",
    rewards = "210 XP",
    tip = "I have a bundle of hides from the animals of the Barrens, and must get them to Thunder Bluff.  A colleague there, Ahanu, will use the hides to create leather goods.\n\nWill you take the hides to him for me?\n\nThe quickest way to Thunder Bluff is on the back of a wind rider.  Bring the bundle of hides to Devrak, our wind rider master in the Crossroads, and speak to him about transport to Thunder Bluff.",
    isForever = false,
  },
  [8803] = {
    id = 8803,
    title = "A Festive Gift",
    reqLevel = 10,
    questLevel = 10,
    faction = "Both",
    zone = "Seasonal Events",
    npc = "Object: Festive Gift",
    objectives = "Inspect Festive Gift in Seasonal Events.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [40] = {
    id = 40,
    title = "A Fishy Peril",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Remy \"Two Times\"",
    objectives = "Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.",
    rewards = "85 XP",
    tip = "$N, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!\n\nI warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger.\n\nPlease, $N, speak to Dughan and persuade him to send more troops to the east!",
    isForever = false,
  },
  [833] = {
    id = 833,
    title = "A Sacred Burial",
    reqLevel = 7,
    questLevel = 10,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Lorekeeper Raintotem",
    objectives = "Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks.",
    rewards = "630 XP • 2s 50c",
    tip = "Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains.\n\nBut it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away.\n\nThey must be driven off with force, $n.",
    isForever = false,
  },
  [6181] = {
    id = 6181,
    title = "A Swift Message",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Quartermaster Lewis",
    objectives = "Bring Lewis' Note to Thor the gryphon master.",
    rewards = "210 XP",
    tip = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Thor, our gryphon master.  He's just down the hill; bring him my note, and then take a gryphon to Stormwind.",
    isForever = false,
  },
  [1638] = {
    id = 1638,
    title = "A Warrior's Training",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Lyria Du Lac",
    objectives = "Speak with Harry Burlguard.",
    rewards = "85 XP",
    tip = "You've shown yourself to be a competent warrior, $N.  But you're still young and have a lot to learn.\n\nSpeak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.",
    isForever = false,
  },
  [371] = {
    id = 371,
    title = "At War With The Scarlet Crusade",
    reqLevel = 5,
    questLevel = 10,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Executor Zygand",
    objectives = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.",
    rewards = "840 XP • 3s 50c",
    tip = "We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!",
    isForever = false,
  },
  [5931] = {
    id = 5931,
    title = "Back to Darnassus",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.",
    rewards = "85 XP",
    tip = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Mathrengyl Bearwalker walks truly in balance with nature, even as he dwells precariously close to where the balance has faltered.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.",
    isForever = false,
  },
  [5932] = {
    id = 5932,
    title = "Back to Thunder Bluff",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.",
    rewards = "85 XP",
    tip = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Though the tauren are thought to be young in the ways of Cenarius, Turak Runetotem walks with much balance in the presence of nature.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.",
    isForever = false,
  },
  [1639] = {
    id = 1639,
    title = "Bartleby the Drunk",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Harry Burlguard",
    objectives = "Speak with Bartleby.",
    rewards = "85 XP",
    tip = "Yeah, I can teach you.  But first I wanna see what moves you have already.\n\nSee that drunk over there at the end of the bar?  Bartleby?  I want you to get his mug.\n\nHah, and if you know Bartleby then you know he won't just give it to you.",
    isForever = false,
  },
  [1665] = {
    id = 1665,
    title = "Bartleby's Mug",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Bartleby",
    objectives = "Bring Bartleby's Mug to Burlguard",
    rewards = "420 XP",
    tip = "Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go.",
    isForever = false,
  },
  [1640] = {
    id = 1640,
    title = "Beat Bartleby",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
