  [6001] = {
    id = 6001,
    title = "Body and Heart",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Mathrengyl Bearwalker",
    objectives = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done.",
    rewards = "840 XP",
    tip = "Directly east of Auberdine lay many moonkin caves.  The one closest to Auberdine has a Moonkin Stone inside it.  Lunaclaw, the defender of the stone, will face you only when Cenarion Moondust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Moondust, $N... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!",
    isForever = false,
  },
  [6002] = {
    id = 6002,
    title = "Body and Heart",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Turak Runetotem",
    objectives = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Turak Runetotem in Thunder Bluff when you are done.",
    rewards = "840 XP",
    tip = "On land west of Taurajo in the Barrens - just before it turns into Mulgore - lies a Moonkin Stone.  The moonkin are special beasts, not native to these parts.  Lunaclaw, the stone's defender, will face you when Cenarion Lunardust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Lunardust, $N... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a",
    isForever = false,
  },
  [46] = {
    id = 46,
    title = "Bounty on Murlocs",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Guard Thomas",
    objectives = "Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.",
    rewards = "840 XP",
    tip = "The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well.\n\nThe murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.",
    isForever = false,
  },
  [983] = {
    id = 983,
    title = "Buzzbox 827",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Wizbang Cranktoggle",
    objectives = "Collect 6 Crawler Legs and place them in Buzzbox 827.",
    rewards = "840 XP • 3s 50c",
    tip = "Hey! Help me with my latest invention, the buzzbox. You can talk to people far away!\n\nMaybe you've already seen them, they're boxes with levers on them. The only problem is they need constant maintenance.\n\nEach one suffers from a different problem, but I made a really smart decision. I placed each one near creatures that have the proper parts to fix that particular machine. Right now Buzzbox 827 is on the fritz. It's just south of Auberdine, real close. It takes 6 Crawler Legs to fix it. I'll pa",
    isForever = false,
  },
  [1522] = {
    id = 1522,
    title = "Call of Fire",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Searn Firewarder",
    objectives = "Find Kranal Fiss in the Barrens.",
    rewards = "420 XP",
    tip = "Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal.\n\nKranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready.\n\nHe be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.",
    isForever = false,
  },
  [1523] = {
    id = 1523,
    title = "Call of Fire",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Xanis Flameweaver",
    objectives = "Find Kranal Fiss in the Barrens.",
    rewards = "420 XP",
    tip = "Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.",
    isForever = false,
  },
  [2983] = {
    id = 2983,
    title = "Call of Fire",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Swart",
    objectives = "Find Kranal Fiss in the Barrens.",
    rewards = "420 XP",
    tip = "It's been some time since you were tested last, $N. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.",
    isForever = false,
  },
