  [59] = {
    id = 59,
    title = "Cloth and Leather Armor",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Marshal Dughan",
    objectives = "Give Sara Timberlain the Stormwind Armor Marker.",
    rewards = "210 XP",
    tip = "For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, $N, use it in the defense of Elwynn.\n\nThe Eastvale Logging Camp is beyond Guard Thomas' post to the east.",
    isForever = false,
  },
  [6281] = {
    id = 6281,
    title = "Continue to Stormwind",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Thor",
    objectives = "Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.",
    rewards = "420 XP • 1s 75c",
    tip = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Lewis' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!",
    isForever = false,
  },
  [1473] = {
    id = 1473,
    title = "Creature of the Void",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Carendin Halgar",
    objectives = "Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned.",
    rewards = "630 XP",
    tip = "It seems the consensus that you are ready to learn to summon a voidwalker.\n\nA being created of the chaos that lies beyond, if you summon one but cannot control it, you will be torn asunder.\n\nThe first voidwalker was summoned by Egalin, and in his grimoire is the process explained.\n\nUnfortunately, it was stolen from us by an agent of the Scarlet Crusade who has it secreted away in his base at a tower to the west. Bring it to me, and I will impart the knowledge to you.",
    isForever = false,
  },
  [1667] = {
    id = 1667,
    title = "Dead-tooth Jack",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Marshal Haggard",
    objectives = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.",
    rewards = "840 XP",
    tip = "Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you...\n\nA while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him!\n\nGet back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south.",
    isForever = false,
  },
  [39] = {
    id = 39,
    title = "Deliver Thomas' Report",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Guard Thomas",
    objectives = "Report to Marshal Dughan in Goldshire.",
    rewards = "1,050 XP • 7s",
    tip = "Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence.\n\nI know we don't have many troops to spare, but hopefully Dughan can find someone.",
    isForever = false,
  },
  [445] = {
    id = 445,
    title = "Delivery to Silverpine Forest",
    reqLevel = 9,
    questLevel = 10,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Apothecary Johaan",
    objectives = "Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.",
    rewards = "630 XP • 2s 50c",
    tip = "Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now.\n\nAs a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires.\n\nTake these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southw",
    isForever = false,
  },
  [5634] = {
    id = 5634,
    title = "Desperate Prayer",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "High Priestess Laurena",
    objectives = "Speak to High Priestess Laurena in Stormwind.",
    rewards = "Experience & Faction Reputation",
    tip = "You're needed in Stormwind, $N. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, $N.",
    isForever = false,
  },
  [5635] = {
    id = 5635,
    title = "Desperate Prayer",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Priestess Josetta",
    objectives = "Speak to High Priestess Laurena in Stormwind.",
    rewards = "210 XP",
    tip = "You've caught the attention of our superiors, $N. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.",
    isForever = false,
  },
  [5636] = {
    id = 5636,
    title = "Desperate Prayer",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Laurna Morninglight",
    objectives = "Speak to High Priestess Laurena in Stormwind.",
    rewards = "210 XP",
    tip = "Elune bless you, good $r. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.",
    isForever = false,
  },
  [5637] = {
    id = 5637,
    title = "Desperate Prayer",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Maxan Anvol",
    objectives = "Speak to High Priestess Laurena in Stormwind.",
    rewards = "210 XP",
    tip = "Time's come for you to head to Stormwind, $N. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can.",
    isForever = false,
  },
  [5638] = {
    id = 5638,
    title = "Desperate Prayer",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Nara Meideros",
    objectives = "Speak to High Priestess Laurena in Stormwind.",
    rewards = "210 XP",
    tip = "Just a short time ago, one of your priests was here looking for you, $r. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good $r.",
    isForever = false,
  },
  [5639] = {
    id = 5639,
    title = "Desperate Prayer",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "High Priest Rohan",
    objectives = "Speak to High Priestess Laurena in Stormwind.",
    rewards = "Experience & Faction Reputation",
    tip = "You're needed in Stormwind, $N. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, $N.",
    isForever = false,
  },
  [2242] = {
    id = 2242,
    title = "Destiny Calls",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Syurna",
    objectives = "- Sethir's Journal",
    rewards = "840 XP",
    tip = "We believe there is one being that may be able to help us understand what is happening to the forests of Teldrassil. Unfortunately, getting the creature to cooperate has proven disastrous.\n\nHe hides on a branch at the outskirts of the Oracle Glade. All who have so far approached the satyr, whether through force or diplomacy, have met with doom. Perhaps stealth is the answer, $N.\n\nFind what Sethir the Ancient carries in his packs and report back to me.",
    isForever = false,
  },
  [45] = {
    id = 45,
    title = "Discover Rolf's Fate",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Object: A half-eaten body",
    objectives = "Search the murloc village for Rolf, or signs of his death.",
    rewards = "420 XP",
    tip = "Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village.\n\nPerhaps Rolf's fate ended there...",
    isForever = false,
  },
  [6385] = {
    id = 6385,
    title = "Doras the Wind Rider Master",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Innkeeper Gryshka",
    objectives = "Bring Gryshka's Letter to Doras in Orgrimmar.",
    rewards = "210 XP",
    tip = "I've written a letter of thanks to Zargh.  Will you deliver it for me?  If you've already been to the Crossroads and spoken with their wind rider master, then you can fly a wind rider back there.\n\nTake my letter to Doras, the wind rider master of Orgrimmar, and speak with him about transport to the Crossroads.",
    isForever = false,
  },
  [2561] = {
    id = 2561,
    title = "Druid of the Claw",
    reqLevel = 3,
    questLevel = 10,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Oben Rageclaw",
    objectives = "Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.",
    rewards = "1,050 XP",
    tip = "After examining this charm, $N, I see now what must be done. Please take it, and do as I ask.\n\nYou are to explore the deepest areas of the Ban'ethil Barrow Den. There, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.\n\nIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.",
    isForever = false,
  },
  [6261] = {
    id = 6261,
    title = "Dungar Longdrink",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Osric Strang",
    objectives = "Bring Osric's Crate to Dungar Longdrink the gryphon master.",
    rewards = "210 XP",
    tip = "$N, I gathered into this crate everything Lewis asked for.  Can you take it to him?\n\nIf you've already spoken to Thor in Westfall, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Lewis as fast as you can.  We don't want our fighting men and women in Westfall to go without fresh equipment!",
    isForever = false,
  },
  [1684] = {
    id = 1684,
    title = "Elanaria",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Moon Priestess Amara",
    objectives = "Speak with Elanaria.",
    rewards = "85 XP",
    tip = "Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher.\n\nThe warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.",
    isForever = false,
  },
  [837] = {
    id = 837,
    title = "Encroachment",
    reqLevel = 6,
    questLevel = 10,
    faction = "Horde",
    zone = "Durotar",
    npc = "Gar'Thok",
    objectives = "Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill.",
    rewards = "630 XP • 2s 50c",
    tip = "When we arrived, the Razormane quilboars possessed much of the land, and proved a thorn in our sides. Through our efforts we have driven out the largest part of their numbers, but still they remain well-fortified in some areas.\n\nIt has gone on long enough, however. For our own protection, we cannot allow the Razormane any hold in our lands. Their camps can be found to the west of here. Look for the brambles and you will find them. Today we drive them from Durotar, tomorrow, perhaps from all of K",
    isForever = false,
  },
  [37] = {
    id = 37,
    title = "Find the Lost Guards",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Guard Thomas",
    objectives = "Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.",
    rewards = "210 XP",
    tip = "A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.\n\nTravel north along the river and find the guards... or their remains.",
    isForever = false,
  },
  [6342] = {
    id = 6342,
    title = "Flight to Auberdine",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Vesprystus",
    objectives = "Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird.",
    rewards = "420 XP",
    tip = "From Rut'theran, there are two methods of travel to Auberdine: by ferry and by hippogryph.  Both are quick and reliable, but if you have not yet flown to Auberdine by hippogryph, then I suggest you do.\n\nIt is sound advice to speak with the hippogryph master in every town that has one.  Once you speak to the master, you can then fly there from other towns.\n\nHere is Nessa's collection.  Speak with me again when you are ready to fly to Auberdine and deliver Nessa's collection to Laird.",
    isForever = false,
  },
  [1503] = {
    id = 1503,
    title = "Forged Steel",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Thun'grim Firegaze",
    objectives = "Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.",
    rewards = "840 XP",
    tip = "I will give you a weapon, $N, but first you must aid me.  The Razormanes to the northwest came into my camp a few nights past.  They would not meet me in combat, but they know my eyes are bad--a few distracted me with snorts while others stole from me!  The cowards!\n\nThey took an iron chest, and within it were some forged steel bars.  If you can recover them then I will give you the weapon you seek.\n\nSearch for the iron box within the quilboar camps, and return with the forged steel bars.",
    isForever = false,
  },
  [35] = {
    id = 35,
    title = "Further Concerns",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Marshal Dughan",
    objectives = "Marshal Dughan wants you to speak with Guard Thomas.",
    rewards = "420 XP",
    tip = "If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area.\n\nBring me his report.",
    isForever = false,
  },
  [1685] = {
    id = 1685,
    title = "Gakin's Summons",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Remen Marcot",
    objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
    rewards = "420 XP",
    tip = "Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.\n\nI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.\n\nYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about ",
    isForever = false,
  },
  [1506] = {
    id = 1506,
    title = "Gan'rul's Summons",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Ophek",
    objectives = "Speak with Gan'rul Bloodeye in Orgrimmar.",
    rewards = "210 XP",
    tip = "You there. $n, right?\n\nI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.\n\nBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.",
    isForever = false,
  },
  [5929] = {
    id = 5929,
    title = "Great Bear Spirit",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.",
    rewards = "420 XP",
    tip = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.\n\nGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teach",
    isForever = false,
  },
  [5930] = {
    id = 5930,
    title = "Great Bear Spirit",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
