  [6388] = {
    id = 6388,
    title = "Gryth Thurden",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Golnir Bouldertoe",
    objectives = "Bring the Honorary Picks to Gryth Thurden in Ironforge.",
    rewards = "210 XP",
    tip = "Here are the honorary picks for Brock's students.  If you've already been to Thelsamar, then you should fly a gryphon back there!\n\nTake the picks to our gryphon master, Gryth Thurden, and speak with him about a ride back to Thelsamar.",
    isForever = false,
