  [1478] = {
    id = 1478,
    title = "Halgar's Summons",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Ageron Kargal",
    objectives = "Speak with Carendin Halgar in the Undercity.",
    rewards = "210 XP",
    tip = "Ah, $n! I just received word from Carendin Halgar that he would like to see you for further training.\n\nYou should be proud of yourself, $n. It's not every day that Master Halgar personally sees fit to instruct a young warlock.\n\nYou'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.",
    isForever = false,
  },
  [5923] = {
    id = 5923,
    title = "Heeding the Call",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Denatharion",
    objectives = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
    rewards = "85 XP",
    tip = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.",
    isForever = false,
  },
  [5924] = {
