  [5926] = {
    id = 5926,
    title = "Heeding the Call",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Innkeeper Pala",
    objectives = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.",
    rewards = "85 XP",
    tip = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.",
    isForever = false,
  },
  [5927] = {
