  [5652] = {
    id = 5652,
    title = "Hex of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Ur'kyo",
    objectives = "Speak to Ur'kyo in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "I sent here to make sure that you not wander too far from home, $N. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You got to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.",
    isForever = false,
  },
  [5654] = {
    id = 5654,
    title = "Hex of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Tai'jin",
    objectives = "Speak to Ur'kyo in Orgrimmar.",
    rewards = "210 XP",
    tip = "It be time for you to meet with Ur'kyo, $N. He be in the Valley of Spirits in the orc city. Go there and speak to him. It is time you learn more of the old ways of our kind. It time you be brought into the circle and made a true priest of our tribe.",
    isForever = false,
  },
  [5655] = {
    id = 5655,
    title = "Hex of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Class Trainer",
    objectives = "Speak to Ur'kyo in Orgrimmar.",
    rewards = "210 XP",
    tip = "I sent here to make sure that you not wander too far from home, $N. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You go to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.",
    isForever = false,
  },
  [5656] = {
    id = 5656,
    title = "Hex of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Class Trainer",
    objectives = "Speak to Ur'kyo in Orgrimmar.",
    rewards = "210 XP",
    tip = "It always warms my undying heart to see priests from all cultures wander the world. To know that power exists that is not arcane and well within our grasp. That's why it is my honor to direct you home, $N.\n\nUr'kyo, your great priest in Orgrimmar, has asked for your presence. You can find him in the Valley of Spirits.",
    isForever = false,
  },
  [5657] = {
    id = 5657,
    title = "Hex of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Aelthalyste",
    objectives = "Speak to Ur'kyo in Orgrimmar.",
    rewards = "210 XP",
    tip = "Home. Return home, young $r.\n\nYour spiritual leader Ur'kyo begs you to return to him and speak about the path you travel.\n\nGo to the Valley of Spirits in the great Horde city of Orgrimmar. You will find him there.",
    isForever = false,
  },
  [6387] = {
    id = 6387,
    title = "Honor Students",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Brock Stoneseeker",
    objectives = "Bring Brock's List to Thorgrum Borrelson in Thelsamar.",
    rewards = "210 XP",
    tip = "I see a lot of young dwarves at my door, eager to learn the trade of mining.  And if there's one thing a miner needs more than anything, it's a pick!\n\nI have a list of mining students who scored high in their lessons and earned an honorary pick.  Take my list to Golnir Bouldertoe in Ironforge.  He'll get the picks ready.\n\nThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Thorgrum Borrelson, and speak with him about transport to Ironforge.",
    isForever = false,
  },
  [9262] = {
    id = 9262,
    title = "Investigate the Scourge of Darnassus",
    reqLevel = 1,
    questLevel = 10,
    faction = "Both",
    zone = "Azeroth",
    npc = "Lieutenant Beitha",
    objectives = "Collect three Dim Necrotic Stones from the Scourge outside Darnassus and investigate the glowing runic circles nearby their encampment.",
    rewards = "417 XP",
    tip = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Darnassus from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!",
    isForever = false,
  },
