  [9264] = {
    id = 9264,
    title = "Investigate the Scourge of Thunder Bluff",
    reqLevel = 1,
    questLevel = 10,
    faction = "Both",
    zone = "Azeroth",
    npc = "Lieutenant Lisande",
    objectives = "Collect three Dim Necrotic Stones from the Scourge outside Thunder Bluff and investigate the glowing runic circles nearby their encampment.",
    rewards = "630 XP • 2s 50c",
