  [775] = {
    id = 775,
    title = "Journey into Thunder Bluff",
    reqLevel = 3,
    questLevel = 10,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Ancestral Spirit",
    objectives = "Speak with Cairne Bloodhoof in Thunder Bluff.",
    rewards = "420 XP",
    tip = "You will now be revered within our great city. Any $r worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.",
    isForever = false,
  },
  [1884] = {
    id = 1884,
    title = "Ju-Ju Heaps",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Un'Thuwa",
    objectives = "Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village.",
    rewards = "840 XP",
    tip = "The warlock Zalazane of the Echo Isles has disrupted the normal flow of magic in Durotar.  He does this through tainted fetishes, ju-ju heaps, which he has placed among his huts on the main Echo Isle.\n\nThese heaps corrupt our wildlife and give power to the warlocks and infernal creatures that lurk in the land's dark corners.\n\nYou must destroy the ju-ju heaps, $N, before the flow of magic is forever altered.",
    isForever = false,
  },
  [769] = {
    id = 769,
    title = "Kodo Hide Bag",
    reqLevel = 4,
    questLevel = 10,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Veren Tallstrider",
    objectives = "Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.",
    rewards = "420 XP",
    tip = "The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us.  If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade.\n\nDo this, and I will share my knowledge with you.",
    isForever = false,
  },
  [1880] = {
    id = 1880,
    title = "Mage-tastic Gizmonitor",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Bink",
    objectives = "Bring Bink her Mage-tastic Gizmonitor.",
    rewards = "840 XP",
    tip = "We mages do more than just waggle our fingers and make pretty sparks!  We control magic, the base fabric of our world!  And that takes great care, and resolve.  And knowledge... so much knowledge!\n\nOne of my devices, the mage-tastic gizmonitor, collects and stores that knowledge in huge amounts!  But it's lost!  When we fled our home of Gnomeregan, I left it in a chest in one of our huts outside the city, and now the place is crawling with leper gnomes!\n\nPlease, $N, retrieve my gizmonitor!",
    isForever = false,
  },
  [147] = {
    id = 147,
    title = "Manhunt",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Marshal Dughan",
    objectives = "Find and kill \"the Collector\"  then return to Marshal Dughan with The Collector's Ring.",
    rewards = "840 XP",
    tip = "If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom!  Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me.  It may tell us whom the Collector is working for...\n\nThat Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch.  You should search for him there.",
    isForever = false,
  },
  [1666] = {
    id = 1666,
    title = "Marshal Haggard",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Harry Burlguard",
    objectives = "Speak with Marshal Haggard.",
    rewards = "420 XP",
    tip = "You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you.\n\nMarshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career.\n\nLet him know I sent you, and with luck he'll have a spare weapon to offer.",
    isForever = false,
  },
  [6365] = {
    id = 6365,
    title = "Meats to Orgrimmar",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Zargh",
    objectives = "Bring Zargh's Meats to Devrak in the Crossroads.",
    rewards = "210 XP",
    tip = "I have some choice cuts of meat that I want to send to a friend.  Her name is Gryshka, the innkeeper in Orgrimmar.  Will you deliver the meat for me?\n\nThe fastest way to Orgrimmar is on a wind rider.  Take the meats to the Crossroads wind rider master, Devrak, and speak with him about transport to Orgrimmar.",
    isForever = false,
  },
  [1885] = {
    id = 1885,
    title = "Mennet Carkad",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Marion Call",
    objectives = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.",
    rewards = "210 XP",
    tip = "$n? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?\n\nEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons.",
    isForever = false,
  },
  [6322] = {
    id = 6322,
    title = "Michael Garrett",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Gordon Wendham",
    objectives = "Bring Gordon's Crate to Michael Garrett.",
    rewards = "210 XP",
    tip = "I have placed the Sepulcher's supplies into this crate.  If you have already visited the Sepulcher and spoken with their bat master, then you may ride a bat back to him.\n\nSpeak with the Undercity's bat master, Michael Garrett.  He can provide you with a bat to the Sepulcher.",
    isForever = false,
  },
  [1861] = {
    id = 1861,
    title = "Mirror Lake",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Jennea Cannon",
    objectives = "Bring a Mirror Lake sample to Jennea Cannon in Stormwind.",
    rewards = "840 XP",
    tip = "This world has been victim to massive mystic struggles, which tore magic currents from once stable channels.  We struggle to determine the effects these changes have caused, and some of us fear the worst!\n\nBut I will reveal more of this later.  Right now, we need you to gather information.\n\nHere, take this flask.  Go to the base of the waterfall at Mirror Lake, southwest of the Stormwind gates, and retrieve a sample of the water there.  Return it to me so that I might test it for magical taints.",
    isForever = false,
  },
  [5921] = {
    id = 5921,
    title = "Moonglade",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Mathrengyl Bearwalker",
    objectives = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
    rewards = "210 XP",
    tip = "All druids are welcome in the sacred lands of Moonglade, regardless of the current tensions in the Cenarion Circle between Arch Druid Staghelm and Keeper Remulos - Moonglade's guardian.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, youn",
    isForever = false,
  },
  [5922] = {
    id = 5922,
    title = "Moonglade",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Turak Runetotem",
    objectives = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
    rewards = "210 XP",
    tip = "All druids are welcomed to the sacred lands of Moonglade, tauren and night elf alike.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.",
    isForever = false,
  },
  [1679] = {
    id = 1679,
    title = "Muren Stormpike",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Granis Swiftaxe",
    objectives = "Speak with Muren Stormpike.",
    rewards = "85 XP",
    tip = "Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.\n\nYou can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior.",
    isForever = false,
  },
  [6344] = {
    id = 6344,
    title = "Nessa Shadowsong",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Mydrannul",
    objectives = "Speak with Nessa Shadowsong.",
    rewards = "210 XP",
    tip = "A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut'theran Village.  She needs a parcel taken to Darkshore, and is looking for someone to help her.\n\nIf you're interested, then to reach Nessa you must take the portal in Darnassus to Rut'theran Village.  You will find the portal west of the Temple Gardens.",
    isForever = false,
  },
  [2239] = {
    id = 2239,
    title = "Onin's Report",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Onin MacHammar",
    objectives = "Take Onin's Report back to Hulfdan in Ironforge.",
    rewards = "840 XP",
    tip = "The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.\n\nMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.\n\nIt's all in the report, $r. Take it back to Hulfdan so he can plan the next step.",
    isForever = false,
  },
  [412] = {
    id = 412,
    title = "Operation Recombobulation",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Razzle Sprysprocket",
    objectives = "Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",
    rewards = "840 XP",
    tip = "Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes.\n\nOzzie and I plan to reverse the horrible leper effect with our latest invention: The Recombobulator.  The machine is almost complete but we are in dire need of some Restabilization Cogs and Gyromechanic Gears.  Retrieve some from the leper gnomes out front of Gnomeregan for ",
    isForever = false,
  },
  [1498] = {
    id = 1498,
    title = "Path of Defense",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Uzzek",
    objectives = "Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.",
    rewards = "630 XP",
    tip = "As a warrior, one of our most crucial tasks is... protection.  We are the shield of the Horde, and we keep our weaker brethren safe.  If you are to join in our ranks, then you must prove your mettle to me.\n\nGo to Thunder Ridge in Durotar, where live the lightning hides and thunder lizards.  Hunt the beasts!  Show me you are tougher than they!  Brave their assaults and bring me a stack of their singed scales as proof.\n\nDo this, and then I will teach you.",
    isForever = false,
  },
  [52] = {
    id = 52,
    title = "Protect the Frontier",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Guard Thomas",
    objectives = "Kill 8 Prowlers and 5 Young Forest Bears, and then return to Guard Thomas at the east Elwynn bridge.",
    rewards = "630 XP • 2s 50c",
    tip = "Hail, $N.  Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears!\n\nWe could use your help out here.",
    isForever = false,
  },
  [421] = {
    id = 421,
    title = "Prove Your Worth",
    reqLevel = 9,
    questLevel = 10,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Dalar Dawnweaver",
    objectives = "Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.",
    rewards = "840 XP • 3s 50c",
    tip = "Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south.\n\nBut that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest.\n\nI need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.",
    isForever = false,
  },
  [415] = {
    id = 415,
    title = "Rejold's New Brew",
    reqLevel = 8,
    questLevel = 10,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Pilot Bellowfiz",
    objectives = "Speak with Rejold Barleybrew.",
    rewards = "85 XP",
    tip = "Rejold Barleybrew at Brewnall Village has been asking for you.\n\nHe wants to talk to you about a new drink he's been brewing...said something about you helping him with it.  You might want to head back to Brewnall Village and see what he has to say.\n\nThere could be some free booze in it for you...",
    isForever = false,
  },
  [109] = {
    id = 109,
    title = "Report to Gryan Stoutmantle",
    reqLevel = 9,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Guard Thomas",
    objectives = "Talk to Gryan Stoutmantle.  He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.",
    rewards = "630 XP • 2s 50c",
    tip = "Looks to me you've seen quite a bit of combat in your time, $c.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.",
    isForever = false,
  },
  [71] = {
    id = 71,
    title = "Report to Thomas",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Object: Rolf's corpse",
    objectives = "Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.",
    rewards = "210 XP",
    tip = "Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.",
    isForever = false,
  },
  [6392] = {
    id = 6392,
    title = "Return to Brock",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Gryth Thurden",
    objectives = "Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar.",
    rewards = "1,050 XP • 3s 50c",
    tip = "For a small fee you can buy a gryphon ride to Thelsamar... as long as you've already been there.  Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later.\n\nYou've already been to Thorgrum, the gryphon master of Thelsamar, so now you can return to him.  And once in Thelsamar, you can deliver the picks to Brock Stoneseeker.\n\nSpeak with me when you're ready to go.",
    isForever = false,
  },
  [6364] = {
    id = 6364,
    title = "Return to Jahan",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Tal",
    objectives = "Buy a wind rider to the Crossroads from the wind rider master Tal, then bring Ahanu's Leather Goods to Jahan Hawkwing.",
    rewards = "1,050 XP • 3s 50c",
    tip = "In order to fly to a town, you must have already been there and spoken with the wind rider master of that town.  You have been to the Crossroads and spoken to their wind rider master Devrak, so for a small fee you can take a wind rider to him from here.\n\nSpeak with me again when you are ready.  Once at the Crossroads, you can then deliver the leather goods to Jahan Hawkwing.",
    isForever = false,
  },
  [6285] = {
    id = 6285,
    title = "Return to Lewis",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Dungar Longdrink",
    objectives = "Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill.",
    rewards = "1,050 XP • 3s 50c",
    tip = "The gryphon master in Westfall is Thor.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Thor, so just speak with me again when you're ready to take a gryphon to Westfall.  Once there, you can deliver Osric's Crate to Quartermaster Lewis.",
    isForever = false,
  },
  [6343] = {
    id = 6343,
    title = "Return to Nessa",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Laird",
    objectives = "Bring Laird's Response to Nessa Shadowsong.",
    rewards = "1,050 XP • 2s 50c",
    tip = "I must send a response to Nessa.  She'll be very interested to know how different the fish here are from those along Teldrassil's coastline.  We can only guess the cause, but it is my suspicion that the world tree itself is affecting the wildlife around it!\n\nPlease, take this response to Nessa.  If you wish to take a hippogryph back to Rut'theran then speak with the hippogryph master Caylais Moonfeather.  If you wish to take the ferry, then one regularly departs from the dock to the northwest.",
    isForever = false,
  },
  [6324] = {
    id = 6324,
    title = "Return to Podrig",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Michael Garrett",
    objectives = "Buy a bat ride to the Sepulcher from the bat master Michael Garrett, then bring Gordon's Crate to Deathguard Podrig in the Sepulcher.",
    rewards = "1,050 XP • 3s 50c",
    tip = "The bat master in the Sepulcher is Karos Razok.  If you have already met him, then I can give you a bat to fly back to him.\n\nOur bats will always fly to the Undercity, but to travel to more remote locales their rider must first visit the area and speak with its bat master.\n\nYou have met Karos in the Sepulcher, so you may now fly bats there.  Speak with me again when you are ready.",
    isForever = false,
  },
  [6386] = {
    id = 6386,
    title = "Return to the Crossroads.",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Doras",
    objectives = "Buy a wind rider to the Crossroads from the wind rider master Doras, then bring Gryshka's Letter to Zargh at the Crossroads.",
    rewards = "1,050 XP • 3s 50c",
    tip = "My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there.\n\nYou have been to the Crossroads and spoken to their wind rider master Devrak, so now you can fly directly to him from here.  Once you're at the Crossroads, you can deliver Gryshka's letter to Zargh.\n\nSpeak with me when you are ready to go.",
    isForever = false,
  },
  [5628] = {
    id = 5628,
    title = "Returning Home",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Priestess Josetta",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "210 XP",
    tip = "Ah, yes, hello, $N? I'm glad you stopped to talk for a moment. You are a far way from home at such a young age--I admire such ambition. I wish when I was younger I could have mustered the courage to travel the world.\n\nThere was a priestess of your order here looking for you not too long ago. She said it was very urgent you returned to the Temple of the Moon in Darnassus and speak to Priestess Alathea--it had something to do with your training. I wouldn't dally too long if you can help it.",
    isForever = false,
  },
  [5629] = {
    id = 5629,
    title = "Returning Home",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Laurna Morninglight",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "210 XP",
    tip = "Hello again, $N. I know you've been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you've caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.",
    isForever = false,
  },
  [5630] = {
    id = 5630,
    title = "Returning Home",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Maxan Anvol",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "210 XP",
    tip = "Hello there, $gladdy:lassy;. Good to see you travelin' far and wide to distant lands. No offense meant, but a lot o' your kind don't take well to these cold climates usually. Glad to see you're made of tougher stuff.\n\nNot too long ago one of your priestesses was in here lookin' for you--said somethin' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.",
    isForever = false,
  },
  [5631] = {
    id = 5631,
    title = "Returning Home",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Brother Joshua",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "210 XP",
    tip = "A priestess recently visited our halls seeking you out, young $r. She said that she was on a mission to find you and that you should return to the Temple of the Moon in Darnassus as soon as possible. When you arrive, seek out a Priestess Alathea--she will tell you more.\n\nThe Light be with you, $N.",
    isForever = false,
  },
  [5632] = {
    id = 5632,
    title = "Returning Home",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Nara Meideros",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "210 XP",
    tip = "Oh, yes, of course. Hello, $N. A messenger from our order was here not too long ago looking for you. She mentioned something important happening back in Darnassus and that you should return to the Temple of the Moon as soon as you can. When you arrive, speak to Priestess Alathea. I believe it has something to do with your progressing so well in our ways.\n\nAgain, return to Darnassus when you can.",
    isForever = false,
  },
  [5633] = {
    id = 5633,
    title = "Returning Home",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Braenna Flintcrag",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "210 XP",
    tip = "Greetings, $gladdy:lass;. Good to see you here in our great halls. A blessing be on you and your kind.\n\nWhile you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I'm sorry I can't tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.",
    isForever = false,
  },
  [6391] = {
    id = 6391,
    title = "Ride to Ironforge",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Thorgrum Borrelson",
    objectives = "Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge.",
    rewards = "420 XP • 1s 75c",
    tip = "For just a few coins, one of my gryphons will take you to Ironforge.  From there, deliver Brock's list to Golnir Bouldertoe.  You'll find him in the Deep Mountain Mining Guild.  That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off!\n\nSpeak to me again when you're ready for the journey.",
    isForever = false,
  },
  [6384] = {
    id = 6384,
    title = "Ride to Orgrimmar",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Devrak",
    objectives = "Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh's Meats to Gryshka in Orgrimmar.",
    rewards = "420 XP • 1s 75c",
    tip = "For just a few coins I will have a wind rider bring you to Orgrimmar.  When you get there, you can take Zargh's Meats to Gryshka.  Her inn is in the Valley of Strength, not far from the Skytower, where my wind rider will drop you off.\n\nSpeak with me again when you are ready for the journey.",
    isForever = false,
  },
  [6362] = {
    id = 6362,
    title = "Ride to Thunder Bluff",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Devrak",
    objectives = "Buy a wind rider to Thunder Bluff from the wind rider master Devrak, then bring the Bundle of Hides to Ahanu in Thunder Bluff.",
    rewards = "420 XP • 1s 75c",
    tip = "For a small fee, I will give you a wind rider to Thunder Bluff.  There's no faster way to the city!\n\nIf that is acceptable, speak to me again when you are ready to go.\n\nIf you're taking those hides to Ahanu, then I think he's at Hewa's Armory, at the base of the wind rider tower in Thunder Bluff.  And that's right where you'll land!",
    isForever = false,
  },
  [6323] = {
    id = 6323,
    title = "Ride to the Undercity",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Karos Razok",
    objectives = "Buy a bat ride to the Undercity from the bat master Karos Razok, then take Podrig's Order to Gordon Wendham in the Undercity.",
    rewards = "420 XP • 1s 75c",
    tip = "One of my bats can take you to the Undercity, for a small fee.  Speak with me again when you are ready so that we may arrange your transport.\n\nYou will find Gordon Wendham in the Trade Quarter of the Undercity.  That is the same quarter where my bat will land.",
    isForever = false,
  },
  [773] = {
    id = 773,
    title = "Rite of Wisdom",
    reqLevel = 3,
    questLevel = 10,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Seer Wiserunner",
    objectives = "Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.",
    rewards = "840 XP",
    tip = "To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.\n\nNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.\n\nTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, $n.",
    isForever = false,
  },
  [11] = {
    id = 11,
    title = "Riverpaw Gnoll Bounty",
    reqLevel = 6,
    questLevel = 10,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Deputy Rainer",
    objectives = "Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.",
    rewards = "840 XP",
    tip = "Pro-tip: Fantastic quest to get a free 14-slot bag during mid-level leveling.",
    isForever = false,
  },
  [2218] = {
    id = 2218,
    title = "Road to Salvation",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Hogral Bakkan",
    objectives = "Speak with Hulfdan Blackbeard in Ironforge.",
    rewards = "420 XP, 1s 75c",
    tip = "Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.\n\nWell, today's your lucky day, friend. Hogral's got the cure for your ailment.\n\nHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.",
    isForever = false,
  },
  [2205] = {
    id = 2205,
    title = "Seek out SI: 7",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Keryn Sylvius",
    objectives = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.",
    rewards = "210 XP, 85c",
    tip = "The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery $g boy:girl; instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.\n\nSpeaking of which, deliver this package to Mathias and he may give you a small task or two.\n\nGet cracking.",
    isForever = false,
  },
  [860] = {
    id = 860,
    title = "Sergra Darkthorn",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Melor Stonehoof",
    objectives = "Speak with Sergra Darkthorn at the Crossroads.",
    rewards = "85 XP",
    tip = "If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow.\n\nSpeak with Sergra Darkthorn.  She will be your first guide in the Barrens.\n\nSergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary.",
    isForever = false,
  },
  [413] = {
    id = 413,
    title = "Shimmer Stout",
    reqLevel = 8,
    questLevel = 10,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Rejold Barleybrew",
    objectives = "Take the Barrel of Shimmer Stout to Mountaineer Barleybrew.",
    rewards = "420 XP",
    tip = "I'd like my brother Wellart to try my new Shimmer Stout.  He's a Mountaineer stationed in the southern guard tower, one of two towers on the border to Loch Modan.\n\nHe may not be a brewer like the rest of us Barleybrews, but he loves his drinks and I know he'll like this one.\n\nCan you bring him this Barrel of Shimmer Stout for me?",
    isForever = false,
  },
  [2238] = {
    id = 2238,
    title = "Simple Subterfugin'",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Hulfdan Blackbeard",
    objectives = "Find Onin MacHammar by Gnomeregan.",
    rewards = "840 XP",
    tip = "Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.\n\nThe Hidden Circle has values, $N. We value valuables. Can ye understand?\n\nNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.\n\nWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.",
    isForever = false,
  },
  [1692] = {
    id = 1692,
    title = "Smith Mathiel",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Elanaria",
    objectives = "Bring the Case of Elunite to Smith Mathiel.",
    rewards = "420 XP",
    tip = "I have placed the elunite you gathered into a case.  Take it to the blacksmith Mathiel, and he will craft for you an elunite weapon.\n\nMathiel is to the south, on the other side of this building.",
    isForever = false,
  },
  [2206] = {
    id = 2206,
    title = "Snatch and Grab",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Master Mathias Shaw",
    objectives = "- Defias Shipping Schedule",
    rewards = "840 XP",
    tip = "Our operatives in the field are reporting heavy Defias activity south of Goldshire. The reports indicate that the Defias have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.\n\nI need you to infiltrate the dock house and get me that shipping schedule, $N. You will probably find it buried deep in the pockets of the Dockmaster.\n\n...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence.",
    isForever = false,
  },
  [1881] = {
    id = 1881,
    title = "Speak with Anastasia",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Cain Firesong",
    objectives = "Speak with Anastasia Hartwell.",
    rewards = "85 XP",
    tip = "$N, Anastasia Hartwell has a task for someone of your talents.  Speak with her in the Magic Quarter of the Undercity, and prepare yourself for your first task for the mages of the Forsaken.",
    isForever = false,
  },
  [1879] = {
    id = 1879,
    title = "Speak with Bink",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Magis Sparkmantle",
    objectives = "Speak with Bink in Ironforge.",
    rewards = "85 XP",
    tip = "$N!  Bink, my gnome colleague in Ironforge, sends word.  She has a task that needs doing and won't rely on anyone but a mage to do it!  Are you that mage, $N?\n\nIf so, then speak with Bink.  She spends her time in the Hall of Mysteries in the Mystic Ward of Ironforge.",
    isForever = false,
  },
  [1820] = {
    id = 1820,
    title = "Speak with Coleman",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Deathguard Dillinger",
    objectives = "Speak with Coleman Farthing.",
    rewards = "210 XP",
    tip = "You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.\n\nColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.\n\nYou will find him in the Gallow's End Tavern in eastern Brill.",
    isForever = false,
  },
  [1818] = {
    id = 1818,
    title = "Speak with Dillinger",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Austil de Mon",
    objectives = "Speak with Deathguard Dillinger in Brill.",
    rewards = "85 XP",
    tip = "I was told Deathguard Dillinger has a job for someone like you.  If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.\n\nDeathguard Dillinger's post is on the west end of Brill, near the graveyard.",
    isForever = false,
  },
  [1860] = {
    id = 1860,
    title = "Speak with Jennea",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Zaldimar Wefhellt",
    objectives = "Speak with Jennea Cannon in Stormwind.",
    rewards = "420 XP",
    tip = "We mages have a task that needs doing.  One that is vital to the safety of Stormwind and Elwynn forest.\n\nJennea Cannon has the details.  She studies in the wizard's sanctum, in the mage district of Stormwind.  You should make your way to her with haste.",
    isForever = false,
  },
  [355] = {
    id = 355,
    title = "Speak with Sevren",
    reqLevel = 7,
    questLevel = 10,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Coleman Farthing",
    objectives = "Speak with Magistrate Sevren in Brill.",
    rewards = "85 XP",
    tip = "You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me.\n\nI have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.",
    isForever = false,
  },
  [1883] = {
    id = 1883,
    title = "Speak with Un'thuwa",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Thurston Xane",
    objectives = "Speak with Un'thuwa.",
    rewards = "85 XP",
    tip = "Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid.  Speak with Un'thuwa and do what you can to help him.\n\nDo this, and in time further secrets will be revealed to you.",
    isForever = false,
  },
  [5627] = {
    id = 5627,
    title = "Stars of Elune",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Priestess Alathea",
    objectives = "Speak with Priestess Alathea in Priest Class Quests.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [414] = {
    id = 414,
    title = "Stout to Kadrell",
    reqLevel = 8,
    questLevel = 10,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Mountaineer Barleybrew",
    objectives = "Take the Cask of Shimmer Stout to Mountaineer Kadrell.",
    rewards = "630 XP",
    tip = "I've been drinking more of that Shimmer Stout my brother made - it's great stuff!  I want a fellow Mountaineer to try it.  His name's Kadrell, and he's usually patrolling the road through Thelsamar in Loch Modan.\n\nTo get to Thelsamar, go southeast through the tunnel, then turn northeast when the path forks into a road.  Follow that road straight into Thelsamar.\n\nGive Mountaineer Kadrell this cask of Shimmer Stout and see what he thinks!",
    isForever = false,
  },
  [6321] = {
    id = 6321,
    title = "Supplying the Sepulcher",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Deathguard Podrig",
    objectives = "Bring Podrig's Order to Karos Razok.",
    rewards = "210 XP",
    tip = "Executor Hadrec asked me to take stock of our equipment at the Sepulcher.  With the Scourge, and worse, lurking in the woods, he doesn't want the Deathguards to lack gear they might need.\n\nI found that we are, in general, well stocked, but we do need more weapons to replace those lost in the field.\n\nHere is a requisition order of what is needed, for the weapon dealer Gordon Wendham in the Undercity.  Take the order to our bat master, Karos Razok, and speak with him about transport to the Underci",
    isForever = false,
  },
  [1688] = {
    id = 1688,
    title = "Surena Caledon",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Gakin the Darkbinder",
    objectives = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.",
    rewards = "630 XP",
    tip = "I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!\n\nThe thieving wench ran off with one of the Defias, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.\n\nHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what i",
    isForever = false,
  },
  [6363] = {
    id = 6363,
    title = "Tal the Wind Rider Master",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Ahanu",
    objectives = "Bring Ahanu's Leather Goods to Tal in Thunder Bluff.",
    rewards = "210 XP",
    tip = "I have prepared leather goods for Jahan to sell at the Crossroads.  Will you bring them to him?\n\nIf you have already been to the Crossroads and spoken to their wind rider master, then you can fly one of our Thunder Bluff wind riders back to him.\n\nTake the leather goods to Tal, our wind rider master in Thunder Bluff, and speak with him to arrange transport to the Crossroads.",
    isForever = false,
  },
  [6061] = {
    id = 6061,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Yaw Sharpmane",
    objectives = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
    rewards = "840 XP",
    tip = "As a tauren, it is important to follow the traditions of our ancestors by fighting mighty creatures. By besting these creatures, we are able to intake their spirits, allowing us to become closer to the Earthmother.\n\nIn the same way, taming a beast to fight alongside us helps us become one with nature around us. Eventually, you will learn to tame a beast of your choosing. But all things take practice, and you have much to learn. Begin by taking this taming rod; you must tame an adult plainstrider",
    isForever = false,
  },
  [6062] = {
    id = 6062,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Thotar",
    objectives = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.",
    rewards = "840 XP",
    tip = "It is an admirable skill to command one's authority over nature. As a hunter, you must strive to learn to use the force and power inherent to any creature of your choosing.\n\nGaining control of an animal is not an easy feat; it is a task that you must undertake with much determination.\n\nFor your first assignment, take this taming rod and use it to tame a dire mottled boar. You can find them quite close to Razor Hill. Practice your skills in battle with the boar at your side, then return to me.",
    isForever = false,
  },
  [6063] = {
    id = 6063,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Dazalar",
    objectives = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
    rewards = "840 XP",
    tip = "As a hunter, it is important to remember the responsibility you hold in your hands. Nature is not a power that can be bent to obey our desires; it is one that is to be respected and acknowledged as something stronger than your very existence.\n\n$N, you must prove your understanding of this before you will gain the ability to tame an animal to be your companion.\n\nYour first task is to take this taming rod. With it, you will be able to tame a webwood lurker. Tame it, and practice your skills as a h",
    isForever = false,
  },
  [6064] = {
    id = 6064,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Grif Wildheart",
    objectives = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.",
    rewards = "840 XP",
    tip = "Hi there, $Glad:lass;! So, you'd be wanting to know how you can gain a pet of your own?\n\nWell, let's get started. There's nothing more important than yer equipment when it comes to hunting, but we can chat about my new Shrapnel Blaster some other time. Fer now, let's focus on something I'm sure you're quite interested in: a pet!\n\nThe best way to learn is for you to try out several creatures as companions and see what ya like. So, find a large crag boar, then use the taming rod to tame it.",
    isForever = false,
  },
  [6082] = {
    id = 6082,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Thotar",
    objectives = "- Tame an Armored Scorpid",
    rewards = "840 XP",
    tip = "The final creature you need to tame is one you should strive to emulate; the armored scorpid. It strikes quickly and confidently; to control a force such as this is your fate as a hunter.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing; this creature will be yours to command. Under your control, your pet will gain experience alongside you. I will also show you how to call it and dismiss it as you wish.",
    isForever = false,
  },
  [6083] = {
    id = 6083,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Thotar",
    objectives = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill.",
    rewards = "840 XP",
    tip = "The advantage a pet affords you against your rivals is duly noted, $N. When you gain control over another creature, you are adding to your own strength. Your pet must become an extension of yourself.\n\nThe next task requires you to turn from the land; you will find the next creature in the waters off the coast. Across from Sen'jin Village, near the Echo Isles. look for a spirited crab called the surf crawler. Use the taming rod to tame it, then practice your skills.",
    isForever = false,
  },
  [6084] = {
    id = 6084,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Grif Wildheart",
    objectives = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.",
    rewards = "840 XP",
    tip = "Those crag boars are quite burly; maybe you'd like something with a little more finesse? Alright then, I've got jus' the thing. South and east of here, you'll find large white cats called snow leopards. Just like an elegantly-carved rifle, behind their beautiful exterior lies a powerful fighter, capable of doing extreme damage. You'll find them to be much more agile an' swift than the boar you tamed.\n\nTake this taming rod and see how you like the snow leopard.",
    isForever = false,
  },
  [6085] = {
    id = 6085,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Grif Wildheart",
    objectives = "- Tame an Ice Claw Bear",
    rewards = "840 XP",
    tip = "Perhaps you'd like a creature that possesses little more than brute strength. The ice claw bear is an excellent companion for a fledgling hunter like yourself, and can be found east of Kharanos. Here is the taming rod; try this animal as a pet and see if ya like it!\n\nWhen you return, I'll give ya the skills you will need to tame an animal of your choosing; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as ya ",
    isForever = false,
  },
  [6087] = {
    id = 6087,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Yaw Sharpmane",
    objectives = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
    rewards = "840 XP",
    tip = "You have a fiery spirit, hunter, readily awaiting your next challenge.\n\nYour next task is to gain the companionship of a wolf known as the prairie stalker. This creature is swift and fearless; in taking this beast as your pet, you must also take on these qualities.\n\nDuring a battle, you will learn how you and your pet will become a team. In the end you must work as one, muscle to muscle.\n\nHere is the taming rod, $N. Tame a prairie stalker and practice your skills.",
    isForever = false,
  },
  [6088] = {
    id = 6088,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Yaw Sharpmane",
    objectives = "- Tame a Swoop",
    rewards = "840 XP",
    tip = "The final task that I have for you requires that you tame a creature that inhabits the sky. The swoop is a difficult opponent, but as your ally, you will acquire its sharp attacks and threatening presence.\n\nBy the will of the Earthmother, when you return I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as yo",
    isForever = false,
  },
  [6101] = {
    id = 6101,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Dazalar",
    objectives = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
    rewards = "840 XP",
    tip = "The variance of nature is something that can be relied upon, $N. It is predictable in the way that it never remains the same; it is always changing.\n\nThe tasks I give to you will help you to see and appreciate the vast differences of the creatures you may choose as your companion.\n\nTake this taming rod and use it to tame a nightsaber stalker, found to the south. Practice your skills as a hunter. Then you will begin to understand the similarities and differences of nature.",
    isForever = false,
  },
  [6102] = {
    id = 6102,
    title = "Taming the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Dazalar",
    objectives = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
    rewards = "840 XP",
    tip = "You have tamed two creatures that inhabit the land, now you must tame one that soars the skies. Use the taming rod to tame a strigid screecher, found west of here. Practice your skills with this mighty owl at your side.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish.",
    isForever = false,
  },
  [2241] = {
    id = 2241,
    title = "The Apple Falls",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Jannok Breezesong",
    objectives = "Take Jannok's Rose to Syurna in Darnassus.",
    rewards = "420 XP",
    tip = "They say I'm 'lovestruck,' whatever that means.\n\nSure, I spend my every waking moment thinking about Syurna. Sure, my home is full of paintings and drawings of Syurna. Sure, I often go days without eating, sleeping, or drinking, while I lament about the love we could have had. Is that so wrong?\n\nNow she won't see me! ME! I've tried sending her messages but she won't even talk to another person unless they are a rogue.\n\nCould you deliver this flower to her? Don't forget to tell her it's from Jann",
    isForever = false,
  },
  [1882] = {
    id = 1882,
    title = "The Balnir Farmstead",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Anastasia Hartwell",
    objectives = "Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity.",
    rewards = "840 XP",
    tip = "The Plaguelands to the east are an aberration.  Devised by the Lich King, they spread their magic into the soil, corrupting and killing all that live.  Although there is a certain charm to the destructive forces of the plague, we, the mages of the Forsaken, believe it is unruly and must be curtailed.\n\nBut first, we must measure how far it has spread into Tirisfal.  Go to the Balnir Farmstead in eastern Tirisfal.  In the garden are flowers--snapdragons.  Gather these and return.",
    isForever = false,
  },
  [886] = {
    id = 886,
    title = "The Barrens Oases",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Arch Druid Hamuul Runetotem",
    objectives = "Speak with Tonga Runetotem at the Crossroads.",
    rewards = "85 XP",
    tip = "The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.\n\nTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.\n\nTravel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads.\n\nAnd do not leave the road, $N, for the Barrens is a harsh land.",
    isForever = false,
  },
  [1471] = {
    id = 1471,
    title = "The Binding",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Carendin Halgar",
    objectives = "Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity.",
    rewards = "630 XP",
    tip = "Surely you have seen the circle of summoning below us? Only there will you be able to draw forth an unbound voidwalker.\n\nUsing these runes, you will be able to draw it forth, and then you must dominate it through strength of arms and magic.\n\nWhen it is subdued, it will be indentured to you. Come to me then, and I will elucidate the spell of summoning, so that it may serve you to whatever end you wish.",
    isForever = false,
  },
  [1689] = {
    id = 1689,
    title = "The Binding",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Gakin the Darkbinder",
    objectives = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.",
    rewards = "630 XP",
    tip = "By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was.\n\nWith that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that.\n\nI will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle b",
    isForever = false,
  },
  [6341] = {
    id = 6341,
    title = "The Bounty of Teldrassil",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Nessa Shadowsong",
    objectives = "Bring Nessa's Collection to Vesprystus.",
    rewards = "210 XP",
    tip = "The fishermen of Rut'theran village do very well, for the fish here are extremely large and abundant.  I would like to compare the bounty here with that of the mainland.\n\nI have a collection of fish bones and scales that I would like taken to a colleague of mine in Darkshore.  His name is Laird, he is a fish vendor in the village of Auberdine.\n\nBring my collection to our hippogryph master, Vesprystus, and speak to him about traveling to Auberdine.",
    isForever = false,
  },
  [123] = {
    id = 123,
    title = "The Collector",
    reqLevel = 7,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Item: Gold Pickup Schedule",
    objectives = "Go to Marshal Dughan in Goldshire and give him The Collector's Schedule",
    rewards = "210 XP • 85c",
    tip = "This note is a schedule with a list of days and times when a person -- described only as \"The Collector\" -- will receive a shipment of gold from the mines in Elwynn Forest.\n\nFrom the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn.\n\nThis sounds important.  You should report it to Marshal Dughan in Goldshire.",
    isForever = false,
  },
