  [930] = {
    id = 930,
    title = "The Glowing Fruit",
    reqLevel = 4,
    questLevel = 10,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Object: Strange Fruited Plant",
    objectives = "Bring the glowing fruit to Denalan at Lake Al'Ameth.",
    rewards = "840 XP • 3s 50c",
    tip = "Hanging from beneath its fronds of this glowing plant is a large, round fruit.\n\nDenalan would want to study this fruit, you are certain.",
    isForever = false,
  },
  [362] = {
    id = 362,
    title = "The Haunted Mills",
    reqLevel = 7,
    questLevel = 10,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Coleman Farthing",
    objectives = "Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.",
    rewards = "420 XP",
    tip = "Devlin Agamand was the younger of two sons in the Agamand family, and in life the two could not be more different.  Thurman was tall and gentle while his younger brother was weak and sharp tongued.\n\nWhen Agamand Mills fell to the Plague, I was not surprised to hear that Devlin was quick to succumb.  His mad chattering can still be heard near the road leading to the Agamand Mills.\n\nI'm collecting the remains of the Agamands, and I want poor Devlin.  Find him, destroy him, and bring me his bones.",
    isForever = false,
  },
