  [861] = {
    id = 861,
    title = "The Hunter's Way",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Skorn Whitecloud",
    objectives = "Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff.",
    rewards = "840 XP",
    tip = "You are eager to explore, I can tell.  I too had the lust to wander, once...\n\nWander, and hunt.  For hunting is a Tauren's greatest honor.\n\nIf you truly wish to follow the ways of the hunter, then Melor Stonehoof can show you the path.  He is in Thunder Bluff, on the Hunter's Rise.\n\nAnd to show him your skill and resolve, bring him the claws of the flatland prowlers of Mulgore.  They are tough and cunning -- fitting prey for a young $c on the hunter's path.",
    isForever = false,
  },
  [76] = {
    id = 76,
    title = "The Jasperlode Mine",
    reqLevel = 4,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Marshal Dughan",
    objectives = "Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.",
    rewards = "840 XP • 3s 50c",
    tip = "Thanks to you we know the Fargodeep Mine is infested with kobolds.  Now we need a scout to investigate the more distant Jasperlode Mine.\n\nExplore Jasperlode and confirm any kobold presence.  To reach the mine, travel east along the road until you reach the Tower of Azora.  From the tower, head north and you'll find the mine in the foothills.",
    isForever = false,
  },
  [419] = {
    id = 419,
    title = "The Lost Pilot",
    reqLevel = 8,
    questLevel = 10,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Pilot Hammerfoot",
    objectives = "Find Pilot Hildelve.",
    rewards = "420 XP",
    tip = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills.  We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot, searching.\n\nIt's been days, and I've heard some beastly growls in the hills at night.  Mori's tough as nails, but I'm worried.\n\nPlease, $N.  Find him.",
    isForever = false,
  },
  [291] = {
    id = 291,
    title = "The Reports",
    reqLevel = 1,
    questLevel = 10,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Senir Whitebeard",
    objectives = "Deliver Senir's report to Senator Barin Redstone in Ironforge.",
    rewards = "420 XP • 1s 75c",
    tip = "Excellent! Take my report to Senator Barin Redstone. He's a sour type, so don't let his less-than-sunny disposition get to you. He's in Ironforge, in the chamber where King Magni holds court.\n\nDon't know the way to Ironforge? Take the road out of Kharanos north, cross the bridge, then follow the road east--there are large banners flanking the road--up the mountainside.\n\nBy the way, if you might avoid mentioning how you assisted me? Can't let them think I'm not working hard out here, you know?",
    isForever = false,
  },
  [1686] = {
    id = 1686,
    title = "The Shade of Elura",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Elanaria",
    objectives = "Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus.",
    rewards = "840 XP",
    tip = "You have learned much, $N.  Now we will craft you a weapon.  A warrior's weapon.\n\nTo do this, you must travel to Darkshore.\n\nLong ago a ship crashed upon the rocks near the Auberdine lighthouse, scattering many crates of elunite ore along the ocean floor.\n\nFirst, you must defeat the elunite's guardian, the Shade of Elura.  Once the ship's captain, she cursed herself to roam the deeps and protect her shipment for all time.  Defeat her, gain her medallion, and gather the crates of lost Elunite.",
    isForever = false,
  },
  [931] = {
    id = 931,
    title = "The Shimmering Frond",
    reqLevel = 4,
    questLevel = 10,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Object: Strange Fronded Plant",
    objectives = "Bring a Shimmering Frond to Denalan at Lake Al'Ameth",
    rewards = "840 XP • 3s 50c",
    tip = "The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura.\n\nYou believe that Denalan would want a specimen of this.",
    isForever = false,
  },
  [1715] = {
    id = 1715,
    title = "The Slaughtered Lamb",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Lago Blackwrench",
    objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
    rewards = "420 XP",
    tip = "Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training.\n\nLuckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood!\n\nAnyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.",
    isForever = false,
  },
  [2399] = {
    id = 2399,
    title = "The Sprouted Fronds",
    reqLevel = 4,
    questLevel = 10,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Object: Sprouted Frond",
    objectives = "Inspect Sprouted Frond in Teldrassil.",
    rewards = "85 XP",
    tip = "",
    isForever = false,
  },
  [2519] = {
    id = 2519,
    title = "The Temple of the Moon",
    reqLevel = 5,
    questLevel = 10,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Sister Aquinne",
    objectives = "Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon.",
    rewards = "85 XP",
    tip = "A once great creature of the forest is in need of help, $r.\n\nThere is a difficult task that must be done.\n\nPlease seek out Priestess A'moora; she will explain things to you. Find her to the southeast of here, inside the Temple of the Moon.",
    isForever = false,
  },
  [764] = {
    id = 764,
    title = "The Venture Co.",
    reqLevel = 5,
    questLevel = 10,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Morin Cloudstalker",
    objectives = "Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village.",
    rewards = "630 XP • 2s 50c",
    tip = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.",
    isForever = false,
  },
  [1859] = {
    id = 1859,
    title = "Therzok",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Kaplak",
    objectives = "Speak with Therzok in the Cleft of Shadow in Orgrimmar.",
    rewards = "210 XP",
    tip = "Lower your voice, $n. Yeah, I know your name. Was told to keep an eye out for an orc by your description.\n\nFrom what we've heard about you, you can handle yourself in combat, and aren't opposed to a little sneakery from time to time.\n\nAm I right?\n\nAnyways, you should go see Therzok in Orgrimmar. He's got an offer for you to hear.",
    isForever = false,
  },
  [1502] = {
    id = 1502,
    title = "Thun'grim Firegaze",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Uzzek",
    objectives = "Speak with Thun'grim Firegaze in the Barrens.",
    rewards = "210 XP",
    tip = "It is vital that a warrior's weapon is one of quality.  And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze.  He is a hermit who dwells atop the hills east of the Crossroads.\n\nIf you seek a weapon, warrior, then you should seek Thun'grim.  To find him, first travel to the Crossroads to the west, then strike east into the hills.  His camp is high on a hilltop.",
    isForever = false,
  },
  [5658] = {
    id = 5658,
    title = "Touch of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Aelthalyste",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "Experience & Faction Reputation",
    tip = "You be far from home, $C. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.",
    isForever = false,
  },
  [5660] = {
    id = 5660,
    title = "Touch of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Tai'jin",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "210 XP",
    tip = "You be far from home, $c. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.",
    isForever = false,
  },
  [5661] = {
    id = 5661,
    title = "Touch of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Class Trainer",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "210 XP",
    tip = "You be far from home out here in the Bloodhoof Village, $N. I be sent here to find priests of my own tribe to send back to speak to our leaders, but that not mean I cannot help you too.\n\nI hear word that your head priestess spirit want all Forsaken to come to her--there are things you must learn.\n\nGo to meet Aelthalyste in the War Quarter in that city of yours.",
    isForever = false,
  },
  [5662] = {
    id = 5662,
    title = "Touch of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Ur'kyo",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "210 XP",
    tip = "My respect to you and your kind, $N. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron.\n\nYou should return to her if you're to learn those abilities that set you apart from other faiths.\n\nGo to the War Quarter in the Undercity and find your mistress there.",
    isForever = false,
  },
  [5663] = {
    id = 5663,
    title = "Touch of Weakness",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Miles Welsh",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "210 XP",
    tip = "Aelthalyste sent word out to all her priests. We're to direct the younger of our order to the Undercity for more training. If you truly count yourself among our faithful, then you should return there also.\n\nYou can find Aelthalyste in the War Quarter deep in the Undercity.",
    isForever = false,
  },
  [6081] = {
    id = 6081,
    title = "Training the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Thotar",
    objectives = "Speak with Ormak Grimshot in Orgrimmar.",
    rewards = "420 XP",
    tip = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Orgrimmar. There you must speak to one of our most revered hunters, Ormak Grimshot. He will give you the ability to train your new pet. You will find him in the Valley of Honor.\n\nGood luck, $N.",
    isForever = false,
  },
  [6086] = {
    id = 6086,
    title = "Training the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Grif Wildheart",
    objectives = "Speak with Belia Thundergranite in Ironforge.",
    rewards = "420 XP",
    tip = "$N, ya now have the power to tame a pet, but you must also gain the skills ta train it.\n\nTravel to Ironforge and find the Hall of Arms. There you must speak to one of our most revered animal trainers, Belia Thundergranite. She'll give ya the power to train your new pet, so get goin', $Glad:lass;!\n\nBelia is a friendly sort; you should have no problems gaining her approval. Good luck, $N.",
    isForever = false,
  },
  [6089] = {
    id = 6089,
    title = "Training the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Hunter Class Quests",
    npc = "Yaw Sharpmane",
    objectives = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff.",
    rewards = "420 XP",
    tip = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Thunder Bluff. There you must speak to one of our most revered hunters, Holt Thunderhorn. If he deems you worthy, he will give you the ability to train your new pet.\n\nHolt has bested the most powerful and feared beasts of Azeroth, and commands many strong creatures of his own. His ties to the Earthmother are strong, and you can learn much from him. Good luck, $N.",
    isForever = false,
  },
  [6103] = {
    id = 6103,
    title = "Training the Beast",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Hunter Class Quests",
    npc = "Dazalar",
    objectives = "Speak to Jocaste in the Cenarion Enclave, in Darnassus.",
    rewards = "420 XP",
    tip = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Darnassus. There you must speak to one of our most revered hunters, Jocaste. She will give you the ability to train your new pet, so make haste.\n\nWhile Jocaste may seem stern, she is always pleased to see another hunter rising through the ranks. Treat her with respect and she will return in kind. Good luck, $N.",
    isForever = false,
  },
  [1819] = {
    id = 1819,
    title = "Ulag the Cleaver",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Deathguard Dillinger",
    objectives = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.",
    rewards = "840 XP",
    tip = "When the Scourge swept through Tirisfal Glades, we captured one to study.  He had a free mind, and called himself Ulag the Cleaver.  But, although his will was free, he was still enthralled by the Lich King.\n\nWe hoped to find a way to break the king's control over Ulag, but we failed.  Now, finally, it is time to free him.  \n\nFree him, and kill him.\n\nActivate the skull stone trigger near the mausoleum to the north.  This will lift the magical seal that binds him.\n\nThen... be ready, $N.",
    isForever = false,
  },
  [1505] = {
    id = 1505,
    title = "Veteran Uzzek",
    reqLevel = 10,
    questLevel = 10,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Krang Stonehoof",
    objectives = "Speak with Uzzek at Far Watch Post.",
    rewards = "85 XP",
    tip = "The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well.\n\nSeek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar.",
    isForever = false,
  },
  [1683] = {
    id = 1683,
    title = "Vorlus Vilehoof",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Elanaria",
    objectives = "Bring the Horn of Vorlus to Elanaria in Darnassus.",
    rewards = "840 XP",
    tip = "Before I can teach you, you must show me your resolve.\n\nThe satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth.\n\nFind Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior.\n\nThe path to the moonwell is hidden well, $N, but stay focused and alert and you will find it.",
    isForever = false,
  },
  [398] = {
    id = 398,
    title = "Wanted: Maggot Eye",
    reqLevel = 6,
    questLevel = 10,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Object: Wanted!",
    objectives = "Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.",
    rewards = "840 XP • 3s 50c",
    tip = "Wanted: Maggot Eye!\n\nA foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken.  This despicable villain has been stealing corpses for use by the Lich King's army.  Maggot Eye was last seen pillaging the lands near Garren's Haunt to the north of Brill.\n\nThe town of Brill hereby offers a reward to the capable soul who can carry out the execution.  Show Executor Zygand the villain's paw once the deed is done.\n\nMercy is for the weak.",
    isForever = false,
  },
  [1693] = {
    id = 1693,
    title = "Weapons of Elunite",
    reqLevel = 10,
    questLevel = 10,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Mathiel",
    objectives = "Speak with Mathiel in Warrior Class Quests.",
    rewards = "630 XP",
    tip = "",
    isForever = false,
  },
  [239] = {
    id = 239,
    title = "Westbrook Garrison Needs Help!",
    reqLevel = 6,
    questLevel = 10,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Marshal Dughan",
    objectives = "Go to the Westbrook Garrison and speak with Deputy Rainer.",
    rewards = "210 XP",
    tip = "The Garrison on our western border sends word of increasing gnoll and thief activity.  They're requesting we send more Stormwind soldiers... but we just don't have any to spare!\n\nIf you can help, we could use it.  Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done.\n\nThe Garrison is down the road to the west.  After you cross the bridge over the small brook it will be to the right.",
    isForever = false,
  },
  [36] = {
    id = 36,
    title = "Westfall Stew",
    reqLevel = 9,
    questLevel = 10,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Verna Furlbrow",
    objectives = "Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.",
    rewards = "420 XP",
    tip = "I never thought the day would come when I'd leave the farm.  But the fields are overrun with thieves and it's far too dangerous for us here now.  As soon as Farmer Furlbrow gets the wagon fixed, we'll be on our way.  \n \nMaybe you could do me a favor?  Let me scribble down my recipe for Westfall stew.  Please take it to Salma Saldean over on the farm yonder.  The Saldean's farm is just beyond the fork in the road.",
    isForever = false,
  },
  [760] = {
    id = 760,
    title = "Wildmane Cleansing",
    reqLevel = 4,
    questLevel = 10,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Mull Thunderhorn",
    objectives = "Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.",
    rewards = "1,050 XP",
    tip = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young $N.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the goblins' poisons!  Let clean water flow once again!",
    isForever = false,
  },
  [759] = {
    id = 759,
    title = "Wildmane Totem",
    reqLevel = 4,
    questLevel = 10,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Mull Thunderhorn",
    objectives = "Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.",
    rewards = "840 XP",
    tip = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.",
    isForever = false,
  },
  [826] = {
    id = 826,
    title = "Zalazane",
    reqLevel = 4,
    questLevel = 10,
    faction = "Horde",
    zone = "Durotar",
    npc = "Master Gadrin",
    objectives = "Defeat Zalazane.\n\nKill 8 Voodoo Trolls and 8 Hexed Trolls.\n\nBring Zalazane's Head to Gadrin.",
    rewards = "840 XP",
    tip = "The witchdoctor Zalazane dwells on the Echo Isles to the east.  They are the isles we once called home.\n\nFrom there he sends his trolls to the mainland, to hex our people and drag more of them under his sway.\n\nHe must be stopped.\n\nDefeat Zalazane and his minions -- former Darkspear trolls, now lost to us.  Bring me his head and I will know his reign of evil is over.",
    isForever = false,
  },
  [369] = {
    id = 369,
    title = "A New Plague",
    reqLevel = 6,
    questLevel = 11,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Apothecary Johaan",
    objectives = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.",
    rewards = "220 XP",
    tip = "While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders.\n\nBring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal ",
    isForever = false,
  },
  [492] = {
    id = 492,
    title = "A New Plague",
    reqLevel = 6,
    questLevel = 11,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Apothecary Johaan",
    objectives = "Bring Johaan's Special Drink to the Captured Mountaineer.",
    rewards = "880 XP",
    tip = "According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be \"properly\" dealt with.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.",
    isForever = false,
  },
  [417] = {
    id = 417,
    title = "A Pilot's Revenge",
    reqLevel = 8,
    questLevel = 11,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Object: A Dwarven Corpse",
    objectives = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot.",
    rewards = "660 XP",
    tip = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.",
    isForever = false,
  },
  [1821] = {
    id = 1821,
    title = "Agamand Heirlooms",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Coleman Farthing",
    objectives = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.",
    rewards = "660 XP • 3s",
    tip = "The Agamand family were my employers in life, and they were the cause of my death!  It is fitting that the Agamands are now mindless minions of the Lich King.\n\nNow I would have their last vestiges of honor.  Go into their family crypt and rob them of their family heirlooms: a sword, an axe, a dagger and a mace.  Bring them to me!\n\nThe Agamand family crypt is at the north end of the Agamand mills, protected by lurking scourge and dead Agamands.",
    isForever = false,
  },
  [422] = {
    id = 422,
    title = "Arugal's Folly",
    reqLevel = 9,
    questLevel = 11,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Dalar Dawnweaver",
    objectives = "Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher.",
    rewards = "880 XP",
    tip = "How Arugal gained acceptance within the Kirin Tor is beyond me.  His spell-casting knowledge seemed as transparent as a blown glass bauble.\n\nWhat's important now is learning exactly what magic Arugal used so that I can turn it against him and secure Silverpine Forest for the Dark Lady.\n\nArugal first stayed at the wheat farm just north of the bridge.  One of the Deathstalkers reported seeing some spellbooks but could not secure them.  Retrieve for me the spell labeled Remedy of Arugal from those ",
    isForever = false,
  },
  [1524] = {
    id = 1524,
    title = "Call of Fire",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Kranal Fiss",
    objectives = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.",
    rewards = "660 XP",
    tip = "You are powerful enough to wield the totem of fire, but that does not mean you are ready.\n\nAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.\n\nTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of",
    isForever = false,
  },
  [1501] = {
    id = 1501,
    title = "Creature of the Void",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Gan'rul Bloodeye",
    objectives = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.",
    rewards = "880 XP",
    tip = "So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief.\n\nIt is time that you learned a new summoning spell.\n\nFirst, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker.",
    isForever = false,
  },
  [934] = {
    id = 934,
    title = "Crown of the Earth",
    reqLevel = 1,
    questLevel = 11,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Corithras Moonrage",
    objectives = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.",
    rewards = "660 XP",
    tip = "All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.\n\nHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.",
    isForever = false,
  },
  [935] = {
    id = 935,
    title = "Crown of the Earth",
    reqLevel = 1,
    questLevel = 11,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Corithras Moonrage",
    objectives = "Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus.",
    rewards = "1,100 XP",
    tip = "Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw. Strange beasts have been reported arising from the very ground of the tree, and crazed furbolgs attack passing travelers.\n\nI can only hope that the solution the Arch Druid is looking for will be found quickly. I will pour all the phials you brought into this vessel, for you to deliver to Darnassus.\n\nBring it to Fandral Staghelm, you will find him in the druid grove.",
    isForever = false,
  },
  [7383] = {
    id = 7383,
    title = "Crown of the Earth",
    reqLevel = 1,
    questLevel = 11,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Corithras Moonrage",
    objectives = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.",
    rewards = "660 XP",
    tip = "All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.\n\nHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.",
    isForever = false,
  },
  [354] = {
    id = 354,
    title = "Deaths in the Family",
    reqLevel = 7,
    questLevel = 11,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Coleman Farthing",
    objectives = "Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.",
    rewards = "880 XP • 4s",
    tip = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the Plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the Plague.  Serve me by bringing me their rem",
    isForever = false,
  },
  [435] = {
    id = 435,
    title = "Escorting Erland",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Deathstalker Erland",
    objectives = "Escort Erland through the wolves, to Rane Yorick.",
    rewards = "880 XP",
    tip = "The wolves outside won't leave, and they eye me evilly every time I step foot out that door.  They must be incredibly hungry to think I'm worth eating.\n\nI have to report to my teammate, the Deathstalker Rane Yorick.  And to get to Rane, I'll need help against those wolves.\n\nPlease escort me!  And there are a lot of wolves out there, so we'll have a better chance if you have friends who can help...",
    isForever = false,
  },
  [952] = {
    id = 952,
    title = "Grove of the Ancients",
    reqLevel = 6,
    questLevel = 11,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Arch Druid Fandral Staghelm",
    objectives = "Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine.",
    rewards = "880 XP",
    tip = "If you had enough time to run messages for the Oracle Tree, then I'm sure that I can press you into service to deliver a message to the Grove of the Ancients in Darkshore, due south of Auberdine.\n\nYou will most likely have to secure transport on a hippogryph, but I have faith enough in you that you can manage that. Take this to Onu, the Ancient of Lore. He has been awaiting word from me, even as I waited for news from the Oracle Glade.",
    isForever = false,
  },
  [1822] = {
    id = 1822,
    title = "Heirloom Weapon",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Coleman Farthing",
    objectives = "Speak with Coleman Farthing in Warrior Class Quests.",
    rewards = "880 XP",
    tip = "",
    isForever = false,
  },
  [1681] = {
    id = 1681,
    title = "Ironband's Compound",
    reqLevel = 10,
    questLevel = 11,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Tormus Deepforge",
    objectives = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.",
    rewards = "660 XP",
    tip = "My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best.\n\nBut one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone!\n\nEnter Ironband's compound, $N, and avenge my master's death.  And bring me the load of umbral ore that caused it.",
    isForever = false,
  },
  [816] = {
    id = 816,
    title = "Lost But Not Forgotten",
    reqLevel = 8,
    questLevel = 11,
    faction = "Horde",
    zone = "Durotar",
    npc = "Misha Tor'kren",
    objectives = "Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.",
    rewards = "880 XP",
    tip = "$N, please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River. I fear the worst.\n\nAs strong as he was, his stubborn pride has always drawn him into trouble. I warned him that the crocolisks were powerful and vicious. He grew angry and stormed off.\n\nIf you can't find him, at least bring me a sign of his fate... even if you have to open up the stomach of every crocolisk along the Southfury's b",
    isForever = false,
  },
  [744] = {
    id = 744,
    title = "Preparation for Ceremony",
    reqLevel = 7,
    questLevel = 11,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Eyahn Eagletalon",
    objectives = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.",
    rewards = "880 XP",
    tip = "$N, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.",
    isForever = false,
  },
  [416] = {
    id = 416,
    title = "Rat Catching",
    reqLevel = 10,
    questLevel = 11,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Kadrell",
    objectives = "Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar.",
    rewards = "880 XP • 4s",
    tip = "We have a real infestation problem to the west.  Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!\n\nWe want them eliminated.  Hunt them, bring me their ears and earn their bounty.\n\nYou can find tunnel rat kobolds and their dens west of Thelsamar, littered along the mountainside.",
    isForever = false,
  },
  [356] = {
    id = 356,
    title = "Rear Guard Patrol",
    reqLevel = 6,
    questLevel = 11,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Deathguard Linnea",
    objectives = "Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.",
    rewards = "660 XP • 3s",
    tip = "The defenders on The Bulwark protecting Tirisfal from the Plaguelands are on constant alert.  But sometimes Scourge will slip past them.\n\nOur success at the Bulwark depends on a one-front battle - we cannot allow an attack from the rear, nor can we allow our defenders' supply line to be cut.\n\nAssist the Bulwark.  Patrol east and slay any Scourge you find.  Spend particular effort at the Balnir Farmstead to the east.  It has become a haven for interloping Scourge.",
    isForever = false,
  },
  [430] = {
    id = 430,
    title = "Return to Quinn",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Apothecary Renferrel",
    objectives = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.",
    rewards = "660 XP",
    tip = "Here is the potion to aid in Quinn Yorick's recovery.\n\nNow if you will excuse me, I have very important work to continue...",
    isForever = false,
  },
  [835] = {
    id = 835,
    title = "Securing the Lines",
    reqLevel = 7,
    questLevel = 11,
    faction = "Horde",
    zone = "Durotar",
    npc = "Rezlak",
    objectives = "Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine.",
    rewards = "880 XP",
    tip = "Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\"\n\nI can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Drygulch Ravine lies through the eastern part of Razorwind Canyon. If we kill all the harpies there, the routes will be safe.\n\nOf course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" So, going to help me out, $",
    isForever = false,
  },
  [940] = {
    id = 940,
    title = "Teldrassil",
    reqLevel = 6,
    questLevel = 11,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Sentinel Arynia Cloudsbreak",
    objectives = "Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus.",
    rewards = "440 XP",
    tip = "The forest whispers of your feats of valor, $n. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him.\n\nDeliver this to him and know that the forest will see you safely along its paths to the forest of stone.",
    isForever = false,
  },
  [1504] = {
    id = 1504,
    title = "The Binding",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Gan'rul Bloodeye",
    objectives = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.",
    rewards = "660 XP",
    tip = "Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker.\n\nYou must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will.",
    isForever = false,
  },
  [449] = {
    id = 449,
    title = "The Deathstalkers' Report",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Rane Yorick",
    objectives = "Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.",
    rewards = "440 XP • 2s",
    tip = "Although Quinn's wounds are mending, I want to get our report to High Executor Hadrec as quickly as possible.  It has information that is vital to the Forsaken's occupation of Silverpine.",
    isForever = false,
  },
  [937] = {
    id = 937,
    title = "The Enchanted Glade",
    reqLevel = 6,
    questLevel = 11,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Sentinel Arynia Cloudsbreak",
    objectives = "Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.",
    rewards = "440 XP",
    tip = "I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back.\n\nWhen the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies.\n\nIf you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.",
    isForever = false,
  },
  [433] = {
    id = 433,
    title = "The Public Servant",
    reqLevel = 6,
    questLevel = 11,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Senator Mehr Stonehallow",
    objectives = "Kill 10 Rockjaw Bonesnappers for Senator Mehr Stonehallow at the Gol'Bolar quarry.",
    rewards = "660 XP • 3s",
    tip = "As a member of the Senate and the Explorers' League, I've taken it upon myself to take care of this part of the trogg infestation that has gripped our lands.\n\nThey've certainly made a mess of Gol'Bolar quarry, and for no reason. As we dug deep into the earth, they poured out, destroying our equipment and driving the miners out. There's not much for us to do but to exterminate the lot of them, rebuild, then get back to work.\n\nIf you help me with the troggs, I'll gladly recompense you for your tim",
    isForever = false,
  },
  [418] = {
    id = 418,
    title = "Thelsamar Blood Sausages",
    reqLevel = 7,
    questLevel = 11,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Vidra Hearthstove",
    objectives = "Bring 3 pieces of Bear Meat, 3 Boar Intestines, and 3 Spider Ichor to Vidra Hearthstove in Thelsamar.",
    rewards = "880 XP • 4s",
    tip = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after  a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy $c, you'll be any exception.\n\nI'll need bear meat, boar intestines for the casings, and spider ichor for spice. You get me some of those, and leave the cooking to Vidra!",
    isForever = false,
  },
  [1680] = {
    id = 1680,
    title = "Tormus Deepforge",
    reqLevel = 10,
    questLevel = 11,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Muren Stormpike",
    objectives = "Speak with Tormus Deepforge.",
    rewards = "90 XP",
    tip = "Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like.\n\nYou'll find Tormus here in Ironforge, at the Great Forge.",
    isForever = false,
  },
  [1678] = {
    id = 1678,
    title = "Vejrek",
    reqLevel = 10,
    questLevel = 11,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Muren Stormpike",
    objectives = "Bring Vejrek's Head to Muren Stormpike in Ironforge.",
    rewards = "1,100 XP",
    tip = "If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes.\n\nVejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold\n\nBring me Vejrek's head and I'll know you have mettle.",
    isForever = false,
  },
  [176] = {
    id = 176,
    title = "Wanted:  \"Hogger\"",
    reqLevel = 5,
    questLevel = 11,
    faction = "Alliance",
    zone = "Elwynn Forest",
    npc = "Object: Wanted Poster",
    objectives = "Slay the gnoll Hogger and bring his Huge Gnoll Claw to Marshal Dughan.",
    rewards = "880 XP",
    tip = "Wanted: Hogger\n\nA huge gnoll, Hogger, is prowling the woods in southwestern Elwynn.  He has overpowered all attempts at his capture.\n\nThe Stormwind Army has placed a generous bounty on the Gnoll.  To earn the reward, bounty hunters should bring proof of Hogger's demise to Marshal Dughan in Goldshire.",
    isForever = false,
  },
  [1492] = {
    id = 1492,
    title = "Wharfmaster Dizzywig",
    reqLevel = 9,
    questLevel = 11,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Apothecary Helbrim",
    objectives = "Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet.",
    rewards = "440 XP",
    tip = "I have need to send a crate of potions, reagents and other items to my associates in the Old World. Little time I have to actually see them to the dock at Ratchet, and the last caravan has already left.\n\nIf you could, please take this to Wharfmaster Dizzywig. He will ensure that it is placed on the next boat to Blackwater Cove.",
    isForever = false,
  },
  [429] = {
    id = 429,
    title = "Wild Hearts",
    reqLevel = 10,
    questLevel = 11,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Rane Yorick",
    objectives = "Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.",
    rewards = "440 XP",
    tip = "My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs.\n\nGather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion.\n\nYou can find plenty of worgs between here and Malden's Orchard to the east.",
    isForever = false,
  },
  [447] = {
    id = 447,
    title = "A Recipe For Death",
    reqLevel = 9,
    questLevel = 12,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Apothecary Renferrel",
    objectives = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.",
    rewards = "910 XP • 5s",
    tip = "Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.\n\nMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity",
    isForever = false,
  },
  [372] = {
    id = 372,
    title = "At War With The Scarlet Crusade",
    reqLevel = 5,
    questLevel = 12,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Executor Zygand",
    objectives = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.",
    rewards = "910 XP",
    tip = "Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew.\n\nI am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady.",
    isForever = false,
  },
  [954] = {
    id = 954,
    title = "Bashal'Aran",
    reqLevel = 7,
    questLevel = 12,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Thundris Windweaver",
    objectives = "Find the source of the strange blue aura in the ruins of Bashal'Aran.",
    rewards = "680 XP",
    tip = "The ruins of Bashal'Aran to the east are overrun with demonic minions. The sprites and satyrs that have taken up residence in the area feed upon the magical energies of the area, their powers growing from continued exposure.\n\nEven with that, I have noticed that there is one shrine they will not approach. On the western side of the ruins, atop a small bluff, a strange blue aura permeates... There must be an explanation to the demons' reluctance.\n\nI would like you to investigate it.",
    isForever = false,
  },
  [955] = {
    id = 955,
    title = "Bashal'Aran",
    reqLevel = 7,
    questLevel = 12,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Asterion",
    objectives = "Acquire 8 Grell Earrings for Asterion in Bashal'Aran.",
    rewards = "910 XP",
    tip = "If I were to relate the story of my life, I have no doubt it would surpass the limits of your patience. Let us say that mine has been a long and painful life, and this spectral form is perhaps the worst torment of all.\n\nI am held here by the means of magic. Though my words may seem disingenuous, I assure you I would be grateful beyond words if you would help me find the means of my imprisonment. A seal binds me, and by examining the earpieces of the sprites and grells, I may find a trace of it.",
    isForever = false,
  },
  [832] = {
    id = 832,
    title = "Burning Shadows",
    reqLevel = 4,
    questLevel = 12,
    faction = "Horde",
    zone = "Durotar",
    npc = "Item: Eye of Burning Shadow",
    objectives = "Take this eye to Neeru Fireblade.",
    rewards = "680 XP",
    tip = "<Words emanate from the pendant and into your mind.>\n\nGazz'uz?\n\nGazz'uz...report!\n\nThere is word of your discovery in Skull Rock.  You must prepare for an attack!\n\nGazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality.\n\nDo not test your skills against Neeru...\n\n...Gazz'uz, are you there...?",
    isForever = false,
  },
  [1001] = {
    id = 1001,
    title = "Buzzbox 411",
    reqLevel = 7,
    questLevel = 12,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Buzzbox 827",
    objectives = "Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411.",
    rewards = "1,150 XP • 10s",
    tip = "A tiny voice crackles from deep within the machine.\n\n\"Wizbang here! The next Buzzbox is north of Auberdine, on the beach\n\nSo, that Buzzbox is number 411 and it needs 3 Thresher Eyes for its repairs. They're just off the coast! The darkshore threshers... *Hic*... Sorry about that...\n\nJust like last time, when you give the Buzzbox the goods, it'll spit out your reward. *Hic*... What? No, I'm fine!\"",
    isForever = false,
  },
  [1525] = {
    id = 1525,
    title = "Call of Fire",
    reqLevel = 10,
    questLevel = 12,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Telf Joolam",
    objectives = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.",
    rewards = "910 XP",
    tip = "But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem.\n\nThe first step is to create a sapta and bind you to the flame.\n\nI can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens.\n\nThe second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor ",
    isForever = false,
  },
  [840] = {
    id = 840,
    title = "Conscript of the Horde",
    reqLevel = 10,
    questLevel = 12,
    faction = "Horde",
    zone = "Durotar",
    npc = "Takrin Pathseeker",
    objectives = "Follow the western road from Razor Hill to the Barrens over a bridge.\n\nStop at the orc outpost across the bridge.\n\nGive Kargal Battlescar at the Barrens outpost your recruitment letter.",
    rewards = "455 XP",
    tip = "Hmm, you look pretty strong.\n\nListen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.\n\nTake this recruitment letter to Kargal and see if he'll sign it.",
    isForever = false,
  },
  [842] = {
    id = 842,
    title = "Crossroads Conscription",
    reqLevel = 10,
    questLevel = 12,
    faction = "Horde",
    zone = "Durotar",
    npc = "Kargal Battlescar",
    objectives = "Follow the western road from Kargal's Far Watch Outpost.\n\nAt the T intersection, turn left and follow the road south. \n\nFind Sergra Darkthorn at the crossing of roads within the Crossroads.",
    rewards = "910 XP",
    tip = "Take this signed recruitment letter to the Crossroads.\n\nSergra Darkthorn, curse her hide, is in charge there. She's a nasty shaman who will talk your head in circles before she lets you do anything useful. Thrall is convinced she's something special, but I'm not so sure.\n\nYou'll just have to decide for yourself, pup...",
    isForever = false,
  },
  [806] = {
    id = 806,
    title = "Dark Storms",
    reqLevel = 4,
    questLevel = 12,
    faction = "Horde",
    zone = "Durotar",
    npc = "Orgnil Soulscar",
    objectives = "Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.",
    rewards = "910 XP",
    tip = "We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers!\n\nI have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos.\n\nFind and defeat Fizzle, and bring me his dead claw!",
    isForever = false,
  },
  [6661] = {
    id = 6661,
    title = "Deeprun Rat Roundup",
    reqLevel = 10,
    questLevel = 12,
    faction = "Alliance",
    zone = "Deeprun Tram",
    npc = "Monty",
    objectives = "Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished.",
    rewards = "910 XP",
    tip = "Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck.\n\nWhat do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world!\n\nJust capture five of the little buggers and bring em back here. We needs em alive.\n\nArrrrr...",
    isForever = false,
  },
  [871] = {
    id = 871,
    title = "Disrupt the Attacks",
    reqLevel = 9,
    questLevel = 12,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Thork",
    objectives = "Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads.",
    rewards = "910 XP",
    tip = "All the quilboars are our enemies, $N. Some just prove to be more of a nuisance than others.\n\nThe Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.\n\nStart in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.",
    isForever = false,
  },
  [2178] = {
    id = 2178,
    title = "Easy Strider Living",
    reqLevel = 9,
    questLevel = 12,
    faction = "Alliance",
    zone = "Cooking",
    npc = "Alanndarian Nightsong",
    objectives = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.",
    rewards = "910 XP",
    tip = "Do you smell that delicious aroma? It's my secret recipe, $N--fresh strider stew. Delicious!\n\nPerhaps you would be interested in learning the recipe?\n\nBefore I teach you the recipe, you will need to prove that you can handle the beasts.\n\nNow, I don't expect you to go out and tame one and ride it back to me, but if you can kill a few and bring back some of their succulent meat, I may be persuaded to show you the ways of strider stew.",
    isForever = false,
  },
  [1580] = {
    id = 1580,
    title = "Electropellers",
    reqLevel = 10,
    questLevel = 12,
    faction = "Alliance",
    zone = "Fishing",
    npc = "Wizbang Cranktoggle",
    objectives = "Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.",
    rewards = "910 XP • 5s",
    tip = "We know you're lucky, but... just how lucky are you, $N?\n\nOne night I was wandering the roads of Darkshore.  I was looking for a good river or lake to try my new self-propelled, exploding duck decoy and I think I was a little tipsy... because I passed out and awoke hours later in Auberdine.  My hair was singed and my bag of electropellers was gone!  I must have dropped them in the water!\n\nI need those electropellers!  Maybe you can fish them out of some lake or stream in Darkshore...",
    isForever = false,
  },
  [1579] = {
    id = 1579,
    title = "Gaffer Jacks",
    reqLevel = 10,
    questLevel = 12,
    faction = "Alliance",
    zone = "Fishing",
    npc = "Wizbang Cranktoggle",
    objectives = "Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.",
    rewards = "455 XP • 2s 50c",
    tip = "I came to Auberdine because of the quiet.  I want to invent my inventions where it's quiet, because after a night of drinking I don't like all the noise of Ironforge!\n\nSo I took a ship to Auberdine and had a little too much to drink on the way.  I dropped my box of gaffer jacks overboard!  I need my gaffer jacks!\n\nI don't know exactly where I dropped them, but if you fish for them in the ocean you might get lucky...",
    isForever = false,
  },
  [22] = {
    id = 22,
    title = "Goretusk Liver Pie",
    reqLevel = 9,
    questLevel = 12,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Salma Saldean",
    objectives = "Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie.",
    rewards = "910 XP",
    tip = "The onions are peeled.  The garlic is minced.  The rosemary is crushed.  The crust has been baked.  The dill weed is chopped.  The gravy is simmering.  Now all I need for my famous meat pie are 8 Goretusk Livers!",
    isForever = false,
  },
  [5726] = {
    id = 5726,
    title = "Hidden Enemies",
    reqLevel = 9,
    questLevel = 12,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Thrall",
    objectives = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.",
    rewards = "910 XP • 2s 50c",
    tip = "One thing I will not tolerate are traitors in our midst, $N. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to",
    isForever = false,
  },
  [5727] = {
    id = 5727,
    title = "Hidden Enemies",
    reqLevel = 9,
    questLevel = 12,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Thrall",
    objectives = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.",
    rewards = "455 XP",
    tip = "Now let us see if this insignia you found is worth the effort.\n\nThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.\n\nTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.",
    isForever = false,
  },
  [224] = {
    id = 224,
    title = "In Defense of the King's Lands",
    reqLevel = 10,
    questLevel = 12,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Cobbleflint",
    objectives = "Mountaineer Cobbleflint of the southern guard tower wants you to kill 10 Stonesplinter Troggs and 10 Stonesplinter Scouts.",
    rewards = "910 XP • 5s",
    tip = "We need to protect the Loch, $N!  With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front.  Troggs are tunneling up from every crevice!  The Trogg infestation poses the largest threat to Ironforge.  These disgusting mutants must be destroyed.\n\nWe need you, brave adventurer, to venture forth and lay waste to the Trogg threat.  Slay 10 Stonesplinter Troggs and 10 Stonesplinter Scouts and report back.",
    isForever = false,
  },
  [425] = {
    id = 425,
    title = "Ivar the Foul",
    reqLevel = 10,
    questLevel = 12,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Rane Yorick",
    objectives = "Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.",
    rewards = "680 XP • 3s 50c",
    tip = "My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul.\n\nWe escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers.\n\nKill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop.",
    isForever = false,
  },
  [854] = {
    id = 854,
    title = "Journey to the Crossroads",
    reqLevel = 9,
    questLevel = 12,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Kirge Sternhorn",
    objectives = "Speak with Thork at the Crossroads in the Barrens.",
    rewards = "225 XP",
    tip = "I have foreseen your arrival, young $c. Though perhaps you are not so young anymore.\n\nI think that it is time for you to move deeper into this land. I can sense that you are destined for great things.\n\nIt is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.",
    isForever = false,
  },
  [428] = {
    id = 428,
    title = "Lost Deathstalkers",
    reqLevel = 10,
    questLevel = 12,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "High Executor Hadrec",
    objectives = "Find the Deathstalkers Quinn and Rane Yorick.",
    rewards = "225 XP",
    tip = "A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.\n\nThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.\n\nTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there.",
    isForever = false,
  },
  [828] = {
    id = 828,
    title = "Margoz",
    reqLevel = 4,
    questLevel = 12,
    faction = "Horde",
    zone = "Durotar",
    npc = "Orgnil Soulscar",
    objectives = "Speak with Margoz.",
    rewards = "90 XP",
    tip = "One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the northeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, $N, I still want you to crush those cultists!",
    isForever = false,
  },
  [6662] = {
    id = 6662,
    title = "Me Brother, Nipsy",
    reqLevel = 10,
    questLevel = 12,
    faction = "Alliance",
    zone = "Deeprun Tram",
    npc = "Monty",
    objectives = "Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.",
    rewards = "90 XP • 5s",
    tip = "Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on!\n\nYe have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.",
    isForever = false,
  },
  [938] = {
    id = 938,
    title = "Mist",
    reqLevel = 7,
    questLevel = 12,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Mist",
    objectives = "Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.",
    rewards = "910 XP",
    tip = "The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach.\n\nShe raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.",
    isForever = false,
  },
  [829] = {
    id = 829,
    title = "Neeru Fireblade",
    reqLevel = 4,
    questLevel = 12,
    faction = "Horde",
    zone = "Durotar",
    npc = "Margoz",
    objectives = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.",
    rewards = "455 XP",
    tip = "The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Neeru in Orgrimmar in the Cleft of Shadow.",
    isForever = false,
  },
  [844] = {
    id = 844,
    title = "Plainstrider Menace",
    reqLevel = 10,
    questLevel = 12,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Sergra Darkthorn",
    objectives = "Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.",
    rewards = "910 XP • 5s",
    tip = "Your first prey will be easy.\n\nThe plainstriders to the east have been harassing our food supplies and have become a nuisance.\n\nPut down the plainstriders and return to me with their beaks.",
    isForever = false,
  },
  [941] = {
    id = 941,
    title = "Planting the Heart",
    reqLevel = 9,
    questLevel = 12,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Denalan",
    objectives = "Plant the Tainted Heart in Denalan's Planter.",
    rewards = "910 XP",
    tip = "I have removed that foul moss from the heart, but it remains tainted...\n\nTry placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.",
    isForever = false,
  },
  [314] = {
    id = 314,
    title = "Protecting the Herd",
    reqLevel = 6,
    questLevel = 12,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Rudra Amberstill",
    objectives = "Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",
    rewards = "910 XP",
    tip = "We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With most of King Magni's army off in distant lands fighting with the Alliance, there is no one to keep Vagash at bay.\n\nPerhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.",
    isForever = false,
  },
  [409] = {
    id = 409,
    title = "Proving Allegiance",
    reqLevel = 5,
    questLevel = 12,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Gunther Arcanus",
    objectives = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her.\n\nReturn to Gunther on his island.",
    rewards = "680 XP",
    tip = "You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe.",
    isForever = false,
  },
  [2520] = {
    id = 2520,
    title = "Sathrah's Sacrifice",
    reqLevel = 5,
    questLevel = 12,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Priestess A'moora",
    objectives = "Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.",
    rewards = "910 XP",
    tip = "Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest.\n\nInside this temple, find the central fountain. There is where you may leave the sacrifice.  The holy waters will purify and cleanse the corruption that drove Sathrah mad.\n\nWhen you have completed this, return to me.",
    isForever = false,
  },
  [827] = {
    id = 827,
    title = "Skull Rock",
    reqLevel = 4,
    questLevel = 12,
    faction = "Horde",
    zone = "Durotar",
    npc = "Margoz",
    objectives = "Gather Searing Collars from the cultists in Skull Rock.\n\nBring them to Margoz at his camp.",
    rewards = "910 XP",
    tip = "$N.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.",
    isForever = false,
  },
  [3221] = {
    id = 3221,
    title = "Speak with Renferrel",
    reqLevel = 10,
    questLevel = 12,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "High Executor Hadrec",
    objectives = "Speak with Apothecary Renferrel at the Sepulcher.",
    rewards = "90 XP",
    tip = "While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons.  He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.",
    isForever = false,
  },
  [765] = {
    id = 765,
    title = "Supervisor Fizsprocket",
    reqLevel = 5,
    questLevel = 12,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Morin Cloudstalker",
    objectives = "Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village.",
    rewards = "910 XP",
    tip = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything usefu",
    isForever = false,
  },
  [1578] = {
    id = 1578,
    title = "Supplying the Front",
    reqLevel = 1,
    questLevel = 12,
    faction = "Alliance",
    zone = "Blacksmithing",
    npc = "Tormus Deepforge",
    objectives = "Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan",
    rewards = "910 XP",
    tip = "The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs.\n\nThat's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you.\n\nThorvald is in Loch Modan's southern guard tower.",
    isForever = false,
  },
  [2518] = {
    id = 2518,
    title = "Tears of the Moon",
    reqLevel = 5,
    questLevel = 12,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Priestess A'moora",
    objectives = "Priestess A'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah's Silvery Spinnerets.",
    rewards = "1,150 XP • 10s",
    tip = "Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept here in the temple.\n\nBut of late, Sathrah has descended into madness. Her future generations are now threatened as well.\n\nFind Lady Sathrah, $N, and end her suffering. She dwells along the northern borders of Teldrassil, near Wellspring Lake. Gather her silvery spinnerets and bring them back to me.",
    isForever = false,
  },
  [770] = {
    id = 770,
    title = "The Demon Scarred Cloak",
    reqLevel = 6,
    questLevel = 12,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Item: Demon Scarred Cloak",
    objectives = "Find someone who knows of Ghost Howl.",
    rewards = "910 XP",
    tip = "The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion.\n\nPerhaps someone in Bloodhoof Village should know of Ghost Howl's demise....",
    isForever = false,
  },
  [953] = {
    id = 953,
    title = "The Fall of Ameth'Aran",
    reqLevel = 9,
    questLevel = 12,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Sentinel Tysha Moonblade",
    objectives = "Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore.",
    rewards = "910 XP • 5s",
    tip = "To the east you will find the ruins of Ameth'Aran. It is now inhabited by the restless spirits of the Highborne that once dwelt within its walls, but once it was a place where the servants of Azshara freely practiced their powerful magics.\n\nI was sent to explore the ruins and came across two large tablets, scrawled with the stories of Ameth'Aran and its fall. While I read the runes, I was accosted by the spirits, and fled.\n\nPlease, if you can, venture to the ruins and decipher the tablets in my ",
    isForever = false,
  },
  [64] = {
    id = 64,
    title = "The Forgotten Heirloom",
    reqLevel = 9,
    questLevel = 12,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Farmer Furlbrow",
    objectives = "Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West.",
    rewards = "910 XP",
    tip = "It was horrible!  Verna woke me when she heard a ruckus in the fields.  The fields were full of hooligans.  We left in a rush and I forgot to pack my pocket watch.  Verna's pa gave me that watch on our wedding day and I feel just sick knowing those thieves have it.  I left the pocket watch in the wardrobe at the farmhouse.  Look for the field of pumpkins to the West -- you can't miss it.  If you bring it back to me, I'd sure be grateful!",
    isForever = false,
  },
  [927] = {
    id = 927,
    title = "The Moss-twined Heart",
    reqLevel = 5,
    questLevel = 12,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Item: Moss-twined Heart",
    objectives = "Bring the Moss-twined Heart to Denalan at Lake Al'Ameth.",
    rewards = "455 XP",
    tip = "The heart of Blackmoss the Fetid is covered with a dark, oily moss.  In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now.\n\nPerhaps Denalan will want to see this heart.",
    isForever = false,
  },
  [12] = {
