    reqLevel = 9,
    questLevel = 12,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Gryan Stoutmantle",
    objectives = "Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.",
    rewards = "910 XP • 5s",
    tip = "Pro-tip: Epic chain leading into 'You Are Rakh'likh' with blood-soaked Demon combat in Blasted Lands.",
    isForever = false,
  },
  [411] = {
