    title = "The Prodigal Lich Returns",
    reqLevel = 5,
    questLevel = 12,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Gunther Arcanus",
    objectives = "Bring the Nether Gem to Bethor Iceshard in the Undercity.",
    rewards = "910 XP • 5s",
