    isForever = false,
  },
  [1642] = {
    id = 1642,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 12,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Item: Tome of Divinity",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "90 XP",
    tip = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.",
    isForever = false,
  },
  [1643] = {
    id = 1643,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 12,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Duthorian Rall",
    objectives = "Search the Trade District of Stormwind for Stephanie Turner.",
    rewards = "455 XP",
    tip = "Your task then, $N, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light.",
    isForever = false,
  },
