  [267] = {
    id = 267,
    title = "The Trogg Threat",
    reqLevel = 10,
    questLevel = 12,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Captain Rugelfuss",
    objectives = "Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower.",
    rewards = "910 XP • 5s",
    tip = "$C, you may or may not be aware of the Trogg threat looming over Dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we are left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the Gate here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned Troggs lurking in the hills.  If you're up to the task, wage an assault on the Troggs.  Bring me back 8 Trogg Stone Teeth as ",
    isForever = false,
  },
  [2997] = {
    id = 2997,
    title = "Tome of Divinity",
    reqLevel = 12,
    questLevel = 12,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Azar Stronghammer",
    objectives = "Speak to Tiza Battleforge in Ironforge.",
    rewards = "90 XP",
    tip = "Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.\n\nYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, $N.",
    isForever = false,
  },
  [2998] = {
    id = 2998,
    title = "Tome of Divinity",
    reqLevel = 12,
    questLevel = 12,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Brother Wilhelm",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "225 XP",
    tip = "Greetings, $Gbrother:sister;. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.\n\nIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time.",
    isForever = false,
  },
  [2999] = {
    id = 2999,
    title = "Tome of Divinity",
    reqLevel = 12,
    questLevel = 12,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Brandur Ironhammer",
    objectives = "Speak to Tiza Battleforge in Ironforge",
    rewards = "90 XP",
    tip = "Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.",
    isForever = false,
  },
  [3000] = {
    id = 3000,
    title = "Tome of Divinity",
    reqLevel = 12,
    questLevel = 12,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Lord Grayson Shadowbreaker",
    objectives = "Speak to Tiza Battleforge in Ironforge.",
    rewards = "225 XP",
    tip = "Hello, $N. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.\n\nYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.",
    isForever = false,
  },
  [3681] = {
    id = 3681,
    title = "Tome of Divinity",
    reqLevel = 12,
    questLevel = 12,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Brandur Ironhammer",
    objectives = "Speak with Duthorian Rall in Stormwind.",
    rewards = "225 XP",
    tip = "Sorry to interrupt your travels, $r, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.\n\nIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.\n\nLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.",
    isForever = false,
  },
  [958] = {
    id = 958,
    title = "Tools of the Highborne",
    reqLevel = 9,
    questLevel = 12,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Thundris Windweaver",
    objectives = "Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine.",
    rewards = "910 XP • 5s",
    tip = "$C. A task I would ask of you.\n\nHave you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south. Once they were the home of many powerful Highborne, now they are a testament to the destruction their dabblings produced.\n\nI have been told by the Sentinels that the spirits of the Highborne persist, and that they wield their ancient magical implements. Those relics must be appropriated, so that we might destroy them.",
    isForever = false,
  },
  [312] = {
    id = 312,
    title = "Tundra MacGrann's Stolen Stash",
    reqLevel = 7,
    questLevel = 12,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Tundra MacGrann",
    objectives = "Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.",
    rewards = "910 XP",
    tip = "I had a month's worth of dried meats salted and locked away for the cold season.  Kept it locked so the bears wouldn't get it!  But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker.  He won't be able to smash through that Thorium though.  But I'll starve if I can't get my meats back.\n\nYou seem a bit more stealthy than me.  Perhaps you can retrieve my stash?  I'll never make it in and out of that cave fast enough with this bum leg of mine.",
    isForever = false,
  },
  [486] = {
    id = 486,
    title = "Ursal the Mauler",
    reqLevel = 4,
    questLevel = 12,
    faction = "Alliance",
    zone = "Teldrassil",
    npc = "Athridas Bearmantle",
    objectives = "Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar.",
    rewards = "1,150 XP",
    tip = "Now the time has come to save the Druids of the Talon. If we fail now, $N, they will be forever lost in sleep.\n\nI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.  Only then will the ritual be complete.\n\nIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed.  Travel to Gnarlpine Hold in the southwest and slay hi",
    isForever = false,
  },
  [809] = {
    id = 809,
    title = "Ak'Zeloth",
    reqLevel = 4,
    questLevel = 13,
    faction = "Horde",
    zone = "Durotar",
    npc = "Neeru Fireblade",
    objectives = "Speak with Ak'Zeloth in the Barrens.",
    rewards = "455 XP",
    tip = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!\n\nGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.",
    isForever = false,
  },
  [956] = {
    id = 956,
    title = "Bashal'Aran",
    reqLevel = 7,
    questLevel = 13,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Asterion",
    objectives = "Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran.",
    rewards = "910 XP",
    tip = "If the grells have come into close contact with the seal that binds my eternal prison, I suspect I know the cause. No doubt the seal has come into the possession of the satyr that lead them.\n\nI feel strongly that this must be true, $n. One of the satyr must surely possess it. If you can obtain it, you would bring me so close to passing the bars of my prison that tears would come to my eyes.",
    isForever = false,
  },
  [957] = {
    id = 957,
    title = "Bashal'Aran",
    reqLevel = 7,
    questLevel = 13,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Asterion",
    objectives = "Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.",
    rewards = "680 XP",
    tip = "It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color. In this flame this seal could be destroyed.\n\nBe wary in the ruins, $n...",
    isForever = false,
  },
  [4723] = {
    id = 4723,
    title = "Beached Sea Creature",
    reqLevel = 11,
    questLevel = 13,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Creature",
    objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "455 XP • 3s",
    tip = "The remains of a giant thresher - much larger than one you'd expect to find in Darkshore - lie beached on the coast of the Mist's Edge.  How this creature came to be here is unknown; the group of murlocs that now feast off the carcass of it seem to be much too weak, even in large numbers, to have brought down the beast. \n\nWhile some of it has been picked clean, enough of it remains to take a sample for Gwennyth Bly'Leggonde in Auberdine to study.",
    isForever = false,
  },
  [4722] = {
    id = 4722,
    title = "Beached Sea Turtle",
    reqLevel = 11,
    questLevel = 13,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Turtle",
    objectives = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "455 XP • 3s",
    tip = "You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been scavenged by the murlocs who have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.",
    isForever = false,
  },
  [1526] = {
    id = 1526,
    title = "Call of Fire",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Telf Joolam",
    objectives = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.",
    rewards = "1,150 XP",
    tip = "The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him.\n\nStrike him down swiftly, $N, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch.",
    isForever = false,
  },
  [1527] = {
    id = 1527,
    title = "Call of Fire",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Object: Brazier of the Dormant Flame",
    objectives = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.",
    rewards = "1,150 XP",
    tip = "Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.\n\nYou start off down the path back to the Barrens in search of Kranal Fiss.",
    isForever = false,
  },
  [1464] = {
    id = 1464,
    title = "Fire Sapta",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Telf Joolam",
    objectives = "Speak to Telf Joolam for another Fire Sapta.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [869] = {
    id = 869,
    title = "Raptor Thieves",
    reqLevel = 9,
    questLevel = 13,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Gazrog",
    objectives = "Bring 12 Raptor Heads to Gazrog at the Crossroads.",
    rewards = "910 XP • 6s",
    tip = "Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back.\n\nThe strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable!\n\nI don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again!\n\nHunt raptors in the Barrens.  Collect for me their heads!",
    isForever = false,
  },
  [1886] = {
    id = 1886,
    title = "The Deathstalkers",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Mennet Carkad",
    objectives = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.",
    rewards = "680 XP",
    tip = "If you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.\n\nI will not lie to you, $n, this task could mean your death.\n\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.\n\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.",
    isForever = false,
  },
  [1898] = {
    id = 1898,
    title = "The Deathstalkers",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Mennet Carkad",
    objectives = "Speak with Andron Gant in the Undercity.",
    rewards = "230 XP",
    tip = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.\n\nLord Varimathras suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.\n\nI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.",
    isForever = false,
  },
  [1899] = {
    id = 1899,
    title = "The Deathstalkers",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Andron Gant",
    objectives = "Bring Astor's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.",
    rewards = "230 XP",
    tip = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.",
    isForever = false,
  },
  [1978] = {
    id = 1978,
    title = "The Deathstalkers",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Mennet Carkad",
    objectives = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.",
    rewards = "910 XP",
    tip = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.",
    isForever = false,
  },
  [408] = {
    id = 408,
    title = "The Family Crypt",
    reqLevel = 7,
    questLevel = 13,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Magistrate Sevren",
    objectives = "Kill 8 Wailing Ancestors and 8 Rotting Ancestors.\n\nKill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.",
    rewards = "910 XP",
    tip = "The Agamand Mills area has become a foothold for the Scourge.  Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered.  With Necromancy he has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.\n\nAnd, bring me the skull of Captain Dargol.",
    isForever = false,
  },
  [870] = {
    id = 870,
    title = "The Forgotten Pools",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Tonga Runetotem",
    objectives = "Report back to Tonga Runetotem with your findings.",
    rewards = "680 XP",
    tip = "Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart.\n\nBut within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface.\n\nWe must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here.",
    isForever = false,
  },
  [1858] = {
    id = 1858,
    title = "The Shattered Hand",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Therzok",
    objectives = "Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar.",
    rewards = "455 XP",
    tip = "I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key.\n\nAs you didn't find it on Tazan's body, I can only assume that he left the key in the care of another... Ah, yes, that's right. He had an assistant named Gamon. A drunkard, you'll most likely find him at the tavern. Perhaps you could quietly relieve him of the key.",
    isForever = false,
  },
  [1963] = {
    id = 1963,
    title = "The Shattered Hand",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Therzok",
    objectives = "Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar.",
    rewards = "680 XP",
    tip = "The Warchief is too subtle in his methods. He is cautious to unleash the might of the Horde. Once we were stronger, mighty conquerors all. That pride we must regain, and the Shattered Hand will do so.\n\nWe build strength from the shadows and strike at the exposed, secretly laying our enemies low. A task you must complete for me, to prove your worth.\n\nThe troll Tazan trades with the pirates near Ratchet. He has information I must have. Kill him and bring me his satchel.",
    isForever = false,
  },
  [1644] = {
    id = 1644,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Stephanie Turner",
    objectives = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind.",
    rewards = "910 XP",
    tip = "Bless their hearts, most of them have no families because of the Scourge attacks in the last decade.\n\nMy husband John collects the materials for me to make the shirts and pants for the children, but I haven't even had time to do that. I've been too focused on keeping food on their plates, and a roof over their heads.\n\nWhat's that? You'd be willing to help? Oh, thank the Light, and thank you, $N.\n\nIf you could bring me some linen cloth so I can sew clothes for the kids, that would help me out so ",
    isForever = false,
  },
  [1648] = {
    id = 1648,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "John Turner",
    objectives = "Bring 10 Linen Cloth to John Turner in Ironforge.",
    rewards = "910 XP",
    tip = "My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help.\n\nThis trip's been agonizingly slow, and not very productive.\n\nIf I could just get some more linen for my wife to make some clothes, I could finally send a shipment home.",
    isForever = false,
  },
  [1778] = {
    id = 1778,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "John Turner",
    objectives = "Speak to Tiza Battleforge in Ironforge.",
    rewards = "230 XP",
    tip = "I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, $c.",
    isForever = false,
  },
  [1779] = {
    id = 1779,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Tiza Battleforge",
    objectives = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "I want you to take this, $N. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now I want you to prove just how adept you've become in both combat, and power.\n\nMy husband Muiredon returned recently from an encounter with some Dark Iron dwarves, and he barely escaped with his life--he's over there having his wounds healed by one of our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May the Light shine upon you.",
    isForever = false,
  },
  [1780] = {
    id = 1780,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Stephanie Turner",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "230 XP",
    tip = "I'll take these to the children this very day. Please be safe, good $c. It is not often $G men:women; of your character show their faces in the city, but you've proven that the paladins here in Stormwind shall never turn their backs on those in need.\n\nFarewell.",
    isForever = false,
  },
  [1781] = {
    id = 1781,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Duthorian Rall",
    objectives = "Take the Symbol of Life to Gazin Tenorm in Stormwind.",
    rewards = "Experience & Faction Reputation",
    tip = "Take this, $N. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now the time has come to see if you're powerful enough to focus one of the Light's greatest gifts.\n\nMy friend Gazin returned recently from an encounter with some Defias in Elwynn near Heroes' Vigil--he barely escaped with his life. He's near the altar having his wounds healed by our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May you bask in the Light's g",
    isForever = false,
  },
  [1783] = {
    id = 1783,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Muiredon Battleforge",
    objectives = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.",
    rewards = "680 XP",
    tip = "We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.\n\nNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.\n\nNarm needs help, an' I'll not rest till he gets it.\n\nC'n ya help, $N?",
    isForever = false,
  },
  [1784] = {
    id = 1784,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Narm Faulk",
    objectives = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge.",
    rewards = "680 XP",
    tip = "Before I fell in battle, Muiredon and I had almost defeated one of the Dark Iron spies near that small house. We witnessed their captain passing orders to them, and sought to kill him and take the orders.\n\nSome of the council in Ironforge do not yet believe the presence of Dark Iron dwarves exists in Dun Morogh. By attaining one of those scripts, we'll not only have proof of their movements, but possibly an idea of what they're planning.\n\nGet one of those scripts and take it back to Muiredon, $N",
    isForever = false,
  },
  [1785] = {
    id = 1785,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Muiredon Battleforge",
    objectives = "Speak to Tiza Battleforge in Ironforge.",
    rewards = "1,150 XP",
    tip = "I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.\n\nLight be witcha, mighty $c. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes.",
    isForever = false,
  },
  [1786] = {
    id = 1786,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Gazin Tenorm",
    objectives = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.",
    rewards = "680 XP",
    tip = "Henze and I had made it to Heroes' Vigil, an island in the middle of Stone Cairn Lake in northeastern Elwynn. We'd heard the Defias had infiltrated our borders and we wanted proof to take to the king's advisors.\n\nWe caught sight of a couple of the scum going over some documents, and we attacked. Unfortunately, we were quickly overwhelmed by more of the mages.\n\nHenze held them off for me while I escaped... the daft fool, going and being brave.\n\nHe's out there now, Henze is. Can you help us, $N?",
    isForever = false,
  },
  [1787] = {
    id = 1787,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Henze Faulk",
    objectives = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind.",
    rewards = "680 XP",
    tip = "We'll have time to talk more about the Symbol at a later time. What's important now is to get those papers we saw the Defias going over. If we can get our hands on them, we'll be able to prove the Defias have infiltrated Elwynn and hopefully gain some insight into what their plans are.\n\nI'm in no shape for battle as of now, $N. Do you think you're strong enough to get those papers from the Defias here on the island?\n\nIf you're able to get them, bring them back to Gazin and let him know I'm all r",
    isForever = false,
  },
  [1788] = {
    id = 1788,
    title = "The Tome of Divinity",
    reqLevel = 12,
    questLevel = 13,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Gazin Tenorm",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "1,150 XP",
    tip = "I'll take the script to the King's advisors after Duthorian's taken a look at them, but in the meantime, you should go speak to Duthorian now. He'll be wanting to pat you on the back for sure!\n\nThank you again, $N. I hope we meet again. You're surely an ally I'm proud to call friend.",
    isForever = false,
  },
  [845] = {
    id = 845,
    title = "The Zhevra",
    reqLevel = 10,
    questLevel = 13,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Sergra Darkthorn",
    objectives = "Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads.",
    rewards = "910 XP • 6s",
    tip = "The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting.\n\nHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.",
    isForever = false,
  },
  [3524] = {
    id = 3524,
    title = "Washed Ashore",
    reqLevel = 11,
    questLevel = 13,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Gwennyth Bly'Leggonde",
    objectives = "Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "680 XP • 4s",
    tip = "Majestic sea creatures are known to launch themselves at the Darkshore coastline, beached there until they die. Lately, these beasts have been washing ashore in ever-increasing numbers.  I've been sent here by the Temple of the Moon to investigate, but the presence of murlocs along the water has made my research difficult.\n\nThere is a giant creature washed ashore just south of Auberdine that is ringed by the foul Greymist murlocs.  Could you go there and retrieve bones from the creature for our ",
    isForever = false,
  },
  [38] = {
    id = 38,
    title = "Westfall Stew",
    reqLevel = 9,
    questLevel = 13,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Salma Saldean",
    objectives = "Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.",
    rewards = "910 XP",
    tip = "Help me make some Westfall Stew!  Come back with the following ingredients: \n \n 3 Stringy Vulture Meat \n 3 Goretusk Snouts \n 3 Murloc Eyes \n 3 Okra",
    isForever = false,
  },
  [423] = {
    id = 423,
    title = "Arugal's Folly",
    reqLevel = 9,
    questLevel = 14,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Dalar Dawnweaver",
    objectives = "Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher.",
    rewards = "980 XP • 6s",
    tip = "After examining Arugal's work my worst suspicions were confirmed.  The old hack was not qualified to clean chamber pots in Dalaran let alone represent the Kirin Tor in its most dire hour.  Fools!\n\nArugal used enchanted items to reinforce his weak magic.  I need to examine these items first hand.  Travel forth and slay Moonrage Gluttons and Moonrage Darksouls until you have collected enough of their enchanted shackles for my research.  The foul creatures have been seen to the north and east.",
    isForever = false,
  },
  [4812] = {
    id = 4812,
    title = "As Water Cascades",
    reqLevel = 12,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Sentinel Glynda Nal'Shea",
    objectives = "Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall.",
    rewards = "490 XP",
    tip = "Use this empty vial and fill up on some moonwell water here in Auberdine.  Such potent magic should provide a clue as to the composition of the crystal.  To do that, you'll pour the liquid over the crystal; it should take care of the rest.\n\nWhile I don't anticipate anything bad happening to you, I still want you to be careful.  Above us to the east is Felwood; if that crystal is tied to that place as I suspect it is, then it could prove to be very dangerous.",
    isForever = false,
  },
  [4728] = {
    id = 4728,
    title = "Beached Sea Creature",
    reqLevel = 12,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Creature",
    objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "490 XP • 3s",
    tip = "The corpse of what appears to be some sort of giant sea mammal lies partially gutted on the beach.  A wheelbarrow and various tools lie abandoned by this enormous beached sea creature, as though an attempt to study it had been made previously.  Though murlocs have scavenged this beast, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.",
    isForever = false,
  },
  [477] = {
    id = 477,
    title = "Border Crossings",
    reqLevel = 10,
    questLevel = 14,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Shadow Priest Allister",
    objectives = "Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.",
    rewards = "980 XP",
    tip = "As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran.\n\nI don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance.\n\nThey've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.",
    isForever = false,
  },
  [1002] = {
    id = 1002,
    title = "Buzzbox 323",
    reqLevel = 7,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Buzzbox 411",
    objectives = "Collect 6 Moonstalker Fangs and place them in Buzzbox 323.",
    rewards = "980 XP • 6s",
    tip = "The Buzzbox gives a burst of static as you hear Wizbang begin to speak.\n\n\"The next Buzzbox is number 323. Ish north of Auberdine but... where's the ale? Wha? Oh, ish on the road sho ya shouldn't have trouble finding it near the bridge.\"\n\nWizbang mumbles something incoherent before you hear a loud gulping sound.\n\n\"Thish one needs Moonstalker Fangs... 6 of 'em.\"",
    isForever = false,
  },
  [855] = {
    id = 855,
    title = "Centaur Bracers",
    reqLevel = 9,
    questLevel = 14,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Regthar Deathgate",
    objectives = "Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.",
    rewards = "1,250 XP",
    tip = "The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops.  And so, I have a bounty task for you.\n\nWhile in Kolkar territories, slay their warriors and collect centaur bracers.  Return when you have a heap of bracers and the Horde will reward you well.",
    isForever = false,
  },
  [6124] = {
    id = 6124,
    title = "Curing the Sick",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Alanndarian Nightsong",
    objectives = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.",
    rewards = "740 XP",
    tip = "The amount of salve made out of the reagents you brought me is good enough for ten doses, $N.  While I work with the village to try and make some more salve, I'd like for you to help us get a head start.  All around Darkshore are sickly deer; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend Auberdine's thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've g",
    isForever = false,
  },
  [6129] = {
    id = 6129,
    title = "Curing the Sick",
    reqLevel = 14,
    questLevel = 14,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Tonga Runetotem",
    objectives = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads.",
    rewards = "740 XP",
    tip = "I was able to make enough salve for ten doses of curing, $N.  While I work with local authorities to try and make some more salve, I'd like for you to help us get a head start.  All around the northern Barrens are sickly gazelles; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend our thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've given!",
    isForever = false,
  },
  [481] = {
    id = 481,
    title = "Dalar's Analysis",
    reqLevel = 10,
    questLevel = 14,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Shadow Priest Allister",
    objectives = "Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher.",
    rewards = "100 XP",
    tip = "Take the pendant to Dalar Dawnweaver, perhaps he can shed some light on the wizards' plans.",
    isForever = false,
  },
  [482] = {
    id = 482,
    title = "Dalaran's Intentions",
    reqLevel = 10,
    questLevel = 14,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Dalar Dawnweaver",
    objectives = "Speak with Shadow Priest Allister at the Sepulcher.",
    rewards = "100 XP",
    tip = "Of course! How could I have forgotten?\n\nAmbermill was one of the sites earmarked by the Kirin Tor, noted because it houses a dormant ley energy node. The wizards must be planning to reactivate the node and use its energies for some greater purpose.\n\nWe cannot allow this to happen...\n\nIt will take a great amount of power to activate the area's ley energies, we can stall them by taking the pendants away from the wizards.\n\nRelay this information to Allister, he will decide a course of action.",
    isForever = false,
  },
  [926] = {
    id = 926,
    title = "Flawed Power Stone",
    reqLevel = 1,
    questLevel = 14,
    faction = "Horde",
    zone = "Durotar",
    npc = "Object: Flawed Power Stone",
    objectives = "Inspect Flawed Power Stone in Durotar.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [6123] = {
    id = 6123,
    title = "Gathering the Cure",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Alanndarian Nightsong",
    objectives = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.",
    rewards = "740 XP",
    tip = "The water will serve as the base of the curative salve I'll make for the deer.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if we're unlucky and you aren't one then you'll need to find one to help us out.\n\nFinally for potency, I need some lunar fungus.  Finding lunar fungal blooms is easy enough; they're all over the place in caves just to the east of here.  Moonkin reside in the caves and they're irritable as of late, so be careful.",
    isForever = false,
  },
  [6128] = {
    id = 6128,
    title = "Gathering the Cure",
    reqLevel = 14,
    questLevel = 14,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Tonga Runetotem",
    objectives = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve.",
    rewards = "740 XP",
    tip = "The water will serve as the base of the curative salve I shall make for the gazelles.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if you are not familiar with this skill you'll need to find one to help us out.\n\nFinally for potency, I need kodo horns - mere chips and fragments will not suffice.  Kodos you can handle wander the northern part of the Barrens; bring some down for the greater good of the balance $N, and fetch the horns for me.",
    isForever = false,
  },
  [984] = {
    id = 984,
    title = "How Big a Threat?",
    reqLevel = 10,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Terenthis",
    objectives = "Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine.",
    rewards = "740 XP",
    tip = "Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse.\n\nI have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?",
    isForever = false,
  },
  [985] = {
    id = 985,
    title = "How Big a Threat?",
    reqLevel = 10,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Terenthis",
    objectives = "Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine.",
    rewards = "980 XP",
    tip = "You've already proven adept at scouting our enemy, $N. Do you have what it takes to fight them as well?\n\nNot all adventurers prefer straightforward combat to the art of stealth and evasion.\n\nIf you think you're up for the task, then the furbolg camp south of Auberdine is currently the biggest threat to our people. You'll find some of the Blackwood tribe there. Kill 8 pathfinders and 5 windtalkers, and return to me here.",
    isForever = false,
  },
  [6121] = {
    id = 6121,
    title = "Lessons Anew",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Mathrengyl Bearwalker",
    objectives = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.",
    rewards = "100 XP",
    tip = "You're now ready to learn about poison and the power we as druids have over it, $N.  Cenarius has blessed us with the ability to purge even the most foul of poisons with but a mere incantation.  This gift is not to be taken lightly... and to ensure you learn this lesson, you'll work to address the effects of poisonings as a layman would.\n\nTravel to Moonglade and speak with Dendrite Starblaze; he awaits your arrival to begin your lesson.",
    isForever = false,
  },
  [6126] = {
    id = 6126,
    title = "Lessons Anew",
    reqLevel = 14,
    questLevel = 14,
