    isForever = false,
  },
  [478] = {
    id = 478,
    title = "Maps and Runes",
    reqLevel = 10,
    questLevel = 14,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Object: Dalaran Crate",
    objectives = "Bring the strange pendant to Shadow Priest Allister at the Sepulcher.",
