  },
  [120] = {
    id = 120,
    title = "Messenger to Stormwind",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Magistrate Solomon",
    objectives = "Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind.  The judge wants you to return to him as soon as the delivery has been made.",
    rewards = "490 XP",
    tip = "These are trying times, $c.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad. \n\nNow make haste!",
    isForever = false,
  },
  [121] = {
    id = 121,
    title = "Messenger to Stormwind",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "General Marcus Jonathan",
    objectives = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.",
    rewards = "245 XP • 1s 50c",
    tip = "While I wait for a response from the King I want you to carry this letter to Magistrate Solomon. \n\nDismissed, $c!",
    isForever = false,
  },
  [143] = {
    id = 143,
    title = "Messenger to Westfall",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Magistrate Solomon",
    objectives = "Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.",
    rewards = "490 XP",
    tip = "Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall.\n\nTake this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves.",
    isForever = false,
  },
  [144] = {
    id = 144,
    title = "Messenger to Westfall",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Gryan Stoutmantle",
    objectives = "Return to Magistrate Solomon with Gryan Stoutmantle's response.",
    rewards = "245 XP • 1s 50c",
    tip = "Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia.\n\nTake this response to your master in Redridge, $c.  And let him know that my heart is heavy with the loss of good men.",
    isForever = false,
  },
  [2118] = {
    id = 2118,
    title = "Plagued Lands",
    reqLevel = 10,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Tharnariun Treetender",
    objectives = "Capture a living Rabid Thistle Bear and bring it back to Tharnariun.\n\nShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap.",
    rewards = "980 XP • 6s",
    tip = "A sickness spreads across the Darkshore, gripping the minds and bodies of all it touches.\n\nThe Thistle Bears have been hit the hardest by this plague. The once noble beasts are now an instrument of destruction - rabid and frenzied. I may have a cure for this ailment.\n\nTake this trap to the forest and lay it on the ground. Any Rabid Thistle Bear that crosses the light shall become docile for a short time. Once the bear is docile, it shall follow you. Lead it back here, $N.",
    isForever = false,
  },
  [151] = {
    id = 151,
    title = "Poor Old Blanchy",
    reqLevel = 9,
    questLevel = 14,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Verna Furlbrow",
    objectives = "Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats.",
    rewards = "1,250 XP",
    tip = "Poor Old Blanchy!  Such a tired beast after all the work we put her through. I fed her before we left the farm, but we weren't expecting the wagon to break on us. If you could bring her a few handfuls of oats from the fields, I'd be grateful.\n\nI bet you could find some around all of the farms in Westfall, if you can steer clear of those horrific machines that have taken over. There are several farms southwest of here.",
    isForever = false,
  },
  [6125] = {
    id = 6125,
    title = "Power over Poison",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
    rewards = "980 XP",
    tip = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Mathrengyl Bearwalker in Darnassus, $N.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto $g him : her;.\n\nFarewell, young druid.  We shall speak again.",
    isForever = false,
  },
  [6130] = {
    id = 6130,
    title = "Power over Poison",
    reqLevel = 14,
    questLevel = 14,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff.",
    rewards = "980 XP",
    tip = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Turak Runetotem in Thunder Bluff, $N.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto $g him : her;.\n\nFarewell, young druid.  We shall speak again.",
    isForever = false,
  },
  [776] = {
    id = 776,
    title = "Rites of the Earthmother",
    reqLevel = 3,
    questLevel = 14,
    faction = "Horde",
    zone = "Mulgore",
    npc = "Cairne Bloodhoof",
    objectives = "Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.",
    rewards = "1,250 XP",
    tip = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, $n. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.",
    isForever = false,
  },
  [894] = {
    id = 894,
    title = "Samophlange",
    reqLevel = 10,
    questLevel = 14,
    faction = "Both",
    zone = "The Barrens",
    npc = "Sputtervalve",
    objectives = "Access the control console at the Venture Company research site.",
    rewards = "740 XP",
    tip = "The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.",
    isForever = false,
  },
  [900] = {
    id = 900,
    title = "Samophlange",
    reqLevel = 10,
    questLevel = 14,
    faction = "Both",
    zone = "The Barrens",
    npc = "Object: Control Console",
    objectives = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.",
    rewards = "490 XP",
    tip = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.",
    isForever = false,
  },
  [901] = {
    id = 901,
    title = "Samophlange",
    reqLevel = 10,
    questLevel = 14,
    faction = "Both",
    zone = "The Barrens",
    npc = "Object: Control Console",
    objectives = "Get the Console Key from Tinkerer Sniggles to use on the control console.",
    rewards = "740 XP",
    tip = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.",
    isForever = false,
  },
  [887] = {
    id = 887,
    title = "Southsea Freebooters",
    reqLevel = 9,
    questLevel = 14,
    faction = "Both",
    zone = "The Barrens",
    npc = "Gazlowe",
    objectives = "Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet.",
    rewards = "740 XP • 5s",
    tip = "I sure wish Vice Admiral Grezzlik did a better job of keeping the seas safe for our trading vessels. With all the gold the trade princes have poured into the Trade Fleets, it ticks me off to see so many pirates running willy-nilly, raiding my ships and stealing my goods!\n\nI heard that the Southsea Freebooters have set up a camp just south of here. They've been a real thorn in my side and if Grezzlik won't take care of them, well, maybe you can help me get rid of them.",
    isForever = false,
  },
  [1338] = {
    id = 1338,
    title = "Stormpike's Order",
    reqLevel = 9,
    questLevel = 14,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Stormpike",
    objectives = "Bring Stormpike's Request to Furen Longbeard in Stormwind.",
    rewards = "980 XP • 6s",
    tip = "There is a dwarven armorsmith whose work I admire greatly.  His name is Furen Longbeard, and his skill is unmatched.  I need a new shield, and I must have one of his!\n\nThe problem is... Furen is far to the south, in the dwarven district within Stormwind.  In human lands!  I can't imagine why he would live there, so far from Ironforge.  The humans must pay him a king's ransom to keep him there!\n\nSo, if you want to travel and don't mind making some money, then will you send Furen my request for a ",
    isForever = false,
  },
  [5041] = {
    id = 5041,
    title = "Supplies for the Crossroads",
    reqLevel = 9,
    questLevel = 14,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Thork",
    objectives = "Find and return Crossroads' Supply Crates to Thork in the Barrens.",
    rewards = "980 XP • 6s",
    tip = "That attack on the caravan contained supplies we desperately needed.\n\nYou've been brave enough to take on the Razormane tribe so far, and I will ask you to do so again, but this time, I wonder if I could ask you to keep your eyes open for some of our lost supplies. You can probably find them throughout their camps, the quilboar getting fat off their dishonorable acts.\n\nThe people of the Crossroads would be in your debt.",
    isForever = false,
  },
  [437] = {
    id = 437,
    title = "The Dead Fields",
    reqLevel = 10,
    questLevel = 14,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "High Executor Hadrec",
    objectives = "Kill rot hide gnolls at the Dead Fields.\n\nWhen Nightlash appears, kill her.\n\nBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.",
    rewards = "980 XP • 6s",
    tip = "Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.\n\nWe want Nightlash destroyed.\n\nGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.\n\nHer essence will turn to dust.  Bring me that dust as proof.",
    isForever = false,
  },
  [924] = {
    id = 924,
    title = "The Demon Seed",
    reqLevel = 9,
    questLevel = 14,
    faction = "Horde",
    zone = "Durotar",
    npc = "Ak'Zeloth",
    objectives = "Grab a Flawed Power Stone.  Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.",
    rewards = "1,250 XP",
    tip = "The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire.\n\nI have prepared power stones that when placed near the Seed will disrupt its connection to the Legion.\n\nTake a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face.\n\nAnd hurry--the stone's power will consume itself in tim",
    isForever = false,
  },
  [1141] = {
    id = 1141,
    title = "The Family and the Fishing Pole",
    reqLevel = 10,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Gubber Blump",
    objectives = "Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.",
    rewards = "980 XP",
    tip = "I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish.\n\nThere's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too.\n\nSay, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.",
    isForever = false,
  },
  [4813] = {
    id = 4813,
    title = "The Fragments Within",
    reqLevel = 12,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Mysterious Red Crystal",
    objectives = "Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine.",
    rewards = "980 XP",
    tip = "The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone.  The jawbone appears to be from a humanoid, but it is unclear without breaking open the crystal - a feat that even the strongest of magic would find near impossible.\n\nWith the task at hand complete, all that remains is to report back to Sentinel Glynda Nal'Shea in Auberdine.",
    isForever = false,
  },
  [890] = {
    id = 890,
    title = "The Missing Shipment",
    reqLevel = 9,
    questLevel = 14,
    faction = "Both",
    zone = "The Barrens",
    npc = "Gazlowe",
    objectives = "Bring Gazlowe's Ledger to Wharfmaster Dizzywig.",
    rewards = "100 XP",
    tip = "I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge?\n\nHere, take my ledger down to Dizzywig and have him double check my inventory records against his logs.",
    isForever = false,
  },
  [892] = {
    id = 892,
    title = "The Missing Shipment",
    reqLevel = 9,
    questLevel = 14,
    faction = "Both",
    zone = "The Barrens",
    npc = "Wharfmaster Dizzywig",
    objectives = "Return Gazlowe's Ledger to Gazlowe in Ratchet.",
    rewards = "100 XP",
    tip = "Everything looks square from my records, $n. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies.\n\nNothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.",
    isForever = false,
  },
  [13] = {
    id = 13,
    title = "The People's Militia",
    reqLevel = 9,
    questLevel = 14,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Gryan Stoutmantle",
    objectives = "Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.",
    rewards = "980 XP • 6s",
    tip = "Pro-tip: Bring a full group with purges and kicks for the dreadlord's sleep and fire spells.",
    isForever = false,
  },
  [6122] = {
    id = 6122,
    title = "The Principal Source",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore.",
    rewards = "740 XP",
    tip = "The Cliffspring Falls in Darkshore serves as the principal source of drinking water for the region, and now I suspect it is the principal source of the poison that is harming the local fauna - deer specifically.  Use this sampler to draw some water from the mouth of the cave; be careful, as dangerous naga now reside in a cave by the falls.\n\nOnce filled, deliver it to Alanndarian Nightsong in Auberdine.  She is the one that requested our aid, and you will work with her to address this malady.",
    isForever = false,
  },
  [6127] = {
    id = 6127,
    title = "The Principal Source",
    reqLevel = 14,
    questLevel = 14,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens.",
    rewards = "740 XP",
    tip = "Dreadmist Peak to the northwest of the Crossroads is most likely a primary candidate as to the source of the spread of the poison.  Its airy peaks have pools of water that influence the weather patterns.  I suspect the water is now tainted by the demon-worshipping Burning Blade.\n\nUse this sampler to draw water from the pool at the very top of the peak.  Once filled, deliver it to Tonga Runetotem at the Crossroads.  He is the one that requested our aid, and you will work with him to address this ",
    isForever = false,
  },
  [4811] = {
    id = 4811,
    title = "The Red Crystal",
    reqLevel = 12,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Sentinel Glynda Nal'Shea",
    objectives = "Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range.  Report back what you find to Sentinel Glynda Nal'Shea in Auberdine.",
    rewards = "490 XP • 6s",
    tip = "Hostile moonkin roam in ever increasing numbers to our east.  They once were thought to be gentle, almost mystical creatures.  While some continue to hold reverence for them, the safety of Auberdine forces me to keep a more realistic view.\n\nI've received reports that moonkin are being drawn to a large red crystal along Darkshore's eastern mountain range.  No one has any idea what that crystal is, or even if it really exists.  I want you to locate it over there and report back to me what you find",
    isForever = false,
  },
  [730] = {
    id = 730,
    title = "Trouble In Darkshore?",
    reqLevel = 14,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Chief Archaeologist Greywhisker",
    objectives = "Travel to Auberdine and look for signs of the dwarven excavation team.",
    rewards = "490 XP",
    tip = "How nice it is to see a $c interested in the great archeological wonders of our world.\n\nOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.\n\nI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.\n\nTravel to Auberdine and look for a clue as to their whereabouts.",
    isForever = false,
  },
  [4681] = {
    id = 4681,
    title = "Washed Ashore",
    reqLevel = 11,
    questLevel = 14,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Gwennyth Bly'Leggonde",
    objectives = "Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine.",
    rewards = "980 XP",
    tip = "That beached creature is not an isolated incident here in Darkshore.  There are more along the coastline and even in the water.  I would like for you to investigate another one that we know of; this one was reported to be in the water due west of Auberdine, close to a sunken vessel.  Return to me with anything that you may recover that would aid our research.\n\nAlso, in your travels you may find other creatures.  By all means, if you should discover anything then please bring it to our attention!",
    isForever = false,
  },
  [3921] = {
    id = 3921,
    title = "Wenikee Boltbucket",
    reqLevel = 10,
    questLevel = 14,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Sputtervalve",
    objectives = "Bring the Broken Samophlange to Wenikee Boltbucket.",
    rewards = "490 XP",
    tip = "I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it!\n\nTake the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it.",
    isForever = false,
  },
  [129] = {
    id = 129,
    title = "A Free Lunch",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Darcy",
    objectives = "Bring Parker's lunch to Guard Parker.  He patrols the road leading to Darkshire.",
    rewards = "540 XP",
    tip = "Can you do me a favor?  I've prepared a lunch for Guard Parker, but he's out on patrol...he's a big, strong Stormwind guard who can defend himself, but it's much too dangerous out there for a townsperson like me.\n\nSo if you deliver his lunch for me, then come back here and I'll give you a free lunch!  Parker patrols the stretch of road leading to Duskwood.",
    isForever = false,
  },
  [450] = {
    id = 450,
    title = "A Recipe For Death",
    reqLevel = 9,
    questLevel = 15,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Master Apothecary Faranell",
    objectives = "Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.",
    rewards = "1,350 XP • 14s",
    tip = "You can be of further service to the Royal Apothecary Society, $N.\n\nWhen Arugal cast his wretched magic on the forest, he cursed one of our most promising members, Apothecary Berard.  Now a mindless servant of Arugal, Berard is useless to us.  But his findings might prove to be of worth.  He was studying an ancient plague that killed off all the aquatic life in Lake Lordamere ages ago.\n\nRetrieve Berard's Journal from his study in the Pyrewood Village Inn and take it to Apothecary Renferrel.",
    isForever = false,
  },
  [454] = {
    id = 454,
    title = "After the Ambush",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Huldar",
    objectives = "Speak with Miran.",
    rewards = "105 XP",
    tip = "We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones.\n\nI don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?",
    isForever = false,
  },
  [853] = {
    id = 853,
    title = "Apothecary Zamah",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Apothecary Helbrim",
    objectives = "Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.",
    rewards = "800 XP",
    tip = "I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods.\n\nShe is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff.\n\nDo hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.",
    isForever = false,
  },
  [99] = {
    id = 99,
    title = "Arugal's Folly",
    reqLevel = 9,
    questLevel = 15,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Dalar Dawnweaver",
    objectives = "Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.",
    rewards = "1,350 XP",
    tip = "As my understanding of Arugal's magic grows so does my disdain for the hapless fool.  I am close to completing my research on his so called remedy.\n\nMy knowledge will be complete when I learn what enchantment is causing the strange behavior going on in Pyrewood Village.  By day, the peasants appear to be Human.  But when the sun goes down the townsfolk turn into Moonrage Worgen.\n\nI need to draw energy from the enchanted shackles Arugal cast on them.  Bring to me six enchanted Pyrewood Shackles, ",
    isForever = false,
  },
  [424] = {
    id = 424,
    title = "Arugal's Folly",
    reqLevel = 9,
    questLevel = 15,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Dalar Dawnweaver",
    objectives = "Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher.",
    rewards = "1,050 XP • 7s",
    tip = "It will indeed take me longer than I had thought to uncover the dark secrets behind the enchantments Arugal was using.\n\nBut in the meantime I need you to take care of a slight problem our Darkstalkers have discovered.  It seems that Arugal let his magic spread to the Deep Elem Mine in the hills to the southeast.\n\nThe mine would prove to be quite a resource for Varimathras's advance.\n\nI want you to behead the tainted foreman of the mine, Grimson the Pale.  With his death, the mine shall be ours.",
    isForever = false,
  },
  [4725] = {
    id = 4725,
    title = "Beached Sea Turtle",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Turtle",
    objectives = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "540 XP • 3s 50c",
    tip = "More sea turtle remains lie beached along the coastline.  This particular set has an abandoned carriage attached to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Greymist murlocs now make the remains of this creature their home, feasting off the carrion.\n\nIn the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.",
    isForever = false,
  },
  [4727] = {
    id = 4727,
    title = "Beached Sea Turtle",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Turtle",
    objectives = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "540 XP • 3s 50c",
    tip = "The skeletal remains of a sea turtle lie in the sand of the northern Darkshore beaches.  The Greymist murlocs have either not found this carcass, or perhaps they have and are shying away from it for some unknown reason.  Regardless, there is enough of the turtle left to take a sample back to Gwennyth Bly'Leggonde in Auberdine for the Temple of the Moon to study.",
    isForever = false,
  },
  [2038] = {
    id = 2038,
    title = "Bingles' Missing Supplies",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Bingles Blastenheimer",
    objectives = "Find and return Bingles' supplies:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.",
    rewards = "1,050 XP • 7s",
    tip = "As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives. With no gyrocopter and no explosives, the movement has no chance!\n\nGet my tools back and find my Blastencapper explosives, $N. For Gnomeregan!",
    isForever = false,
  },
  [819] = {
    id = 819,
    title = "Chen's Empty Keg",
    reqLevel = 11,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Item: Chen's Empty Keg",
    objectives = "Find someone who knows about Chen's Empty Keg.",
    rewards = "1,050 XP",
    tip = "A small placard on one of the ends of the keg says,\n\n\"Chen Stormstout-\n\nMay your spirit be raised and always raise your spirits.\"",
    isForever = false,
  },
  [821] = {
    id = 821,
    title = "Chen's Empty Keg",
    reqLevel = 11,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Brewmaster Drohn",
    objectives = "Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.",
    rewards = "1,350 XP",
    tip = "Would you like a taste of Chen's namesake? Ahh, the stormstout is a mighty brew. Chen taught the recipe to my mentor, and my mentor passed it on to me. I'll need you to get me a few things, but I can tell you this: the kick is worth it.\n\nBring me 5 savannah lion tusks from any savannah lion, 5 plainstrider kidneys from any plainstrider, and 1 thunder lizard horn from any species of thunder lizard. That should do the trick nicely.\n\nYou can find these ingredients throughout the Barrens.",
    isForever = false,
  },
  [385] = {
    id = 385,
    title = "Crocolisk Hunting",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Marek Ironheart",
    objectives = "Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.",
    rewards = "1,050 XP",
    tip = "Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat.\n\nWe do some trade in this, but not a huge amount, as the crocolisks are ferocious and have entrenched themselves on the islands in the Loch. But don't let me dissuade you, it's quite an experience, wrestling with the jaws of the beasts.\n\nWhy, this one time...",
    isForever = false,
  },
  [131] = {
    id = 131,
    title = "Delivering Daffodils",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Martie Jainrose",
    objectives = "Give Darcy the Daffodil Bouquet.",
    rewards = "270 XP",
    tip = "Here is your bouquet.  I chose Daffodils for you.  They're my favorite!",
    isForever = false,
  },
  [116] = {
    id = 116,
    title = "Dry Times",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Barkeep Daniels",
    objectives = "Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.",
    rewards = "1,050 XP",
    tip = "I find myself in quite a pinch here, $N.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell.\n\nPerhaps you can go to work for me?\n\nI need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.",
    isForever = false,
  },
  [1097] = {
    id = 1097,
    title = "Elmore's Task",
    reqLevel = 9,
    questLevel = 15,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Smith Argus",
    objectives = "Speak with Grimand Elmore.",
    rewards = "105 XP",
    tip = "There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north.\n\nYou have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves.\n\nYou can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.",
    isForever = false,
  },
  [298] = {
    id = 298,
    title = "Excavation Progress Report",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Prospector Ironband",
    objectives = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.",
    rewards = "270 XP",
    tip = "I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar.\n\nIt's not a difficult task, but it must be done.",
    isForever = false,
  },
  [307] = {
    id = 307,
    title = "Filthy Paws",
    reqLevel = 9,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Stormpike",
    objectives = "Go to the Silver Stream Mine and collect 4 loads of Miners' Gear.\n\nReturn to Mountaineer Stormpike.",
    rewards = "1,350 XP",
    tip = "The Silver Stream Mine to the east ran dry long ago.  It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.",
    isForever = false,
  },
  [2039] = {
    id = 2039,
    title = "Find Bingles",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Gnoarn",
    objectives = "Find Bingles Blastenheimer in Loch Modan.",
    rewards = "270 XP",
    tip = "We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.\n\nHe was last seen flying over the Loch. Perhaps you can investigate, $N.",
    isForever = false,
  },
  [848] = {
    id = 848,
    title = "Fungal Spores",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Apothecary Helbrim",
    objectives = "Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads.",
    rewards = "1,050 XP • 7s",
    tip = "The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it.\n\nInvigorating, and altering.\n\nThere is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful.\n\nBring me these spores and you will earn our gratitude.",
    isForever = false,
  },
  [1921] = {
    id = 1921,
    title = "Gathering Materials",
    reqLevel = 15,
    questLevel = 15,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Jennea Cannon",
    objectives = "Bring 10 Linen and the 6 Charged Rift Gems to Wynne Larson in Stormwind.",
    rewards = "800 XP",
    tip = "You have served your fellow mages well, and now it is time to don your wizard's robe.  Wynne Larson can make your robe, but you must bring her the needed materials  \n\nThe robe will be made of linen which is easy to find, but you must also gain charged rift gems, and the only known location of the gems is in the Silver Stream Mine of Loch Modan, left in crates by the dwarven miners' league.\n\nGather the linen and the gems and bring them to Wynne Larson at the Larson Clothiers in the Mage District.",
    isForever = false,
  },
  [1961] = {
    id = 1961,
    title = "Gathering Materials",
    reqLevel = 15,
    questLevel = 15,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Anastasia Hartwell",
    objectives = "Bring 10 Linen and 6 Dalaran Mana Gems to Josef Gregorian.",
    rewards = "800 XP",
    tip = "It is time for you to don your first mage's robes, $N.  They are a sign of your station, and a testament to your worth.\n\nTo gain the robes, you must gather the mana gems from the Dalaran mages of Silverpine.  Their beliefs are similar to ours and so killing them is somewhat distasteful, but if they lack the strength to resist us, then they do not deserve their lives.\n\nBring the gems and a supply of linen to Josef Gregorian at the Magic Quarter's tailor shop.",
    isForever = false,
  },
  [867] = {
    id = 867,
    title = "Harpy Raiders",
    reqLevel = 12,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Darsok Swiftdagger",
    objectives = "Collect 8 Witchwing talons.\n\nReturn them to Darsok Swiftdagger at the Crossroads.",
    rewards = "1,050 XP • 7s",
    tip = "The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers.\n\nI've been snooping around their nests and figured out who leads who. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top.\n\nI'll start you off slow, take out Witchwing Harpies and Witchwing Roguefeathers in the Northwest and bring me 8 Witchwing talons. That should be a good sta",
    isForever = false,
  },
  [5729] = {
    id = 5729,
    title = "Hidden Enemies",
    reqLevel = 9,
    questLevel = 15,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Thrall",
    objectives = "Speak to Neeru Fireblade in Orgrimmar.",
    rewards = "105 XP",
    tip = "I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.\n\nReturn to the Cleft and speak to him again, but do not be too",
    isForever = false,
  },
  [3741] = {
    id = 3741,
    title = "Hilary's Necklace",
    reqLevel = 12,
    questLevel = 15,
    faction = "Both",
    zone = "Redridge Mountains",
    npc = "Shawn",
    objectives = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.",
    rewards = "1,350 XP",
    tip = "My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?",
    isForever = false,
  },
  [399] = {
    id = 399,
    title = "Humble Beginnings",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Baros Alexston",
    objectives = "Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind.",
    rewards = "1,050 XP • 7s",
    tip = "It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by thieves.\n\nI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.\n\nYou'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for ",
    isForever = false,
  },
  [237] = {
    id = 237,
    title = "In Defense of the King's Lands",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Gravelgaw",
    objectives = "Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him.",
    rewards = "1,050 XP • 7s",
    tip = "Mountaineer Cobbleflint had nothing but good things to say about you, $r.  For that reason I am going to entrust upon you a mission of utmost importance.  We need to keep pressure on the invading Trogg forces until our Dwarven brethren return from the Alliance front.\n\nSet forth into the southern hills and kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Your attacks will buy us some time.  Report back when your mission is complete.",
    isForever = false,
  },
  [263] = {
    id = 263,
    title = "In Defense of the King's Lands",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Wallbang",
    objectives = "Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.",
    rewards = "1,050 XP • 7s",
    tip = "The Mountaineers tell me you are quite brave and capable, $N.  We need a $r like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned $c here, let's see what you can do.\n\nGo out and kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.  Let's see if you live up to your reputation, Trogg-Slayer.",
    isForever = false,
  },
  [1941] = {
    id = 1941,
    title = "Manaweave Robe",
    reqLevel = 15,
    questLevel = 15,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Wynne Larson",
    objectives = "Speak with Wynne Larson in Mage Class Quests.",
    rewards = "1,050 XP",
    tip = "",
    isForever = false,
  },
  [8296] = {
