  [1339] = {
    id = 1339,
    title = "Mountaineer Stormpike's Task",
    reqLevel = 9,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Kadrell",
    objectives = "Speak with Mountaineer Stormpike.",
    rewards = "540 XP",
    tip = "I hear Mountaineer Stormpike is looking for a runner.  Someone to do a little traveling for him.  How about it?  Are you the $r for the job?\n\nIf so, then you'll find Stormpike at the top of the northern guard tower.",
    isForever = false,
  },
  [3301] = {
    id = 3301,
    title = "Mura Runetotem",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Tonga Runetotem",
    objectives = "Speak with Mura Runetotem in the Sepulcher.",
    rewards = "1,050 XP",
    tip = "My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies.  Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life.  Perhaps the strange life found here in the Barrens can help her work in Silverpine.\n\nTake a sample of the shells you gathered, and bring it to Mura in Silverpine.  She is staying at the Sepulcher.  With luck, studying the shell will give her the insight she needs to heal that dying place.",
    isForever = false,
  },
  [3922] = {
    id = 3922,
    title = "Nugget Slugs",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Wenikee Boltbucket",
    objectives = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.",
    rewards = "1,050 XP",
    tip = "I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.",
    isForever = false,
  },
  [5713] = {
    id = 5713,
    title = "One Shot. One Kill.",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Sentinel Aynasha",
    objectives = "Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale.",
    rewards = "1,050 XP • 14s",
    tip = "I was traveling to Auberdine with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready.\n\nI would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can.\n\nShould we survive, I will be able deliver my message to Auberdine, while you speak with Onaeya at Maestra's Post to inform her of this incident.",
    isForever = false,
  },
  [302] = {
    id = 302,
    title = "Powder to Ironband",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Prospector Stormpike",
    objectives = "Speak with Jern Hornhelm in Thelsamar.",
    rewards = "270 XP",
    tip = "If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband.\n\nAnd one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open.",
    isForever = false,
  },
  [309] = {
    id = 309,
    title = "Protecting the Shipment",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Miran",
    objectives = "Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.",
    rewards = "1,050 XP",
    tip = "Ready to go, $n?\n\nFirst, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me.\n\nI'll feel a lot better with you coming along.",
    isForever = false,
  },
  [903] = {
    id = 903,
    title = "Prowlers of the Barrens",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Sergra Darkthorn",
    objectives = "Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads.",
    rewards = "1,050 XP • 7s",
    tip = "Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads.\n\nBe wary as you hunt them, $n, or you may find yourself no longer the predator, but instead the prey.",
    isForever = false,
  },
  [452] = {
    id = 452,
    title = "Pyrewood Ambush",
    reqLevel = 12,
    questLevel = 15,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Deathstalker Faerleia",
    objectives = "Help Deathstalker Faerleia kill the Pyrewood Council.",
    rewards = "1,350 XP • 14s",
    tip = "You got here just in the nick of time, $N!\n\nThe Pyrewood Council will be returning any moment.  Arugal has other matters to tend to in the keep.  He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control.  But I believe that without the guidance of the Pyrewood Council, the sons of Arugal will turn against their master.\n\nI cannot handle them all by myself.  I need you to help me.  Together we can lay waste to the Council for Lady Sylvanas.",
    isForever = false,
  },
  [8295] = {
    id = 8295,
    title = "Quell the Silverwing Usurpers",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "- Warsong Gulch Mark of Honor",
    rewards = "Experience & Faction Reputation",
    tip = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.",
    isForever = false,
  },
  [153] = {
    id = 153,
    title = "Red Leather Bandanas",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Scout Galiaan",
    objectives = "Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.",
    rewards = "1,050 XP",
    tip = "The Defias Front is constantly shifting.  I've been following their movements for quite some time now.  On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear.\n\nBring me 15 of these Bandanas and I'll see to it you are rewarded.",
    isForever = false,
  },
  [1959] = {
    id = 1959,
    title = "Report to Anastasia",
    reqLevel = 15,
    questLevel = 15,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Thurston Xane",
    objectives = "Speak with Anastasia Hartwell.",
    rewards = "105 XP",
    tip = "The mages of the Undercity have noted a magical disturbance within the city, and have sent word for mages of the Horde to investigate.\n\nAnastasia Hartwell can tell you more.  Speak with her in the Magic Quarter in the Undercity.",
    isForever = false,
  },
  [301] = {
    id = 301,
    title = "Report to Ironforge",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Jern Hornhelm",
    objectives = "Take Ironband's Progress Report to Prospector Stormpike.",
    rewards = "540 XP • 1s 75c",
    tip = "We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.\n\nHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.\n\nYou'll find Stormpike in the Assembly of Explorers.",
    isForever = false,
  },
  [1919] = {
    id = 1919,
    title = "Report to Jennea",
    reqLevel = 15,
    questLevel = 15,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Zaldimar Wefhellt",
    objectives = "Speak with Jennea Cannon in Stormwind.",
    rewards = "105 XP",
    tip = "Your knowledge of the craft grows, young $N.  Are you now ready to begin your true lessons?  Are you ready to take your place in the secret war we wage?\n\nIf so, then speak with Jennea Cannon, in the wizard's sanctum in the mage district of Stormwind.  She has a task for you which will open your first window into the invisible world.",
    isForever = false,
  },
  [273] = {
    id = 273,
    title = "Resupplying the Excavation",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Jern Hornhelm",
    objectives = "Speak with Huldar.",
    rewards = "270 XP",
    tip = "It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch.\n\nShouldn't have a problem finding them unless they've already gotten there.",
    isForever = false,
  },
  [1358] = {
    id = 1358,
    title = "Sample for Helbrim",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "Undercity",
    npc = "Apothecary Zinge",
    objectives = "Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.",
    rewards = "1,050 XP",
    tip = "A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me.\n\nHelbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.",
    isForever = false,
  },
  [2041] = {
    id = 2041,
    title = "Speak with Shoni",
    reqLevel = 15,
    questLevel = 15,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Gnoarn",
    objectives = "Speak with Shoni the Shilent in Stormwind.",
    rewards = "270 XP",
    tip = "Perhaps... Perhaps you can help us in the battle for Gnomeregan.\n\nIn Stormwind you will find the commander of our underground assault crew, Shoni the Shilent. Shoni needs assistance with her gyrodrillmatic excavationators.\n\nYou will probably find her amongst the dwarves in Stormwind.\n\nGood luck, $N.",
    isForever = false,
  },
  [1962] = {
    id = 1962,
    title = "Spellfire Robes",
    reqLevel = 15,
    questLevel = 15,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Josef Gregorian",
    objectives = "Speak with Josef Gregorian in Mage Class Quests.",
    rewards = "1,050 XP",
    tip = "",
    isForever = false,
  },
  [353] = {
    id = 353,
    title = "Stormpike's Delivery",
    reqLevel = 9,
    questLevel = 15,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Grimand Elmore",
    objectives = "Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.",
    rewards = "1,050 XP • 7s",
    tip = "The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.\n\nThe weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him?\n\nMy last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.",
    isForever = false,
  },
  [8289] = {
    id = 8289,
    title = "Talismans of Merit",
    reqLevel = 10,
    questLevel = 15,
    faction = "Both",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "",
    rewards = "",
    tip = "",
    isForever = false,
  },
  [5723] = {
    id = 5723,
    title = "Testing an Enemy's Strength",
    reqLevel = 9,
    questLevel = 15,
    faction = "Horde",
    zone = "Ragefire Chasm",
    npc = "Rahauro",
    objectives = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.",
    rewards = "1,050 XP • 7s",
    tip = "Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.\n\nShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy th",
    isForever = false,
  },
  [4762] = {
    id = 4762,
    title = "The Cliffspring River",
    reqLevel = 11,
    questLevel = 15,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Thundris Windweaver",
    objectives = "Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.\n\nReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample.",
    rewards = "800 XP",
    tip = "The Cliffspring River has begun turning foul and corrupted.  It empties into the Mist's Edge, and I fear the wash will affect Auberdine soon.  I suspect the Blackwood furbolgs up-river are the cause of the taint, but I also suspect that they aren't the true root of it.\n\nTake this sampling tube and go to the mouth of the river to our north.  Proceed inland to the first waterfall and draw a sample from the pool there.  You'll see a bridge overhead.  Once you have a sample, return to me in Auberdin",
    isForever = false,
  },
  [872] = {
    id = 872,
    title = "The Disruption Ends",
    reqLevel = 9,
    questLevel = 15,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Thork",
    objectives = "Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.\n\nThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.",
    rewards = "1,050 XP",
    tip = "One of my scouts witnessed an attack on a caravan from Durotar, $N. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout. He was seen northeast of here, just south of the road from Durotar. If the threat is to be ended, then Kreenig must die.\n\nTo be sure the attacks cease, though, I say we add insult to their injury. Kill Kreenig along with more of their tribe, and return to me when you have his tusk.",
    isForever = false,
  },
