  [4761] = {
    id = 4761,
    title = "Thundris Windweaver",
    reqLevel = 11,
    questLevel = 15,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Terenthis",
    objectives = "Speak with Thundris Windweaver in Auberdine.",
    rewards = "105 XP",
    tip = "Your scouting of the furbolg camp is information that Thundris Windweaver should be made aware of.  He graciously serves as the elder of Auberdine, offering sage and just stewardship of the day to day affairs of the village.  Please - share with him your findings to date on the furbolg situation.\n\nI believe he has some ideas of his own on the reasons behind their corruption.  Perhaps you can work with him to enact a plan to restore the balance of nature here!",
    isForever = false,
  },
  [264] = {
    id = 264,
    title = "Until Death Do Us Part",
    reqLevel = 12,
    questLevel = 15,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Clarice Foster",
    objectives = "Place Clarice's Pendant on Yuriv's Tomb in Silverpine.",
    rewards = "540 XP",
    tip = "Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\"\n\nWell, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty!\n\nWell, witness what \"justice\" brings you, $N! He's dead and I'm bearing the very thing he was trying to stop!\n\nTake this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!",
    isForever = false,
  },
  [8290] = {
    id = 8290,
    title = "Vanquish the Invaders",
    reqLevel = 10,
    questLevel = 15,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "- Warsong Gulch Mark of Honor",
    rewards = "Experience & Faction Reputation",
    tip = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.",
    isForever = false,
  },
  [130] = {
    id = 130,
    title = "Visit the Herbalist",
    reqLevel = 12,
    questLevel = 15,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Guard Parker",
    objectives = "Speak with the Redridge Herbalist, Martie Jainrose.",
    rewards = "270 XP",
    tip = "Before you go back to Darcy, can you bring her some flowers for me?  You can get them at the herbalist shop back in Lakeshire, at the west end of town.\n\nBut when you get the flowers...don't tell the herbalist, Martie, whom they're from, or whom they're for...",
    isForever = false,
  },
  [1359] = {
    id = 1359,
    title = "Zinge's Delivery",
    reqLevel = 10,
    questLevel = 15,
    faction = "Horde",
    zone = "Undercity",
    npc = "Apothecary Renferrel",
    objectives = "Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.",
    rewards = "105 XP",
    tip = "The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat!\n\nIt's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.",
    isForever = false,
  },
  [257] = {
    id = 257,
    title = "A Hunter's Boast",
    reqLevel = 11,
    questLevel = 16,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Daryl the Youngling",
    objectives = "Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes.",
    rewards = "880 XP",
    tip = "Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it.\n\nA flock of buzzards has nested here in Loch Modan. Why don't you try to take down some of the beasts? Tell you what, if you meet my challenge in fifteen minutes, I'll give you my bow or gun.\n\n<He looks you over dismissively.>\n\nIt seems you haven't much to lose, anyways",
    isForever = false,
  },
  [26] = {
    id = 26,
    title = "A Lesson to Learn",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Mathrengyl Bearwalker",
    objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
    rewards = "115 XP",
    tip = "$N, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.",
    isForever = false,
  },
  [880] = {
    id = 880,
    title = "Altered Beings",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Tonga Runetotem",
    objectives = "Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.",
    rewards = "1,150 XP • 8s",
    tip = "Your findings are incredible, $N.  These oases hold properties that must come from an outside source.  Or perhaps an inside one.\n\nI want to know how these fissures are affecting the beasts who drink from the oases' water.\n\nHunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them.",
    isForever = false,
  },
  [479] = {
    id = 479,
    title = "Ambermill Investigations",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Shadow Priest Allister",
    objectives = "Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher.",
    rewards = "1,150 XP • 8s",
    tip = "Dalar is attempting to locate the source of the wizards' spellcasting. For now, we'll have to slow their progress in any way we can...\n\nThe conjurers, mages and protectors are no doubt carrying the pendants. Remove and retrieve them.\n\nTake the main road south and the eastern fork into Ambermill.",
    isForever = false,
  },
  [31] = {
    id = 31,
    title = "Aquatic Form",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.",
    rewards = "1,150 XP",
    tip = "You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Turak Runetotem, in Thunder Bluff.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.\n\nGoodbye, young druid.  We shall speak again.",
    isForever = false,
  },
  [5061] = {
