  [4730] = {
    id = 4730,
    title = "Beached Sea Creature",
    reqLevel = 12,
    questLevel = 16,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Creature",
    objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "580 XP • 4s",
    tip = "The half-devoured corpse of what might have been a giant sea mammal lies on the beach.  A band of murlocs, stronger than those found closer to Auberdine, have taken up residence around the fallen creature.  Enough of the creature remains that a suitable sample of its bones could be delivered to Gwennyth Bly'Leggonde in Auberdine.",
    isForever = false,
