  [1003] = {
    id = 1003,
    title = "Buzzbox 525",
    reqLevel = 7,
    questLevel = 16,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Buzzbox 323",
    objectives = "Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525.",
    rewards = "1,150 XP • 8s",
    tip = "Over the boiling noises and dripping sounds coming from the machine, you hear Wizbang's wavering voice call out.\n\n\"Nexsht onesh far south down the road. Shouldn't be hard to find... jusht off to the shide... near a fensh. I think I hid it in shum bushesh... Bushessh. Hehehe... Yesh, Buzzbox 525 takes grizzled scalps from thoshe grizzled thistle bears. Boy thash a mouthful. Grizzshled... Hehehe...\"\n\nYou hear more gulping sounds as the machine cuts out. Then, suddenly, it bursts back to life.\n\n\"4!",
    isForever = false,
  },
  [136] = {
    id = 136,
    title = "Captain Sander's Hidden Treasure",
    reqLevel = 10,
    questLevel = 16,
    faction = "Both",
    zone = "Westfall",
    npc = "Item: Captain Sander's Treasure Map",
    objectives = "Find Captain Sanders' footlocker and search it for the next clue.",
    rewards = "580 XP",
    tip = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.",
    isForever = false,
  },
  [138] = {
    id = 138,
    title = "Captain Sander's Hidden Treasure",
    reqLevel = 10,
    questLevel = 16,
    faction = "Both",
    zone = "Westfall",
    npc = "Object: Captain's Footlocker",
    objectives = "Find the old barrel near the ruined chimney and search it for your next clue.",
    rewards = "580 XP",
    tip = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.",
    isForever = false,
  },
  [139] = {
    id = 139,
    title = "Captain Sander's Hidden Treasure",
    reqLevel = 10,
    questLevel = 16,
    faction = "Both",
    zone = "Westfall",
    npc = "Object: Broken Barrel",
    objectives = "Search the empty jug next to the windmill for the next clue.",
    rewards = "580 XP",
    tip = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.",
    isForever = false,
  },
  [140] = {
    id = 140,
    title = "Captain Sander's Hidden Treasure",
    reqLevel = 10,
    questLevel = 16,
    faction = "Both",
    zone = "Westfall",
    npc = "Object: Old Jug",
    objectives = "Locate Captain Sanders' chest and open it for your reward.",
    rewards = "1,150 XP • 8s",
    tip = "Sure enough, deep within the Old Jug there is another clue to Sander's treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!",
    isForever = false,
  },
  [2138] = {
    id = 2138,
    title = "Cleansing of the Infected",
    reqLevel = 10,
    questLevel = 16,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Tharnariun Treetender",
    objectives = "Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.",
    rewards = "1,150 XP",
    tip = "As I had feared, the cure does not work.\n\nIt saddens me greatly to order the death of any of nature's beasts, but the sick and tainted thistle bears must be put down.\n\nReturn to the forest and destroy 20 rabid thistle bears, $N. It will most certainly not put a stop to the plague but it will slow down the damage the animals are doing to our forest and its inhabitants for a short time.",
    isForever = false,
  },
  [881] = {
    id = 881,
    title = "Echeyakee",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Sergra Darkthorn",
    objectives = "Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads.",
    rewards = "1,450 XP",
    tip = "Whitemist, Echeyakee in the Tauren tongue, is the king of the savannah cats.  He hunts with such stealth, they say he's like a thin, white mist on the earth.  And he kills so fast his prey have no time for fear, or pain.\n\nThe Tauren say he is both mercy and death.\n\nYou will learn if that's true, for I now set you on the path to hunt Echeyakee.  His lair is northeast of the Crossroads, among the bones of giant Kodo\n\nGo.  Blow this horn when you reach his lair.  Blow the horn, and he will come.",
    isForever = false,
  },
  [244] = {
    id = 244,
    title = "Encroaching Gnolls",
    reqLevel = 11,
    questLevel = 16,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Guard Parker",
    objectives = "Report to Deputy Feldon.",
    rewards = "290 XP • 2s",
    tip = "Hail, $c.  I am charged to patrol this stretch of road.  Although the road is safe for now, I've seen gnoll encampments to the north and east of here.\n\nLakeshire must know of the gathering gnoll force!  Report to Deputy Feldon in Lakeshire and tell him of the gnolls.  Do this, and I'm sure Feldon will offer you a scout's wage.\n\nFeldon's usually inspecting the area south of the bridge to Lakeshire.",
    isForever = false,
  },
  [2259] = {
    id = 2259,
    title = "Erion Shadewhisper",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Jannok Breezesong",
    objectives = "Contact Erion Shadewhisper in Darnassus.",
    rewards = "115 XP",
    tip = "Do not worry, $N, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!",
    isForever = false,
  },
  [2260] = {
    id = 2260,
    title = "Erion's Behest",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Erion Shadewhisper",
    objectives = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"",
    rewards = "580 XP",
    tip = "Word of your deeds has spread far and wide, $N. So far, in fact, that Stormwind Intelligence has asked for you by name.\n\nThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.\n\nA new world awaits you, $N. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.",
    isForever = false,
  },
  [1998] = {
    id = 1998,
    title = "Fenwick Thatros",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Mennet Carkad",
    objectives = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.",
    rewards = "880 XP",
    tip = "Lord Varimathras has just sent me a missive about a threat to the Forsaken that must be immediately removed. His name is Fenwick Thatros, one whom Lord Varimathras believes is a leader of the undead that have taken root in Silverpine Forest.\n\nYour name came to mind immediately, $n. I have faith enough in your abilities that you will carry out this mission flawlessly.\n\nThe latest reports from the Deathstalkers in Silverpine indicate that Thatros can be found near the decrepit dock on Lordamere.",
    isForever = false,
  },
  [2378] = {
    id = 2378,
    title = "Find the Shattered Hand",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Mennet Carkad",
    objectives = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.",
    rewards = "115 XP",
    tip = "You have served the Deathstalkers well, $N, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.\n\nThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.",
    isForever = false,
  },
  [963] = {
    id = 963,
    title = "For Love Eternal",
    reqLevel = 11,
    questLevel = 16,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Cerellean Whiteclaw",
    objectives = "Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine.",
    rewards = "880 XP",
    tip = "In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya.\n\nI would never have thought, thousands of years later, that memories of Anaya would still haunt my dreams. Wandering the woods of Darkshore in a stupor, I found myself in the ruins of Ameth'Aran... where I saw the haunted spirit of my beloved.\n\nShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.",
    isForever = false,
  },
  [1618] = {
    id = 1618,
    title = "Gearing Redridge",
    reqLevel = 1,
    questLevel = 16,
    faction = "Alliance",
    zone = "Blacksmithing",
    npc = "Tormus Deepforge",
    objectives = "Tormus Deepforge  wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.",
    rewards = "1,150 XP",
    tip = "We dwarves aren't the only ones fighting.  Our human allies have their hands full too!\n\nRedridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.",
    isForever = false,
  },
  [1489] = {
    id = 1489,
    title = "Hamuul Runetotem",
    reqLevel = 12,
    questLevel = 16,
    faction = "Horde",
    zone = "Wailing Caverns",
    npc = "Tonga Runetotem",
    objectives = "Speak with Hamuul Runetotem",
    rewards = "290 XP",
    tip = "The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake.\n\nThe Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel.\n\nYou will find him in Thunder Bluff, on the Elder Rise.",
    isForever = false,
  },
  [875] = {
    id = 875,
    title = "Harpy Lieutenants",
    reqLevel = 12,
    questLevel = 16,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Darsok Swiftdagger",
    objectives = "Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads.",
    rewards = "1,150 XP • 8s",
    tip = "Hahaha, $n. Back for more? Good, I like to hear that.\n\nThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.\n\nMake sure they die painfully, $n. We want those harpy wenches to know the idiocy of picking fights with the Horde.",
    isForever = false,
  },
  [5728] = {
    id = 5728,
    title = "Hidden Enemies",
    reqLevel = 9,
    questLevel = 16,
    faction = "Horde",
    zone = "Ragefire Chasm",
    npc = "Thrall",
    objectives = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",
    rewards = "1,150 XP • 8s",
    tip = "Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.\n\nReturn to the Cleft of Shadow and enter Ragefire Chasm, $N. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his $gbrothers:sisters; in arms.",
    isForever = false,
  },
  [5730] = {
    id = 5730,
    title = "Hidden Enemies",
    reqLevel = 9,
    questLevel = 16,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Neeru Fireblade",
    objectives = "Speak to Thrall in Orgrimmar and tell him what you've learned.",
    rewards = "1,450 XP",
    tip = "You are one of my lieutenants! Prepare yourself, $c. I will call upon you soon.\n\nMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.",
    isForever = false,
  },
  [1960] = {
    id = 1960,
    title = "Investigate the Alchemist Shop",
    reqLevel = 15,
    questLevel = 16,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Anastasia Hartwell",
    objectives = "Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell.  Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.",
    rewards = "1,150 XP",
    tip = "Algernon's alchemist shop in the Apothecarium is the locus of a strange disturbance.  Invisible creatures, made solely of magic, wander the shop--there must be a reason, and we must find it!\n\nInvestigate the disturbance and capture those creatures.  Take a chest of coffers and a scroll from behind me.  Use the scroll at the shop to make the creatures visible, subdue them with your spells, then throw down a coffer to capture them.  Return with the filled coffers, the empty coffers and the cantati",
    isForever = false,
  },
  [1920] = {
    id = 1920,
    title = "Investigate the Blue Recluse",
    reqLevel = 15,
    questLevel = 16,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Jennea Cannon",
    objectives = "Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon.  Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.",
    rewards = "1,150 XP",
    tip = "A disturbance has been reported at the Blue Recluse tavern in the Mage Quarter.  Strange, invisible creatures now wander the tavern, and I fear a mana rift has formed there.\n\nI want you to investigate the tavern and capture those creatures.  Use the cantation of manifestation in the tavern to make the creatures visible, subdue them then use a containment coffer to capture them.  When you have enough, return to me with your filled coffers, your empty coffers and the cantation.",
    isForever = false,
  },
  [2298] = {
    id = 2298,
    title = "Kingly Shakedown",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Hulfdan Blackbeard",
    objectives = "Travel to Stormwind and seek out Renzik \"The Shiv.\"",
    rewards = "115 XP",
    tip = "So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.\n\nWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!\n\nMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"",
    isForever = false,
  },
  [850] = {
    id = 850,
    title = "Kolkar Leaders",
    reqLevel = 11,
    questLevel = 16,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Regthar Deathgate",
    objectives = "Bring Barak's Head to Regthar Deathgate, west of the Crossroads.",
    rewards = "880 XP • 8s",
    tip = "The centaurs have plagued the Tauren for years.  And recently, the Kolkar centaurs of the Barrens have grown into a real threat.  Normally they were disorganized in these lands, but new leaders have risen among them.  Rallying them.\n\nTo preserve our holdings here, these centaur leaders must be destroyed.\n\nBring me the head of Barak Kodobane.  He camps near the Forgotten Pools to the north.\n\nDefeat him, then return to me.",
    isForever = false,
  },
  [1490] = {
    id = 1490,
    title = "Nara Wildmane",
    reqLevel = 12,
    questLevel = 16,
    faction = "Horde",
    zone = "Wailing Caverns",
    npc = "Arch Druid Hamuul Runetotem",
    objectives = "Speak with Nara Wildmane.",
    rewards = "115 XP",
    tip = "I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.\n\nI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.\n\nSpeak with Nara.  She is in the tent, over yonder.",
    isForever = false,
  },
  [441] = {
    id = 441,
    title = "Raleigh and the Undercity",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Magistrate Sevren",
    objectives = "Bring Deliah's Ring to Raleigh.",
    rewards = "580 XP",
    tip = "Deliah had a husband, Raleigh, who now dwells in the Undercity.  If the Deliah who lived in Brill is the one who owned this ring, then Raleigh will know.\n\nRaleigh is in the Trade Quarter of the Undercity.",
    isForever = false,
  },
  [2281] = {
    id = 2281,
    title = "Redridge Rendezvous",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Renzik \"The Shiv\"",
    objectives = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.",
    rewards = "115 XP",
    tip = "Sending you out in the field now would be suicide. Renzik doesn't need another dead rogue on his hands. Don't fret, though, $N - Renzik is going to get you up to speed.\n\nMake your way to the Redridge Mountains and speak with an associate of SI:7 named Lucius. You will find him hanging around the docks of Lakeshire with the other shady good-for-nothings.",
    isForever = false,
  },
  [448] = {
    id = 448,
    title = "Report to Hadrec",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Apothecary Renferrel",
    objectives = "Report to High Executor Hadrec at the Sepulcher.",
    rewards = "580 XP",
    tip = "Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need.",
    isForever = false,
  },
  [5724] = {
    id = 5724,
    title = "Returning the Lost Satchel",
    reqLevel = 9,
    questLevel = 16,
    faction = "Horde",
    zone = "Ragefire Chasm",
    npc = "Maur Grimtotem",
    objectives = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",
    rewards = "1,450 XP",
    tip = "You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs.\n\nRemoving the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff.",
    isForever = false,
  },
  [866] = {
    id = 866,
    title = "Root Samples",
    reqLevel = 9,
    questLevel = 16,
    faction = "Both",
    zone = "Azeroth",
    npc = "Mebok Mizzyrix",
    objectives = "Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.",
    rewards = "1,150 XP • 8s",
    tip = "The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.\n\nI want to study those differences... to see if they're exploitable!\n\nIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.",
    isForever = false,
  },
  [439] = {
    id = 439,
    title = "Rot Hide Clues",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Object: Corpse Laden Boat",
    objectives = "Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.",
    rewards = "290 XP",
    tip = "Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.  \n\nOn the hand is a ring.  Removing the ring and inspecting it reveals an engraving:\n\n\"For Deliah\"",
    isForever = false,
  },
  [2300] = {
    id = 2300,
    title = "SI:7",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Keryn Sylvius",
    objectives = "Travel to Stormwind and seek out Renzik \"The Shiv.\"",
    rewards = "115 XP",
    tip = "Renzik was looking for you, fish.\n\nI wouldn't keep Mathias's second in command waiting if I were you.",
    isForever = false,
  },
  [902] = {
    id = 902,
    title = "Samophlange",
    reqLevel = 10,
    questLevel = 16,
    faction = "Both",
    zone = "The Barrens",
    npc = "Object: Control Console",
    objectives = "Return the Samophlange to Sputtervalve in Ratchet.",
    rewards = "1,150 XP",
    tip = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.",
    isForever = false,
  },
  [5722] = {
    id = 5722,
    title = "Searching for the Lost Satchel",
    reqLevel = 9,
    questLevel = 16,
    faction = "Horde",
    zone = "Ragefire Chasm",
    npc = "Rahauro",
    objectives = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.",
    rewards = "880 XP",
    tip = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrim",
    isForever = false,
  },
  [5761] = {
    id = 5761,
    title = "Slaying the Beast",
    reqLevel = 9,
    questLevel = 16,
    faction = "Horde",
    zone = "Ragefire Chasm",
    npc = "Neeru Fireblade",
    objectives = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",
    rewards = "1,150 XP • 8s",
    tip = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.\n\nIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.\n\nKill him, and his heart will appease Thrall, of this I'm ",
    isForever = false,
  },
  [888] = {
    id = 888,
    title = "Stolen Booty",
    reqLevel = 9,
    questLevel = 16,
    faction = "Both",
    zone = "The Barrens",
    npc = "Gazlowe",
    objectives = "Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.",
    rewards = "1,150 XP • 8s",
    tip = "While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have!\n\nAs you see, my observatory is ready to go, but it needs the smaller of the two lenses. The first arrived by caravan from Durotar, but the second was bound by ship, and never arrived. Also, I never got my boot shipment from Drizzlik in Booty Bay!\n\nHead down to the pirate camp and see if you can find them.",
    isForever = false,
  },
  [438] = {
    id = 438,
    title = "The Decrepit Ferry",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "High Executor Hadrec",
    objectives = "Go to the Decrepit Ferry.\n\nSearch for the reason the Scourge are there.",
    rewards = "880 XP",
    tip = "$N, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead.\n\nThere must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there.",
    isForever = false,
  },
  [440] = {
    id = 440,
    title = "The Engraved Ring",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "High Executor Hadrec",
    objectives = "Bring Deliah's Ring to Magistrate Sevren in Brill.",
    rewards = "580 XP",
    tip = "If you want to find the husband or beloved who gave Deliah her ring... then speak with Magistrate Sevren in Brill.  He should have records of recent deaths and, with luck, can discover who Deliah is.\n\nBut I wouldn't hope.  Whoever gave her the ring is probably dead.  Or if he's undead he probably no longer cares about Deliah.",
    isForever = false,
  },
  [125] = {
    id = 125,
    title = "The Lost Tools",
    reqLevel = 15,
    questLevel = 16,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Foreman Oslow",
    objectives = "Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.",
    rewards = "880 XP",
    tip = "I could really use a hand here, $N.  With the town under siege, it's been hard to get supplies.  My tools were being delivered from Goldshire by wagon but the bridge was blown out.  We put the tools in a boat but the orcs hit it with a catapult.  Just my luck, my toolbox sank right to the bottom of the lake.\n\nRetrieve my toolbox, $N, and I'll make it worth your while.",
    isForever = false,
  },
  [5725] = {
    id = 5725,
    title = "The Power to Destroy...",
    reqLevel = 9,
    questLevel = 16,
    faction = "Horde",
    zone = "Ragefire Chasm",
    npc = "Varimathras",
    objectives = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",
    rewards = "1,450 XP",
    tip = "Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.\n\nA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for ",
    isForever = false,
  },
  [877] = {
    id = 877,
    title = "The Stagnant Oasis",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Tonga Runetotem",
    objectives = "Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.",
    rewards = "1,150 XP",
    tip = "Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life.\n\nWe must test this.\n\nHere, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe.",
    isForever = false,
  },
  [446] = {
    id = 446,
    title = "Thule Ravenclaw",
    reqLevel = 10,
    questLevel = 16,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Bethor Iceshard",
    objectives = "Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.",
    rewards = "290 XP",
    tip = "This Ichor was crafted by an old colleague of mine: Thule Ravenclaw.  He was a young, promising mage before the great war, but when the Lich King rose to power, he betrayed his brethren and allied with the Scourge.\n\nI did not realize he still lives, nor that he leads the Rot Hides in their forays against us!\n\nI know many of his spells, and can help concoct a potion to counter them.  Take this scroll back to Apothecary Renferrel.  It has the incantations needed for the potion.",
    isForever = false,
  },
  [2299] = {
    id = 2299,
    title = "To Hulfdan!",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Hogral Bakkan",
    objectives = "Travel to Ironforge and speak with Hulfdan Blackbeard.",
    rewards = "115 XP",
    tip = "Where have you been, $N? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.\n\nGet to Ironforge as soon as possible and speak with Hulfdan!",
    isForever = false,
  },
  [2380] = {
    id = 2380,
    title = "To Orgrimmar!",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Kaplak",
    objectives = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.",
    rewards = "115 XP",
    tip = "A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.\n\nTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.",
    isForever = false,
  },
  [28] = {
    id = 28,
    title = "Trial of the Lake",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
    rewards = "880 XP",
    tip = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, $N.",
    isForever = false,
  },
  [29] = {
    id = 29,
    title = "Trial of the Lake",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Dendrite Starblaze",
    objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
    rewards = "880 XP",
    tip = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, $N.",
    isForever = false,
  },
  [30] = {
    id = 30,
    title = "Trial of the Sea Lion",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Druid Class Quests",
    npc = "Tajarri",
    objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
    rewards = "880 XP",
    tip = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaz",
    isForever = false,
  },
  [272] = {
    id = 272,
    title = "Trial of the Sea Lion",
    reqLevel = 16,
    questLevel = 16,
    faction = "Alliance",
    zone = "Druid Class Quests",
    npc = "Tajarri",
    objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
    rewards = "880 XP",
    tip = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaz",
