  [895] = {
    id = 895,
    title = "WANTED: Baron Longshore",
    reqLevel = 11,
    questLevel = 16,
    faction = "Both",
    zone = "The Barrens",
    npc = "Object: WANTED",
    objectives = "Bring the head of Baron Longshore to Gazlowe in Ratchet.",
    rewards = "1,150 XP • 8s",
    tip = "WANTED!\n\nBaron Longshore, Captain of the Heedless\n\nCaptain Longshore of Gilneas leads vessels of the Southsea Freebooters, and is wanted on charges of piracy. Remains must be in identifiable condition!\n\n-- Gazlowe",
    isForever = false,
  },
  [2382] = {
    id = 2382,
    title = "Wrenix of Ratchet",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Zando'zan",
    objectives = "Travel to Ratchet and speak with Wrenix the Wretched.",
    rewards = "115 XP",
    tip = "Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.\n\n$N! Zando'zan has a task for $N! $N must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!",
    isForever = false,
  },
  [2379] = {
    id = 2379,
    title = "Zando'zan",
    reqLevel = 16,
    questLevel = 16,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Shenthul",
    objectives = "Speak with Zando'zan at the Cleft of Shadow.",
    rewards = "Experience & Faction Reputation",
    tip = "Your determination alone is not enough to overcome the obstacles that lay ahead of us.\n\nSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.\n\nIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny.",
    isForever = false,
  },
  [258] = {
    id = 258,
    title = "A Hunter's Challenge",
    reqLevel = 11,
    questLevel = 17,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Daryl the Youngling",
    objectives = "Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes.",
    rewards = "950 XP",
    tip = "$nath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat.\n\nYou should try your hand at boar hunting. Trust me, this is no Coldridge Valley boar hunt, so you'd best have a care with them. I'll give you just twelve minutes this time.\n\nDon't feel bad if you fail. I'd give you the shirt off my back if you succeeded!\n\nHave I ever related to you the story of how I received my famous scar? No? It was two years ago...",
    isForever = false,
  },
  [246] = {
    id = 246,
    title = "Assessing the Threat",
    reqLevel = 11,
    questLevel = 17,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Deputy Feldon",
    objectives = "Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.",
    rewards = "950 XP • 7s",
    tip = "We don't have men to spare, but something must be done about those gnolls you reported to me.\n\nScout southern Redridge for gnolls.  Harry them, kill those you can and report back to me with a count of their numbers and an assessment of the threat they present.  You may find those gnolls camped all along the southern road of Redridge.\n\nDo this for the Stormwind Army, $N, and you will be rewarded.",
    isForever = false,
  },
  [947] = {
    id = 947,
    title = "Cave Mushrooms",
    reqLevel = 12,
    questLevel = 17,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Barithras Moonshade",
    objectives = "Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.",
    rewards = "1,250 XP • 9s",
    tip = "I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave.  The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains.\n\nI would go there myself, but I was advised by the Grove of the Ancients to stay away from that place.  Our venerable allies sense that the cave is the hiding place for a new evil in Darkshore.\n\nPlease, $N, gather the mushrooms for me.  And while doing so, scout the cave to confirm the Ancients' fears.",
    isForever = false,
  },
  [982] = {
    id = 982,
    title = "Deep Ocean, Vast Sea",
    reqLevel = 13,
    questLevel = 17,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Gorbold Steelhand",
    objectives = "Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine.  Both items should be found aboard the wreckage of the ships to the north of the village.",
    rewards = "1,250 XP • 18s",
    tip = "Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil.  Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine.  They now lie at the bottom of the ocean as trophies for those fiends.\n\nBoth captains didn't make it out that night, and their logs and other effects are still below in lockboxes.  I'd like for you to recover them for us; it would mean a lot to the crew members still around these parts.",
    isForever = false,
  },
  [1486] = {
    id = 1486,
    title = "Deviate Hides",
    reqLevel = 13,
    questLevel = 17,
    faction = "Both",
    zone = "Wailing Caverns",
    npc = "Nalpak",
    objectives = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.",
    rewards = "1,600 XP • 18s",
    tip = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.\n\nIf you feel up to the task, venture into the caves below and retrieve some deviate hides.",
    isForever = false,
  },
  [1138] = {
    id = 1138,
    title = "Fruit of the Sea",
    reqLevel = 15,
    questLevel = 17,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Gubber Blump",
    objectives = "Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.",
    rewards = "1,250 XP",
    tip = "I love crab.  Crabs are the fruit of the sea!  You can bake it, barbecue it, boil it, and broil it.  They're pan fried, deep fried, and stir fried.  There's crab salad, crab soup, crab stew, pepper crab, lemon crab, whipper root crab, and Ironforge surprise crab.  That's... that's about it.\n\nI'm here fishing right now, so I can't get any fine crab chunks.  You can pick them out of reef crawlers and encrusted tide crawlers.  You can make a lot with it.  You can bake it, barbecue it, boil it...",
    isForever = false,
  },
  [217] = {
    id = 217,
    title = "In Defense of the King's Lands",
    reqLevel = 10,
    questLevel = 17,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Captain Rugelfuss",
    objectives = "Kill the Trogg leader, Grawmug, and his two guards, Gnasher and Brawler then report back to Captain Rugelfuss in the southern guard tower.",
    rewards = "1,600 XP",
    tip = "$N, our scouts have identified the leader of this recent Trogg incursion.  It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug.  Grawmug is heavily guarded, however.  Two of his most elite guards, Gnasher and Brawler, never leave his side.\n\nIf you feel yourself worthy, $N, I want you to lead the assassination mission on Grawmug and his two thugs.  With the Trogg leadership dead, we just might stand a chance at pushing these beasts back into the ground.",
    isForever = false,
  },
  [948] = {
    id = 948,
    title = "Onu",
    reqLevel = 12,
    questLevel = 17,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Barithras Moonshade",
    objectives = "Speak with Onu at the Grove of the Ancients.",
    rewards = "630 XP",
    tip = "Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you.  The grove lies to the south, nestled near the mountains.\n\nThe Ancients are patient and wise, $N.  But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.",
    isForever = false,
  },
  [214] = {
    id = 214,
    title = "Red Silk Bandanas",
    reqLevel = 14,
    questLevel = 17,
    faction = "Alliance",
    zone = "The Deadmines",
    npc = "Scout Riell",
    objectives = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.",
    rewards = "1,250 XP",
    tip = "It's no secret that the trademark of the Defias Gang is their Red Bandanas.  But we've learned that the material from which these bandanas are made signifies the member's rank.\n\nThat being said, I want you to eliminate as many high ranking Defias members as you can.  The highest ranking members will undoubtedly be found in VanCleef's secret hideout.  When you're done bring me 10 Red Silk Bandanas as proof of their deaths and I will reward you.  Good luck, $N.",
    isForever = false,
  },
  [460] = {
    id = 460,
    title = "Resting in Pieces",
    reqLevel = 12,
    questLevel = 17,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Item: A Talking Head",
    objectives = "Bring Alaric's Head to his grave.",
    rewards = "630 XP",
    tip = "You don't look like a rot hide.  Good.  I had lost hope...\n\nMy name is Alaric, and I was once Thule's head servant and bodyguard.  He used his magic to \"protect\" me from the Plague of Undeath, but instead his spell gave me an unlife from which I cannot escape.  And after creating the cursed rot hide gnolls, Thule beheaded me... and gave my head to the gnolls as a plaything!\n\nPlease, take me to my body.  I believe the gnolls buried it here in Fenris Keep, near the stable, in an unmarked grave.",
    isForever = false,
  },
  [950] = {
    id = 950,
    title = "Return to Onu",
    reqLevel = 12,
    questLevel = 17,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Twilight Tome",
    objectives = "Bring Onu the recovered Insane Scribbles.",
    rewards = "950 XP • 7s",
    tip = "Peering into the Twilight Tome is maddening.  Text begins to swim and dance after only a moment's glance, and once beautiful scrollwork twists into grotesque shapes.\n\nTearing away one page of insane scribbles is all that is possible before a swoon overtakes you.",
    isForever = false,
  },
  [443] = {
    id = 443,
    title = "Rot Hide Ichor",
    reqLevel = 10,
    questLevel = 17,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "High Executor Hadrec",
    objectives = "Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.",
    rewards = "1,250 XP • 9s",
    tip = "Before we launch an assault on Fenris Isle, we must determine who is behind the rot hide gnolls.  Our apothecaries believe their origin lies within the strange fluid that flows through their bodies.\n\nGo to Fenris Isle, east of the Decrepit Ferry, and collect rot hide ichor from the gnolls you find there.  Bring it to Apothecary Renferrel, stationed outside the Sepulcher.",
    isForever = false,
  },
  [444] = {
    id = 444,
    title = "Rot Hide Origins",
    reqLevel = 10,
    questLevel = 17,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Apothecary Renferrel",
    objectives = "Bring the Sample Ichor to Bethor Iceshard in the Undercity.",
    rewards = "315 XP",
    tip = "I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation.\n\nWhile I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides.\n\nGo.  You will find Bethor in the Magic Quarter of the Undercity.",
    isForever = false,
  },
  [905] = {
    id = 905,
    title = "The Angry Scytheclaws",
    reqLevel = 10,
    questLevel = 17,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Sergra Darkthorn",
    objectives = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.",
    rewards = "1,250 XP • 9s",
    tip = "Now, $N, the hunt deepens.  Now you must defeat your prey, and then find your way to its lair.\n\nHunt the sunscale raptors to the south.  Slay them and remove the feathers they wear.  Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!",
    isForever = false,
  },
  [944] = {
    id = 944,
    title = "The Master's Glaive",
    reqLevel = 12,
    questLevel = 17,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Onu",
    objectives = "Gather information, then use the Phial of Scrying to create a Scrying Bowl.  Use the bowl to speak with Onu.",
    rewards = "630 XP",
    tip = "It is strange that the naga are here, in Darkshore.  But stranger still...are the Twilight's Hammer.  That cult worships the old, old lords of the earth.  Lords defeated long ago.\n\nThe Master's Glaive, to the south, is a place where such an old lord fell.\n\nGo there and look for more Twilight's Hammer cultists.\n\nTake this phial of scrying.  Use it to create a scrying bowl after searching the Master's Glaive.  Then speak to me through the bowl.",
    isForever = false,
  },
  [14] = {
    id = 14,
    title = "The People's Militia",
    reqLevel = 9,
    questLevel = 17,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Gryan Stoutmantle",
    objectives = "Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.",
    rewards = "1,600 XP",
    tip = "Pro-tip: You MUST throw the holy water at Morbent Fel to remove his protective shield before attacking!",
    isForever = false,
  },
  [1061] = {
    id = 1061,
    title = "The Spirits of Stonetalon",
    reqLevel = 13,
    questLevel = 17,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Zor Lonetree",
    objectives = "Speak with Seereth Stonebreak in the Stonetalon Mountains.",
    rewards = "315 XP",
    tip = "The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.\n\nSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.\n\nMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.",
    isForever = false,
  },
  [949] = {
    id = 949,
    title = "The Twilight Camp",
    reqLevel = 12,
    questLevel = 17,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Scrying Bowl",
    objectives = "Find a clue in the Twilight's Hammer camp at the Master's Glaive.",
    rewards = "1,250 XP • 9s",
    tip = "The Twilight's Hammer's purpose at the Master's Glaive is not known.  But it must be dark.\n\nSearch through their camp at the Glaive... Search for some thing that may teach us their intentions.\n\nFor we must learn their intentions before a plan is made.",
    isForever = false,
  },
  [161] = {
    id = 161,
    title = "A Dark Threat Looms",
    reqLevel = 16,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Chief Engineer Hinderweir VII",
    objectives = "Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert in Dun Modr.",
    rewards = "1,350 XP",
    tip = "If my suspicions are correct, this is some type of explosive powder.  This must be analyzed by an explosives expert so we know just what we're dealing with here.  Ashlan Stonesmirk was assigned to the regiment guarding Dun Modr and the Thandol Span.  I need you to make a grave and perilous journey, $N.\n\nTravel through the Algaz Gate, follow the road through the Wetlands and seek out Stonesmirk in Dun Modr.  Heed my advice: stick to the roads and stop for nothing!",
    isForever = false,
  },
  [199] = {
    id = 199,
    title = "A Dark Threat Looms",
    reqLevel = 16,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Object: Suspicious Barrel",
    objectives = "Return to Chief Engineer Hinderweir and show him the clue that you discovered.",
    rewards = "1,350 XP",
    tip = "You take a sample of the strange smelling powder.",
    isForever = false,
  },
  [250] = {
    id = 250,
    title = "A Dark Threat Looms",
    reqLevel = 16,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Chief Engineer Hinderweir VII",
    objectives = "Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.",
    rewards = "680 XP",
    tip = "Thank the stars someone is concerned about the well-being of the Dam.  First the destruction of the Thandol Span and then the pillaging of Dun Modr!  I have no doubt that the Dam will be the target of the next Dark Iron threat.  Most of the security detail here was reassigned to the Alliance Front, including my top inspector.\n\nThat's why I need you, $N.  I spotted some Dark Iron Sappers milling about the eastern ramp of the Dam.   Investigate the area and bring back a clue.",
    isForever = false,
  },
  [274] = {
    id = 274,
    title = "A Dark Threat Looms",
    reqLevel = 16,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Ashlan Stonesmirk",
    objectives = "Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery.",
    rewards = "340 XP",
    tip = "This ain't no ordinary blast powder.  Look at the tiny silver crystals.  And the distinct smell!  Why it's clear as daylight that this is Seaforium Powder.  Seaforium is harmless enough.  But once it's wet it could blow Ironforge out of the mountain.\n\nThe chemical reaction can be defused by mixing four components:  lurker venom, crushed Mo'Grosh crystal, a crocolisk tear and this disarming colloid.  Now tell Hinderweir before it's too late!",
    isForever = false,
  },
  [278] = {
    id = 278,
    title = "A Dark Threat Looms",
    reqLevel = 16,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Chief Engineer Hinderweir VII",
    objectives = "Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear.",
    rewards = "1,350 XP",
    tip = "Begin collecting the disarming materials immediately, $N.  Lurker Venom can be found on the indigenous spiders in Loch Modan.  Crocolisk tears are found here in the Loch as well.  But a Mo'Grosh crystal will be very difficult to procure.  The ogres to the northeast mine them but the crystals are a very rare commodity.\n\nWe need to be prepared to defuse a Dark Iron attack!  Return to me once you've collected the needed items and I will prepare the mixture.",
    isForever = false,
  },
  [280] = {
    id = 280,
    title = "A Dark Threat Looms",
    reqLevel = 16,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Chief Engineer Hinderweir VII",
    objectives = "Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.",
    rewards = "680 XP",
    tip = "Earlier today I spotted some Dark Iron Insurgents swimming toward the Dam with a large keg.  No Mountaineers were on hand to stop them!  I'm afraid they've planted the Seaforium at the base of the Dam and it could blow at any minute!  Let me combine all these ingredients into the Disarming Mixture.  There we go.\n\nNow I need you to take this mixture and stir it into the keg before it's too late!  Hurry!",
    isForever = false,
  },
  [451] = {
    id = 451,
    title = "A Recipe For Death",
    reqLevel = 9,
    questLevel = 18,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Apothecary Renferrel",
    objectives = "Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.",
    rewards = "2,050 XP",
    tip = "According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east.\n\nHe also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one.\n\nCollect samples of the moss as well as the rare hardened tumor and take them to Master Apothecary Faranell in the Undercity.",
    isForever = false,
  },
  [6548] = {
    id = 6548,
    title = "Avenge My Village",
    reqLevel = 12,
    questLevel = 18,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Makaba Flathoof",
    objectives = "- Grimtotem Ruffian x 8 - Grimtotem Mercenary x 6",
    rewards = "1,350 XP, 10s",
    tip = "The Grimtotem Clan raided my village and killed most everyone. I killed all I could, but barely escaped with my life.\n\n$N, all I wish now is that more of them are dead. You will find them just to the west of here.",
    isForever = false,
  },
  [6421] = {
    id = 6421,
    title = "Boulderslide Ravine",
    reqLevel = 14,
    questLevel = 18,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Mor'rogal",
    objectives = "Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.",
    rewards = "1,350 XP • 10s",
    tip = "Something is amiss here in Stonetalon. Can you feel the tension in the air, $N?\n\nSoutheast of here lies a deep cave in Boulderslide Ravine. The kobolds there are frantically mining a rare crystal called Resonite. I need you to bring back some ore samples so that I can understand what's happening in that cave.  I also need you to investigate the depth of that cave.\n\nGo young $c, it's imperative I know what evil lurks under these mountains.",
    isForever = false,
  },
  [168] = {
    id = 168,
    title = "Collecting Memories",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "The Deadmines",
    npc = "Wilder Thistlenettle",
    objectives = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.",
    rewards = "1,350 XP",
    tip = "Many of my friends perished that horrible day when the mine tunnel caved in.  If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them.  If you come across any of their Miners' Union Cards, bring them back to me and I'll make sure their families get some resolution from this horrible accident.",
    isForever = false,
  },
  [907] = {
    id = 907,
    title = "Enraged Thunder Lizards",
    reqLevel = 10,
    questLevel = 18,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Jorn Skyseer",
    objectives = "Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.",
    rewards = "1,700 XP",
    tip = "Now, $N, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet.\n\nYou will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them.",
    isForever = false,
  },
  [1064] = {
    id = 1064,
    title = "Forsaken Aid",
    reqLevel = 13,
    questLevel = 18,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Magatha Grimtotem",
    objectives = "Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.",
    rewards = "340 XP",
    tip = "The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.\n\nIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.\n\nSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.",
    isForever = false,
  },
  [297] = {
    id = 297,
    title = "Gathering Idols",
    reqLevel = 13,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Magmar Fellhew",
    objectives = "Bring Magmar Fellhew 8 Carved Stone Idols.",
    rewards = "1,350 XP",
    tip = "Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols.  But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!  And those idols have a strange effect on the Troggs.  It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of Trogg hands!  You can find the idols on the Troggs infesting the site.",
    isForever = false,
  },
  [858] = {
    id = 858,
    title = "Ignition",
    reqLevel = 13,
    questLevel = 18,
    faction = "Both",
    zone = "The Barrens",
    npc = "Wizzlecrank's Shredder",
    objectives = "Get the Ignition Key and bring it to Wizzlecrank.",
    rewards = "1,350 XP",
    tip = "I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem.\n\nWe need to get out of here on the double! Go up to the control room at the top of the derrick, the supervisor should have a key for this shredder.\n\nHelp me out h",
    isForever = false,
  },
  [436] = {
    id = 436,
    title = "Ironband's Excavation",
    reqLevel = 13,
    questLevel = 18,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Jern Hornhelm",
    objectives = "Speak with Explorer Fellhew.",
    rewards = "340 XP",
    tip = "Prospector Ironband is heading an excavation of ancient ruins east of the lake.  His progress has been slow lately, especially considering all the supplies we've sent him.\n\nIronband's a stout, honest dwarf who values results, which has me worried that forces are at work against him.\n\nGo to Ironband's Excavation and speak with Magmar Fellhew.  He manages the details of the site and will know why there's a slowdown.\n\nTo get to the excavation site, go around the southern tip of the lake, then head ",
    isForever = false,
  },
  [3261] = {
    id = 3261,
    title = "Jorn Skyseer",
    reqLevel = 10,
    questLevel = 18,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Sergra Darkthorn",
    objectives = "Speak with Jorn Skyseer at Camp Taurajo.",
    rewards = "135 XP",
    tip = "Your time with me is over, $N.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance.",
    isForever = false,
  },
  [1056] = {
    id = 1056,
    title = "Journey to Stonetalon Peak",
    reqLevel = 18,
    questLevel = 18,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Faldreas Goeth'Shael",
    objectives = "Travel to Keeper Albagorm on Stonetalon Peak.",
    rewards = "680 XP",
    tip = "The forest spirits tell me you are brave and willing to travel.\n\nTo the south, not far from Mystral Lake, there lies a tunnel named The Talondeep Path. Through this tunnel you will come to an area known as Windshear Crag in the Stonetalon Mountains. Once there, journey to the southwest past Cragpool Lake and then north, up the steep slope until you reach Stonetalon Peak.\n\nThere awaits Keeper Albagorm. Heed his bidding, $r.\n\nThe journey will be perilous.",
    isForever = false,
  },
  [1065] = {
    id = 1065,
    title = "Journey to Tarren Mill",
    reqLevel = 13,
    questLevel = 18,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Apothecary Zamah",
    objectives = "Bring Zamah's Note to Apothecary Lydon in Tarren Mill.",
    rewards = "1,350 XP",
    tip = "To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed.\n\nA colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron.\n\nTo reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad.\n\nSeek Lydon and bring him this note.  It details our needs to him.",
    isForever = false,
  },
  [6401] = {
    id = 6401,
    title = "Kaya's Alive",
    reqLevel = 12,
    questLevel = 18,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Makaba Flathoof",
    objectives = "Tell Tammra Windfield in Sun Rock Retreat the good news.",
    rewards = "1,000 XP, 7s",
    tip = "Tell Tammra Windfield, Kaya's aunt who's at Sun Rock Retreat, about the good news! Kaya is alive! We had thought she was lost after the brutal attack on our village. Follow the path to the west to get to Sun Rock Retreat.",
    isForever = false,
  },
  [6629] = {
    id = 6629,
    title = "Kill Grundig Darkcloud",
    reqLevel = 12,
    questLevel = 18,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Makaba Flathoof",
    objectives = "- Grundig Darkcloud - Grimtotem Brute x 6",
    rewards = "1,350 XP, 10s",
    tip = "$N, you've done a fine job killing Grimtotem. If you dare, Grundig Darkcloud and his personal band of brutes is by far the worst of the lot. He was the one who led the brutal attack on my village.\n\nYou will find him in Grimtotem Post a bit further up the path to the west. Kill him, and I will be forever grateful.",
    isForever = false,
  },
  [145] = {
    id = 145,
    title = "Messenger to Darkshire",
    reqLevel = 18,
    questLevel = 18,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Magistrate Solomon",
    objectives = "Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.",
    rewards = "1,000 XP",
    tip = "I require your assistance once again.  I have written to Lord Ebonlocke, requesting that he sends his trained guards, the Night Watch, to help with Lakeshire's defense.  It is imperative this message makes it to him swiftly.  You must exercise extreme caution.  Ebonlocke is the mayor of Darkshire, in the heart of Duskwood.  Do not stray from the roads.",
    isForever = false,
  },
  [146] = {
    id = 146,
    title = "Messenger to Darkshire",
    reqLevel = 18,
    questLevel = 18,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Lord Ello Ebonlocke",
    objectives = "Return to Magistrate Solomon with Lord Ebonlocke's letter of response.",
    rewards = "340 XP • 2s 50c",
    tip = "If I did not know Magistrate Solomon personally, I would say the man has gone mad.  Send the Night Watch to Lakeshire because Stormwind refuses aid?  The Night Watch was formed because Stormwind left us when this foul magic seeped into the land.  If I sent my Night Watch, this town would be overrun by evil before the guards even reached the forest's edge.\n\nTake this letter of response to your Master in Lakeshire.",
    isForever = false,
  },
  [896] = {
    id = 896,
    title = "Miner's Fortune",
    reqLevel = 13,
    questLevel = 18,
    faction = "Both",
    zone = "The Barrens",
    npc = "Wharfmaster Dizzywig",
    objectives = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.",
    rewards = "1,700 XP",
    tip = "Being Wharfmaster of a busy port like Ratchet, I keep my finger on the pulse of information. I know all about the exchange of goods and money between here and Booty Bay.\n\nThe latest bit of news I've heard is about the Venture Company's Boulder Lode mine northeast of the Sludge Fen. One of the miners discovered an emerald the size of your fist. I know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale.",
    isForever = false,
  },
  [1582] = {
    id = 1582,
    title = "Moonglow Vest",
    reqLevel = 8,
    questLevel = 18,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Lotherias",
    objectives = "Bring 1 Embossed Leather Glove, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.",
    rewards = "1,350 XP",
    tip = "We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.\n\nIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.",
    isForever = false,
  },
  [2381] = {
    id = 2381,
    title = "Plundering the Plunderers",
    reqLevel = 16,
    questLevel = 18,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Wrenix the Wretched",
    objectives = "- Southsea Treasure",
    rewards = "1,350 XP",
    tip = "I don't mean to scare you, $N, but the last five thieves I sent to steal the southsea treasure came back to me in pieces.\n\nSouth along the coast you'll find Tide Razor, the southsea freebooter's ship. Nestled in the hold is the payoff - the southsea treasure. On the second level of that ship is the pirate's den, a place where they train all of their thieves.\n\nBoard that ship, steal the treasure, and bring it back to me. Use the pirate's den if you need to practice your thievery, but be careful!",
    isForever = false,
  },
  [6523] = {
    id = 6523,
    title = "Protect Kaya",
    reqLevel = 12,
    questLevel = 18,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Kaya Flathoof",
    objectives = "- Kaya Escorted to Camp Aparaje",
    rewards = "1,350 XP, 10s",
    tip = "Thank you for rescuing me! We must leave quickly before they discover that I am free. Please escort me to Camp Aparaje. From there, I know my way.\n\nMy father, Makaba Flathoof, will be desperate to know that I am safe.",
    isForever = false,
  },
  [865] = {
    id = 865,
    title = "Raptor Horns",
    reqLevel = 13,
    questLevel = 18,
    faction = "Both",
    zone = "The Barrens",
    npc = "Mebok Mizzyrix",
    objectives = "Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.",
    rewards = "1,350 XP",
    tip = "The raptors of the Barrens are smarter than raptors in other lands.  And I think all that smarts is hiding in their horns!  If so, then I could grind their horns into powder and use it to make \"smart drinks.\"  I could sell them for a fortune!!!\n\nAnd you can help me.  Find me intact raptor horns from sunscale scytheclaws.  They roam in the southern Barrens, and in the northern Barrens near the border of Ashenvale Forest.",
    isForever = false,
  },
  [92] = {
    id = 92,
    title = "Redridge Goulash",
    reqLevel = 15,
    questLevel = 18,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Chef Breanna",
    objectives = "Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.",
    rewards = "1,350 XP • 10s",
    tip = "Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige.\n\nJust bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.",
    isForever = false,
  },
  [119] = {
    id = 119,
    title = "Return to Verner",
    reqLevel = 13,
    questLevel = 18,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Smith Argus",
    objectives = "Return to Verner Osgood in Redridge.  Give him the Crate of Horseshoes.",
    rewards = "680 XP • 5s",
    tip = "Ok, I'll give him his 50 horseshoes...\n\nHere they are, all boxed up and ready to go!  Tell Verner it was a pleasure doing business, and be sure he reads the note attached to this crate!",
    isForever = false,
  },
  [3923] = {
    id = 3923,
    title = "Rilli Greasygob",
    reqLevel = 10,
    questLevel = 18,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Wenikee Boltbucket",
    objectives = "Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.",
    rewards = "340 XP",
    tip = "Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse.\n\nYou should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli.\n\nYou can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor.",
    isForever = false,
  },
  [962] = {
    id = 962,
    title = "Serpentbloom",
    reqLevel = 14,
    questLevel = 18,
    faction = "Horde",
    zone = "Wailing Caverns",
    npc = "Apothecary Zamah",
    objectives = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",
    rewards = "1,700 XP • 20s",
    tip = "The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, $n. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.\n\nRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.\n\nUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.",
    isForever = false,
  },
  [1491] = {
    id = 1491,
    title = "Smart Drinks",
    reqLevel = 13,
    questLevel = 18,
    faction = "Both",
    zone = "Wailing Caverns",
    npc = "Mebok Mizzyrix",
    objectives = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.",
    rewards = "1,350 XP • 10s",
    tip = "Ok, so the raptor horns didn't work so well.  But that's all right -- no one got rich on their first try!  And besides, I think I found something that'll work even better in my smart drinks!\n\nThere is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens.  Get me some and I'll try it in my drink!\n\nI heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west.  Hunt those creatures and gather the essence.",
    isForever = false,
  },
  [3281] = {
    id = 3281,
    title = "Stolen Silver",
    reqLevel = 9,
    questLevel = 18,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Gazrog",
    objectives = "Bring the Stolen Silver to Gazrog in the Crossroads.",
    rewards = "1,350 XP • 10s",
    tip = "You may have killed the raptors, but the silver they stole must be recovered!  I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds.  It is likely that they brought our stolen silver there.\n\nGo to this raptor haven and search for the stolen silver.  When you find it, return it to me.",
    isForever = false,
  },
  [2139] = {
    id = 2139,
    title = "Tharnariun's Hope",
    reqLevel = 10,
    questLevel = 18,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Tharnariun Treetender",
    objectives = "Find and kill the Den Mother.",
    rewards = "1,350 XP",
    tip = "The survival of our people and lands comes at unfortunate costs, $N.\n\nYou have spilled the blood of nature's servants; many sick animals you have felled. The people of Auberdine are indebted to you, for the forest's pain is eased - even if only for a moment.\n\nI have one final task for you, but be warned, you will have to kill again. It is my hope that this will be the last time I call upon you, $N.\n\nIn a cave to the northeast, near Bashal'Aran, resides the Den Mother. Slay her.",
    isForever = false,
  },
  [4763] = {
    id = 4763,
    title = "The Blackwood Corrupted",
    reqLevel = 15,
    questLevel = 18,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Thundris Windweaver",
    objectives = "Fill the Empty Cleansing Bowl at the Auberdine Moonwell.\n\nGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.\n\nMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.\n\nTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.",
    rewards = "1,700 XP • 20s",
    tip = "We've learned that a source of furbolg corruption is from the satyr.  They hold sway via talismans that they channel magic through.  If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!\n\nFill this bowl at our moonwell and take samples of the furbolgs' food from their northern camp.  Mix them and place it near the bonfire by the river; any furbolgs who eat will be cleansed just long enough to lure out the satyr corruptor... who then you must slay",
    isForever = false,
  },
  [65] = {
    id = 65,
    title = "The Defias Brotherhood",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Gryan Stoutmantle",
    objectives = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.",
    rewards = "1,350 XP",
    tip = "The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood.  I need you to infiltrate this clan of thugs.  We need to know who heads up the cartel and where they are hiding out.  In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor.\n\nTravel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can.",
    isForever = false,
  },
  [132] = {
    id = 132,
    title = "The Defias Brotherhood",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Wiley the Black",
    objectives = "Take Wiley's Note to Gryan Stoutmantle in Westfall.",
    rewards = "680 XP",
    tip = "What I am about to tell you could cost me my life.  The Defias gang is up to something big.  Last I heard they were working in conjunction with various gnolls, kobolds and even goblins.\n\nTake this note to Stoutmantle.  It explains as much as I know on the subject.",
    isForever = false,
  },
  [135] = {
    id = 135,
    title = "The Defias Brotherhood",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Gryan Stoutmantle",
    objectives = "Take Wiley's Note to Mathias Shaw in Stormwind.",
    rewards = "680 XP",
    tip = "I wonder what Wiley meant when he mentioned the Stonemasons.  Perhaps that was a slip of tongue.  Could the Defias gang be related to the Stonemasons?  Only one man would know for sure:  Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town.",
    isForever = false,
  },
  [141] = {
    id = 141,
    title = "The Defias Brotherhood",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Master Mathias Shaw",
    objectives = "Take Shaw's report to Gryan Stoutmantle in Westfall.",
    rewards = "340 XP",
    tip = "The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two.\n\nI have written a more detailed account for your Master in Westfall.  Take this to him at once!",
    isForever = false,
  },
  [142] = {
    id = 142,
    title = "The Defias Brotherhood",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Gryan Stoutmantle",
    objectives = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.",
    rewards = "1,350 XP",
    tip = "We need to discover the location of the Defias hideout.  $N, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.  I want you to capture him.  If he resists, kill him and bring me whatever he is carrying.",
    isForever = false,
  },
  [155] = {
    id = 155,
    title = "The Defias Brotherhood",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Westfall",
    npc = "The Defias Traitor",
    objectives = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood.  Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.",
    rewards = "1,700 XP",
    tip = "So Stoutmantle sends a scrawny $r like you to protect me?  Guess you'll have to do.  Better bring some friends too. \n\nYou know the deal, right?  You watch my back and I'll take you to the Defias hideout.  But you better be close by my side.  The Defias gang wants my head now.  If they see me with you, they'll try to kill me.\n\nLet me know when you and any friends you can round up are ready to go.",
    isForever = false,
  },
  [1063] = {
    id = 1063,
    title = "The Elder Crone",
    reqLevel = 13,
    questLevel = 18,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Seereth Stonebreak",
    objectives = "Speak with Magatha in Thunder Bluff.",
    rewards = "680 XP",
    tip = "To truly tend the spirits of Stonetalon we must consult the tauren elders.\n\nI do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she.\n\nMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains.",
    isForever = false,
  },
  [863] = {
    id = 863,
    title = "The Escape",
    reqLevel = 13,
    questLevel = 18,
    faction = "Both",
    zone = "The Barrens",
    npc = "Wizzlecrank's Shredder",
    objectives = "Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.",
    rewards = "1,700 XP • 20s",
    tip = "I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?",
    isForever = false,
  },
  [461] = {
    id = 461,
    title = "The Hidden Niche",
    reqLevel = 12,
    questLevel = 18,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Object: Shallow Grave",
    objectives = "Take Alaric to the hidden alcove.",
    rewards = "680 XP • 5s",
    tip = "I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there!\n\nThe alcove is in the southwestern tower of the keep, behind a dusty shelf.\n\nTake my body, but leave my boots.  They never fit me anyway...",
    isForever = false,
  },
  [118] = {
    id = 118,
    title = "The Price of Shoes",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Verner Osgood",
    objectives = "Take Verner's Note to Smith Argus in Goldshire.",
    rewards = "340 XP",
    tip = "I've been using so much iron keeping the Stormwind Guards outfitted, I don't have enough to supply the stable's horses with shoes!\n\nTake this note to Blacksmith Argus in Goldshire.  It explains to him my problem and requests a shipment of horseshoes.",
    isForever = false,
  },
  [965] = {
    id = 965,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 18,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Sentinel Elissa Starbreeze",
    objectives = "Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore.",
    rewards = "680 XP",
    tip = "Hail, young $r. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.\n\nTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.\n\nIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.",
    isForever = false,
  },
  [966] = {
    id = 966,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 18,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Balthule Shadowstrike",
    objectives = "Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx.",
    rewards = "1,350 XP • 10s",
    tip = "A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away.\n\nDelgren suspected such a company might be gathering at the tower, but did not know why.\n\nA few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more pow",
    isForever = false,
  },
  [967] = {
    id = 967,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 18,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Balthule Shadowstrike",
    objectives = "Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest.",
    rewards = "1,000 XP",
    tip = "My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle.\n\nDelgren must know of the cult's operations immediately.\n\nYou will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour.",
    isForever = false,
  },
  [945] = {
    id = 945,
    title = "Therylune's Escape",
    reqLevel = 10,
    questLevel = 18,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Therylune",
    objectives = "Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe.",
    rewards = "1,350 XP • 10s",
    tip = "Help!\n\nI was wandering around the Master's Glaive, and these dirty cultists surrounded me.  Lucky I'm good at hiding!!\n\nCan you help me out of here?  And I need to send word to my sister Therysil that I'm all right.  She's in Ashenvale to the south, at the Shrine of Aessina.",
    isForever = false,
  },
  [959] = {
    id = 959,
    title = "Trouble at the Docks",
    reqLevel = 14,
    questLevel = 18,
    faction = "Both",
    zone = "Wailing Caverns",
    npc = "Crane Operator Bigglefuzz",
    objectives = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.",
    rewards = "1,350 XP • 10s",
    tip = "Oops!\n\nHad a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down.\n\nBefore I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there.\n\nMaybe you're brave enough to find him?",
    isForever = false,
  },
  [122] = {
    id = 122,
    title = "Underbelly Scales",
    reqLevel = 14,
    questLevel = 18,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Verner Osgood",
    objectives = "Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.",
    rewards = "1,700 XP",
    tip = "I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire.  If you can get 6 of them for me, then I can pay Argus with some... and have enough left to fashion something for you.\n\nBlack dragon whelps are often flying around south of Lakeshire, but they like to wander.  You might have to just keep an eye out and hunt them when you see them.",
    isForever = false,
  },
  [851] = {
    id = 851,
    title = "Verog the Dervish",
    reqLevel = 11,
    questLevel = 18,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Regthar Deathgate",
    objectives = "Bring Verog's Head to Regthar Deathgate, west of the Crossroads.",
    rewards = "1,000 XP • 10s",
    tip = "The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you.\n\nTravel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come.\n\nBring me his head and I will place it with Barak Kodobane's.",
    isForever = false,
  },
  [4740] = {
    id = 4740,
    title = "WANTED: Murkdeep!",
    reqLevel = 15,
    questLevel = 18,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: WANTED: Murkdeep!",
    objectives = "Find and slay the murloc known as Murkdeep.  The creature is thought to be defending the murloc huts south of Auberdine along the water.\n\nReport the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.",
    rewards = "1,700 XP",
    tip = "Attention!\n\nA reward is being offered for the death of the murloc \"Murkdeep\".  This foul beast is known to be responsible for the death of at least one Sentinel, and is suspected of causing the sinking of at least two cargo vessels in the waters off Darkshore!\n\nMurkdeep was last spotted at a hutted murloc camp south of Auberdine, and is thought to be protecting the huts there.  Reward claims for this bounty should be claimed with Sentinel Glynda Nal'Shea in Auberdine.\n\nThe Auberdine Village Coun",
    isForever = false,
  },
  [491] = {
    id = 491,
    title = "Wand to Bethor",
    reqLevel = 12,
    questLevel = 18,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Object: Dusty Shelf",
    objectives = "Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.",
    rewards = "1,700 XP",
    tip = "Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep.\n\nHere.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it.",
    isForever = false,
  },
  [8368] = {
    id = 8368,
    title = "Battle of Warsong Gulch",
    reqLevel = 10,
    questLevel = 19,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "1,450 XP • 11s",
    tip = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!",
    isForever = false,
  },
