  [4733] = {
    id = 4733,
    title = "Beached Sea Creature",
    reqLevel = 13,
    questLevel = 19,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Creature",
    objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "730 XP • 5s",
    tip = "The remains of what appear to be a giant thresher have washed ashore on the rocky inlet of the Twilight Shore.  The thresher is several times larger than any of the other threshers spotted in these parts.  Wherever it came from, this creature would not seem to have been native to Darkshore.\n\nThough the creature has been picked apart in places, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.",
    isForever = false,
  },
  [4731] = {
    id = 4731,
    title = "Beached Sea Turtle",
    reqLevel = 13,
    questLevel = 19,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Turtle",
    objectives = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "730 XP • 5s",
    tip = "Another set of sea turtle remains lie beached on the coastline.  This set of remains has an abandoned carriage half buckled to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Powerful Greymist murlocs have made the carcass of this creature their current home.\n\nIn the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.",
    isForever = false,
  },
  [4732] = {
    id = 4732,
    title = "Beached Sea Turtle",
    reqLevel = 13,
    questLevel = 19,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Object: Beached Sea Turtle",
    objectives = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
    rewards = "730 XP • 5s",
    tip = "You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been picked nearly clean by Greymist murlocs, the very ones who now have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.",
    isForever = false,
  },
  [6461] = {
    id = 6461,
    title = "Blood Feeders",
    reqLevel = 13,
    questLevel = 19,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Xen'Zilla",
    objectives = "Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters.",
    rewards = "1,450 XP • 11s",
    tip = "We Trolls here at Malaka'Jin have prospered from the land; Stonetalon Mountain offers great hunting for us to live on.\n\nLately, we have attracted the wrong dinner guests... the spiders in these mountains have been raiding our camps at night looking to steal our hunt.\n\nIf you were to help us kill off these ghastly beasts we at Malaka'Jin would be in your debt. Spiders are everywhere in Stonetalon - just head north from here and you will see what I am talking about.",
    isForever = false,
  },
  [8372] = {
    id = 8372,
    title = "Fight for Warsong Gulch",
    reqLevel = 10,
    questLevel = 19,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "1,450 XP • 11s",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
    isForever = false,
  },
  [8386] = {
    id = 8386,
    title = "Fight for Warsong Gulch",
    reqLevel = 10,
    questLevel = 19,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "725 XP",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest. There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack. Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N! For the Alliance!",
    isForever = false,
  },
  [8846] = {
    id = 8846,
    title = "Five Signets for War Supplies",
    reqLevel = 10,
    questLevel = 19,
    faction = "Alliance",
    zone = "Battlegrounds",
    npc = "Field Marshal Snowfall",
    objectives = "Well then, it's settled; here are your supplies, $c. If you wish to do an additional exchange, then I am prepared to authorize it. Just give me the word and I'll make it happen.\n\nKeep up the good work, <player>. We need all the materiel we can muster if we're going to win this thing. If we all do our part, then victory shall be ours for the taking!",
    rewards = "Experience & Faction Reputation",
    tip = "Ah, here for additional supplies for yourself, are you?  Well, I can certainly understand the need for additional materiel... just take a look around if you need any proof.\n\nI'll issue you some additional supplies, but you'll need to give me an appropriate number of commendation signets in exchange.  You won't receive any recognition for surrendering the signets in this manner, but you might find something useful that will help keep you alive when battle is finally upon us.",
    isForever = false,
  },
  [8851] = {
    id = 8851,
    title = "Five Signets for War Supplies",
    reqLevel = 10,
    questLevel = 19,
    faction = "Horde",
    zone = "Battlegrounds",
    npc = "Warlord Gorchuk",
    objectives = "Well then, it's settled; here are your supplies, $c. If you wish to do an additional exchange, then I am prepared to authorize it. Just give me the word and I'll make it happen.\n\nKeep up the good work, <player>. We need all the materiel we can muster if we're going to win this thing. If we all do our part, then victory shall be ours for the taking!",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [1062] = {
    id = 1062,
    title = "Goblin Invaders",
    reqLevel = 13,
    questLevel = 19,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Seereth Stonebreak",
    objectives = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.",
    rewards = "1,450 XP • 11s",
    tip = "The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!\n\nHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work--show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...\n\nViolence.",
    isForever = false,
  },
  [852] = {
    id = 852,
    title = "Hezrul Bloodmark",
    reqLevel = 11,
    questLevel = 19,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Regthar Deathgate",
    objectives = "Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.",
    rewards = "1,100 XP • 8s",
    tip = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens.  He is fierce, brutal and cunning.  Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.\n\nSo kill him.  As with Barak and Verog, bring me Hezrul's Head.\n\nHe leads his people from the Lushwater Oasis, to the south.",
    isForever = false,
  },
  [882] = {
    id = 882,
    title = "Ishamuhale",
    reqLevel = 10,
    questLevel = 19,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Jorn Skyseer",
    objectives = "Bring Ishamuhale's Fang to Jorn at Camp Taurajo.",
    rewards = "1,800 XP",
    tip = "Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill.\n\nAnd you will learn of his nature, $N, for your path now follows the taloned tracks of Ishamuhale.\n\nBegin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it.\n\nBe ready when he comes.",
    isForever = false,
  },
  [255] = {
    id = 255,
    title = "Mercenaries",
    reqLevel = 15,
    questLevel = 19,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Magistrate Bluntnose",
    objectives = "Magistrate Bluntnose of Thelsamar has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers.",
    rewards = "1,800 XP • 20s",
    tip = "Two months just to hear from Ironforge that we'll be spared a handful of soldiers for our own defense, and another two months until they arrive! Bad enough that our town goes unprotected, but the excavation and the dam--the dam!--are open to attacks as well.\n\nI've no choice then, it seems. I'll need hired arms.\n\nHow about you? You seem a likely sort, $c. A group of ogres has set up camp on the northeast of the lake. Perhaps you will be the one to remove the threat to our town?",
    isForever = false,
  },
  [6442] = {
    id = 6442,
    title = "Naga at the Zoram Strand",
    reqLevel = 14,
    questLevel = 19,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Marukai",
    objectives = "Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.",
    rewards = "1,450 XP",
    tip = "There is evil lurking here along the coast, $r.\n\nIt is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must defend the land we have worked so hard to claim as our own.\n\nReturn to me with 20 of their heads! Throw the naga back to the depths!",
    isForever = false,
  },
  [991] = {
    id = 991,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 19,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Raene Wolfrunner",
    objectives = "Find Teronis in Ashenvale.",
    rewards = "1,450 XP",
    tip = "$N, a longtime friend of mine is also aiding the Sentinels here in Ashenvale, but he has yet to return.\n\nHe had leads on finding an item that he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left here, he mentioned seeking out a gem for the rod.\n\nHe mentioned the gem possibly being hidden at the shrine in Lake Falathim at the base of the mountain to the west. The gem was being held there before it was overrun.\n\nFind my friend, $N, plea",
    isForever = false,
  },
  [6541] = {
    id = 6541,
    title = "Report to Kadrak",
    reqLevel = 17,
    questLevel = 19,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Thork",
    objectives = "Report to Kadrak at the watch tower in northern Barrens.",
    rewards = "145 XP",
    tip = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.",
    isForever = false,
  },
  [6542] = {
    id = 6542,
    title = "Report to Kadrak",
    reqLevel = 17,
    questLevel = 19,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Darn Talongrip",
    objectives = "Report to Kadrak at the watch tower in northern Barrens.",
    rewards = "145 XP",
    tip = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.",
    isForever = false,
  },
  [3924] = {
    id = 3924,
    title = "Samophlange Manual",
    reqLevel = 10,
    questLevel = 19,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Rilli Greasygob",
    objectives = "Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.",
    rewards = "1,800 XP",
    tip = "I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few...\n\nBoss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too.",
    isForever = false,
  },
  [152] = {
    id = 152,
    title = "The Coast Isn't Clear",
    reqLevel = 10,
    questLevel = 19,
    faction = "Both",
    zone = "Westfall",
    npc = "Captain Grayson",
    objectives = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse.",
    rewards = "1,450 XP • 11s",
    tip = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.",
    isForever = false,
  },
  [6543] = {
    id = 6543,
    title = "The Warsong Reports",
    reqLevel = 17,
    questLevel = 19,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Kadrak",
    objectives = "Open the Bundle of Reports.  Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.",
    rewards = "1,800 XP • 20s",
    tip = "I recently deployed a few scouts into Ashenvale and I need a runner to take them their orders, and bring me back a report of what they have observed.\n\nYour first stop should be the Zoram'gar Outpost, along the coast to the west, at the Zoram Strand, to locate the first runner. You also need to stop at Splintertree Post, to the north, and along the road to the east, near Azshara. You will find a scout and an outrider there.\n\nGive them each a report, and from them, get an update on their findings.",
    isForever = false,
  },
  [1008] = {
    id = 1008,
    title = "The Zoram Strand",
    reqLevel = 14,
    questLevel = 19,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Shindrell Swiftfire",
    objectives = "Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar.",
    rewards = "1,450 XP • 11s",
    tip = "There is evil lurking on our northwestern coast, known as the Zoram Strand.\n\nIt is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas.  It has been lost to the night elves for ages.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must slay these fiends and throw them back to the depths!\n\nReturn to me when your mission is complete.",
    isForever = false,
  },
  [990] = {
    id = 990,
    title = "Trek to Ashenvale",
    reqLevel = 15,
    questLevel = 19,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Sentinel Selarin",
    objectives = "Find Raene Wolfrunner in Ashenvale.",
    rewards = "365 XP",
    tip = "$N, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there.\n\nHead south from here and stay close to the road--you'll find your way there without issue if you follow those directions.",
    isForever = false,
  },
