  [530] = {
    id = 530,
    title = "A Husband's Revenge",
    reqLevel = 10,
    questLevel = 20,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Raleigh Andrean",
    objectives = "Kill Valdred Moray.\n\nBring his hands to Raleigh Andrean in the Undercity.",
    rewards = "1,550 XP • 12s",
    tip = "Valdred, once my good friend, was my wife's murderer.  Although I am incapable of grieving, I do yearn for revenge.  If you kill Valdred and bring me his cursed hands, then I will reward you.\n\nI last heard he was at the Greymane Wall in southern Silverpine, trying to flee into the kingdom of Gilneas.",
    isForever = false,
  },
  [5641] = {
    id = 5641,
    title = "A Lack of Fear",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "High Priest Rohan",
    objectives = "Speak to High Priest Rohan in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "$N, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.",
    isForever = false,
  },
  [5645] = {
    id = 5645,
    title = "A Lack of Fear",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "High Priestess Laurena",
    objectives = "Speak to High Priest Rohan in Ironforge.",
    rewards = "390 XP",
    tip = "$N, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.",
    isForever = false,
  },
  [5647] = {
    id = 5647,
    title = "A Lack of Fear",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Priestess Alathea",
    objectives = "Speak to High Priest Rohan in Ironforge.",
    rewards = "390 XP",
    tip = "Your race is so very strong, $N. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to not only finding your true origins, but find great confidence that you are on the right path in so many things. That feeling must make you feel so triumphant.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priest Rohan in the Mystic Ward. I would not keep him waiting. May Elune guide your travels.",
    isForever = false,
  },
  [986] = {
    id = 986,
    title = "A Lost Master",
    reqLevel = 10,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Terenthis",
    objectives = "Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine.",
    rewards = "1,550 XP",
    tip = "$N, your skills have already helped me in my endeavor. Could I impose on you again to help Grimclaw and his master Volcor? In addition, I can craft you a magical cloak that will allow you to walk unhindered by Darkshore's creatures while you look for him.\n\nTo create the cloak, I'll need five fine moonstalker pelts from a moonstalker sire or matriarch to have enough material. The cats can be found near Wildbend River to the south, or even farther south near Ashenvale.",
    isForever = false,
  },
  [993] = {
    id = 993,
    title = "A Lost Master",
    reqLevel = 10,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Terenthis",
    objectives = "Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak.",
    rewards = "780 XP",
    tip = "The cloak is complete, $N. The time has come to find Volcor. I can only hope we are in time.\n\nThe cloak's magic, once invoked, will not last long; perhaps five minutes. It will be up to you to know when to use it: I would suggest waiting until you find Grimclaw.\n\nIf what he has told me is true, you will find his master in a cave south of here. Grimclaw will be alongside the road waiting for you. Signal to him by waving when you see him, and he'll point the way towards his master.",
    isForever = false,
  },
