    isForever = false,
  },
  [899] = {
    id = 899,
    title = "Consumed by Hatred",
    reqLevel = 14,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Mankrik",
    objectives = "Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.",
    rewards = "1,950 XP",
    tip = "Perhaps you know the pain of uncertainty, perhaps not, $c. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. Perhaps instead of heading north to the Crossroads I should have headed to Taurajo.\n\nYou, $c--you  could help me.\n\nKill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths tog",
    isForever = false,
  },
  [4021] = {
    id = 4021,
    title = "Counterattack!",
    reqLevel = 11,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Regthar Deathgate",
    objectives = "Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.",
    rewards = "1,950 XP • 25s",
    tip = "The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!\n\nFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.\n\nWe're counting on yo",
    isForever = false,
  },
  [913] = {
    id = 913,
    title = "Cry of the Thunderhawk",
    reqLevel = 10,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Jorn Skyseer",
    objectives = "Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.",
    rewards = "1,950 XP",
    tip = "The thunderhawk, $N, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt.\n\nDo this, and your time with me will near its end.",
    isForever = false,
  },
  [2458] = {
    id = 2458,
    title = "Deep Cover",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Shenthul",
    objectives = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.",
    rewards = "1,150 XP",
    tip = "The Venture Company... Perhaps you have heard of them?\n\nFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.\n\nRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.\n\nWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand.",
    isForever = false,
  },
  [1069] = {
    id = 1069,
    title = "Deepmoss Spider Eggs",
    reqLevel = 15,
    questLevel = 20,
    faction = "Both",
    zone = "The Barrens",
    npc = "Mebok Mizzyrix",
    objectives = "Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.",
    rewards = "1,950 XP • 25s",
    tip = "Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs.\n\nI smell an opportunity!\n\nIn Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle!\n\nIn Windshear Crag, the eggs will be clustered under what trees remain.\n\nIn Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...",
    isForever = false,
  },
  [1472] = {
    id = 1472,
    title = "Devourer of Souls",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Carendin Halgar",
    objectives = "Speak with Godrick Farsan in the Temple of the Damned.",
    rewards = "155 XP",
    tip = "A succubus is a devourer of souls, destroyer of hearts, tempter of men. A creature of profound evil and of singular mind.\n\nIt cannot be brought into our world without a stimulus.\n\nThus we use its own strength against it. With the hearts of good men, pure men, loving men, the succubus will be unable to resist, and will cross into our world. Then you can dominate it, and make it your own.\n\nSpeak with my assistant, Godrick Farsan, within the Temple. He will help you find your bait.",
    isForever = false,
  },
  [1507] = {
    id = 1507,
    title = "Devourer of Souls",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Gan'rul Bloodeye",
    objectives = "Speak with Cazul in the Cleft of Shadow.",
    rewards = "155 XP",
    tip = "The time has come for you to learn more of the summoning magics. You will learn to summon a succubus, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.\n\nA succubus can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.\n\nA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not kn",
    isForever = false,
  },
  [1716] = {
    id = 1716,
    title = "Devourer of Souls",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Gakin the Darkbinder",
    objectives = "Speak with Takar the Seer in the Barrens.",
    rewards = "780 XP",
    tip = "A succubus is a devourer of souls, destroyer of hearts, and dominator of minds. It knows nothing but evil.\n\nThis will be the creature you will learn to summon and control, but it cannot be brought into our world without a stimulus.\n\nWith a symbol of love as bait, it will surely answer your call. Then you can defeat it, and make it your tool.\n\nIt will be hard to find something of this nature, though. You should speak with Takar the Seer. You will find him in the Barrens of Kalimdor near Camp Taur",
    isForever = false,
  },
  [5644] = {
    id = 5644,
    title = "Devouring Plague",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Miles Welsh",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "390 XP",
    tip = "Ah, a wonderful day for you, $N. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy.\n\nI will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days.\n\nGo back to Aelthalyste in the Undercity, $N. She will be awaiting you in the War Quarter.",
    isForever = false,
  },
  [5646] = {
    id = 5646,
    title = "Devouring Plague",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Ur'kyo",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "390 XP",
    tip = "Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe.\n\nYou return to the Undercity, $N. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.",
    isForever = false,
  },
  [5679] = {
    id = 5679,
    title = "Devouring Plague",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Aelthalyste",
    objectives = "Speak to Aelthalyste in the Undercity.",
    rewards = "Experience & Faction Reputation",
    tip = "Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe.\n\nYou return to the Undercity, $N. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.",
    isForever = false,
  },
  [1515] = {
    id = 1515,
    title = "Dogran's Captivity",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Grunt Logmar",
    objectives = "Bring Ken'zigla's Draught to Dogran in the Barrens.",
    rewards = "1,150 XP",
    tip = "You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own.\n\nDogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds.\n\nGood luck.",
    isForever = false,
  },
  [93] = {
    id = 93,
    title = "Dusky Crab Cakes",
    reqLevel = 17,
    questLevel = 20,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Chef Grual",
    objectives = "Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire.",
    rewards = "780 XP",
    tip = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider legs!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!  Bring me Gooey Spider Legs and I'll whip you up a few of them.\n\nI hear Venom Web Spiders are a good source - they nest to the north, between the foothills and the river.",
    isForever = false,
  },
  [6481] = {
    id = 6481,
    title = "Earthen Arise",
    reqLevel = 14,
    questLevel = 20,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Mor'rogal",
    objectives = "Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.",
    rewards = "1,550 XP",
    tip = "You have uncovered a dark threat to the land, $c. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc.\n\nI have changed the mixture of the Resonite crystals that you gathered with my shamanistic powers. Take the enchanted Resonite crystal and smash open the Resonite cask, which houses the Earthen.\n\nWhen awakened, Goggeroc will be weakened... Slay him, $N!",
    isForever = false,
  },
  [5672] = {
    id = 5672,
    title = "Elune's Grace",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Priestess Alathea",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "Experience & Faction Reputation",
    tip = "A wonderful day has come, $N. You've reached the age in which our <priests or priestesses> are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.",
    isForever = false,
  },
  [5673] = {
    id = 5673,
    title = "Elune's Grace",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "High Priestess Laurena",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "390 XP",
    tip = "You know you have access to any of our trainers at any time, $N, but there are some things that we cannot pass on to you. One of those things are the teachings of your goddess Elune. She gives special abilities to her faithful, and if I'm not mistaken, it is time for you to return home to your Temple of the Moon to be tested.\n\nReturn there when you can and speak to Priestess Alathea.",
    isForever = false,
  },
  [5674] = {
    id = 5674,
    title = "Elune's Grace",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "Class Trainer",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "390 XP",
    tip = "A wonderful day has come, $N. You've reached the age in which our $gpriests:priestesses; are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.",
    isForever = false,
  },
  [5675] = {
    id = 5675,
    title = "Elune's Grace",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Priest Class Quests",
    npc = "High Priest Rohan",
    objectives = "Speak to Priestess Alathea in Darnassus.",
    rewards = "390 XP",
    tip = "Time's a wastin', $glad:lass;. It's time for you to return home to Darnassus. Priestess Alathea's sent word here that you're to return there for training. Seems they feel you're ready to be tested much like those who serve the Light. You should head out whenever you can. Alathea's message said that she'd be waitin' for you in the Temple of the Moon. Good luck.",
    isForever = false,
  },
  [995] = {
    id = 995,
    title = "Escape Through Stealth",
    reqLevel = 10,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Volcor",
    objectives = "Escape the Furbolg cave and meet Terenthis in Auberdine.",
    rewards = "780 XP • 6s",
    tip = "All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready.\n\nRemember, after you've escaped, meet Terenthis back in Auberdine. I'll head there on my own since I'll probably be moving faster than you.",
    isForever = false,
  },
  [1132] = {
    id = 1132,
    title = "Fiora Longears",
    reqLevel = 18,
    questLevel = 20,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Red Jack Flint",
    objectives = "Speak with Fiora Longears in Theramore.",
    rewards = "780 XP",
    tip = "Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!\n\nOh, I wish I had your fortune, good $c, for I see the sea in your future!\n\nIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Theramore.  Speak there with my partner, the elf, Fiora Longears.\n\nShe'll start you on your Kalimdor adventure!",
    isForever = false,
  },
  [898] = {
    id = 898,
    title = "Free From the Hold",
    reqLevel = 13,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Gilthares Firebough",
    objectives = "Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.",
    rewards = "1,950 XP • 25s",
    tip = "Finally! Someone to rescue me!\n\nI can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor. I was called an enemy and threat to the Alliance.\n\nMe! A threat to their great sham of an Alliance? I was a deckhand on a moonshine transport between Ratchet and Booty Bay.\n\nEnough talk. Help me get back to Ratchet will you? Let me know when you're ready and we'll make our break.",
    isForever = false,
  },
  [1717] = {
    id = 1717,
    title = "Gakin's Summons",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Lago Blackwrench",
    objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
    rewards = "390 XP",
    tip = "$n! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you.\n\nIt's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.",
    isForever = false,
  },
  [2098] = {
    id = 2098,
    title = "Gyromast's Retrieval",
    reqLevel = 14,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Gelkak Gyromast",
    objectives = "Find and return the three pieces of Gelkak's Key to Gelkak Gyromast.",
    rewards = "1,550 XP • 12s",
    tip = "A pirate's life ain't an easy one, landlubber. It ain't all about plunderin' and booze! Alas, me ship be sunk just off shore thanks to them pesky Threshadons.\n\nWhat I be needin' is me first mate back in workin' order!\n\nWhen I washed up'n shore, the key for me first mate broke on the rocks and was pilfered by the beasties of Darkshore. Out of the corner of me eyes I saw some of them Ragin' Crawlers, Ferocious Foreststrider, and murloc rummaging through the wreckage....",
    isForever = false,
  },
  [2078] = {
    id = 2078,
    title = "Gyromast's Revenge",
    reqLevel = 14,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Gelkak Gyromast",
    objectives = "Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.",
    rewards = "1,150 XP • 9s",
    tip = "Landlubber, ye needs to find me first mate.\n\nTake this'n key, puts it in his gulliver an' bring him back here to serve the Cap'n.\n\nThem murlocs an' their chief ain't gonna be too happy once me first mate gets a hold of em!",
    isForever = false,
  },
  [1476] = {
    id = 1476,
    title = "Hearts of the Pure",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Godrick Farsan",
    objectives = "Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned.",
    rewards = "1,550 XP",
    tip = "Men of honor and goodness? Does such a man exist?\n\nIt took much research, but through bits of overheard stories, I managed to find two men that should do.\n\nThe first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refugees, whom are refused by their kin at the Greymane Wall.\n\nThe other is Comar Villard, a man who remains faithful to his lost love, wandering the Wetlands for a sign of his wife.\n\nDeliver their hearts to Carendin. But first, let me show you your quarry.",
    isForever = false,
  },
  [1738] = {
    id = 1738,
    title = "Heartswood",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Takar the Seer",
    objectives = "Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
    rewards = "1,550 XP",
    tip = "In preparation for your coming, I used my sight to look over the world and through the mists of time. I have found what it is you seek.\n\nIn the War of the Ancients, two lovers fell together in battle. Where they took their last breaths, a tree known as the heartswood grew, a symbol of their undying love.\n\nThat should be enough to tempt a succubus. You will find it in the ruins of Ordil'Aran in the northwestern part of the forest of Ashenvale.",
    isForever = false,
  },
  [2480] = {
    id = 2480,
    title = "Hinott's Assistance",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Serge Hinott",
    objectives = "Wait for Serge Hinott to complete the cure.",
    rewards = "155 XP",
    tip = "I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.\n\nSo, I am to cure you of this and then teach you how to make use of the poison?\n\nGive me a few moments to examine the toxin, $N.",
    isForever = false,
  },
  [5] = {
    id = 5,
    title = "Jitters' Growling Gut",
    reqLevel = 17,
    questLevel = 20,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Jitters",
    objectives = "Speak with Chef Grual.",
    rewards = "390 XP",
    tip = "Pro-tip: Leads directly to Mistmantle Manor, which receives expanded questing and dungeon connections in WoW: Forever!",
    isForever = false,
  },
  [1133] = {
    id = 1133,
    title = "Journey to Astranaar",
    reqLevel = 18,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Fiora Longears",
    objectives = "Speak with Shindrell Swiftfire in Astranaar.",
    rewards = "Experience & Faction Reputation",
    tip = "If you're fresh off the boat from Menethil, then the first thing you should do is... go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services.\n\nBut don't bother mentioning who sent you.  Shindrell does not know me...",
    isForever = false,
  },
  [493] = {
    id = 493,
    title = "Journey to Hillsbrad Foothills",
    reqLevel = 19,
    questLevel = 20,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Apothecary Renferrel",
    objectives = "Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.",
    rewards = "1,150 XP • 9s",
    tip = "The Royal Apothecary Society is under extreme pressure from the Dark Lady to develop a New Plague.  We are working diligently and have made much progress.  It is our belief that the success will be achieved much faster if we share information amongst the Society.\n\nFor that reason I want you to deliver my latest findings to Apothecary Lydon in Tarren Mill, a small town nestled in the Hillsbrad Foothills.  The journey will be a long one.\n\nHead south and stick to the roads.  Follow the signs closel",
    isForever = false,
  },
  [1511] = {
    id = 1511,
    title = "Ken'zigla's Draught",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Ken'zigla",
    objectives = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.",
    rewards = "1,550 XP",
    tip = "I figured there might be another coming to get the draught, so I prepared it anyways.\n\nHere you go, $n. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half.\n\nAnyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is.",
    isForever = false,
  },
  [1060] = {
    id = 1060,
    title = "Letter to Jin'Zil",
    reqLevel = 15,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Darsok Swiftdagger",
    objectives = "Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.",
    rewards = "1,550 XP",
    tip = "You've done so well for me, $n. You're a regular lucky rabbit's foot and there's something I want you to see.\n\nThe harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil.\n\nHe'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place",
    isForever = false,
  },
  [4921] = {
    id = 4921,
    title = "Lost in Battle",
    reqLevel = 14,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Mankrik",
    objectives = "Find Mankrik's wife and then return to him in the Crossroads.",
    rewards = "1,150 XP • 9s",
    tip = "We battled in a small tauren camp when we were separated--she held three of the Bristlebacks off by herself. But the odds began to overwhelm us. I led some away only to see her overwhelmed by newcomers. In my rage, I turned to face my enemies, but they brought me down easily with their vast numbers.\n\nI awoke to a tauren druid tending my wounds--he had come across me on the Gold Road as I fell.\n\nPlease, $c, find some sign of my wife.",
    isForever = false,
  },
  [1512] = {
    id = 1512,
    title = "Love's Gift",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Grunt Dogran",
    objectives = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.",
    rewards = "390 XP",
    tip = "Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice.\n\nLeave me, $n. And thank you. I may end my life in glorious battle, instead of a lifeless husk.\n\nAnd please, I would ask you not to tell my mate of this... I do not want guilt on her conscience.",
    isForever = false,
  },
  [2360] = {
    id = 2360,
    title = "Mathias and the Defias",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Master Mathias Shaw",
    objectives = "Travel to Westfall and find Agent Kearnen for your debriefing.",
    rewards = "390 XP",
    tip = "Not a moment too soon, $N. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.\n\nIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.\n\nGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.\n\n...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence.",
    isForever = false,
  },
  [951] = {
    id = 951,
    title = "Mathystra Relics",
    reqLevel = 12,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Onu",
    objectives = "Bring 6 Mathystra Relics to Onu at the Grove of the Ancients.",
    rewards = "1,950 XP",
    tip = "The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!  It is heavily cursed and tainted by the corruption of the Twilight's Hammer, but it seems the cult is using ancient elven magic to bring their old masters back to our world.\n\nTravel to the ruins of Mathystra to the northeast, and search for ancient relics among the grass and broken stones.  Through their study, we may divine how the Twilight's Hammer intends to exploit the magic of the elves.",
    isForever = false,
  },
  [150] = {
    id = 150,
    title = "Murloc Poachers",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Dockmaster Baren",
    objectives = "Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire.",
    rewards = "1,550 XP",
    tip = "Murlocs are becoming a problem.  Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!  We need them gone before they eat all the fish in the lake!\n\nHunt murlocs!  Bring me eight of their fins and I might have something for you...",
    isForever = false,
  },
  [1509] = {
    id = 1509,
    title = "News of Dogran",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Zankaja",
    objectives = "Speak with Gazrog at the Crossroads.",
    rewards = "390 XP",
    tip = "My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.\n\nI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.\n\nNow it's been a week after he should have returned, and I have received no word from him...\n\nPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.",
    isForever = false,
  },
  [1510] = {
    id = 1510,
    title = "News of Dogran",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Gazrog",
    objectives = "Speak with Ken'zigla at the Malaka'jin.",
    rewards = "780 XP",
    tip = "He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.\n\nThey sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet.",
    isForever = false,
  },
  [167] = {
    id = 167,
    title = "Oh Brother. . .",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "The Deadmines",
    npc = "Wilder Thistlenettle",
    objectives = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.",
    rewards = "1,550 XP",
    tip = "We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us. I got out but the others... well... the others haven't been heard from.\n\nYou look like you might have better luck in there. If you could look for my brother, I'd be thankful.  He always carried his Explorers' League Badge. If you can't find him, that badge would at least give me some peace of mind.",
    isForever = false,
  },
  [1020] = {
    id = 1020,
    title = "Orendil's Cure",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Orendil Broadleaf",
    objectives = "Bring Orendil's Cure to Pelturas Whitemoon in Astranaar.",
    rewards = "1,950 XP • 25s",
    tip = "$N, I have created a cure that I believe will help the afflicted child.  Take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south, then east.",
    isForever = false,
  },
  [163] = {
    id = 163,
    title = "Raven Hill",
    reqLevel = 17,
    questLevel = 20,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Elaine Carevin",
    objectives = "Find out what is haunting Raven Hill.",
    rewards = "390 XP",
    tip = "Something's amiss at Raven Hill, $n. Calor swears that someone--or something--is haunting the buildings there. Two nights running he's noticed the shadows moving, and the third before that he says he saw light in one of the windows.\n\nIf, as you say, you care about the safety of Duskwood, find out what monster haunts in Raven Hill.",
    isForever = false,
  },
