  [876] = {
    id = 876,
    title = "Serena Bloodfeather",
    reqLevel = 12,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Darsok Swiftdagger",
    objectives = "Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.",
    rewards = "1,950 XP",
    tip = "You did so well with the lieutenants and underlings that I'd like you to do one last thing for me.\n\nSerena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago. Apparently, these attacks on the Horde caravans are revenge for her sister's death.\n\nI need you to slit her throat and bring me back her head. I want to place it on the next caravan we send out... Give those harpies something to think about.",
    isForever = false,
  },
  [5642] = {
    id = 5642,
    title = "Shadowguard",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Miles Welsh",
    objectives = "Speak to Ur'kyo in Orgrimmar.",
    rewards = "390 XP",
    tip = "Something important is up in Orgrimmar, $N.\n\nThe normal messengers that come through here looking for troll priests usually are very casual. This time, they seemed to be in much more a hurry. Don't dally too long in Thunder Bluff. I'd return to the Valley of Spirits as soon as possible.",
    isForever = false,
  },
  [5643] = {
    id = 5643,
    title = "Shadowguard",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Priest Class Quests",
    npc = "Aelthalyste",
    objectives = "Speak to Ur'kyo in Orgrimmar.",
    rewards = "390 XP",
    tip = "Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.",
    isForever = false,
  },
  [5680] = {
