    zone = "Priest Class Quests",
    npc = "Ur'kyo",
    objectives = "Speak to Ur'kyo in Ogrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.",
    isForever = false,
  },
  [1823] = {
    id = 1823,
    title = "Speak with Ruga",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Torm Ragetotem",
    objectives = "Speak with Ruga Ragetotem.",
    rewards = "155 XP",
    tip = "You are a warrior of skill and growing renown.  Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.\n\nHe awaits those warriors who answer his call.",
    isForever = false,
  },
  [1825] = {
