    title = "Speak with Thun'grim",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Ruga Ragetotem",
    objectives = "Speak with Thun'grim Firegaze in the Barrens.",
    rewards = "780 XP",
    tip = "Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde.  He would like to fashion for you a suit of armor, and bids you speak with him immediately.\n\nThun'grim is camped east of the Crossroads in the Barrens.",
    isForever = false,
  },
