  [729] = {
    id = 729,
    title = "The Absent Minded Prospector",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Archaeologist Hollee",
    objectives = "Travel south and check on Prospector Remtravel.",
    rewards = "1,150 XP",
    tip = "What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries.\n\nBut the prospector is rather... um... oblivious ...to his surroundings.\n\nWe had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help.\n\nPlease travel south and see if the prospector is ",
    isForever = false,
  },
  [731] = {
    id = 731,
    title = "The Absent Minded Prospector",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Prospector Remtravel",
    objectives = "Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.",
    rewards = "1,950 XP",
    tip = "So then, Hollee... oh that's right, you are not Hollee. Where's Hollee?\n\nBah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing.\n\nLet me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League.\n\nSo are you ready yet?",
    isForever = false,
  },
  [741] = {
    id = 741,
    title = "The Absent Minded Prospector",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Archaeologist Hollee",
    objectives = "Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.",
    rewards = "1,150 XP",
    tip = "So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him.\n\nHere, $n, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.",
    isForever = false,
  },
  [942] = {
    id = 942,
    title = "The Absent Minded Prospector",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Chief Archaeologist Greywhisker",
    objectives = "Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor.",
    rewards = "1,550 XP",
    tip = "This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow.\n\nLast I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past.\n\nThe ship to Menethil departs from Auber",
    isForever = false,
  },
  [1007] = {
    id = 1007,
    title = "The Ancient Statuette",
    reqLevel = 19,
    questLevel = 20,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Talen",
    objectives = "Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand.",
    rewards = "1,150 XP • 9s",
    tip = "I would charge you with a task, $N.\n\nI was on my small vessel, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws!  I fled, carrying what supplies I could to make this meager camp.\n\nBut when I reached the shore and ran... my prized possession was lost.\n\nPlease, $N, find the site of my ambush, along the coast to the north, and search for an ancient statuette.  It is the reason I have braved the dangers of the Zoram Strand.",
    isForever = false,
  },
  [235] = {
    id = 235,
    title = "The Ashenvale Hunt",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Warcaller Gorlach",
    objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.",
    rewards = "155 XP",
    tip = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!",
    isForever = false,
  },
  [742] = {
    id = 742,
    title = "The Ashenvale Hunt",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Bluff Runner Windstrider",
    objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.",
    rewards = "155 XP",
    tip = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!",
    isForever = false,
  },
  [6382] = {
    id = 6382,
    title = "The Ashenvale Hunt",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Jorn Skyseer",
    objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.",
    rewards = "390 XP",
    tip = "Your strength impresses me, $c.  Your willingness to embrace the hunt gives me confidence that you could move on to bigger game... and bigger challenges.\n\nThe forests of Ashenvale represent a vast untamed wild that the Horde seeks to impose its own will upon, both politically and spiritually.  If you seek to prove yourself in an unproven land, seek the guidance of Senani Thunderheart in Splintertree Post.  The outpost is due north of the path leading from the Barrens.",
    isForever = false,
  },
  [6383] = {
    id = 6383,
    title = "The Ashenvale Hunt",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Senani Thunderheart",
    objectives = "Speak with Senani Thunderheart in Ashenvale.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [1474] = {
    id = 1474,
    title = "The Binding",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Carendin Halgar",
    objectives = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.",
    rewards = "1,550 XP",
    tip = "Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus. \n\nBeware its charms, $n, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command.",
    isForever = false,
  },
  [1513] = {
    id = 1513,
    title = "The Binding",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Gan'rul Bloodeye",
    objectives = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.",
    rewards = "1,150 XP",
    tip = "Take this to the summoning circle in Neeru's tent, $n. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock.\n\nWhen you have defeated it, return the pendant to me so that I might deliver the news to Zankaja.",
    isForever = false,
  },
  [1739] = {
    id = 1739,
    title = "The Binding",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Gakin the Darkbinder",
    objectives = "Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.",
    rewards = "1,150 XP",
    tip = "Using the heartswood core, you will be able to cast a spell at the summoning circle in the crypt below to open a portal for the succubus to pass through.\n\nBe careful, $n, succubi have overrun even the strongest of minds.\n\nOnce you have bested and returned it to the void, return to me and I will show you how to call and control it.",
    isForever = false,
  },
  [89] = {
    id = 89,
    title = "The Everstill Bridge",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Foreman Oslow",
    objectives = "Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire.",
    rewards = "1,550 XP",
    tip = "During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor.  We sent word to Stormwind for a new shipment of materials but a band of Redridge gnolls hijacked the caravan and ran off into the hills behind Lakeshire.\n\nNow we're coming up short on supplies to get this bridge rebuilt.  If you can bring me 5 iron pikes and 5 iron rivets, $N, I'll make sure you're rewarded. \n\nNow let's get to work!",
    isForever = false,
  },
  [891] = {
    id = 891,
    title = "The Guns of Northwatch",
    reqLevel = 13,
    questLevel = 20,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Captain Thalo'thas Brightsun",
    objectives = "Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.",
    rewards = "1,550 XP",
    tip = "Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold!\n\nThose bastards must be dealt with. Their paranoia has them in a state of frenzy. Trigger happy, reckless louts are shooting at anything in their sights.\n\nTravel south along the Merchant Coast to the Hold and lay siege to their forces. Bring me the medals of their soldiers as proof. And for the love of my fleet, slay Captain Fairmount and her overzealous cannoneers!",
    isForever = false,
  },
  [968] = {
    id = 968,
    title = "The Powers Below",
    reqLevel = 10,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Item: Book: The Powers Below",
    objectives = "Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge.",
    rewards = "1,950 XP",
    tip = "Although terribly worn and scratched, the title of this book can still be read upon its cover:\n\nThe Powers Below\n\nInside the book is a listing of unpronounceable names with foreboding titles, methods of worship, and preferred sacrifices...many of which include living, humanoid creatures.\n\nOn the inside cover of the book are the words: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge.  Proprietor: Gerrig Bonegrip.\"\n\nIf Bonegrip sells books like this, perhaps he'll buy this one back.",
    isForever = false,
  },
  [2460] = {
    id = 2460,
    title = "The Shattered Salute",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Shenthul",
    objectives = "Perform the Shattered Salute on Shenthul.",
    rewards = "155 XP",
    tip = "As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.\n\nWatch, learn, repeat.",
    isForever = false,
  },
  [5321] = {
    id = 5321,
    title = "The Sleeper Has Awakened",
    reqLevel = 17,
    questLevel = 20,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Kerlonian Evershade",
    objectives = "Escort Kerlonian Evershade to Liladris Moonriver at Maestra's Post in Ashenvale.",
    rewards = "1,550 XP",
    tip = "I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy...\n\n<yawn>\n\nWould you mind showing me the way? I understand that Maestra's Post is south of here, along the road in Ashenvale. It can be dangerous, so I hope you have some friends that will join us.\n\nLastly, I may fall asleep so if you ever need to wake me, please use my horn. You'll find it in the chest here.",
    isForever = false,
  },
  [1649] = {
    id = 1649,
    title = "The Tome of Valor",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Item: Tome of Valor",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "390 XP",
    tip = "Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.\n\nThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot.",
    isForever = false,
  },
  [1793] = {
    id = 1793,
    title = "The Tome of Valor",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Duthorian Rall",
    objectives = "Speak with Duthorian Rall in Paladin Class Quests.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [1794] = {
