    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Tiza Battleforge",
    objectives = "Speak with Tiza Battleforge in Paladin Class Quests.",
    rewards = "Experience & Faction Reputation",
    tip = "",
