  },
  [2607] = {
    id = 2607,
    title = "The Touch of Zanzil",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Master Mathias Shaw",
    objectives = "Speak with Doc Mixilpixil in the cellar of the Barracks.",
    rewards = "Experience & Faction Reputation",
    tip = "It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, $N.\n\nA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help.",
    isForever = false,
  },
  [2608] = {
    id = 2608,
    title = "The Touch of Zanzil",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Doc Mixilpixil",
    objectives = "- Diagnosis Complete",
    rewards = "155 XP",
    tip = "Oh my, you look like death. Correction - I've seen death, you look worse than death. You, $g sir:miss;, would be what death coughed up at his last physical.\n\nHah! You hear that Noarm? Write that one down!\n\n*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, $N.",
    isForever = false,
  },
  [2609] = {
    id = 2609,
    title = "The Touch of Zanzil",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Doc Mixilpixil",
    objectives = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;.",
    rewards = "1,150 XP",
    tip = "It's unanimous, $N. You've got the 'itis.'\n\nLuckily, I have a cure for the 'itis.'\n\nHere's what I need: One bundle of simple wildflowers, one leaded vial, one bronze tube, and last but certainly not least, one spool of light chartreuse silk thread. Ol' Emma left a spool of it for me at 'The Finest Thread.' You can find the shop along the canals.\n\nHurry along now, $N, and try not to touch anyone until you're cured. Oh, and Dr. Montgomery says you need a shower -- his words, not mine.",
    isForever = false,
  },
  [494] = {
    id = 494,
    title = "Time To Strike",
    reqLevel = 19,
    questLevel = 20,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Deathstalker Lesh",
    objectives = "Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia.",
    rewards = "780 XP • 6s",
    tip = "Be silent and pay attention, $c.\n\nI was sent to this position in order to survey the town of Hillsbrad.  My mission is one of reconnaissance.  It is imperative that you send word to High Executor Darthalia in Tarren Mill at once.  Let her know that I, Deathstalker Lesh, send the following message:\n\n\"The raven's cry from the west doth beckon.\"\n\nFollow the road to the east and pay close attention to the signs.  Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!",
    isForever = false,
  },
  [1999] = {
    id = 1999,
    title = "Tools of the Trade",
    reqLevel = 16,
    questLevel = 20,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Mennet Carkad",
    objectives = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.",
    rewards = "1,550 XP",
    tip = "The wizards of the Kirin Tor at Ambermill have stored away important documents pertaining to the current state of Dalaran. This we know from the admissions of one of our prisoners. Lord Varimathras has placed the duty of recovering them in the hands of the Deathstalkers.\n\nThis task falls to you, $n. You will need some equipment, however, and the knowledge of lockpicking. Speak with Estelle Gendry, our outfitter, and ask her for a set of tools before you set out.",
    isForever = false,
  },
  [1824] = {
    id = 1824,
    title = "Trial at the Field of Giants",
    reqLevel = 20,
    questLevel = 20,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Ruga Ragetotem",
    objectives = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo",
    rewards = "1,550 XP",
    tip = "To pass this trial, you must travel south to the Field of Giants.  There you will find a host of crawling, insect creatures.  They are new to the Barrens and I do not like what they herald.\n\nBring me their still-twitching antennae, and waste no time, $N, for harvested antennae will not twitch for long.  Bring me the antennae in the time allowed, and you will pass the trial.",
    isForever = false,
  },
  [2040] = {
    id = 2040,
    title = "Underground Assault",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "The Deadmines",
    npc = "Shoni the Shilent",
    objectives = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.",
    rewards = "1,550 XP",
    tip = "Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, $N.\n\nDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!",
    isForever = false,
  },
  [271] = {
    id = 271,
    title = "Vyrin's Revenge",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Vyrin Swiftwind",
    objectives = "Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge.",
    rewards = "780 XP",
    tip = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the hills over Thels",
    isForever = false,
  },
  [531] = {
    id = 531,
    title = "Vyrin's Revenge",
    reqLevel = 15,
    questLevel = 20,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Daryl the Youngling",
    objectives = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.",
    rewards = "1,550 XP",
    tip = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!",
    isForever = false,
  },
  [972] = {
