  [1698] = {
    id = 1698,
    title = "Yorus Barleybrew",
    reqLevel = 20,
    questLevel = 20,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Wu Shen",
    objectives = "Speak with Yorus Barleybrew.",
    rewards = "155 XP",
    tip = "Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.",
    isForever = false,
  },
  [1071] = {
    id = 1071,
    title = "A Gnome's Respite",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Gaxim Rustfizzle",
    objectives = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.",
    rewards = "1,650 XP",
    tip = "You see, $N, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.\n\nBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!\n\nI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east",
    isForever = false,
  },
  [1075] = {
    id = 1075,
    title = "A Scroll from Mauren",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Gaxim Rustfizzle",
    objectives = "Find Collin Mauren in Stormwind.",
    rewards = "830 XP",
    tip = "Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?\n\nOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.\n\nBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.",
    isForever = false,
  },
  [94] = {
    id = 94,
    title = "A Watchful Eye",
    reqLevel = 20,
    questLevel = 21,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Theocritus",
    objectives = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.",
    rewards = "1,250 XP",
    tip = "My rival, Morganth, is a vicious mage of great power who lives in the Tower of Ilgalar in Redridge.  I have developed a means of spying on him, the Eye of Azora, and can now view him from afar.\n\nBut to study his thoughts ... I require further aid.\n\nIf you are willing, then take my Glyph of Azora to the Tower of Ilgalar.  Place it upon the Lion Statue near the Tower.\n\nWhen this is done, the power of Azora will grant visions of Morganth's future plans.",
    isForever = false,
  },
  [1072] = {
    id = 1072,
    title = "An Old Colleague",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Gaxim Rustfizzle",
    objectives = "Speak to Lomac Gearstrip in Ironforge.",
    rewards = "830 XP",
    tip = "The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.\n\nAnd for that, we're going to need some potent explosives: Nitromirglyceronium.\n\nThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.\n\nYou talk him into making us some NG-5, I'll get to work on placement for my devices.",
    isForever = false,
  },
  [6284] = {
    id = 6284,
    title = "Arachnophobia",
    reqLevel = 15,
    questLevel = 21,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Object: Wanted Poster: Besseleth",
    objectives = "Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.",
    rewards = "1,650 XP",
    tip = "Warning: Proceed into Sishir Canyon west of here at your own risk.\n\nBesseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair.\n\nMaggran Earthbinder in Sun Rock Retreat has placed a bounty on Besseleth. Slay her and bring proof of your killing to Maggran; there you will receive your reward for disposing this eight-legged menace.",
    isForever = false,
  },
  [516] = {
    id = 516,
    title = "Beren's Peril",
    reqLevel = 16,
    questLevel = 21,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Shadow Priest Allister",
    objectives = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.",
    rewards = "1,250 XP",
    tip = "I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud.\n\nUnfortunately, my information is spotty, at best. They are reported to be hiding in a location known as Beren's Peril. The exact location is unknown, but it appears to be a cave in the hills, near a pocket of Dalaran wizards.\n\nI trust your resourcefulness. Find them, and put them down.",
    isForever = false,
  },
  [20] = {
    id = 20,
    title = "Blackrock Menace",
    reqLevel = 18,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Marshal Marris",
    objectives = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.",
    rewards = "1,650 XP • 13s",
    tip = "Pro-tip: Clear Emperor Thaurissan while keeping Moira crowd-controlled to complete the quest without killing her.",
    isForever = false,
  },
  [5052] = {
    id = 5052,
    title = "Blood Shards of Agamaggan",
    reqLevel = 14,
    questLevel = 21,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Mangletooth",
    objectives = "Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.\n\nCollect more Blood Shards if you want him to bless you with Agamaggan's power.",
    rewards = "1,250 XP",
    tip = "Along with the thorns, the blood affected <snort> other aspects of the earth: blood red stones mixed in with other minerals. The Bristleback dig up these shards and carry them as totems <snort> for strength in battle and as totems for their magics. <snort>\n\nI know the secrets of that magic.\n\nBring Mangletooth one of these blood shards to show you understand. Bring Mangletooth many of the shards, and he will bless you with quilboar magic--the magic of Agamaggan! <snort>",
    isForever = false,
  },
  [469] = {
    id = 469,
    title = "Daily Delivery",
    reqLevel = 18,
    questLevel = 21,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Einar Stonegrip",
    objectives = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.",
    rewards = "830 XP • 7s",
    tip = "Greetings, traveler!\n\nDon't suppose you might be heading in the direction of Menethil, would you? If you're not, I'd suggest you stop there, it's a good place to purchase goods and even have a pint and relax.\n\nNow, if it just so happens that you're heading in that direction, I don't suppose you'd mind taking this bundle of crocolisk skins to James Halloran, the tanner?\n\nI'd do it myself, but my wife's been in quite a mood lately, and I'd like to put off facing her as long as possible.",
    isForever = false,
  },
  [1487] = {
    id = 1487,
    title = "Deviate Eradication",
    reqLevel = 15,
    questLevel = 21,
    faction = "Both",
    zone = "Wailing Caverns",
    npc = "Ebru",
    objectives = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.",
    rewards = "2,050 XP • 25s",
    tip = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.\n\nNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.\n\nWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.\n\nBrave the caverns, $n, and eradicate the deviate spawn.",
    isForever = false,
  },
  [1076] = {
    id = 1076,
    title = "Devils in Westfall",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Collin Mauren",
    objectives = "Bring Dust Devil Debris to Collin Mauren in Stormwind.",
    rewards = "1,650 XP",
    tip = "Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.\n\nI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.\n\nWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.\n\nI'll be here when you return.",
    isForever = false,
  },
  [245] = {
    id = 245,
    title = "Eight-Legged Menaces",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Watcher Dodds",
    objectives = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.",
    rewards = "1,250 XP",
    tip = "Hail, $c. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire.\n\nI hate to ask this of you, but you seem like you might be able to handle them. I can't promise you anything of great value, but I can reward you if you can help root out the filthy bugs.\n\nOh, and a word of advice, you'll want to avoid their venom if you can.",
    isForever = false,
  },
  [1094] = {
    id = 1094,
    title = "Further Instructions",
    reqLevel = 16,
    questLevel = 21,
    faction = "Both",
    zone = "Stonetalon Mountains",
    npc = "Ziz Fizziks",
    objectives = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.",
    rewards = "830 XP",
    tip = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.\n\nSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.",
    isForever = false,
  },
  [1073] = {
    id = 1073,
    title = "Ineptitude + Chemicals = Fun",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Lomac Gearstrip",
    objectives = "Bring 4 Minor Mana Potions and 2 Elixirs of Fortitude to Lomac Gearstrip in Ironforge.",
    rewards = "1,650 XP",
    tip = "Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!\n\nI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.\n\nThere's a problem though: I'm all out.\n\nBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.\n\nThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.",
    isForever = false,
  },
  [1074] = {
    id = 1074,
    title = "Ineptitude + Chemicals = Fun",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Lomac Gearstrip",
    objectives = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.",
    rewards = "830 XP",
    tip = "Here you go, stranger. Take heed with it though... it's volatile stuff.\n\nIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.",
    isForever = false,
  },
  [1070] = {
    id = 1070,
    title = "On Guard in Stonetalon",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Sentinel Thenysil",
    objectives = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.",
    rewards = "830 XP",
    tip = "Hello, $N.\n\nYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.\n\nRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.\n\nWould you find her and report back to me?",
    isForever = false,
  },
  [1085] = {
    id = 1085,
    title = "On Guard in Stonetalon",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Kaela Shadowspear",
    objectives = "Speak to Gaxim.",
    rewards = "165 XP",
    tip = "The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.\n\nThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.\n\nDo not judge Gaxim prematurely; he understands the need for us to work together.\n\nIf you wish to aid us, then start by speaking to Gaxim.\n\nI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.",
    isForever = false,
  },
  [1134] = {
    id = 1134,
    title = "Pridewings of Stonetalon",
    reqLevel = 18,
    questLevel = 21,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Shindrell Swiftfire",
    objectives = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.",
    rewards = "1,650 XP • 13s",
    tip = "We are not in open war with the Horde, but our peace is fragile.  We often find their agents moving against us, but they do so covertly.\n\nOne such advance was revealed to us from hidden sources in Theramore, claiming that the orcs collect venom from the pridewings near Mirkfallon Lake, in the Stonetalon Mountains to the south.  Orc assassins then use the venom on their secret death raids against the Alliance!\n\nIf this is true, then we must stop them, $N.  We must deny them their source of venom.",
    isForever = false,
  },
  [1023] = {
    id = 1023,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 21,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Teronis' Corpse",
    objectives = "Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.",
    rewards = "1,250 XP",
    tip = "As you rummage through Teronis' belongings, you find a journal that is still in good condition.\n\nYou take the journal and leave Teronis' corpse as is.\n\nThe only thing left to do is find the gem Teronis was seeking. Raene mentioned it being in the area. Perhaps the murlocs have it...",
    isForever = false,
  },
  [1024] = {
    id = 1024,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 21,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Raene Wolfrunner",
    objectives = "Find Shael'dryn at the moonwell to the northeast.",
    rewards = "830 XP",
    tip = "You'll have to do the research yourself, but from what notes Teronis has made, it sounds like your next course of action is to find the other pieces of the rod Dartol created. I would start by heading to the moonwell east of Iris Lake. When you're ready, follow the road and turn north when you reach a small sitting area on your left.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.",
    isForever = false,
  },
  [468] = {
    id = 468,
    title = "Report to Mountaineer Rockgar",
    reqLevel = 19,
    questLevel = 21,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Mountaineer Kadrell",
    objectives = "Speak with Mountaineer Rockgar.",
    rewards = "165 XP",
    tip = "Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.  \n\nIf you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower.",
    isForever = false,
  },
  [127] = {
    id = 127,
    title = "Selling Fish",
    reqLevel = 16,
    questLevel = 21,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Dockmaster Baren",
    objectives = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.",
    rewards = "1,250 XP • 10s",
    tip = "Lake Everstill is famous for its spotted sunfish.  There's always demand for them...and I'm running low!\n\nBring me a batch of 10 and I'll barter well for them.  If you can't fish yourself, then...maybe you can get them off the murlocs!",
    isForever = false,
  },
  [1077] = {
    id = 1077,
    title = "Special Delivery for Gaxim",
    reqLevel = 17,
    questLevel = 21,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Collin Mauren",
    objectives = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.",
    rewards = "830 XP",
    tip = "Here you are, $N. This should do nicely.\n\nPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.\n\nFare well.",
    isForever = false,
  },
  [1093] = {
    id = 1093,
    title = "Super Reaper 6000",
    reqLevel = 16,
    questLevel = 21,
    faction = "Both",
    zone = "Stonetalon Mountains",
    npc = "Ziz Fizziks",
    objectives = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.",
    rewards = "1,650 XP",
    tip = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!\n\nLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!\n\nTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.",
    isForever = false,
  },
  [455] = {
    id = 455,
    title = "The Algaz Gauntlet",
    reqLevel = 19,
    questLevel = 21,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Mountaineer Rockgar",
    objectives = "Traverse Dun Algaz.\n\nKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.\n\nReport to Valstag Ironjaw in Menethil Harbor.",
    rewards = "1,250 XP • 10s",
    tip = "Orcs of the Dragonmaw clan have a haven in the Wetlands.  And now they have expanded into Dun Algaz!  We can't let them keep their foothold here or Loch Modan will be cut off from Menethil Harbor, our port and stronghold in the Wetlands.\n\nBreak through Dun Algaz to the Wetlands beyond, and kill some orcs for good measure!  Report to Valstag Ironjaw in Menethil Harbor.\n\nMenethil is through Dun Algaz, then north along the road, then west at the fork.\n\nWe're counting on you, $N.  Do not fail.",
    isForever = false,
  },
  [463] = {
    id = 463,
    title = "The Greenwarden",
    reqLevel = 20,
    questLevel = 21,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "First Mate Fitzsimmons",
    objectives = "Find the Greenwarden.",
    rewards = "830 XP",
    tip = "You've heard of the Greenwarden?  You're not looking for him, are you?  Well I say you're crazy if you are, but who am I to keep a fool from $ghis:her; death?\n\nIf you are seeking that beast, then I hear he is in the marsh, east of the road where it forks to Dun Modr.  He's lurking there among the crocs...and worse!\n\nAnd leave your money here.  You won't need it where you're going...and you don't want to chip ol' Greenie's tooth on your gold when he bites you in half, do you?",
    isForever = false,
  },
  [1653] = {
    id = 1653,
    title = "The Test of Righteousness",
    reqLevel = 20,
    questLevel = 21,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Duthorian Rall",
    objectives = "Speak to Jordan Stilwell in Ironforge",
    rewards = "830 XP",
    tip = "Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.\n\nJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.\n\nHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air.",
    isForever = false,
  },
  [970] = {
    id = 970,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 21,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Delgren the Purifier",
    objectives = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.",
    rewards = "1,650 XP",
    tip = "Balthule's letter is dire. This Cult of the Dark Strand is a thorn in my side that must be removed. I have been dealing with some of the Dark Strand scum northeast of here at Ordil'Aran. One of their number possesses a soul gem that I believe holds the secret to the cult's power.\n\nBring it to me, and I will be able to decipher the secrets held within.",
    isForever = false,
  },
  [276] = {
    id = 276,
    title = "Tramping Paws",
    reqLevel = 20,
    questLevel = 21,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Rethiel the Greenwarden",
    objectives = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.",
    rewards = "1,250 XP",
    tip = "The Mosshide Gnolls have lived in the Wetlands peacefully for many years, but now grow in numbers.  Their feet stamp flat the fen's bushes and flowers, and their foul axes cut too much wood to fuel their fires.\n\nThey are no longer in balance with the land.  For the Wetlands to survive, the Gnolls must be reduced.\n\nKill 15 Mosshide Gnolls and 10 Mosshide Mongrels.  Hunt them to the south, near the Dwarven gate of Algaz.  After you do this, return to me.",
    isForever = false,
  },
  [878] = {
    id = 878,
    title = "Tribes at War",
    reqLevel = 14,
    questLevel = 21,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Mangletooth",
    objectives = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.",
    rewards = "1,650 XP",
    tip = "You must strike my enemies. <snort> You must help Mangletooth and the Razormane by weakening the Bristlebacks. Both tribes are very spiritual--tied to the earth and its power. <snort> It gives us strength in all things... especially war.\n\nIf you want to find out who really causes Thork <snort> and the Horde such anguish, then help Mangletooth! You attack the spiritual leaders of the Bristlebacks to the north; weaken them so the Razormanes can defeat them and rule the Barrens.",
    isForever = false,
  },
  [6547] = {
    id = 6547,
    title = "Warsong Scout Update",
    reqLevel = 17,
    questLevel = 21,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Warsong Scout",
    objectives = "- Warsong Report",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [226] = {
    id = 226,
    title = "Wolves at Our Heels",
    reqLevel = 19,
    questLevel = 21,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Lars",
    objectives = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.",
    rewards = "1,250 XP",
    tip = "Sven and I have dangerous days ahead of us, what with the Necromancer to the east and all.  And out here alone as we are, we have to hunt for our own food.  It seems every time I'm heading back to camp with some meat on me, starving or rabid dire wolves come out of the forest wanting a bite.  It goes without saying, living out here is dangerous work!\n\nBut if you can rid us of some of those wolves, we'd have an easier time of it.  They mostly prowl north and east of here, near the river.",
    isForever = false,
  },
  [1483] = {
    id = 1483,
    title = "Ziz Fizziks",
    reqLevel = 16,
    questLevel = 21,
    faction = "Both",
    zone = "The Barrens",
    npc = "Sputtervalve",
    objectives = "Speak with Ziz Fizziks in Windshear Crag.",
    rewards = "415 XP",
    tip = "The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.\n\nA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.\n\nMaybe you could look in on him for me? He's stationed at the western edge of Windshea",
    isForever = false,
  },
  [6564] = {
    id = 6564,
    title = "Allegiance to the Old Gods",
    reqLevel = 17,
    questLevel = 22,
    faction = "Horde",
    zone = "Blackfathom Deeps",
    npc = "Item: Damp Note",
    objectives = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.",
    rewards = "1,300 XP • 11s",
    tip = "Some poor handwriting is scrawled on the crumpled up note:\n\n\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.\n\nBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"",
    isForever = false,
  },
  [1655] = {
    id = 1655,
    title = "Bailor's Ore Shipment",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Bailor Stonehand",
    objectives = "Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan.",
    rewards = "435 XP",
    tip = "Ach, ya startled me, $G man:woman;! Can't ya see I was lost in thought?\n\nWhat's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough.\n\nIf you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.",
    isForever = false,
  },
  [389] = {
    id = 389,
    title = "Bazil Thredd",
    reqLevel = 16,
    questLevel = 22,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Baros Alexston",
    objectives = "Speak with Warden Thelwater in the Stockade.",
    rewards = "435 XP",
    tip = "VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.\n\nWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.\n\nHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Sto",
    isForever = false,
  },
  [1530] = {
    id = 1530,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 22,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Islen Waterseer",
    objectives = "Find Brine in Southern Barrens.",
    rewards = "435 XP",
    tip = "If there is one lesson you must learn of water, it is this: water means rebirth.\n\nIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.\n\nWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.\n\nIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.",
    isForever = false,
  },
  [1535] = {
    id = 1535,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 22,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Brine",
    objectives = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.",
    rewards = "870 XP",
    tip = "To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives.\n\nWe shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me.",
    isForever = false,
  },
  [1536] = {
    id = 1536,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 22,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Brine",
    objectives = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.",
    rewards = "1,300 XP",
    tip = "Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill.\n\nIt was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea.\n\nBring me a sample of that water in this waterskin.",
    isForever = false,
  },
  [279] = {
    id = 279,
    title = "Claws from the Deep",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Karl Boran",
    objectives = "Kill 12 Bluegill Murlocs.\n\nSlay Gobbler and take his head.\n\nBring Gobbler's Head to Karl Boran in Menethil Harbor.",
    rewards = "1,750 XP • 14s",
    tip = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.",
    isForever = false,
  },
  [1079] = {
    id = 1079,
    title = "Covert Ops - Alpha",
    reqLevel = 17,
    questLevel = 22,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Gaxim Rustfizzle",
    objectives = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.",
    rewards = "2,200 XP",
    tip = "This is it, $N. Pay close attention. The devices are done, and ready to be used.\n\nTake these pages--they'll explain more about the detonators and explosives, and where you should place them.\n\nRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.",
    isForever = false,
  },
  [1080] = {
    id = 1080,
    title = "Covert Ops - Beta",
    reqLevel = 17,
    questLevel = 22,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Gaxim Rustfizzle",
    objectives = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.",
    rewards = "2,200 XP",
    tip = "Plan Beta's just like Plan Alpha, $N.\n\nWe cause a distraction and then steal their precious letters.\n\nThe key is to get their letters... remember that.\n\nThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....",
    isForever = false,
  },
  [868] = {
    id = 868,
    title = "Egg Hunt",
    reqLevel = 17,
    questLevel = 22,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Korran",
    objectives = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.",
    rewards = "1,750 XP",
    tip = "Hey, $N. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar.\n\nOne object of my studies are the insect-like creatures found to the south in the Field of Giants. We know little of the creatures, so I be makin' it a point to discover more. They seem to have intelligence to them, more so than any normal animal.\n\nTake this digging claw and collect some of the creatures' eggs from their mounds, but be careful: if alerted, they will attack y",
    isForever = false,
  },
  [496] = {
    id = 496,
    title = "Elixir of Suffering",
    reqLevel = 19,
    questLevel = 22,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.",
    rewards = "175 XP • 1s 50c",
    tip = "Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, $N.\n\nThe sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all.\n\nIf you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.",
    isForever = false,
  },
  [499] = {
    id = 499,
    title = "Elixir of Suffering",
    reqLevel = 19,
    questLevel = 22,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Give Umpi the Elixir of Suffering.",
    rewards = "1,750 XP",
    tip = "It will take but a moment for me to mix these components into what I have deemed an Elixir of Suffering.\n\nThere we go!  Ah, nothing brightens a gloomy day in these miserable foothills like bringing a little suffering into the world.\n\nLet us see if our little potion has achieved its desired effect.\n\nGive my assistant Umpi a taste of what the Dark Lady has planned for both humans and Scourge alike.",
    isForever = false,
  },
  [1033] = {
    id = 1033,
    title = "Elune's Tear",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Pelturas Whitemoon",
    objectives = "Bring Elune's Tear to Pelturas in Astranaar.",
    rewards = "1,750 XP • 14s",
    tip = "I had hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through my child.  We must find more powerful medicine!  Thankfully, Orendil spoke to me of further remedies to try should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the isle on Iris Lake, east of Astranaar.  Orendil said the stone will wash away corruption... please, $N, bring me Elune's Tear and pray it will end my child's sickness!",
    isForever = false,
  },
  [994] = {
    id = 994,
    title = "Escape Through Force",
    reqLevel = 10,
    questLevel = 22,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Volcor",
    objectives = "Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.",
    rewards = "1,750 XP • 14s",
    tip = "All right, $N, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there. Once there, we can part ways.\n\nTerenthis will want to hear your version of the story immediately, so head to Auberdine after we make it out of here.",
    isForever = false,
  },
  [1090] = {
    id = 1090,
    title = "Gerenzo's Orders",
    reqLevel = 17,
    questLevel = 22,
    faction = "Both",
    zone = "Stonetalon Mountains",
    npc = "Piznik",
    objectives = "Get the mysterious ore from Piznik after he finishes mining it.",
    rewards = "2,200 XP",
    tip = "You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are.\n\nAnyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I",
    isForever = false,
  },
  [1092] = {
    id = 1092,
    title = "Gerenzo's Orders",
    reqLevel = 17,
    questLevel = 22,
    faction = "Both",
    zone = "Stonetalon Mountains",
    npc = "Piznik",
    objectives = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.",
    rewards = "1,300 XP",
    tip = "I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again.\n\nI'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job!\n\nI'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.",
    isForever = false,
  },
  [2358] = {
    id = 2358,
    title = "Horns of Nez'ra",
    reqLevel = 16,
    questLevel = 22,
    faction = "Both",
    zone = "Rogue Class Quests",
    npc = "Class Trainer",
    objectives = "Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.",
    rewards = "1,800 XP",
    tip = "Many years ago, the Horns of Nez'ra were stolen from Ravenholdt manor. Across continents and oceans I have searched, only to discover that these insignificant beasts have had it in their possession all along.\n\nSlay every Blackrock orc you cross until the Horns of Nez'ra are recovered. Should you recover the horns, find me in Lakeshire.\n\nDo this for me and your name shall be known to Ravenholdt, $N.",
    isForever = false,
  },
  [1091] = {
    id = 1091,
    title = "Kaela's Update",
    reqLevel = 17,
    questLevel = 22,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Gaxim Rustfizzle",
    objectives = "Bring the Venture Co. Letters to Kaela Shadowspear.",
    rewards = "175 XP",
    tip = "$N, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.\n\nMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.",
    isForever = false,
  },
  [883] = {
    id = 883,
    title = "Lakota'mani",
    reqLevel = 10,
    questLevel = 22,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Item: Hoof of Lakota'mani",
    objectives = "Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.",
    rewards = "1,300 XP",
    tip = "The Hoof of Lakota'mani is a symbol of the strength of the great kodo.",
    isForever = false,
  },
  [914] = {
    id = 914,
    title = "Leaders of the Fang",
    reqLevel = 11,
    questLevel = 22,
    faction = "Horde",
    zone = "Wailing Caverns",
    npc = "Nara Wildmane",
    objectives = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",
    rewards = "2,200 XP",
    tip = "The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.\n\nThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.\n\nGo, $N.  You will find them lurking deep within the Wailing Caverns.",
    isForever = false,
  },
  [248] = {
    id = 248,
    title = "Looking Further",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Object: Old Lion Statue",
    objectives = "Climb the intact watch tower beside Stonewatch Keep.\n\nFind a suitable container to place the Glyph of Azora.",
    rewards = "1,300 XP",
    tip = "I have been watching the Tower of Ilgalar, and can detect that Morganth is in conflict with the Orcs in Stonewatch Keep.  I do not know the reason behind their contention, but you may aid me in unraveling this mystery.\n\nTake another Glyph of Azora, then go to the top of the intact watch tower beside Stonewatch Keep.\n\nFind a suitable object on which to place the Glyph.  A chest or a jar -- some place where the glyph will not be noticed -- will suit my purpose.",
    isForever = false,
  },
  [466] = {
    id = 466,
    title = "Search for Incendicite",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Pilot Stonegear",
    objectives = "Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh.",
    rewards = "1,750 XP",
    tip = "I heard that a rare ore, incendicite, was found in the Wetlands, in a cave northwest of Algaz Gate.  Incendicite is volatile stuff and hard to use without blowing yourself up, but I'm sure if it's smelted the right way it could make cannon shells that pack a mighty punch!\n\nGet me incendicite ore and I'll find someone brave enough to experiment with it.\n\nOh, and to extract that ore from a vein you'll need skill in mining.  If you don't have it, then ... bring a friend who does to that cave!",
    isForever = false,
  },
  [1442] = {
    id = 1442,
    title = "Seeking the Kor Gem",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Thundris Windweaver",
    objectives = "Bring a Kor Gem to Thundris Windweaver in Darkshore.",
    rewards = "435 XP",
    tip = "Greetings, $N. What can I do for one who follows a holy path?\n\nAh, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time.\n\nHe never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble.\n\nIf you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, ",
    isForever = false,
  },
  [166] = {
    id = 166,
    title = "The Defias Brotherhood",
    reqLevel = 14,
    questLevel = 22,
    faction = "Alliance",
    zone = "The Deadmines",
    npc = "Gryan Stoutmantle",
    objectives = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.",
    rewards = "2,600 XP",
    tip = "There is but one task left for you to complete.  Edwin VanCleef must be assassinated.  While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all.  Bring me the villain's head once the deed is done.",
    isForever = false,
  },
  [6563] = {
    id = 6563,
    title = "The Essence of Aku'Mai",
    reqLevel = 17,
    questLevel = 22,
    faction = "Horde",
    zone = "Blackfathom Deeps",
    npc = "Je'neu Sancrea",
    objectives = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.",
    rewards = "1,750 XP • 14s",
    tip = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, $N? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.",
    isForever = false,
  },
  [498] = {
    id = 498,
    title = "The Rescue",
    reqLevel = 17,
    questLevel = 22,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Krusk",
    objectives = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.",
    rewards = "2,200 XP",
    tip = "Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.\n\nWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.\n\nDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.",
    isForever = false,
  },
  [1699] = {
    id = 1699,
    title = "The Rethban Gauntlet",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Yorus Barleybrew",
    objectives = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.\n\nYou must not die and release your spirit.",
    rewards = "1,300 XP",
    tip = "I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles...\n\nYou have to return within an hour.\n\nThere are whole heaps of Redridge Gnolls in the way.\n\nBefore you start, you have to take a swig of my family's signature drink: Barleybrew Scalder!\n\nSo what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?",
    isForever = false,
  },
  [1702] = {
    id = 1702,
    title = "The Shieldsmith",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Yorus Barleybrew",
    objectives = "Bring the Cask of Scalder to Furen Longbeard.",
    rewards = "435 XP",
    tip = "You really showed what you were made of when you ran the Rethban Gauntlet, $N.  And I'm true to my word.  I'll get you the reward I promised...\n\nExcept it's in Stormwind.\n\nTalk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor.\n\nHere, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one.",
    isForever = false,
  },
  [1654] = {
    id = 1654,
    title = "The Test of Righteousness",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Jordan Stilwell",
    objectives = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.",
    rewards = "870 XP",
    tip = "I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance.\n\nI will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, $c?",
    isForever = false,
  },
  [1806] = {
    id = 1806,
    title = "The Test of Righteousness",
    reqLevel = 20,
    questLevel = 22,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Jordan Stilwell",
    objectives = "Wait for Jordan Stilwell to finish forging a weapon for you.",
    rewards = "2,200 XP",
    tip = "Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.\n\nWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.\n\nI'll be somewhat honest, $N, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy.",
    isForever = false,
  },
  [373] = {
    id = 373,
    title = "The Unsent Letter",
    reqLevel = 16,
    questLevel = 22,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Item: An Unsent Letter",
    objectives = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.",
    rewards = "870 XP • 7s",
    tip = "Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square.\n\nIt appears to be recently written and sealed.",
    isForever = false,
  },
  [480] = {
    id = 480,
    title = "The Weaver",
    reqLevel = 10,
    questLevel = 22,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "Shadow Priest Allister",
    objectives = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.",
    rewards = "1,750 XP",
    tip = "An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him. It will be difficult, he is no doubt protected by many other mages and warders.\n\nYou must go, and you must dispatch him quickly. When he is dead, retrieve his staff for me. Go now.",
    isForever = false,
  },
  [6562] = {
    id = 6562,
    title = "Trouble in the Deeps",
    reqLevel = 17,
    questLevel = 22,
    faction = "Horde",
    zone = "Blackfathom Deeps",
    npc = "Tsunaman",
    objectives = "Speak to Je'neu Sancrea in Ashenvale.",
    rewards = "435 XP",
    tip = "Je'neu Sancrea is in need of aid. He is at the Zoram'gar Outpost in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, $N. There are forces there that will not take to your presence kindly.",
    isForever = false,
  },
  [1082] = {
    id = 1082,
    title = "Update for Sentinel Thenysil",
    reqLevel = 17,
    questLevel = 22,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Kaela Shadowspear",
    objectives = "Return to Sentinel Thenysil in Ashenvale.",
    rewards = "870 XP",
    tip = "$N, you have done a great deed by lending a hand here.\n\nThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.\n\nFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.",
    isForever = false,
  },
  [256] = {
    id = 256,
    title = "WANTED: Chok'sul",
    reqLevel = 17,
    questLevel = 22,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Object: WANTED",
    objectives = "Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar.",
    rewards = "1,750 XP",
    tip = "By order of the Magistrate of Thelsamar:\n\nChok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary.\n\nMonetary compensation will be provided when proof is brought to the Magistrate of Chok'sul's death.\n\nChok'sul was last seen at the ogre encampment in the northeastern part of Loch Modan.",
    isForever = false,
  },
  [549] = {
    id = 549,
    title = "WANTED: Syndicate Personnel",
    reqLevel = 17,
    questLevel = 22,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Object: WANTED",
    objectives = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.",
    rewards = "1,750 XP • 14s",
    tip = "By the authority of Lady Sylvanas, all members of the organization known as the Syndicate are wanted dead. Those brought into custody or taken prisoner will be summarily executed. They are currently known to be amassing in the ruins of Durnholde Keep, to the southeast of Tarren Mill.\n\nA handsome reward is offered to all who bring proof of their deeds to High Executor Darthalia.",
    isForever = false,
  },
  [484] = {
    id = 484,
    title = "Young Crocolisk Skins",
    reqLevel = 18,
    questLevel = 22,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "James Halloran",
    objectives = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.",
    rewards = "1,750 XP • 14s",
    tip = "I'm James Halloran, the tanner. My cured crocolisk skins are sought after all over, shipments leaving by boat to ports around the world.\n\nMet Einar? He's one of the hunters that brings crocolisk skins in for me.\n\nI'm a bit short on the softer skins that come off crocolisk young.\n\nBeing that I'm running low, I'll pay you top coin for a stack of the skins. You can find the young crocs in the marshes right outside of town.",
    isForever = false,
  },
  [1066] = {
    id = 1066,
    title = "Blood of Innocents",
    reqLevel = 13,
    questLevel = 23,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Apothecary Lydon",
    objectives = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.",
    rewards = "1,850 XP",
    tip = "I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?\n\nBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.\n\nFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.\n\nYou can find the Syndicate shadow mages in Durnholde Keep to the southeast.",
    isForever = false,
  },
  [63] = {
    id = 63,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 23,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Islen Waterseer",
    objectives = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.",
    rewards = "1,400 XP",
    tip = "Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.\n\nTake the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.\n\nBring me proof the task is done, and I will reward you with your to",
    isForever = false,
  },
  [96] = {
    id = 96,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 23,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Minor Manifestation of Water",
    objectives = "Bring the Shard of Water to Islen Waterseer in the Barrens.",
    rewards = "2,750 XP",
    tip = "Take shard. Take shard and give life.\n\nGive life and understand. Understand water is life... corruption stops life.\n\nYou protect and give life with water's power.",
    isForever = false,
  },
  [100] = {
    id = 100,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 23,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Object: Brazier of Everfount",
    objectives = "Speak to the Minor Manifestation of Water in Silverpine Forest.",
    rewards = "Experience & Faction Reputation",
    tip = "Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.",
    isForever = false,
  },
  [220] = {
    id = 220,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 23,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Brine",
    objectives = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens.",
    rewards = "460 XP",
    tip = "Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is.\n\nGo now and find her. We shall meet again some day.",
    isForever = false,
  },
  [1103] = {
    id = 1103,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 23,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Tiev Mordune",
    objectives = "Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water.",
    rewards = "Experience & Faction Reputation",
    tip = "Greetin's, $g brotha:sista;! Have you too come to purify the waters here and prove your understandin' to Islen?\n\nI've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier.\n\nWhat's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again.\n\nBring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me pa",
    isForever = false,
  },
  [1534] = {
    id = 1534,
    title = "Call of Water",
    reqLevel = 20,
    questLevel = 23,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Brine",
    objectives = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.",
    rewards = "1,400 XP",
    tip = "Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens.\n\nOnce you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain.\n\nBring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen.",
    isForever = false,
  },
  [6301] = {
    id = 6301,
    title = "Cycle of Rebirth",
    reqLevel = 17,
    questLevel = 23,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Tammra Windfield",
    objectives = "Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.",
    rewards = "1,400 XP • 12s",
    tip = "Industrial greed and continuous war have wrecked the lands of Stonetalon. Only the blessings of the Earthmother can cure such injury.\n\n$N, I will require you to seek a special seed, the Gaea seed. They are only found here in Stonetalon Mountain, north of Sun Rock Retreat at Mirkfallon Lake, near the water's edge.\n\nOnce you bring me the seeds I will imbue them with shamanistic power to speed their growth.",
    isForever = false,
  },
  [164] = {
    id = 164,
    title = "Deliveries to Sven",
    reqLevel = 17,
    questLevel = 23,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Elaine Carevin",
    objectives = "Deliver the supplies to Sven.",
    rewards = "920 XP • 8s",
    tip = "Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood.\n\nUnfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?",
    isForever = false,
  },
  [862] = {
    id = 862,
    title = "Dig Rat Stew",
    reqLevel = 15,
    questLevel = 23,
    faction = "Horde",
    zone = "Cooking",
    npc = "Grub",
    objectives = "Bring 8 Dig Rats to Grub east of the Crossroads.",
    rewards = "1,850 XP",
    tip = "A $c like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long.\n\nTell you what, I'll fix you up a nice stew. Just need a few dig rats.\n\nSeems those filthy dwarves at Bael Modan are overrun with everyone's favorite feast. Now head on down south to Bael Modan and bring me back some dig rats.\n\nYou can't call yourself a seasoned adventurer until you've spent some time killing rats! Haw!",
    isForever = false,
  },
  [277] = {
    id = 277,
    title = "Fire Taboo",
    reqLevel = 20,
    questLevel = 23,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Rethiel the Greenwarden",
    objectives = "Bring Rethiel the Greenwarden 9 Crude Flints.",
    rewards = "1,850 XP",
    tip = "The Mosshides are cutting the trees of the Wetlands, using the trees' flesh to warm themselves with fire.  I will suffer this pain no longer!\n\nRid the Mosshides of their crude flints, the tools they use to make fire.  The flints are borne by all Mosshides except the smaller Mosshide gnolls and Mosshide mongrels.",
    isForever = false,
  },
  [843] = {
    id = 843,
    title = "Gann's Reclamation",
    reqLevel = 17,
    questLevel = 23,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Gann Stonespire",
    objectives = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.$b$bBring Khazgorm's Journal to Gann Stonespire.",
    rewards = "1,850 XP • 15s",
    tip = "In solitude I wander these roads.\n\nThe dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves.\n\nAttempts at reaching a diplomatic resolution have failed. Now is the time for decisive action.\n\nDrive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.",
    isForever = false,
  },
  [971] = {
    id = 971,
    title = "Knowledge in the Deeps",
    reqLevel = 10,
    questLevel = 23,
    faction = "Alliance",
    zone = "Blackfathom Deeps",
    npc = "Gerrig Bonegrip",
    objectives = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.",
    rewards = "2,750 XP",
    tip = "As you might know, I collect lore.  Old lore.  Powerful lore.  Lore that opens doorways, and lore that can awaken Those Who Sleep.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in Ashenvale.  That place is the old dwelling of long-dead elves.  Elves who held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript.  Do this, and I will not forget it.  Not even after ... the end days.",
    isForever = false,
  },
  [1067] = {
    id = 1067,
    title = "Return to Thunder Bluff",
    reqLevel = 13,
    questLevel = 23,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Apothecary Lydon",
    objectives = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.",
    rewards = "1,400 XP",
    tip = "Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!\n\nBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.",
    isForever = false,
  },
  [115] = {
    id = 115,
    title = "Shadow Magic",
    reqLevel = 18,
    questLevel = 23,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Marshal Marris",
    objectives = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.",
    rewards = "2,300 XP • 30s",
    tip = "The Blackrock orcs enlisted shadowcasters to aid their attacks in Redridge, and they have brought with them devices of dark power--midnight orbs.  These orbs have struck telling blows against Redridge's defenders, and it's imperative we remove the demon-tainted items from the conflict.\n\nFind and deliver to me midnight orbs from slain Blackrock shadowcasters.  I will then have them disposed of, for this world would be a better place without them!",
    isForever = false,
  },
  [1068] = {
    id = 1068,
    title = "Shredding Machines",
    reqLevel = 13,
    questLevel = 23,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Seereth Stonebreak",
    objectives = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.",
    rewards = "1,850 XP • 15s",
    tip = "There is a relation to the spiritual magic of shaman and the natural magic of druids.  This is why we shaman can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear...\n\nI saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped!\n\nIn my vision, the machines were marked with strange symbols:\n\nXT:4 and XT:9.",
    isForever = false,
  },
  [91] = {
    id = 91,
    title = "Solomon's Law",
    reqLevel = 17,
    questLevel = 23,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Bailiff Conacher",
    objectives = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.",
    rewards = "1,850 XP • 15s",
    tip = "An enemy of Stormwind has taken up residence in the eastern foothills of Redridge. This wicked villain uses the Arcane to spread terror and misery upon our town and our people. Under the name, Morganth, he conducts his evil business.\n\nMorganth now controls the Shadowhide Gnoll Clan to perform his biddings. As stated by the Law of Lakeshire, aiding a criminal of the Kingdom is punishable by death.\n\nThese vile gnolls must be killed!\n\nTurn in 10 Shadowhide Pendants to me, and you shall be rewarded.",
    isForever = false,
  },
  [467] = {
    id = 467,
    title = "Stonegear's Search",
    reqLevel = 20,
    questLevel = 23,
    faction = "Alliance",
    zone = "Dun Morogh",
    npc = "Mountaineer Kadrell",
    objectives = "Speak with Pilot Stonegear.",
    rewards = "460 XP",
    tip = "Pilot Stonegear loves his siege engine, as every pilot should!  And he's always eager to find new ways to improve his tank's firepower!\n\nHe heard rumors of a rare ore and is looking for someone to hunt it down for him.  If your boots are starting to itch, then find Stonegear at Steelgrill's Depot in Dun Morogh and see what he wants.",
    isForever = false,
  },
  [1086] = {
    id = 1086,
    title = "The Flying Machine Airport",
    reqLevel = 13,
    questLevel = 23,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Apothecary Zamah",
    objectives = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.",
    rewards = "2,300 XP • 30s",
    tip = "The toxin is ready.  All that remains is its delivery.  You, $N, must make that delivery.\n\nThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.\n\nPlace it, and r",
    isForever = false,
  },
  [1034] = {
    id = 1034,
    title = "The Ruins of Stardust",
    reqLevel = 20,
    questLevel = 23,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Pelturas Whitemoon",
    objectives = "Bring 5 Handfuls of Stardust to Pelturas in Astranaar.",
    rewards = "1,850 XP • 15s",
    tip = "Elune's Tear washed clear some of my daughter's sickness.  Her nightmares are lessened and I thank the goddess for her blessing.  But ... fever still rages within her.\n\nOrendil told me of a frosted dust found among the Ruins of Stardust.  Perhaps it will abate Relara's fever.  Gather some of the dust, then please return to me.\n\nThe Ruins of Stardust lie to the south, $N.  May Elune speed your journey.",
    isForever = false,
  },
  [1650] = {
    id = 1650,
    title = "The Tome of Valor",
    reqLevel = 20,
    questLevel = 23,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Duthorian Rall",
    objectives = "Find Daphne Stilwell in Westfall.",
    rewards = "1,850 XP",
    tip = "Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.\n\nAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.\n\nReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go the",
    isForever = false,
  },
  [178] = {
    id = 178,
    title = "Theocritus' Retrieval",
    reqLevel = 15,
    questLevel = 23,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Item: Glowing Shadowhide Pendant",
    objectives = "Bring the Faded Shadowhide Pendant to Theocritus the Mage.",
    rewards = "1,400 XP • 12s",
    tip = "<You hear a disembodied voice...>\n\nDo not be alarmed.  I am Theocritus, High Mage of Tower Azora in Elwynn Forest.  The pendant you are holding is a method of communication between the Shadowhide Gnolls and their master, Morganth.\n\nThrough months of research, I believe I too can communicate through these pendants.  If you can hear this message, then my spell was a success.\n\nBring me this pendant and I will reward you for the service.",
    isForever = false,
  },
  [6641] = {
    id = 6641,
    title = "Vorsha the Lasher",
    reqLevel = 20,
    questLevel = 23,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Muglash",
    objectives = "Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.\n\nIf you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher.",
    rewards = "2,300 XP",
    tip = "Vorsha the Lasher... the fiendish hydra that roams the seas...\n\nShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.\n\nBut I am ready, $N. I have prepared to best the hydra and end these attacks on Zoram'gar.\n\nThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.\n\nWe will need help, so be sure to bring some strong allies.",
    isForever = false,
  },
  [1025] = {
    id = 1025,
    title = "An Aggressive Defense",
    reqLevel = 18,
    questLevel = 24,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Raene Wolfrunner",
    objectives = "Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.",
    rewards = "1,950 XP • 17s",
    tip = "Before you travel to the moonwell I have another task that will aid the people of Ashenvale if you would like to test your skills.\n\nAlong the road heading east before the Falfarren River, furbolgs have been attacking travelers. Their tortured minds feeding upon fear, and their appetites satiated by the blood of innocents.\n\nAid the Sentinels in protecting the lands by showing those monsters the same mercy they have shown our kind.\n\nI believe their camps are south of the road... be careful.",
    isForever = false,
  },
  [34] = {
    id = 34,
    title = "An Unwelcome Guest",
    reqLevel = 18,
    questLevel = 24,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Martie Jainrose",
    objectives = "Martie Jainrose of Lakeshire wants you to kill Bellygrub.  Bring her his tusk as proof.",
    rewards = "1,950 XP • 17s",
    tip = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.",
    isForever = false,
  },
  [6503] = {
    id = 6503,
    title = "Ashenvale Outrunners",
    reqLevel = 19,
    questLevel = 24,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Kuray'bin",
    objectives = "Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost.",
    rewards = "1,950 XP",
    tip = "We received reports that Ashenvale outrunners left Silverwing Outpost not long ago, and now sneak near our territories in the forest.  We don't want them gathering intelligence on our defenses!\n\nSneak through the forests south of our post here and east of the Alliance outpost of Silverwing.  Find and slay the outrunners, then return to me.",
    isForever = false,
  },
  [442] = {
    id = 442,
    title = "Assault on Fenris Isle",
    reqLevel = 10,
    questLevel = 24,
    faction = "Horde",
    zone = "Silverpine Forest",
    npc = "High Executor Hadrec",
    objectives = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.",
    rewards = "1,950 XP",
    tip = "Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle.\n\nYou must again go to the Isle and destroy Thule Ravenclaw.  I want his head!\n\nThis mission is as dangerous as it is vital, $N.  You must not fail.",
    isForever = false,
  },
  [527] = {
    id = 527,
    title = "Battle of Hillsbrad",
    reqLevel = 19,
    questLevel = 24,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "High Executor Darthalia",
    objectives = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.",
    rewards = "1,950 XP • 17s",
    tip = "Stand at attention while addressing me, $c.\n\nI am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague.\n\nOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.\n\nTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.",
    isForever = false,
  },
  [216] = {
    id = 216,
    title = "Between a Rock and a Thistlefur",
    reqLevel = 21,
    questLevel = 24,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Karang Amakkar",
    objectives = "Take down 12 Thistlefur Avengers and 12 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.",
    rewards = "1,950 XP • 17s",
    tip = "The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our east blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.\n\n$N, we must not allow... an expansion path gap!\n\nProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!",
    isForever = false,
  },
  [344] = {
    id = 344,
    title = "Brother Paxton",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Milton Sheaf",
    objectives = "Speak with Brother Paxton in the Northshire Abbey.",
    rewards = "485 XP",
    tip = "The Stresses of Iron?  Yes, I know the book.  Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago.  He spent most his time deep in the mountains of Khaz Modan, digging ore.  Smart fellow!\n\nBut where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey.  The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves.\n\nBut that was months ago.  I wonder why it's taking him so long...",
    isForever = false,
  },
  [822] = {
    id = 822,
    title = "Chen's Empty Keg",
    reqLevel = 11,
    questLevel = 24,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Brewmaster Drohn",
    objectives = "Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.",
    rewards = "970 XP",
    tip = "Good stuff, that stormstout, huh?\n\nI have another recipe that I learned from Chen. Would you be interested? It won't take long to make, and it might be useful if you plan on adventuring some more.\n\nBring me 5 lightning glands from any stormhide, 1 thunderhawk saliva gland from greater thunderhawks, and a kodo liver from any of the Barrens' kodos.\n\nLike I said, this stuff has kick; it's the trogg ale that I mentioned to you before.",
    isForever = false,
  },
  [157] = {
    id = 157,
    title = "Deliver the Thread",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Madame Eva",
    objectives = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.",
    rewards = "1,450 XP • 13s",
    tip = "Here is your thread, $N.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.",
    isForever = false,
  },
  [470] = {
    id = 470,
    title = "Digging Through the Ooze",
    reqLevel = 19,
    questLevel = 24,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Sida",
    objectives = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.",
    rewards = "2,400 XP • 35s",
    tip = "On my weekly visit to Ironbeard's Tomb I was attacked by dreadful, dripping oozes! Naturally, I panicked.\n\nI threw my bag at one, but it didn't do anything! The ooze just sucked it right up... Luckily, it did give me enough time to get away.\n\nThe bad news is that I really need to get the contents of my bag!\n\nI don't know which ooze I threw my bag at; they all looked the same! Ironbeard's Tomb is northeast of here, near Dun Modr. Thank you so much!",
    isForever = false,
  },
  [1016] = {
    id = 1016,
    title = "Elemental Bracers",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Sentinel Velene Starstrike",
    objectives = "Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge.",
    rewards = "1,950 XP",
    tip = "Take this divining scroll--it can determine the creator of these elementals. But you will need something from them to use as a reagent to focus scroll's magic--their bracers should do nicely.\n\nA few intact bracers from the creatures should be enough. The other bracers will be useless for our purposes, but they may be worth something to a merchant if you wish to sell them. Once you have the intact bracers attempt to use the scroll. Return to me with the results and we shall proceed from there.",
    isForever = false,
  },
  [501] = {
    id = 501,
    title = "Elixir of Pain",
    reqLevel = 21,
    questLevel = 24,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.",
    rewards = "1,950 XP",
    tip = "Oh, $N. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves.\n\nAs much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little",
    isForever = false,
  },
  [502] = {
    id = 502,
    title = "Elixir of Pain",
    reqLevel = 21,
    questLevel = 24,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Feed the Elixir of Pain to Stanley.",
    rewards = "1,450 XP",
    tip = "Ah, nothing like the smell of fresh blood in the foothills!\n\nNow we'll mix in a touch of this and a little of that and let the real fun begin!  What I have created with this blood, I like to call an Elixir of Pain.  If my calculations are correct this concoction could be the start of something very beautiful for Lady Sylvanas.  But what we need is a test.\n\nTake this elixir out to the northern farm in Hillsbrad Fields to the southwest.  Let's see how Farmer Ray's little dog Stanley likes this \"tr",
    isForever = false,
  },
  [6482] = {
    id = 6482,
    title = "Freedom to Ruul",
    reqLevel = 19,
    questLevel = 24,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Ruul Snowhoof",
    objectives = "Escort Ruul, then speak with Yama Snowhoof in Spintertree Post.",
    rewards = "2,400 XP • 17s",
    tip = "Eh?  Who are you?\n\n$N?  You're no furbolg.  They are cursed!  They thought I was a bear and captured me, and now they starve me!  My strength is failing...\n\nHelp me escape, then speak with my sister Yama at the Splintertree Post to the east.\n\n$N! I must escape!",
    isForever = false,
  },
  [156] = {
    id = 156,
    title = "Gather Rot Blossoms",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Tavernkeep Smitts",
    objectives = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.",
    rewards = "970 XP",
    tip = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nRot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look!\n\nThe Raven Hill Cemetery is lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful.",
    isForever = false,
  },
  [149] = {
    id = 149,
    title = "Ghost Hair Thread",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Madame Eva",
    objectives = "Bring the Spectral Comb to Blind Mary.",
    rewards = "485 XP",
    tip = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...",
    isForever = false,
  },
  [1198] = {
    id = 1198,
    title = "In Search of Thaelrid",
    reqLevel = 18,
    questLevel = 24,
    faction = "Alliance",
    zone = "Blackfathom Deeps",
    npc = "Dawnwatcher Shaedlass",
    objectives = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.",
    rewards = "2,400 XP",
    tip = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.\n\nMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out and aid Thaelrid for me, $n.",
    isForever = false,
  },
  [305] = {
    id = 305,
    title = "In Search of The Excavation Team",
    reqLevel = 21,
    questLevel = 24,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Tarrel Rockweaver",
    objectives = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.",
    rewards = "970 XP",
    tip = "Oh my, you must be the scout Longbraid said he would send!  You cannot imagine how worried I have been.\n\nMy wife, Merrin, has been sending me letters each week for the past month.  She is part of the Whelgar Excavation team.  But it has been nearly two weeks since her last correspondence.  Surely something is wrong!\n\nLongbraid said that he would send a scout to check up on things if we did not hear from the team soon.  I assume that scout is you, $N.  Find Merrin at the excavation site to the ea",
    isForever = false,
  },
  [306] = {
    id = 306,
    title = "In Search of The Excavation Team",
    reqLevel = 21,
    questLevel = 24,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Merrin Rockweaver",
    objectives = "Return to Tarrel Rockweaver with Merrin's note.",
    rewards = "485 XP",
    tip = "It was horrible!  We were uncovering some rare artifacts and we began to discover these large bones.\n\nBefore we knew what was happening, these Mottled Raptors overwhelmed the dig site.  Many lives were lost.\n\nOrmer here -- so brave -- saved the Prospector and me.  He defended us as we ran for shelter.  Now we are trapped.  And our hard work lies in ruin.\n\nHere, take this note back to my sweet Tarrel.  It will explain the situation to him.",
    isForever = false,
  },
  [345] = {
    id = 345,
    title = "Ink Supplies",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Brother Paxton",
    objectives = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.",
    rewards = "485 XP",
    tip = "I've been meaning to finish my copy of The Stresses of Iron, but...\n\nWell you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink!\n\nTo make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.",
    isForever = false,
  },
  [159] = {
    id = 159,
    title = "Juice Delivery",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Tavernkeep Smitts",
    objectives = "Bring the Zombie Juice to Abercrombie at his shack.",
    rewards = "970 XP • 17s",
    tip = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!",
    isForever = false,
  },
  [2359] = {
    id = 2359,
    title = "Klaven's Tower",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Rogue Class Quests",
    npc = "Agent Kearnen",
    objectives = "- Klaven Mortwake's Journal - Defias Tower Key",
    rewards = "1,950 XP",
    tip = "I've been staking out this tower for weeks, $N. Recently a major shipment came through from Duskwood, and along with it came those guards.\n\nWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.\n\nAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.\n\nGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias.",
    isForever = false,
  },
  [2478] = {
    id = 2478,
    title = "Mission: Possible But Not Probable",
    reqLevel = 20,
    questLevel = 24,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Taskmaster Fizzule",
    objectives = "- Mutated Venture Co. Drone x 2 - Venture Co. Lookout x 2 - Venture Co. Patroller x 2 - Gallywix's Head - Silixiz's Tower Key - Cache of Zanzil's Altered Mixture",
    rewards = "1,950 XP",
    tip = "You will need to steal the tower key from Foreman Silixiz, $N. Once you've got the key in your possession, hold on to it - I may need it later.\n\nRemember, the poison has weakened everything in this tower. Use your abilities to bring chaos and destruction to its inhabitants. Slay them all -- show no mercy!\n\nOnce everything inside lays in a bloodied heap, pick Gallywix's lockbox and steal the cache of Zanzil's mixture held inside. Take both the head of Gallywix and the mixture to Shenthul in Orgri",
    isForever = false,
  },
  [294] = {
    id = 294,
    title = "Ormer's Revenge",
    reqLevel = 22,
    questLevel = 24,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Ormer Ironbraid",
    objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.",
    rewards = "1,950 XP • 17s",
    tip = "The situation is severe, that much is for sure.  When we uncovered these bones it attracted the Raptors.  These filthy beasts killed my brethren and trapped me, Merrin and the poor Prospector up here.\n\nHelp clear the Wetlands of these Raptors, $N.  Mottled Raptors and Mottled Screechers are just West of the bluff there.  Kill 10 of each, if you can.\n\nThat will be a good start to the vengeance I have planned for them.",
    isForever = false,
  },
  [884] = {
    id = 884,
    title = "Owatanka",
    reqLevel = 10,
    questLevel = 24,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Item: Owatanka's Tailspike",
    objectives = "Bring Owatanka's Tailspike to Jorn at Camp Taurajo.",
    rewards = "1,450 XP",
    tip = "When touched, sparks fly from the tailspike of Owatanka.",
    isForever = false,
  },
  [1275] = {
    id = 1275,
    title = "Researching the Corruption",
    reqLevel = 18,
    questLevel = 24,
    faction = "Alliance",
    zone = "Blackfathom Deeps",
    npc = "Gershala Nightwhisper",
    objectives = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.",
    rewards = "2,400 XP • 35s",
    tip = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the elves are headed toward. In Blackfathom Deeps, on the coast of Ashenvale, you will find both satyr and naga.\n\n'Tis a long journey, $n.",
    isForever = false,
  },
  [347] = {
    id = 347,
    title = "Rethban Ore",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Foreman Oslow",
    objectives = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.",
    rewards = "970 XP",
    tip = "Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here.\n\nWe usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves.\n\nSo if you need some, you'll have to get it you",
    isForever = false,
  },
  [154] = {
    id = 154,
    title = "Return the Comb",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Blind Mary",
    objectives = "Return the Ghost Hair Comb to Madame Eva in Darkshire.",
    rewards = "195 XP • 1s 75c",
    tip = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!",
    isForever = false,
  },
  [346] = {
    id = 346,
    title = "Return to Kristoff",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Brother Paxton",
    objectives = "Return to Brother Kristoff in the Cathedral Square.  Give him the book The Stresses of Iron.",
    rewards = "1,950 XP",
    tip = "Now that I've finished copying the book, here's the original Stresses of Iron.  Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.",
    isForever = false,
  },
  [343] = {
    id = 343,
    title = "Speaking of Fortitude",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Brother Kristoff",
    objectives = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf.  He can find for you the book on metallurgy that Brother Kristoff needs for his speech.",
    rewards = "195 XP",
    tip = "I'm giving a speech on the Fortitude of the Spirit, and I'd like to recite passages from a particular book on metallurgy - \"The Stresses of Iron.\"  A copy of this book should be in the Royal Library, within Stormwind Keep.  Can you retrieve it for me?  If so, then may the blessings of the Light be with you!\n\nThe Royal Library is very large, but the head librarian, Milton Sheaf, knows each shelf like it was his own son.  Speak to him, he'll retrieve the book for you.",
    isForever = false,
  },
  [148] = {
    id = 148,
    title = "Supplies from Darkshire",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Abercrombie",
    objectives = "Speak with Madame Eva.",
    rewards = "485 XP",
    tip = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square.",
    isForever = false,
  },
  [976] = {
    id = 976,
    title = "Supplies to Auberdine",
    reqLevel = 19,
    questLevel = 24,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Feero Ironhand",
    objectives = "Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.",
    rewards = "2,900 XP • 50s",
    tip = "Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands.\n\nIf you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.",
    isForever = false,
  },
  [943] = {
    id = 943,
    title = "The Absent Minded Prospector",
    reqLevel = 15,
    questLevel = 24,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Archaeologist Flagongut",
    objectives = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.",
    rewards = "2,400 XP",
    tip = "Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil.\n\nWhile I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost. I don't know which one of the mottled beasts swallowed the relic but if you can retrieve it, I can unleash the power of these artifacts.\n\nBring me both the Stone of Relu, and the original fossil he holds.",
    isForever = false,
  },
  [3765] = {
    id = 3765,
    title = "The Corruption Abroad",
    reqLevel = 18,
    questLevel = 24,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Argos Nightwhisper",
    objectives = "Travel to Gershala Nightwhisper in Auberdine.",
    rewards = "1,450 XP • 13s",
    tip = "Stormwind -- such a bustling hub of activity.\n\nI have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets.\n\nMy brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine.\n\nThe journey is a long and epic one. It is for this reason that I ask the help of a seasoned $c such as yourself.",
    isForever = false,
  },
  [897] = {
    id = 897,
    title = "The Harvester",
    reqLevel = 10,
    questLevel = 24,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Item: Harvester's Head",
    objectives = "Bring the Harvester's Head to Jorn Skyseer.",
    rewards = "2,400 XP",
    tip = "This strange, insect-like creature looks outside of the natural order, as though it does not belong in the Barrens.",
    isForever = false,
  },
  [6681] = {
    id = 6681,
    title = "The Manor, Ravenholdt",
    reqLevel = 24,
    questLevel = 24,
    faction = "Both",
    zone = "Rogue Class Quests",
    npc = "Item: Elegant Letter",
    objectives = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared.",
    rewards = "1,950 XP",
    tip = "$N,\n\nRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix.\n\nShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.\n\nYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.\n\nRegards,\n\nFahrad",
    isForever = false,
  },
  [56] = {
    id = 56,
    title = "The Night Watch",
    reqLevel = 18,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Commander Althea Ebonlocke",
    objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.",
    rewards = "1,450 XP • 17s",
    tip = "As Commander of The Night Watch it is my sworn duty to protect the citizens of Darkshire.  Stormwind has retracted their commissioned guards from their posts here, leaving us to our own devices.\n\nIf you feel worthy of the task, we need your help! Assist The Night Watch by venturing forth into Tranquil Gardens, just south of Darkshire, and slaying 8 Skeletal Warriors and 6 Skeletal Mages.  The undead threat must be thwarted!",
    isForever = false,
  },
  [105] = {
    id = 105,
    title = "The Sunken Citadel of Zephras",
    reqLevel = 22,
    questLevel = 24,
    faction = "Both",
    zone = "Zephras Isle",
    npc = "High Executor Derrington",
    objectives = "Bring Araj's Phylactery Shard to High Executor Derrington at the Bulwark, Western Plaguelands.",
    rewards = "8,300 XP",
    tip = "Pro-tip: New level 20-24 dungeon designed as the coastal counterpart to the Deadmines and Wailing Caverns.",
    isForever = true,
  },
  [973] = {
    id = 973,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 24,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Delgren the Purifier",
    objectives = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.",
    rewards = "1,950 XP",
    tip = "Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine,  a place of great evil in southwestern Ashenvale.\n\nHe had been little more than an annoyance until now, and I had not dealt with him, but it seems that his time has come.",
    isForever = false,
  },
  [6544] = {
    id = 6544,
    title = "Torek's Assault",
    reqLevel = 20,
    questLevel = 24,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Torek",
    objectives = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.",
    rewards = "2,400 XP • 17s",
    tip = "Hey!  $C!  Come here!\n\nMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!\n\nDo you want to share in the glory, $N, and aid us?  If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree.\n\nWhat do you say.  Are you with us?",
    isForever = false,
  },
  [6462] = {
    id = 6462,
    title = "Troll Charm",
    reqLevel = 19,
    questLevel = 24,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Mitsuwa",
    objectives = "Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost.",
    rewards = "1,950 XP • 17s",
    tip = "My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar!  Those vile Furbolgs!\n\nI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!\n\n$N, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar",
    isForever = false,
  },
  [23] = {
    id = 23,
    title = "Ursangous's Paw",
    reqLevel = 20,
    questLevel = 24,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Item: Ursangous's Paw",
    objectives = "Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.",
    rewards = "1,950 XP",
    tip = "The paw of the mighty bear Ursangous is your trophy for this part of the Ashenvale Hunt.  On the paw is a small quarter-crescent emblem; the significance of the emblem remains a mystery.\n\nThe paw should be brought to Senani Thunderheart in Splintertree Post to prove that you have bested the mighty creature and completed this portion of the hunt.",
    isForever = false,
  },
  [893] = {
    id = 893,
    title = "Weapons of Choice",
    reqLevel = 17,
    questLevel = 24,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Tatternack Steelforge",
    objectives = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.",
    rewards = "1,950 XP",
    tip = "The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible.\n\nIf you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!",
    isForever = false,
  },
  [158] = {
    id = 158,
    title = "Zombie Juice",
    reqLevel = 20,
    questLevel = 24,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Abercrombie",
    objectives = "Speak with Tavernkeep Smitts.",
    rewards = "485 XP",
    tip = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, $N.  These nights get cold, and I need that drink to put fire in my veins again!",
    isForever = false,
  },
  [337] = {
    id = 337,
    title = "An Old History Book",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Item: An Old History Book",
    objectives = "Return the book: The History of Stormwind, to the Stormwind Library.",
    rewards = "1,500 XP • 14s",
    tip = "Although the cover of this book is marred by scratches and caked with mud, the words \"The History of Stormwind\" can still be read along its spine.  Upon opening the book, the seal of the Stormwind Library is clearly stamped on the book's first page.\n\nIt looks like someone checked out this book, and never returned it...",
    isForever = false,
  },
  [8155] = {
    id = 8155,
    title = "Arathi Basin Resources!",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Sergeant Maclear",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "2,000 XP • 55s",
    tip = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [528] = {
    id = 528,
    title = "Battle of Hillsbrad",
    reqLevel = 19,
    questLevel = 25,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "High Executor Darthalia",
    objectives = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.",
    rewards = "2,000 XP • 18s",
    tip = "Word of the attack on the northern farms has the townsfolk panicked.  Most excellent.\n\nOur Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom.\n\nProve them wrong, $N.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady.\n\nDismissed!",
    isForever = false,
  },
  [879] = {
    id = 879,
    title = "Betrayal from Within",
    reqLevel = 17,
    questLevel = 25,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Mangletooth",
    objectives = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.",
    rewards = "1,500 XP",
    tip = "Three of my tribe came out of the Kraul to lead the raids against the Horde, $r. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort>\n\nNak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, $r, like they have killed me",
    isForever = false,
  },
  [906] = {
    id = 906,
    title = "Betrayal from Within",
    reqLevel = 17,
    questLevel = 25,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Mangletooth",
    objectives = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.",
    rewards = "3,050 XP",
    tip = "Take Lok's head to Thork in the Crossroads, $r. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort>\n\nI will continue to bless you with Agamaggan's power for as long as I remain in this cage, $r. Until then, farewell.",
    isForever = false,
  },
  [128] = {
    id = 128,
    title = "Blackrock Bounty",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Guard Howe",
    objectives = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.",
    rewards = "2,000 XP • 18s",
    tip = "The Blackrock Clan must be destroyed. The Enemy has invaded our lands. These mountains fall under the sovereign right of the King of Stormwind. Our sources tell us that the leaders of each unit within the Clan are known as Champions. You'll find them in their encampment to the north, just west of the road to the Burning Steppes.\n\nMagistrate Solomon wants these foul brutes dead. Slay 15 Blackrock Champions and return to me.",
    isForever = false,
  },
  [1087] = {
    id = 1087,
    title = "Cenarius' Legacy",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Braelyn Firehand",
    objectives = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.",
    rewards = "1,500 XP",
    tip = "You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests.\n\nWould that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done.\n\nI have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satis",
    isForever = false,
  },
  [1054] = {
    id = 1054,
    title = "Culling the Threat",
    reqLevel = 18,
    questLevel = 25,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Raene Wolfrunner",
    objectives = "Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.",
    rewards = "2,000 XP • 18s",
    tip = "Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly.\n\nKill as many of their kind as you can, but bring me their chieftain's skull as proof that their efforts have been stifled... for now.\n\nI shall remain here in Astranaar and await word from you. Elune be with you.",
    isForever = false,
  },
  [8162] = {
    id = 8162,
    title = "Cut Arathor Supply Lines",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathstalker Mortis",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "2,000 XP • 55s",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
  [1098] = {
    id = 1098,
    title = "Deathstalkers in Shadowfang",
    reqLevel = 18,
    questLevel = 25,
    faction = "Horde",
    zone = "Shadowfang Keep",
    npc = "High Executor Hadrec",
    objectives = "Find the Deathstalker Adamant and Deathstalker Vincent.",
    rewards = "2,000 XP • 18s",
    tip = "In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!\n\nSo here is your task, $N.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.\n\nThis mission is as dangerous as is it critical, $N.  Do not fail.",
    isForever = false,
  },
  [6393] = {
    id = 6393,
    title = "Elemental War",
    reqLevel = 19,
    questLevel = 25,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Tsunaman",
    objectives = "Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.",
    rewards = "2,000 XP • 18s",
    tip = "The Tribunal of the Tides has sent me to wage war on the fire elementals here in Stonetalon Mountain. Neptulon the Tidehunter, Lord of all water elementals, has taken a personal interest in seeing our fiery cousins extinguished.\n\n$N, you can help me gain favor with the Tribunal by destroying the fire elementals in Charred Vale. When destroyed, the fire elementals leave Incendrites. Return these to me and be rewarded.",
    isForever = false,
  },
  [472] = {
    id = 472,
    title = "Fall of Dun Modr",
    reqLevel = 25,
    questLevel = 25,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Harlo Barnaby",
    objectives = "Search for Longbraid near the town of Dun Modr.",
    rewards = "1,000 XP",
    tip = "Dun Modr has fallen to the Dark Iron Dwarves!\n\nMy wounds are grave, $c.  Most of the regiment was killed!  The Dark Iron thugs attacked us before we could regroup from the Thandol Span ambush.\n\nOur leader, Longbraid, sounded the retreat horn.  As we left the town I was hit by a stray axe in the back.  All went black.\n\nI awoke here in Menethil but I fear for my fellow soldiers.  Hope still burns within me.  Perhaps Longbraid is still alive!  See if you can find him near Dun Modr, $r!",
    isForever = false,
  },
  [453] = {
    id = 453,
    title = "Finding the Shadowy Figure",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Tavernkeep Smitts",
    objectives = "Find the Shadowy Figure.  Your clues:\n\nHe is not native to Darkshire.\n\nHe is a nervous, jittery person.\n\nHe left Darkshire and headed west.",
    rewards = "1,000 XP",
    tip = "Good luck, $N.  I hope you find the chap, and I hope you find him alive.\n\nIf he's left the safety of Darkshire then he could be prey to the beasts of the wilds.",
    isForever = false,
  },
  [9388] = {
    id = 9388,
    title = "Flickering Flames in Kalimdor",
    reqLevel = 1,
    questLevel = 25,
    faction = "Both",
    zone = "Azeroth",
    npc = "Quest Event / Discovery",
    objectives = "- Flame of Ashenvale - Flame of the Barrens - Flame of Darkshore - Flame of Stonetalon",
    rewards = "Experience & Faction Reputation",
    tip = "There are many flames burning throughout the world today, $n. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?\n\nYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.",
    isForever = false,
  },
  [9389] = {
    id = 9389,
    title = "Flickering Flames in the Eastern Kingdoms",
    reqLevel = 1,
    questLevel = 25,
    faction = "Both",
    zone = "Azeroth",
    npc = "Quest Event / Discovery",
    objectives = "- Flame of Hillsbrad - Flame of Silverpine - Flame of Westfall - Flame of the Wetlands",
    rewards = "Experience & Faction Reputation",
    tip = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.",
    isForever = false,
  },
  [126] = {
    id = 126,
    title = "Howling in the Hills",
    reqLevel = 15,
    questLevel = 25,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Verner Osgood",
    objectives = "Bring Yowler's Paw to Verner Osgood in Lakeshire.",
    rewards = "2,000 XP",
    tip = "$N, the gnolls are still out there.  I can hear their baying as they hunt in the hills above Lakeshire.  And one cry is louder than the rest - Yowler,  their leader.\n\nKill Yowler and send his pack scattering!  Bring me his paw as proof.\n\nAnd be careful, this gnoll is their leader for a reason.  He is no Mongrel...",
    isForever = false,
  },
  [3369] = {
    id = 3369,
    title = "In Nightmares",
    reqLevel = 15,
    questLevel = 25,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Falla Sagewind",
    objectives = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.",
    rewards = "2,000 XP",
    tip = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.\n\nHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more.",
    isForever = false,
  },
  [3370] = {
    id = 3370,
    title = "In Nightmares",
    reqLevel = 15,
    questLevel = 25,
    faction = "Alliance",
    zone = "The Barrens",
    npc = "Falla Sagewind",
    objectives = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.",
    rewards = "2,000 XP",
    tip = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... \n\nMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.",
    isForever = false,
  },
  [266] = {
    id = 266,
    title = "Inquire at the Inn",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Clerk Daltry",
    objectives = "Search the inn for clues about the shadowy figure.",
    rewards = "200 XP",
    tip = "Here is your book, and good luck with your inquiries.\n\nYou might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there.",
    isForever = false,
  },
  [174] = {
    id = 174,
    title = "Look To The Stars",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Viktori Prism'Antras",
    objectives = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.",
    rewards = "2,000 XP",
    tip = "My Gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars.  A truth exists, beyond magic, that can explain the strange transformation in the forest.\n\nBring to me a bronze tube made by a skilled engineer.  That is the first step, according to Cog's blueprint.",
    isForever = false,
  },
  [175] = {
    id = 175,
    title = "Look To The Stars",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Viktori Prism'Antras",
    objectives = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.",
    rewards = "1,000 XP",
    tip = "According to Cog's blueprint, what I need now is a way to reflect light.  I remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .",
    isForever = false,
  },
  [177] = {
    id = 177,
    title = "Look To The Stars",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Blind Mary",
    objectives = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.",
    rewards = "1,500 XP",
    tip = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an Insane Ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.",
    isForever = false,
  },
  [1017] = {
    id = 1017,
    title = "Mage Summoner",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Sentinel Velene Starstrike",
    objectives = "Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.",
    rewards = "2,550 XP",
    tip = "There's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me.\n\n$n, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels.\n\nDestroy him and bring me his head. Be wary though, the Horde may be watching for you.",
    isForever = false,
  },
  [7925] = {
    id = 7925,
    title = "Mark of Honor",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Warsong Mark of Honor for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to rage against the Silverwing Sentinels! Bring me more marks of honor!",
    isForever = false,
  },
  [4542] = {
    id = 4542,
    title = "Message to Freewind Post",
    reqLevel = 23,
    questLevel = 25,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Brave Moonhorn",
    objectives = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post.",
    rewards = "510 XP, 1s 75c",
    tip = "Brave traveler, the centaurs have increased their attacks in this area. Freewind Post must know about this renewed harassment immediately! Seek Cliffwatcher Longhorn at Freewind Post to the southeast and give him this urgent message.\n\nBe warned, avoid the Grimtotem Clan nearby... they have been acting strange toward us lately.",
    isForever = false,
  },
  [219] = {
    id = 219,
    title = "Missing In Action",
    reqLevel = 19,
    questLevel = 25,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Corporal Keeshan",
    objectives = "Protect Corporal Keeshan on the journey back to Redridge.",
    rewards = "2,550 XP",
    tip = "At last, friends of the Alliance!\n\nHelp... please... \n\nThe last thing I remember these foul Orcs overpowered our regiment.  Most the men were killed. I took a strong blow to the head and everything went black. Now I am held captive in this cave.  Help me, I am hurt badly.\n\nI'll need help getting back to town... please... you're my last hope...",
    isForever = false,
  },
  [8158] = {
    id = 8158,
    title = "More Resource Crates",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "",
    tip = "War must be fought with soldiers, any soldier will tell you. They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important. There are key areas in the basin that hold essential resources. Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N. Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [8165] = {
    id = 8165,
    title = "More Resource Crates",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi. They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe. We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N. Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman. Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
  [6381] = {
    id = 6381,
    title = "New Life",
    reqLevel = 17,
    questLevel = 25,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Tammra Windfield",
    objectives = "Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.",
    rewards = "2,000 XP",
    tip = "As you have seen, $c, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale. Beware, for harpies and angry fire elementals still plague the scarred land.\n\n$N, take these enchanted Gaea seeds and plant them in fertile mounds of soil. The cycle of life must go on!",
    isForever = false,
  },
  [4841] = {
    id = 4841,
    title = "Pacify the Centaur",
    reqLevel = 23,
    questLevel = 25,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Cliffwatcher Longhorn",
    objectives = "- Galak Scout x 12 - Galak Wrangler x 10 - Galak Windchaser x 6",
    rewards = "2,000 XP, 18s",
    tip = "$N, I entreat you to hunt these centaur down. They shall feel the wrath of our revenge. Attack the centaur camp to the north of Freewind Post!  Let wrath guide your hand!",
    isForever = false,
  },
  [7789] = {
    id = 7789,
    title = "Quell the Silverwing Usurpers",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Captain Shatterskull",
    objectives = "- Warsong Gulch Mark of Honor",
    rewards = "2,000 XP, 55s",
    tip = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.",
    isForever = false,
  },
  [281] = {
    id = 281,
    title = "Reclaiming Goods",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Karl Boran",
    objectives = "Search the crates and barrels at the coastal Murloc camps.",
    rewards = "510 XP",
    tip = "Not long ago a merchant vessel, the Blind Princess, was raided by Murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal Murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil Statuette and return it to me.",
    isForever = false,
  },
  [286] = {
    id = 286,
    title = "Return the Statuette",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Object: Half-buried Barrel",
    objectives = "Bring Karl Boran the Menethil Statuette.",
    rewards = "1,500 XP",
    tip = "After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired Paladin with hammer upraised.\n\nThis must be the Menethil Statuette!  You must now return it to Karl Boran in Menethil Harbor.",
    isForever = false,
  },
  [268] = {
    id = 268,
    title = "Return to Sven",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Jitters",
    objectives = "Return to Sven with Jitters' completed journal.",
    rewards = "510 XP",
    tip = "The book you found was only half finished.  I had to leave it at Sven's farm when I fled there...\n\nHere.  Take my completed journal to Sven.  It describes more fully what happened at his farm.\n\nAlthough this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!",
    isForever = false,
  },
  [1009] = {
    id = 1009,
    title = "Ruuzel",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Talen",
    objectives = "Bring the Ring of Zoram to Talen near the Zoram Strand.",
    rewards = "2,550 XP",
    tip = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock.\n\nThat key is a ring, the Ring of Zoram.  It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on an isle on the northern edge of Zoram.  Please, $N, retrieve the ring for me!",
    isForever = false,
  },
  [285] = {
    id = 285,
    title = "Search More Hovels",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Object: Sealed Barrel",
    objectives = "Continue searching the Murloc hovels for the Menethil Statuette.",
    rewards = "1,000 XP",
    tip = "This grouping of Murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil Statuette!",
    isForever = false,
  },
  [90] = {
    id = 90,
    title = "Seasoned Wolf Kabobs",
    reqLevel = 18,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Chef Grual",
    objectives = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.",
    rewards = "2,000 XP • 18s",
    tip = "Seasoned Wolf Kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.  Bring me 10 Lean Wolf Flanks as well as some Stormwind Seasoning Herbs.  There are so many wolves here in the forest, I am sure finding the Flanks will be no problem.  For the herbs, seek out Felicia Gump in her canal district flower shop in Stormwind.",
    isForever = false,
  },
  [546] = {
    id = 546,
    title = "Souvenirs of Death",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Deathguard Samsa",
    objectives = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.",
    rewards = "2,550 XP",
    tip = "I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad.  So jealous I am. . .\n\nWhile you're off having all the fun -- slaying humans, pillaging the town, terrorizing innocent people -- I am stuck standing guard here in Tarren Mill.\n\nPerhaps you'll take pity on an old Deathguard like myself?  You see I am collecting human skulls.  And you will be fighting humans for quite some time.  Over the course of your long battle, bring me 30 skulls and I will make it worth your while.",
    isForever = false,
  },
  [25] = {
    id = 25,
    title = "Stonetalon Standstill",
    reqLevel = 23,
    questLevel = 25,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Mastok Wrilehiss",
    objectives = "Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.\n\nScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.\n\nReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
    rewards = "2,000 XP • 18s",
    tip = "If you want to be useful, then why don't you do something about the situation near Talondeep Path?\n\nThe transports between Ashenvale and Stonetalon are at a standstill because of the lake coming alive and attacking anything that gets close... which means anyone on the path.  What'd be even more useful than just putting the hammer down on the water elementals there is someone scouting the gazebo on Mystral Lake - the one that has a solid view of the Alliance outpost there.\n\nYou up for being usefu",
    isForever = false,
  },
  [230] = {
    id = 230,
    title = "Sven's Camp",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Object: Mound of loose dirt",
    objectives = "Bring the Book from Sven's Farm to Sven.",
    rewards = "1,000 XP",
    tip = "Digging through the mound, you find a small, dirt-stained book.\n\nThe book has no title, but...it has information Sven would like to know.",
    isForever = false,
  },
  [95] = {
    id = 95,
    title = "Sven's Revenge",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sven Yorgen",
    objectives = "Go to Sven's Farm and find what was buried behind the old stump.",
    rewards = "1,000 XP",
    tip = "I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!\n\nWhen I returned I saw a shadowy figure skulking near my barn, burying something.  He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders.  So I never discovered what was hidden.\n\nIf you can find what that shadowy figure buried, I would be grateful.  The hiding spot is behind the old stump near my ",
    isForever = false,
  },
  [7921] = {
    id = 7921,
    title = "Talismans of Merit",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to aid the cause and bring me more talismans of merit. Do this, and you will earn even more of our trust.",
    isForever = false,
  },
  [19] = {
    id = 19,
    title = "Tharil'zun",
    reqLevel = 18,
    questLevel = 25,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Marshal Marris",
    objectives = "Bring Tharil'zun's Head to Marshal Marris in Redridge.",
    rewards = "2,550 XP",
    tip = "Pro-tip: Important step in the Forsaken Royal Apothecary Society questline in Kalimdor.",
    isForever = false,
  },
  [8168] = {
    id = 8168,
    title = "The Battle for Arathi Basin!",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Field Marshal Oslight",
    objectives = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.",
    rewards = "2,000 XP • 35s",
    tip = "$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.",
    isForever = false,
  },
  [8171] = {
    id = 8171,
    title = "The Battle for Arathi Basin!",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathmaster Dwire",
    objectives = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
    rewards = "2,000 XP • 35s",
    tip = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, $N.  Report back to me when this task is compl",
    isForever = false,
  },
  [165] = {
    id = 165,
    title = "The Hermit",
    reqLevel = 17,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Elaine Carevin",
    objectives = "Check on the old man in the shack near Raven Hill cemetery.",
    rewards = "1,000 XP",
    tip = "There was an old man who used to come into town to buy supplies rather frequently, but I haven't seen him for quite some time now. He lives out in a shack overlooking Raven Hill cemetery, if I remember correctly. Perhaps you should go see if something is amiss.",
    isForever = false,
  },
  [1740] = {
    id = 1740,
    title = "The Orb of Soran'ruk",
    reqLevel = 20,
    questLevel = 25,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Doan Karhan",
    objectives = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.",
    rewards = "2,550 XP",
    tip = "When demons of the Legion fall out of favor, their spirits are imprisoned within orbs and distributed to their mages and warlocks.\n\nMany were carried by their servants in Azeroth. Even fragmented, they still possess the powers of the demons trapped inside.\n\nThe orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps. The other, larger piece, was possessed by a wizard in Shadowfang Keep. Find them and I can refor",
    isForever = false,
  },
  [3513] = {
    id = 3513,
    title = "The Runed Scroll",
    reqLevel = 15,
    questLevel = 25,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Item: Runed Scroll",
    objectives = "Take the Runed Scroll to the northern guard tower in the Barrens.",
    rewards = "2,550 XP",
    tip = "The official-looking scroll is wrapped tightly with a silvery ribbon. You're sure someone would be interested in seeing this, but who?\n\nThere is an outpost close to the Ashenvale border to the north, and if the information on this scroll involves the night elves, this would be the place to take it.",
    isForever = false,
  },
  [1195] = {
    id = 1195,
    title = "The Sacred Flame",
    reqLevel = 20,
    questLevel = 25,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Zangen Stonehoof",
    objectives = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.",
    rewards = "2,550 XP • 35s",
    tip = "The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.\n\nWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.\n\nTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.",
    isForever = false,
  },
  [284] = {
    id = 284,
    title = "The Search Continues",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Object: Damaged Crate",
    objectives = "Search for the Menethil Statuette.",
    rewards = "510 XP",
    tip = "You thoroughly search this cluster of Murloc hovels, and find no trace of the Menethil Statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.",
    isForever = false,
  },
  [262] = {
    id = 262,
    title = "The Shadowy Figure",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sven Yorgen",
    objectives = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.",
    rewards = "510 XP",
    tip = "I must know who was that skulker in the shadows I saw the night my family was killed!\n\nPlease, $N, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds!\n\nI do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner.",
    isForever = false,
  },
  [265] = {
    id = 265,
    title = "The Shadowy Search Continues",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Madame Eva",
    objectives = "See if other townsfolk have clues about the shadowy figure.",
    rewards = "200 XP",
    tip = "Here is your book back, $N, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues.\n\nAnd here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here.",
    isForever = false,
  },
  [1651] = {
    id = 1651,
    title = "The Tome of Valor",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Daphne Stilwell",
    objectives = "Defend Daphne Stilwell from the Defias attack.\n\nNeither of your spirits must be released from their mortal coils if you wish to succeed.\n\nAfter you are successful, speak to Daphne Stilwell again.",
    rewards = "1,000 XP",
    tip = "Now, they'll be coming again soon, I'd wager, so get yourself ready.\n\nI've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own.\n\nI've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier.\n\nAsk the Light for whatever blessings you can because... did you hear that? I think they're coming.\n\nWe make our stand near the house!",
    isForever = false,
  },
  [1652] = {
    id = 1652,
    title = "The Tome of Valor",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Daphne Stilwell",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "2,550 XP",
    tip = "Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.\n\nHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.\n\nOh, how I miss my husband. I can't wait till he returns.",
    isForever = false,
  },
  [3567] = {
    id = 3567,
    title = "To the Top",
    reqLevel = 25,
    questLevel = 25,
    faction = "Both",
    zone = "Feralas",
    npc = "Marli Wishrunner",
    objectives = "Speak with Marli Wishrunner in Feralas.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [1199] = {
    id = 1199,
    title = "Twilight Falls",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Blackfathom Deeps",
    npc = "Argent Guard Manados",
    objectives = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.",
    rewards = "2,550 XP",
    tip = "Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.",
    isForever = false,
  },
  [7788] = {
    id = 7788,
    title = "Vanquish the Invaders!",
    reqLevel = 20,
    questLevel = 25,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Sentinel Farsong",
    objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
    rewards = "2,000 XP • 55s",
    tip = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.",
    isForever = false,
  },
  [6546] = {
    id = 6546,
    title = "Warsong Outrider Update",
    reqLevel = 17,
    questLevel = 25,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Warsong Outrider",
    objectives = "- Warsong Report",
