    isForever = false,
  },
  [885] = {
    id = 885,
    title = "Washte Pawne",
    reqLevel = 10,
    questLevel = 25,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Item: Washte Pawne's Feather",
    objectives = "Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.",
    rewards = "1,500 XP",
    tip = "The feather of Washte Pawne is painful to the touch.",
    isForever = false,
  },
  [386] = {
    id = 386,
    title = "What Comes Around...",
    reqLevel = 22,
    questLevel = 25,
    faction = "Alliance",
    zone = "The Stockade",
    npc = "Guard Berton",
    objectives = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.",
    rewards = "2,000 XP",
    tip = "Targorr the Dread served under Gath'Ilzogg as supreme Executioner.  His methods were ruthless, even by filthy orc standards.  Men who fought bravely to defend the Kingdom were tortured on his whim.  Now he is being held in the Stormwind Stockade, sentenced to die.  Yet something is amiss.  One of the bureaucratic nobles put a hold on his execution.  I am sure foul play is in the works.\n\nPut an end to Targorr the Dread, $N.  Travel to The Stockade and behead him before trickery is upon us.",
    isForever = false,
  },
  [4821] = {
    id = 4821,
    title = "Alien Egg",
    reqLevel = 24,
    questLevel = 26,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Hagar Lightninghoof",
    objectives = "- Alien Egg",
    rewards = "2,100 XP, 15s",
    tip = "A rumor has surfaced about an alien egg here in Thousand Needles. Those that report seeing this egg have failed to even get close enough to examine it in detail. Serpents guard the egg as if it's one of their own.\n\nI want you to seek out this alien egg and bring it to me so that I may examine it. Reports say the egg is located within a serpent den, but there are several serpent dens along the base of the cliff walls south and northeast of Freewind Post.",
    isForever = false,
  },
  [6565] = {
    id = 6565,
    title = "Allegiance to the Old Gods",
    reqLevel = 17,
    questLevel = 26,
    faction = "Horde",
    zone = "Blackfathom Deeps",
    npc = "Je'neu Sancrea",
    objectives = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.",
    rewards = "2,650 XP • 40s",
    tip = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, $N. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here at Zoram'gar when it's done.",
    isForever = false,
  },
  [471] = {
    id = 471,
    title = "Apprentice's Duties",
    reqLevel = 18,
    questLevel = 26,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "James Halloran",
    objectives = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.",
    rewards = "2,100 XP",
    tip = "I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him... Let's just say it wasn't a pretty sight.\n\nMidwife says he might pull through, but in the meantime I still need my skins!\n\n...If you'd like to kill a few more of the brutes, I wouldn't be opposed, after what they did. You'll find the crocs north up the coast, beyond the murloc hovels.",
    isForever = false,
  },
  [1942] = {
    id = 1942,
    title = "Astral Knot Garment",
    reqLevel = 26,
    questLevel = 26,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Wynne Larson",
    objectives = "Speak with Wynne Larson in Mage Class Quests.",
    rewards = "2,100 XP",
    tip = "",
    isForever = false,
  },
  [529] = {
    id = 529,
    title = "Battle of Hillsbrad",
    reqLevel = 19,
    questLevel = 26,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "High Executor Darthalia",
    objectives = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.$b$bRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.",
    rewards = "2,100 XP • 20s",
    tip = "The humans of Hillsbrad have been putting up unexpected resistance.  The problem appears to be that the townsfolk are being armed by the local blacksmith.  We need to shut down all supply lines.\n\nYour mission will be to execute Blacksmith Verringtan.  Slay his apprentices as well.  While there, bring back a shipment of iron from their stockpile.  The supplies will come in handy when we are done with the conquering of Hillsbrad and begin razing Southshore.",
    isForever = false,
  },
  [532] = {
    id = 532,
    title = "Battle of Hillsbrad",
    reqLevel = 19,
    questLevel = 26,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "High Executor Darthalia",
    objectives = "Kill Magistrate Burnside and 5 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards.",
    rewards = "2,100 XP • 20s",
    tip = "The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity.\n\nDespite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry.",
    isForever = false,
  },
  [275] = {
    id = 275,
    title = "Blisters on The Land",
    reqLevel = 20,
    questLevel = 26,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Rethiel the Greenwarden",
    objectives = "Kill 12 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.",
    rewards = "2,650 XP",
    tip = "I do not know why, but a festering grows within the Wetlands.  Fen Creepers have risen.  They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes.\n\nThe Fen Creepers shamble amidst the waterways of the Wetlands.",
    isForever = false,
  },
  [6283] = {
    id = 6283,
    title = "Bloodfury Bloodline",
    reqLevel = 18,
    questLevel = 26,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Maggran Earthbinder",
    objectives = "Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.",
    rewards = "2,100 XP",
    tip = "Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!\n\nShe is all but a queen to those filthy creatures. Slay her and their numbers will surely diminish.\n\nGo back into the Charred Vale and you will find her along the western hills. She will not be easy to vanquish, but the reward will be great.",
    isForever = false,
  },
  [1221] = {
    id = 1221,
    title = "Blueleaf Tubers",
    reqLevel = 20,
    questLevel = 26,
    faction = "Both",
    zone = "Azeroth",
    npc = "Mebok Mizzyrix",
    objectives = "Grab a Crate with Holes.\nGrab a Snufflenose Command Stick.\nGrab and read the Snufflenose Owner's Manual.\n\nIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",
    rewards = "2,100 XP",
    tip = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.",
    isForever = false,
  },
  [377] = {
    id = 377,
    title = "Crime and Punishment",
    reqLevel = 22,
    questLevel = 26,
    faction = "Alliance",
    zone = "The Stockade",
    npc = "Councilman Millstipe",
    objectives = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.",
    rewards = "2,100 XP",
    tip = "As if the neglect for the residents of Duskwood was not bad enough, now the House of Nobles spits in the eye of the Darkshire Council with their decision to imprison Dextren Ward in Stormwind rather than behead the villain as per Lord Ebonlocke's sentence.\n\nWard was caught selling bodies from the cemetery to Morbent Fel, a crime punishable by death.  Yet Stormwind claims Ward as their prisoner.\n\nAssassinate Ward in The Stormwind Stockade - bring me his hand - and I shall reward you.",
    isForever = false,
  },
  [1083] = {
    id = 1083,
    title = "Enraged Spirits",
    reqLevel = 20,
    questLevel = 26,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Kaela Shadowspear",
    objectives = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.",
    rewards = "2,100 XP • 20s",
    tip = "I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.\n\nThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.\n\nBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.\n\nThe land has no chance to see Elune's smile while these creatures roam free.\n\nBring me their smoldering embers to show you've reduced their numbers.",
    isForever = false,
  },
  [6282] = {
    id = 6282,
    title = "Harpies Threaten",
    reqLevel = 18,
    questLevel = 26,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Maggran Earthbinder",
    objectives = "Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
    rewards = "2,100 XP • 20s",
    tip = "Tauren take pride as the protector of these lands. Undoubtedly you can guess why I am alarmed with the number of harpies that dwell here in Stonetalon.\n\nThe Bloodfuries are the source of the increasing number of harpies in Kalimdor; they encroach upon all likes of life preventing the innocent from leaving their boundaries.\n\nI need you to cull the harpies, $N!",
    isForever = false,
  },
  [1939] = {
    id = 1939,
    title = "High Sorcerer Andromath",
    reqLevel = 26,
    questLevel = 26,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "Bink",
    objectives = "Speak with High Sorcerer Andromath.",
    rewards = "1,050 XP",
    tip = "High Sorcerer Andromath wishes to speak with you, $N.  He is at the top of the wizard's sanctum, in the mage's district of Stormwind.\n\nIt would be wise to speak with him, for Andromath is one of the most powerful mages not locked away in Dalaran.  Council with him is high council indeed.",
    isForever = false,
  },
  [2479] = {
    id = 2479,
    title = "Hinott's Assistance",
    reqLevel = 20,
    questLevel = 26,
    faction = "Horde",
    zone = "Rogue Class Quests",
    npc = "Shenthul",
    objectives = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!",
    rewards = "1,050 XP",
    tip = "Take a sample of the mixture to Serge Hinott in Tarren Mill.\n\nIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use.",
    isForever = false,
  },
  [1058] = {
    id = 1058,
    title = "Jin'Zil's Forest Magic",
    reqLevel = 20,
    questLevel = 26,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Witch Doctor Jin'Zil",
    objectives = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.",
    rewards = "2,100 XP",
    tip = "So excited I am!\n\nThree little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of... what do they call it... forest magic!\n\nI'll need a good mess of Stonetalon sap. From those horrid felines, bring me some twilight whiskers. This calls for plenty of courser eyes, of course -- can never have enough eyes. Oh, and lest we forget, a precious scale from a fey dragon.\n\nHurry to Stonetalon Peak, $n, so I can brew some forest magic!",
    isForever = false,
  },
  [6621] = {
    id = 6621,
    title = "King of the Foulweald",
    reqLevel = 21,
    questLevel = 26,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Karang Amakkar",
    objectives = "Place Karang's Banner on the Foulweald Totem Mound.  Do not let the furbolgs destroy the banner.  Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.",
    rewards = "2,650 XP • 20s",
    tip = "$N, another tribe of Furbolgs,  the Foulweald, live southeast of Astranaar.  They are not as many as the Thistlefur, but their ferocity poses a future threat.  With a show of force, we can remove that threat.\n\nTake this banner, go to the Foulweald village and place it on their totem mound.  They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.\n\nGather your allies, $N.  This is no task for a single ",
    isForever = false,
  },
  [1945] = {
    id = 1945,
    title = "Laughing Sisters",
    reqLevel = 26,
    questLevel = 26,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Deino",
    objectives = "Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads.",
    rewards = "1,600 XP",
    tip = "For your services, I have arranged for the creation of your new robes, provided you can gather the needed materials...\n\nFor these robes, you must return to Ashenvale for the locks of hair from laughing sisters--dryads who gather near the Raynewood Retreat.\n\nWhen you have their hair, bring it to Kil'hala, a troll tailor at the Crossroads in the Barrens.  He will be expecting you, and will fashion your robes.",
    isForever = false,
  },
  [1946] = {
    id = 1946,
    title = "Nether-lace Garment",
    reqLevel = 26,
    questLevel = 26,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Kil'hala",
    objectives = "Speak with Kil'hala in Mage Class Quests.",
    rewards = "2,100 XP",
    tip = "",
    isForever = false,
  },
  [1940] = {
    id = 1940,
    title = "Pristine Spider Silk",
    reqLevel = 26,
    questLevel = 26,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "High Sorcerer Andromath",
    objectives = "Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind.",
    rewards = "1,600 XP",
    tip = "Your service has been unwavering, $N.  I think, perhaps, it is time you had a finer garment, one more suiting your station as an adept mage.  If you gather the needed materials, then we will arrange the robe made.\n\nYou must enter Duskwood and hunt carrion recluse spiders.  Extract their silk, but only the finest, most pristine silk will do.  When you have enough, take it to Wynne Larson, here in the mage district at the Larson Clothiers.  She will craft your robe.",
    isForever = false,
  },
  [387] = {
    id = 387,
    title = "Quell The Uprising",
    reqLevel = 22,
    questLevel = 26,
    faction = "Alliance",
    zone = "The Stockade",
    npc = "Warden Thelwater",
    objectives = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.",
    rewards = "2,650 XP • 40s",
    tip = "The uprising must be quelled!  I need your assistance.  If word gets out that the prison is overrun I will lose my job!  This is a case of foul play if I've ever seen one.  But what's important now is forcing these prisoners into submission for the safety of Stormwind.\n\nThe punishment for insurgency is death.  Kill some of these deviants!  That ought to get things under control.",
    isForever = false,
  },
  [1078] = {
    id = 1078,
    title = "Retrieval for Mauren",
    reqLevel = 17,
    questLevel = 26,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Collin Mauren",
    objectives = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.",
    rewards = "2,100 XP",
    tip = "Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co.\n\nWithin the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created.\n\nIf those basilisks still live, I would love to have a few of their scales.\n\nTake your time, it is no rush, but I can pay w",
    isForever = false,
  },
  [846] = {
    id = 846,
    title = "Revenge of Gann",
    reqLevel = 17,
    questLevel = 26,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Gann Stonespire",
    objectives = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.",
    rewards = "2,100 XP • 20s",
    tip = "It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon.\n\nI want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies.\n\nCollect these items and bring them to me. I will fashion a charge that the dwarves won't fo",
    isForever = false,
  },
  [849] = {
    id = 849,
    title = "Revenge of Gann",
    reqLevel = 17,
    questLevel = 26,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Gann Stonespire",
    objectives = "Destroy the flying machine at Bael Modan and return to Gann Stonespire.",
    rewards = "2,100 XP • 20s",
    tip = "Following Khazgorm's plans it should be no problem to fashion an explosive charge\n\nAh, there we go.\n\nNow, $n, I am going to entrust you with a special task. Take this explosive stick and use it to blow up the flying machine at Bael Modan.\n\nNot only is the flying machine a key part of the site's infrastructure it also serves as a weapon of war. More importantly it is an icon of power and an insult to the memory of my tribe.\n\nMake me proud by completing this heroic task and you shall be rewarded.",
    isForever = false,
  },
  [6441] = {
    id = 6441,
    title = "Satyr Horns",
    reqLevel = 21,
    questLevel = 26,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Pixel",
    objectives = "Collect 16 Satyr Horns for Pixel in Splintertree Post.",
    rewards = "2,100 XP • 20s",
    tip = "Heya! I've been traveling through Ashenvale, heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days.\n\nAfter asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be!\n\nTell you what, you collect the horns for me and I'll make it worth your",
    isForever = false,
  },
  [2922] = {
    id = 2922,
    title = "Save Techbot's Brain!",
    reqLevel = 20,
    questLevel = 26,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Tinkmaster Overspark",
    objectives = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.",
    rewards = "2,650 XP • 20s",
    tip = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!\n\nBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Tec",
    isForever = false,
  },
  [4865] = {
    id = 4865,
    title = "Serpent Wild",
    reqLevel = 24,
    questLevel = 26,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Hagar Lightninghoof",
    objectives = "Report your findings to Motega Firemane.",
    rewards = "1,050 XP",
    tip = "If I did not see that with my own eyes I would never have believed it to be true. Vengeance has come to Thousand Needles!\n\n<Hagar wipes his brow.>\n\n$N, you must act quickly! Go now and seek out Motega Firemane; he is located at Whitereach Post just northwest of Freewind Post along the road. He will know what to do!",
    isForever = false,
  },
  [1943] = {
    id = 1943,
    title = "Speak with Deino",
    reqLevel = 26,
    questLevel = 26,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Anastasia Hartwell",
    objectives = "Speak with Deino.",
    rewards = "210 XP",
    tip = "The troll mage Deino has need of your assistance, $N.  She resides in Orgrimmar, in the Darkbriar Lodge.",
    isForever = false,
  },
  [1149] = {
    id = 1149,
    title = "Test of Faith",
    reqLevel = 25,
    questLevel = 26,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Dorn Plainstalker",
    objectives = "If you have faith, leap from the planks overlooking Thousand Needles.",
    rewards = "1,050 XP",
    tip = "So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.\n\nMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.\n\nIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.\n\nThe first is a Test of Faith.",
    isForever = false,
  },
  [1013] = {
    id = 1013,
    title = "The Book of Ur",
    reqLevel = 16,
    questLevel = 26,
    faction = "Horde",
    zone = "Shadowfang Keep",
    npc = "Keeper Bel'dugur",
    objectives = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.",
    rewards = "2,100 XP",
    tip = "$N, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection.  Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken.\n\nEnter Shadowfang Keep and find the book.  Bring it to me, and I will report your service to our Dark Lady...",
    isForever = false,
  },
  [388] = {
    id = 388,
    title = "The Color of Blood",
    reqLevel = 22,
    questLevel = 26,
    faction = "Alliance",
    zone = "The Stockade",
    npc = "Nikova Raskol",
    objectives = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.",
    rewards = "2,650 XP • 40s",
    tip = "Bitterness flows through my veins like a cold river.  My grandson, Mac, was such a good boy.  A mere 14 years old.  When the army was sent off to the front, Mac took up arms to defend the city.  He was a guard in The Stockade, where the Defias gang is locked up.  Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang.  For that Mac was stabbed in the back.\n\nI want revenge.  Bring me 10 of their precious Wool Bandanas.  They are the color of ",
    isForever = false,
  },
  [6981] = {
    id = 6981,
    title = "The Glowing Shard",
    reqLevel = 15,
    questLevel = 26,
    faction = "Both",
    zone = "Wailing Caverns",
    npc = "Item: Glowing Shard",
    objectives = "Travel to Ratchet to find someone that can tell you more about the glowing shard.\n\nThen, deliver the shard as you are directed.",
    rewards = "2,650 XP",
    tip = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.",
    isForever = false,
  },
  [57] = {
    id = 57,
    title = "The Night Watch",
    reqLevel = 18,
    questLevel = 26,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Commander Althea Ebonlocke",
    objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.",
    rewards = "2,100 XP • 20s",
    tip = "$N, I'm getting reports of an undead infestation in the forest!  If you're up to the job, journey to the Raven Hill graveyard and slay 15 of those vile Skeletal Fiends and 15 Skeletal Horrors.  There are also reports of skeletons just south of Darkshire, in and around Tranquil Gardens Cemetery.  The undead must be driven from Duskwood!",
    isForever = false,
  },
  [2923] = {
    id = 2923,
    title = "Tinkmaster Overspark",
    reqLevel = 20,
    questLevel = 26,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Brother Sarno",
    objectives = "Speak with Tinkmaster Overspark in Ironforge.",
    rewards = "210 XP",
    tip = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad.  But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help.",
    isForever = false,
  },
  [169] = {
    id = 169,
    title = "Wanted: Gath'Ilzogg",
    reqLevel = 15,
    questLevel = 26,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Object: Wanted: Gath'Ilzogg",
    objectives = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.",
    rewards = "2,650 XP • 40s",
    tip = "Wanted! Gath'Ilzogg, Leader of the Blackrock attacks on Stonewatch Keep and raids against the township of Lakeshire. \n\nGath'Ilzogg is extremely dangerous.  He is reportedly holed up in the recently conquered keep plotting the Blackrock clan's further crimes against humanity.  The orc infestation must be quelled at all costs.  A gracious reward will be given to whatever brave soul can deliver the head of Gath'Ilzogg to Magistrate Solomon.",
    isForever = false,
  },
  [180] = {
    id = 180,
    title = "Wanted: Lieutenant Fangore",
    reqLevel = 15,
    questLevel = 26,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Object: Wanted: Lieutenant Fangore",
    objectives = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.",
    rewards = "2,650 XP • 40s",
    tip = "Wanted: Lieutenant Fangore\n\nKnown leader of the Shadowhide Gnoll Clan, working under the enemy of the Township and Kingdom, Morganth.  By mandate of Magistrate Solomon, this vile betrayer of Stormwind is wanted dead.  Show his paw to the Magistrate as proof of his death.",
    isForever = false,
  },
  [1944] = {
    id = 1944,
    title = "Waters of Xavian",
    reqLevel = 26,
    questLevel = 26,
    faction = "Horde",
    zone = "Mage Class Quests",
    npc = "Deino",
    objectives = "Bring the Xavian Water Sample to Deino in Orgrimmar.",
    rewards = "2,100 XP",
    tip = "The fabled city of Xavian lies nestled deep within eastern Ashenvale, and tales of its ancient knowledge are well known among the learned.  It is said that the waters of Xavian hold vast magical powers.\n\nI would have a sample of those waters, from their source.\n\nTake this flask and go to Xavian.  Gather water from the bottom of its highest waterfall, and return to me.  And use care as you move through that ancient city--satyrs now hold the ruins and do not like mages prying into their affairs.",
    isForever = false,
  },
  [6921] = {
    id = 6921,
    title = "Amongst the Ruins",
    reqLevel = 21,
    questLevel = 27,
    faction = "Horde",
    zone = "Blackfathom Deeps",
    npc = "Je'neu Sancrea",
    objectives = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
    rewards = "2,750 XP • 45s",
    tip = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n$N, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop th",
    isForever = false,
  },
  [1014] = {
    id = 1014,
    title = "Arugal Must Die",
    reqLevel = 18,
    questLevel = 27,
    faction = "Horde",
    zone = "Shadowfang Keep",
    npc = "Dalar Dawnweaver",
    objectives = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.",
    rewards = "3,300 XP",
    tip = "Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain.\n\nI shall see to it that his magic is eradicated, $n. But I leave it in your hands to see that Arugal meets the death he so deserves.\n\nTravel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!",
    isForever = false,
  },
  [1200] = {
    id = 1200,
    title = "Blackfathom Villainy",
    reqLevel = 18,
    questLevel = 27,
    faction = "Alliance",
    zone = "Blackfathom Deeps",
    npc = "Argent Guard Thaelrid",
    objectives = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.",
    rewards = "3,300 XP • 65s",
    tip = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Selgorm in Darnassus, $N, please.",
    isForever = false,
  },
  [6561] = {
    id = 6561,
    title = "Blackfathom Villainy",
    reqLevel = 18,
    questLevel = 27,
    faction = "Horde",
    zone = "Blackfathom Deeps",
    npc = "Argent Guard Thaelrid",
    objectives = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.",
    rewards = "3,300 XP • 65s",
    tip = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, $N, pleas",
    isForever = false,
  },
  [1095] = {
    id = 1095,
    title = "Further Instructions",
    reqLevel = 16,
    questLevel = 27,
    faction = "Both",
    zone = "Stonetalon Mountains",
    npc = "Sputtervalve",
    objectives = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.",
    rewards = "1,100 XP",
    tip = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.",
    isForever = false,
  },
  [1096] = {
    id = 1096,
    title = "Gerenzo Wrenchwhistle",
    reqLevel = 16,
    questLevel = 27,
    faction = "Both",
    zone = "Stonetalon Mountains",
    npc = "Ziz Fizziks",
    objectives = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.",
    rewards = "2,200 XP • 22s",
    tip = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.\n\nNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.\n\nIf you kill him for me, I'll make it worth your wh",
    isForever = false,
  },
  [133] = {
    id = 133,
    title = "Ghoulish Effigy",
    reqLevel = 20,
    questLevel = 27,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Abercrombie",
    objectives = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.",
    rewards = "1,650 XP • 22s",
    tip = "I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house!\n\nI want to make an effigy - a kind of \"scarecrow\" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders.\n\nGet the ribs for me, and I will repay you with some coin.",
    isForever = false,
  },
  [2926] = {
    id = 2926,
    title = "Gnogaine",
    reqLevel = 20,
    questLevel = 27,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Ozzie Togglevolt",
    objectives = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.",
    rewards = "2,200 XP • 22s",
    tip = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, $N.\n\nLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!",
    isForever = false,
  },
  [873] = {
    id = 873,
    title = "Isha Awak",
    reqLevel = 10,
    questLevel = 27,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Mahren Skyseer",
    objectives = "Bring the Heart of Isha Awak to Mahren Skyseer.",
    rewards = "2,750 XP",
    tip = "The grand Isha Awak is lord of these waters.  Great is his strength, and solemn his pride.  The humans on the coast fear him, for he has consumed many of their number.\n\nBut I do not fear him.  I am grateful he is here.  He is a worthy challenge, and honorable prey.\n\nIf you are ready, then swim out and search for Isha Awak, the Deep Doom.\n\nHis spirit dwells in his heart, and to hear its beat is to know your fate.",
    isForever = false,
  },
  [824] = {
    id = 824,
    title = "Je'neu of the Earthen Ring",
    reqLevel = 23,
    questLevel = 27,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Mastok Wrilehiss",
    objectives = "Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
    rewards = "2,200 XP",
    tip = "The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.\n\nLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.",
    isForever = false,
  },
  [874] = {
    id = 874,
    title = "Mahren Skyseer",
    reqLevel = 9,
    questLevel = 27,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Jorn Skyseer",
    objectives = "Speak with Mahren Skyseer.",
    rewards = "550 XP",
    tip = "You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway $ghim:her;.\n\nNot even the sea.\n\nFind my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways.\n\nBut be wary in your search for her, for the Barrens' coast is held by humans.",
    isForever = false,
  },
  [249] = {
    id = 249,
    title = "Morganth",
    reqLevel = 20,
    questLevel = 27,
    faction = "Alliance",
    zone = "Redridge Mountains",
    npc = "Object: Old Lion Statue",
    objectives = "Defeat Morganth.\n\nBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.",
    rewards = "2,750 XP",
    tip = "After much observation, I have discovered Morganth's plans.\n\nHe searches for the Scythe of Elune...and he may have found it!  If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might.\n\nI am not prepared to pit myself against Morganth, but I fear he must be dealt with now.  So you must enter the Tower of Ilgalar and face Morganth.\n\nDefeat him, and bring me his Pendant of Shadow.  Do this, and the kingdom will owe you much.",
    isForever = false,
  },
  [295] = {
    id = 295,
    title = "Ormer's Revenge",
    reqLevel = 22,
    questLevel = 27,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Ormer Ironbraid",
    objectives = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.",
    rewards = "2,200 XP • 22s",
    tip = "Now it's time to really make those dreaded Raptors regret their blood-thirst.  Just down below there are scores of Mottled Scytheclaws and Mottled Razormaws.  Make those rotten creatures pay by slaying 10 of each!",
    isForever = false,
  },
  [1026] = {
    id = 1026,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 27,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Shael'dryn",
    objectives = "Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.",
    rewards = "2,200 XP",
    tip = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nIf your goal is to find the next piece of the rod, then you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here, near Felwood. Once you have it, look for a small glade west of the road near the Felwood border... the chest should be hidden around there.",
    isForever = false,
  },
  [1057] = {
    id = 1057,
    title = "Reclaiming the Charred Vale",
    reqLevel = 20,
    questLevel = 27,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Keeper Albagorm",
    objectives = "Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
    rewards = "2,200 XP",
    tip = "As a protector of the forest spirits you can undoubtedly guess why I am alarmed.\n\nYou have traveled through these mountains to reach this peak. Surely you have seen the travesty which has befallen the land. Greed has led to the destruction of these sacred hills.\n\nThe Charred Vale to the south was set afire by the greedy mechanized army of industrialists. Worse yet, the Bloodfuries that have encroached on the land refuse us passage in to begin regrowth.\n\nDrive the wretched harpies out, $n!",
    isForever = false,
  },
  [1059] = {
    id = 1059,
    title = "Reclaiming the Charred Vale",
    reqLevel = 20,
    questLevel = 27,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Keeper Albagorm",
    objectives = "Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.",
    rewards = "2,200 XP",
    tip = "The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.\n\nFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.\n\nThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.\n\nSend word of our need! Seek him out at once!",
    isForever = false,
  },
  [5062] = {
    id = 5062,
    title = "Sacred Fire",
    reqLevel = 24,
    questLevel = 27,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Motega Firemane",
    objectives = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.",
    rewards = "2,200 XP • 22s",
    tip = "Arikara is a deadly creature that must be dealt with swiftly. In order to hunt her down you will need to light the sacred fire of life - this will summon Arikara.\n\nGo now and harvest the rare Incendia agave plant. Once you have harvested enough agave, seek council with Magatha Grimtotem on Elder Rise in Thunder Bluff. She is a powerful shaman that can enchant the agave plant to create a powder that will light the fire.\n\nTravel northeast to the Boiling Pool and gather Incendia Agave.",
    isForever = false,
  },
  [24] = {
    id = 24,
    title = "Shadumbra's Head",
    reqLevel = 20,
    questLevel = 27,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Item: Shadumbra's Head",
    objectives = "Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.",
    rewards = "2,200 XP",
    tip = "The once swift Shadumbra now lies still as you claim victory over it.  The head of the slain nightsaber is a fitting trophy for this fight of the Ashenvale Hunt.  Senani Thunderheart at Splintertree Post will want to see such a trophy to award you credit for this part of the Ashenvale Hunt.",
    isForever = false,
  },
  [1918] = {
    id = 1918,
    title = "The Befouled Element",
    reqLevel = 23,
    questLevel = 27,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Item: Befouled Water Globe",
    objectives = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
    rewards = "550 XP",
    tip = "The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.\n\nIt's not exactly common knowledge who might be interested in such a find; perhaps the person who originally sent you out to the lake, Mastok Wrilehiss at Splintertree Post, might have an idea.",
    isForever = false,
  },
  [2927] = {
    id = 2927,
    title = "The Day After",
    reqLevel = 20,
    questLevel = 27,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Gnoarn",
    objectives = "Speak with Ozzie Togglevolt in Kharanos.",
    rewards = "220 XP",
    tip = "You don't think I was always bald, do you? No $g sir:ma'am;! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.\n\n<Gnoarn shakes his fist in the air.>\n\nDamn those damned dirty troggs - damn them all!!\n\nPerhaps it's not too late, $N. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution.",
    isForever = false,
  },
  [378] = {
    id = 378,
    title = "The Fury Runs Deep",
    reqLevel = 22,
    questLevel = 27,
    faction = "Alliance",
    zone = "The Stockade",
    npc = "Motley Garmason",
    objectives = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.",
    rewards = "2,750 XP",
    tip = "You have proven your loyalty to King Magni, $c.  And your hatred for the Dark Iron scum is as great as my own.\n\nThere is a task I wish to complete myself but I am bound by honor to stay with Longbraid.  But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span.  It was by Deepfury's planning that Longbraid lost his kin.\n\nDeepfury is being held for political reasons in the Stormwind Stockade.  I want him dead, $N.  For Longbraid!  Bring me hi",
    isForever = false,
  },
  [288] = {
    id = 288,
    title = "The Third Fleet",
    reqLevel = 22,
    questLevel = 27,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "First Mate Fitzsimmons",
    objectives = "Buy First Mate Fitzsimmons a Flagon of Mead.",
    rewards = "220 XP",
    tip = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked  by Red Dragons.  Dragons controlled by Orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Oh, my head hammers and pounds!  I'll need a fresh drink if I'm to get a handle on this hangover and continue my tale.",
    isForever = false,
  },
  [6581] = {
    id = 6581,
    title = "Warsong Saw Blades",
    reqLevel = 22,
    questLevel = 27,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Pixel",
    objectives = "- Deadly Blunderbuss",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [6571] = {
    id = 6571,
    title = "Warsong Supplies",
    reqLevel = 22,
    questLevel = 27,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Locke Okarr",
    objectives = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.",
    rewards = "2,750 XP",
    tip = "We are in short supply of a few items at the Warsong lumber camp!\n\nPixel at Splintertree Post has our shipment of saw blades. It'll take a trip to Booty Bay to pick up a crate of axes from Wharfmaster Lozgil.\n\nOur shipment of oil and rope will be more difficult. The rope was pilfered by the Thistlefur and Foulweald furbolgs, and the satyrs intercepted the delivery of the oil and are now using it for detestable rituals in Night Run, Satyrnaar, and Xavian!\n\nCan you help me?",
    isForever = false,
  },
  [5088] = {
    id = 5088,
    title = "Arikara",
    reqLevel = 24,
    questLevel = 28,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Magatha Grimtotem",
    objectives = "Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.",
    rewards = "2,300 XP • 25s",
    tip = "Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead.\n\nThe enchantment that I have weaved into the Incendia powder will summon Arikara to you, $N.\n\nI fear she may be stalking Cairne Bloodhoof; too much Tauren lore has changed, and I fear this has angered Arikara. Move quickly before all is lost, $c!",
    isForever = false,
  },
  [4881] = {
    id = 4881,
    title = "Assassination Plot",
    reqLevel = 23,
    questLevel = 28,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Item: Assassination Note",
    objectives = "Warn Kanati Greycloud at Whitereach Post of the plot to kill him.",
    rewards = "2,300 XP",
    tip = "The Tauren, Kanati Greycloud is bold to set up a hunting camp in Thousand Needles. We must kill him to rid this hunting camp and all who may follow him. We will converge at the small post Southwest of the Great Lift.",
    isForever = false,
  },
  [539] = {
    id = 539,
    title = "Battle of Hillsbrad",
    reqLevel = 19,
    questLevel = 28,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "High Executor Darthalia",
    objectives = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.",
    rewards = "2,300 XP • 25s",
    tip = "The Hillsbrad Town Registry indicates that the Azureload Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories.\n\nEven though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azureload Mine fervently.\n\nThe mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance.",
    isForever = false,
  },
  [1705] = {
    id = 1705,
    title = "Burning Blood",
    reqLevel = 20,
    questLevel = 28,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Grimand Elmore",
    objectives = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.",
    rewards = "2,300 XP",
    tip = "I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, $N, then you can have the armor.\n\nTo make this armor, I need samples of burning blood and a burning rock.\n\nThe only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock.\n\nMay fortune grant you speed, $N.",
    isForever = false,
  },
  [5881] = {
    id = 5881,
    title = "Calling in the Reserves",
    reqLevel = 23,
    questLevel = 28,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Maggran Earthbinder",
    objectives = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.",
    rewards = "1,150 XP • 12s",
    tip = "The Horde does well keeping our troops fresh... since the Great War we have been prosperous here in Kalimdor.\n\nI need you to do me a favor, I have a lad by the name of Grish Longrunner protecting the Great Lift in the southern barrens. Give him this letter; the letter will let him know that I have a reserve warrior coming to relieve him of duty so that he can visit his family. He requested this sometime ago and he would be happy to hear the news.",
    isForever = false,
  },
  [2931] = {
    id = 2931,
    title = "Castpipe's Task",
    reqLevel = 25,
    questLevel = 28,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Gaxim Rustfizzle",
    objectives = "Speak with Master Mechanic Castpipe in Ironforge.",
    rewards = "230 XP",
    tip = "Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.\n\nCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!\n\nThose are good odds!",
    isForever = false,
  },
  [567] = {
    id = 567,
    title = "Dangerous!",
    reqLevel = 19,
    questLevel = 28,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Object: Dangerous!",
    objectives = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.",
    rewards = "2,300 XP",
    tip = "Dangerous!\n\nThe following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia:\n\nClerk Horrace Whitesteed.  Wanted for the murder of Deathguard Toma.\n\nCitizen Wilkes.  Wanted for the murder of Apothecary Eli.\n\nMiner Hackett.  Wanted for the murder of Deathstalker Fry.\n\nFarmer Kalaba.  Wanted for the ambush of supplies from the Undercity.\n\nAll of these enemies are hiding and will be hard to find.  A reward will be granted upon notice of their death.",
    isForever = false,
  },
  [509] = {
    id = 509,
    title = "Elixir of Agony",
    reqLevel = 24,
    questLevel = 28,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.",
    rewards = "2,300 XP • 25s",
    tip = "Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.\n\nAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?\n\nHere's the plan, $N: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.",
    isForever = false,
  },
  [513] = {
    id = 513,
    title = "Elixir of Agony",
    reqLevel = 24,
    questLevel = 28,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.",
    rewards = "1,150 XP",
    tip = "Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms.\n\nFirst I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed!\n\nHere, take this Mudsnout Composite and run it off to Master Faranell at once, $N.",
    isForever = false,
  },
  [1701] = {
    id = 1701,
    title = "Fire Hardened Mail",
    reqLevel = 20,
    questLevel = 28,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Furen Longbeard",
    objectives = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.",
    rewards = "2,300 XP",
    tip = "So I gave you a nice shield, but we don't have to stop there.  I know the secrets to make extremely hard mail armor.  It's not easy and it takes very rare materials, but if you're willing to do the legwork then I'll make a piece for you.\n\nWhat do you say, $N?  If you're up for the challenge, then I'll give you a list of what to get and where to get them.",
    isForever = false,
  },
  [1782] = {
    id = 1782,
    title = "Furen's Armor",
    reqLevel = 20,
    questLevel = 28,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Furen Longbeard",
    objectives = "Speak with Furen Longbeard in Warrior Class Quests.",
    rewards = "3,400 XP",
    tip = "",
    isForever = false,
  },
  [1700] = {
    id = 1700,
    title = "Grimand Elmore",
    reqLevel = 20,
    questLevel = 28,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Furen Longbeard",
    objectives = "Bring Furen's Notes to Grimand Elmore.",
    rewards = "570 XP",
    tip = "I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop.\n\nAnd duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me...",
    isForever = false,
  },
  [5064] = {
    id = 5064,
    title = "Grimtotem Spying",
    reqLevel = 24,
    questLevel = 28,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Cliffwatcher Longhorn",
    objectives = "- Secret Note #1 - Secret Note #2 - Secret Note #3",
    rewards = "2,300 XP",
    tip = "$N, you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks. We discovered that separate chests in Darkcloud Pinnacle hold these guarded messages.\n\n$N, if you succeed in this dangerous mission, I will reward you in kind.",
    isForever = false,
  },
  [1704] = {
    id = 1704,
    title = "Klockmort Spannerspan",
    reqLevel = 20,
    questLevel = 28,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Furen Longbeard",
    objectives = "Bring Furen's Notes to Klockmort Spannerspan.",
    rewards = "570 XP",
    tip = "I made a copy of my notes on the techniques I learned while making your armor, and need someone to take them to Klockmort Spannerspan.  He's a gnomish blacksmith in Ironforge and when he learns what I've learned... I bet he'll pull off his own beard in excitement.",
    isForever = false,
  },
  [1703] = {
    id = 1703,
    title = "Mathiel",
    reqLevel = 20,
    questLevel = 28,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Furen Longbeard",
    objectives = "Bring Furen's Notes to Mathiel.",
    rewards = "1,150 XP",
    tip = "I made a copy of my notes on the techniques I learned while making your armor, and need them sent to the blacksmith Mathiel.  He lives in Darnassus which is quite a long way off, but I'm sure he'll be very grateful to learn what I've learned.",
    isForever = false,
  },
  [4966] = {
    id = 4966,
    title = "Protect Kanati Greycloud",
    reqLevel = 23,
    questLevel = 28,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Kanati Greycloud",
    objectives = "Protect Kanati Greycloud from the centaur attack.",
    rewards = "2,300 XP",
    tip = "But, there may be more centaur than I thought, I ask you, $n, to fight with me against these vile assassins.",
    isForever = false,
  },
  [323] = {
    id = 323,
    title = "Proving Your Worth",
    reqLevel = 20,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sven Yorgen",
    objectives = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.",
    rewards = "2,300 XP • 18s",
    tip = "Morbent Fel is a necromancer, and an ally to the dark riders.  I would pit you against the power of Morbent Fel, but I will not send you against that vile fiend without first knowing your strength.\n\nYou have already proven your bravery to me, but if you truly wish to face the necromancer, then you must now prove your skill against his minions.",
    isForever = false,
  },
  [1027] = {
    id = 1027,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 28,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Shael'dryn",
    objectives = "Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.",
    rewards = "2,300 XP",
    tip = "The final piece of the rod was given to the druids of Dor'danil for safekeeping. I have no idea where they hid it. I'm sorry I can't help you more than that.\n\nAll I can tell you is to follow the road that leads towards the Barrens. The druids took shelter to the east of that road, but they won't be of much help to you: they were killed recently... it's something I don't like to think about much.\n\nWhen you find the final piece, bring it to me and I will help you reconstruct the rod.",
    isForever = false,
  },
  [1028] = {
    id = 1028,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 28,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Shael'dryn",
    objectives = "Find the hidden shrine and re-enchant Dartol's Rod.",
    rewards = "1,700 XP",
    tip = "Here is the completed rod, $N. Reconstructing it was simple... it's finding the shrine that has the power to recharge it that will be the hard part.\n\nWith some focus and effort it shouldn't be too hard for someone like you, who's already accomplished so much.\n\nHead southeast of here--there are very few paths, so be careful--and keep your eyes to the north. The shrine is hidden within the mountains that surround this glade.\n\nOnce there, place the rod within the shrine... the rest is magic. Hehe.",
    isForever = false,
  },
  [1029] = {
    id = 1029,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 28,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Shael'dryn",
    objectives = "Return to Raene Wolfrunner in Astranaar.",
    rewards = "230 XP",
    tip = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nGood luck, $N.",
    isForever = false,
  },
  [1030] = {
    id = 1030,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 28,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Raene Wolfrunner",
    objectives = "Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.",
    rewards = "1,700 XP",
    tip = "Alas, I'm not completely certain what he had in mind next.\n\nIf what he said was true about the rod's power, then it will allow you to take on another form altogether. Which form, I do not know.\n\nPerhaps he meant to use its powers to get closer to the tainted furbolgs, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was safe from the effects of Fel Moss.\n\nI would start your search southeast of Mystral ",
    isForever = false,
  },
  [1055] = {
    id = 1055,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 28,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Object: Hidden Shrine",
    objectives = "Return to Shael'dryn at the moonwell.",
    rewards = "230 XP",
    tip = "The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success.",
    isForever = false,
  },
  [1081] = {
    id = 1081,
    title = "Reception from Tyrande",
    reqLevel = 17,
    questLevel = 28,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Sentinel Thenysil",
    objectives = "Find Tyrande Whisperwind in Darnassus.",
    rewards = "3,400 XP",
    tip = "$N, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.\n\nIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.\n\nIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.",
    isForever = false,
  },
  [473] = {
    id = 473,
    title = "Report to Captain Stoutfist",
    reqLevel = 23,
    questLevel = 28,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Valstag Ironjaw",
    objectives = "Speak with Captain Stoutfist.",
    rewards = "230 XP",
    tip = "$N.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room.",
    isForever = false,
  },
  [66] = {
    id = 66,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Madame Eva",
    objectives = "Seek out the Clerk Daltry in the Darkshire Town Hall.",
    rewards = "230 XP",
    tip = "Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table.\n\nAfter taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan.\n\nSeek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all.",
    isForever = false,
  },
  [67] = {
    id = 67,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Clerk Daltry",
    objectives = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.",
    rewards = "1,150 XP",
    tip = "Stalvan, eh?  Let me check the town registry.\n\nStalvan. . .Stalvan. . .let's see.  Ah, here we go!  I have a record of a Mr. Stalvan Mistmantle.  The last recorded address is the Moonbrook Schoolhouse.  My, talk about outdated!\n\nDo me a favor will you, friend?  If you happen to go out to Moonbrook, let me know if you get any update on this fellow.  I like to keep the records clean.",
    isForever = false,
  },
  [68] = {
    id = 68,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Object: Old Footlocker",
    objectives = "Take the Dusty Unsent Letter to Clerk Daltry.",
    rewards = "1,700 XP",
    tip = "You find a Dusty Unsent Letter in the old footlocker.",
    isForever = false,
  },
  [69] = {
    id = 69,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Clerk Daltry",
    objectives = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.",
    rewards = "570 XP",
    tip = "Oh my!  Must have missed this the first time.  In the registry, right beneath the first address for Stalvan there's another one listed, only partially scratched out.  Looks like he was headed to The Lion's Pride Inn over in Goldshire.  Might want to check there, $N.",
    isForever = false,
  },
  [70] = {
    id = 70,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Innkeeper Farley",
    objectives = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.",
    rewards = "1,700 XP",
    tip = "The name Stalvan rings a bell.  I remember now.\n\nMany years back, on a stormy night, a messenger came in, seeking refuge for the night.  Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear.  Still wearing his bedclothes, he disappeared into the downpour.\n\nIn his haste he forgot his letters in the chest upstairs.  He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind.  Help yourself to it.",
    isForever = false,
  },
  [72] = {
    id = 72,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Caretaker Folsom",
    objectives = "Search through the packed up possessions for a clue.",
    rewards = "230 XP",
    tip = "My father was the caretaker of the estate long before I was.  He had to mop the blood up after the massacre.  But that's neither here nor there.\n\nThe last funds of the Flintridge trust have dried up.  Now the last of the family possessions are headed for auction.  Blame the tax vultures.  I guess if you're really itching to learn more you're free to look through this junk.  Who knows what you might find.",
    isForever = false,
  },
  [74] = {
    id = 74,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Object: Sealed Crate",
    objectives = "The Torn Journal page you discovered provides your next clue.",
    rewards = "1,150 XP",
    tip = "Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books.  Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page.",
    isForever = false,
  },
  [75] = {
    id = 75,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Marshal Haggard",
    objectives = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.",
    rewards = "1,150 XP",
    tip = "There was a bundle of parchments in the chest upstairs when I moved into this place.  I looked at them once when I first arrived but I gave up once the fog hazed over my peepers. \n\nDo an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character.  I'm pretty sure there's a faded journal page that might be of interest to you.  Bring it to me and I'll help in anyway I can.",
    isForever = false,
  },
  [78] = {
    id = 78,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Marshal Haggard",
    objectives = "Take the Faded Journal Page to Tavernkeep Smitts.",
    rewards = "570 XP",
    tip = "I know of someone who might be able to assist you.  Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire.  The Innkeeper there, Smitts, was quite an expert on the local lore.  Show him this page and see what he has to say about it.",
    isForever = false,
  },
  [79] = {
    id = 79,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Tavernkeep Smitts",
    objectives = "Take the muddy page to Commander Ebonlocke.",
    rewards = "230 XP",
    tip = "I followed the legend of that Stalvan character for years.  When those visiting nobles were slaughtered a few years back I went with Haggard to investigate.  I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods.  Your trail of evidence proves his guilt.  Take this to Commander Ebonlocke immediately and fill her in on what you've discovered!",
    isForever = false,
  },
  [80] = {
    id = 80,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Commander Althea Ebonlocke",
    objectives = "Show Clerk Daltry the Bloodstained Journal Page.",
    rewards = "230 XP",
    tip = "I have had my eye on that creep, Stalvan, for quite sometime.  But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt.\n\nIn all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting.  Show him this page and see if the writing matches that of the registry signature.",
    isForever = false,
  },
  [97] = {
    id = 97,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Clerk Daltry",
    objectives = "Report the news to Commander Ebonlocke.",
    rewards = "230 XP",
    tip = "Let Commander Ebonlocke know immediately that the handwriting matched, $N!  Her suspicions were correct!",
    isForever = false,
  },
  [1241] = {
    id = 1241,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 28,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Bishop DeLavey",
    objectives = "Find Jorgen in Stormwind City.",
    rewards = "230 XP",
    tip = "Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.\n\nI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.\n\nAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.\n\nIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instruct",
    isForever = false,
  },
  [1242] = {
    id = 1242,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 28,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Jorgen",
    objectives = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.",
    rewards = "230 XP",
    tip = "Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.\n\nI'm gonna only impress this on ya once more, $N: treat this matter seriously, and keep your yapper shut.\n\nYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.",
    isForever = false,
  },
  [1243] = {
    id = 1243,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 28,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Elling Trias",
    objectives = "Give the Sealed Note to Watcher Backus in Duskwood.",
    rewards = "230 XP",
    tip = "Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?\n\nAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!\n\nHere's what's gonna happen, $N. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.\n\nHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he",
    isForever = false,
  },
  [1274] = {
    id = 1274,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 28,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Thomas",
    objectives = "Find Bishop DeLavey in Stormwind Keep.",
    rewards = "230 XP",
    tip = "Excuse me, $g sir : madam;. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.\n\nIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.",
    isForever = false,
  },
  [1140] = {
    id = 1140,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 28,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Delgren the Purifier",
    objectives = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.",
    rewards = "2,300 XP",
    tip = "The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies.\n\nFrom Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale.\n\nBe careful out there, $n, the satyrs' blood-soaked temples can be unsettling even for a seasoned $c such as your",
    isForever = false,
  },
  [1167] = {
    id = 1167,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 28,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Delgren the Purifier",
    objectives = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.",
    rewards = "570 XP",
    tip = "Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.",
    isForever = false,
  },
  [299] = {
    id = 299,
    title = "Uncovering the Past",
    reqLevel = 25,
    questLevel = 28,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Prospector Whelgar",
    objectives = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.",
    rewards = "2,300 XP • 25s",
    tip = "Just before the invasion I uncovered a large tablet called the Goaz Stone.  The translated text breaks off in 4 places.  The text speaks of a \"divine plan\" and a \"doomed prophecy.\"\n\nI fear we are running out of time.  I am too old to go down and brave those beasts.  But you are strong.\n\nScour the excavation site and uncover the 4 missing tablet fragments: Ados, Modr, Golm and Neru.  Search for them in ancient artifacts or where the soil is loose.  Bring them to me so I can begin unlocking the my",
    isForever = false,
  },
  [1938] = {
    id = 1938,
    title = "Ur's Treatise on Shadow Magic",
    reqLevel = 26,
    questLevel = 28,
    faction = "Alliance",
    zone = "Mage Class Quests",
    npc = "High Sorcerer Andromath",
    objectives = "Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind.",
    rewards = "2,300 XP",
    tip = "Long ago, three mages studied in this tower until one fell to the dark arts.  He was urged to turn away from that evil magic, but he could not resist.  And so he was banished.\n\nThe fallen mage's new domain is the tower of Ilgalar in Redridge, and he took with him a powerful book--Ur's Treatise on Shadow Magic.\n\nWe, the mages of Stormwind, would have that book returned.  Enter the tower of Ilgalar, find the tome in his library, and bring it to me.",
    isForever = false,
  },
  [464] = {
    id = 464,
    title = "War Banners",
    reqLevel = 23,
    questLevel = 28,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Captain Stoutfist",
    objectives = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.",
    rewards = "2,300 XP • 25s",
    tip = "The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation.\n\nNow they've gained strength, and have an encampment northeast of Menethil.\n\nWe want you to attack that encampment.  Gather and bring me their war banners as proof.",
    isForever = false,
  },
  [173] = {
    id = 173,
    title = "Worgen in the Woods",
    reqLevel = 23,
    questLevel = 28,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Calor",
    objectives = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.",
    rewards = "1,150 XP • 18s",
    tip = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane Shadow Weaver worgen in Brightwood Grove--bright, hah!--and the Rotting Orchard.",
    isForever = false,
  },
  [1084] = {
    id = 1084,
    title = "Wounded Ancients",
    reqLevel = 22,
    questLevel = 28,
    faction = "Alliance",
    zone = "Stonetalon Mountains",
    npc = "Kaela Shadowspear",
    objectives = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.",
    rewards = "2,300 XP • 25s",
    tip = "It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.\n\nGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.\n\nI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.\n\nBring me some of the shrapnel so the gnome can tell me more...",
    isForever = false,
  },
  [1153] = {
    id = 1153,
    title = "A New Ore Sample",
    reqLevel = 25,
    questLevel = 29,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Tatternack Steelforge",
    objectives = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.",
    rewards = "2,350 XP • 25s",
    tip = "$C, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.\n\nTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to ex",
    isForever = false,
  },
  [325] = {
    id = 325,
    title = "Armed and Ready",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Grimand Elmore",
    objectives = "Bring Morbent's Bane to Sven in Duskwood.",
    rewards = "590 XP",
    tip = "Here is the weapon against the fiend of which you spoke.  You're all ready, $N.  Best of luck to you, and I look forward to your tale of glory!",
    isForever = false,
  },
  [8426] = {
    id = 8426,
    title = "Battle of Warsong Gulch",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "2,350 XP • 25s",
    tip = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!",
    isForever = false,
  },
  [8431] = {
