  [322] = {
    id = 322,
    title = "Blessed Arm",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Glorin Steelbrow",
    objectives = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.",
    rewards = "1,200 XP",
    tip = "There is a dwarven weaponsmith in the Dwarven District of Stormwind who can craft with lightforge iron.  His name is Grimand Elmore.\n\nI've packed the iron you found into a crate.  Take it to Grimand and tell him your tale.  I'm sure he'll oblige someone on a quest such as yours, and craft for you a weapon - a weapon to give even Morbent Fel worry!",
    isForever = false,
  },
  [8374] = {
    id = 8374,
    title = "Claiming Arathi Basin",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "2,350 XP • 25s",
    tip = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Bas",
    isForever = false,
  },
  [8384] = {
    id = 8384,
    title = "Claiming Arathi Basin",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "1,200 XP",
    tip = "Winning a war is about more than just outsmarting and outfighting your opponent. Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops. If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us! Now is the time to help the Alliance in Arathi Basin,",
    isForever = false,
  },
  [8370] = {
    id = 8370,
    title = "Conquering Arathi Basin",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "2,350 XP • 25s",
    tip = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $N!",
    isForever = false,
  },
  [8390] = {
    id = 8390,
    title = "Conquering Arathi Basin",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "1,200 XP",
    tip = "Our conflict with the Alliance has escalated to a true war. No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple. Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going. Help the Defilers maintain the flow of resources we need, $N!",
    isForever = false,
  },
  [8399] = {
    id = 8399,
    title = "Fight for Warsong Gulch",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "2,350 XP • 25s",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
    isForever = false,
  },
  [8404] = {
    id = 8404,
    title = "Fight for Warsong Gulch",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "1,200 XP",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest. There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack. Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N! For the Alliance!",
    isForever = false,
  },
  [1011] = {
    id = 1011,
    title = "Forsaken Diseases",
    reqLevel = 24,
    questLevel = 29,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Kayneth Stillwind",
    objectives = "Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.",
    rewards = "2,350 XP",
    tip = "The Forsaken, the undead arm of the Horde, have crept into Ashenvale, lurking at our ruins and our barrows.  We believe their goal is to spread disease amongst the lands of the night elves.  We must confirm this!\n\nThe Forsaken have a camp south of here, near the Dor'Danil Barrow Den, where they create poisons and diseases and place them in bottles.  Fight your way into that camp and steal a bottle of disease.  Return with such a bottle.  I will test it and find its purpose.",
    isForever = false,
  },
  [4904] = {
    id = 4904,
    title = "Free at Last",
    reqLevel = 25,
    questLevel = 29,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Lakota Windsong",
    objectives = "Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.",
    rewards = "2,350 XP",
    tip = "Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong. He... he slew my brother and then brought me here.  My poor brother...\n\n$N, could you escort me out of the Darkcloud Pinnacle?  Please... I need to get back to Thalia! She must be worried sick about me.",
    isForever = false,
  },
  [4770] = {
    id = 4770,
    title = "Homeward Bound",
    reqLevel = 25,
    questLevel = 29,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Pao'ka Swiftmountain",
    objectives = "Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.",
    rewards = "2,350 XP • 19s",
    tip = "Please help me, $c! I've been hiding here in Highperch for some time now and it's been days since I've seen a friendly face. I came here to study the wyvern and I think I got a little too close. After being chased away from one of the nests I got lost.\n\nI need to get back to Whitereach Post! Motega does not know that I am missing and will be furious to know that I ventured into Highperch by myself.\n\nWhitereach Post is just east of here... please take me there!",
    isForever = false,
  },
  [3514] = {
    id = 3514,
    title = "Horde Presence",
    reqLevel = 15,
    questLevel = 29,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Kadrak",
    objectives = "Kill the leader of the Talon Den, Rynthariel the Keymaster.",
    rewards = "2,950 XP",
    tip = "This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak.\n\nShe'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here. The Horde will not tolerate her outrunners here.\n\n$N, travel to the Talon Den. Kill Rynthariel, and then put up a symbol for all to see. Take this Horde flag, $N. Put it up in the Talon Den so that they will not be so rash as to send another messenger through our territory again.",
    isForever = false,
  },
  [1708] = {
    id = 1708,
    title = "Iron Coral",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Klockmort Spannerspan",
    objectives = "Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge.",
    rewards = "1,750 XP",
    tip = "I want to try Furen Longbeard's new techniques on my own piece of armor.  And because you helped Furen and he helped me, you're welcome to the armor after I make it!\n\nTo finish the piece, I need a special coral, searing coral.  It grows in only one place--along the coast south of Menethil Harbor in the Wetlands.\n\nBring me enough searing coral and I'll get right to work on the armor.  And hurry, $N.  I'm so eager to get started it's making my toes twist!",
    isForever = false,
  },
  [4581] = {
    id = 4581,
    title = "Kayneth Stillwind",
    reqLevel = 24,
    questLevel = 29,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Shindrell Swiftfire",
    objectives = "Take Shindrell's Note to Kayneth Stillwind in Forest Song.",
    rewards = "590 XP",
    tip = "The druid Kayneth Stillwind sent word to me.  He would like a report of the happenings along our coast and in the forests surrounding Astranaar.  He fears there is a corruption moving through Ashenvale... and he may be right.\n\nHere, take my report to him.  You will find him in the shrine of Forest Song, in the Nightsong Woods to the east.",
    isForever = false,
  },
  [526] = {
    id = 526,
    title = "Lightforge Ingots",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Glorin Steelbrow",
    objectives = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.",
    rewards = "1,750 XP",
    tip = "You might have found one lightforge ingot in that chest, but that's not enough to craft anything decent!\n\nYou should go back there and look for more.  Maybe the murlocs around that wrecked ship have lightforge ingots on them.",
    isForever = false,
  },
  [321] = {
    id = 321,
    title = "Lightforge Iron",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Glorin Steelbrow",
    objectives = "Search the wreckage of The Flying Osprey in the Wetlands.",
    rewards = "590 XP",
    tip = "The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War.\n\nThe Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it.  It was shipping a load of Lightforge Iron and joined the Third Fleet for protection.  Ironic that it sunk to the same dragons...\n\nEnough history.  The Flying Osprey is wrecked to the south of Menethil Harbor.  If you find the Lightforge Iron there, bring it to me.",
    isForever = false,
  },
  [1088] = {
    id = 1088,
    title = "Ordanus",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Braelyn Firehand",
    objectives = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.",
    rewards = "2,350 XP",
    tip = "They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head!\n\nMagic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short.\n\nBring it to me and I will share with you a mighty gift.",
    isForever = false,
  },
  [296] = {
    id = 296,
    title = "Ormer's Revenge",
    reqLevel = 22,
    questLevel = 29,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Ormer Ironbraid",
    objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.",
    rewards = "2,950 XP",
    tip = "While you were down there I happened to notice that one of those beasts stood out from the rest.  He was bigger and more menacing.  I bet he's the one who led the others here to cause the disruption to the dig site.\n\nI ask of you now one final task, $N.  See to it that Sarltooth is brought to justice.  And considering the gravity of his crimes, justice in this case means death!  Bring me one of his talons as proof of his death.",
    isForever = false,
  },
  [269] = {
    id = 269,
    title = "Seeking Wisdom",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sven Yorgen",
    objectives = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.",
    rewards = "590 XP",
    tip = "Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light.  Give him Jitters' journal and tell him you mean to face Morbent Fel.\n\nAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise.  He may help you on your quest to save us.\n\nYour mission is perilous, but hurry, $N.  With each passing hour, the shadows of Duskwood grow ever darker.",
    isForever = false,
  },
  [393] = {
    id = 393,
    title = "Shadow of the Past",
    reqLevel = 16,
    questLevel = 29,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Baros Alexston",
    objectives = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.",
    rewards = "590 XP",
    tip = "I really haven't a clue, $N. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city.\n\nIf anyone knows, it'd be him.",
    isForever = false,
  },
  [8847] = {
    id = 8847,
    title = "Ten Signets for War Supplies",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Battlegrounds",
    npc = "Field Marshal Snowfall",
    objectives = "Well then, it's settled; here are your supplies, $c. If you wish to do an additional exchange, then I am prepared to authorize it. Just give me the word and I'll make it happen.\n\nKeep up the good work, <player>. We need all the materiel we can muster if we're going to win this thing. If we all do our part, then victory shall be ours for the taking!",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [8852] = {
    id = 8852,
    title = "Ten Signets for War Supplies",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Battlegrounds",
    npc = "Warlord Gorchuk",
    objectives = "Well then, it's settled; here are your supplies, $c. If you wish to do an additional exchange, then I am prepared to authorize it. Just give me the word and I'll make it happen.\n\nKeep up the good work, <player>. We need all the materiel we can muster if we're going to win this thing. If we all do our part, then victory shall be ours for the taking!",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [392] = {
    id = 392,
    title = "The Curious Visitor",
    reqLevel = 16,
    questLevel = 29,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Warden Thelwater",
    objectives = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.",
    rewards = "590 XP",
    tip = "During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him.\n\nAnyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out.\n\nHis documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore.",
    isForever = false,
  },
  [289] = {
    id = 289,
    title = "The Cursed Crew",
    reqLevel = 22,
    questLevel = 29,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "First Mate Fitzsimmons",
    objectives = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.",
    rewards = "1,750 XP • 19s",
    tip = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north.  But although I'm the only member of the fleet still breathing, I'm not the only one still walking about!  For on one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nBut if you can free some of my brothers, then perhaps you can break their cur",
    isForever = false,
  },
  [1089] = {
    id = 1089,
    title = "The Den",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Stonetalon Mountains",
    npc = "Braelyn Firehand",
    objectives = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard.",
    rewards = "2,950 XP",
    tip = "The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items.\n\nThey devised a complex scheme to keep them from falling into the wrong hands.\n\nLuckily, I managed to... extract some details from one of them.\n\nHidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.",
    isForever = false,
  },
  [270] = {
    id = 270,
    title = "The Doomed Fleet",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Bishop Farthing",
    objectives = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.",
    rewards = "1,200 XP",
    tip = "Years ago, the Third Fleet of Kul'Tiras sunk along the coasts of The Wetlands, an expanse of marsh north of the Dwarven kingdom of Ironforge.  Aboard one ship was a load of Lightforge Iron.\n\nThis metal is precious to us, for items crafted from it strike with holy truth.  If you are to face Morbent Fel, then you will need such a weapon.\n\nGo to Menethil Harbor and speak with my dwarven colleague Glorin Steelbrow.  If that lost metal can be found, he'll know where to look.",
    isForever = false,
  },
  [324] = {
    id = 324,
    title = "The Lost Ingots",
    reqLevel = 20,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Object: Waterlogged Chest",
    objectives = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.",
    rewards = "1,750 XP",
    tip = "Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest.  Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron.",
    isForever = false,
  },
  [1196] = {
    id = 1196,
    title = "The Sacred Flame",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Zangen Stonehoof",
    objectives = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.",
    rewards = "590 XP",
    tip = "Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens.\n\nI wouldn't be surprised if you can help us out further.",
    isForever = false,
  },
  [1197] = {
    id = 1197,
    title = "The Sacred Flame",
    reqLevel = 20,
    questLevel = 29,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Rau Cliffrunner",
    objectives = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.",
    rewards = "2,350 XP",
    tip = "Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.\n\nYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.\n\nBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.",
    isForever = false,
  },
  [391] = {
    id = 391,
    title = "The Stockade Riots",
    reqLevel = 16,
    questLevel = 29,
    faction = "Alliance",
    zone = "The Stockade",
    npc = "Warden Thelwater",
    objectives = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.",
    rewards = "2,350 XP • 25s",
    tip = "Let's get one thing straight, $N: I don't trust you. But, with the situation as it is, you probably won't make a difference.\n\nSo here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots.",
    isForever = false,
  },
  [5147] = {
    id = 5147,
    title = "Wanted - Arnak Grimtotem",
    reqLevel = 25,
    questLevel = 29,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Object: Wanted Poster - Arnak Grimtotem",
    objectives = "Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.",
    rewards = "2,350 XP",
    tip = "Wanted: Arnak Grimtotem\n\nArnak the outcast is wanted for the heinous crimes of murder and kidnapping. Handsome rewards will be given to those brave enough to bring this criminal to justice.\n\nArnak was last seen on the cliffs near the Darkcloud Pinnacle. Show the proof of your deed to Cliffwatcher Longhorn in Freewind Post in order to claim the reward.",
    isForever = false,
  },
  [4767] = {
    id = 4767,
    title = "Wind Rider",
    reqLevel = 25,
    questLevel = 29,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Elu",
    objectives = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.",
    rewards = "1,750 XP • 19s",
    tip = "I've been tasked to recruit more wyverns for the master wind riders. Their numbers are growing and I myself hope to become a wind rider one day. However, we cannot train enough wyverns to keep up with the demand. Perhaps you can help me, $N.\n\nI need you to travel to Highperch to gather some wyvern eggs. From here, head northwest along the canyon walls to a ramp that will lead you into Highperch. Be careful, wyverns are very protective over their eggs and they will not be kind to intruders.",
    isForever = false,
  },
  [221] = {
    id = 221,
    title = "Worgen in the Woods",
    reqLevel = 23,
    questLevel = 29,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Calor",
    objectives = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.",
    rewards = "1,750 XP • 19s",
    tip = "You might have noticed some larger worgen wandering around with the Shadow Weavers in the woods? From what we can tell, these Dark Runners make up the bulk of the worgen numbers.\n\nOn my rangings, I've also noticed that they have overrun the Rotting Orchard southwest of town. These worgen are a bit tougher than the last you faced.\n\nBe on your guard.",
    isForever = false,
  },
  [2904] = {
    id = 2904,
    title = "A Fine Mess",
    reqLevel = 24,
    questLevel = 30,
    faction = "Both",
    zone = "Azeroth",
    npc = "Kernobee",
    objectives = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.",
    rewards = "2,450 XP",
    tip = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, $N!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!",
    isForever = false,
  },
  [686] = {
    id = 686,
    title = "A King's Tribute",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "King Magni Bronzebeard",
    objectives = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.",
    rewards = "1,200 XP",
    tip = "I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul.\n\nWhile I cannot bring her husband back from the Twisting Nether, I can pay tribute to him.\n\nI am going to commission a memorial to Sully Balloo to be built by Grand Mason Marblesten.\n\nSend word to him now, $c. You shall be custodian of my bidd",
    isForever = false,
  },
  [335] = {
    id = 335,
    title = "A Noble Brew",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Zardeth of the Black Claw",
    objectives = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.",
    rewards = "2,450 XP • 25s",
    tip = "Lord Wishock is causing quite a stir amongst the House of Nobles.  He was made aware of our little \"establishment\" down here and is lobbying for a full investigation.  I have a plan to keep Wishock \"preoccupied\", but I'll need your help. \n\nThere is a flower growing in the Garden of Stalvan on the outskirts of Darkshire.  This small white flower is known as the Tear of Tilloa.  I will also need a Musquash Root, found only at the very base of the falls far beneath the Stonewrought Dam in the Wetla",
    isForever = false,
  },
  [336] = {
    id = 336,
    title = "A Noble Brew",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Zardeth of the Black Claw",
    objectives = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.",
    rewards = "2,450 XP • 25s",
    tip = "Lord Wishock, like all men, has his weaknesses.  His happens to be a fondness for liquor.  The hypocrisy is astounding.  The trite fool spends his days trying to shut down our little \"tavern\" while his nights are spent upstairs, running up a bill he never pays.  Well, let's see how Wishock likes this special brew I have prepared for him:  Black Claw stout.  It's got quite a kick, $n.\n\nTake it to him and see how he likes it.  Most likely the old fool is milling about the Hall of Petitioners.",
    isForever = false,
  },
  [1431] = {
    id = 1431,
    title = "Alliance Relations",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Craven Drok",
    objectives = "Speak to Keldran in Orgrimmar.",
    rewards = "610 XP",
    tip = "Be still, $c, and allow me to share with you something important to our people, but far from obvious.\n\nWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.\n\nIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.",
    isForever = false,
  },
  [1432] = {
    id = 1432,
    title = "Alliance Relations",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Keldran",
    objectives = "Speak to Takata Steelblade in Desolace.",
    rewards = "1,200 XP",
    tip = "As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.\n\nI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.",
    isForever = false,
  },
  [1044] = {
    id = 1044,
    title = "Answered Questions",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Jonathan Carevin",
    objectives = "Return to Thyn'tel Bladeweaver in Darnassus.",
    rewards = "3,050 XP",
    tip = "We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, $n, and the darkness knows no respite.\n\nI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood.",
    isForever = false,
  },
  [6922] = {
    id = 6922,
    title = "Baron Aquanis",
    reqLevel = 21,
    questLevel = 30,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Item: Strange Water Globe",
    objectives = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
    rewards = "3,050 XP",
    tip = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.",
    isForever = false,
  },
  [541] = {
    id = 541,
    title = "Battle of Hillsbrad",
    reqLevel = 19,
    questLevel = 30,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "High Executor Darthalia",
    objectives = "Travel to Dun Garok and kill 10 Mountaineers, 8 Riflemen, 4 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.",
    rewards = "2,450 XP • 25s",
    tip = "Dwarves aiding the humans?  Damn those filthy little beasts.\n\nWe shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory.\n\nThey have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, $c.  Captain Ironhill, their leader, must die.",
    isForever = false,
  },
  [253] = {
    id = 253,
    title = "Bride of the Embalmer",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Lord Ello Ebonlocke",
    objectives = "Find Eliza's grave.  Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.",
    rewards = "3,650 XP",
    tip = "The Embalmer is a name told in one of our children's stories.  He was a kindly alchemist, driven mad by the death of his wife, Eliza.  To restore her, he used dark magic to place his own heart within the bosom of his dead spouse.\n\nThis revived Eliza...but it cursed her with a hunger for human flesh, forcing the Embalmer to keep her buried.\n\nHis heart is his power.  Find his wife's grave, retrieve his heart, and bring it to me while it still beats.  Do this and his power will be broken.",
    isForever = false,
  },
  [1838] = {
    id = 1838,
    title = "Brutal Armor",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Thun'grim Firegaze",
    objectives = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.",
    rewards = "3,650 XP",
    tip = "I have heard tales of your strength and valor, and wish to make for you a suit of armor, a companion to aid you as tales of your great deeds grow.\n\nBut the fashioning of this armor will be a quest unto itself, $N.  I will need your help, and the help of other smiths of the Horde.\n\nHere, take this scroll.  I spent many nights, struggling with near-blind eyes, writing that which I need for the armor.  Bring me the items on this scroll and I will create for you the first piece of the suit.",
    isForever = false,
  },
  [1843] = {
    id = 1843,
    title = "Brutal Gauntlets",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Ula'elek",
    objectives = "Speak with Ula'elek in Warrior Class Quests.",
