  [1531] = {
    id = 1531,
    title = "Call of Air",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Searn Firewarder",
    objectives = "Find Prate Cloudseer in Thousand Needles.",
    rewards = "2,450 XP",
    tip = "You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect.\n\nHead south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.",
    isForever = false,
  },
  [1532] = {
    id = 1532,
    title = "Call of Air",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Xanis Flameweaver",
    objectives = "Find Prate Cloudseer in Thousand Needles.",
    rewards = "2,450 XP",
    tip = "The winds of Kalimdor rush to meet you and you shall be counted among some of our most powerful $g brothers:sisters;. I am proud to see you have come this far and have such a promising future.\n\nThe element of air is a difficult one to control, but I have faith that your skills will overcome any obstacles that are placed in front of you.\n\nHead to the very south of the Barrens, and enter Thousand Needles. It is there, far to the east, that you will find Prate Cloudseer. She will teach you more.",
    isForever = false,
  },
  [1844] = {
    id = 1844,
    title = "Chimaeric Horn",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Orm Stonehoof",
    objectives = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.",
    rewards = "1,200 XP",
    tip = "I will make you the helm, but you must show me you are worthy of it.\n\nNestled in the northwestern reaches of the Stonetalon Mountains there lies the Charred Vale.  It was once a verdant place, but is now defiled and ashen, and what creatures remain there are mad with pain and despair.\n\nThat place is where I send you, $N.\n\nYou must go to the Charred Vale and find a chimaera matriarch.  Slay her, free her of her misery.  Bring me her galvanized horn as proof, and I shall make for you the helm.",
    isForever = false,
  },
  [293] = {
    id = 293,
    title = "Cleansing the Eye",
    reqLevel = 22,
    questLevel = 30,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Glorin Steelbrow",
    objectives = "Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.",
    rewards = "2,450 XP",
    tip = "I can't lift the curse from the Eye of Paleth.  The Eyes were crafted by Human Priests, so you'll have to go to Stormwind to find someone who can help you.  Speak with Archbishop Benedictus.  He is head of the Cathedral of Light in Stormwind.  He can help.\n\nI hope, for your sake.",
    isForever = false,
  },
  [2930] = {
    id = 2930,
    title = "Data Rescue",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Master Mechanic Castpipe",
    objectives = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.",
    rewards = "3,650 XP • 25s",
    tip = "When we fled Gnomeregan, we left so much data behind!  Vitally important data!\n\nI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan.  You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C.  And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.\n\nIt's a catastrophe!  Can you ",
    isForever = false,
  },
  [536] = {
    id = 536,
    title = "Down the Coast",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Lieutenant Farren Orinelle",
    objectives = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.",
    rewards = "1,850 XP • 21s",
    tip = "Transferred from the Stormwind city guard to Southshore, a town that should be abandoned by the looks of it... Smell of the harbor day and night.\n\nNot to mention ol' Redpath... Wants me to take care of the murlocs. Ha! \n\nI can barely rouse myself to go out to some of the pockets of the overgrown fish down the Western Strand. If you would go in my place and take care of them, I'd appreciate it.",
    isForever = false,
  },
  [1846] = {
    id = 1846,
    title = "Dragonmaw Shinbones",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Velora Nitely",
    objectives = "Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity.",
    rewards = "1,200 XP",
    tip = "To make the brutal leg guards, I need a brace of sturdy shinbones.  The Dragonmaw orcs of the Wetlands have nice, thick shinbones.  I'll need theirs.\n\nBut they must be sturdy.  Be sure to test the shinbones as you collect them.  If you can break them with your bare hands, then they won't be sturdy enough to work with.",
    isForever = false,
  },
  [515] = {
    id = 515,
    title = "Elixir of Agony",
    reqLevel = 24,
    questLevel = 30,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Master Apothecary Faranell",
    objectives = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.",
    rewards = "3,050 XP",
    tip = "A mudsnout composite?  Absolutely brilliant!  Why didn't I think of that?\n\nLet me contribute my colloid of decay to this devilish brew.\n\nIn order to activate the contaminating agents in this mudsnout mixture, Lydon is going to need a strong troll's blood potion, as well as some daggerspine scales and torn fin eyes from the southern coast of Hillsbrad.  He'll know what to do once you've gathered him all the reagents.  And my, how anxious I am to hear how his experiment goes!",
    isForever = false,
  },
  [517] = {
    id = 517,
    title = "Elixir of Agony",
    reqLevel = 24,
    questLevel = 30,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.",
    rewards = "1,200 XP",
    tip = "This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas.\n\nHead down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, $N.",
    isForever = false,
  },
  [524] = {
    id = 524,
    title = "Elixir of Agony",
    reqLevel = 24,
    questLevel = 30,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Apothecary Lydon",
    objectives = "Place the Tainted Keg on the rug for the captured farmers.",
    rewards = "3,650 XP",
    tip = "Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal.\n\nI think it's time we threw those farmers a party.  Sounds like a grand ol' time!\n\nPlace this tainted keg on the rug in their room.  Plagued brew for ",
    isForever = false,
  },
  [2924] = {
    id = 2924,
    title = "Essential Artificials",
    reqLevel = 24,
    questLevel = 30,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Klockmort Spannerspan",
    objectives = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.",
    rewards = "3,050 XP • 55s",
    tip = "A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan.  But during the frantic exodus from our city, no one remembered to take any of these devices with them!  And I need a large supply of them for work I will soon undertake.\n\nPlease, go into Gnomeregan and get me some essential artificials.  You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.\n\nThank you, $N, and please hurry!",
    isForever = false,
  },
  [1035] = {
    id = 1035,
    title = "Fallen Sky Lake",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Pelturas Whitemoon",
    objectives = "Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.",
    rewards = "3,050 XP",
    tip = "Relara's fever has passed, but she is still very weak.  I do not believe time alone will give her back the strength she has lost.  I believe it will take the power of a moonstone.\n\nWe used to gather moonstones at Fallen Sky Lake to the southeast... until the Shadethickets came.\n\nTheir leader, a Shadethicket Oracle, gathered up all the fallen moonstones and hoards them.  Now, you must retrieve a moonstone from the Oracle.\n\nAnd to do that, I fear that you must slay him.",
    isForever = false,
  },
  [1950] = {
    id = 1950,
    title = "Get the Scoop",
    reqLevel = 30,
    questLevel = 30,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Magus Tirth",
    objectives = "Find the phrase to Tirth's strongbox, then return to Tirth.",
    rewards = "1,850 XP",
    tip = "I can help you with the book, but first you have to help me!\n\nThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.\n\nIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!",
    isForever = false,
  },
  [1706] = {
    id = 1706,
    title = "Grimand's Armor",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Grimand Elmore",
    objectives = "Speak with Grimand Elmore in Warrior Class Quests.",
    rewards = "3,050 XP",
