    isForever = false,
  },
  [2928] = {
    id = 2928,
    title = "Gyrodrillmatic Excavationators",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Shoni the Shilent",
    objectives = "- Robo-mechanical Guts x 24",
    rewards = "2,450 XP",
    tip = "It's terrible, $N. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.\n\nWhat we need are spare parts, $N. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.\n\nWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.",
    isForever = false,
  },
  [1105] = {
    id = 1105,
    title = "Hardened Shells",
    reqLevel = 28,
    questLevel = 30,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Wizzle Brassbolts",
    objectives = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.",
    rewards = "2,450 XP • 25s",
    tip = "My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!\n\nI want to reinforce its fuel tanks before that happens.\n\nThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.\n\nYou look responsible enough.  Will you get me those shells?",
    isForever = false,
  },
  [1135] = {
    id = 1135,
    title = "Highperch Venom",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Fiora Longears",
    objectives = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.",
    rewards = "3,650 XP",
    tip = "As you may know, wyverns are often tamed by orcs for use as mounts.  But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself.  So if you're not afraid to do a little wyvern hunting, then... I have a job for you.\n\nThere is a place called Highperch in the land of a Thousand Needles, west of here.  The Highperch wyverns have a potent venom.  Potent, and valuable.",
    isForever = false,
  },
  [547] = {
    id = 547,
    title = "Humbert's Sword",
    reqLevel = 26,
    questLevel = 30,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Deathguard Humbert",
    objectives = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.",
    rewards = "3,050 XP",
    tip = "High Executor Darthalia sent me to keep watch of Dun Garok from a distance.  I had set up camp just out of sight.  But when morning came and I had to boil water, I left to gather firewood.\n\nWhen I returned to camp, I discovered my gear was missing.\n\nApparently some dwarven scouts from Dun Garok had passed by and made off with it.  I need my sword!  If you can get it back for me I would be so grateful.  So many dwarves there...it will be quite difficult to find the dirty little thief who stole it",
    isForever = false,
  },
  [5151] = {
    id = 5151,
    title = "Hypercapacitor Gizmo",
    reqLevel = 24,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Wizlo Bearingshiner",
    objectives = "- Hypercapacitor Gizmo",
    rewards = "3,050 XP",
    tip = "I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck. Hah! Even the centaur tremble in the presence of this ferocious beast!\n\nHere is the key to the cage. They took everything there, but left him alone. Slay this beast and bring back my hypercapacitor, and I shall reward you.\n\nThe wrecked caravan is just north of here.",
    isForever = false,
  },
  [1709] = {
    id = 1709,
    title = "Klockmort's Creation",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Klockmort Spannerspan",
    objectives = "Speak with Klockmort Spannerspan in Warrior Class Quests.",
    rewards = "3,050 XP",
    tip = "",
    isForever = false,
  },
  [2925] = {
    id = 2925,
    title = "Klockmort's Essentials",
    reqLevel = 24,
    questLevel = 30,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Mathiel",
    objectives = "Speak with Klockmort Spannerspan in Ironforge.",
    rewards = "245 XP",
    tip = "A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.",
    isForever = false,
  },
  [290] = {
    id = 290,
    title = "Lifting the Curse",
    reqLevel = 22,
    questLevel = 30,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "First Mate Fitzsimmons",
    objectives = "Get the Intrepid Strongbox Key from Captain Halyndor.\n\nUse the key to open the Intrepid's Locked Strongbox.",
    rewards = "1,200 XP",
    tip = "To break the curse and free all of my brethren, the...thing...stowed on my ship must be retrieved and cleansed!  I don't know what it was, but I do know that it was stored securely in the ship's strongbox, which Captain Halyndor lorded over.\n\nMy old captain is still in my dreams.  I know he walks my doomed ship, the Intrepid.  Get the key from him, and use it to open the Intrepid's strongbox.\n\nThen, after you have the cursed thing, bring it to the priest Glorin Steelbrow in town.",
    isForever = false,
  },
  [1176] = {
    id = 1176,
    title = "Load Lightening",
    reqLevel = 29,
    questLevel = 30,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Pozzik",
    objectives = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.",
    rewards = "1,850 XP • 25s",
    tip = "When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.\n\nWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.\n\nBring me some and I'll give you a good price on the",
    isForever = false,
  },
  [181] = {
    id = 181,
    title = "Look To The Stars",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Viktori Prism'Antras",
    objectives = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.",
    rewards = "2,450 XP",
    tip = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!",
    isForever = false,
  },
  [647] = {
    id = 647,
    title = "MacKreel's Moonshine",
    reqLevel = 28,
    questLevel = 30,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Foggy MacKreel",
    objectives = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.",
    rewards = "3,050 XP • 55s",
    tip = "Had quite a bit of the ol' Moonshine last night!  Longbraid would have my head if he knew that I passed out during my watch.\n\nThe noggin hurts something fierce.  Felt as though a whole brigade of siege engines passed overhead, all that rumbling.\n\nOh my, look at the time! I promised Brewmeister Bilger in Southshore that I'd repay my debt to him by sending some Moonshine.\n\nBut there are just 15 minutes left before I'm overdue!  Take him this batch, would you please?  And hurry!",
    isForever = false,
  },
