  [1142] = {
    id = 1142,
    title = "Mortality Wanes",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Heralath Fallowbrook",
    objectives = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.",
    rewards = "3,050 XP",
    tip = "I have not long to live... so... so... weak.\n\n...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...\n\nBut before I... d-d-die...\n\n...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...\n\nFind it p-p-please... and return it to Treshala in Darnassus...\n\n...along with w-w-word of my lonely... death.",
    isForever = false,
  },
  [160] = {
    id = 160,
    title = "Note to the Mayor",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Abercrombie",
    objectives = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.",
    rewards = "610 XP",
    tip = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!",
    isForever = false,
  },
  [134] = {
    id = 134,
    title = "Ogre Thieves",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Abercrombie",
    objectives = "Return Abercrombie's Crate to Abercrombie.",
    rewards = "1,200 XP • 14s",
    tip = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, $N, retrieve this crate for me for I miss it sorely.",
    isForever = false,
  },
  [1840] = {
    id = 1840,
    title = "Orm Stonehoof and the Brutal Helm",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Thun'grim Firegaze",
    objectives = "Speak with Orm Stonehoof in Thunder Bluff.",
    rewards = "1,200 XP",
    tip = "Orm Stonehoof is respected greatly for his skill.  He will make for you the brutal helm.\n\nSeek him out in Thunder Bluff, near the pool by the city's great, central totem.",
    isForever = false,
  },
  [1040] = {
    id = 1040,
    title = "Passage to Booty Bay",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Wharfmaster Dizzywig",
    objectives = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.",
    rewards = "610 XP",
    tip = "Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.\n\nVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.\n\nNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.\n\nMove along, now. I haven't all day for yo",
    isForever = false,
  },
  [1045] = {
    id = 1045,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Krolg",
    objectives = "Kill Ran Bloodtooth and 4 Bloodtooth Guards and return to Krolg near Lake Mystral.",
    rewards = "2,450 XP",
    tip = "The night elves are as old as time, but their arrogance destroys their very world. And now it destroys our lives too. But that can no longer be controlled...\n\nI blame the elves for much, but we are still responsible for our actions. Even beyond the corruption, we are capable of great evil.\n\nRan Bloodtooth is one such evil. Power hungry, lusting... the corruption has only made him stronger. My hatred for the elves burns, but I do not wish ill upon their children, so we must police our own.",
    isForever = false,
  },
  [1046] = {
    id = 1046,
    title = "Raene's Cleansing",
    reqLevel = 18,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Krolg",
    objectives = "Bring Ran Bloodtooth's Skull and Dartol's Rod of Transformation to Raene Wolfrunner in Astranaar.",
    rewards = "3,050 XP",
    tip = "Return to your own tribe and let them know of your victory here.\n\nShow them your trophy, and bask in the glory...",
    isForever = false,
  },
  [1104] = {
    id = 1104,
    title = "Salt Flat Venom",
    reqLevel = 28,
    questLevel = 30,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Fizzle Brassbolts",
    objectives = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.",
    rewards = "1,850 XP • 25s",
    tip = "I have so many designs for our rocket car!  So many!  And I must try them all!!\n\nI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...\n\nThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!\n\nBring me venom and trust me -- our car will fly!!",
    isForever = false,
  },
  [683] = {
    id = 683,
    title = "Sara Balloo's Plea",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Sara Balloo",
    objectives = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.",
    rewards = "1,200 XP",
    tip = "$n, I have but a small request to ask of you.\n\nTake this note I have prepared to our great monarch of Ironforge, King Magni Bronzebeard. 'Tis a small task to ask of one such as yourself, someone who has shown great valor to the cause of the Alliance thus far.\n\nFor me to go before the King in my grief-ridden state would not serve the purpose of my cause.  Surely you understand.",
    isForever = false,
  },
  [1842] = {
    id = 1842,
    title = "Satyr Hooves",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Ula'elek",
    objectives = "Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar",
    rewards = "1,200 XP",
    tip = "I can make you a pair of brutal gauntlets, and great magic will they hold.  But first, you must collect this magic and bring it to me.\n\nThe satyrs dwell in northeastern Ashenvale because of the forest's power.  They feed off its purity, leeching and corrupting.  You can tell which satyrs have drawn the most of Ashenvale's magic by their swollen, uncloven hooves.\n\nThese hooves hold great power.  I will need them for your gauntlets' crafting.",
    isForever = false,
  },
  [1798] = {
    id = 1798,
    title = "Seeking Strahad",
    reqLevel = 30,
    questLevel = 30,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Gakin the Darkbinder",
    objectives = "Speak with Strahad Farsan in the Barrens.",
    rewards = "610 XP",
    tip = "It is time you learned the felhunter summoning, $n. I do not have the reagents and items necessary to teach you here, so you will have to seek out another, Strahad Farsan, another of our inner circle.\n\nHe makes his residence in the goblin port of Ratchet. I will send word ahead of you to inform him of your coming.",
    isForever = false,
  },
  [2996] = {
    id = 2996,
    title = "Seeking Strahad",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Gan'rul Bloodeye",
    objectives = "Speak to Strahad Farsan in Ratchet.",
    rewards = "610 XP",
    tip = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.",
    isForever = false,
  },
  [3001] = {
    id = 3001,
    title = "Seeking Strahad",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Carendin Halgar",
    objectives = "Find Strahad Farsan in Ratchet.",
    rewards = "610 XP",
    tip = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.\n\nYou can find him in Ratchet... above the port town next to the tower there.",
    isForever = false,
  },
  [2] = {
    id = 2,
    title = "Sharptalon's Claw",
    reqLevel = 20,
    questLevel = 30,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "NULL",
    objectives = "Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.",
    rewards = "2,450 XP",
    tip = "Pro-tip: Bring an Extra Dimensional Ghost Revealer. Essential for unlocking the upgraded 8-piece dungeon tier sets.",
    isForever = false,
  },
  [1131] = {
    id = 1131,
    title = "Steelsnap",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Melor Stonehoof",
    objectives = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.",
    rewards = "2,450 XP",
    tip = "At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings.\n\nBut the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing.\n\nThe hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts.\n\nFind Steelsnap, $N.  Find him, and defeat him.",
    isForever = false,
  },
  [637] = {
    id = 637,
    title = "Sully Balloo's Letter",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Item: Waterlogged Envelope",
    objectives = "Deliver Sully Balloo's Letter to Sara Balloo.",
    rewards = "2,450 XP",
    tip = "The waterlogged and war-torn envelope dissolves in your hands, leaving you with a few pages of a letter in your grasp, written with painstaking care.\n\nThe letter is addressed to a Mrs. Sara Balloo of Ironforge and begins, \"My dear Sara....\"",
    isForever = false,
  },
  [1710] = {
    id = 1710,
    title = "Sunscorched Shells",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Warrior Class Quests",
    npc = "Mathiel",
    objectives = "Bring 20 Sunscorched Shells to Mathiel in Darnassus.",
    rewards = "1,850 XP",
    tip = "My colleague, Furen Longbeard, made a discovery which I am eager to test.  I wish to try it on a new armor that I am researching, for I believe Furen's techniques will produce superior results.\n\nWill you help me?  If you gather what I need to make the armor, then I will make an extra piece for you.\n\nI need the sunscorched egg shells of the Highperch Wyverns who dwell at Highperch, in Thousand Needles.  Search for the shells below their nests, and return to me when you have a sufficient amount.",
    isForever = false,
  },
  [1150] = {
    id = 1150,
    title = "Test of Endurance",
    reqLevel = 25,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Dorn Plainstalker",
    objectives = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.",
    rewards = "2,450 XP",
    tip = "I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.\n\nFirst is a test of endurance. Go to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.",
    isForever = false,
  },
  [1152] = {
    id = 1152,
    title = "Test of Lore",
    reqLevel = 25,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Dorn Plainstalker",
    objectives = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
    rewards = "1,200 XP",
    tip = "Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\n\nIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, $N.\n\nWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, $N, the night elves may wish to impede your te",
    isForever = false,
  },
  [1154] = {
    id = 1154,
    title = "Test of Lore",
    reqLevel = 25,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Braug Dimspirit",
    objectives = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
    rewards = "1,850 XP",
    tip = "You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.\n\nI shall explain it simply: find the book I name, study it, and answer my question about its contents.\n\nWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.",
    isForever = false,
  },
  [1159] = {
    id = 1159,
    title = "Test of Lore",
    reqLevel = 25,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Braug Dimspirit",
    objectives = "Find Parqual Fintallas in Undercity.",
    rewards = "1,200 XP",
    tip = "Well done, $N. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.\n\nSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.\n\nHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.",
    isForever = false,
  },
  [6627] = {
    id = 6627,
    title = "Test of Lore",
    reqLevel = 25,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Braug Dimspirit",
    objectives = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.",
    rewards = "245 XP",
    tip = "You have brought me the book, and now it is time for your question. Are you ready?\n\nTime is not an issue, $c, so do not feel pressured. You may take as long as you like to answer.",
    isForever = false,
  },
  [6628] = {
    id = 6628,
    title = "Test of Lore",
    reqLevel = 25,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Parqual Fintallas",
    objectives = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.",
    rewards = "245 XP",
    tip = "So the time is once again upon us. As a student of lore, you have shown great tenacity by undertaking my task.\n\nAnd so now I offer you your question. If you are ready, speak to me again, and take all the time you need, $N--there is no pressure to answer quickly.",
    isForever = false,
  },
  [1151] = {
    id = 1151,
    title = "Test of Strength",
    reqLevel = 25,
    questLevel = 30,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Dorn Plainstalker",
    objectives = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.",
    rewards = "3,050 XP",
    tip = "During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.\n\nThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.\n\nTo test your strength, find Rok'Alim in Thousand Needles and slay hi",
    isForever = false,
  },
  [1719] = {
    id = 1719,
    title = "The Affray",
    reqLevel = 30,
    questLevel = 30,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Klannoc Macleod",
    objectives = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.",
    rewards = "2,450 XP",
    tip = "If you want to learn from me, then you must first pass The Affray.  It is a challenge we on Fray Island like to offer rising warriors who think they're tough, and if you can pass this test then I'll know you are.\n\nTo begin, walk into the middle of that crowd yonder and step on the grate.  That'll tell Twiggy Flathead you're ready, and he'll send challengers against you.\n\nBeat all the challengers and he'll call out Big Will.  Kill Big Will, and return to me in the time we allow.",
    isForever = false,
  },
  [1039] = {
    id = 1039,
    title = "The Barrens Port",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Thyn'tel Bladeweaver",
    objectives = "Speak with Wharfmaster Dizzywig in Ratchet.",
    rewards = "1,200 XP",
    tip = "Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers.\n\nFollow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, $n, warriors of the Horde patrol the land. You will be safe at the port, though.",
    isForever = false,
  },
  [1795] = {
    id = 1795,
    title = "The Binding",
    reqLevel = 30,
    questLevel = 30,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Strahad Farsan",
    objectives = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.",
    rewards = "2,450 XP",
    tip = "If you are sufficiently prepared, then we should begin. Let me explain the process to you.\n\nI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.\n\nOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, $n. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders.",
    isForever = false,
  },
  [1179] = {
    id = 1179,
    title = "The Brassbolts Brothers",
    reqLevel = 28,
    questLevel = 30,
    faction = "Alliance",
    zone = "Thousand Needles",
    npc = "Pilot Longbeard",
    objectives = "Bring the crate of crash helmets to Wizzle Brassbolts in the Shimmering Flats.",
    rewards = "2,450 XP",
    tip = "You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat!\n\nA couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions.\n\nSo they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip!\n\nCan",
    isForever = false,
  },
  [1041] = {
    id = 1041,
    title = "The Caravan Road",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Caravaneer Ruzzgot",
    objectives = "Speak with Clerk Daltry in Darkshire.",
    rewards = "1,200 XP",
    tip = "Turns out I was wrong about you, and that isn't something that happens everyday.\n\nIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.\n\nWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.\n\nBe careful in the jungle, it is a deadly place even at the best of times.",
    isForever = false,
  },
  [1042] = {
    id = 1042,
    title = "The Carevin Family",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Clerk Daltry",
    objectives = "Speak with Jonathan Carevin in Darkshire.",
    rewards = "245 XP",
    tip = "No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning?\n\nThese wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household.",
    isForever = false,
  },
  [303] = {
    id = 303,
    title = "The Dark Iron War",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Motley Garmason",
    objectives = "Motley Garmason at Dun Modr wants you to kill 15 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.",
    rewards = "2,450 XP • 25s",
    tip = "War rages both home and abroad.  While mighty Dwarven soldiers give their lives in far off territories in the name of the Alliance, our own lands fall prey to the evil deeds of the Dark Iron Dwarves.  They laid waste to the Thandol Span.  Dun Modr fell soon after.\n\nWe need you to gather force and push the front back.  If you can kill 10 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs and 5 Demolitionists, the reserve might arrive in time to finish the drive.\n\nNow make haste!",
    isForever = false,
  },
  [292] = {
    id = 292,
    title = "The Eye of Paleth",
    reqLevel = 22,
    questLevel = 30,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Object: Intrepid's Locked Strongbox",
    objectives = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.",
    rewards = "1,200 XP",
    tip = "Opening the chest reveals a blackened orb, pulsing with an eerie light.  It is the treasure of which Fitzsimmons spoke: a Cursed Eye of Paleth.\n\nTake the Cursed Eye of Paleth to the dwarven priest Glorin Steelbrow, in Menethil Harbor.  Ask him how to remove the Eye's curse.",
    isForever = false,
  },
  [1022] = {
    id = 1022,
    title = "The Howling Vale",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Sentinel Melyria Frostshadow",
    objectives = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at the Shrine of Aessina.",
    rewards = "2,450 XP • 25s",
    tip = "Though we have put many resources and much effort into driving the remaining demons from the Felwood to the north, our successes have been few. We have been able to keep much of the demonic presence from Ashenvale.\n\nTo the north, near the Felwood border, the ruined shrine of Mel'Thandris has been overtaken by mysterious wolf-men. Their chilling calls have led the area to be known as the Howling Vale. The Tome of Mel'Thandris kept at the shrine may shed some light on why these wolf-men have come.",
    isForever = false,
  },
  [247] = {
    id = 247,
    title = "The Hunt Completed",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Senani Thunderheart",
    objectives = "Speak with Senani Thunderheart in Ashenvale.",
    rewards = "3,050 XP",
    tip = "",
    isForever = false,
  },
  [1718] = {
    id = 1718,
    title = "The Islander",
    reqLevel = 30,
    questLevel = 30,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Torm Ragetotem",
    objectives = "Speak with Klannoc Macleod.",
    rewards = "610 XP",
    tip = "Your renown as a warrior grows, $N.  Now it is time to pit yourself against your peers and see where you stand.\n\nThere is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet.\n\nMeet, and fight.\n\nSpeak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path.\n\nTo reach Fray Island, search for the sand bar shallows along the Merchant Coast.",
    isForever = false,
  },
  [6504] = {
    id = 6504,
    title = "The Lost Pages",
    reqLevel = 23,
    questLevel = 30,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Gurda Ragescar",
    objectives = "- Shredder Operating Manual - Chapter 1 - Shredder Operating Manual - Chapter 2 - Shredder Operating Manual - Chapter 3",
    rewards = "3,650 XP",
    tip = "I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty. I was given a manual on how to operate the shredder, but on the trip back, a huge gust of wind blew it from my hands. The pages went everywhere, and all I was left with was the cover.\n\nThe pages could be just about anywhere by now, I suppose... but I don't know how to use the shredder without them! Will you find them for me?",
    isForever = false,
  },
  [1244] = {
    id = 1244,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 30,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Watcher Backus",
    objectives = "Find the Defias Docket and return it to Watcher Backus in Duskwood.",
    rewards = "2,450 XP",
    tip = "Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat.\n\nBut now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down.\n\nWhy don't you check there first and bring me back anything you find?\n\nThe farmstead is south of the road from Westfall just as you enter Duskwood.",
    isForever = false,
  },
  [1245] = {
    id = 1245,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 30,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Watcher Backus",
    objectives = "Bring the Defias Docket to Elling Trias in Stormwind.",
    rewards = "245 XP",
    tip = "Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see.\n\nAnd do me a favor, $N, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me.",
    isForever = false,
  },
  [58] = {
    id = 58,
    title = "The Night Watch",
    reqLevel = 18,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Commander Althea Ebonlocke",
    objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.",
    rewards = "2,450 XP • 25s",
    tip = "The situation in Raven Hill is still grim.  The safety of Darkshire is in your hands, $N.  I don't have enough Watchers to keep the town safe.  We need you to dispatch for Raven Hill yet again and rid the eastern mausoleum of 20 Plague Spreaders!",
    isForever = false,
  },
  [2962] = {
    id = 2962,
    title = "The Only Cure is More Green Glow",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Ozzie Togglevolt",
    objectives = "- High Potency Radioactive Fallout",
    rewards = "2,450 XP, 25s",
    tip = "Not only was your sample insufficient in quantity, it was also impure.\n\nWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered",
    isForever = false,
  },
  [1043] = {
    id = 1043,
    title = "The Scythe of Elune",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Jonathan Carevin",
    objectives = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.",
    rewards = "2,450 XP • 25s",
    tip = "Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results.\n\nThere is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found.\n\nGo about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war agains",
    isForever = false,
  },
  [2951] = {
    id = 2951,
    title = "The Sparklematic 5200!",
    reqLevel = 25,
    questLevel = 30,
    faction = "Both",
    zone = "Azeroth",
    npc = "Object: The Sparklematic 5200",
    objectives = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
    rewards = "Experience & Faction Reputation",
    tip = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"",
    isForever = false,
  },
