  [857] = {
    id = 857,
    title = "The Tear of the Moons",
    reqLevel = 22,
    questLevel = 30,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Feegly the Exiled",
    objectives = "Feegly the Exiled wants you to retrieve for him the Tear of the Moons.",
    rewards = "2,450 XP • 25s",
    tip = "The power was mine! In my very hands! And I want it back! Back I say!\n\nThose dirty excavators uncovered it... so beautiful it was. Deemed the Tear of the Moons, it was the first great discovery we made at Bael Modan.\n\nIt should have been mine! Mine I say!\n\nGeneral Twinbraid grew jealous of the power it gave me. He locked it away in the Keep. Called it cursed, he did! The fool!\n\nOthers wanted it and they had to be stopped! That bastard Twinbraid drove me off.\n\nNow I want it back. Back I say!",
    isForever = false,
  },
  [1791] = {
    id = 1791,
    title = "The Windwatcher",
    reqLevel = 30,
    questLevel = 30,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Klannoc Macleod",
    objectives = "Speak with Bath'rah the Windwatcher.",
    rewards = "245 XP",
    tip = "Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.\n\nTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands.  He is a skilled weapon maker and a powerful shaman.\n\nTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank.  Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank.",
    isForever = false,
  },
  [1758] = {
    id = 1758,
    title = "Tome of the Cabal",
    reqLevel = 30,
    questLevel = 30,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Strahad Farsan",
    objectives = "Speak with Krom Stoutarm in Ironforge.",
    rewards = "610 XP",
    tip = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge.",
    isForever = false,
  },
  [1801] = {
    id = 1801,
    title = "Tome of the Cabal",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Strahad Farsan",
    objectives = "Speak with Jorah Annison in the Undercity.",
    rewards = "610 XP",
    tip = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know.",
    isForever = false,
  },
  [1802] = {
    id = 1802,
    title = "Tome of the Cabal",
    reqLevel = 30,
    questLevel = 30,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Krom Stoutarm",
    objectives = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.",
    rewards = "2,450 XP",
    tip = "It was lost, but there's some idea as to where it might be found.\n\nThere was only one copy ever made and it was vandalized at some point, a large portion of it ripped from the binding. Rumor has it that it somehow passed into the hands of the centaur of Thousand Needles.\n\nThe rest was lost off the coast west of Southshore, where it was to be transported to Menethil Harbor by boat. It never arrived.\n\nIn exchange for this knowledge, all I ask is that if you find it, bring it to me to see.",
    isForever = false,
  },
  [1803] = {
    id = 1803,
    title = "Tome of the Cabal",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Jorah Annison",
    objectives = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.",
    rewards = "610 XP",
    tip = "Ah! I see that you are a warlock of similar tastes to mine. Indeed, acquiring the Tome of the Cabal is a worthy aspiration. Did you know that it was once held within the walls of Lordaeron? It was vandalized though, almost half its pages removed. Who would commit such a heinous act?\n\nThat half is lost, though rumor says that it fell into the hands of the centaur of the Thousand Needles.\n\nThe rest of the text was to be transferred to Ironforge, but was lost in transit on the coast west of Southsh",
    isForever = false,
  },
  [1804] = {
    id = 1804,
    title = "Tome of the Cabal",
    reqLevel = 30,
    questLevel = 30,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Krom Stoutarm",
    objectives = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
    rewards = "2,450 XP",
    tip = "Well, ah, it's hard to let it go. But you found it, and you have more important things to do with it, of course. Just, please, be sure to mention to Strahad that I wanted a copy.\n\nWhile you were out, he sent a message for you. He wanted me to tell you that for his acolytes to assist with the summoning, you'll have to acquire three rods of channeling.\n\nHe might not know where to find them, but I do! They were last used by the orcs of the Dragonmaw clan in the Wetlands. I'd check their spellcaster",
    isForever = false,
  },
  [1805] = {
    id = 1805,
    title = "Tome of the Cabal",
    reqLevel = 30,
    questLevel = 30,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Jorah Annison",
    objectives = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
    rewards = "2,450 XP",
    tip = "This is one of the most interesting texts I have perused in the last few years. The selection here is sparse--mostly books on geography--and I have already read them all. I should hope that Strahad would send me a copy of this tome when he has the chance.\n\nSpeaking of him, he sent word to me while you were away. For your task, you must obtain three rods of channeling.\n\nFor allowing me to look at this text, I will share a secret: You can find the rods on orcs of the Dragonmaw Clan in the Wetlands",
    isForever = false,
  },
  [251] = {
    id = 251,
    title = "Translate Abercrombie's Note",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Lord Ello Ebonlocke",
    objectives = "Bring the Letter to Ello to Sirra Von'Indi.",
    rewards = "245 XP",
    tip = "Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he.",
    isForever = false,
  },
  [252] = {
    id = 252,
    title = "Translation to Ello",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sirra Von'Indi",
    objectives = "Bring the Translated Letter to Lord Ello Ebonlocke",
    rewards = "245 XP",
    tip = "Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable.\n\nYou better bring the translated note back to Ello.\n\nAnd do so quickly, for I fear a doom already lumbers toward our town...",
    isForever = false,
  },
  [1839] = {
    id = 1839,
    title = "Ula'elek and the Brutal Gauntlets",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Thun'grim Firegaze",
    objectives = "Speak with Ula'elek in Durotar.",
    rewards = "1,200 XP",
    tip = "The troll smith Ula'elek will craft for you the brutal gauntlets.  He dwells in Durotar, in Sen'jin Village with his Darkspear brethren, and he awaits your coming.",
    isForever = false,
  },
  [1037] = {
    id = 1037,
    title = "Velinde Starsong",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Sentinel Melyria Frostshadow",
    objectives = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.",
    rewards = "610 XP",
    tip = "Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared.\n\nI was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to.\n\nSurely she will understand the import of such information.",
    isForever = false,
  },
  [1038] = {
    id = 1038,
    title = "Velinde's Effects",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Thyn'tel Bladeweaver",
    objectives = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.",
    rewards = "610 XP",
    tip = "The Tome of Mel'Thandris showed you this? I suppose there would be little harm in allowing you to examine her belongings. This key will allow you to open the chest where we stored her things in the Sentinels' bunkhouse. She kept a journal of her duties, if there is anything to be learned, it will be from that.\n\nI should tell you, the Sentinels believe that she had her own reasons for leaving, and expect that she could return at any time. The priestess has done much in the past to earn our trust.",
    isForever = false,
  },
  [1841] = {
    id = 1841,
    title = "Velora Nitely and the Brutal Legguards",
    reqLevel = 20,
    questLevel = 30,
    faction = "Horde",
    zone = "Warrior Class Quests",
    npc = "Thun'grim Firegaze",
    objectives = "Speak with Velora Nitely in the Undercity.",
    rewards = "1,200 XP",
    tip = "It is said that, before her death, Velora Nitely was one of the finest armorsmiths in Lordaeron.  Death, it seems, has not decreased her talents.  Speak with Velora--she will make your brutal legguards.\n\nVelora plies her trade in the Undercity of Lordaeron, in the trade quarter.",
    isForever = false,
  },
  [401] = {
    id = 401,
    title = "Wait for Sirra to Finish",
    reqLevel = 20,
    questLevel = 30,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sirra Von'Indi",
    objectives = "Wait a moment, then speak with Sirra Von'Indi again.",
    rewards = "1,850 XP",
    tip = "I'm almost finished translating that note.  If you come back in a few moments I should be done.",
    isForever = false,
  },
  [583] = {
    id = 583,
    title = "Welcome to the Jungle",
    reqLevel = 28,
    questLevel = 30,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Barnil Stonepot",
    objectives = "Speak with Hemet Nesingwary.",
    rewards = "245 XP",
    tip = "Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  He's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, $c.\n\nBeing a veteran of many battles himself, Master Nesingwary has a soft spot for fellow heroes.\n\nGo and speak with him.  Perhaps he can give you some hunting pointers.",
    isForever = false,
  },
  [1144] = {
    id = 1144,
    title = "Willix the Importer",
    reqLevel = 23,
    questLevel = 30,
    faction = "Both",
    zone = "Azeroth",
    npc = "Willix the Importer",
    objectives = "Escort Willix the Importer out of Razorfen Kraul.",
    rewards = "3,050 XP",
    tip = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Blueleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.",
    isForever = false,
  },
  [397] = {
    id = 397,
    title = "You Have Served Us Well",
    reqLevel = 25,
    questLevel = 30,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Zardeth of the Black Claw",
    objectives = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.",
    rewards = "245 XP",
    tip = "I hear Lord Wishock enjoyed his beverage.  \n\nYou have served us well, $N.  The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you.  For your efforts, I have prepared a special gift for you.  Speak with my servant, Zggi, and claim your reward.",
    isForever = false,
  },
  [689] = {
    id = 689,
    title = "A King's Tribute",
    reqLevel = 25,
    questLevel = 31,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Grand Mason Marblesten",
    objectives = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.",
    rewards = "2,500 XP",
    tip = "So our good King would like a memorial built in honor of a soldier named Sully Balloo?  And you say the poor chap died during the Thandol Span tragedy?\n\nBah, will there ever be peace on Azeroth?\n\nNonetheless, any commission from the King is of utmost importance. To build a truly epic and lasting piece I want to work with one of the finest stones available. Travel to Darrow Hill in Hillsbrad and gather for me some Alterac Granite.",
    isForever = false,
  },
  [700] = {
    id = 700,
    title = "A King's Tribute",
    reqLevel = 25,
    questLevel = 31,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Grand Mason Marblesten",
    objectives = "Report to King Magni Bronzebeard.",
    rewards = "2,500 XP",
    tip = "Ah, such fine stone comes from Lordaeron.  Such a shame the land is in such shambles.\n\nBut the Memorial came out quite well! I should think the King will be most pleased with it.\n\nNow if you will, please send word to His Majesty that the Memorial is complete as requested.",
    isForever = false,
  },
  [396] = {
    id = 396,
    title = "An Audience with the King",
    reqLevel = 16,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Baros Alexston",
    objectives = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.",
    rewards = "3,750 XP",
    tip = "I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind.\n\nYour audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.",
    isForever = false,
  },
  [395] = {
    id = 395,
    title = "Brotherhood's End",
    reqLevel = 16,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Master Mathias Shaw",
    objectives = "Speak with Baros Alexston in Stormwind.",
    rewards = "630 XP",
    tip = "Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles.\n\nA bit of advice, $N: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things.\n\nAnd as far as Trias goes, well, speak to no one of him... ever... if you can help it.",
    isForever = false,
  },
  [1366] = {
    id = 1366,
    title = "Centaur Bounty",
    reqLevel = 30,
    questLevel = 31,
    faction = "Horde",
    zone = "Desolace",
    npc = "Felgur Twocuts",
    objectives = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.",
    rewards = "3,150 XP",
    tip = "Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.\n\nBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.\n\nGood hunting, $N.",
    isForever = false,
  },
  [1387] = {
    id = 1387,
    title = "Centaur Bounty",
    reqLevel = 30,
    questLevel = 31,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Corporal Melkins",
    objectives = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.",
    rewards = "3,750 XP",
    tip = "Many clans make up the centaur race.  Each has its own leader and agenda, but all the clans have one thing in common.  Cruelty.\n\nIf we are to ever find peace, then the centaurs must be removed.  And so I put you on the task to do just that.\n\nWhile wandering Desolace, hunt centaur and take their ears.  Bring me many, many ears.\n\nDo this in service of the Alliance, $N, and we will be one step closer to war's end.",
    isForever = false,
  },
  [1796] = {
    id = 1796,
    title = "Components for the Enchanted Gold Bloodrobe",
    reqLevel = 31,
    questLevel = 31,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Bring Robes of the Arcana to Menara Voidrender in the Barrens.",
    rewards = "2,500 XP",
    tip = "The first item I will aid you in creating is a robe. You will gather the items for me, and we will put them together. Afterwards, assuming you succeed, you will have the first of many items that will make you more powerful and aid you in your struggles.\n\nTo start, you must have crafted Robes of Arcana. A tailor can make this for you, or perhaps you can purchase one from someone else--I'd be most impressed if you could make it yourself--but regardless, bring me the robes, and we shall go from the",
    isForever = false,
  },
  [5762] = {
    id = 5762,
    title = "Hemet Nesingwary",
    reqLevel = 28,
    questLevel = 31,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Take Kravel's Crate to Hemet Nesingwary in Stranglethorn.",
    rewards = "1,250 XP • 30s",
    tip = "I have a package for an old customer of mine, a dwarf named Hemet Nesingwary.  The package took weeks to arrive, and Hemet's long gone by now.  He said he was going to Stranglethorn to hunt the beasts there, but he left me some money to send his delivery when I could.  \n\nHemet's a rich dwarf and it's a good idea to keep up relations with the rich ones, yeah?  So... you want to deliver the package for me?\n\nI heard Hemet has a camp in Stranglethorn, north of Grom'gol.",
    isForever = false,
  },
  [5763] = {
    id = 5763,
    title = "Hunting in Stranglethorn",
    reqLevel = 28,
    questLevel = 31,
    faction = "Horde",
    zone = "Desolace",
    npc = "Roon Wildmane",
    objectives = "Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn.",
    rewards = "1,250 XP",
    tip = "Long ago, a dwarf came to this land.  His name was Hemet and he wished to hunt great beasts.  His skills with the rifle were uncanny, and we spent many days hunting together.  Even the enmity between our peoples was forgotten.\n\nWhen he left Desolace for Stranglethorn, I vowed to one day welcome him back so that we may hunt again.  Now is that time.\n\nTake this kodo horn as a gift to Hemet.  He will know it is from me.  You will find him in Stranglethorn, north of the Grom'gol Base camp.",
    isForever = false,
  },
  [4736] = {
    id = 4736,
    title = "In Search of Menara Voidrender",
    reqLevel = 31,
    questLevel = 31,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Briarthorn",
    objectives = "Speak to Menara Voidrender in the Barrens.",
    rewards = "630 XP",
    tip = "Ah, hello, $N. You're progressing well in your training. So well in fact that I think you should be rewarded for your hard work--and for not becoming corrupted by the arcane yet.\n\nIf you're interested, seek out Menara Voidrender in Ratchet. She is currently staying at Strahad Farsan's tower overlooking the town.\n\nShe's not very friendly, $N, so don't expect any praise. But if you work hard, she'll make sure you're taken care of.",
    isForever = false,
  },
  [4737] = {
    id = 4737,
    title = "In Search of Menara Voidrender",
    reqLevel = 31,
    questLevel = 31,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Zevrost",
    objectives = "Speak to Menara Voidrender in the Barrens.",
    rewards = "630 XP",
    tip = "Hmph, still you strive to become more powerful. I say it's only time before the corruption and addiction takes hold of you and you become a slave to that which you seek to gain power over.\n\nPfah! A fool you are! Time will prove me right--nothing else... just time.\n\nBut it seems that not all agree with Zevrost. It seems Menara would create tools for you to become more powerful and to harness your strength. If you're interested, then go to Ratchet in the Barrens. She is there overlooking the town.",
    isForever = false,
  },
  [4738] = {
    id = 4738,
    title = "In Search of Menara Voidrender",
    reqLevel = 31,
    questLevel = 31,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Demisette Cloyce",
    objectives = "Speak with Menara Voidrender in the Barrens.",
    rewards = "630 XP",
    tip = "Let us be clear about one thing, $N: I don't feel you are ready for such responsibilities. I don't think aiding in the creation of any item of power is something a novice should ever be involved in; especially one so untested.\n\nBut that's not my decision. The powers that be, or at least the ones that do wish to impart such gifts upon you get to decide that.\n\nIf you're interested in learning more, I suggest you seek out Menara Voidrender in Ratchet. She usually resides in the tower above the port",
    isForever = false,
  },
  [4739] = {
    id = 4739,
    title = "In Search of Menara Voidrender",
    reqLevel = 31,
    questLevel = 31,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Kaal Soulreaper",
    objectives = "Speak to Menara Voidrender in the Barrens.",
    rewards = "630 XP",
    tip = "$C! Yes, you!\n\nYou don't have all the accoutrements, but it's plain to see you're ready--the air around you exudes greater confidence. Yes, I see it now.\n\nMenara Voidrender would teach you a few things if you feel you're ready. She spends her time tutoring younger students in the arcane. She even gives gifts to those who pass her tests.\n\nGo to Ratchet in the Barrens if you're interested. She's above the city in Strahad's tower.",
    isForever = false,
  },
  [2745] = {
    id = 2745,
    title = "Infiltrating the Castle",
    reqLevel = 16,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Elling Trias",
    objectives = "Speak to Tyrion in Stormwind Castle.",
    rewards = "250 XP",
    tip = "Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.\n\nLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?\n\nYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this.",
    isForever = false,
  },
  [2746] = {
    id = 2746,
    title = "Items of Some Consequence",
    reqLevel = 16,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Tyrion",
    objectives = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.",
    rewards = "630 XP",
    tip = "Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get $g his:her; hands dirty, understand? Good.\n\nOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.\n\nBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples.",
    isForever = false,
  },
  [350] = {
    id = 350,
    title = "Look to an Old Friend",
    reqLevel = 16,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Master Mathias Shaw",
    objectives = "Speak to Elling Trias in Stormwind.",
    rewards = "250 XP",
    tip = "That Marzon would be contacting a member of the Defias and have ties to Lescovar...\n\nHaving killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law.\n\nYou'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city.",
    isForever = false,
  },
  [465] = {
    id = 465,
    title = "Nek'rosh's Gambit",
    reqLevel = 23,
    questLevel = 31,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Captain Stoutfist",
    objectives = "Destroy the Dragonmaw catapults.",
    rewards = "1,900 XP",
    tip = "While you were fighting the Dragonmaws, we discovered more of their plans.\n\nNek'rosh has built catapults and aims to lay siege to Menethil!  And with the fighting in Dun Algaz, we're effectively blocked from reinforcements!\n\nYou need to take out those catapults.  They're in the Dragonmaw encampment.\n\nHere, take this tinder.  Fight your way to the catapults and light them with the tinder.\n\nAnd after you've done that, find and kill Nek'rosh.  We need to cut this Dragonmaw beast down...at its neck.",
    isForever = false,
  },
  [681] = {
    id = 681,
    title = "Northfold Manor",
    reqLevel = 30,
    questLevel = 31,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Captain Nials",
    objectives = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.\n\nReturn to Captain Nials at Refuge Pointe.",
    rewards = "2,500 XP",
    tip = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nWe need help from the town of Southshore, but supplies are difficult to receive while the Syndicate holds territory between us.\n\nGo to the Syndicate base in Northfold Manor and slay them.  Then, perhaps, pressure on our supply trains will lessen and more will get thro",
    isForever = false,
  },
  [190] = {
    id = 190,
    title = "Panther Mastery",
    reqLevel = 28,
    questLevel = 31,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Sir S. J. Erlgadin",
    objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.",
    rewards = "1,250 XP",
    tip = "If you want to be a part of the hunt with this crack group under Hemet's leadership, you're going to need to prove yourself an able panther hunter.  We'll start you out easy -- don't you worry.  Let's see you kill 10 young panthers to start.\n\nTracking them down is only half the challenge...",
    isForever = false,
  },
  [634] = {
    id = 634,
    title = "Plea To The Alliance",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Rhag Garmason",
    objectives = "Seek out Captain Nials at Refuge Pointe.",
    rewards = "1,250 XP",
    tip = "I ask of you one more small favor, $c.  We await the reserves of Ironforge.  However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe.\n\nTravel there and seek out Captain Nials.  Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.",
    isForever = false,
  },
  [1110] = {
    id = 1110,
    title = "Rocket Car Parts",
    reqLevel = 28,
    questLevel = 31,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.",
    rewards = "2,500 XP • 30s",
    tip = "Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way.  If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!\n\nAnd those parts are worth money to the gnomes and goblins.  They're always looking for more contraptions to slap onto their cars.\n\nSo go out and get me parts.  Bring me a heap and I'll pay you well.",
    isForever = false,
  },
  [555] = {
    id = 555,
    title = "Soothing Turtle Bisque",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Chef Jessen",
    objectives = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore.",
    rewards = "2,500 XP • 30s",
    tip = "If there's one thing you'll learn about Southshore it's that we have some of the best cuisine north of Stormwind!\n\nTake my secret recipe for Turtle Bisque, for example. I've known folks to travel from as far as Darkshire just to enjoy a bowl.  Speaking of which, I haven't been able to make any lately.  I used to head up past Dalaran to Lake Lordamere myself to hunt Snapjaws but it's just too dangerous now. If you bring me some Turtle Meat from the Snapjaws up north and Soothing Spices, I'll whip",
    isForever = false,
  },
  [7321] = {
    id = 7321,
    title = "Soothing Turtle Bisque",
    reqLevel = 28,
    questLevel = 31,
    faction = "Horde",
    zone = "Cooking",
    npc = "Christoph Jeffcoat",
    objectives = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill.",
    rewards = "2,500 XP • 30s",
    tip = "Who says that the undead don't know anything about cooking? Take my secret recipe for Turtle Bisque, for example. I've known folks that would come back from the dead just to enjoy a bowl! Heh, heh...\n\nSpeaking of which, I haven't been able to make any lately.  I used to head over to Lake Lordamere myself to hunt snapjaws, the nasty things, but I can't pull myself away from my work here.\n\nIf you bring me some Turtle Meat from the snapjaws and soothing spices, I'll show you how it's done!",
    isForever = false,
  },
  [575] = {
    id = 575,
    title = "Supply and Demand",
    reqLevel = 26,
    questLevel = 31,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Drizzlik",
    objectives = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.",
    rewards = "1,250 XP • 22s",
    tip = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in northern Stranglethorn.",
    isForever = false,
  },
  [434] = {
    id = 434,
    title = "The Attack!",
    reqLevel = 16,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Tyrion",
    objectives = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.",
    rewards = "1,900 XP",
    tip = "After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem.\n\nWhile you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information.\n\nLescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to T",
    isForever = false,
  },
  [394] = {
    id = 394,
    title = "The Head of the Beast",
    reqLevel = 16,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Elling Trias",
    objectives = "Speak to Mathias Shaw in Stormwind.",
    rewards = "250 XP",
    tip = "Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens.\n\nHe'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, $N. The nobles can think they rule the city all they want, but some things remain out of their hands.",
    isForever = false,
  },
  [1246] = {
    id = 1246,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Elling Trias",
    objectives = "Speak to Dashel Stonefist in Stormwind.",
    rewards = "250 XP",
    tip = "Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls.\n\nYou can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willi",
    isForever = false,
  },
  [1247] = {
    id = 1247,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Dashel Stonefist",
    objectives = "Speak to Elling Trias in Stormwind.",
    rewards = "250 XP",
    tip = "So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers.\n\nThe guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan.",
    isForever = false,
  },
  [1447] = {
    id = 1447,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Dashel Stonefist",
    objectives = "Defeat Dashel Stonefist in Stormwind.",
    rewards = "1,250 XP",
    tip = "Yeah, you're obviously not the smartest $c to come into Stormwind, but you're about to be one of the dumbest to never leave.\n\nHave you met me friends?",
    isForever = false,
  },
  [631] = {
    id = 631,
    title = "The Thandol Span",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Rhag Garmason",
    objectives = "Rhag Garmason wants you to locate Ol' Rustlocke.",
    rewards = "2,500 XP",
    tip = "A tremendous explosion roared through the hills.  'Twas horrible, I tell you!\n\nGood soldiers died defending the Thandol Span.  Longbraid says we'll take revenge on the Dark Irons before all is said and done.\n\nWe're in a world of hurt though and I don't see any reinforcements in sight.  Longbraid sent Ol' Rustlocke to scout the eastern bridge to see if we could secure it.\n\nThat was days ago.  We haven't the manpower to search for him with Dun Modr under siege.\n\nPerhaps you can find him...",
    isForever = false,
  },
  [632] = {
    id = 632,
    title = "The Thandol Span",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Object: Ebenezer Rustlocke's Corpse",
    objectives = "Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse.",
    rewards = "2,500 XP",
    tip = "It seems as though poor Ol' Rustlocke ran into a Dark Iron ambush.  You notice a parchment next to his clenched fist.\n\nReport the grim news to Rhag Garmason and show him what you found.",
    isForever = false,
  },
  [633] = {
    id = 633,
    title = "The Thandol Span",
    reqLevel = 28,
    questLevel = 31,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Rhag Garmason",
    objectives = "Destroy the cache of explosives.",
    rewards = "2,500 XP",
    tip = "Heavens no!  Poor Rustlocke.  'Tis quite a tragedy indeed.\n\nWe must not let his death pass in vain.  This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands.\n\nIf those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, $n!  Return to me when your mission is complete.\n\nYou're our only hope.",
    isForever = false,
  },
  [981] = {
    id = 981,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 31,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Balthule Shadowstrike",
    objectives = "Talk to Delgren the Purifier at Maestra's Post.",
    rewards = "2,500 XP",
    tip = "For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered.",
    isForever = false,
  },
  [1143] = {
    id = 1143,
    title = "The Tower of Althalaxx",
    reqLevel = 13,
    questLevel = 31,
    faction = "Alliance",
    zone = "Darkshore",
    npc = "Balthule Shadowstrike",
    objectives = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.",
    rewards = "2,500 XP",
    tip = "I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before.",
    isForever = false,
  },
  [185] = {
    id = 185,
    title = "Tiger Mastery",
    reqLevel = 28,
    questLevel = 31,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Ajeck Rouack",
    objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.",
    rewards = "1,250 XP",
    tip = "When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  For this reason, we'll start you out easy.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down.",
    isForever = false,
  },
  [222] = {
    id = 222,
    title = "Worgen in the Woods",
    reqLevel = 23,
    questLevel = 31,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Calor",
    objectives = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.",
    rewards = "1,900 XP • 22s",
    tip = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...",
    isForever = false,
  },
  [223] = {
    id = 223,
    title = "Worgen in the Woods",
    reqLevel = 23,
    questLevel = 31,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Calor",
    objectives = "Bring Calor's note to Jonathan Carevin.",
    rewards = "3,150 XP",
    tip = "Here you go, $n. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.",
    isForever = false,
  },
  [1386] = {
    id = 1386,
    title = "Assault on the Kolkar",
    reqLevel = 30,
    questLevel = 32,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Warug",
    objectives = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.",
    rewards = "2,550 XP",
    tip = "The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!",
    isForever = false,
  },
  [2751] = {
    id = 2751,
    title = "Barbaric Battlements",
    reqLevel = 32,
    questLevel = 32,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Orokk Omosh",
    objectives = "- Patterned Bronze Bracers x 2 - Bronze Greatsword x 2 - Sharp Claw x 2",
    rewards = "2,550 XP",
    tip = "Twenty generations of Omosh have held this hammer, $N. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.\n\nI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!\n\nProve to Orokk you are capable, $N. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.",
    isForever = false,
  },
  [550] = {
    id = 550,
    title = "Battle of Hillsbrad",
    reqLevel = 19,
    questLevel = 32,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "High Executor Darthalia",
    objectives = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.",
    rewards = "2,550 XP",
    tip = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Varimathras in the Undercity.  Go with pride, $c.",
    isForever = false,
  },
  [677] = {
    id = 677,
    title = "Call to Arms",
    reqLevel = 30,
    questLevel = 32,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Drum Fel",
    objectives = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.",
    rewards = "2,550 XP",
    tip = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with",
    isForever = false,
  },
  [474] = {
    id = 474,
    title = "Defeat Nek'rosh",
    reqLevel = 23,
    questLevel = 32,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Object: Dragonmaw Catapult",
    objectives = "Kill Chieftain Nek'rosh\n\nBring Nek'rosh's Head to Captain Stoutfist.",
    rewards = "2,550 XP",
    tip = "Now that the catapults have been burned, find and kill Chieftain Nek'rosh.",
    isForever = false,
  },
  [559] = {
    id = 559,
    title = "Farren's Proof",
    reqLevel = 25,
    questLevel = 32,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Lieutenant Farren Orinelle",
    objectives = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.",
    rewards = "2,550 XP • 30s",
    tip = "Would you believe it, $n? Redpath wasn't satisfied with all the murlocs we killed--oh now, don't be modest, you had some hand in it. Now he wants me to bring proof of the dead, hacking off cold, slimy murloc heads to submit for his approval.",
    isForever = false,
  },
  [560] = {
    id = 560,
    title = "Farren's Proof",
    reqLevel = 25,
    questLevel = 32,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Lieutenant Farren Orinelle",
    objectives = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.",
    rewards = "255 XP",
    tip = "You know, $n, I'd really rather not take these heads... Since you've already got a handle on them, would you mind delivering them to Redpath for me?",
    isForever = false,
  },
  [561] = {
    id = 561,
    title = "Farren's Proof",
    reqLevel = 25,
    questLevel = 32,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Marshal Redpath",
    objectives = "Speak with Lieutenant Farren Orinelle in Southshore.",
    rewards = "255 XP",
    tip = "Please inform Lieutenant Orinelle that I would like him to refocus his efforts on the naga infesting the Eastern Strand. When he has results, tell him to report to me in person.",
    isForever = false,
  },
  [1012] = {
    id = 1012,
    title = "Insane Druids",
    reqLevel = 24,
    questLevel = 32,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Kayneth Stillwind",
    objectives = "Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.",
    rewards = "3,200 XP",
    tip = "When I struggled with the Forsaken's poisons, I had a vision.  I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!  They are now errant ghosts, severed from their bodies and driven mad.\n\nSo that the druids' spirits might some day find peace, you must enter the Dor'danil Barrow Den and destroy its once great leaders: Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak.\n\nDo this, then return to me.",
    isForever = false,
  },
  [201] = {
    id = 201,
    title = "Investigate the Camp",
    reqLevel = 28,
    questLevel = 32,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Krazek",
    objectives = "Find the hunters' camp and report its location to Krazek in Booty Bay.",
    rewards = "255 XP • 16s",
    tip = "I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti.  Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary was one of the hunters there.  He's certainly well-connected, if you catch my meaning, and you never can be too safe.\n\nWhy don't you go check out the camp, $n, see what they're about?",
    isForever = false,
  },
  [690] = {
    id = 690,
    title = "Malin's Request",
    reqLevel = 30,
    questLevel = 32,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Archmage Malin",
    objectives = "Find Skuerto at Refuge Pointe in the Arathi Highlands.",
    rewards = "1,950 XP",
    tip = "Greetings, $N. You have the look of an adventurer about you, and I have a task that needs some tending to.\n\nArchmage Trelane, my original master, fled Stromgarde in the Arathi Highlands not too long ago, and he's asked me to help him in recovering some of the items he left behind.\n\nThe city fell under siege, and he attempted to defend the Tower of Arathor, but to no avail. I have agents in the Highlands already, but they've requested I send more aid. Are you interested?",
    isForever = false,
  },
  [55] = {
    id = 55,
    title = "Morbent Fel",
    reqLevel = 20,
    questLevel = 32,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sven Yorgen",
    objectives = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.",
    rewards = "3,850 XP",
    tip = "Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery.  His time in this land is drawing to an end...\n\nUse Morbent's Bane against him.  It will render his protective magics powerless.\n\nSlay him.  Slay him, and save us from his wickedness.  Be the instrument of my revenge, and a hero of Duskwood!",
    isForever = false,
  },
  [2752] = {
    id = 2752,
    title = "On Iron Pauldrons",
    reqLevel = 32,
    questLevel = 32,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Orokk Omosh",
    objectives = "Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar.",
    rewards = "2,550 XP",
    tip = "Orokk sees the eagerness in your eyes, $N. Like a sponge you soak in the wisdom of the Omosh.\n\nThree lessons I shall teach!\n\nReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.",
    isForever = false,
  },
  [1384] = {
    id = 1384,
    title = "Raid on the Kolkar",
    reqLevel = 30,
    questLevel = 32,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Uthek the Wise",
    objectives = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.",
    rewards = "2,550 XP",
    tip = "The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them!\n\nYou will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!",
    isForever = false,
  },
  [563] = {
    id = 563,
    title = "Reassignment",
    reqLevel = 25,
    questLevel = 32,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Lieutenant Farren Orinelle",
    objectives = "Deliver Farren's report to Major Samuelson in Stormwind Keep.",
    rewards = "3,200 XP",
    tip = "It shouldn't be a problem getting my report seen. The new captain of the guard, Major Samuelson, was my mentor while I was stationed in Stormwind. It should give him more than enough excuse to have me transferred back to the city. I'll need you to carry my report to him, though... wouldn't want ol' Redpath to catch on.",
    isForever = false,
  },
  [1361] = {
    id = 1361,
    title = "Regthar Deathgate",
    reqLevel = 30,
    questLevel = 32,
    faction = "Horde",
    zone = "Desolace",
    npc = "Krusk",
    objectives = "Speak with Regthar Deathgate.",
    rewards = "640 XP",
    tip = "A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.\n\nAnd sharpen your weapons.  Desolace is a place torn by war.",
    isForever = false,
  },
  [1032] = {
    id = 1032,
    title = "Satyr Slaying!",
    reqLevel = 26,
    questLevel = 32,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Illiyana",
    objectives = "- Satyr Horns x 16",
    rewards = "2,550 XP, 30s",
    tip = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.",
    isForever = false,
  },
  [556] = {
    id = 556,
    title = "Stone Tokens",
    reqLevel = 30,
    questLevel = 32,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Keeper Bel'varil",
    objectives = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.",
    rewards = "2,550 XP • 30s",
    tip = "A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study.\n\nEnter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens.\n\nYou might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.",
    isForever = false,
  },
  [562] = {
    id = 562,
    title = "Stormwind Ho!",
    reqLevel = 25,
    questLevel = 32,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Lieutenant Farren Orinelle",
    objectives = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.",
    rewards = "1,950 XP",
    tip = "My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga. From what he's heard, there's good chances for promotion--or at least reassignment--for anyone who proves valuable in this regard.\n\nThere's just one small problem... I can't handle the naga, $n. Oh sure, I could break up a drunken barroom brawl, or haul off a belligerent beggar, but the naga are too much for me. You've got to help me, $n!",
    isForever = false,
  },
  [198] = {
    id = 198,
    title = "Supplies to Private Thorsen",
    reqLevel = 30,
    questLevel = 32,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Krazek",
    objectives = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.",
    rewards = "640 XP • 16s",
    tip = "Hmm. Yes, I do have something you could do, actually. Lieutenant Doren and his followers up in the north need their regular supplies from us.\n\nThey haven't been delivered, and with the trolls attacking, I'll need someone to do it. Doren's camp lies northwest of the road at the entrance to Stranglethorn from Duskwood. Give the supplies to Private Thorsen, if he's not in the camp, then he'll be patrolling south of it. He'll take care of them.\n\nMind you, if you fail, you'll owe me restitution.",
    isForever = false,
  },
  [1031] = {
    id = 1031,
    title = "The Branch of Cenarius",
    reqLevel = 26,
    questLevel = 32,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Anilia",
    objectives = "Kill Geltharis and return the Branch of Cenarius to Illiyana at the Shrine of Aessina.",
    rewards = "2,550 XP",
    tip = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.",
    isForever = false,
  },
  [676] = {
    id = 676,
    title = "The Hammer May Fall",
    reqLevel = 30,
    questLevel = 32,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Tallow",
    objectives = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.",
    rewards = "2,550 XP • 30s",
    tip = "Weaklings... all of them. You, $c, what are you looking at? Think you're something special, huh? Why not prove it?\n\nThe Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent.\n\nBut before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.",
    isForever = false,
  },
  [1362] = {
    id = 1362,
    title = "The Kolkar of Desolace",
    reqLevel = 30,
    questLevel = 32,
    faction = "Horde",
    zone = "Desolace",
    npc = "Regthar Deathgate",
    objectives = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.",
    rewards = "640 XP",
    tip = "The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.\n\nBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.\n\nSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.",
    isForever = false,
  },
  [1021] = {
    id = 1021,
    title = "Vile Satyr! Dryads in Danger!",
    reqLevel = 26,
    questLevel = 32,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Illiyana",
    objectives = "Find Anilia in Xavian.",
    rewards = "2,550 XP",
    tip = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n$n, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.",
    isForever = false,
  },
  [1175] = {
    id = 1175,
    title = "A Bump in the Road",
    reqLevel = 28,
    questLevel = 33,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Trackmaster Zherin",
    objectives = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.",
    rewards = "2,650 XP • 35s",
    tip = "After the big crash with the goblins' Red Thunder racer and a basilisk, Kronkrider hired me on to take care of the track. I don't know what all the animals out on the flats are feeding on to grow so big, but we have to be careful to thin them out so they won't wander onto the track when a race is going on.\n\nTell you what. If you want to go out and make a little profit, go out and remove the basilisks from the area.",
    isForever = false,
  },
  [1433] = {
    id = 1433,
    title = "Alliance Relations",
    reqLevel = 30,
    questLevel = 33,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Takata Steelblade",
    objectives = "Speak to Maurin Bonesplitter in Desolace.",
    rewards = "265 XP",
    tip = "The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.\n\nKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.\n\nHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.\n\nSpeak to him, and he will guide you in his designs.",
    isForever = false,
  },
  [1436] = {
    id = 1436,
    title = "Alliance Relations",
    reqLevel = 30,
    questLevel = 33,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Takata Steelblade",
    objectives = "Speak to Keldran in Orgrimmar.",
    rewards = "2,650 XP",
    tip = "The fight goes well, $N. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings.\n\nReturn to Keldran and let him know what we have done. I am sure he will reward you for your efforts here. His cause is important to him, and he will take pride in knowing that the Warchief respects his concerns.",
    isForever = false,
  },
  [1434] = {
    id = 1434,
    title = "Befouled by Satyr",
    reqLevel = 25,
    questLevel = 33,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Takata Steelblade",
    objectives = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.",
    rewards = "2,650 XP",
    tip = "A demon infestation does not occur without other influences--something else allows evil to gain a foothold.\n\nIt may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr.\n\nTies have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back.",
    isForever = false,
  },
  [1369] = {
    id = 1369,
    title = "Broken Tears",
    reqLevel = 30,
    questLevel = 33,
    faction = "Both",
    zone = "Desolace",
    npc = "Warug",
    objectives = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.",
    rewards = "2,650 XP",
    tip = "The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest!\n\nShow the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!",
    isForever = false,
  },
  [671] = {
    id = 671,
    title = "Foul Magics",
    reqLevel = 30,
    questLevel = 33,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Tor'gan",
    objectives = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.",
    rewards = "2,650 XP",
    tip = "I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew.\n\nOn the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring",
    isForever = false,
  },
  [1368] = {
    id = 1368,
    title = "Gelkis Alliance",
    reqLevel = 30,
    questLevel = 33,
    faction = "Horde",
    zone = "Desolace",
    npc = "Gurda Wildmane",
    objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
    rewards = "660 XP",
    tip = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.",
    isForever = false,
  },
  [1109] = {
    id = 1109,
    title = "Going, Going, Guano!",
    reqLevel = 30,
    questLevel = 33,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Master Apothecary Faranell",
    objectives = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.",
    rewards = "3,300 XP",
    tip = "As you can see, $n, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a $c. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...",
    isForever = false,
  },
  [1113] = {
    id = 1113,
    title = "Hearts of Zeal",
    reqLevel = 30,
    questLevel = 33,
    faction = "Horde",
    zone = "Scarlet Monastery",
    npc = "Master Apothecary Faranell",
    objectives = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.",
    rewards = "3,300 XP",
    tip = "Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.\n\nIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate, both inside and outside the halls. Which you slay matters not, any of them may have the heart",
    isForever = false,
  },
  [552] = {
    id = 552,
    title = "Helcular's Revenge",
    reqLevel = 29,
    questLevel = 33,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Novice Thaivand",
    objectives = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.",
    rewards = "2,650 XP",
    tip = "Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery.\n\nSuch disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.\n\nWe will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.",
    isForever = false,
  },
  [553] = {
    id = 553,
    title = "Helcular's Revenge",
    reqLevel = 29,
    questLevel = 33,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Novice Thaivand",
    objectives = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.$b$bDrive the charged rod into Helcular's grave in Southshore.",
    rewards = "3,300 XP",
    tip = "Here, take the Rod of Helcular. You will need it.\n\nHelcular fashioned 3 ceremonial pyres as part of his most powerful spell.  The Flame of Azel and the Flame of Veraz lie within the Foothill Caverns. The Flame of Uzel lies in a cave above the caverns, further north in the mountains.\n\nThe Rod of Helcular must be charged from each of the three flames. Once the ritual is complete, drive the rod into Helcular's grave in Southshore, the heavily guarded human town to the south.  Vengeance shall be our",
    isForever = false,
  },
  [659] = {
    id = 659,
    title = "Hints of a New Plague?",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Phin Odelic",
    objectives = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.",
    rewards = "1,300 XP",
    tip = "Hail, and well met, $N. I lead a group of adventurers investigating odd happenings in this area.\n\nMy cousin in Hillsbrad recently put down his dog Stanley because the animal mystically grew to an immense size and savagely attacked anyone who came near him.\n\nI believe the undead are involved, and we're looking for signs to prove as much.\n\nTwo of my companions, Quae and Kinelory, headed to the Go'Shek Farm in the Arathi Highlands, and haven't checked in for days. Find them for me? I grow concerned",
    isForever = false,
  },
  [215] = {
    id = 215,
    title = "Jungle Secrets",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Private Thorsen",
    objectives = "Speak with Lieutenant Doren at the Rebel Camp.",
    rewards = "1,300 XP",
    tip = "Thank you for saving me, $N.  I know how this looks, but...allow me to explain.\n\nI was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me.\n\nThis was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain.",
    isForever = false,
  },
  [1367] = {
    id = 1367,
    title = "Magram Alliance",
    reqLevel = 30,
    questLevel = 33,
    faction = "Horde",
    zone = "Desolace",
    npc = "Gurda Wildmane",
    objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.",
    rewards = "660 XP",
    tip = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.",
    isForever = false,
  },
  [191] = {
    id = 191,
    title = "Panther Mastery",
    reqLevel = 28,
    questLevel = 33,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Sir S. J. Erlgadin",
    objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.",
    rewards = "1,300 XP",
    tip = "Now you're ready to turn it up a notch.  If you want to prove yourself worthy of socializing with the likes of these big game hunters, you'll need to prove that you can kill 10 panthers.\n\nThose big boys are tougher.  They're not as easy as the young ones you were killing earlier.",
    isForever = false,
  },
  [1458] = {
    id = 1458,
    title = "Reagents for Reclaimers Inc.",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Kreldig Ungor",
    objectives = "Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.",
    rewards = "2,650 XP • 35s",
    tip = "One of my tasks out here involves picking up some reagents for Leftwitch, a gnome mage in Kharanos . Roetten seems to think it's easy coin in the bank since we're out here already. He doesn't really care that we're short-handed as is.\n\nThe first few items on his list should be easy enough to get, and it'd be a good chunk of coin for anyone helping me out.\n\nI need some horns and claws from the Hatefury satyr to the east of here. Bring 'em back to me and we'll get started on the rest of the list.",
    isForever = false,
  },
  [1453] = {
    id = 1453,
    title = "Reclaimers' Business in Desolace",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Roetten Stonehammer",
    objectives = "Speak to Kreldig Ungor in Desolace.",
    rewards = "1,300 XP",
    tip = "There's work to be done in Desolace, $N. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha.\n\nYou can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.",
    isForever = false,
  },
  [1440] = {
    id = 1440,
    title = "Return to Vahlarriel",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Dalinda Malem",
    objectives = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.",
    rewards = "3,300 XP",
    tip = "So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right.",
    isForever = false,
  },
  [5741] = {
    id = 5741,
    title = "Sceptre of Light",
    reqLevel = 30,
    questLevel = 33,
    faction = "Both",
    zone = "Desolace",
    npc = "Azore Aldamort",
    objectives = "- Sceptre of Light",
    rewards = "2,650 XP, 35s",
    tip = "The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power.\n\nTo that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers.",
    isForever = false,
  },
  [1439] = {
    id = 1439,
    title = "Search for Tyranis",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Dalinda Malem",
    objectives = "Find Tyranis Malem in Desolace.",
    rewards = "2,650 XP",
    tip = "We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans.\n\nTyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why.\n\nPlease, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known.",
    isForever = false,
  },
  [505] = {
    id = 505,
    title = "Syndicate Assassins",
    reqLevel = 26,
    questLevel = 33,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Magistrate Henry Maleb",
    objectives = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.",
    rewards = "1,950 XP",
    tip = "I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate.  The assassins were never found, but through our investigations we're almost certain they were hired by the Syndicate - a group of thieves led by villainous nobles of the now fallen kingdom of Alterac.\n\nThe Syndicate has a camps in Sofera's Naze and Corahn's Dagger, north and west of the Horde-occupied Tarren Mill.  Slay the Syndicate members you find in these camps.",
    isForever = false,
  },
  [1435] = {
    id = 1435,
    title = "The Burning of Spirits",
    reqLevel = 25,
    questLevel = 33,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Maurin Bonesplitter",
    objectives = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.",
    rewards = "2,650 XP",
    tip = "Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness.\n\nTake this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind.\n\nBring me these infused gems so I may dispose of them properly.\n\nGo now, and may you elude death.",
    isForever = false,
  },
  [1480] = {
    id = 1480,
    title = "The Corrupter",
    reqLevel = 25,
    questLevel = 33,
    faction = "Horde",
    zone = "Desolace",
    npc = "Item: Flayed Demon Skin",
    objectives = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.",
    rewards = "1,300 XP",
    tip = "The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile.\n\nAs you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind.\n\nPerhaps it is something Maurin could tell you more about?",
    isForever = false,
  },
  [1481] = {
    id = 1481,
    title = "The Corrupter",
    reqLevel = 25,
    questLevel = 33,
    faction = "Horde",
    zone = "Desolace",
    npc = "Maurin Bonesplitter",
    objectives = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.",
    rewards = "2,650 XP",
    tip = "I believe I can find this demon lord given the proper reagents.\n\nIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.\n\nFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.\n\nSearch for them among the ancient ruins in the northeast of Desolace.",
    isForever = false,
  },
  [1248] = {
    id = 1248,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 33,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Elling Trias",
    objectives = "Speak to Mikhail in the Wetlands.",
    rewards = "660 XP",
    tip = "A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago.\n\nSpeak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's c",
    isForever = false,
  },
  [1249] = {
    id = 1249,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 33,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Mikhail",
    objectives = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.",
    rewards = "1,300 XP",
    tip = "You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you.\n\nHmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him.\n\nDon't look now, $N, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door.",
    isForever = false,
  },
  [1250] = {
    id = 1250,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 33,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Tapoke \"Slim\" Jahn",
    objectives = "Speak to Mikhail in the Wetlands.",
    rewards = "265 XP",
    tip = "The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them.\n\nMy part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know.",
    isForever = false,
  },
  [1264] = {
    id = 1264,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 33,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Mikhail",
    objectives = "Find Commander Samaul in Dustwallow Marsh.",
    rewards = "1,300 XP",
    tip = "The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them.\n\nCommander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discreetly.",
    isForever = false,
  },
  [203] = {
    id = 203,
    title = "The Second Rebellion",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Sergeant Yohwa",
    objectives = "Kill 15 Kurzen Jungle Fighters.\n\nReturn to Sergeant Yohwa at the Rebel Camp.",
    rewards = "1,950 XP",
    tip = "We're fighting a losing battle with Colonel Kurzen.  Not only is he a brilliant tactician, he outnumbers us at least 10 to 1!  To survive, we need to use his own, covert tactics against him.\n\nEnter his camp to the east and kill his men.  Lots of them.  And get out before reinforcements can close on you.",
    isForever = false,
  },
  [1145] = {
    id = 1145,
    title = "The Swarm Grows",
    reqLevel = 29,
    questLevel = 33,
    faction = "Horde",
    zone = "The Barrens",
    npc = "Korran",
    objectives = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.",
    rewards = "1,300 XP",
    tip = "Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.\n\nI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.\n\nBelgrom usually be found outside the warriors' guild house.",
    isForever = false,
  },
  [1146] = {
    id = 1146,
    title = "The Swarm Grows",
    reqLevel = 29,
    questLevel = 33,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Belgrom Rockmaul",
    objectives = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.",
    rewards = "1,950 XP",
    tip = "So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.\n\nA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.\n\nThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him thi",
    isForever = false,
  },
  [186] = {
    id = 186,
    title = "Tiger Mastery",
    reqLevel = 28,
    questLevel = 33,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Ajeck Rouack",
    objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.",
    rewards = "1,300 XP",
    tip = "You are learning, $c.  Let us test your skills with the mature cats now. Kill 10 Stranglethorn Tigers this time out.",
    isForever = false,
  },
  [1437] = {
    id = 1437,
    title = "Vahlarriel's Search",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Vahlarriel Demonslayer",
    objectives = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.",
    rewards = "1,950 XP",
    tip = "I am Vahlarriel, $N. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.\n\nLast word tells of them passing through the Stonetalon Mountains a few weeks ago.\n\nIf you find their wagon, please, come find me immediately.",
    isForever = false,
  },
  [1438] = {
    id = 1438,
    title = "Vahlarriel's Search",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Vahlarriel Demonslayer",
    objectives = "Find Dalinda Malem in Desolace.",
    rewards = "2,650 XP",
    tip = "Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.\n\n$N, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.",
    isForever = false,
  },
  [1465] = {
    id = 1465,
    title = "Vahlarriel's Search",
    reqLevel = 30,
    questLevel = 33,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Object: Malem Chest",
    objectives = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.",
    rewards = "1,950 XP",
    tip = "As you continue your search of the wagon you find not only a pendant, but also footprints leading off towards the south. In the distance you can see smoke rising from a large fort. The smoke is from a kept fire, not the burning of buildings, and your instincts tell you that the Malems, if still alive, were taken that direction.\n\nYou think Vahlarriel at Nijel's Point should not only see the pendant you've found, but also know about the signs of life to the south.",
    isForever = false,
  },
  [1051] = {
    id = 1051,
    title = "Vorrel's Revenge",
    reqLevel = 25,
    questLevel = 33,
    faction = "Horde",
    zone = "Scarlet Monastery",
    npc = "Vorrel Sengutz",
    objectives = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.",
    rewards = "3,300 XP",
    tip = "Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered.\n\nInterrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The bastard!\n\nRevenge... I want revenge!\n\nThe pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill.\n\nHeed my last wishes....",
    isForever = false,
  },
  [304] = {
    id = 304,
    title = "A Grim Task",
    reqLevel = 26,
    questLevel = 34,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Longbraid the Grim",
    objectives = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.",
    rewards = "3,350 XP",
    tip = "Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed.  Aye, the Dark Iron dwarves are a devilish breed.  From what Roggo was able to gather, the leader of the thugs in the Wetlands is a warlock named Balgaras the Foul. He is quite a coward, sending his soldiers to do his bidding but hides in his camp on Direforge Hill, to the southeast.\n\nIf you can find the spineless scum, slay him and bring me his ear. I will reward",
    isForever = false,
  },
  [1102] = {
    id = 1102,
    title = "A Vengeful Fate",
    reqLevel = 29,
    questLevel = 34,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Auld Stonespire",
    objectives = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",
    rewards = "4,050 XP",
    tip = "Cairne is a noble leader for uniting our people here on Thunder Bluff.\n\nBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.\n\nA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.\n\nBring me Razorflank's heart and I can die in peace, $n.",
    isForever = false,
  },
  [8260] = {
    id = 8260,
    title = "Arathor Basic Care Package",
    reqLevel = 25,
    questLevel = 34,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Samuel Hawke",
    objectives = "- The League of Arathor:",
    rewards = "270 XP",
    tip = "",
    isForever = false,
  },
  [204] = {
    id = 204,
    title = "Bad Medicine",
    reqLevel = 30,
    questLevel = 34,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Sergeant Yohwa",
    objectives = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.",
    rewards = "2,700 XP",
    tip = "To have a chance against Kurzen, we need his healing support neutralized.  He has gathered a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts.\n\nWe need those remedies and extracts for our own.  Search the Kurzen Compound - his Medicine Men and Jungle fighers will have the remedies, and the extracts are probably stowed in some of the camp's supply boxes.",
    isForever = false,
  },
  [565] = {
    id = 565,
    title = "Bartolo's Yeti Fur Cloak",
    reqLevel = 29,
    questLevel = 34,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Bartolo Ginsetti",
    objectives = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.",
    rewards = "2,700 XP",
    tip = "I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!\n\nTravel the planet and find yourself a better cloak, I dare you.  Oh wait, what is that, little $r?  \"Bartolo, there is no finer cloak!\"  Yes, yes!  That, I have heard before.\n\nBartolo requires a Bolt of Wool, a Hillman's Cloak made by a skilled leatherworker, Fine Thread and Yeti Fur, of course!  Bring to me these items and you shall be a happy customer!",
    isForever = false,
  },
  [557] = {
    id = 557,
    title = "Bracers of Binding",
    reqLevel = 30,
    questLevel = 34,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Keeper Bel'varil",
    objectives = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.",
    rewards = "2,700 XP • 35s",
    tip = "The Magus will be busy studying those stone tokens you gathered, but I know he'll eventually want examples of their counterpart: bracers of binding.  These are set around the wrists of actual elementals, and bind them into the mage's service.\n\nHunt elementals in the ruins of Dalaran and gather their Bracers of Earth Binding, and the Magus will be pleased.",
    isForever = false,
  },
  [4781] = {
    id = 4781,
    title = "Components for the Enchanted Gold Bloodrobe",
    reqLevel = 31,
    questLevel = 34,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.",
    rewards = "2,000 XP",
    tip = "Your next task is as simple as your first, but will require you to seek out aid.\n\nI require gold thread for the embroidery of the cloak, but gold thread is not easy to come by, and very few know how to make it. Fortunately, one who is loyal to our cause knows its secrets and is willing to help those rising in our ranks.\n\nBring a gold bar to Xizk Goodstitch in Booty Bay. He is a master tailor and will be happy to spin the thread for you. Gold bars are smelted by skilled miners. Ask a miner for he",
    isForever = false,
  },
  [4782] = {
    id = 4782,
    title = "Components for the Enchanted Gold Bloodrobe",
    reqLevel = 31,
    questLevel = 34,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Xizk Goodstitch",
    objectives = "Return to Menara Voidrender in the Barrens.",
    rewards = "1,350 XP",
    tip = "Return to Menara, tell her it'll take some time, but I'll make sure to come through for her... and you. Tell her to have you finish gathering the rest of your components--I should have the thread done by then. You can return and pick it up then.\n\nGood luck, $N. Oh, and say hello to Strahad for me while you're there. That old coot... putting a tower right there next to Ratchet... crazy.",
    isForever = false,
  },
  [564] = {
    id = 564,
    title = "Costly Menace",
    reqLevel = 30,
    questLevel = 34,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Darren Malvew",
    objectives = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.",
    rewards = "2,700 XP",
    tip = "Ain't nothin' that irks me more than losin' these here beautiful horses.  And believe me, we've lost quite a few between them pesky undead creeps, the dang Syndicate gang and all the other good-for-nothin' scoundrels pokin' about these parts.\n\nBut I swear on my ol' grand-daddy's grave there ain't no bigger menace to our horses here than them Mountain Lions up in Alterac.  Always comin' down from the hills and makin' my life difficult!\n\nYou fancy yourself a hero?  Go and do somethin' about it the",
    isForever = false,
  },
  [8263] = {
    id = 8263,
    title = "Defiler's Basic Care Package",
    reqLevel = 25,
    questLevel = 34,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Rutherford Twing",
    objectives = "- The Defilers:",
    rewards = "270 XP",
    tip = "",
    isForever = false,
  },
  [511] = {
    id = 511,
    title = "Encrypted Letter",
    reqLevel = 30,
    questLevel = 34,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Object: Syndicate Documents",
    objectives = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.",
    rewards = "1,350 XP",
    tip = "One of the letters on this table is encrypted and inscrutable.",
    isForever = false,
  },
  [510] = {
    id = 510,
    title = "Foreboding Plans",
    reqLevel = 26,
    questLevel = 34,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Object: Syndicate Documents",
    objectives = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.",
    rewards = "1,350 XP",
    tip = "Among these documents is a list of requested supplies.  These include mundane items (food, weapons, clothing) as well as more exotic gear (masks, oil, poison).\n\nBut what is most notable is the urgency of the request - these supplies were needed soon in order to undertake what is described in the document as an \"important mission against Southshore.\"",
    isForever = false,
  },
  [525] = {
    id = 525,
    title = "Further Mysteries",
    reqLevel = 30,
    questLevel = 34,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Prospector Stormpike",
    objectives = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.",
    rewards = "1,350 XP",
    tip = "I decrypted the letter, but I don't know what to make of it.  You found this among thieves in the Alterac foothills?  Very strange...\n\nYou should take this to the magistrate of Southshore.  Although this letter is cryptic, his is the closest town to Alterac; if a threat is brewing, then he should know.",
    isForever = false,
  },
  [2945] = {
    id = 2945,
    title = "Grime-Encrusted Ring",
    reqLevel = 28,
    questLevel = 34,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: Grime-Encrusted Ring",
    objectives = "Figure out a way to remove the grime from the Grime-Encrusted Ring.",
    rewards = "2,700 XP",
    tip = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.",
    isForever = false,
  },
  [655] = {
    id = 655,
    title = "Hammerfall",
    reqLevel = 29,
    questLevel = 34,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Gor'mul",
    objectives = "Speak with Tor'gan in Hammerfall.",
    rewards = "270 XP",
    tip = "It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.\n\nIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...",
    isForever = false,
  },
  [581] = {
    id = 581,
    title = "Hunt for Yenniku",
    reqLevel = 30,
    questLevel = 34,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Nimboya",
    objectives = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.",
    rewards = "2,000 XP",
    tip = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.",
    isForever = false,
  },
  [533] = {
    id = 533,
    title = "Infiltration",
    reqLevel = 29,
    questLevel = 34,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Krusk",
    objectives = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.",
    rewards = "2,700 XP • 35s",
    tip = "At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here.\n\nGo there, $n, and bring back whatever information you can get your hands on.",
    isForever = false,
  },
  [5561] = {
    id = 5561,
    title = "Kodo Roundup",
    reqLevel = 30,
    questLevel = 34,
    faction = "Both",
    zone = "Desolace",
    npc = "Smeed Scrabblescrew",
    objectives = "Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.",
    rewards = "2,000 XP",
    tip = "Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership.\n\nTake the kombobulator and use it on any ancient, aged, or dying kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me",
    isForever = false,
  },
  [514] = {
    id = 514,
    title = "Letter to Stormpike",
    reqLevel = 30,
    questLevel = 34,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Loremaster Dibbs",
    objectives = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.",
    rewards = "1,350 XP",
    tip = "I have a colleague in Ironforge who may be able to help decrypt this letter.  Go to the Library in the Hall of Explorers in Ironforge and speak with Prospector Stormpike.  Tell him I sent you and show him the letter.  If there's anyone north of Blackrock Spire who can read this, it is he.",
    isForever = false,
  },
  [1100] = {
    id = 1100,
    title = "Lonebrow's Journal",
    reqLevel = 29,
    questLevel = 34,
    faction = "Alliance",
    zone = "Thousand Needles",
    npc = "Item: Henrig Lonebrow's Journal",
    objectives = "Read Henrig Lonebrow's Journal.",
    rewards = "1,350 XP",
    tip = "You slowly open the weathered journal of Henrig Lonebrow....",
    isForever = false,
  },
  [7866] = {
    id = 7866,
    title = "Outrider Basic Care Package",
    reqLevel = 25,
    questLevel = 34,
    faction = "Horde",
    zone = "Ashenvale",
    npc = "Kelm Hargunth",
    objectives = "Speak with Kelm Hargunth in Ashenvale.",
    rewards = "270 XP",
    tip = "",
    isForever = false,
  },
  [544] = {
    id = 544,
    title = "Prison Break In",
    reqLevel = 30,
    questLevel = 34,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Magus Wordeen Voidglare",
    objectives = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.",
    rewards = "3,350 XP • 70s",
    tip = "I came to Tarren Mill to research, but now must resolve a crisis.  You see, four Forsaken fled the Undercity a few months ago.  They turned their backs on their brethren, but what's worse...they stole from the Dark Lady.\n\nThese thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies.  Sylvanas would have these artifacts returned.\n\nThe thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.",
    isForever = false,
  },
  [672] = {
    id = 672,
    title = "Raising Spirits",
    reqLevel = 29,
    questLevel = 34,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Tor'gan",
    objectives = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.",
    rewards = "2,700 XP",
    tip = "We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him.\n\nTales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try!\n\nA small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.",
    isForever = false,
  },
  [674] = {
    id = 674,
    title = "Raising Spirits",
    reqLevel = 29,
    questLevel = 34,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Tor'gan",
    objectives = "Give the Raptor Talon Amulet to Gor'mul.",
    rewards = "270 XP",
    tip = "Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.",
    isForever = false,
  },
  [675] = {
    id = 675,
    title = "Raising Spirits",
    reqLevel = 29,
    questLevel = 34,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Gor'mul",
    objectives = "Speak with Tor'gan.",
    rewards = "270 XP",
    tip = "<Gor'mul tosses the amulet into the ground.>\n\nTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...",
    isForever = false,
  },
  [194] = {
    id = 194,
    title = "Raptor Mastery",
    reqLevel = 28,
    questLevel = 34,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Hemet Nesingwary",
    objectives = "Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors.",
    rewards = "1,350 XP",
    tip = "So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill 10 Stranglethorn Raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge.",
    isForever = false,
  },
  [2947] = {
    id = 2947,
    title = "Return of the Ring",
    reqLevel = 28,
    questLevel = 34,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Object: The Sparklematic 5200",
    objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
    rewards = "2,700 XP",
    tip = "Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...",
    isForever = false,
  },
  [2949] = {
    id = 2949,
    title = "Return of the Ring",
    reqLevel = 28,
    questLevel = 34,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Object: The Sparklematic 5200",
    objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
    rewards = "2,700 XP",
    tip = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...",
    isForever = false,
  },
  [7863] = {
    id = 7863,
