  [1101] = {
    id = 1101,
    title = "The Crone of the Kraul",
    reqLevel = 29,
    questLevel = 34,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Falfindel Waywarder",
    objectives = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.",
    rewards = "3,350 XP",
    tip = "Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.\n\nWe must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.\n\nSurely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. $n, assemble a party to slay the crone.\n\nBring me Razorflank's Medallion as proof of demise.",
    isForever = false,
  },
  [535] = {
    id = 535,
    title = "Valik",
    reqLevel = 29,
    questLevel = 34,
    faction = "Horde",
    zone = "Alterac Mountains",
    npc = "Henchman Valik",
    objectives = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.",
    rewards = "270 XP",
    tip = "Urrgh... Injured and dying and confronted with the enemy.\n\nNo doubt you'll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don't they?--I'll tell you what you want to know.",
    isForever = false,
  },
  [231] = {
    id = 231,
    title = "A Daughter's Love",
    reqLevel = 28,
    questLevel = 35,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Watcher Ladimore",
    objectives = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.",
    rewards = "1,350 XP",
    tip = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, $n.",
    isForever = false,
  },
  [719] = {
    id = 719,
    title = "A Dwarf and His Tools",
    reqLevel = 35,
    questLevel = 35,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Prospector Ryedol",
    objectives = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.",
    rewards = "2,750 XP",
    tip = "Hey, $N. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan.\n\nThey just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe. I barely escaped with me life.\n\nThe site's just to the north of here, and I'm tryin' to plan a way to get some of our supplies back, especially me lucky pick.\n\nThink you'd be up to helpin' me out some? One of those damned Dark Iron must have my pick! Could be anyone of them.",
    isForever = false,
  },
  [6626] = {
    id = 6626,
    title = "A Host of Evil",
    reqLevel = 28,
    questLevel = 35,
    faction = "Both",
    zone = "Razorfen Downs",
    npc = "Myriam Moonsinger",
    objectives = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.",
    rewards = "3,450 XP • 75s",
    tip = "The Forsaken do not pass on their... illness... from what I have seen. This diplomat seems to be granting undeath to would-be followers. I am beginning to think he is one of the Scourge.\n\nFor now, my concern is not with him though, it's with the growing ranks around him. They creep from the shadows daily, almost begging him for more power.\n\nI'm not powerful enough to fight them on my own, $N. What do you say? Are you up for some hunting?",
    isForever = false,
  },
  [720] = {
    id = 720,
    title = "A Sign of Hope",
    reqLevel = 35,
    questLevel = 35,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Object: Crumpled Map",
    objectives = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.",
    rewards = "1,350 XP",
    tip = "<There is text roughly scribbled in chalk on the map.>\n\n\"Ryedol, \nThey're taking me to Uldaman. Send help.\n-Hammertoe\"",
    isForever = false,
  },
  [721] = {
    id = 721,
    title = "A Sign of Hope",
    reqLevel = 35,
    questLevel = 35,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Prospector Ryedol",
    objectives = "Find Hammertoe Grez in Uldaman.",
    rewards = "2,750 XP",
    tip = "$N, can ye find him? Can you find Hammertoe in Uldaman?\n\nIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.\n\nFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.\n\nThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!",
    isForever = false,
  },
  [8156] = {
    id = 8156,
    title = "Arathi Basin Resources!",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Sergeant Maclear",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "2,750 XP • 1g 10s",
    tip = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [189] = {
    id = 189,
    title = "Bloodscalp Ears",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Kebok",
    objectives = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.",
    rewards = "2,050 XP • 35s",
    tip = "Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz?\n\nDecisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... $n, is it? You'll help me, won't you? There's money to be had!\n\nHere's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well.",
    isForever = false,
  },
  [5821] = {
    id = 5821,
    title = "Bodyguard for Hire",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Desolace",
    npc = "Cork Gizelton",
    objectives = "Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.",
    rewards = "2,750 XP",
    tip = "Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop. It's not good for business to be dead!\n\nI'll tell you what $c, if you protect us past the Kolkar village we'll make it worth your while.\n\nIt's just a short distance, all you need to do is keep the caravan intact and you can pick up your reward from Smeed Scrabblescrew - he is down the road a bit. We do a little business together.",
    isForever = false,
  },
  [200] = {
    id = 200,
    title = "Bookie Herod",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Lieutenant Doren",
    objectives = "Find Bookie Herod's Records.",
    rewards = "1,350 XP",
    tip = "If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked!\n\nThorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered.\n\nWhen we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still t",
    isForever = false,
  },
  [1385] = {
    id = 1385,
    title = "Brutal Politics",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Captain Pentigast",
    objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.",
    rewards = "2,050 XP",
    tip = "Desolace is a land at war.  The centaurs wage war with each other, and we believe the victor among them will spill out and threaten our strongholds.  That, we cannot allow\n\nWe must learn how to beat the centaurs, and to do that... we must ally with one of the clans.  The Magram centaurs war with the Gelkis.  If you fight the Gelkis then the Magram might consider an alliance.\n\nEarn the favor of the Magrams then speak with Warug, in the Magram village in southeastern Desolace.",
    isForever = false,
  },
  [1220] = {
    id = 1220,
    title = "Captain Vimes",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Theramore Lieutenant",
    objectives = "Bring the Spy's Report to Captain Garran Vimes.",
    rewards = "2,750 XP",
    tip = "Captain Vimes should see the orc report you found, $N.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.",
    isForever = false,
  },
  [2842] = {
    id = 2842,
    title = "Chief Engineer Scooty",
    reqLevel = 25,
    questLevel = 35,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Sovik",
    objectives = "Speak with Scooty in Booty Bay.",
    rewards = "275 XP",
    tip = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, $N. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!",
    isForever = false,
  },
  [6142] = {
    id = 6142,
    title = "Clam Bait",
    reqLevel = 31,
    questLevel = 35,
    faction = "Horde",
    zone = "Desolace",
    npc = "Mai'Lahii",
    objectives = "Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.",
    rewards = "2,750 XP",
    tip = "You have the look of a fisherman, $c! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?\n\nUp north you will find a wrecked ship off the coast. Soft-shelled clams are littered throughout the area. If you bring me back 10 pieces of soft-shelled clam meat, I will give you something in return.",
    isForever = false,
  },
  [635] = {
    id = 635,
    title = "Crystal in the Mountains",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Item: Pendant of Myzrael",
    objectives = "Find the crystal from your vision.",
    rewards = "275 XP",
    tip = "This shard pulses as you hold it...\n\nYou feel a sense of pleading coming from the shard, as if someone is trying to communicate, someone who desperately needs your help.\n\nA vision appears in your mind - of the northern mountains of Arathi, and of a brilliant crystal jutting from the earth there.\n\nYou feel drawn to that place.",
    isForever = false,
  },
  [8161] = {
    id = 8161,
    title = "Cut Arathor Supply Lines",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathstalker Mortis",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "2,750 XP • 1g 10s",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
  [545] = {
    id = 545,
    title = "Dalaran Patrols",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Magus Wordeen Voidglare",
    objectives = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.",
    rewards = "2,050 XP • 25s",
    tip = "The wizards of Dalaran constructed a vast, magical dome around the heart of their city.  Some believe it was for protection from the violence of these times, while others say they merely wanted solitude, to study and plot.\n\nI don't care what the reason was.  I do care that the ruined outskirts of their city, outside the dome, may hide valuable magical treasures.\n\nBut the area is patrolled by the wizards and their elemental slaves.\n\nSo hunt them, and return when their numbers are sufficiently red",
    isForever = false,
  },
  [254] = {
    id = 254,
    title = "Digging Through the Dirt",
    reqLevel = 20,
    questLevel = 35,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Object: Eliza's Grave Dirt",
    objectives = "Inspect Eliza's Grave Dirt in Duskwood.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [1389] = {
    id = 1389,
    title = "Draenethyst Crystals",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Swamp of Sorrows",
    npc = "Magtoor",
    objectives = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.",
    rewards = "2,750 XP",
    tip = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the east, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.",
    isForever = false,
  },
  [1107] = {
    id = 1107,
    title = "Encrusted Tail Fins",
    reqLevel = 28,
    questLevel = 35,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Wizzle Brassbolts",
    objectives = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.",
    rewards = "3,450 XP • 75s",
    tip = "Our rocket car is the fastest thing on the flats!  So fast that ... I'm afraid friction is going to tear it apart!\n\nTo prevent that I need to create a composite to coat the car's moving parts.  It must be hard but not brittle, and must be resistant to salt corrosion, or time spent on the Shimmering Flats will eat it away.\n\nHave you heard of the Vile Reef, $N?  It's off the coast of Stranglethorn Vale.  Saltscale murlocs live there, and their tail fins are a crucial ingredient of my composite.",
    isForever = false,
  },
  [5361] = {
    id = 5361,
    title = "Family Tree",
    reqLevel = 32,
    questLevel = 35,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Cliffwatcher Longhorn",
    objectives = "Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace.",
    rewards = "2,050 XP • 25s",
    tip = "My brother Nataka is stationed at Ghost Walker Post over in Desolace. I'd like to ask you... could you give this report to him for me? A year has passed since the last time I wrote, there has been unusual centaur activity since then and he should be informed.\n\nJourney to Stonetalon Mountain north of the Crossroads, and then head west into Charred Vale. From there, head south into Desolace; there you will find a road going south to Ghost Walker Post.",
    isForever = false,
  },
  [1371] = {
    id = 1371,
    title = "Gizmo for Warug",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Desolace",
    npc = "Warug",
    objectives = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.",
    rewards = "2,050 XP",
    tip = "Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh.\n\nI kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it.\n\nI want a new one.  Get me a new one!",
    isForever = false,
  },
  [2948] = {
    id = 2948,
    title = "Gnome Improvement",
    reqLevel = 28,
    questLevel = 35,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Talvash del Kissel",
    objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.",
    rewards = "1,350 XP",
    tip = "Listen $n, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...\n\nI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!\n\nTrust me!",
    isForever = false,
  },
  [2843] = {
    id = 2843,
    title = "Gnomer-gooooone!",
    reqLevel = 20,
    questLevel = 35,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Scooty",
    objectives = "- Goblin Transponder",
    rewards = "Experience & Faction Reputation",
    tip = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.",
    isForever = false,
  },
  [1301] = {
    id = 1301,
    title = "James Hyal",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Connor Rivers",
    objectives = "Speak with Vincent Hyal in Menethil Harbor.",
    rewards = "690 XP",
    tip = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?",
    isForever = false,
  },
  [1302] = {
    id = 1302,
    title = "James Hyal",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Wetlands",
    npc = "Vincent Hyal",
    objectives = "Speak with Clerk Lendry in Theramore.",
    rewards = "690 XP",
    tip = "My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.\n\nI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him. Look for him on the top floor of that keep near the middle of the city. What's it called... Foothold Citadel, that",
    isForever = false,
  },
  [1206] = {
    id = 1206,
    title = "Jarl Needs Eyes",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Dustwallow Marsh",
    npc = "\"Swamp Eye\" Jarl",
    objectives = "Bring 40 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.",
    rewards = "2,750 XP",
    tip = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?",
    isForever = false,
  },
  [1203] = {
    id = 1203,
    title = "Jarl Needs a Blade",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Dustwallow Marsh",
    npc = "\"Swamp Eye\" Jarl",
    objectives = "Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh.",
    rewards = "3,450 XP • 35s",
    tip = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a moonsteel broadsword.  I call it a swing blade.\n\nYou help me?  Maybe you find it in town, maybe you talk to a blacksmith and he'll make it special.\n\nBut don't sleep on this.  What I'm cutting won't keep forever...",
    isForever = false,
  },
  [1365] = {
    id = 1365,
    title = "Khan Dez'hepah",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Desolace",
    npc = "Felgur Twocuts",
    objectives = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.",
    rewards = "3,450 XP",
    tip = "The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.\n\nWe must deal with them before they unite.\n\nYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.\n\nThe Kolkar Village is northeast of here.  Go, and may fortune go with you.",
    isForever = false,
  },
  [4965] = {
    id = 4965,
    title = "Knowledge of the Orb of Orahil",
    reqLevel = 35,
    questLevel = 35,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Briarthorn",
    objectives = "Speak to Menara Voidrender in the Barrens.",
    rewards = "1,350 XP",
    tip = "Well, well, well... a pleasure to see you're growing in power, $N. I'd wager you'd be about ready to speak to Menara Voidrender in the Barrens. If you haven't spoken to her before, then let me tell you, I don't think I've ever met another expert in the creation of items--orbs specifically--that can inprison even a demon to serve our will so easily.\n\nIf you're interested, she's in Strahad's tower above Ratchet in the Barrens.",
    isForever = false,
  },
  [4967] = {
    id = 4967,
    title = "Knowledge of the Orb of Orahil",
    reqLevel = 35,
    questLevel = 35,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Zevrost",
    objectives = "Speak to Menara Voidrender in the Barrens.",
    rewards = "1,350 XP",
    tip = "Still a fool, and still seeking the trappings of mortals. Yes, I speak to you with arrogance. I see you before me and I laugh. You're pathetic!\n\nBut it matters not what I think. It only matters what those willing to deal with you thinks!  And in this case, against my better judgment, those with some portion of power feel you deserve more.\n\nIf this is something you strive for then you should speak with Menara Voidrender in the tower above Ratchet. I believe you have met her before some time ago.",
    isForever = false,
  },
  [4968] = {
    id = 4968,
    title = "Knowledge of the Orb of Orahil",
    reqLevel = 35,
    questLevel = 35,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Demisette Cloyce",
    objectives = "Speak to Menara Voidrender in the Barrens.",
    rewards = "1,350 XP",
    tip = "Hmm, you've made it this far... truly astonishing. I would have thought the corruption of channeling the arcane would have seeped into your very soul and driven you mad by now. How about we try and push you further then?\n\nIf you want to test your skill, seek out Menara Voidrender above Ratchet in Strahad's tower. She will guide you.",
    isForever = false,
  },
  [4969] = {
    id = 4969,
    title = "Knowledge of the Orb of Orahil",
    reqLevel = 35,
    questLevel = 35,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Kaal Soulreaper",
    objectives = "Speak to Menara Voidrender in the Barrens.",
    rewards = "1,350 XP",
    tip = "Haha! You're doing very well for yourself, young $c.\n\nGiven time, infernals and dreadlords will bow before you!\n\nBut until that time comes, you must still rely on weapons forged by the hands of the mortal races.\n\nYou seem prepared for another such creation, and if you are willing, Menara Voidrender would speak with you! She is near Strahad's tower overlooking the port town of Ratchet. Go there when you are ready.",
    isForever = false,
  },
  [663] = {
    id = 663,
    title = "Land Ho!",
    reqLevel = 35,
    questLevel = 35,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Lolo the Lookout",
    objectives = "Talk to Captain O'Breen in Faldir's Cove.",
    rewards = "690 XP",
    tip = "Lolo sees a tiny $r! Always on the lookout, Lolo is!\n\nWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.\n\nBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!\n\nLolo suggests you talk to Captain O'Breen if you plan on sticking around here.",
    isForever = false,
  },
  [636] = {
    id = 636,
    title = "Legends of the Earth",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Quest Event / Discovery",
    objectives = "Find the Shards of Myzrael.",
    rewards = "275 XP",
    tip = "This book tells the tale of an elemental princess, Myzrael, and of her imprisonment deep underneath the Arathi Highlands.\n\nIt also tells of a secret outcropping of crystals in the highlands.  These crystals, the Shards of Myzrael, are a window to the princess' prison.\n\nIf a brave soul found the Shards of Myzrael, the perhaps $ghe:she; could speak with her...",
    isForever = false,
  },
  [7924] = {
    id = 7924,
    title = "Mark of Honor",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Warsong Mark of Honor for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to rage against the Silverwing Sentinels! Bring me more marks of honor!",
    isForever = false,
  },
  [1106] = {
    id = 1106,
    title = "Martek the Exiled",
    reqLevel = 26,
    questLevel = 35,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Fizzle Brassbolts",
    objectives = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.",
    rewards = "1,350 XP",
    tip = "I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!\n\nBut there is someone who might know how.\n\nHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!\n\nBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!\n\nFind him!",
    isForever = false,
  },
  [228] = {
    id = 228,
    title = "Mor'Ladim",
    reqLevel = 28,
    questLevel = 35,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Commander Althea Ebonlocke",
    objectives = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.",
    rewards = "2,050 XP • 35s",
    tip = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.",
    isForever = false,
  },
  [8159] = {
    id = 8159,
    title = "More Resource Crates",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "",
    tip = "War must be fought with soldiers, any soldier will tell you. They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important. There are key areas in the basin that hold essential resources. Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N. Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [8164] = {
    id = 8164,
    title = "More Resource Crates",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi. They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe. We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N. Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman. Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
  [227] = {
    id = 227,
    title = "Morgan Ladimore",
    reqLevel = 28,
    questLevel = 35,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Sirra Von'Indi",
    objectives = "Speak with Commander Althea Ebonlocke in Darkshire.",
    rewards = "275 XP",
    tip = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.",
    isForever = false,
  },
  [1418] = {
    id = 1418,
    title = "Neeka Bloodscar",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Helgrum the Swift",
    objectives = "Speak with Neeka Bloodscar.",
    rewards = "1,350 XP",
    tip = "The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.\n\nProve yourself, $N.  Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost.  Speak with her, and then send her report back to me.",
    isForever = false,
  },
  [2950] = {
    id = 2950,
    title = "Nogg's Ring Redo",
    reqLevel = 28,
    questLevel = 35,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Nogg",
    objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.",
    rewards = "1,350 XP",
    tip = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?",
    isForever = false,
  },
  [1148] = {
    id = 1148,
    title = "Parts of the Swarm",
    reqLevel = 28,
    questLevel = 35,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Item: Cracked Silithid Carapace",
    objectives = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.",
    rewards = "2,750 XP",
    tip = "You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.\n\nLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they co",
    isForever = false,
  },
  [1184] = {
    id = 1184,
    title = "Parts of the Swarm",
    reqLevel = 28,
    questLevel = 35,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Korran",
    objectives = "Return to Belgrom Rockmaul in Orgrimmar.",
    rewards = "1,350 XP • 18s",
    tip = "Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.",
    isForever = false,
  },
  [7874] = {
    id = 7874,
    title = "Quell the Silverwing Usurpers",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Captain Shatterskull",
    objectives = "- Warsong Gulch Mark of Honor",
    rewards = "2,750 XP, 1g 10s",
    tip = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.",
    isForever = false,
  },
  [1459] = {
    id = 1459,
    title = "Reagents for Reclaimers Inc.",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Kreldig Ungor",
    objectives = "Bring 10 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.",
    rewards = "2,750 XP • 25s",
    tip = "Next on Leftwitch's list is... let's see... hmm. Oh, here it is.\n\nSimple enough, but pretty explicit in his directions. He needs venom from the scorpashi, and hide from some kodo. The fine print says both are from specific creatures: the venom's got to come from any of the scorpashi, and the hide's got to come from an aged kodo, not the dying or ancient ones.\n\nMages, I tell ya, some of the stuff they want... it's just weird.",
    isForever = false,
  },
  [2841] = {
    id = 2841,
    title = "Rig Wars",
    reqLevel = 25,
    questLevel = 35,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Nogg",
    objectives = "- Rig Blueprints - Thermaplugg's Safe Combination",
    rewards = "2,750 XP",
    tip = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, $N!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, $N. Then crack open that safe and bring back those blueprint",
    isForever = false,
  },
  [605] = {
    id = 605,
    title = "Singing Blue Shards",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Crank Fizzlebub",
    objectives = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.",
    rewards = "2,750 XP • 35s",
    tip = "The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any!\n\nI'd like to hire you.\n\nThe basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it.\n\nYou can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the n",
    isForever = false,
  },
  [1218] = {
    id = 1218,
    title = "Soothing Spices",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Dustwallow Marsh",
    npc = "\"Swamp Eye\" Jarl",
    objectives = "Bring 3 Soothing Spices to \"Swamp Eye\" Jarl in Dustwallow Marsh.",
    rewards = "1,350 XP",
    tip = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd for cooking, I need spice.  Soothing spice.  Then I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?",
    isForever = false,
  },
  [1370] = {
    id = 1370,
    title = "Stealing Supplies",
    reqLevel = 30,
    questLevel = 35,
    faction = "Both",
    zone = "Desolace",
    npc = "Uthek the Wise",
    objectives = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.",
    rewards = "1,350 XP",
    tip = "When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones.\n\nIt is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.",
    isForever = false,
  },
  [1382] = {
    id = 1382,
    title = "Strange Alliance",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Captain Pentigast",
    objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
    rewards = "2,050 XP",
    tip = "We are fortunate the centaur clans fight among themselves, for if they joined into a single force then they would be unstoppable.  Yes, we are fortunate, and we should press our advantage.\n\nOne of the centaur clans, the Gelkis clan, is in brutal war with the Magram clan.  If we attack the Magram, then perhaps an alliance may be struck with the Gelkis.\n\nSpeak with Uthek the Wise, in the outskirts of the Gelkis camps in southwestern Desolace.  Through her we might strike an alliance with the Gelki",
    isForever = false,
  },
  [1268] = {
    id = 1268,
    title = "Suspicious Hoofprints",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Object: Hoofprints",
    objectives = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.",
    rewards = "1,350 XP",
    tip = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.",
    isForever = false,
