  [7887] = {
    id = 7887,
    title = "Talismans of Merit",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to aid the cause and bring me more talismans of merit. Do this, and you will earn even more of our trust.",
    isForever = false,
  },
  [8167] = {
    id = 8167,
    title = "The Battle for Arathi Basin!",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Field Marshal Oslight",
    objectives = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.",
    rewards = "2,750 XP • 75s",
    tip = "$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.",
    isForever = false,
  },
  [8170] = {
    id = 8170,
    title = "The Battle for Arathi Basin!",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathmaster Dwire",
    objectives = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
    rewards = "2,750 XP • 75s",
    tip = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, $N.  Report back to me when this task is compl",
    isForever = false,
  },
  [1251] = {
    id = 1251,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Object: Black Shield",
    objectives = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.",
    rewards = "690 XP",
    tip = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.",
    isForever = false,
  },
  [1253] = {
    id = 1253,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Object: Black Shield",
    objectives = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.",
    rewards = "690 XP",
    tip = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.",
    isForever = false,
  },
  [1319] = {
    id = 1319,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Captain Garran Vimes",
    objectives = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.",
    rewards = "275 XP",
    tip = "I'm sorry I can't be of much help, $n, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.",
    isForever = false,
  },
  [1320] = {
    id = 1320,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Caz Twosprocket",
    objectives = "Speak with Captain Garran Vimes in Theramore.",
    rewards = "1,350 XP",
    tip = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.",
    isForever = false,
  },
  [1321] = {
    id = 1321,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Krog",
    objectives = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.",
    rewards = "275 XP",
    tip = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...",
    isForever = false,
  },
  [1482] = {
    id = 1482,
    title = "The Corrupter",
    reqLevel = 25,
    questLevel = 35,
    faction = "Horde",
    zone = "Desolace",
    npc = "Maurin Bonesplitter",
    objectives = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.",
    rewards = "2,750 XP",
    tip = "An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.\n\nNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.\n\nWhen you return, we shall see about finding this demon lord Azrethoc.",
    isForever = false,
  },
  [1484] = {
    id = 1484,
    title = "The Corrupter",
    reqLevel = 25,
    questLevel = 35,
    faction = "Horde",
    zone = "Desolace",
    npc = "Maurin Bonesplitter",
    objectives = "Speak to Takata Steelblade in Desolace.",
    rewards = "265 XP",
    tip = "This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.\n\nSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.",
    isForever = false,
  },
  [229] = {
    id = 229,
    title = "The Daughter Who Lived",
    reqLevel = 28,
    questLevel = 35,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Commander Althea Ebonlocke",
    objectives = "Speak with Watcher Sarah Ladimore in Darkshire.",
    rewards = "275 XP",
    tip = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.",
    isForever = false,
  },
  [2929] = {
    id = 2929,
    title = "The Grand Betrayal",
    reqLevel = 25,
    questLevel = 35,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "High Tinker Mekkatorque",
    objectives = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.",
    rewards = "2,750 XP • 35s",
    tip = "I trusted Thermaplugg, $r. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....\n\nWe will retake Gnomeregan, $N. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.",
    isForever = false,
  },
  [98] = {
    id = 98,
    title = "The Legend of Stalvan",
    reqLevel = 22,
    questLevel = 35,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Commander Althea Ebonlocke",
    objectives = "Kill Stalvan Mistmantle and show Madame Eva his family ring.",
    rewards = "4,100 XP",
    tip = "Stalvan Mistmantle led a life of depravity.  Innocent victims died by his hand.  Undoubtedly he is guilty of countless crimes.  Now the lunatic threatens Darkshire.  The Light only knows what sordid acts he is plotting.  Travel to his cottage just north of town, $C, and execute Stalvan, once and for all.\n\nWhen the deed is done, travel to Madame Eva's and show her his family ring.  After all, it was her premonition that led to this gruesome discovery.  But Darkshire is safer because of her.",
    isForever = false,
  },
  [1421] = {
    id = 1421,
    title = "The Lost Caravan",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Swamp of Sorrows",
    npc = "Watcher Biggs",
    objectives = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.",
    rewards = "2,750 XP",
    tip = "I was stunned during the attack by the Lost Ones, but before my sight went black I spied one of our wagons being dragged to the Fallow Sanctuary, the lost one village to the north.\n\nA caravan chest with valuable reagents was in that wagon, reagents vital to the studies of the wizards of Nethergarde Keep.  Find the chest and get those reagents, $N.  Get them and bring them to me.",
    isForever = false,
  },
  [1238] = {
    id = 1238,
    title = "The Lost Report",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Object: Loose Dirt",
    objectives = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.",
    rewards = "2,050 XP",
    tip = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.",
    isForever = false,
  },
  [1265] = {
    id = 1265,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 35,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Commander Samaul",
    objectives = "Search Sentry Point for any sign of Private Hendel.",
    rewards = "275 XP",
    tip = "Hendel? Yes, I know the man. But why would you need one of my soldiers?\n\nElling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can.\n\nI believe Hendel was stationed at the first tower outside of Theramore. Be cautious.",
    isForever = false,
  },
  [1219] = {
    id = 1219,
    title = "The Orc Report",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Object: Loose Dirt",
    objectives = "Bring the Spy's Report to a Theramore Lieutenant.",
    rewards = "690 XP",
    tip = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.",
    isForever = false,
  },
  [1239] = {
    id = 1239,
    title = "The Severed Head",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Object: Loose Dirt",
    objectives = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.",
    rewards = "2,050 XP",
    tip = "Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.",
    isForever = false,
  },
  [1147] = {
    id = 1147,
    title = "The Swarm Grows",
    reqLevel = 29,
    questLevel = 35,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Moktar Krin",
    objectives = "- Silithid Searcher x 5 - Silithid Hive Drone x 5 - Silithid Invader x 5",
    rewards = "2,750 XP, 35s",
    tip = "Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.\n\nI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?",
    isForever = false,
  },
  [1202] = {
    id = 1202,
    title = "The Theramore Docks",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Nazeer Bloodpike",
    objectives = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.",
    rewards = "2,750 XP",
    tip = "$N, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.\n\nOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.\n\nThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, $N, and bring them to me.",
    isForever = false,
  },
  [1240] = {
    id = 1240,
    title = "The Troll Witchdoctor",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Nazeer Bloodpike",
    objectives = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.",
    rewards = "2,750 XP",
    tip = "We must know the events surrounding Marg's death!  And the only way to do that, $N, is through the witch-magic of trolls.\n\nBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.\n\nKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.",
    isForever = false,
  },
  [225] = {
    id = 225,
    title = "The Weathered Grave",
    reqLevel = 28,
    questLevel = 35,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Object: A Weathered Grave",
    objectives = "Speak with Sirra Von'Indi in Darkshire.",
    rewards = "690 XP",
    tip = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>",
    isForever = false,
  },
  [1201] = {
    id = 1201,
    title = "Theramore Spies",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Nazeer Bloodpike",
    objectives = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.",
    rewards = "2,750 XP",
    tip = "The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top!\n\nNow is the chance to do just that.\n\nAlliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow.\n\nHunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' prese",
    isForever = false,
  },
  [1282] = {
    id = 1282,
    title = "They Call Him Smiling Jim",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Guard Byron",
    objectives = "Speak with Captain Garran Vimes in Theramore.",
    rewards = "275 XP",
    tip = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.",
    isForever = false,
  },
  [187] = {
    id = 187,
    title = "Tiger Mastery",
    reqLevel = 28,
    questLevel = 35,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Ajeck Rouack",
    objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.",
    rewards = "2,050 XP",
    tip = "Now I'm going to up the stakes on you and truly test your skill.  Prove to me you can kill 10 Elder Stranglethorn Tigers.  If you can do that, you will be ready for your final challenge before I declare you a master tiger hunter in Master Nesingwary's presence.\n\nElder Stranglethorn Tigers are not only the most difficult to find, they are also the fiercest to defeat.",
    isForever = false,
  },
  [7871] = {
    id = 7871,
    title = "Vanquish the Invaders!",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Sentinel Farsong",
    objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
    rewards = "2,750 XP • 1g 10s",
    tip = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.",
    isForever = false,
  },
  [6983] = {
    id = 6983,
    title = "You're a Mean One...",
    reqLevel = 30,
    questLevel = 35,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Strange Snowman",
    objectives = "Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.",
    rewards = "3,300 XP",
    tip = "A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, $N.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!\n\nYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats $N, take them b-b-back to Smokywood Pastures in Orgrimmar, and t-t-tell them I n-n-need to be unfrozen!",
    isForever = false,
  },
  [7043] = {
    id = 7043,
    title = "You're a Mean One...",
    reqLevel = 30,
    questLevel = 35,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Strange Snowman",
    objectives = "- Stolen Treats",
    rewards = "3,300 XP",
    tip = "A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, $N.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!\n\nYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats $N, take them b-b-back to Smokywood Pastures in Ironforge, and t-t-tell them I n-n-need to be unfrozen!",
    isForever = false,
  },
  [6521] = {
    id = 6521,
    title = "An Unholy Alliance",
    reqLevel = 28,
    questLevel = 36,
    faction = "Horde",
    zone = "Razorfen Downs",
    npc = "Varimathras",
    objectives = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.",
    rewards = "3,500 XP • 20s",
    tip = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.\n\nHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.\n\nFind Malcin and slay him, $N. Return to me after the deed is done.",
    isForever = false,
  },
  [6522] = {
    id = 6522,
    title = "An Unholy Alliance",
    reqLevel = 28,
    questLevel = 36,
    faction = "Horde",
    zone = "Razorfen Downs",
    npc = "Item: Small Scroll",
    objectives = "Take the Small Scroll to Varimathras in the Undercity.",
    rewards = "2,800 XP • 40s",
    tip = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin",
    isForever = false,
  },
  [506] = {
    id = 506,
    title = "Blackmoore's Legacy",
    reqLevel = 29,
    questLevel = 36,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Gol'dir",
    objectives = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.",
    rewards = "2,100 XP • 30s",
    tip = "A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.\n\nMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.\n\nNow go, I will make my own way, after I have settled my business here.",
    isForever = false,
  },
  [6161] = {
    id = 6161,
    title = "Claim Rackmore's Treasure!",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Desolace",
    npc = "Object: Rackmore's Log",
    objectives = "Find Rackmore's Silver Key.  Find Rackmore's Golden Key.  Find and open Rackmore's Chest.",
    rewards = "2,800 XP • 1g 15s",
    tip = "Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures.  To prevent his treasure from falling into enemy hands, he hid his chest on Ranazjar Isle.\n\nTo open the chest requires two keys, a silver and a gold.  These keys were lost, but if the keys and the chest are found, a treasure awaits!",
    isForever = false,
  },
  [500] = {
    id = 500,
    title = "Crushridge Bounty",
    reqLevel = 30,
    questLevel = 36,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Marshal Redpath",
    objectives = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains.  Bring them to Marshal Redpath in Southshore.",
    rewards = "3,500 XP • 75s",
    tip = "Crushridge ogres have dug an ogre mound up in the Alterac Mountains near the ruined city of Alterac.  And my scouts tell me they've taken over those ruins as well.\n\nWe can't let them get cozy up there; if they think they're safe where they are, then their next step will be to move down into the foothills, which will put them right at our front door!\n\nGo north to the Alterac Mountains and hunt ogres.  Bring me the Dirty Knucklebones they carry and you will earn a nice bounty.",
    isForever = false,
  },
  [1114] = {
    id = 1114,
    title = "Delivery to the Gnomes",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.",
    rewards = "700 XP • 10s",
    tip = "Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...\n\nAnd I wouldn't bother mentioning it to him.  It was small and worthless.\n\nTrust me.",
    isForever = false,
  },
  [1116] = {
    id = 1116,
    title = "Dream Dust in the Swamp",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Swamp of Sorrows",
    npc = "Krazek",
    objectives = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.",
    rewards = "3,500 XP",
    tip = "Getting the information on Nazz is quite a favor, $N.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?\n\nWhile I contact my sources, why don't you gather something for me, eh?\n\nHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!\n\nGet it for me, $N, and I'll give you the information you seek.",
    isForever = false,
  },
  [1394] = {
    id = 1394,
    title = "Final Passage",
    reqLevel = 25,
    questLevel = 36,
    faction = "Horde",
    zone = "Thousand Needles",
    npc = "Parqual Fintallas",
    objectives = "Speak to Dorn Plainstalker in Thousand Needles.",
    rewards = "4,200 XP",
    tip = "You have done well, $N. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.\n\nStay true to the balance you've shown throughout these trials, $N. Dorn will test you again in the future if you do.",
    isForever = false,
  },
  [503] = {
    id = 503,
    title = "Gol'dir",
    reqLevel = 29,
    questLevel = 36,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Krusk",
    objectives = "Free Gol'dir then return to Krusk in Tarren Mill.",
    rewards = "2,800 XP",
    tip = "From what I can tell of the documents you procured, Gol'dir is being held in a large Syndicate base to the north, most likely in the Alterac Mountains. He has been held captive far too long and must be freed.",
    isForever = false,
  },
  [657] = {
    id = 657,
    title = "Hints of a New Plague?",
    reqLevel = 30,
    questLevel = 36,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Quae",
    objectives = "Speak to Kinelory.",
    rewards = "Experience & Faction Reputation",
    tip = "<Quae begins to go through the folder.>\n\nThis IS interesting. Seems Apothecary Jorell has been working on some deadly experiments here at Go'Shek. Not sure what that has to do with Hillsbrad, but Phin wouldn't like it if we let it continue.\n\nWe had a run-in with some orcs while you were gone, and I'm not in good enough shape to help Kinelory. If you're up for it, she's going to need some protection when she goes down to the farm to steal whatever research Jorell still hasn't sent to Tarren Mill.",
    isForever = false,
  },
  [658] = {
    id = 658,
    title = "Hints of a New Plague?",
    reqLevel = 30,
    questLevel = 36,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Quae",
    objectives = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.",
    rewards = "2,800 XP",
    tip = "So, Phin sent you to check on us? Not surprised--he worries too much.\n\nWe've been watching the farm for days, and Kin claims she saw a courier come out of that small house to the south not long ago.\n\nShe talks a lot, but I can always trust her senses when we're in dangerous areas.\n\nYou wouldn't happen to be a skilled tracker, would you? We think the courier might be carrying notes to Tarren Mill. If we could get our hands on those documents, it might shed some light on what's happening in Hillsb",
    isForever = false,
  },
  [2754] = {
    id = 2754,
    title = "Horns of Frenzy",
    reqLevel = 32,
    questLevel = 36,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Orokk Omosh",
    objectives = "- Solid Iron Maul x 2 - Silvered Bronze Boots x 2 - Silvered Bronze Gauntlets x 2",
    rewards = "2,800 XP",
    tip = "The final lesson Orokk teaches you, $N. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.\n\nSee the fear in their eyes as you approach!",
    isForever = false,
  },
  [213] = {
    id = 213,
    title = "Hostile Takeover",
    reqLevel = 31,
    questLevel = 36,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Kebok",
    objectives = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.",
    rewards = "2,800 XP",
    tip = "He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!\n\nRevilgaz won't have it, and he's told me to take care of the problem in my own way.\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get th",
    isForever = false,
  },
  [1177] = {
    id = 1177,
    title = "Hungry!",
    reqLevel = 32,
    questLevel = 36,
    faction = "Both",
    zone = "Dustwallow Marsh",
    npc = "Mudcrush Durtfeet",
    objectives = "Mudcrush Durtfeet in northern Dustwallow wants 12 Mirefin Heads.",
    rewards = "2,800 XP",
    tip = "Mud big ogre.\n\nMe hungry.\n\nGo bash fishy. Bring Mud food.\n\nYou feed Mud or Mud eat you.",
    isForever = false,
  },
  [2755] = {
    id = 2755,
    title = "Joys of Omosh",
    reqLevel = 32,
    questLevel = 36,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Orokk Omosh",
    objectives = "- Omosh Dance of Joy Learned",
    rewards = "280 XP",
    tip = "Orokk is not crying, $N. Soot is in eye.\n\n<Orokk wipes a tear away.>\n\nThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to $N.\n\nLearn Omosh dance of joy and then you learn fist of iron!",
    isForever = false,
  },
  [512] = {
    id = 512,
    title = "Noble Deaths",
    reqLevel = 26,
    questLevel = 36,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Magistrate Henry Maleb",
    objectives = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.",
    rewards = "2,800 XP • 40s",
    tip = "I fear the leadership behind the Syndicate is bent on Southshore's ruin.  We must strike hard at these leaders before their plans are realized.\n\nEnter the ruins of Strahnbrad, in the Alterac Mountains to the north.  We think the Syndicate is using the area as a headquarters.\n\nWe know this gang of cutthroats is run by former Alterac nobles.  They may be hiding as normal Syndicate agents, but you'll know you've killed a noble by the signet ring he wears.\n\nBring me those signet rings.",
    isForever = false,
  },
  [6143] = {
    id = 6143,
    title = "Other Fish to Fry",
    reqLevel = 32,
    questLevel = 36,
    faction = "Horde",
    zone = "Desolace",
    npc = "Drulzegar Skraghook",
    objectives = "Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.",
    rewards = "2,800 XP • 40s",
    tip = "Maybe you heard or maybe you haven't... my crew and I was out fishing near Ranazjar Isle, north of the wrecked ship off the coast up north. We used to fish there all the time; now all I do is think of a way to seek revenge for my fallen comrades.\n\nThe naga attacked us one morning, killing everyone except me.\n\nMe conscience can't handle the guilt, $c; I need you to go and fry them naga for me. I'll make the effort worth your while; you think you can help me with that?",
    isForever = false,
  },
  [1112] = {
    id = 1112,
    title = "Parts for Kravel",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Wharfmaster Dizzywig",
    objectives = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.",
    rewards = "1,250 XP • 15s",
    tip = "Here's Kravel's package, $N.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!",
    isForever = false,
  },
  [2418] = {
    id = 2418,
    title = "Power Stones",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Azeroth",
    npc = "Rigglefuzz",
    objectives = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",
    rewards = "3,500 XP",
    tip = "A while ago, I had an incident with the Shadowforge Dwarves.  They brought me to Angor Fortress to study two types of strange stones from Uldaman.  I discovered that the stones were sustained, stable power sources if treated correctly.  It's amazing the things one can find in that old dig site!\n\nAnyway, after I told them the secret of the stones they kicked me out of Angor Fortress and began digging for more in Uldaman.\n\nI want those stones for myself!  Bring me both types and I'll pay you plent",
    isForever = false,
  },
  [195] = {
    id = 195,
    title = "Raptor Mastery",
    reqLevel = 28,
    questLevel = 36,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Hemet Nesingwary",
    objectives = "Hemet Nesingwary wants you to kill 10 Lashtail Raptors.",
    rewards = "1,400 XP",
    tip = "Now let's step up the challenge and see if you're up to it.  Venture into the jungle and bag yourself 10 of those bloody Lashtail Raptors.  Let's see what you've got!",
    isForever = false,
  },
  [1117] = {
    id = 1117,
    title = "Rumors for Kravel",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Krazek",
    objectives = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.",
    rewards = "3,500 XP • 75s",
    tip = "I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.\n\nHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.\n\nJust don't tell anyone where you got it!",
    isForever = false,
  },
  [577] = {
    id = 577,
    title = "Some Assembly Required",
    reqLevel = 31,
    questLevel = 36,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Drizzlik",
    objectives = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.",
    rewards = "1,400 XP • 30s",
    tip = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boot",
    isForever = false,
  },
  [1160] = {
    id = 1160,
    title = "Test of Lore",
    reqLevel = 25,
    questLevel = 36,
    faction = "Horde",
    zone = "Scarlet Monastery",
    npc = "Parqual Fintallas",
    objectives = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.",
    rewards = "2,100 XP",
    tip = "I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.\n\nGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.\n\nBring it to me.",
    isForever = false,
  },
  [568] = {
    id = 568,
    title = "The Defense of Grom'gol",
    reqLevel = 33,
    questLevel = 36,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Commander Aggro'gosh",
    objectives = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.",
    rewards = "2,800 XP • 40s",
    tip = "Throm'ka, $c!\n\nYour arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.",
    isForever = false,
  },
  [1266] = {
    id = 1266,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 36,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Archmage Tervosh",
    objectives = "Find Private Hendel in Dustwallow Marsh.",
    rewards = "700 XP",
    tip = "Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders.\n\nYou should have no problem finding him; just look for the tents along the road.\n\nI have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems.",
    isForever = false,
  },
  [1115] = {
    id = 1115,
    title = "The Rumormonger",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Talk to Krazek in Booty Bay.",
    rewards = "1,400 XP",
    tip = "Now that we've done a service for the gnomes, it's time to do the goblins a favor!  \n\nI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.\n\nIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.\n\nIf you can get useful information from him, then we might just turn a profit from",
    isForever = false,
  },
  [1164] = {
    id = 1164,
    title = "To Steal From Thieves",
    reqLevel = 27,
    questLevel = 36,
    faction = "Horde",
    zone = "Undercity",
    npc = "Genavie Callow",
    objectives = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",
    rewards = "2,800 XP",
    tip = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.",
    isForever = false,
  },
  [2753] = {
    id = 2753,
    title = "Trampled Under Foot",
    reqLevel = 32,
    questLevel = 36,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Orokk Omosh",
    objectives = "Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar.",
    rewards = "2,800 XP",
    tip = "Only two more lessons Orokk will teach, $N. Your muscles ache, I know, but continue on for the Omosh!\n\nBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!",
    isForever = false,
  },
  [1111] = {
    id = 1111,
    title = "Wharfmaster Dizzywig",
    reqLevel = 30,
    questLevel = 36,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.",
    rewards = "1,400 XP",
    tip = "I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.\n\nSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.\n\nDo this for me, and I'll have more jobs for you.\n\nJobs, my friend, with serious profit potential...",
    isForever = false,
  },
  [691] = {
    id = 691,
    title = "Worth Its Weight in Gold",
    reqLevel = 30,
    questLevel = 36,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Apprentice Kryten",
    objectives = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.",
    rewards = "3,500 XP",
    tip = "Archmage Malin sent Skuerto and I here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need the following: Witherbark tusks, Witherbark medicine pouches and a shadow hunter knife.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.",
    isForever = false,
  },
  [603] = {
    id = 603,
    title = "Ansirem's Key",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Archmage Ansirem Runeweaver",
    objectives = "Talk to Catelyn in Booty Bay.",
    rewards = "1,400 XP",
    tip = "The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.\n\nAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.\n\nYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate.",
    isForever = false,
  },
  [596] = {
    id = 596,
    title = "Bloody Bone Necklaces",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Kin'weelay",
    objectives = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.",
    rewards = "2,100 XP",
    tip = "I was sent to Grom'gol  to aid Nimboya on his quest, but... I too have reasons for being here.\n\nThe Bloodscalp tribe is enemy to our tribe.  Collecting trophies of our enemies gives us power over them.  You may aid our tribe by hunting our enemies.\n\nThey dwell to the north.  Slay Bloodscalp trolls and take from them their bloody bone necklaces.  Collect many, and your reward will be great.",
    isForever = false,
  },
  [5386] = {
    id = 5386,
    title = "Catch of the Day",
    reqLevel = 32,
    questLevel = 37,
    faction = "Horde",
    zone = "Desolace",
    npc = "Nataka Longhorn",
    objectives = "Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.",
    rewards = "2,100 XP",
    tip = "The smell of cooked fish has long been missing here at Ghost Walker Post. The trolls at Shadowprey Village are the best at catching fish... but alas, with all the centaur activities I have little time to make a journey to the trolls. Hrm...\n\nDo me a favor and journey to Shadowprey Village. Talk to the local fisherman Jinar'Zillen and bring me back my favorite, Bloodbelly fish. The road south of here will take you west to the troll village.",
    isForever = false,
  },
  [4783] = {
    id = 4783,
    title = "Components for the Enchanted Gold Bloodrobe",
    reqLevel = 31,
    questLevel = 37,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.",
    rewards = "2,850 XP",
    tip = "The next components are found in Desolace, far to the west of the Barrens and even the Stonetalon Mountains.\n\nThere, chaos still reigns after the Sundering. Both your strength and cunning will be tested there--you will face creatures of hatred and also of the Burning Legion.\n\nFrom the Hatefury satyr in the northeast, bring me their blood. From the lesser infernals in Mannoroc Coven, bring me a lesser infernal stone.\n\nWe will use both in the construction of your robe.",
    isForever = false,
  },
  [4784] = {
    id = 4784,
    title = "Components for the Enchanted Gold Bloodrobe",
    reqLevel = 31,
    questLevel = 37,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.",
    rewards = "2,100 XP",
    tip = "I need only three things now, $N, then we can finish your robe.\n\nFirst, the fine gold thread Xizk is making for you. Return to him in Booty Bay and get it.\n\nSecond, bring me two smoldering coals from the fire elementals in the Arathi Highlands. If I recall correctly, they are to the west, near Thoradin's Wall.\n\nFinally, a soul shard created by you.\n\nAfter you have all the components, return here to the tower and I will complete the robe for you.",
    isForever = false,
  },
  [713] = {
    id = 713,
    title = "Coolant Heads Prevail",
    reqLevel = 35,
    questLevel = 37,
    faction = "Both",
    zone = "Badlands",
    npc = "Lotwil Veriatus",
    objectives = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.",
    rewards = "2,850 XP",
    tip = "Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it.\n\nIts cooling properties are extraordinary, and its longevity as a lubricant without equal. That's not all: it also aids in retaining enchantments on magical items.\n\nI need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all.\n\nBro'kin, a goblin friend of mine, can teach you to make it. He's in Alterac.",
    isForever = false,
  },
  [1396] = {
    id = 1396,
    title = "Encroaching Wildlife",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Swamp of Sorrows",
    npc = "Watcher Biggs",
    objectives = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.",
    rewards = "2,850 XP",
    tip = "My caravan was destined for the eastern coast, but we did not reach our goal.  Lost Ones attacked us, killing guards and dashing supplies.\n\nI alone survived their assault.  I have sworn to protect what supplies remain, but wild creatures skulk near.  Please, help me defend my camp from the beasts!",
    isForever = false,
  },
  [1714] = {
    id = 1714,
    title = "Essence of the Exile",
    reqLevel = 30,
    questLevel = 37,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Object: Bath'rah's Cauldron",
    objectives = "- Thundering Charm x 8 - Burning Charm x 8 - Cresting Charm x 8",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [3525] = {
    id = 3525,
    title = "Extinguishing the Idol",
    reqLevel = 32,
    questLevel = 37,
    faction = "Both",
    zone = "Razorfen Downs",
    npc = "Belnistrasz",
    objectives = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.\n\nProtect Belnistrasz while he performs the ritual to shut down the idol.",
    rewards = "4,250 XP",
    tip = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.\n\nAre you with me?!",
    isForever = false,
  },
  [627] = {
    id = 627,
    title = "Favor for Krazek",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Krazek",
    objectives = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.",
    rewards = "2,100 XP • 30s",
    tip = "There is a mountain cave in Drywhisker Gorge, far to the north in the Arathi Highlands.  In that cave is rare ore: bloodstone.  The bloodstone in this cave is not of the highest grade, but even low-quality bloodstone is valuable... to those with the knowledge to use it.\n\nI would like some.\n\nI will fix your crock pot, but while I work on it... bring me samples of bloodstone.  Bring me enough, and I'll even give you a bonus.\n\nOh, and if you don't have the skill to mine it... find someone who does!",
    isForever = false,
  },
