  [1136] = {
    id = 1136,
    title = "Frostmaw",
    reqLevel = 26,
    questLevel = 37,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Melor Stonehoof",
    objectives = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.",
    rewards = "4,250 XP",
    tip = "$N, it is now time for you to travel to far-off lands.  You are ready.\n\nYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.\n\nBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.\n\nNow go, $N.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complet",
    isForever = false,
  },
  [1178] = {
    id = 1178,
    title = "Goblin Sponsorship",
    reqLevel = 29,
    questLevel = 37,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Pozzik",
    objectives = "Speak to Gazlowe in Ratchet.",
    rewards = "710 XP",
    tip = "Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.\n\nYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!\n\nA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining o",
    isForever = false,
  },
  [1180] = {
    id = 1180,
    title = "Goblin Sponsorship",
    reqLevel = 29,
    questLevel = 37,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Gazlowe",
    objectives = "Speak with Wharfmaster Lozgil in Booty Bay.",
    rewards = "710 XP",
    tip = "Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.\n\nIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.\n\nCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records.",
    isForever = false,
  },
  [1181] = {
    id = 1181,
    title = "Goblin Sponsorship",
    reqLevel = 29,
    questLevel = 37,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Wharfmaster Lozgil",
    objectives = "Speak with Baron Revilgaz in Booty Bay.",
    rewards = "285 XP",
    tip = "I'm afraid I can't be of much more help to you, $n. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.\n\nYou'll find him at the tavern across the harbor, top floor.",
    isForever = false,
  },
  [1182] = {
    id = 1182,
    title = "Goblin Sponsorship",
    reqLevel = 29,
    questLevel = 37,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Baron Revilgaz",
    objectives = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.",
    rewards = "2,850 XP • 40s",
    tip = "See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.\n\nYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key.",
    isForever = false,
  },
  [1183] = {
    id = 1183,
    title = "Goblin Sponsorship",
    reqLevel = 29,
    questLevel = 37,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Baron Revilgaz",
    objectives = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.",
    rewards = "710 XP",
    tip = "You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!",
    isForever = false,
  },
  [701] = {
    id = 701,
    title = "Guile of the Raptor",
    reqLevel = 29,
    questLevel = 37,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Tor'gan",
    objectives = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.",
    rewards = "2,850 XP",
    tip = "With some additional objects, I will be able to create an item that will imbue Gor'mul with the guile of the raptor! With the power of the raptor flowing through him, Gor'mul will know our new power and rediscover the warrior that lies dormant!\n\nI will require raptor hearts to fashion the item and spell.",
    isForever = false,
  },
  [702] = {
    id = 702,
    title = "Guile of the Raptor",
    reqLevel = 29,
    questLevel = 37,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Tor'gan",
    objectives = "Give Tor'gan's Orb to Gor'mul.",
    rewards = "285 XP",
    tip = "Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.",
    isForever = false,
  },
  [847] = {
    id = 847,
    title = "Guile of the Raptor",
    reqLevel = 29,
    questLevel = 37,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Gor'mul",
    objectives = "Speak with Tor'gan.",
    rewards = "2,850 XP",
    tip = "This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.",
    isForever = false,
  },
  [714] = {
    id = 714,
    title = "Gyro... What?",
    reqLevel = 35,
    questLevel = 37,
    faction = "Both",
    zone = "Badlands",
    npc = "Lotwil Veriatus",
    objectives = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.",
    rewards = "2,850 XP",
    tip = "$N, you've done your job well beyond all standards.\n\n<Lotwil's obviously distracted by his work.>\n\nIf we ever meet in Kharanos, feel free to come apply for work.\n\nWhoops! Quick, grab the... yes, that. Thanks.\n\nNow I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom.\n\nIf you could just go grab one and bring it to me, I should be ready to complete this.",
    isForever = false,
  },
  [582] = {
    id = 582,
    title = "Headhunting",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Nimboya",
    objectives = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.",
    rewards = "2,100 XP",
    tip = "We must find if Yenniku is dead.\n\nSlay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, $N.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north.",
    isForever = false,
  },
  [660] = {
    id = 660,
    title = "Hints of a New Plague?",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Kinelory",
    objectives = "Protect Kinelory until she returns to Quae.",
    rewards = "2,850 XP",
    tip = "All right, $N. I'm ready if you are.\n\nShall we?",
    isForever = false,
  },
  [661] = {
    id = 661,
    title = "Hints of a New Plague?",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Hillsbrad Foothills",
    npc = "Quae",
    objectives = "Find Phin Odelic in Southshore.",
    rewards = "3,550 XP",
    tip = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nThese items she brought back from the farm should at least let Phin get an idea of what's going on out here in Arathi. Just to make sure there's no retaliation after your attack, we're going to stay here for a bit longer. Would you be willing to head back to Southshore and talk to Phin?",
    isForever = false,
  },
  [707] = {
    id = 707,
    title = "Ironband Wants You!",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Prospector Stormpike",
    objectives = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.",
    rewards = "710 XP",
    tip = "$N.  I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations.\n\nI don't have more details than that, but if you want to stretch your legs then go speak with Ironband.",
    isForever = false,
  },
  [1374] = {
    id = 1374,
    title = "Khan Jehn",
    reqLevel = 30,
    questLevel = 37,
    faction = "Both",
    zone = "Desolace",
    npc = "Uthek the Wise",
    objectives = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.",
    rewards = "2,850 XP",
    tip = "The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan!\n\nBring me the head of the Magram Khan, Jehn!",
    isForever = false,
  },
  [1375] = {
    id = 1375,
    title = "Khan Shaka",
    reqLevel = 30,
    questLevel = 37,
    faction = "Both",
    zone = "Desolace",
    npc = "Warug",
    objectives = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.",
    rewards = "2,850 XP",
    tip = "You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!",
    isForever = false,
  },
  [210] = {
    id = 210,
    title = "Krazek's Cookery",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Corporal Kaleb",
    objectives = "Bring Krazek's Crock Pot to Krazek the goblin.",
    rewards = "1,400 XP",
    tip = "I do most of the cooking at the camp.  And it used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant in Booty Bay.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.",
    isForever = false,
  },
  [1269] = {
    id = 1269,
    title = "Lieutenant Paval Reethe",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Object: Theramore Guard Badge",
    objectives = "Bring Reethe's Badge to Krog in Brackenwall Village.",
    rewards = "710 XP",
    tip = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".",
    isForever = false,
  },
  [715] = {
    id = 715,
    title = "Liquid Stone",
    reqLevel = 35,
    questLevel = 37,
    faction = "Both",
    zone = "Badlands",
    npc = "Lucien Tosselwrench",
    objectives = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.",
    rewards = "2,100 XP",
    tip = "I'm thinking those items you acquired for Lotwil are going to be the least of our worries, $N. On the other hand, you've proven more than adept at the sciences Lotwil holds sacred, so how about helping me out?\n\nI need an invisibility potion and a healing potion; both might come in handy real soon if he pulls this off.\n\nIn return, I'll give you this recipe for a potion I've been developing while learning from Lotwil. It's based on some of the research he's been doing here in the Badlands.",
    isForever = false,
  },
  [602] = {
    id = 602,
    title = "Magical Analysis",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Baron Revilgaz",
    objectives = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.",
    rewards = "1,400 XP",
    tip = "From what I've heard, the mages of Dalaran are busy with the reconstruction of their destroyed city, I'm sure you can find one of them who will spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle.\n\nTake the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver in particular.  I've dealt with him before, and his knowledge is vast.",
    isForever = false,
  },
  [1373] = {
    id = 1373,
    title = "Ongeku",
    reqLevel = 30,
    questLevel = 37,
    faction = "Both",
    zone = "Desolace",
    npc = "Uthek the Wise",
    objectives = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.",
    rewards = "2,850 XP",
    tip = "You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you.\n\nThe earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule.\n\nBring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.",
    isForever = false,
  },
  [330] = {
    id = 330,
    title = "Patrol Schedules",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Lieutenant Doren",
    objectives = "Speak with Corporal Sethman.",
    rewards = "285 XP",
    tip = "The note you gave me is signed with an \"-M\"...I don't know what that could mean.\n\nBut...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor!\n\nGo to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen.",
    isForever = false,
  },
  [705] = {
    id = 705,
    title = "Pearl Diving",
    reqLevel = 30,
    questLevel = 37,
    faction = "Both",
    zone = "Badlands",
    npc = "Rigglefuzz",
    objectives = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.",
    rewards = "3,550 XP",
    tip = "The Badlands is a harsh place, filled with vicious predators and bold scavengers.  Scary, especially for a short little goblin.  To survive, I have to be tricky!\n\nI know the recipe for flash bombs.  I use those to scare away wildlife.  But I'm running low on one of the ingredients: crushed blue pearl powder.  Get me some and I'll make it worth your efforts.\n\nHeh, and I hope you have good boots on.  The Blue Pearls I need are found from clams at the Vile Reef.\n\nYep, the Vile Reef in Stranglethorn",
    isForever = false,
  },
  [1273] = {
    id = 1273,
    title = "Questioning Reethe",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Ogron",
    objectives = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.",
    rewards = "3,550 XP",
    tip = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.",
    isForever = false,
  },
  [331] = {
    id = 331,
    title = "Report to Doren",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Corporal Sethman",
    objectives = "Speak with Lieutenant Doren.",
    rewards = "2,850 XP",
    tip = "Did Lieutenant Doren want you to report back to him with that patrol information?",
    isForever = false,
  },
  [622] = {
    id = 622,
    title = "Return to Corporal Kaleb",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Krazek",
    objectives = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.",
    rewards = "2,850 XP",
    tip = "While you were gone I fixed the pot you brought me.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.",
    isForever = false,
  },
  [3523] = {
    id = 3523,
    title = "Scourge of the Downs",
    reqLevel = 32,
    questLevel = 37,
    faction = "Both",
    zone = "Razorfen Downs",
    npc = "Belnistrasz",
    objectives = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.",
    rewards = "285 XP",
    tip = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too m",
    isForever = false,
  },
  [639] = {
    id = 639,
    title = "Sigil of Strom",
    reqLevel = 32,
    questLevel = 37,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Zengu",
    objectives = "Get the Sigil of Strom for Zengu in Hammerfall.",
    rewards = "2,850 XP • 40s",
    tip = "In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.\n\nBut now the sons of Trollbane are weakened, their stronghold brought to ruin.\n\nThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.\n\nThe first was taken by the Syndicate, one of their men in Stromgarde should have it.",
    isForever = false,
  },
  [1222] = {
    id = 1222,
    title = "Stinky's Escape",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "\"Stinky\" Ignatz",
    objectives = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.",
    rewards = "2,850 XP • 40s",
    tip = "Great, finally something that doesn't want to eat me!\n\nI need help handling the critters around here, and you fit the mold, $gbuddy:lady;.\n\nThe cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty.\n\nAnyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?",
    isForever = false,
  },
  [1270] = {
    id = 1270,
    title = "Stinky's Escape",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "\"Stinky\" Ignatz",
    objectives = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.",
    rewards = "2,850 XP • 40s",
    tip = "Great, finally something that doesn't want to eat me!!\n\nI need help handling the critters around here, and you fit the mold, $gbuddy:lady;.\n\nA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.\n\nToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?",
    isForever = false,
  },
  [682] = {
    id = 682,
    title = "Stromgarde Badges",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Captain Nials",
    objectives = "Bring Stromgarde Badges to Captain Nials at Refuge Pointe.",
    rewards = "3,550 XP",
    tip = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.",
    isForever = false,
  },
  [710] = {
    id = 710,
    title = "Study of the Elements: Rock",
    reqLevel = 35,
    questLevel = 37,
    faction = "Both",
    zone = "Badlands",
    npc = "Lotwil Veriatus",
    objectives = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.",
    rewards = "2,850 XP",
    tip = "Here in the Badlands I've stopped to work on my latest project: my shackles of elemental binding.\n\nWhen complete, they will allow mages to summon even more powerful elementals for use in even greater capacities. To start things off, I need small stone shards to test some of my newest offensive spells along with a few gizmos I've pieced together.\n\nThe shards are easily collected from the lesser rock elementals to the west of here. Could you bring me some?",
    isForever = false,
  },
  [1276] = {
    id = 1276,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Krog",
    objectives = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.",
    rewards = "1,400 XP",
    tip = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.",
    isForever = false,
  },
  [1322] = {
    id = 1322,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Do'gol",
    objectives = "Acquire 6 Acidic Venom Sacs for Do'gol in Brackenwall Village.",
    rewards = "2,850 XP",
    tip = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.",
    isForever = false,
  },
  [1323] = {
    id = 1323,
    title = "The Black Shield",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Do'gol",
    objectives = "Talk with Krog in Brackenwall Village.",
    rewards = "1,400 XP",
    tip = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.",
    isForever = false,
  },
  [569] = {
    id = 569,
    title = "The Defense of Grom'gol",
    reqLevel = 33,
    questLevel = 37,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Commander Aggro'gosh",
    objectives = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.",
    rewards = "2,850 XP",
    tip = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm me",
    isForever = false,
  },
  [1186] = {
    id = 1186,
    title = "The Eighteenth Pilot",
    reqLevel = 29,
    questLevel = 37,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Pozzik",
    objectives = "Speak with Razzeric on the Shimmering Flats.",
    rewards = "285 XP",
    tip = "I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.\n\nHe's a little off his rocker, though, so try not to act too surprised.",
    isForever = false,
  },
  [616] = {
    id = 616,
    title = "The Haunted Isle",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Krazek",
    objectives = "Speak with Baron Revilgaz in Booty Bay.",
    rewards = "285 XP",
    tip = "Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say.\n\nIf you're going to go talk to Revilgaz, could you relay that story to him?",
    isForever = false,
  },
  [328] = {
    id = 328,
    title = "The Hidden Key",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Object: Bookie Herod's Records",
    objectives = "Use the Small Brass Key to open Bookie Herod's Strongbox.",
    rewards = "1,400 XP",
    tip = "Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key.\n\nAnd after further study of his notes, a few references to a \"secure strongbox\" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound.\n\nIf this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be reveale",
    isForever = false,
  },
  [642] = {
    id = 642,
    title = "The Princess Trapped",
    reqLevel = 30,
    questLevel = 37,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Object: Shards of Myzrael",
    objectives = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.",
    rewards = "2,850 XP",
    tip = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, $N, aid me!",
    isForever = false,
  },
  [329] = {
    id = 329,
    title = "The Spy Revealed!",
    reqLevel = 30,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Object: Bookie Herod's Strongbox",
    objectives = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.",
    rewards = "1,400 XP",
    tip = "Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M.\n\nBut whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp.",
    isForever = false,
  },
  [578] = {
    id = 578,
    title = "The Stone of the Tides",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Baron Revilgaz",
    objectives = "Find the haunted island for Baron Revilgaz in Booty Bay.",
    rewards = "2,850 XP • 40s",
    tip = "If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine!\n\nI want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in.\n\nCould it be that Gazban actually discovered the Stone...?",
    isForever = false,
  },
  [629] = {
    id = 629,
    title = "The Vile Reef",
    reqLevel = 30,
    questLevel = 37,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Kin'weelay",
    objectives = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.",
    rewards = "2,850 XP",
    tip = "Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the Savage Coast to the northwest.  We call that place the Vile Reef, for murlocs now reside in the ruins of the city, attacking any who draw close.\n\nThere is an old tablet among those ruins that tells the ancient tale of Gri'lek, a hero of troll legends.  The tale is sacred to the Darkspear tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in Orgrimmar.",
    isForever = false,
  },
  [188] = {
    id = 188,
    title = "Tiger Mastery",
    reqLevel = 28,
    questLevel = 37,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Ajeck Rouack",
    objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.",
    rewards = "2,850 XP",
    tip = "Here is the final challenge that I will put forth.  We've been tracking an elusive tiger for weeks.  We call the beast Sin'Dall.  See if you can do what no $r has done before: hunt down and kill Sin'Dall.  Bring me her paw as proof of your accomplishment.\n\nTracking her down will be no easy task.",
    isForever = false,
  },
  [638] = {
    id = 638,
    title = "Trollbane",
    reqLevel = 32,
    questLevel = 37,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Nimboya",
    objectives = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.",
    rewards = "710 XP",
    tip = "With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.\n\nZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.",
    isForever = false,
  },
  [601] = {
    id = 601,
    title = "Water Elementals",
    reqLevel = 32,
    questLevel = 37,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Baron Revilgaz",
    objectives = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.",
    rewards = "2,850 XP • 40s",
    tip = "The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence...\n\nPerhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens.",
    isForever = false,
  },
  [704] = {
    id = 704,
    title = "Agmond's Fate",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Prospector Ironband",
    objectives = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.",
    rewards = "2,850 XP",
    tip = "The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here.\n\nI need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me.",
    isForever = false,
  },
  [522] = {
    id = 522,
    title = "Assassin's Contract",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Item: Assassin's Contract",
    objectives = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.",
    rewards = "710 XP",
    tip = "This is a contract for the assassination of Magistrate Henry Maleb.  It was sealed and stamped in red wax, using a distinctive signet ring.",
    isForever = false,
  },
  [6027] = {
    id = 6027,
    title = "Book of the Ancients",
    reqLevel = 30,
    questLevel = 38,
    faction = "Both",
    zone = "Desolace",
    npc = "Azore Aldamort",
    objectives = "- Book of the Ancients",
    rewards = "3,550 XP, 45s",
    tip = "$n, I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients. This book contains the secrets of the naga, secrets that have been kept for centuries.  Bring this book to me, and we will learn much about our scaled foes!",
    isForever = false,
  },
  [678] = {
    id = 678,
    title = "Call to Arms",
    reqLevel = 30,
    questLevel = 38,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Drum Fel",
    objectives = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.",
    rewards = "2,850 XP",
    tip = "Your strength is evident, $N. Now to see how you fare against a real enemy.\n\nThe Boulderfists have a lair to the southwest of here towards the dwarven bridge, and, if I'm not mistaken, the maulers and magi there shall present to you a greater challenge--they have done so to us thus far.\n\nSlay as many as you can and come to me in body when you are successful, or come to me in spirit when you fail. I shall give praise to your tenacity in battle either way.",
    isForever = false,
  },
  [1049] = {
    id = 1049,
    title = "Compendium of the Fallen",
    reqLevel = 28,
    questLevel = 38,
    faction = "Horde",
    zone = "Scarlet Monastery",
    npc = "Sage Truthseeker",
    objectives = "Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.",
    rewards = "3,550 XP",
    tip = "The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?\n\nThe Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar.\n\nDeep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove u",
    isForever = false,
  },
  [1285] = {
    id = 1285,
    title = "Daelin's Men",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Adjutant Tesoran",
    objectives = "Return the information about Reethe to Captain Garran Vimes in Theramore.",
    rewards = "285 XP",
    tip = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.",
    isForever = false,
  },
  [628] = {
    id = 628,
    title = "Excelsior",
    reqLevel = 31,
    questLevel = 38,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Drizzlik",
    objectives = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.",
    rewards = "2,850 XP",
    tip = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder saltwater crocolisk. The elders only come out to defend the other saltwater crocs, so you might need to kill a few to draw one out.",
    isForever = false,
  },
  [738] = {
    id = 738,
    title = "Find Agmond",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Prospector Ironband",
    objectives = "Find Agmond.",
    rewards = "1,450 XP • 4s",
    tip = "Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest.  I say \"was\" because...well, I haven't heard from him in weeks.  I need you to find Agmond so I can get his report.\n\nLast I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress.  I'd start your search for him there.",
    isForever = false,
  },
  [1393] = {
    id = 1393,
    title = "Galen's Escape",
    reqLevel = 30,
    questLevel = 38,
    faction = "Both",
    zone = "Swamp of Sorrows",
    npc = "Galen Goodward",
    objectives = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.",
    rewards = "2,850 XP",
    tip = "Please help!  These creatures are going to eat me!\n\nHelp me out of here, and I'll give you a great treasure!  It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know.\n\nIf you help me escape, then I'll teach it to you.",
    isForever = false,
  },
  [5943] = {
    id = 5943,
    title = "Gizelton Caravan",
    reqLevel = 32,
    questLevel = 38,
    faction = "Both",
    zone = "Desolace",
    npc = "Rigger Gizelton",
    objectives = "Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.",
    rewards = "2,850 XP",
    tip = "You look like a capable $r. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!\n\nUp ahead is Mannoroc Coven... normally the demons ignore us but something has the kodos spooked this time. I'll pay you to protect the caravan past Mannoroc Coven. Once we are safely past you can receive your reward from our business associate Smeed at Scrabblescrew's Camp.",
    isForever = false,
  },
  [5381] = {
    id = 5381,
    title = "Hand of Iruxos",
    reqLevel = 32,
    questLevel = 38,
    faction = "Horde",
    zone = "Desolace",
    npc = "Taiga Wisemane",
    objectives = "- Demon Box",
    rewards = "2,850 XP, 45s",
    tip = "The Burning Blade possesses the Demon Box. Within it lies the powerful Hand of Iruxos. The Burning Blade uses it to open demonic portals at Mannoroc Coven. We must stop the tide of demons entering our world, $n!\n\nUse this demon pick on the red crystal in Thunder Axe Fortress to gain access to the Demon Box.",
    isForever = false,
  },
  [1949] = {
    id = 1949,
    title = "Hidden Secrets",
    reqLevel = 30,
    questLevel = 38,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Tabetha",
    objectives = "Speak with Magus Tirth in the Shimmering Flats.",
    rewards = "1,450 XP",
    tip = "To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.\n\nI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.\n\nGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.",
    isForever = false,
  },
  [1947] = {
    id = 1947,
    title = "Journey to the Marsh",
    reqLevel = 30,
    questLevel = 38,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Ursyn Ghull",
    objectives = "Speak with Tabetha.",
    rewards = "285 XP",
    tip = "Now it is time for you to earn your mage's wand.  To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh.  You will find her shack deep in the marsh, west of Theramore.\n\nSpeak with her, for her knowledge is vast.  You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins.",
    isForever = false,
  },
  [207] = {
    id = 207,
    title = "Kurzen's Mystery",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Brother Nimetz",
    objectives = "Find the 4 tablets and bring their legends back to Brother Nimetz.",
    rewards = "3,550 XP",
    tip = "Colonel Kurzen was once a great, noble man - I must find what caused his fall into depravity!  He may be under the sway of troll magic.  To confirm this, I must study some of their legends.\n\nThere are 4 tablets hidden within the troll ruins of Stranglethorn.  I must see what is written on these tablets!  Transcribe their markings and bring the transcriptions back to me.\n\nThe first tablet is in the Bal'lal Ruins, the second is in the Vile Reef, and the third and fourth are in the Ruins of Zul'Kun",
    isForever = false,
  },
  [718] = {
    id = 718,
    title = "Mirages",
    reqLevel = 35,
    questLevel = 38,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Sigrun Ironhew",
    objectives = "Retrieve the Supply Crate for Sigrun Ironhew.",
    rewards = "2,150 XP",
    tip = "In our hurry to leave the Uldaman excavation site, we were forced to abandon many wagons and crates of supplies along the way. The local ogres from Camp Kosh have been on our abandoned equipment like vultures on a rotting corpse. Don't smell much better, either. Than the corpses, I mean.\n\nAnyways, they took the cart that was carrying all our weapons and such... so--well, this is a bit embarrassing--we haven't been able to get any food.\n\nWe're in a bit of a pickle here, suppose you could help us ",
    isForever = false,
  },
  [570] = {
    id = 570,
    title = "Mok'thardin's Enchantment",
    reqLevel = 33,
    questLevel = 38,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Far Seer Mok'thardin",
    objectives = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.",
    rewards = "2,150 XP",
    tip = "The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave $c, I shall make a special item indeed.\n\nBring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition.\n\nThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.",
    isForever = false,
  },
  [1260] = {
    id = 1260,
    title = "Morgan Stern",
    reqLevel = 33,
    questLevel = 38,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Angus Stern",
    objectives = "Speak with Morgan Stern in Theramore.",
    rewards = "710 XP",
    tip = "I'm developing a new menu for the restaurant.  It will be filled with rural dishes with a \"bayou\" theme.  I think my clientele at the Blue Recluse will love them!\n\nI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh.  He's there gathering recipes from the locals, and I must know what he found so far.\n\nThe trip to Theramore is long.  Too long for me.  But I bet a young $c like yourself would jump at the chance to travel, yes?",
    isForever = false,
  },
  [1204] = {
    id = 1204,
    title = "Mudrock Soup and Bugs",
    reqLevel = 33,
    questLevel = 38,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Morgan Stern",
    objectives = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.",
    rewards = "2,850 XP",
    tip = "I'm working on a dish I call \"Mudrock Soup and Bugs.\"  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh!\n\nSo, $N, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay.\n\nBut I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked...\n\nThey say the forked tongues have a distinct flavor, and I want that flavor in my dish...",
    isForever = false,
  },
  [1050] = {
    id = 1050,
    title = "Mythology of the Titans",
    reqLevel = 28,
    questLevel = 38,
    faction = "Alliance",
    zone = "Scarlet Monastery",
    npc = "Librarian Mae Paledust",
    objectives = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",
    rewards = "3,550 XP",
    tip = "The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea.\n\nBut perhaps, by studying the past, we can know what to expect and be better prepared for the unknown.\n\nBefore dire troubles fell upon Lordaeron, there was a bastion of knowledge tucked away in the Tirisfal Glades. It is rumored that a book called Mythology of the Titans was housed in the library of the old Monastery.\n\nBring it to me and perhaps together we can unlock the secrets of the past!",
    isForever = false,
  },
  [1137] = {
    id = 1137,
    title = "News for Fizzle",
    reqLevel = 28,
    questLevel = 38,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Martek the Exiled",
    objectives = "Speak with Fizzle Brassbolts in the Shimmering Flats.",
    rewards = "1,450 XP",
    tip = "Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.\n\nTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.\n\nSend Fizzle Brassbolts my regards, and tell him what I told you.\n\nSafe travels, $N.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!",
    isForever = false,
  },
  [192] = {
    id = 192,
    title = "Panther Mastery",
    reqLevel = 28,
    questLevel = 38,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Sir S. J. Erlgadin",
    objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.",
    rewards = "2,150 XP",
    tip = "Now the hard part.  A true panther hunter can show skill by dropping Shadowmaw Panthers, the deadliest in Stranglethorn.  Prove to us that you can slay 10 of these beasts.\n\nIf you think they are hard to track, wait until you attempt to slay one....",
    isForever = false,
  },
  [5581] = {
    id = 5581,
    title = "Portals of the Legion",
    reqLevel = 32,
    questLevel = 38,
    faction = "Horde",
    zone = "Desolace",
    npc = "Taiga Wisemane",
    objectives = "- Portals Banished x 6",
    rewards = "3,550 XP, 45s",
    tip = "Behold - the Hand of Iruxos. A gruesome sight indeed.\n\nYou must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do. The Demon threat is increasing and we must close these portals to stem the tide of demons to this world. Good luck, $N... and be wary of the portal guardians.",
    isForever = false,
  },
  [540] = {
    id = 540,
    title = "Preserving Knowledge",
    reqLevel = 20,
    questLevel = 38,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Loremaster Dibbs",
    objectives = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.",
    rewards = "3,550 XP",
    tip = "Those beastly ogres now reside within Alterac's ruins, and I shudder to think what they're doing with the precious books still there.  You must recover what you can!\n\nEnter the Ruins of Alterac and search for tomes looted by the ogres.  Get whatever you can find and bring them to me, but also seek out one book in particular: The Arm of Gri'lek.  It contains ancient troll lore that I must learn, and the Ruins of Alterac was the last known location of an intact copy of this book.",
    isForever = false,
  },
  [542] = {
    id = 542,
    title = "Return to Milton",
    reqLevel = 20,
    questLevel = 38,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Loremaster Dibbs",
    objectives = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.",
    rewards = "3,550 XP • 85s",
    tip = "I need to spend some time studying the Arm of Gri'lek book you brought me, though I'm sure Milton is eager to get the other recovered books into Stormwind's collection.\n\nHere are the books you gathered from the Ruins of Alterac, packed and catalogued.  Take them back to Milton Sheaf in Stormwind and I'm sure he'll be grateful.",
    isForever = false,
  },
  [538] = {
    id = 538,
    title = "Southshore",
    reqLevel = 20,
    questLevel = 38,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Milton Sheaf",
    objectives = "Speak with Loremaster Dibbs in Southshore.",
    rewards = "710 XP",
    tip = "$N.  If you don't mind a long journey then I have a task for you, to again help Stormwind fill its library.\n\nThe old kingdom of Alterac fell after the great war, and it had a large collection of books.  It's a tragedy that the city is ruined, but even more tragic is all of their knowledge lost!  We must recover what we can.\n\nSouthshore is the closest town to the Ruins of Alterac.  Go there and speak with Loremaster Dibbs.  He can direct you to the ruins, and to what books may be found there.",
    isForever = false,
  },
  [574] = {
    id = 574,
    title = "Special Forces",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Sergeant Yohwa",
    objectives = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.\n\nReport to Lieutenant Doren at the Rebel Camp.",
    rewards = "2,850 XP",
    tip = "Now that many of his regular troops are reduced, you must face his highly trained forces.  When they're not in the wilderness slaughtering our rebel soldiers, they are found deep in the back of the Kurzen Compound, in a cave they call the Stockpile.\n\nI know many of Kurzen's troops personally, and I know they are skilled, loyal, and cruel.  This is no easy task I set before you, $N.\n\nAfter you defeat them, report to Lieutenant Doren, my commanding officer.  He will want your report firsthand.",
    isForever = false,
  },
  [651] = {
    id = 651,
    title = "Stones of Binding",
    reqLevel = 30,
    questLevel = 38,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Object: Iridescent Shards",
    objectives = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.\n\nBring them to the Stone of Inner Binding.",
    rewards = "2,850 XP",
    tip = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.",
    isForever = false,
  },
  [4786] = {
    id = 4786,
    title = "The Completed Robe",
    reqLevel = 31,
    questLevel = 38,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Wait for Menara Voidrender to complete your robe and then speak to her again.",
    rewards = "3,550 XP",
    tip = "I will put the robe together for you now. It will take but a few moments. Do not go far.",
    isForever = false,
  },
  [1286] = {
    id = 1286,
    title = "The Deserters",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Captain Garran Vimes",
    objectives = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.",
    rewards = "2,850 XP",
    tip = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, $n. He may be a tough nut to crack.",
    isForever = false,
  },
  [1287] = {
    id = 1287,
    title = "The Deserters",
    reqLevel = 30,
    questLevel = 38,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Balos Jacken",
    objectives = "Speak with Captain Garran Vimes in Theramore about Reethe.",
    rewards = "2,850 XP",
    tip = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?",
    isForever = false,
  },
  [1267] = {
    id = 1267,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 38,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Lady Jaina Proudmoore",
    objectives = "Speak to Jaina Proudmore in Dustwallow Swamp.",
    rewards = "4,300 XP • 1g 30s",
    tip = "",
    isForever = false,
  },
  [1324] = {
    id = 1324,
    title = "The Missing Diplomat",
    reqLevel = 28,
    questLevel = 38,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Private Hendel",
    objectives = "Defeat Private Hendel in Dustwallow Marsh.",
    rewards = "2,150 XP",
    tip = "What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time.",
    isForever = false,
  },
  [610] = {
    id = 610,
    title = "\"Pretty Boy\" Duncan",
    reqLevel = 32,
    questLevel = 39,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Catelyn the Blade",
    objectives = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.",
    rewards = "2,250 XP",
    tip = "My FATHER sent you? I'd have thought that old codger would have given up on me by now.\n\nIt wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages!\n\nIf you need my dagger, you'll have to get it back from \"Pretty Boy\" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up.",
    isForever = false,
  },
  [695] = {
    id = 695,
    title = "An Apprentice's Enchantment",
    reqLevel = 30,
    questLevel = 39,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Apprentice Kryten",
    objectives = "Speak to Skuerto.",
    rewards = "300 XP",
    tip = "Here you are, $N. The gem only needs to be pressed against one of the pedestals near the base of the tower to activate its defenses. Use it when you're ready to enter the tower and find Trelane's remaining items. \n\nGood luck to you. I'll be awaiting your return here at the camp. Oh, and speak to Skuerto before you leave. He'll give you the rest of the details you'll need.",
    isForever = false,
  },
  [696] = {
    id = 696,
    title = "Attack on the Tower",
    reqLevel = 30,
    questLevel = 39,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Skuerto",
    objectives = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.",
    rewards = "3,000 XP",
    tip = "Here's what your lookin' for: Trelane's phylactery, Trelane's orb, an' Trelane's ember agate.\n\nAll three should be in chests within the tower an' you shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nThe tower's defenses won't take care of 'em on their own; you'll need to have your weapons at the ready. Those ogres find out you're there and stealing from 'em, an' they'll be sure to put the hurt on you.\n\nBe careful, an' good luck.",
    isForever = false,
  },
  [2258] = {
    id = 2258,
    title = "Badlands Reagent Run",
    reqLevel = 36,
    questLevel = 39,
    faction = "Horde",
    zone = "Badlands",
    npc = "Jarkal Mossmeld",
    objectives = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.",
    rewards = "3,000 XP • 45s",
    tip = "$N, I could use your aid if you're up for it.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.  Watcha wanna do?",
    isForever = false,
  },
  [2500] = {
    id = 2500,
    title = "Badlands Reagent Run",
    reqLevel = 36,
    questLevel = 39,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Ghak Healtouch",
    objectives = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.",
    rewards = "3,000 XP • 45s",
    tip = "$C, I would make use of your services.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.\n\nWell, what say ye?",
    isForever = false,
  },
  [8427] = {
    id = 8427,
    title = "Battle of Warsong Gulch",
    reqLevel = 30,
    questLevel = 39,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "3,000 XP • 45s",
    tip = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!",
    isForever = false,
  },
  [8432] = {
