  [8400] = {
    id = 8400,
    title = "Fight for Warsong Gulch",
    reqLevel = 30,
    questLevel = 39,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "3,000 XP • 45s",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
    isForever = false,
  },
  [8405] = {
    id = 8405,
    title = "Fight for Warsong Gulch",
    reqLevel = 30,
    questLevel = 39,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "1,500 XP",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest. There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack. Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N! For the Alliance!",
    isForever = false,
  },
  [6132] = {
    id = 6132,
    title = "Get Me Out of Here!",
    reqLevel = 34,
    questLevel = 39,
    faction = "Both",
    zone = "Desolace",
    npc = "Melizza Brimbuzzle",
    objectives = "Escort Melizza Brimbuzzle, then speak with Hornizz Brimbuzzle at the Kodo Graveyard in Desolace.",
    rewards = "2,250 XP • 45s",
    tip = "Get me out of here!\n\nI came up to the Valley of Spears to talk to the Maraudines.  I thought I could do a little business with them... but they don't want to talk!  I think they want to eat me!\n\nGet me out of here and my brother Hornizz will pay you big!  He's at our camp next to the kodo graveyard, to the east.\n\nLet's hurry, $N.  Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...",
    isForever = false,
  },
  [6134] = {
    id = 6134,
    title = "Ghost-o-plasm Round Up",
    reqLevel = 34,
    questLevel = 39,
    faction = "Both",
    zone = "Desolace",
    npc = "Hornizz Brimbuzzle",
    objectives = "Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.",
    rewards = "2,250 XP • 45s",
    tip = "There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts.  Sounds scary, doesn't it?  Well think how scary it is to the Magram!  If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs.\n\nHere, take this crate of ghost magnets.  If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it.  Distance yourself, take out the ghosts and get their ghost-o-plasm--that's what we'll sell to the Mag",
    isForever = false,
  },
  [1108] = {
    id = 1108,
    title = "Indurium",
    reqLevel = 28,
    questLevel = 39,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Martek the Exiled",
    objectives = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.",
    rewards = "3,000 XP",
    tip = "I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, $N, if you have the guts to get it.\n\nThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.\n\nBut let's make sure.  Get me samples of indurium and I'll test its properties.\n\nTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flake",
    isForever = false,
  },
  [697] = {
    id = 697,
    title = "Malin's Request",
    reqLevel = 30,
    questLevel = 39,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Skuerto",
    objectives = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.",
    rewards = "3,750 XP • 90s",
    tip = "Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, $N, of that I've no doubt.\n\nTravel safely.",
    isForever = false,
  },
  [1392] = {
    id = 1392,
    title = "Noboru the Cudgel",
    reqLevel = 29,
    questLevel = 39,
    faction = "Both",
    zone = "Swamp of Sorrows",
    npc = "Item: Noboru's Cudgel",
    objectives = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.",
    rewards = "2,250 XP",
    tip = "Noboru has plagued the Draenei of the Harborage for months, and his cudgel is a symbol of the brutality they have suffered at the hands of the lost ones.",
    isForever = false,
  },
  [8266] = {
    id = 8266,
    title = "Ribbons of Sacrifice",
    reqLevel = 10,
    questLevel = 39,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Sentinel Farsong",
    objectives = "Bring the Ribbons of Sacrifice to Sentinel Farsong so that the Sentinels may reward you for acting on our behalf.",
    rewards = "660 XP",
    tip = "I understand that it can be difficult at times to come out on top in Warsong Gulch. Still, your effort on our behalf - even when victory is not achieved - is important.\n\nShould you complete one of the trials inside Warsong Gulch and not achieve victory, you will still receive a Ribbons of Sacrifice. Bring it to me so that the Outriders may reward you for acting on our behalf... even if you weren't able to win this time.",
    isForever = false,
  },
  [8268] = {
