  },
  [339] = {
    id = 339,
    title = "Chapter I",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Barnil Stonepot",
    objectives = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.",
    rewards = "780 XP",
    tip = "Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me! \n\nBut that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!",
    isForever = false,
  },
  [340] = {
    id = 340,
    title = "Chapter II",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Barnil Stonepot",
    objectives = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.",
    rewards = "780 XP",
    tip = "Chapter II was chock full of exciting tales of panther and tiger hunting.  I could just kick myself for letting the pages blow away! \n\n It seems I was able to recover all of the pages with the exception of pages 10, 11, 14, and 16.",
    isForever = false,
  },
  [341] = {
    id = 341,
    title = "Chapter III",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Barnil Stonepot",
    objectives = "Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.",
    rewards = "780 XP",
    tip = "Chapter III was my favorite.  It tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.  And the end of Chapter III, why, such a cliffhanger!  \n\nLooks to me as though we still need pages 18, 20, 21 and 24 to finish the chapter.  Those pages are out there somewhere. . .",
    isForever = false,
  },
  [342] = {
    id = 342,
    title = "Chapter IV",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Barnil Stonepot",
    objectives = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.",
    rewards = "780 XP",
    tip = "Ah Chapter IV; the big finale!  And what an ending it was! \n\nWe are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together.",
    isForever = false,
  },
  [4961] = {
    id = 4961,
    title = "Cleansing of the Orb of Orahil",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Tabetha",
    objectives = "Kill the Demon of the Orb, then speak with Tabetha.",
    rewards = "2,350 XP",
    tip = "Ah, a summoner's orb--this is where the taint must be coming from. We must exorcise the demon within it if you're to use it. That I can do easily.\n\nYou're the one who has the hard job.  You must kill the demon once I release it.\n\nAnd you'll have to be quick.  If you take too long then he'll return to the orb and we'll have to start over!\n\nSo get yourself ready, $N.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pre",
    isForever = false,
  },
  [202] = {
    id = 202,
    title = "Colonel Kurzen",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Lieutenant Doren",
    objectives = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.",
    rewards = "3,150 XP",
    tip = "You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself.  You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!\n\nHe commands his men from deep within the Stockpile.  You must enter that cave, brave through his defenders, and face Kurzen and his leaders.\n\nFarewell, $N.  My hope, and the fate of my men, go with you.",
    isForever = false,
  },
  [1419] = {
    id = 1419,
    title = "Coyote Thieves",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Badlands",
    npc = "Neeka Bloodscar",
    objectives = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.",
    rewards = "3,150 XP",
    tip = "Have you spent many days in the Badlands, $c?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It's time you did.\n\nCrag coyotes are a tough breed.  Tough, and bold enough to creep into Kargath and steal from our food supplies.  Help rid the outpost of these thieves!\n\nHunt crag coyotes, $N.  Hunt them and bring me their jawbones.  Bring me enough, and maybe I'll believe it when you say you know the Badlands.",
    isForever = false,
  },
  [504] = {
    id = 504,
    title = "Crushridge Warmongers",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Marshal Redpath",
    objectives = "Slay 15 Crushridge Warmongers, then return to Marshal Redpath in Southshore.",
    rewards = "4,700 XP",
    tip = "Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses...\n\nGo into the Ruins of Alterac and seek out the Crushridge Warmongers.  I want you to cut down a good number of them - that's the only way those brutes will learn to keep their distance from Alliance territory.",
    isForever = false,
  },
  [1712] = {
    id = 1712,
    title = "Cyclonian",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Bath'rah the Windwatcher",
    objectives = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.",
    rewards = "2,350 XP",
    tip = "I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord.\n\nPerhaps you are that champion.\n\nProve it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart.\n\nIf so, then I will infuse the heart's power in a weapon, and I will give that weapon to you.\n\nHere is a parchment with the items I need.",
    isForever = false,
  },
  [537] = {
    id = 537,
    title = "Dark Council",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Magistrate Henry Maleb",
    objectives = "Kill 4 Argus Shadow Mages.\n\nBring the Head of Nagaz to Magistrate Maleb in Southshore.",
    rewards = "3,150 XP • 50s",
    tip = "The letter you brought me was written by a being who calls himself Nagaz, a member of the Argus Wake.  I don't know what this Argus Wake is, but if they're in alliance with the Syndicate then they must be a threat.\n\nI want you to find Nagaz and the Argus Shadow Mages mentioned in that letter.  I want you to find them, and kill them.\n\nSearch in the Uplands, where the Syndicate is strongest.  It is north of Strahnbrad.\n\nWith luck, you'll find these envoys of the Argus Wake there.",
    isForever = false,
  },
  [662] = {
    id = 662,
    title = "Deep Sea Salvage",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "First Mate Nilzlix",
    objectives = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.",
    rewards = "3,150 XP",
    tip = "O'Breen led the ships into the cove.  We were certain this is where the treasure could be found.  The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower.  Strangest thing I've ever seen!\n\nThose two ships ran aground into something... some sort of temple in the reef.  They sank so quickly, was quite a tragedy.\n\nWe need to retrieve their Logs as well as their Charts before we leave.  We can't leave that information behind for prying eyes!",
    isForever = false,
  },
  [1052] = {
    id = 1052,
    title = "Down the Scarlet Path",
    reqLevel = 34,
    questLevel = 40,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Brother Anton",
    objectives = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.",
    rewards = "1,550 XP",
    tip = "We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron.\n\nYou have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron.\n\nTravel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery.",
    isForever = false,
  },
  [664] = {
    id = 664,
    title = "Drowned Sorrows",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Captain Steelgut",
    objectives = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.",
    rewards = "3,150 XP",
    tip = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.",
    isForever = false,
  },
  [737] = {
    id = 737,
    title = "Forbidden Knowledge",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Badlands",
    npc = "Gerrig Bonegrip",
    objectives = "Bring Yagyin's Digest to Theldurin.",
    rewards = "2,350 XP",
    tip = "I have the digest for you, $N.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.  \n\nThis book holds many truths...\n\n...And the truth can burn.",
    isForever = false,
  },
  [673] = {
    id = 673,
    title = "Foul Magics",
    reqLevel = 35,
    questLevel = 40,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Tor'gan",
    objectives = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.",
    rewards = "3,150 XP",
    tip = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy.\n\nFind the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.",
    isForever = false,
  },
  [1799] = {
    id = 1799,
    title = "Fragments of the Orb of Orahil",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.\n\nAfterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh.",
    rewards = "3,150 XP",
    tip = "Good, then we shall begin.\n\nThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.\n\nSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.\n\nAgain, do not come back until you have done both things I've asked.",
    isForever = false,
  },
  [2759] = {
    id = 2759,
    title = "In Search of Galvan",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Blacksmithing",
    npc = "Hank the Hammer",
    objectives = "Speak with McGavan in Booty Bay.",
    rewards = "1,550 XP",
    tip = "Although Galvan left Booty Bay many years ago, members of the order still remain in town, hoping to one day find another worthy of Galvan's tutelage.\n\nTake this insignia and present it to McGavan in Booty Bay.\n\nIf you actually make it that far, he'll know that you are worthy. I have faith, $N!",
    isForever = false,
  },
  [1053] = {
    id = 1053,
    title = "In the Name of the Light",
    reqLevel = 34,
    questLevel = 40,
    faction = "Alliance",
    zone = "Scarlet Monastery",
    npc = "Raleigh the Devout",
    objectives = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.",
    rewards = "4,700 XP",
    tip = "I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.\n\nBut as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued. \n\nThe Scarlet Crusade must be crushed in the name of the Light. You, $n, must destroy the deranged ",
    isForever = false,
  },
  [1948] = {
    id = 1948,
    title = "Items of Power",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Tabetha",
    objectives = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.",
    rewards = "3,150 XP",
    tip = "The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.\n\nI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly.",
    isForever = false,
  },
  [698] = {
    id = 698,
    title = "Lack of Surplus",
    reqLevel = 35,
    questLevel = 40,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Dar",
    objectives = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.",
    rewards = "3,150 XP",
    tip = "I'm working on getting some supplies together for our outpost near the beach to the east--Tok'kar does what he can, but between shifts of guard duty and cooking for his soldiers there's not much time left in the day.\n\nThey do enjoy cooking up some sawtooth meat when they can, but I haven't had time to get them another shipment. Would you mind helping them out?\n\nThe young sawtooths aren't as tasty as the older ones, so stay clear of those; give them a year or two to get to full size.",
    isForever = false,
  },
  [1252] = {
    id = 1252,
    title = "Lieutenant Paval Reethe",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Object: Theramore Guard Badge",
    objectives = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.",
    rewards = "780 XP",
    tip = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".",
    isForever = false,
  },
  [1259] = {
    id = 1259,
    title = "Lieutenant Paval Reethe",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Dustwallow Marsh",
    npc = "Captain Garran Vimes",
    objectives = "Find out more about Reethe from Adjutant Tesoran in Theramore.",
    rewards = "315 XP",
    tip = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.",
    isForever = false,
  },
  [1952] = {
    id = 1952,
    title = "Mage's Wand",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Tabetha",
    objectives = "Speak with Tabetha after her ritual.",
    rewards = "3,150 XP",
    tip = "I'll go make the wands now.",
    isForever = false,
  },
  [1957] = {
    id = 1957,
    title = "Mana Surges",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Tabetha",
    objectives = "Kill 12 Mana Surges in the allowed time limit.",
    rewards = "2,350 XP",
    tip = "We are almost finished, but this last step is the most perilous, $N.\n\nI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.\n\nKill enough mana surges before the rift closes and I will place all their collected energy in your orb.",
    isForever = false,
  },
  [1261] = {
    id = 1261,
    title = "Marg Speaks",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Object: Bubbling Cauldron",
    objectives = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.",
    rewards = "3,150 XP",
    tip = "Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...\n\nBut my mission!  My mission!  You, $N, must complete it.\n\nWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!\n\nThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!\n\n$N, you must find that muckshell and recover the pendant!",
    isForever = false,
  },
  [653] = {
    id = 653,
    title = "Myzrael's Allies",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Object: Keystone",
    objectives = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
    rewards = "2,350 XP",
    tip = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface.\n\nSpeak with Gerrig Bonegrip.  He is in Ironforge, in a shop of the Forlorn Cavern.  He knows how I can be summoned.",
    isForever = false,
  },
  [688] = {
    id = 688,
    title = "Myzrael's Allies",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Object: Keystone",
    objectives = "Speak with Zaruk in Hammerfall.",
    rewards = "2,350 XP",
    tip = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface\n\nSpeak with Zaruk in Hammerfall.  He knows how I can be summoned.",
    isForever = false,
  },
  [193] = {
    id = 193,
    title = "Panther Mastery",
    reqLevel = 28,
    questLevel = 40,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Sir S. J. Erlgadin",
    objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.",
    rewards = "3,150 XP",
    tip = "You've almost proven yourself to be a master hunter of panthers.  A panther by the name of Bhag'thera has been prowling the jungle.  So far he's eluded our party.  See if you can use your skills to kill the great Bhag'thera.\n\nBring me the Fang of Bhag'thera and you'll have earned my respect!",
    isForever = false,
  },
  [725] = {
    id = 725,
    title = "Passing Word of a Threat",
    reqLevel = 35,
    questLevel = 40,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Historian Karnik",
    objectives = "Find Advisor Belgrum and give him his note.",
    rewards = "1,550 XP",
    tip = "$N, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.\n\nIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray.",
    isForever = false,
  },
  [726] = {
    id = 726,
    title = "Passing Word of a Threat",
    reqLevel = 35,
    questLevel = 40,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Advisor Belgrum",
    objectives = "Speak to Historian Karnik.",
    rewards = "2,350 XP",
    tip = "<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>\n\nOch, these are evil tidings.\n\n$N, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.",
    isForever = false,
  },
  [1956] = {
    id = 1956,
    title = "Power in Uldaman",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Tabetha",
    objectives = "Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.",
    rewards = "3,900 XP",
    tip = "Now that the demon has been removed, we must gain a power source.  Unfortunately, the best power sources are usually the oldest and the hardest to get.  It's neat how fate likes to take a bite out of you sometimes, isn't it?\n\nSo you're going to need to go to Uldaman and defeat the obsidian sentinel there.  He's big, he's tough, and his power source packs a punch!\n\nI wish you the best of luck, $N.  And if you don't get lucky then, well... it was nice knowing you.",
    isForever = false,
  },
  [723] = {
    id = 723,
    title = "Prospect of Faith",
    reqLevel = 35,
    questLevel = 40,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Hammertoe Grez",
    objectives = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.",
    rewards = "2,350 XP",
    tip = "<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>\n\nFind Ryedol, $N. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>",
    isForever = false,
  },
  [724] = {
    id = 724,
    title = "Prospect of Faith",
    reqLevel = 35,
    questLevel = 40,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Prospector Ryedol",
    objectives = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.",
    rewards = "3,150 XP",
    tip = "Okay, okay... who would know what to do?\n\nHistorian Karnik! That's it!\n\nHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.\n\nGuess the Shadowforge found out the two of them knew more than they were lettin' on.\n\nTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next.",
    isForever = false,
  },
  [1466] = {
    id = 1466,
    title = "Reagents for Reclaimers Inc.",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Kreldig Ungor",
    objectives = "Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.",
    rewards = "3,150 XP • 35s",
    tip = "This is the last of the items, and I won't lie, it ain't pretty. I'm also expecting this to take you a little bit longer than the other items.\n\nSo, enough with the warning, let's get this started. Leftwitch says he needs: ten brains from either mana eaters, mage hunters, or ley hunters. Ten nether wings from a nether maiden, sister or sorceress. And... ten vials of doomwarder blood from a doomwarder captain, or lord.\n\nSimple enough, huh? Sheesh... if you wanna pass on this one, I'd understand.",
    isForever = false,
  },
  [1467] = {
    id = 1467,
    title = "Reagents for Reclaimers Inc.",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Desolace",
    npc = "Kreldig Ungor",
    objectives = "Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.",
    rewards = "3,150 XP • 35s",
    tip = "To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway. Just give him this and it should be enough to get your booty.\n\nAnd don't worry, I'm still going to put in a good word for you when I get back. I shouldn't be in Desolace much longer.",
    isForever = false,
  },
  [1420] = {
    id = 1420,
    title = "Report to Helgrum",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Badlands",
    npc = "Neeka Bloodscar",
    objectives = "Bring Neeka's Report to Helgrum the Swift in Stonard.",
    rewards = "2,350 XP",
    tip = "I wrote a fresh report for Helgrum in Stonard.  Bring it to him.\n\nAnd if you consider yourself an outrunner, then don't lose your way.  Or fall to an enemy.",
    isForever = false,
  },
  [1262] = {
    id = 1262,
    title = "Report to Zor",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Nazeer Bloodpike",
    objectives = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.",
    rewards = "3,150 XP",
    tip = "It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!\n\nRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.\n\nTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.",
    isForever = false,
  },
  [1953] = {
    id = 1953,
    title = "Return to the Marsh",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Ursyn Ghull",
    objectives = "Speak with Tabetha.",
    rewards = "315 XP",
    tip = "It is time, $N, for you to speak with Tabetha... the hermit of Dustwallow Marsh.  She will instruct you on the creation of a powerful mage's implement.\n\nTabetha's shack lies deep in Dustwallow Marsh, west of Theramore.",
    isForever = false,
  },
  [4976] = {
    id = 4976,
    title = "Returning the Cleansed Orb",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Tabetha",
    objectives = "Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens.",
    rewards = "1,550 XP",
    tip = "Take the cleansed orb back to Menara in Ratchet, $N. Give her my regards and be safe. I truly hope you are able to withstand the temptation and corruption that is sure to come as you follow your path.\n\nGood luck.",
    isForever = false,
  },
  [1951] = {
    id = 1951,
    title = "Rituals of Power",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Magus Tirth",
    objectives = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.",
    rewards = "3,150 XP",
    tip = "Hm... now that I think about it, I don't have my book!  You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....\n\nA member of the Scarlet Brotherhood.  He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!\n\nIf you want that book, then you'll have to go to the monastery to find it.  And sorry about all the trouble.  I'm not myself these days...",
    isForever = false,
  },
  [733] = {
    id = 733,
    title = "Scrounging",
    reqLevel = 35,
    questLevel = 40,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Sigrun Ironhew",
    objectives = "Get 7 pieces of Scrap Metal for Sigrun.",
    rewards = "3,150 XP",
    tip = "It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal. Maybe the stories of siege engines in the Badlands weren't so far off after all...\n\nAnyways, the Prospector's been getting worried about the state of our little camp, so I'd like to get working soon if I can.\n\nThe main ogre camp is at Dustbelch Grotto, a good trek to the west of here.",
    isForever = false,
  },
  [4962] = {
    id = 4962,
    title = "Shard of a Felhound",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Acolyte Wytula",
    objectives = "Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.",
    rewards = "2,350 XP",
    tip = "So, you have chosen to capture the soul of a felhound, good.\n\nTake this ruby--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.\n\nI would suggest going to Desolace and trying your hand at any of the felhounds there. Those should do nicely.\n\nAfter you're successful, take both the captured spirit and your ruby to Menara.",
    isForever = false,
  },
  [4963] = {
    id = 4963,
    title = "Shard of an Infernal",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Acolyte Magaz",
    objectives = "Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.",
    rewards = "2,350 XP",
    tip = "So, you have chosen to capture the soul of an infernal, good.\n\nTake this emerald--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.\n\nI would suggest going to Desolace and trying your hand at any of the infernals there. Those should do nicely.\n\nAfter you're successful, take both the captured spirit and your emerald to Menara.",
    isForever = false,
  },
  [641] = {
    id = 641,
    title = "Sigil of Thoradin",
    reqLevel = 32,
    questLevel = 40,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Tor'gan",
    objectives = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.",
    rewards = "315 XP",
    tip = "The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.",
    isForever = false,
  },
  [709] = {
    id = 709,
    title = "Solution to Doom",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Azeroth",
    npc = "Theldurin the Lost",
    objectives = "Bring the Tablet of Ryun'eh to Theldurin the Lost.",
    rewards = "3,150 XP",
    tip = "Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom!\n\nNo, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!\n\nMaybe.\n\nGo into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again!\n\nIt is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf.",
    isForever = false,
  },
  [585] = {
    id = 585,
    title = "Speaking with Nezzliok",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Object: Bubbling Cauldron",
    objectives = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.",
    rewards = "2,350 XP",
    tip = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe.",
    isForever = false,
  },
  [554] = {
    id = 554,
    title = "Stormpike's Deciphering",
    reqLevel = 28,
    questLevel = 40,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Loremaster Dibbs",
    objectives = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.",
    rewards = "1,550 XP • 50s",
    tip = "Prospector Stormpike is a master of decryption and deciphering.  If you take the parchment you found to him, then with luck he can make sense of it.  Stormpike is currently studying in the Prospector headquarters in Ironforge.\n\nAnd when you see him tell him you spoke with me - I've been sending him quite a lot of business lately.",
    isForever = false,
  },
  [3631] = {
    id = 3631,
    title = "Summon Felsteed",
    reqLevel = 40,
    questLevel = 40,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Zevrost",
    objectives = "Speak to Strahad Farsan in the Barrens.",
    rewards = "315 XP",
    tip = "Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.\n\nHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.\n\nDo not dawdle long.",
    isForever = false,
  },
  [4487] = {
    id = 4487,
    title = "Summon Felsteed",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Briarthorn",
    objectives = "Speak to Strahad Farsan in Ratchet.",
    rewards = "315 XP",
    tip = "Ah, good, you're here. I sent a $g succubus:infernal; after you to get your attention, but it seems you were able to get here before it found you. No matter.\n\nThere has been some talk lately of your growing power--that is good for you, possibly bad for others. But those are irrelevant points. The point is, I feel you've proven yourself and therefore are deserving of... hehe... a blessing of sorts.\n\nAbove Ratchet in the Barrens you'll find a man named Strahad. I believe you've crossed paths befor",
    isForever = false,
  },
  [4488] = {
    id = 4488,
    title = "Summon Felsteed",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Warlock Class Quests",
    npc = "Demisette Cloyce",
    objectives = "Speak to Strahad Farsan in Ratchet.",
    rewards = "315 XP",
    tip = "Ah, $N, you've seen fit to grace us with your presence. How wonderful!\n\nI hope you do not expect us to wait on you hand and foot also. You may be growing quickly in power, but you still are a pup when it comes to true knowledge and understanding. If you're not careful, corruption will overwhelm you and your weak will.\n\nBut I should get to the point: Strahad wishes to speak to you. He is still residing in his tower overlooking Ratchet in the Barrens. I suggest not taking too long.",
    isForever = false,
  },
  [4489] = {
    id = 4489,
    title = "Summon Felsteed",
    reqLevel = 40,
    questLevel = 40,
    faction = "Horde",
    zone = "Warlock Class Quests",
    npc = "Kaal Soulreaper",
    objectives = "Speak to Strahad Farsan in Ratchet.",
    rewards = "315 XP",
    tip = "You, $r! Come here!\n\nYou're the one they call $N, yes?\n\nI thought as much. I will keep this short: you're growing in power, and it has been acknowledged. And now, the time has come that you are rewarded for your efforts.\n\nGo to the Barrens. There, above Ratchet, you'll find Strahad Farsan--perhaps you remember him? He would have words with you. I wouldn't take long.",
    isForever = false,
  },
  [4490] = {
    id = 4490,
    title = "Summon Felsteed",
    reqLevel = 40,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Strahad Farsan",
    objectives = "Speak to Strahad Farsan in Ratchet to learn the ability to summon a Felsteed.",
    rewards = "315 XP",
    tip = "I would give you a reward for your patience and hard work. But know this, the ability to summon a Felsteed will be much more difficult in the future. You will have to earn it... and it will not be easy.\n\nFor now, go with the power to summon such a creature and use it as you see fit.",
    isForever = false,
  },
  [665] = {
    id = 665,
    title = "Sunken Treasure",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Professor Phizzlethorpe",
    objectives = "Escort Professor Phizzlethorpe to the cave and back.",
    rewards = "3,150 XP",
    tip = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.",
    isForever = false,
  },
  [666] = {
    id = 666,
    title = "Sunken Treasure",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Doctor Draxlegauge",
    objectives = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.",
    rewards = "3,900 XP",
    tip = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, $n, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.",
    isForever = false,
  },
  [668] = {
    id = 668,
    title = "Sunken Treasure",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Doctor Draxlegauge",
    objectives = "Take the Elven Gems to Captain O'Breen.",
    rewards = "1,550 XP",
    tip = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, $n, take these to O'Breen.",
    isForever = false,
  },
  [669] = {
    id = 669,
    title = "Sunken Treasure",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Shakes O'Breen",
    objectives = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.",
    rewards = "3,150 XP",
    tip = "Fleet Master Seahorn will want to hear about our find at once.\n\nBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.\n\nYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof.",
    isForever = false,
  },
  [670] = {
    id = 670,
    title = "Sunken Treasure",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Fleet Master Seahorn",
    objectives = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.",
    rewards = "3,150 XP",
    tip = "Say, $n, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.\n\nThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.\n\nCan I trust you to deliver this message safely and in confidence?",
    isForever = false,
  },
  [508] = {
    id = 508,
    title = "Taretha's Gift",
    reqLevel = 29,
    questLevel = 40,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Elysa",
    objectives = "Return Taretha's pendant to Krusk in Tarren Mill.",
    rewards = "3,900 XP",
    tip = "The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace...",
    isForever = false,
  },
  [5283] = {
    id = 5283,
    title = "The Art of the Armorsmith",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Blacksmithing",
    npc = "Grumnus Steelshaper",
    objectives = "To become an Armorsmith, you must make the following items and return them to Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.",
    rewards = "3,150 XP",
    tip = "So ye made the smart decision.\n\nThere ain't no love lost betwixt me an old Ironus here. That good for nothing toy maker knows who the true craftsmen round here be.\n\nThe truly great wars are won with a good defense. When it be go time, no offense is gonna be helping ye out.\n\nRight, so let's get to work. All ye need to do is show me that ye've got some raw talent. After that, I'll yank whatever impurities be left in ye and mold ye into an armorsmith. Ye do know how to make ornate mithril, don't ye",
    isForever = false,
  },
  [5301] = {
    id = 5301,
    title = "The Art of the Armorsmith",
    reqLevel = 40,
    questLevel = 40,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Okothos Ironrager",
    objectives = "To become an armorsmith, you must make the following items and return them to Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.",
    rewards = "3,150 XP",
    tip = "Satisfaction. It is what I draw from the hammer and the anvil. To see a proud Horde warrior protected under my steel reminds me of what it is to be alive. It is an addiction that I dare never give up, $N.\n\nI can not grant you this satisfaction, merely set you upon the path. As with all of life's endeavors, the path of the armorsmith is a journey.\n\nIf you wish to be one of the select few, you need only to ask and I shall train, but, a task you must first complete.",
    isForever = false,
  },
  [708] = {
    id = 708,
    title = "The Black Box",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Item: Corroded Black Box",
    objectives = "Take the Corroded Black Box to the Hall of Arms in Ironforge.",
    rewards = "2,350 XP • 50s",
    tip = "The surface of this metallic black box is heavily pitted, as if it had been immersed in acid - it must have been sitting in the giant condor's stomach for a long time.\n\nTurning the box over, a symbol is found stamped on its bottom.  Below the symbol are the words:\n\n\"Engine #19 - Ironforge Siege Brigade\"",
    isForever = false,
  },
  [640] = {
    id = 640,
    title = "The Broken Sigil",
    reqLevel = 32,
    questLevel = 40,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Zengu",
    objectives = "Retrieve the 11 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.",
    rewards = "3,150 XP • 50s",
    tip = "Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.\n\nThe sigil of Thoradin was divided into five pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.",
    isForever = false,
  },
  [4964] = {
    id = 4964,
    title = "The Completed Orb of Dar'Orahil",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.",
    rewards = "3,900 XP",
    tip = "I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.",
    isForever = false,
  },
  [4975] = {
    id = 4975,
    title = "The Completed Orb of Noh'Orahil",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Menara Voidrender",
    objectives = "Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.",
    rewards = "3,900 XP",
    tip = "I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.",
    isForever = false,
  },
  [1488] = {
    id = 1488,
    title = "The Corrupter",
    reqLevel = 25,
    questLevel = 40,
    faction = "Horde",
    zone = "Desolace",
    npc = "Takata Steelblade",
    objectives = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.",
    rewards = "3,900 XP",
    tip = "Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.\n\nYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.\n\nWhen you are ready, head directly south,  and return to me when the threat has been ended.",
    isForever = false,
  },
  [611] = {
    id = 611,
    title = "The Curse of the Tides",
    reqLevel = 32,
    questLevel = 40,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Catelyn the Blade",
    objectives = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.",
    rewards = "3,150 XP",
    tip = "So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there.\n\nYou got my knife back for me, so I guess you can borrow it... but I want it back when you're done!",
    isForever = false,
  },
  [551] = {
    id = 551,
    title = "The Ensorcelled Parchment",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Alterac Mountains",
    npc = "Item: Ensorcelled Parchment",
    objectives = "Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore.",
    rewards = "780 XP",
    tip = "This parchment is enchanted with a spell, rendering it indecipherable.  But one word at the top of the paper can be read:\n\n\n      Nagaz",
    isForever = false,
  },
  [1955] = {
    id = 1955,
    title = "The Exorcism",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Tabetha",
    objectives = "Kill the Demon of the Orb, then speak with Tabetha.",
    rewards = "2,350 XP",
    tip = "Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.\n\nYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.\n\nAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!\n\nSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.",
    isForever = false,
  },
  [338] = {
    id = 338,
    title = "The Green Hills of Stranglethorn",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Barnil Stonepot",
    objectives = "Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.",
    rewards = "4,700 XP",
    tip = "Master Nesingwary will be so upset if he finds out!\n\nHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!\n\nI was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters.\n\nI will help you organize them.  Return the chapters to me once you have all four.",
    isForever = false,
  },
  [2240] = {
    id = 2240,
    title = "The Hidden Chamber",
    reqLevel = 35,
    questLevel = 40,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Baelog",
    objectives = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.",
    rewards = "3,900 XP",
    tip = "Now for the task at hand.\n\nThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.\n\nI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, $N, must find the chamber of Khaz'mul for us!\n\nRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.",
    isForever = false,
  },
  [1954] = {
    id = 1954,
    title = "The Infernal Orb",
    reqLevel = 35,
    questLevel = 40,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Tabetha",
    objectives = "Bring an Infernal Orb to Tabetha in Dustwallow Marsh.",
    rewards = "2,350 XP",
    tip = "The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.\n\nGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.\n\nWhen you have the orb, return to me.",
    isForever = false,
  },
  [2398] = {
    id = 2398,
    title = "The Lost Dwarves",
    reqLevel = 35,
    questLevel = 40,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Prospector Stormpike",
    objectives = "Find Baelog in Uldaman.",
    rewards = "315 XP • 5s",
    tip = "The dig site at Uldaman wasn't always overrun.  We Ironforge dwarves used to control the area, but... that was before the troggs came.  They came so fast and in such numbers that not even dwarven might could stop them!\n\nIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.\n\nMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up.  If he and his company live, then I want you to find them.",
    isForever = false,
  },
  [1423] = {
    id = 1423,
    title = "The Lost Supplies",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Swamp of Sorrows",
    npc = "Item: Lost Supplies",
    objectives = "Bring the Lost Supplies to Quartermaster Lungertz.",
    rewards = "Experience & Faction Reputation",
    tip = "This barrel is small yet sturdy.  Its seams are sealed with a yellow, pungent wax.  Stamped on the bottom of the barrel are the words:\n\nQUARTERMASTER LUNGERTZ\n\nNETHERGARDE KEEP",
    isForever = false,
  },
  [2760] = {
    id = 2760,
    title = "The Mithril Order",
    reqLevel = 40,
    questLevel = 40,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "McGavan",
    objectives = "Speak with Galvan the Ancient in Stranglethorn Vale.",
    rewards = "3,150 XP",
    tip = "Most of our recruits never make it to Booty Bay, $N. The shine of the insignia is enough to trigger the loot lust in even the staunchest of blacksmiths. Fools they be, as the insignia is a drop in the bucket compared to the wealth of items you'll see!\n\nFind Galvan the Ancient and show him this pin. His residence is far to the north, between Zul Gurub and the Mosh'Ogg ogre mound.",
    isForever = false,
  },
  [2756] = {
    id = 2756,
    title = "The Old Ways",
    reqLevel = 40,
    questLevel = 40,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Aturk the Anvil",
    objectives = "- Steel Breastplate x 4 - Steel Plate Helm x 4",
    rewards = "3,150 XP",
    tip = "In the time of legends, Aturk would crush the skulls of his enemies and grind the bone into a fine powder for use in filament. Long gone are those days, $r. The Warchief calls for peace among the clans. Old enemies are now only watched with weary eyes!\n\nUnbelievable, I know, but such is the will of Thrall.\n\nEnough lamenting! You are here to learn, and learn you will! Bring me four steel breastplates and four steel helms and you will gain a taste of war!",
    isForever = false,
  },
  [2758] = {
    id = 2758,
    title = "The Origins of Smithing",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Blacksmithing",
    npc = "Hank the Hammer",
    objectives = "Bring six Golden Scale Bracers to Hank the Hammer in Stormwind.",
    rewards = "3,150 XP",
    tip = "When I was about your age, a dwarf by the name of Galvan took me under his wing and trained me in the ways of the armorsmith. Before he left for Booty Bay, he made me promise to train all those with the desire and determination to advance in the craft of blacksmithing -- so here I am -- all these years later.\n\nSo, now it's time for you to learn a little something. Make me six golden scale bracers and you will learn where smithing comes from, $N.",
    isForever = false,
  },
  [543] = {
    id = 543,
    title = "The Perenolde Tiara",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Count Remington Ridgewell",
    objectives = "Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.",
    rewards = "4,700 XP • 1g 50s",
    tip = "The Perenolde Tiara is an old heirloom of the Perenolde \"nobles\" - the ruling family of Alterac before that kingdom fell to ruin.  It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds.\n\nWhen Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures.\n\nWe would have you acquire the tiara for us.",
    isForever = false,
  },
  [680] = {
    id = 680,
    title = "The Real Threat",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Korin Fel",
    objectives = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.",
    rewards = "3,900 XP",
    tip = "You serve my husband well, $c, but he does not know why Hammerfall is under attack.\n\nOr'Kalar, Mug'thol's pawn in Stromgarde, has an intense hatred for my husband, and wishes nothing more than my husband's death for defeating him years ago.\n\nMy auguries tell me that Or'Kalar has laid a trap for my husband, so I have hidden signs of the ogre's presence from him.\n\nMy husband will rush off foolishly if he learns of the ogre's whereabouts and I would ask for your help in slaying the creature.",
    isForever = false,
  },
  [1713] = {
    id = 1713,
    title = "The Summoning",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Bath'rah the Windwatcher",
    objectives = "Bring the Whirlwind Heart to Bath'rah Windwatcher.",
    rewards = "2,350 XP",
    tip = "I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power.\n\n$N, are you ready to face the wind lord?",
    isForever = false,
  },
  [1661] = {
    id = 1661,
    title = "The Tome of Nobility",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Duthorian Rall",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "Experience & Faction Reputation",
    tip = "I greet you once again, $N. I am more proud to call you $g brother:sister; than ever before--your dedication is a tribute to us all.\n\nThe time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest.\n\nSpeak to me again and I shall grant you a great boon.",
    isForever = false,
  },
  [4485] = {
    id = 4485,
    title = "The Tome of Nobility",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Arthur the Faithful",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "315 XP",
    tip = "Hello, $N. I see your dedication remains strong, as does your faith.\n\nI think it is time you spoke with Duthorian Rall in Stormwind. There are some more lessons for you to learn, and I feel you are prepared.\n\nSeek him out in the Cathedral of Light, and $N, take these lessons seriously. You've attained your status through humility and hard work, do not disappoint us by becoming arrogant.\n\nBe well.",
    isForever = false,
  },
  [4486] = {
    id = 4486,
    title = "The Tome of Nobility",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Brandur Ironhammer",
    objectives = "Speak to Duthorian Rall in Stormwind.",
    rewards = "315 XP",
    tip = "Well, well, well, look at the mighty paladin in all $ghis:her; regality.\n\nSorry, $N, I meant no offense... I just get a little jealous sometimes when I see some of the feats you've accomplished. Tiza tells me it's my weakness, and I swore to her I'd work on it. It's just hard sometimes, you know?\n\nBut the reason I wanted to talk to you was because Duthorian Rall in Stormwind sent word for you to meet him in the Cathedral of Light when you're ready. Sounded important. Sounded like something's goi",
    isForever = false,
  },
  [5284] = {
    id = 5284,
    title = "The Way of the Weaponsmith",
    reqLevel = 40,
    questLevel = 40,
    faction = "Alliance",
    zone = "Blacksmithing",
    npc = "Ironus Coldsteel",
    objectives = "- Moonsteel Broadsword x 4 - Massive Iron Axe x 4 - Heavy Mithril Axe x 2 - Big Black Mace x 2",
    rewards = "3,150 XP",
    tip = "As a weaponsmith you'll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung.\n\nOh yes, $N, weaponsmiths are the ones with all the gold!\n\nIf you wish to join our ranks, you'll need to show me that you can make me a silver or two - I mean, show me that you've got what it takes to be the go to $g guy:girl; when people need superior quality weapons. Get to wor",
    isForever = false,
  },
  [5302] = {
    id = 5302,
    title = "The Way of the Weaponsmith",
    reqLevel = 40,
    questLevel = 40,
    faction = "Horde",
    zone = "Blacksmithing",
    npc = "Borgosh Corebender",
    objectives = "- Moonsteel Broadsword x 4 - Massive Iron Axe x 4 - Heavy Mithril Axe x 2 - Big Black Mace x 2",
    rewards = "3,150 XP",
    tip = "One day, I will create a legendary hammer. A hammer fit for a Warchief!\n\nIt is my life's work, $N. My passion. I recognize that you have the potential to be among us, one of us - a weaponsmith. I am the one that can help you harness that potential.\n\nA simple task is all that you must complete. Simple for one of your exceptional skill.",
    isForever = false,
  },
  [687] = {
    id = 687,
    title = "Theldurin the Lost",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Gerrig Bonegrip",
    objectives = "Find Theldurin the Lost.",
    rewards = "1,550 XP",
    tip = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.\n\nTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.",
    isForever = false,
  },
  [727] = {
    id = 727,
    title = "To Ironforge for Yagyin's Digest",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Theldurin the Lost",
    objectives = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
    rewards = "780 XP",
    tip = "The Tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!",
    isForever = false,
  },
  [728] = {
    id = 728,
    title = "To the Undercity for Yagyin's Digest",
    reqLevel = 30,
    questLevel = 40,
    faction = "Horde",
    zone = "Badlands",
    npc = "Theldurin the Lost",
    objectives = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.",
    rewards = "780 XP",
    tip = "The tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!",
    isForever = false,
  },
  [205] = {
    id = 205,
    title = "Troll Witchery",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Brother Nimetz",
    objectives = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.",
    rewards = "3,150 XP",
    tip = "While I study those legends you acquired, gather for me implements of evil troll magic.  Enter the territory of the Skullsplitter trolls, a second tribe to the distant south, and acquire Skullsplitter Fetishes from their Witchdoctors and Mystics.",
    isForever = false,
  },
  [566] = {
    id = 566,
    title = "WANTED: Baron Vardus",
    reqLevel = 35,
    questLevel = 40,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Object: WANTED",
    objectives = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.",
    rewards = "3,150 XP",
    tip = "By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate.\n\nHe was last spotted in the Uplands in the Alterac Mountains, north of Tarren Mill.\n\nHe is wanted dead. Bring evidence of his demise to High Executor Darthalia to claim the reward.",
    isForever = false,
  },
  [685] = {
    id = 685,
    title = "Wanted!  Otto and Falconcrest",
    reqLevel = 30,
    questLevel = 40,
    faction = "Alliance",
    zone = "Arathi Highlands",
    npc = "Object: Wanted Board",
    objectives = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.",
    rewards = "3,900 XP",
    tip = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.",
    isForever = false,
  },
  [1792] = {
    id = 1792,
    title = "Whirlwind Weapon",
    reqLevel = 30,
    questLevel = 40,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Bath'rah the Windwatcher",
    objectives = "Speak with Bath'rah the Windwatcher in Warrior Class Quests.",
    rewards = "3,900 XP",
