  [2200] = {
    id = 2200,
    title = "Back to Uldaman",
    reqLevel = 37,
    questLevel = 42,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Talvash del Kissel",
    objectives = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who has it last.",
    rewards = "2,550 XP",
    tip = "A competitor of mine started a rumor that my necklace cursed the paladin.  Needless to say, no one wants to buy cursed items from a jeweler.\n\n$N, I'll make you a deal - find the gems and I'll reassemble the necklace, so long as you'll advertise that I do NOT make cursed items!\n\nTry looking for clues in Uldaman; maybe see if the paladin's body is down there, since he's the one who we know had it last!  When you find the gems you should use this; it'll allow you to contact me here in Ironforge.",
    isForever = false,
  },
  [652] = {
    id = 652,
    title = "Breaking the Keystone",
    reqLevel = 30,
    questLevel = 42,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Object: Stone of Inner Binding",
    objectives = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.",
    rewards = "3,450 XP",
    tip = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n$N, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!",
    isForever = false,
  },
  [3341] = {
    id = 3341,
    title = "Bring the End",
    reqLevel = 37,
    questLevel = 42,
    faction = "Horde",
    zone = "Razorfen Downs",
    npc = "Andrew Brownell",
    objectives = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.",
    rewards = "4,300 XP",
    tip = "In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...\n\nThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.\n\nAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, $N. An end must come to the Coldbri",
    isForever = false,
  },
  [3636] = {
    id = 3636,
    title = "Bring the Light",
    reqLevel = 39,
    questLevel = 42,
    faction = "Alliance",
    zone = "Razorfen Downs",
    npc = "Archbishop Benedictus",
    objectives = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.",
    rewards = "4,300 XP",
    tip = "The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, $N.\n\nIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.\n\nAlign yourself with the Light, $N; put an end to this evil union.",
    isForever = false,
  },
  [1425] = {
    id = 1425,
    title = "Deliver the First Shipment",
    reqLevel = 30,
    questLevel = 42,
    faction = "Alliance",
    zone = "Swamp of Sorrows",
    npc = "Watcher Biggs",
    objectives = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.",
    rewards = "2,550 XP",
    tip = "While I fix this wagon, $N, I have one last task for you.\n\nI have packed the most vital supplies saved from the ogre attacks.  Take them to Nethergarde Keep.  The keep is nestled in the northern hills of the Blasted Lands, keeping watch over the Dark Portal.\n\nTo reach Nethergard, follow the road east.  When it branches head south into the Blasted Lands, then turn left at the next fork.  Follow the road, $N, and be wary.",
    isForever = false,
  },
  [1398] = {
    id = 1398,
    title = "Driftwood",
    reqLevel = 30,
    questLevel = 42,
    faction = "Alliance",
    zone = "Swamp of Sorrows",
    npc = "Watcher Biggs",
    objectives = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.",
    rewards = "3,450 XP",
    tip = "I owe you greatly, $N.  An honorable heart beats within you.  And now I have another task for which I humbly ask your aid.\n\nIf I'm ever to reach Nethergarde, then I must fix this wagon.  And for that... I will need wood.  Strong, dry wood--not the spongy, tangled wood of the swamp's trees.\n\n$N, go east to the coast and search for driftwood that has been dried by the sun.  Bring it to me.",
    isForever = false,
  },
  [2932] = {
    id = 2932,
    title = "Grim Message",
    reqLevel = 35,
    questLevel = 42,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Nimboya",
    objectives = "Gather Witherbark Skulls and place on Nimboya's Pike.  Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn.",
    rewards = "3,450 XP • 55s",
    tip = "The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!\n\nHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.\n\nWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.\n\nShow them their vile actions are of consequence!",
    isForever = false,
  },
  [1192] = {
