  [1048] = {
    id = 1048,
    title = "Into The Scarlet Monastery",
    reqLevel = 33,
    questLevel = 42,
    faction = "Horde",
    zone = "Scarlet Monastery",
    npc = "Varimathras",
    objectives = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.",
    rewards = "5,150 XP",
    tip = "Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.\n\nNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.\n\nTravel to the Monastery, $c, and lay waste to High Inquisitor Whitemane and her top lieutenants.",
    isForever = false,
  },
  [576] = {
    id = 576,
    title = "Keep An Eye Out",
    reqLevel = 37,
    questLevel = 42,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Dizzy One-Eye",
    objectives = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.",
    rewards = "2,550 XP",
    tip = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?",
    isForever = false,
  },
  [1380] = {
    id = 1380,
    title = "Khan Hratha",
    reqLevel = 30,
    questLevel = 42,
    faction = "Both",
    zone = "Desolace",
    npc = "Uthek the Wise",
    objectives = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.",
    rewards = "4,300 XP",
    tip = "$N, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha!\n\nTo face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears.\n\nBut to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur.\n\nAfter the horn is blown, centaur will come.  Kill them until Hratha appears.\n\nKhan Hratha holds the piece of... a key.  Bring it to me...",
    isForever = false,
  },
  [1381] = {
    id = 1381,
    title = "Khan Hratha",
    reqLevel = 30,
    questLevel = 42,
    faction = "Both",
    zone = "Desolace",
    npc = "Warug",
    objectives = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.",
    rewards = "4,300 XP",
    tip = "The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha!\n\nTo face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn.\n\nDo this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...",
    isForever = false,
  },
  [699] = {
    id = 699,
    title = "Lack of Surplus",
    reqLevel = 35,
    questLevel = 42,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Tok'Kar",
    objectives = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.",
    rewards = "3,450 XP",
    tip = "With the threat of murlocs along the coast, we're stationed out here to protect--or warn if the force is too large--of any coming threats to Stonard. It doesn't give us much time for relaxation, and we could use some more help if you're able.\n\nThe sawtooth snappers' claws make for fine weapons when properly prepared. Bring me some of their claws and I'll see you're rewarded with one of our weapons in thanks for the fresh meat and the good company.",
    isForever = false,
  },
  [507] = {
    id = 507,
    title = "Lord Aliden Perenolde",
    reqLevel = 29,
    questLevel = 42,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Krusk",
    objectives = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.",
    rewards = "4,300 XP",
    tip = "It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, $n, then retrieve the pendant that the Warchief desires, and return here.",
    isForever = false,
  },
  [739] = {
    id = 739,
    title = "Murdaloc",
    reqLevel = 30,
    questLevel = 42,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Object: Battered Dwarven Skeleton",
    objectives = "Slay Agmond's killer, Murdaloc.\n\nSlay 12 Stonevault Bonesnappers.\n\nReport to Prospector Ironband in Loch Modan.",
    rewards = "3,450 XP",
    tip = "Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.\n\nAnd here he died.\n\nUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.\n\nScrawled next to Agmond's dead hand.",
    isForever = false,
  },
  [1372] = {
    id = 1372,
    title = "Nothing But The Truth",
    reqLevel = 37,
    questLevel = 42,
    faction = "Horde",
    zone = "Duskwood",
    npc = "Deathstalker Zraedus",
    objectives = "Speak with Apothecary Faustin at Beggar's Haunt.",
    rewards = "345 XP",
    tip = "Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.\n\nWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.\n\nI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.\n\nWork with Faustin here to develop a... truth serum for our friend in Stonard.",
    isForever = false,
  },
  [1383] = {
    id = 1383,
    title = "Nothing But The Truth",
    reqLevel = 37,
    questLevel = 42,
    faction = "Horde",
    zone = "Duskwood",
    npc = "Apothecary Faustin",
    objectives = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and a Deep Strider Tumor.",
    rewards = "4,300 XP",
    tip = "I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with.\n\nFor this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, $n, can persuade him to part with some.\n\nNow the hard part will be locating a Deepstrider tumor from far-off Desolace. Very rarely the giants there become ill and a tumor forms.\n\nNow, off you go!",
    isForever = false,
  },
  [1388] = {
    id = 1388,
    title = "Nothing But The Truth",
    reqLevel = 37,
    questLevel = 42,
    faction = "Horde",
    zone = "Duskwood",
    npc = "Apothecary Faustin",
    objectives = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.",
    rewards = "345 XP",
    tip = "Everything is proceeding according to plan, $n. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly.\n\nHaha!",
    isForever = false,
  },
  [1391] = {
    id = 1391,
    title = "Nothing But The Truth",
    reqLevel = 37,
    questLevel = 42,
    faction = "Horde",
    zone = "Duskwood",
    npc = "Deathstalker Zraedus",
    objectives = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.",
    rewards = "2,550 XP",
    tip = "We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right?\n\nBut if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew.\n\nMake haste to Stonard in the Swamp of Sorrows, $n. And keep our little mission nice and quiet...",
    isForever = false,
  },
  [3375] = {
    id = 3375,
    title = "Replacement Phial",
    reqLevel = 37,
    questLevel = 42,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Talvash del Kissel",
    objectives = "Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying.",
    rewards = "Experience & Faction Reputation",
    tip = "Um... you need another phial of scrying?  You're kidding, right?  What did you do with the first one?!  We have a lot of work ahead of us here, $r.  Those phials don't grow on trees!  Actually, I wish they did, because I'd go there and pick one off since I don't have another one!!\n\nin order to make you one, I need the following: a mana potion, a piece of coal, and some sweet nectar.  Don't ask why, just bring me what I ask and I'll make you a new one.",
    isForever = false,
  },
  [7068] = {
    id = 7068,
    title = "Shadowshard Fragments",
    reqLevel = 38,
    questLevel = 42,
    faction = "Horde",
    zone = "Maraudon",
    npc = "Uthel'nay",
    objectives = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.",
    rewards = "3,450 XP",
    tip = "Strong magics be found in the centaur holy place... the holy place of Maraudon. The Desolace tribes of centaur protect that place wit' their lives, but they canna stop us from takin' what we need.\n\nYou, you head to this Maraudon place and find the rock creatures made of shadowshard. You bring me the purple crystals, and Uthel'nay make you somethin' for your time.\n\nThe place be dangerous, so maybe you be bringing some friends.",
    isForever = false,
  },
  [7070] = {
    id = 7070,
    title = "Shadowshard Fragments",
    reqLevel = 38,
    questLevel = 42,
    faction = "Alliance",
    zone = "Maraudon",
    npc = "Archmage Tervosh",
    objectives = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.",
    rewards = "3,450 XP",
    tip = "I've recently begun testing various crystals and their arcane properties. Lady Proudmoore has given me leave to ask travelers heading into Desolace to seek out a place called Maraudon. Within the ruined temple are great elementals composed of purplish stones I've named shadowshards.\n\nIf you decide to head that direction and find some of the crystals, I would be very thankful. I could even fashion you a trinket from them if you so desired.",
    isForever = false,
  },
  [644] = {
    id = 644,
    title = "Sigil of Trollbane",
    reqLevel = 32,
    questLevel = 42,
    faction = "Horde",
    zone = "Arathi Highlands",
    npc = "Zengu",
    objectives = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.",
    rewards = "3,450 XP • 55s",
    tip = "The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.",
    isForever = false,
  },
  [209] = {
    id = 209,
    title = "Skullsplitter Tusks",
    reqLevel = 37,
    questLevel = 42,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Kebok",
    objectives = "Acquire 18 Skullsplitter Tusks and return them to Kebok.",
    rewards = "3,450 XP • 55s",
    tip = "It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries.\n\nThe closest match we've found, amazingly, are the tusks of the Skullsplitter trolls.\n\nHey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!",
    isForever = false,
  },
  [598] = {
    id = 598,
    title = "Split Bone Necklace",
    reqLevel = 30,
    questLevel = 42,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Kin'weelay",
    objectives = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.",
    rewards = "3,450 XP",
    tip = "Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters.\n\nSo, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.",
    isForever = false,
  },
  [716] = {
    id = 716,
    title = "Stone Is Better than Cloth",
    reqLevel = 35,
    questLevel = 42,
    faction = "Both",
    zone = "Badlands",
    npc = "Lucien Tosselwrench",
    objectives = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.",
    rewards = "2,550 XP",
    tip = "I know how cheap Lotwil can be, $N, so let me make you something for all your troubles. Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention.\n\nI've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use. They're enchanted, of course.\n\nI'll just need patterned bronze bracers crafted by a blacksmith so I can complete the bracers I'm making for you.",
    isForever = false,
  },
  [712] = {
    id = 712,
    title = "Study of the Elements: Rock",
    reqLevel = 35,
    questLevel = 42,
    faction = "Both",
    zone = "Badlands",
    npc = "Lotwil Veriatus",
    objectives = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.",
    rewards = "3,450 XP",
    tip = "$N, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles.\n\nMy attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall.\n\nBring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research.",
    isForever = false,
  },
  [734] = {
    id = 734,
    title = "This Is Going to Be Hard",
    reqLevel = 35,
    questLevel = 42,
    faction = "Both",
    zone = "Badlands",
    npc = "Lotwil Veriatus",
    objectives = "Speak to Lucien Tosselwrench in the Badlands.",
    rewards = "Experience & Faction Reputation",
    tip = "Wonderful, wonderful.\n\n<Lotwil looks up at you for a moment before going back to his shackles.>\n\nGo speak to Lucien, $N. I need a cog #5. Bring it to me, will you?",
    isForever = false,
  },
  [777] = {
    id = 777,
    title = "This Is Going to Be Hard",
    reqLevel = 35,
    questLevel = 42,
    faction = "Both",
    zone = "Badlands",
    npc = "Lucien Tosselwrench",
    objectives = "Bring Cog #5 to Lotwil Veriatus.",
    rewards = "Experience & Faction Reputation",
    tip = "Okay, here you go.\n\nI'm going to be over here... behind cover.\n\nFeel free to join me.",
    isForever = false,
  },
  [2318] = {
    id = 2318,
    title = "Translating the Journal",
    reqLevel = 37,
    questLevel = 42,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Remains of a Paladin",
    objectives = "Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands.",
    rewards = "3,450 XP",
    tip = "At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start.",
    isForever = false,
  },
  [2338] = {
    id = 2338,
    title = "Translating the Journal",
    reqLevel = 37,
    questLevel = 42,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Jarkal Mossmeld",
    objectives = "Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you.",
    rewards = "345 XP",
    tip = "Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.\n\nIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?",
    isForever = false,
  },
  [645] = {
