  [2202] = {
    id = 2202,
    title = "Uldaman Reagent Run",
    reqLevel = 36,
    questLevel = 42,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Jarkal Mossmeld",
    objectives = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.",
    rewards = "3,450 XP • 55s",
    tip = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!",
    isForever = false,
  },
  [2862] = {
    id = 2862,
    title = "War on the Woodpaw",
    reqLevel = 39,
    questLevel = 42,
    faction = "Horde",
    zone = "Feralas",
    npc = "Hadoken Swiftstrider",
    objectives = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.",
    rewards = "2,550 XP • 45s",
    tip = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!",
    isForever = false,
  },
  [2981] = {
    id = 2981,
    title = "A Threat in Feralas",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Belgrom Rockmaul",
    objectives = "Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache.",
    rewards = "890 XP",
    tip = "Feralas is an ideal location for an accomplished $c to prove $Ghimself:herself;. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.\n\nA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.",
    isForever = false,
  },
  [2869] = {
    id = 2869,
    title = "Against the Hatecrest",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Latronicus Moonspear",
    objectives = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.",
    rewards = "2,700 XP • 45s",
    tip = "The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.\n\nBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our adva",
    isForever = false,
  },
  [3130] = {
    id = 3130,
    title = "Against the Hatecrest",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Shandris Feathermoon",
    objectives = "Report to Latronicus Moonspear in Feathermoon Stronghold.",
    rewards = "360 XP",
    tip = "At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.\n\nAnyway, Latronicus awaits.  Good work thus far, $n.  Keep it up.\n\nYou're dismissed.",
    isForever = false,
  },
  [617] = {
    id = 617,
    title = "Akiris by the Bundle",
    reqLevel = 38,
    questLevel = 43,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Privateer Bloads",
    objectives = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.",
    rewards = "3,600 XP • 60s",
    tip = "You looking fer work, $N? I might have some if you're up for a little challenge.\n\nI got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff.\n\nYa bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here.",
    isForever = false,
  },
  [623] = {
    id = 623,
    title = "Akiris by the Bundle",
    reqLevel = 38,
    questLevel = 43,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Privateer Bloads",
    objectives = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.",
    rewards = "2,700 XP • 45s",
    tip = "$N, since I have you here, I got a message from Groy while you were gone. He mentioned bein' satisfied with the last shipment that arrived and has a client that wants some more of the stuff right away.\n\nI won't be headin' to Theramore for a week, but if you're willin' to make the journey, there's no reason you can't take the stuff for me.\n\nFeeling adventurous? You do know where Dustwallow Marsh is, doncha? I'd be careful though, Theramore can be dangerous if you're the wrong kind of crowd.",
    isForever = false,
  },
  [2863] = {
    id = 2863,
    title = "Alpha Strike",
    reqLevel = 39,
    questLevel = 43,
    faction = "Horde",
    zone = "Feralas",
    npc = "Hadoken Swiftstrider",
    objectives = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.",
    rewards = "2,700 XP • 45s",
    tip = "The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!\n\nI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work $N, or we'll remain at this impasse!",
    isForever = false,
  },
  [1168] = {
    id = 1168,
    title = "Army of the Black Dragon",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Tharg",
    objectives = "Tharg in Brackenwall Village wants you to kill 15 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Guards.",
    rewards = "4,450 XP",
    tip = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.",
    isForever = false,
  },
  [1118] = {
    id = 1118,
    title = "Back to Booty Bay",
    reqLevel = 35,
    questLevel = 43,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.",
    rewards = "890 XP",
    tip = "$N, you're a $c I can trust, both to get the job done and to keep your mouth shut while doing it.\n\nI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.\n\nTo start, you must go back to Booty Bay.  I apologize, good $N.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.\n\nGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort",
    isForever = false,
  },
  [208] = {
    id = 208,
    title = "Big Game Hunter",
    reqLevel = 28,
    questLevel = 43,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Hemet Nesingwary",
    objectives = "Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.",
    rewards = "5,350 XP",
    tip = "$N, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated.\n\nYou have killed the ferocious Sin'Dall, the elusive Bag'thera and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here.  I've had my sights on him for quite some time now.  Kill King Bangalash and your hunting prowess is proven to be second to none.",
    isForever = false,
  },
  [782] = {
    id = 782,
    title = "Broken Alliances",
    reqLevel = 40,
    questLevel = 43,
    faction = "Horde",
    zone = "Badlands",
    npc = "Gorn",
    objectives = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.",
    rewards = "3,600 XP",
    tip = "From the Horde's alliance with the dragon Deathwing during the Second War, we know that two of his lieutenants, Blacklash and Hematus, were imprisoned within Lethlor Ravine far to the east. We must silence our depraved allies of old to restore honor to the Horde!\n\nWe hired Tho'grun and his band of ogre mercenaries to help us obtain the Sign of the Earth, a key needed to unlock the drakes' prison. Tho'grun betrayed us though, overwhelming us and taking it for himself. Go to Camp Boff and take it ",
    isForever = false,
  },
  [624] = {
    id = 624,
    title = "Cortello's Riddle",
    reqLevel = 35,
    questLevel = 43,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Item: Cortello's Riddle",
    objectives = "Solve the riddle!",
    rewards = "3,600 XP",
    tip = "There is an ornate, well-traveled bridge\nEast of Deadwind and south of Redridge\nUnderneath there waits something for you\nSome call it a hint, others a clue\nThere it will lie for endless tomorrows\nBiding its time in the Swamp of Sorrows",
    isForever = false,
  },
  [625] = {
    id = 625,
    title = "Cortello's Riddle",
    reqLevel = 35,
    questLevel = 43,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Object: A Soggy Scroll",
    objectives = "Solve the riddle!",
    rewards = "3,600 XP",
    tip = "A far off land in Kalimdor awaits\nWhere peril has dashed hopes and fates\nEast of Barrens the weather is harsh\nGloom and danger pock Dustwallow Marsh\nBut there lies a clue for those up to the test\nWaiting to be found in a cave in the southwest",
    isForever = false,
  },
  [2201] = {
    id = 2201,
    title = "Find the Gems",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Remains of a Paladin",
    objectives = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n\n* The sapphire has been claimed by Grimlok, the trogg leader.",
    rewards = "3,600 XP",
    tip = "The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.\n\nArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions.",
    isForever = false,
  },
  [2987] = {
    id = 2987,
    title = "Gordunni Cobalt",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Feralas",
    npc = "Orwin Gizzmick",
    objectives = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.",
    rewards = "3,600 XP",
    tip = "I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.\n\nIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!",
    isForever = false,
  },
  [1450] = {
    id = 1450,
    title = "Gryphon Master Talonaxe",
    reqLevel = 38,
    questLevel = 43,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Falstad Wildhammer",
    objectives = "Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary.",
    rewards = "890 XP",
    tip = "So you're a glorified errand $g boy:girl; for some old Explorers' League geezer, eh?\n\nWell you listen to me, $c. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?\n\nIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.\n\nNow get a move on.",
    isForever = false,
  },
  [1169] = {
    id = 1169,
    title = "Identifying the Brood",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Draz'Zilb",
    objectives = "Draz'Zilb in Brackenwall Village would like you to bring him 15 Searing Tongues and 15 Searing Hearts.",
    rewards = "5,350 XP",
    tip = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, $n? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...",
    isForever = false,
  },
  [1448] = {
    id = 1448,
    title = "In Search of The Temple",
    reqLevel = 38,
    questLevel = 43,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Brohann Caskbelly",
    objectives = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.",
    rewards = "3,600 XP",
    tip = "There was a time when I was young and full of vigor like you, $c.\n\nBut now I'm old and unable to explore the world like I once did. Ah, the things I saw!\n\nBut there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows.\n\nBecause of my frail state, I traveled the skies by gryphon in search of it but never found it.\n\nHelp an old dwarf out? Perhaps you will have better luck on fo",
    isForever = false,
  },
  [1166] = {
    id = 1166,
    title = "Overlord Mok'Morokk's Concern",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Overlord Mok'Morokk",
    objectives = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.",
    rewards = "4,450 XP",
    tip = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny $r, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!",
    isForever = false,
  },
  [1424] = {
    id = 1424,
    title = "Pool of Tears",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Fel'zerul",
    objectives = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.",
    rewards = "4,450 XP • 1g 20s",
    tip = "The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.\n\nThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.\n\nThe green dragons now guard the site, claiming to be protectors of Azeroth.\n\nWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.",
    isForever = false,
  },
  [197] = {
    id = 197,
    title = "Raptor Mastery",
    reqLevel = 28,
    questLevel = 43,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Hemet Nesingwary",
    objectives = "Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.",
    rewards = "3,600 XP",
    tip = "Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill.  Ajeck here calls this wily raptor Tethis.\n\nIf you want to prove yourself a true master, kill Tethis and bring me his talon.  It would be a feat that no other big game hunter has accomplished.",
    isForever = false,
  },
  [1360] = {
    id = 1360,
    title = "Reclaimed Treasures",
    reqLevel = 33,
    questLevel = 43,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Krom Stoutarm",
    objectives = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.",
    rewards = "3,600 XP • 60s",
    tip = "I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up.  I escaped with my hide barely intact, and nothing else.  In the chaos, I left my most treasured possession.  It's safe from the troggs in my chest, sure, but it's right in the thick of 'em.\n\nI'd be in your debt, both in honor and coin, if you could fetch it for me!  A chest with my name on it is at the end of the North Common Hall.  That's the one you need to get i",
    isForever = false,
  },
  [2342] = {
    id = 2342,
    title = "Reclaimed Treasures",
    reqLevel = 33,
    questLevel = 43,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Patrick Garrett",
    objectives = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.",
    rewards = "3,600 XP • 60s",
    tip = "Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.\n\nThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.\n\nReclaim my family's treasure and bring it to me!  Help me restore my birthright!",
    isForever = false,
  },
  [2867] = {
    id = 2867,
    title = "Return to Feathermoon Stronghold",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Object: Solarsal Gazebo",
    objectives = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.",
    rewards = "1,800 XP • 45s",
    tip = "With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here.",
    isForever = false,
  },
  [1451] = {
    id = 1451,
    title = "Rhapsody Shindigger",
    reqLevel = 38,
    questLevel = 43,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Gryphon Master Talonaxe",
    objectives = "Seek out Rhapsody Shindigger in The Hinterlands.",
    rewards = "1,800 XP",
    tip = "Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.\n\nBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.\n\nFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.\n\nLast I heard, he's set up a brew camp to the east of he",
    isForever = false,
  },
  [1452] = {
    id = 1452,
    title = "Rhapsody's Kalimdor Kocktail",
    reqLevel = 38,
    questLevel = 43,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Rhapsody Shindigger",
    objectives = "Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers.",
    rewards = "3,600 XP",
    tip = "Hiccup!\n\nSo that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup!\n\nIf ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup!\n\nTell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it.\n\nGonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas...\n\nA nice stiff Kalimdor Kocktail... that'll get me talking!",
    isForever = false,
  },
  [1469] = {
    id = 1469,
    title = "Rhapsody's Tale",
    reqLevel = 38,
    questLevel = 43,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Rhapsody Shindigger",
    objectives = "Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.",
    rewards = "2,700 XP",
    tip = "Before the flight, I drank me a whole keg of stout. Hiccup!\n\nAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!\n\nWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hic",
    isForever = false,
  },
  [2903] = {
    id = 2903,
    title = "The Battle Plans",
    reqLevel = 39,
    questLevel = 43,
    faction = "Horde",
    zone = "Feralas",
    npc = "Object: Woodpaw Battle Map",
    objectives = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.",
    rewards = "3,600 XP",
    tip = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.",
    isForever = false,
  },
  [604] = {
    id = 604,
    title = "The Bloodsail Buccaneers",
    reqLevel = 37,
    questLevel = 43,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Fleet Master Seahorn",
    objectives = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.",
    rewards = "3,600 XP",
    tip = "Crazz speaks highly of your dedication to the Blackwater Raiders.  I am going to trust you with a mission of extreme importance to the fleet.\n\nInfiltrate the so-called southern command post the Bloodsail Buccaneers have established on the Wild Shore.  Raid the encampment.  Bring me their charts along with their written orders.  We shall see exactly what those scum are up to.",
    isForever = false,
  },
  [1170] = {
    id = 1170,
    title = "The Brood of Onyxia",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Draz'Zilb",
    objectives = "Speak with Overlord Mok'Morokk in Brackenwall Village.",
    rewards = "360 XP",
    tip = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.",
    isForever = false,
  },
  [1171] = {
    id = 1171,
    title = "The Brood of Onyxia",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Overlord Mok'Morokk",
    objectives = "Speak with Draz'Zilb in Brackenwall Village.",
    rewards = "360 XP",
    tip = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.",
    isForever = false,
  },
  [520] = {
    id = 520,
    title = "The Crown of Will",
    reqLevel = 34,
    questLevel = 43,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Melisara",
    objectives = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.",
    rewards = "4,450 XP",
    tip = "With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows.\n\nFind Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end.",
    isForever = false,
  },
  [521] = {
    id = 521,
    title = "The Crown of Will",
    reqLevel = 34,
    questLevel = 43,
    faction = "Horde",
    zone = "Hillsbrad Foothills",
    npc = "Melisara",
    objectives = "Deliver the Crown of Will to Sharlindra in the Undercity.",
    rewards = "3,600 XP",
    tip = "All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, $n, Mug'Thol's fate should be illustration enough.",
    isForever = false,
  },
  [2978] = {
    id = 2978,
    title = "The Gordunni Scroll",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Feralas",
    npc = "Item: Gordunni Scroll",
    objectives = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.",
    rewards = "1,800 XP",
    tip = "Picking up the soiled scroll, you notice that it seems to be depicting some sort of meeting or ceremony. Rok Orhan would be interested in this scroll, and what it might mean to the Gordunni.",
    isForever = false,
  },
  [4124] = {
    id = 4124,
    title = "The Missing Courier",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Latronicus Moonspear",
    objectives = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
    rewards = "360 XP",
    tip = "An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.\n\nIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters.",
    isForever = false,
  },
  [4125] = {
    id = 4125,
    title = "The Missing Courier",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Ginro Hearthkindle",
    objectives = "Locate the courier's boat somewhere along the coast of Feralas.",
    rewards = "2,700 XP",
    tip = "It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.\n\nI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know.",
    isForever = false,
  },
  [2975] = {
    id = 2975,
    title = "The Ogres of Feralas",
    reqLevel = 38,
    questLevel = 43,
    faction = "Horde",
    zone = "Feralas",
    npc = "Rok Orhan",
    objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.",
    rewards = "2,700 XP • 45s",
    tip = "The effects of the Gordunni Ogre tribe can hardly go unnoticed in this area. Look around, $N; their very presence scars this land. We must push them back before they expand even further into Feralas.\n\nFollow the river north, and you will find their outpost. Decrease their numbers, $N. We must show them that their kind is not wanted here.",
    isForever = false,
  },
  [2866] = {
    id = 2866,
    title = "The Ruins of Solarsal",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Shandris Feathermoon",
    objectives = "Explore the Ruins of Solarsal and investigate the presence of the naga there.",
    rewards = "2,700 XP",
    tip = "To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.\n\nVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.\n\nGo there, explore the ruins, and look for anything that stands out to you. Good luck, $n",
    isForever = false,
  },
  [1426] = {
    id = 1426,
    title = "Threat From the Sea",
    reqLevel = 35,
    questLevel = 43,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Katar",
    objectives = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.",
    rewards = "4,450 XP",
    tip = "I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will.\n\nWhich brings us to you, $c. How many can you slay? Would you test yourself against their most powerful kind?",
    isForever = false,
  },
  [1427] = {
    id = 1427,
    title = "Threat From the Sea",
    reqLevel = 35,
    questLevel = 43,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Katar",
    objectives = "Speak with Tok'Kar in the Swamp of Sorrows.",
    rewards = "3,600 XP",
    tip = "Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.",
    isForever = false,
  },
  [1449] = {
    id = 1449,
    title = "To The Hinterlands",
    reqLevel = 38,
    questLevel = 43,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Brohann Caskbelly",
    objectives = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.",
    rewards = "1,800 XP",
    tip = "As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.\n\nI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...\n\nIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.\n\nJourney there and seek out Falstad Wildhammer.\n\nWe need to find out what happened to that pilot.",
    isForever = false,
  },
  [732] = {
    id = 732,
    title = "Tremors of the Earth",
    reqLevel = 40,
    questLevel = 43,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Garek",
    objectives = "Retrieve the Sign of the Earth for Garek.",
    rewards = "3,600 XP",
    tip = "I heard from Sigrun that you have been a great help to him. Perhaps I might enlist your help. I was sent here by my master, Krasus of the Kirin Tor, to put an end to the trouble brewing in Lethlor Ravine.\n\nI cannot divulge the exact nature of my assignment here or the tasks that I must undertake, but be assured it is of vital importance.\n\nA band of wandering ogres, sometimes seen near Camp Boff, stole an object called the Sign of the Earth; I must have it. Bring it to me, and I will tell you mor",
    isForever = false,
  },
  [2933] = {
    id = 2933,
    title = "Venom Bottles",
    reqLevel = 40,
    questLevel = 43,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Object: Venom Bottle",
    objectives = "Bring a Venom Bottle to an apothecary in Tarren Mill.",
    rewards = "3,600 XP",
    tip = "These bottles hold a vile, green venom.\n\nConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample.",
    isForever = false,
  },
  [1690] = {
    id = 1690,
    title = "Wastewander Justice",
    reqLevel = 40,
    questLevel = 43,
    faction = "Both",
    zone = "Tanaris",
    npc = "Chief Engineer Bilgewhizzle",
    objectives = "Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle.",
    rewards = "3,600 XP • 60s",
    tip = "You there!  It's time for you to be a big helper to the Gadgetzan Water Company.\n\nThe Wastewander nomads out in the Tanaris desert have seized almost all the water wells!  Without access to them, our water supply will dry up in no time.  If you want to get in our good graces, then you'll help us bring justice to those nomads!\n\nHead east of here and bring down ten Wastewander Bandits and Thieves, then report back to me on the double.  Justice waits for no man... goblin... bah, just get on it!",
    isForever = false,
  },
  [2902] = {
    id = 2902,
    title = "Woodpaw Investigation",
    reqLevel = 39,
    questLevel = 43,
    faction = "Horde",
    zone = "Feralas",
    npc = "Hadoken Swiftstrider",
    objectives = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.",
    rewards = "1,800 XP",
    tip = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.",
    isForever = false,
  },
  [762] = {
    id = 762,
    title = "An Ambassador of Evil",
    reqLevel = 35,
    questLevel = 44,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Historian Karnik",
    objectives = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.",
    rewards = "4,650 XP • 1g 25s",
    tip = "Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman.\n\nIt has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge.\n\nOur goal is simple, $c. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory.\n\nIt is in your hands ",
    isForever = false,
  },
  [8261] = {
    id = 8261,
    title = "Arathor Standard Care Package",
    reqLevel = 35,
    questLevel = 44,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Samuel Hawke",
    objectives = "- The League of Arathor:",
    rewards = "380 XP",
