    isForever = false,
  },
  [2203] = {
    id = 2203,
    title = "Badlands Reagent Run II",
    reqLevel = 40,
    questLevel = 44,
    faction = "Horde",
    zone = "Badlands",
    npc = "Jarkal Mossmeld",
    objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath.",
    rewards = "3,750 XP",
    tip = "You have been most helpful to me, $c.  I would reward you with the very recipe for the brew I gave you earlier... but I would ask of you a task that is quite dangerous.  Hear my request.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be warned.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.",
    isForever = false,
  },
  [2501] = {
    id = 2501,
    title = "Badlands Reagent Run II",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Ghak Healtouch",
    objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Ghak Healtouch in Thelsamar.",
    rewards = "3,750 XP",
    tip = "You have been most helpful to me, $N.  I would like to reward you with the very recipe for the brew I gave you earlier, but I must ask of you a favor that is quite dangerous.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be careful.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.",
    isForever = false,
  },
  [4127] = {
    id = 4127,
    title = "Boat Wreckage",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Object: Wrecked Row Boat",
    objectives = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.",
    rewards = "375 XP",
    tip = "Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.\n\nYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water...",
    isForever = false,
  },
  [613] = {
    id = 613,
    title = "Cracking Maury's Foot",
    reqLevel = 30,
    questLevel = 44,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "\"Sea Wolf\" MacKinley",
    objectives = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.",
    rewards = "4,650 XP",
    tip = "Curses!  That swab Maury put a lock on his foot, and I can't open it!  His loot's inside the foot, and that's what he owes me!\n\nWe need to find the key to open the lock.  Maury was known to gamble with the Mosh'Ogg ogres, at their mound to the northeast.  And he told me, when he was still alive, that the last time he went to the mound he was chased off after winning too much.  Maybe the Ogres there have his key.\n\nBut if they do, you might have to kill a load of them to find the right one...",
    isForever = false,
  },
  [667] = {
    id = 667,
    title = "Death From Below",
    reqLevel = 35,
    questLevel = 44,
    faction = "Both",
    zone = "Arathi Highlands",
    npc = "Shakes O'Breen",
    objectives = "Protect Shakes O'Breen during the attack.",
    rewards = "4,650 XP",
    tip = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, $n?",
    isForever = false,
  },
  [8264] = {
    id = 8264,
    title = "Defiler's Standard Care Package",
    reqLevel = 35,
    questLevel = 44,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Rutherford Twing",
    objectives = "- The Defilers:",
    rewards = "380 XP",
