  },
  [2340] = {
    id = 2340,
    title = "Deliver the Gems",
    reqLevel = 37,
    questLevel = 44,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Jarkal Mossmeld",
    objectives = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.",
    rewards = "1,850 XP • 1g 25s",
    tip = "Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.\n\nI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.\n\nHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you.",
    isForever = false,
  },
  [2339] = {
    id = 2339,
    title = "Find the Gems and Power Source",
    reqLevel = 37,
    questLevel = 44,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Jarkal Mossmeld",
    objectives = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.",
    rewards = "3,750 XP",
    tip = "Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.\n\nLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.\n\nWhen you have everything collected, come back here!",
    isForever = false,
  },
  [1127] = {
    id = 1127,
    title = "Fool's Stout",
    reqLevel = 36,
    questLevel = 44,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Crank Fizzlebub",
    objectives = "Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.",
    rewards = "Experience & Faction Reputation",
    tip = "So you want some Fool's Stout, eh?  Thinking of heading back to the races...?\n\nAll right, bring me more of Zanzil's mixture and I'll make some more stout for you.",
    isForever = false,
  },
  [1430] = {
    id = 1430,
    title = "Fresh Meat",
    reqLevel = 35,
    questLevel = 44,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Dar",
    objectives = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.",
    rewards = "3,750 XP",
    tip = "There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers.\n\nIf you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar.\n\nThe coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.",
    isForever = false,
  },
  [1120] = {
    id = 1120,
    title = "Get the Gnomes Drunk",
    reqLevel = 35,
    questLevel = 44,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Bring the Fool's Stout to the Gnome Pit Boss.",
    rewards = "375 XP",
    tip = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.",
    isForever = false,
  },
  [1121] = {
    id = 1121,
    title = "Get the Goblins Drunk",
    reqLevel = 35,
    questLevel = 44,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Bring the Fool's Stout to the Goblin Pit Boss.",
    rewards = "375 XP",
    tip = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.",
    isForever = false,
  },
  [573] = {
    id = 573,
    title = "Mok'thardin's Enchantment",
    reqLevel = 33,
    questLevel = 44,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Far Seer Mok'thardin",
    objectives = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water.  He also wants you to kill 10 Naga Explorers.",
    rewards = "4,650 XP",
    tip = "There is but one final reagent needed to complete the enchantment.\n\nIn the south, towards the western coast, high above the bluffs, lies a Holy Spring.  This spring is the subject of great conflict amongst religious and mystical scholars.  Every race in Azeroth claims that the spring waters were made divine for their people.\n\nMy final request of you: bring to me Holy Spring Water.  Be warned.  An expedition of naga explorers have advanced upon the spring.  They will need to be dealt with as well",
    isForever = false,
  },
  [1691] = {
    id = 1691,
    title = "More Wastewander Justice",
    reqLevel = 40,
    questLevel = 44,
    faction = "Both",
    zone = "Tanaris",
    npc = "Chief Engineer Bilgewhizzle",
    objectives = "- Wastewander Rogue x 8 - Wastewander Assassin x 6 - Wastewander Shadow Mage x 10",
    rewards = "3,750 XP, 65s",
    tip = "We need you to take on the stronger ranks of the Wastewander nomads now.  You've done a good job thus far, but if we are to take back those water wells, then it only makes sense to do it against as few nomads as possible!\n\nThis time around we need you to take down their rogues, assassins, and shadow mages.  You'll find them east and southeast of here.\n\nI'm not going to lie to you - they're a nasty lot.  Do this for us though, and we'll be on our way to taking back what is rightfully ours!",
    isForever = false,
  },
  [2341] = {
    id = 2341,
    title = "Necklace Recovery, Take 3",
    reqLevel = 40,
    questLevel = 44,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Dran Droffers",
    objectives = "Visit Jarkal Mossmeld in Kargath to see if he was successful.",
    rewards = "5,600 XP",
    tip = "As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.",
    isForever = false,
  },
  [7867] = {
    id = 7867,
    title = "Outrider Standard Care Package",
    reqLevel = 35,
