  [4130] = {
    id = 4130,
    title = "Psychometric Reading",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Quintis Jonespyre",
    objectives = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
    rewards = "375 XP",
    tip = "I'm a little wobbly still, sorry.  Anyway, I received some useful visions.\n\nRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.\n\nI need to rest, sorry $N.  Tell Gin what I've seen.  He needs to kn",
    isForever = false,
  },
  [1122] = {
    id = 1122,
    title = "Report Back to Fizzlebub",
    reqLevel = 35,
    questLevel = 44,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Kravel Koalbeard",
    objectives = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.",
    rewards = "1,850 XP",
    tip = "That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!\n\nThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.\n\nAnd hopefully we can get more of that Fool's Stout for future races!",
    isForever = false,
  },
  [2204] = {
    id = 2204,
    title = "Restoring the Necklace",
    reqLevel = 37,
    questLevel = 44,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Talvash del Kissel",
    objectives = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.",
    rewards = "930 XP",
    tip = "You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.\n\nWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!",
    isForever = false,
  },
  [2361] = {
    id = 2361,
