  [1444] = {
    id = 1444,
    title = "Return to Fel'Zerul",
    reqLevel = 38,
    questLevel = 44,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Atal'ai Exile",
    objectives = "Return to Fel'Zerul in Stonard.",
    rewards = "3,750 XP",
    tip = "Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.\n\nHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.\n\nWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.\n\nThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....",
    isForever = false,
  },
  [3520] = {
    id = 3520,
    title = "Screecher Spirits",
    reqLevel = 40,
    questLevel = 44,
    faction = "Both",
    zone = "Tanaris",
    npc = "Yeh'kinya",
    objectives = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.",
    rewards = "3,750 XP",
    tip = "I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.\n\nTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.\n\nReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.",
    isForever = false,
  },
  [7864] = {
    id = 7864,
    title = "Sentinel Standard Care Package",
    reqLevel = 35,
    questLevel = 44,
    faction = "Alliance",
    zone = "Ashenvale",
    npc = "Illiyana Moonblaze",
    objectives = "Speak with Illiyana Moonblaze in Ashenvale.",
    rewards = "380 XP",
    tip = "",
    isForever = false,
  },
  [48] = {
    id = 48,
    title = "Sweet Amber",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Grimbooze Thunderbrew",
    objectives = "Bring Holy Spring Water to Grimbooze Thunderbrew.",
    rewards = "3,750 XP • 65s",
    tip = "In the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.",
    isForever = false,
  },
  [49] = {
    id = 49,
    title = "Sweet Amber",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Grimbooze Thunderbrew",
    objectives = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.",
    rewards = "4,650 XP • 1g 25s",
    tip = "Amber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.",
    isForever = false,
  },
  [50] = {
    id = 50,
    title = "Sweet Amber",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Grimbooze Thunderbrew",
    objectives = "Grimbooze Thunderbrew wants Truesilver.",
    rewards = "4,650 XP • 1g 25s",
    tip = "I'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.",
    isForever = false,
  },
  [51] = {
    id = 51,
    title = "Sweet Amber",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Grimbooze Thunderbrew",
    objectives = "Bring a Sycamore Branch to Grimbooze Thunderbrew.",
    rewards = "4,650 XP • 1g 25s",
    tip = "Not yet filtered but freshly distilled\nLike unseeded land waiting there tilled.\nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.",
    isForever = false,
  },
  [53] = {
    id = 53,
    title = "Sweet Amber",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Westfall",
    npc = "Grimbooze Thunderbrew",
    objectives = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.",
    rewards = "5,600 XP",
    tip = "Mellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.",
    isForever = false,
  },
  [4281] = {
    id = 4281,
    title = "Thalanaar Delivery",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Item: Undelivered Parcel",
    objectives = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.",
    rewards = "2,800 XP • 65s",
    tip = "This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished.\n\nExamining the parcel in detail reveals a hand written name of \"Falfindel Waywarder\" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient.",
    isForever = false,
  },
  [1429] = {
    id = 1429,
    title = "The Atal'ai Exile",
    reqLevel = 38,
    questLevel = 44,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Fel'zerul",
    objectives = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.",
    rewards = "3,750 XP",
    tip = "While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.\n\nThis priest was sentenced to a fate worse than death amongst the Atal'ai.\n\nHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.\n\nI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.",
    isForever = false,
  },
  [2982] = {
    id = 2982,
    title = "The High Wilderness",
    reqLevel = 39,
    questLevel = 44,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Angelas Moonbreeze",
    objectives = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.",
    rewards = "3,750 XP • 65s",
    tip = "Although it is dangerous, Troyas and I have been investigating the ruins that cover the forests of Feralas.\n\nLately, though, Troyas has been going on his own to the High Wilderness, and I really worry about him. The Gordunni Ogres have taken over that area, and they don't take kindly to anyone that enters their territory.\n\nI was hoping you might be willing to travel to the ruins to the southeast and clear out some of the ogres. Make it a little safer for my Troyas, and I will be extremely gratef",
    isForever = false,
  },
  [4129] = {
    id = 4129,
    title = "The Knife Revealed",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Ginro Hearthkindle",
    objectives = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.",
    rewards = "375 XP",
    tip = "The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.\n\nTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife.",
    isForever = false,
  },
  [2980] = {
    id = 2980,
    title = "The Ogres of Feralas",
    reqLevel = 38,
    questLevel = 44,
    faction = "Horde",
    zone = "Feralas",
    npc = "Rok Orhan",
    objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.",
    rewards = "3,750 XP • 1g 25s",
    tip = "Now that you have proven that you are a true fighter, I trust that you possess the courage to continue with the task at hand.\n\nTravel to the High Wilderness, southwest of here. There lie some abandoned and destroyed structures, on land that once belonged to the night elves. Look for these ruins, and when you see the withered trees and desecrated terrain, you will find the Gordunni. Push them back.\n\nThese ogres are much stronger than the ones you faced previously, $N. Be aware.",
    isForever = false,
  },
  [735] = {
    id = 735,
    title = "The Star, the Hand and the Heart",
    reqLevel = 30,
    questLevel = 44,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Gerrig Bonegrip",
    objectives = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.",
    rewards = "5,600 XP",
    tip = "Yagyin's Digest, eh?  Are you starting a new chapter of us, somewhere?  Never mind, it is not my place to ask.\n\nI will help you, for I have an extra copy.  We must aid each other, yes?  That is how we flourish.\n\nI require three items of power.  Bring them to me and I will give you the digest.\n\nI will not speak their names.  Ears may be on us.  But here, I will write them down.",
    isForever = false,
  },
  [736] = {
    id = 736,
    title = "The Star, the Hand and the Heart",
    reqLevel = 30,
    questLevel = 44,
    faction = "Horde",
    zone = "Undercity",
    npc = "Keeper Bel'dugur",
    objectives = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.",
    rewards = "5,600 XP",
    tip = "You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, $gbrother:sister;.\n\nBut you must help me too.\n\nI require three items of power.  Bring me these and the digest will be yours.\n\nI cannot utter the names of these items, but I will write them down.\n\nGet me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order.",
    isForever = false,
  },
  [4131] = {
    id = 4131,
    title = "The Woodpaw Gnolls",
    reqLevel = 40,
    questLevel = 44,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Ginro Hearthkindle",
    objectives = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.",
    rewards = "2,800 XP",
    tip = "Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.\n\nI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them",
    isForever = false,
  },
  [609] = {
    id = 609,
    title = "Voodoo Dues",
    reqLevel = 30,
    questLevel = 44,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "\"Sea Wolf\" MacKinley",
    objectives = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.",
    rewards = "3,750 XP • 65s",
    tip = "My list is shortening, but there are still people who owe me.\n\nNext, we have Maury \"Club Foot\" Wilkins, Jon-Jon the Crow, and Chucky \"Ten Thumbs.\"\n\nThese scurvy dogs' debts are months outstanding and I thought they skipped town to avoid paying up!  Later, I heard they're cursed and bewitched and now wander the jungle ruins.  But I don't care what their fate is - I want what's mine!\n\nThey're at the Ruins of Aboraz and the Ruins of Jubuwal, northeast of here.  Find them, and collect.",
    isForever = false,
  },
  [1707] = {
    id = 1707,
    title = "Water Pouch Bounty",
    reqLevel = 40,
    questLevel = 44,
    faction = "Both",
    zone = "Tanaris",
    npc = "Spigot Operator Luglunket",
    objectives = "Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan.",
    rewards = "2,800 XP",
    tip = "Greetings $n - the name's Luglunket, and we've got an important job for you if you're up for it!  Huzzah!\n\nNothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert.  That's our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in.  Most importantly though, you're helping Gadgetzan help itself!",
    isForever = false,
  },
  [1878] = {
    id = 1878,
    title = "Water Pouch Bounty",
    reqLevel = 40,
    questLevel = 44,
    faction = "Both",
    zone = "Tanaris",
    npc = "Spigot Operator Luglunket",
    objectives = "- Wastewander Water Pouch x 5",
    rewards = "375 XP",
    tip = "",
    isForever = false,
  },
  [1119] = {
    id = 1119,
    title = "Zanzil's Mixture and a Fool's Stout",
    reqLevel = 35,
    questLevel = 44,
    faction = "Both",
    zone = "Thousand Needles",
    npc = "Crank Fizzlebub",
    objectives = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.",
    rewards = "3,750 XP",
    tip = "I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.\n\nAnd $N, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.",
    isForever = false,
  },
  [621] = {
    id = 621,
    title = "Zanzil's Secret",
    reqLevel = 35,
    questLevel = 44,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Crank Fizzlebub",
    objectives = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.",
    rewards = "3,750 XP • 65s",
    tip = "Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...\n\nZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.\n\nHis mixture would be worth much to those who wish to control others.\n\nBring me samples of his mixture, and I will find a use for them.",
    isForever = false,
  },
  [2771] = {
    id = 2771,
    title = "A Good Head On Your Shoulders",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Trenton Lighthammer",
    objectives = "Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer.",
    rewards = "3,900 XP",
    tip = "It seems as if master had this planned from the start. I was not taught to create the items which you learned to create and you were not taught the items which I learned to create.\n\nThe master is wise, $N. We shall teach each other!\n\nShow me how to make a mithril coif and ornate mithril shoulders and I shall show you how to create an ornate mithril helm.",
    isForever = false,
  },
  [2974] = {
    id = 2974,
    title = "A Grim Discovery",
    reqLevel = 38,
    questLevel = 45,
    faction = "Horde",
    zone = "Feralas",
    npc = "Krueg Skullsplitter",
    objectives = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.",
    rewards = "3,900 XP • 65s",
    tip = "What!? You came across tauren in the area? You're joking! What did they look like!?\n\nThe Grimtotem clan! You found some of them? Belgrom, one of our masters, has an interest in their kind... he's even put a bounty on them.\n\nYou have to go back, $c. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.",
    isForever = false,
  },
  [2976] = {
    id = 2976,
    title = "A Grim Discovery",
    reqLevel = 37,
    questLevel = 45,
    faction = "Horde",
    zone = "Feralas",
    npc = "Krueg Skullsplitter",
    objectives = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.",
    rewards = "4,850 XP • 65s",
    tip = "What?!\n\nAh, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it?\n\nYou did the work, so I suppose it is only right you reap the greatest reward from it. Take the horns, I'll have them put in a crate for you. Find Belgrom Rockmaul in the Valley of Honor, he'll want to know what you saw and he'll reward you for your hard work.\n\nBe well, $c, and thank you again for everything you've done.",
    isForever = false,
  },
  [2973] = {
    id = 2973,
    title = "A New Cloak's Sheen",
    reqLevel = 38,
    questLevel = 45,
    faction = "Horde",
    zone = "Feralas",
    npc = "Krueg Skullsplitter",
    objectives = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.",
    rewards = "3,900 XP • 65s",
    tip = "Well met, $c. I've traveled with my companions down to the Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with gorgeous wings I want are west of Camp Mojache.",
    isForever = false,
  },
  [3121] = {
    id = 3121,
    title = "A Strange Request",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Feralas",
    npc = "Witch Doctor Uzer'i",
    objectives = "Take the Shrunken Head to Neeru Fireblade in Orgrimmar.",
    rewards = "1,950 XP",
    tip = "Neeru Fireblade in Orgrimmar has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.\n\nOff with you now -- to Orgrimmar. Here, take this with you. It's a shrunken head that I promised Neeru in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure Neeru will be pleased.\n\nYou'll find Neeru in the Cleft of Shadow.",
    isForever = false,
  },
  [2870] = {
    id = 2870,
    title = "Against Lord Shalzaru",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Latronicus Moonspear",
    objectives = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.",
    rewards = "2,900 XP • 50s",
    tip = "$n, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.\n\nSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.\n\nPut a stop to it by putting a stop to him, and bring me his relic so we can study it.",
    isForever = false,
  },
  [6625] = {
    id = 6625,
    title = "Alliance Trauma",
    reqLevel = 35,
    questLevel = 45,
    faction = "Alliance",
    zone = "First Aid",
    npc = "Nissa Firestone",
    objectives = "Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma.",
    rewards = "970 XP",
    tip = "Doctor $N, I presume. It is a pleasure to see you.\n\nI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!",
    isForever = false,
  },
  [8154] = {
    id = 8154,
    title = "Arathi Basin Resources!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Sergeant Maclear",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "3,900 XP • 1g 95s",
    tip = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [4449] = {
    id = 4449,
    title = "Caught!",
    reqLevel = 43,
    questLevel = 45,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Object: Wooden Outhouse",
    objectives = "Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.",
    rewards = "3,900 XP",
    tip = "Hey! Hey, you! Get over here!\n\nYa gotta help me out. I was runnin' from them Dark Iron dwarves, and I hid in here to get out of sight. Damn bastard geologists and their magic ways! They musta seen me hide, cause next thing I knew, they locked the door and stuck me in here.\n\nTeach them geologists a lesson! Oh... an' can ya get me some pieces of silk cloth for... for... nothin'.",
    isForever = false,
  },
  [1173] = {
    id = 1173,
    title = "Challenge Overlord Mok'Morokk",
    reqLevel = 38,
    questLevel = 45,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Overlord Mok'Morokk",
    objectives = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.",
    rewards = "4,850 XP",
    tip = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny $r!\n\nYou tell me when ready for good beating.",
    isForever = false,
  },
  [6610] = {
    id = 6610,
    title = "Clamlette Surprise",
    reqLevel = 35,
    questLevel = 45,
    faction = "Both",
    zone = "Cooking",
    npc = "Dirge Quikcleave",
    objectives = "Dirge Quikcleave wants you to get the following items:\n\n12 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\n\n10 pieces of Zesty Clam Meat. You can find those in clams, naturally!\n\n20 pieces of Alterac Swiss. Get thee to a cheesery!\n\nGather all of the items and return to Dirge.",
    rewards = "3,900 XP",
    tip = "Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, $N, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:",
    isForever = false,
  },
  [2935] = {
    id = 2935,
    title = "Consult Master Gadrin",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Apothecary Lydon",
    objectives = "Speak with Master Gadrin in Sen'jin Village.",
    rewards = "2,900 XP",
    tip = "The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.\n\nI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom.",
    isForever = false,
  },
  [1428] = {
    id = 1428,
    title = "Continued Threat",
    reqLevel = 35,
    questLevel = 45,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Katar",
    objectives = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.",
    rewards = "3,900 XP",
    tip = "It pleases me to see your hatred for the fish men grows with mine.\n\nFind more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.",
    isForever = false,
  },
  [2882] = {
    id = 2882,
    title = "Cuergo's Gold",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: Cuergo's Treasure Map",
    objectives = "Find Cuergo's gold!",
    rewards = "Experience & Faction Reputation",
    tip = "This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...\n\n\nSouth of Wheedle\nSouth of home\nFind a mast and flag and bones\nDig you there, if you be bold\nDig and claim Cuergo's gold!\nA key you'll need and a key you'll see\nThe men you face take blood as fee.",
    isForever = false,
  },
  [8160] = {
    id = 8160,
    title = "Cut Arathor Supply Lines",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathstalker Mortis",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "3,900 XP • 1g 95s",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
  [1205] = {
    id = 1205,
    title = "Deadmire",
    reqLevel = 35,
    questLevel = 45,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Melor Stonehoof",
    objectives = "Bring Deadmire's Tooth to Melor in Thunder Bluff.",
    rewards = "3,900 XP",
    tip = "Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.\n\nOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.\n\nYet now he lives in constant, maddening pain.  You must end the life of this noble creature, $N.  You must lead Deadmire to peace.",
    isForever = false,
  },
  [2874] = {
    id = 2874,
    title = "Deliver to MacKinley",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Tanaris",
    npc = "Stoley",
    objectives = "Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay.",
    rewards = "3,900 XP • 50s",
    tip = "Thanks again for your help, $N.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze.",
    isForever = false,
  },
  [2871] = {
    id = 2871,
    title = "Delivering the Relic",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Latronicus Moonspear",
    objectives = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.",
    rewards = "3,900 XP",
    tip = "If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!\n\nShe's just around the bend, no doubt studying.  Thanks, $n.",
    isForever = false,
  },
  [232] = {
    id = 232,
    title = "Errand for Apothecary Zinge",
    reqLevel = 38,
    questLevel = 45,
    faction = "Horde",
    zone = "Undercity",
    npc = "Apothecary Zinge",
    objectives = "Take the purchase order to Alessandro Luca in the Undercity.",
    rewards = "390 XP",
    tip = "The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan.\n\nApothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail",
    isForever = false,
  },
  [238] = {
    id = 238,
    title = "Errand for Apothecary Zinge",
    reqLevel = 38,
    questLevel = 45,
    faction = "Horde",
    zone = "Undercity",
    npc = "Alessandro Luca",
    objectives = "Bring the Field Sampling Kit to Apothecary Zinge in the Undercity.",
    rewards = "390 XP",
    tip = "The kit is ready, $n.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations.\n\nWell, don't just stand there.  Such is the life of a simple courier, yes?",
    isForever = false,
  },
  [2765] = {
    id = 2765,
    title = "Expert Blacksmith!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Galvan the Ancient",
    objectives = "Claim your reward from Galvan the Ancient!",
    rewards = "3,900 XP",
    tip = "When you first came to me, I knew that you would turn out to be one of my finest pupils! It was without hesitancy that you gave up a trinket of some power to McGavan. You did this only so that you could meet me. Such blind faith and devotion to the craft should be rewarded.\n\nYou have attained expertise over blacksmithing, $N. Reap the rewards!",
    isForever = false,
  },
  [3125] = {
    id = 3125,
    title = "Faerie Dragon Muisek",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Feralas",
    npc = "Witch Doctor Uzer'i",
    objectives = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.",
    rewards = "3,900 XP",
    tip = "$N, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, $N. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.",
    isForever = false,
  },
  [706] = {
    id = 706,
    title = "Fiery Blaze Enchantments",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Sigrun Ironhew",
    objectives = "Acquire a Black Drake's Heart for Sigrun Ironhew.",
    rewards = "3,900 XP",
    tip = "As an apprentice to Feranor Steeltoe, I learned his special technique for imbuing weapons with fiery enchantments. Last I heard of him, he was working at a smithy with a hunting party up in Lordaeron.\n\nI can't tell you too many of the details about the process, but I can tell you it requires blood from a rare, still-beating black drake whelp's heart. I don't have much to do waiting for word from Ironforge. If you bring me a heart from the whelps in Lethlor Ravine, I'll show you my skill!",
    isForever = false,
  },
  [2766] = {
    id = 2766,
    title = "Find OOX-22/FE!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Feralas",
    npc = "Item: OOX-22/FE Distress Beacon",
    objectives = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.",
    rewards = "3,900 XP",
    tip = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"",
    isForever = false,
  },
  [2764] = {
    id = 2764,
    title = "Galvan's Finest Pupil",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Galvan the Ancient",
    objectives = "Speak with Trenton Lighthammer in Gadgetzan.",
    rewards = "2,900 XP",
    tip = "If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.\n\nThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!\n\nOh, Gadgetzan is in Tanaris, of course!",
    isForever = false,
  },
  [6623] = {
    id = 6623,
    title = "Horde Trauma",
    reqLevel = 35,
    questLevel = 45,
    faction = "Horde",
    zone = "First Aid",
    npc = "Arnok",
    objectives = "Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma.",
    rewards = "970 XP",
    tip = "Doctor $N, I presume. It is a pleasure to see you again.\n\nI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!",
    isForever = false,
  },
  [6609] = {
    id = 6609,
    title = "I Got Nothin' Left!",
    reqLevel = 35,
    questLevel = 45,
    faction = "Alliance",
    zone = "Fishing",
    npc = "Grimnur Stonebrand",
    objectives = "Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!",
    rewards = "970 XP",
    tip = "I'm a dwarf fer cryin' out loud, $g lad:missy;! I ain't been designed to fish! I mean look at me! I'm practically made outta stone.\n\nI got nothin' left - ye tapped me out. I've taught ye all I know, flipflop!\n\nDon't ye get it? Ah, fine. I got an ol' friend over on Kalimdor who can help ye out. 'Is name be Nat Pagle, a fine lad. Find him on the islands south o' Theramore. Git goin'!",
    isForever = false,
  },
  [6612] = {
    id = 6612,
    title = "I Know A Guy...",
    reqLevel = 35,
    questLevel = 45,
    faction = "Alliance",
    zone = "Cooking",
    npc = "Daryl Riknussun",
    objectives = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.",
    rewards = "970 XP",
    tip = "I can tell by yer cooking spoon that ye know what yer doin'. Unfortunately, I can't teach ya nothin'.\n\nLuckily fer ye, I know a guy. He's a goblin and probably the best cook on Kalimdor.\n\nAyep, that's the bad news, $g lad:missy; - ye got to travel to Kalimdor. Git to Gadgetzan and find Dirge Quikcleave. He'll set ya straight.",
    isForever = false,
  },
  [7923] = {
    id = 7923,
    title = "Mark of Honor",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Warsong Mark of Honor for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to rage against the Silverwing Sentinels! Bring me more marks of honor!",
    isForever = false,
  },
  [2853] = {
    id = 2853,
    title = "Master of the Wild Leather",
    reqLevel = 30,
    questLevel = 45,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Pratt McGrubben",
    objectives = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.",
    rewards = "3,900 XP",
    tip = "Well $n, you are the definition of diligence.  There is one pattern left for Wild Leather armor; you've mastered the others.  I won't require you to toil needlessly for the pattern.  You've earned it outright, and then some... but I cannot give it to you myself.  My teacher, the one who brought me into the craft, is the one who must reward you.\n\nTake this letter to Telonis; he teaches leatherworking in Darnassus.  Show him the letter, and let him acknowledge you as an equal, as I do.",
    isForever = false,
  },
  [2860] = {
    id = 2860,
    title = "Master of the Wild Leather",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Jangdor Swiftstrider",
    objectives = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.",
    rewards = "3,900 XP",
    tip = "$n, you have learned all I am able to teach you.  There is, however, one remaining pattern for Wild Leather armor.  I will not require you to toil needlessly for this; you've earned it outright, and then some.  This pattern, however, is one that I cannot freely share with you.\n\nMy teacher, the one who brought me into the craft, is the one who must reward you.  Take this note to Una; she teaches leatherworking in Thunder Bluff.  Show her the letter, and let her acknowledge you as an equal, as I d",
    isForever = false,
  },
  [594] = {
    id = 594,
    title = "Message in a Bottle",
    reqLevel = 45,
    questLevel = 45,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Item: Carefully Folded Note",
    objectives = "Find the author of the message in a bottle.",
    rewards = "2,900 XP",
    tip = "The note reads, in fairly good handwriting:\n\nTo any that can aid me-\n\nPlease, my need for help is dire. A great Skymane holds me captive on an island in the South Seas.\n\nThe stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see Wild Shore to the northwest, and what seem to be large sailing ships to the southwest.\n\nI beg of you, my would-be savior, please help me.",
    isForever = false,
  },
  [8157] = {
    id = 8157,
    title = "More Resource Crates",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "",
    tip = "War must be fought with soldiers, any soldier will tell you. They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important. There are key areas in the basin that hold essential resources. Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N. Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [8163] = {
    id = 8163,
    title = "More Resource Crates",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi. They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe. We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N. Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman. Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
  [6607] = {
    id = 6607,
    title = "Nat Pagle, Angler Extreme",
    reqLevel = 35,
    questLevel = 45,
    faction = "Both",
    zone = "Fishing",
    npc = "Nat Pagle",
    objectives = "Nat Pagle wants you to catch the following fish:\n\nMisty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.\n\nA Sar'theris Striker from the Sar'theris Strand in Desolace.\n\nFeralas Ahi from the Verdantis River of Feralas.\n\nSavage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.\n\nReturn to Nat Pagle when you have reeled them all in!",
    rewards = "3,900 XP",
    tip = "Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now.\n\nI reckon people are driven to do what they do for different reasons.\n\nNow, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'.\n\nI'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:",
    isForever = false,
  },
  [8365] = {
    id = 8365,
    title = "Pirate Hats Ahoy!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Tanaris",
    npc = "Haughty Modiste",
    objectives = "Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.",
    rewards = "3,900 XP • 65s",
    tip = "You're the help the Cartel sent? I suppose you'll do. Listen carefully $c. As you know, I am a procurer of fashionable apparel for the elite of Azerothian society.  Kings and Queens, Warchiefs and, well whatever the Horde calls their queens, all wear what I choose is in style.  And they pay through the nose for it, which is the best part.\n\nSo here's what's going to happen. You head down to Lost Rigger Cove and acquire a lot of pirate hats by whatever means. Do you think you can handle that?",
    isForever = false,
  },
  [7875] = {
    id = 7875,
    title = "Quell the Silverwing Usurpers",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Captain Shatterskull",
    objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
    rewards = "3,900 XP • 1g 95s",
    tip = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.",
    isForever = false,
  },
  [2767] = {
    id = 2767,
    title = "Rescue OOX-22/FE!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Feralas",
    npc = "Homing Robot OOX-22/FE",
    objectives = "Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.",
    rewards = "4,850 XP",
    tip = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the dock along the Forgotten Coast!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely to the dock, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!",
    isForever = false,
  },
  [3122] = {
    id = 3122,
    title = "Return to Witch Doctor Uzer'i",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Feralas",
    npc = "Neeru Fireblade",
    objectives = "Deliver Neeru's Herb Pouch to Witch Doctor Uzer'i in Feralas.",
    rewards = "970 XP",
    tip = "Here are the herbs, $N. Take them to Witch Doctor Uzer'i.\n\nPlease let him know that I am satisfied with the shrunken head.",
    isForever = false,
  },
  [2865] = {
    id = 2865,
    title = "Scarab Shells",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Azeroth",
    npc = "Tran'rek",
    objectives = "Bring 9 Uncracked Scarab Shells to Tran'rek in Gadgetzan.",
    rewards = "3,900 XP • 65s",
    tip = "The scarabs of Tanaris have very hard shells!  Hard enough to use as a building material for lots of things.  So many things!\n\nIn fact, those shells are so useful... the scarabs were hunted all to near extinction!\n\nI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are.  Promise?\n\nOk, the scarabs have a colony in Zul'Farrak.  I guess the trolls don't hunt them for their shells.\n\nBut you can!  Go to Zul'Farrak and get me uncracked shells",
    isForever = false,
  },
  [7541] = {
    id = 7541,
    title = "Service to the Horde",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Zor Lonetree",
    objectives = "Speak with Zor Lonetree in Dustwallow Marsh.",
    rewards = "1,550 XP • 1g 50s",
    tip = "",
    isForever = false,
  },
  [2876] = {
    id = 2876,
    title = "Ship Schedules",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Tanaris",
    npc = "Item: Ship Schedule",
    objectives = "Report the Ship Schedules to an authority in Steamwheedle Port.",
    rewards = "4,850 XP • 1g 30s",
    tip = "This scroll contains the schedules of shipments between Steamwheedle Port and Booty Bay. Both past and future shipments are included, along with ship names, with large 'X's next to some ships' journeys, and annotations like \"GREAT LOOT\" and \"HARD FIGHT\" next to others.\n\nSomeone at Steamwheedle Port would want to see this document.",
    isForever = false,
  },
  [2761] = {
    id = 2761,
    title = "Smelt On, Smelt Off",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Galvan the Ancient",
    objectives = "Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn.",
    rewards = "3,900 XP",
    tip = "Many blacksmiths believe that mining and smithing are separate, independent jobs; but can there be blacksmithing without mining? Ah ha -- it is an impossibility! The accomplished blacksmith must also be an accomplished miner.\n\nShow Galvan that you are capable, $N. Bring me forty bars of iron and forty bars of mithril. For this, Galvan will teach you the ways of the ornate mithril pants!",
    isForever = false,
  },
  [8366] = {
    id = 8366,
    title = "Southsea Shakedown",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Tanaris",
    npc = "Security Chief Bilgewhizzle",
    objectives = "Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.",
    rewards = "3,900 XP • 65s",
    tip = "Argh! They want the impossible from me!\n\nThe Steamwheedle Cartel wants me to teach the Southsea pirates a lesson.  The problem is that I can't be in two places at once; I need to stay here to keep the peace.\n\nOf late, the pirates have been disregarding the protection money that the cartel regularly forks over. So I'd like to temporarily deputize you to go down there and show them what for.\n\nYou'll find them at Lost Rigger Cove, which is not too far to the south.  Thanks $N, I'll owe you one!",
    isForever = false,
  },
  [2872] = {
    id = 2872,
    title = "Stoley's Debt",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Tanaris",
    npc = "\"Sea Wolf\" MacKinley",
    objectives = "Speak with Stoley in Steamwheedle Port.",
    rewards = "390 XP",
    tip = "My old buddy Stoley owes me a very special bottle of rum.  He tends the bar at Steamwheedle Port in Tanaris, Kalimdor,  and he promised me that the rum there is stronger than anything we can find in Booty Bay.  He's so confident that he says if I try that rum and don't agree with him, then he'll double the money he owes me!\n\nWell, I think he's not as confident as he was when last we spoke, and now he's afraid to give me that rum.  But I don't back down from wagers, so why don't you talk to him f",
    isForever = false,
  },
  [2873] = {
    id = 2873,
    title = "Stoley's Shipment",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Tanaris",
    npc = "Stoley",
    objectives = "Bring Stoley's Shipment to Stoley in Steamwheedle Port.",
    rewards = "3,900 XP • 50s",
    tip = "I owe \"Sea Wolf\" MacKinley in Booty Bay some rum, to settle a bet, but I'm all out of rum!  Captain Cuergo stole my last shipment, and he has it stowed in that walled pirate town to the south.\n\nIf you can find my shipment of rum and return it to me, then I can prove to MacKinley that Kalimdor's booze beats the dirt out of Booty Bay!",
    isForever = false,
  },
  [348] = {
    id = 348,
    title = "Stranglethorn Fever",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Fin Fizracket",
    objectives = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage.  Bring the Heart of Mokk to Fin Fizracket.",
    rewards = "5,850 XP",
    tip = "Sick...so...very s-s-sick....\n\n...have contracted Stranglethorn Fever...deadly v-v-virus...\n\n...only cure...is...is...to eat the heart of M-m-m-m-mokk the Savage...elusive white beast...\n\n...Witch doctor Unbagwa...only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape...\n\n...hurry...dying...dying....",
    isForever = false,
  },
  [349] = {
    id = 349,
    title = "Stranglethorn Fever",
    reqLevel = 32,
    questLevel = 45,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Witch Doctor Unbagwa",
    objectives = "temp text 02 - log",
    rewards = "Experience & Faction Reputation",
    tip = "Hi, $N!\n\nSpeak with me friend Witch Doctor Unbagwa.",
    isForever = false,
  },
  [1395] = {
    id = 1395,
    title = "Supplies for Nethergarde",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Duskwood",
    npc = "Watchmaster Sorigal",
    objectives = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.",
    rewards = "2,900 XP • 50s",
    tip = "This crate of powerstones needs to go to Nethergarde Keep, in the Blasted Lands.  They won't hold their power for long, so we can't ship them with the next caravan.\n\nYou must take them, and you must take them quickly.\n\nBring them to Quartermaster Lungertz in Nethergarde Keep.  To reach the keep, you must travel east through Deadwind Pass, then east through the Swamp of Sorrows, then south through the Blasted Lands.\n\nUse caution, $N.  You will travel through dangerous lands, yet you must not fail",
    isForever = false,
  },
  [7888] = {
    id = 7888,
    title = "Talismans of Merit",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to aid the cause and bring me more talismans of merit. Do this, and you will earn even more of our trust.",
    isForever = false,
  },
  [2763] = {
    id = 2763,
    title = "The Art of the Imbue",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Galvan the Ancient",
    objectives = "Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn.",
    rewards = "3,900 XP",
    tip = "The harvesting of precious gems is of utmost importance to our craft, $N. Few gems are more precious than the citrine. The magical properties we imbue into our goods are amplified greatly by the presence of citrine.\n\nFor this lesson, we will fortify forty bars of mithril with four citrines. The result will be a better understanding of magical gemology and the knowledge to create ornate mithril shoulders.",
    isForever = false,
  },
  [8166] = {
    id = 8166,
    title = "The Battle for Arathi Basin!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Field Marshal Oslight",
    objectives = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.",
    rewards = "3,900 XP • 1g 30s",
    tip = "$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.",
    isForever = false,
  },
  [8169] = {
    id = 8169,
    title = "The Battle for Arathi Basin!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathmaster Dwire",
    objectives = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
    rewards = "3,900 XP • 1g 30s",
    tip = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, $N.  Report back to me when this task is compl",
    isForever = false,
  },
  [608] = {
    id = 608,
    title = "The Bloodsail Buccaneers",
    reqLevel = 37,
    questLevel = 45,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Fleet Master Seahorn",
    objectives = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.",
    rewards = "4,850 XP",
    tip = "Blast the nerve of Firallon!  He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us.\n\nThe Bloodsail Buccaneers will pay for their carelessness.  Now that we know their plan of attack, we can counter before they know what hit them.\n\nBut why send the entire fleet to do the work of one brave adventuring party?  $n, take some of your most skilled comrades out to Firallon's landing spot and assassinate the Bloodsail leadership.  Their fleet will sink soon after....",
    isForever = false,
  },
  [1172] = {
    id = 1172,
    title = "The Brood of Onyxia",
    reqLevel = 38,
    questLevel = 45,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Draz'Zilb",
    objectives = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.",
    rewards = "4,850 XP",
    tip = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.",
    isForever = false,
  },
  [588] = {
    id = 588,
    title = "The Fate of Yenniku",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Object: Bubbling Cauldron",
    objectives = "Speak with Kin'weelay.",
    rewards = "390 XP",
    tip = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, $c.\n\nPerhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt.",
    isForever = false,
  },
  [2762] = {
    id = 2762,
    title = "The Great Silver Deceiver",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Galvan the Ancient",
    objectives = "Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn.",
    rewards = "3,900 XP",
    tip = "It is said that truesilver is stronger and more durable than mithril. Galvan does not disagree with this assessment of the minerals, but contrary to its name, truesilver is not true! Mithril is a far nobler mineral! HAH! Regardless, for this lesson you will need to find the great silver deceiver, $N.\n\nBring me forty bars of mithril and five bars of truesilver. In exchange, you will be taught the secret of ornate mithril gloves and more importantly, learn that truesilver is a liar!",
    isForever = false,
  },
  [1139] = {
    id = 1139,
    title = "The Lost Tablets of Will",
    reqLevel = 35,
    questLevel = 45,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Advisor Belgrum",
    objectives = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.",
    rewards = "5,850 XP • 1g 30s",
    tip = "We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.\n\nWe must still recover the Tablet before the Shadowforge clan finds it.\n\nReturn to Uldaman, find the tablet, and return here immediately.",
    isForever = false,
  },
  [2773] = {
    id = 2773,
    title = "The Mithril Kid",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Trenton Lighthammer",
    objectives = "Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer.",
    rewards = "3,900 XP",
    tip = "Around these parts I am known as the Mithril Kid. I supply ornate mithril to adventurers from around the world.\n\n<Trenton whispers.>\n\nLittle do they know that I do not know the technique to fashion ornate mithril gloves. Shhhh! This will be our little secret.\n\nTeach me the technique to create ornate mithril gloves, $N, and in exchange, I will show you the resultant of the culmination of my training under Galvan: the ornate mithril breastplate.",
    isForever = false,
  },
  [589] = {
    id = 589,
    title = "The Singing Crystals",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Kin'weelay",
    objectives = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.",
    rewards = "3,900 XP",
    tip = "Legends tell of a jewel, hidden deep in the heart of Stranglethorn.  We call it the Mind's Eye, and it has great powers.  If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.\n\nI will consult with the spirits of the jungle to find the Mind's Eye.  While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks.  The shards are rare, but we will need their magic to bend the Mind's Eye to our will.",
    isForever = false,
  },
  [2936] = {
    id = 2936,
    title = "The Spider God",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Master Gadrin",
    objectives = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.",
    rewards = "4,850 XP",
    tip = "The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!\n\nTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.\n\nDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me.",
    isForever = false,
  },
  [2772] = {
    id = 2772,
    title = "The World At Your Feet",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Trenton Lighthammer",
    objectives = "- Heavy Mithril Boots x 2 - Ornate Mithril Pants",
    rewards = "3,900 XP",
    tip = "At last year's All-Valley Blacksmithing Championship, all those who watched saw my leg get swept from under me by a cowardly dog from the Venture Co. Foundry. What they didn't know, however, was the reason I was able to continue and ultimately win the tournament: That's right, ornate mithril boots!\n\nI will need to learn how to craft ornate mithril pants for this year's tournament, however, as a Venture Co. shredder is an entrant! Teach me the way of the pants and learn the way of the boot!",
    isForever = false,
  },
  [778] = {
    id = 778,
    title = "This Is Going to Be Hard",
    reqLevel = 35,
    questLevel = 45,
    faction = "Both",
    zone = "Badlands",
    npc = "Lotwil Veriatus",
    objectives = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.",
    rewards = "4,850 XP",
    tip = "Haha! Done! The shackles are done!\n\nIt's time, Lucien. It's time, Servo!\n\nAre you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, $N?\n\nI shall summon forth a powerful elemental now. This is a groundbreaking day for all of us.",
    isForever = false,
  },
  [1422] = {
    id = 1422,
    title = "Threat From the Sea",
    reqLevel = 35,
    questLevel = 45,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Tok'Kar",
    objectives = "Speak to Katar in the Swamp of Sorrows.",
    rewards = "Experience & Faction Reputation",
    tip = "While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.",
    isForever = false,
  },
  [6611] = {
    id = 6611,
    title = "To Gadgetzan You Go!",
    reqLevel = 35,
    questLevel = 45,
    faction = "Horde",
    zone = "Cooking",
    npc = "Zamja",
    objectives = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.",
    rewards = "970 XP",
    tip = "How you expect Zamja teach you anything? You got all of Zamja's cooking mojo and still you crave more!\n\nZamja can't help. Fat $r needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty.\n\nWhen you become big cook on the block, you come back and teach Zamja, ok? Now go!",
    isForever = false,
  },
  [2864] = {
    id = 2864,
    title = "Tran'rek",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Azeroth",
    npc = "Krazek",
    objectives = "Speak with Tran'rek in Gadgetzan.",
    rewards = "390 XP",
    tip = "My cousin Tran'rek is in a tight spot.  He promised me a load of scarab shells weeks ago and he hasn't delivered.  He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.\n\nCan you speak to Tran'rek for me?  Let him know he needs to get that delivery together before I do something rash?\n\nGadgetzan is in northern Tanaris, in Kalimdor.",
    isForever = false,
  },
  [6622] = {
    id = 6622,
    title = "Triage",
    reqLevel = 35,
    questLevel = 45,
    faction = "Horde",
    zone = "First Aid",
    npc = "Doctor Gregory Victor",
    objectives = "- 15 Patients Saved!",
    rewards = "3,900 XP",
    tip = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nTriage bandages will be supplied.\n\nGood luck, doctor.",
    isForever = false,
  },
  [6624] = {
    id = 6624,
    title = "Triage",
    reqLevel = 35,
    questLevel = 45,
    faction = "Alliance",
    zone = "First Aid",
    npc = "Doctor Gustaf VanHowzen",
    objectives = "- 15 Patients Saved!",
    rewards = "3,900 XP",
    tip = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nGood luck, doctor.",
    isForever = false,
  },
  [2880] = {
    id = 2880,
    title = "Troll Necklace Bounty",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Fraggar Thundermantle",
    objectives = "Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak.",
    rewards = "3,900 XP • 65s",
    tip = "Get this straight, $r - we are NOT part of the Alliance!  The Wildhammers are independent, relying on deeds and actions to prove one's worth, rather than the blather of those who use jibber-jabber to bolster their do-nothing attitudes!\n\nIf you're looking for friends here, then prove your worth to us first!  The foul trolls that choke the hillsides of the Hinterlands sometimes carry tribal necklaces.  Bring five of them to me, and we'll mark it down as a step in the right direction for you.",
    isForever = false,
  },
  [2881] = {
    id = 2881,
    title = "Troll Necklace Bounty",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Fraggar Thundermantle",
    objectives = "- Troll Tribal Necklace x 5",
    rewards = "390 XP",
    tip = "",
    isForever = false,
  },
  [3042] = {
    id = 3042,
    title = "Troll Temper",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Azeroth",
    npc = "Trenton Lighthammer",
    objectives = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.",
    rewards = "3,900 XP • 1g 95s",
    tip = "The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft, yes I can!  It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.\n\nZul'Farrak is northwest of Gadgetzan.  Good luck.",
    isForever = false,
  },
  [2934] = {
    id = 2934,
    title = "Undamaged Venom Sac",
    reqLevel = 40,
    questLevel = 45,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Apothecary Lydon",
    objectives = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill.",
    rewards = "3,900 XP",
    tip = "I must have a fresh sample of the venom you brought me.  The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me.  You will find many spiders near the troll city of Shadra'Alor.\n\nDo not tarry, $N, for the venom sac must be fresh when you deliver it.",
    isForever = false,
  },
  [7872] = {
    id = 7872,
    title = "Vanquish the Invaders!",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Sentinel Farsong",
    objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
    rewards = "3,900 XP • 1g 95s",
    tip = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.",
    isForever = false,
  },
  [1477] = {
    id = 1477,
    title = "Vital Supplies",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "High Sorcerer Andromath",
    objectives = "Speak with Watchmaster Sorigal.",
    rewards = "970 XP",
    tip = "Our mages are conducting research at Nethergarde Keep in the Blasted Lands, research vital to our understanding of the Dark Portals. They require nearly constant supplies, but our supply line to Nethergarde is tenuous.\n\nYou must help ensure the supplies make it to Nethergard.  Report to Watchmaster Sorigal in Darkshire, and do as he asks.  This task will take you into hostile lands, $N.  Prepare yourself.",
    isForever = false,
  },
  [2875] = {
    id = 2875,
    title = "WANTED: Andre Firebeard",
    reqLevel = 40,
    questLevel = 45,
    faction = "Both",
    zone = "Tanaris",
    npc = "Object: Wanted Poster",
    objectives = "Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port.",
    rewards = "3,900 XP • 1g 30s",
    tip = "The vile pirate Andre Firebeard is wanted for crimes against Steamwheedle and Gadgetzan.\n\nBy decree of governing counsel, any who read this are hereby authorized to use lethal force during the apprehension of Andre and his abettors.\n\nBy further decree, should Andre be deceased, or otherwise indisposed, during the time of his hearing, his head may act as proxy, and deliverance of such head to Security Chief Bilgewhizzle constitutes a binding, and tenderable, contract.",
    isForever = false,
  },
  [2847] = {
    id = 2847,
    title = "Wild Leather Armor",
    reqLevel = 30,
    questLevel = 45,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Pratt McGrubben",
    objectives = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold.",
    rewards = "1,950 XP",
    tip = "$n, you're becoming quite skilled as a leatherworker!  I know some patterns you might be interested in... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  The armor made using it is second to none for people of your skill, guaranteed.\n\nI'll teach this to you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk speci",
    isForever = false,
  },
  [2854] = {
    id = 2854,
    title = "Wild Leather Armor",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Jangdor Swiftstrider",
    objectives = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.",
    rewards = "1,950 XP",
    tip = "$n, your skill as a leatherworker precedes you.  I possess leatherworking lore you would be wise to acquire... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  Armor made using it is second to none for a crafter of your skill, guaranteed.\n\nI'll teach you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics",
    isForever = false,
  },
  [2851] = {
    id = 2851,
    title = "Wild Leather Boots",
    reqLevel = 30,
    questLevel = 45,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Pratt McGrubben",
    objectives = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
    rewards = "2,900 XP",
    tip = "You've learned quite a bit now, $n; still, there is more for you to learn.  Next are Wild Leather boots, the cornerstone of any set.\n\nThese boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need an order of two Nightscape pants and two Nightscape boots filled.  I also will require two wildvines... not just one.  When you have all this, let me know.",
    isForever = false,
  },
  [2850] = {
    id = 2850,
    title = "Wild Leather Helmet",
    reqLevel = 30,
    questLevel = 45,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Pratt McGrubben",
    objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
    rewards = "2,900 XP",
    tip = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random enhancement to the frame of the helm.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, two Nightscape headbands, and a wildvine.  Complete this order and the pattern will be yours!",
    isForever = false,
  },
  [2857] = {
    id = 2857,
    title = "Wild Leather Helmet",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Jangdor Swiftstrider",
    objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
    rewards = "2,900 XP",
    tip = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random magic imbuement to the helm's frame.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, 2 Nightscape headbands, and a wildvine.  Complete this lesson and the pattern will be yours!",
    isForever = false,
  },
  [2852] = {
    id = 2852,
    title = "Wild Leather Leggings",
    reqLevel = 30,
    questLevel = 45,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Pratt McGrubben",
    objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
    rewards = "2,900 XP",
    tip = "With the basics down, you are ready to master more complex fare, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor this pattern, I need an order of two Turtle Scale helms, two Turtle Scale bracers, and two wildvines filled.",
    isForever = false,
  },
  [2859] = {
    id = 2859,
    title = "Wild Leather Leggings",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Jangdor Swiftstrider",
    objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",
    rewards = "2,900 XP",
    tip = "You are ready to master more complex lessons, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor you to gain this pattern, I need two Turtle Scale helms, two Turtle Scale bracers, and two wildvines.",
    isForever = false,
  },
  [2848] = {
    id = 2848,
    title = "Wild Leather Shoulders",
    reqLevel = 30,
    questLevel = 45,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Pratt McGrubben",
    objectives = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
    rewards = "2,900 XP",
    tip = "Wild Leather shoulders support the wearer's frame extremely well, offering top notch protection of the upper arms and the shoulders themselves.  As with all Wild Leather armor, a potent but random benefit is applied to the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.",
    isForever = false,
  },
  [2855] = {
    id = 2855,
    title = "Wild Leather Shoulders",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Jangdor Swiftstrider",
    objectives = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
    rewards = "2,900 XP",
    tip = "Wild Leather shoulders support a wearer's frame extremely well, offering superior protection of the upper arms as well as the shoulders.  As with all Wild Leather armor, a random yet very potent enhancement is imbued within the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.",
    isForever = false,
  },
  [2849] = {
    id = 2849,
    title = "Wild Leather Vest",
    reqLevel = 30,
    questLevel = 45,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Pratt McGrubben",
    objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
    rewards = "2,900 XP",
    tip = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.",
    isForever = false,
  },
  [2856] = {
    id = 2856,
    title = "Wild Leather Vest",
    reqLevel = 30,
    questLevel = 45,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Jangdor Swiftstrider",
    objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
    rewards = "2,900 XP",
    tip = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.",
    isForever = false,
  },
  [2988] = {
    id = 2988,
    title = "Witherbark Cages",
    reqLevel = 40,
    questLevel = 45,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Gryphon Master Talonaxe",
    objectives = "Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe.",
    rewards = "3,900 XP",
    tip = "The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.\n\nYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there.",
    isForever = false,
  },
  [6608] = {
    id = 6608,
    title = "You Too Good.",
    reqLevel = 35,
    questLevel = 45,
    faction = "Horde",
    zone = "Fishing",
    npc = "Lumak",
    objectives = "You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said).",
    rewards = "970 XP",
    tip = "Lumak no can teach $N no more. You too good! Find Lumak friend, Nat Pagle. Is human but no eat! Is Lumak friend! Nat teach you fish gooder.\n\nYou find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!",
    isForever = false,
  },
  [7730] = {
    id = 7730,
    title = "Zukk'ash Infestation",
    reqLevel = 39,
    questLevel = 45,
    faction = "Horde",
    zone = "Feralas",
    npc = "Hadoken Swiftstrider",
    objectives = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.",
    rewards = "3,900 XP • 65s",
    tip = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not if they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.\n\nDrive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork",
    isForever = false,
  },
  [4266] = {
    id = 4266,
    title = "A Hero's Welcome",
    reqLevel = 40,
    questLevel = 46,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Ginro Hearthkindle",
    objectives = "Speak with Shandris Feathermoon in Feathermoon Stronghold.",
    rewards = "6,050 XP",
    tip = "$N, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.\n\nGeneral Feathermoon is waiting for you in the main compound.",
    isForever = false,
  },
  [841] = {
    id = 841,
    title = "Another Power Source?",
    reqLevel = 38,
    questLevel = 46,
    faction = "Horde",
    zone = "Tanaris",
    npc = "Chief Engineer Bilgewhizzle",
    objectives = "Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source.",
    rewards = "Experience & Faction Reputation",
    tip = "Let me guess - you didn't get whatever world-ending, nefarious deed you were doing done in time.  No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you.  This time, however, it will cost you ten, YES TEN Wastewander Water Pouches!\n\nTimes are tough all around, $n, and power sources don't grow on trees!  Hrm, but what if they did.  Maybe we could MAKE a power source tree...",
    isForever = false,
  },
  [2979] = {
    id = 2979,
    title = "Dark Ceremony",
    reqLevel = 38,
    questLevel = 46,
    faction = "Horde",
    zone = "Feralas",
    npc = "Rok Orhan",
    objectives = "Rok Orhan in Camp Mojache wants you to find a Gordunni Orb.",
    rewards = "4,050 XP",
    tip = "These seem to be plans for some sort of dark ceremony, $N. From what I can make out, this ritual is conducted by the Gordunni mage-lords.\n\nFind one of these mage-lords, and from him, gather an orb.\n\nThe orb of a mage contains great power, and will help us discover more about this ceremony and the magic that the Gordunni wield.",
    isForever = false,
  },
  [593] = {
    id = 593,
    title = "Filling the Soul Gem",
    reqLevel = 1,
    questLevel = 46,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Yenniku",
    objectives = "- Soul Gem",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [4265] = {
    id = 4265,
    title = "Freed from the Hive",
    reqLevel = 40,
    questLevel = 46,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Object: Zukk'ash Pod",
    objectives = "Free Raschal from the Zukk'ash hive.\n\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.",
    rewards = "4,050 XP",
    tip = "The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.\n\n\"Thank Elune - you've saved me, friend!  I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me.  Were you sent by the Stronghold?\"\n\nIt would seem that you've found the missing courier!",
    isForever = false,
  },
  [992] = {
    id = 992,
    title = "Gadgetzan Water Survey",
    reqLevel = 38,
    questLevel = 46,
    faction = "Both",
    zone = "Tanaris",
    npc = "Senior Surveyor Fizzledowser",
    objectives = "Use the untapped dowsing widget near the pool of water by Sandsorrow Watch.  Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.",
    rewards = "3,050 XP • 35s",
    tip = "We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!\n\nWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.\n\nTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!",
    isForever = false,
  },
  [243] = {
    id = 243,
    title = "Into the Field",
    reqLevel = 38,
    questLevel = 46,
    faction = "Horde",
    zone = "Tanaris",
    npc = "Apothecary Zinge",
    objectives = "Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit.",
    rewards = "2,000 XP",
    tip = "You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type.\n\nIn addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit.\n\nReturn to me only when you are success",
    isForever = false,
  },
  [4450] = {
    id = 4450,
    title = "Ledger from Tanaris",
    reqLevel = 43,
    questLevel = 46,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Object: Wooden Outhouse",
    objectives = "Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.",
    rewards = "5,050 XP",
    tip = "Oh, you know what? That reminds me.\n\nYou wanna finish up a little job I took up while I was in Tanaris? It's easy...\n\nKrinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places. Maybe you could take a look at the list and then bring it all to him?\n\nI'll just slide his ledger under the door if you're interested. Take that, and the stuff he wants back to him after ya collected it all.",
    isForever = false,
  },
  [206] = {
    id = 206,
    title = "Mai'Zoth",
    reqLevel = 30,
    questLevel = 46,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Brother Nimetz",
    objectives = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.",
    rewards = "5,050 XP",
    tip = "Kurzen may be dead, but...that which drove him to evil still lives!  Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn.  He is rumored to employ mind-controlling magic, and I am positive that he corrupted Kurzen.\n\nIf Mai'Zoth is allowed to live, then his evil may influence others, and may even cause another Kurzen to surface.\n\nKill him, and bring me his Mind's Eye, the artifact he uses to corrupt others.",
    isForever = false,
  },
  [864] = {
    id = 864,
    title = "Return to Apothecary Zinge",
    reqLevel = 38,
    questLevel = 46,
    faction = "Horde",
    zone = "Undercity",
    npc = "Chief Engineer Bilgewhizzle",
    objectives = "Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity.",
    rewards = "5,050 XP • 1g 30s",
    tip = "\"Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all.\"\n\nThe goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there.",
    isForever = false,
  },
  [4267] = {
    id = 4267,
    title = "Rise of the Silithid",
    reqLevel = 40,
    questLevel = 46,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Shandris Feathermoon",
    objectives = "Bring Raschal's Report to Gracina Spiritmight in Darnassus.",
    rewards = "405 XP",
    tip = "I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.\n\nYou're dismissed - good luck, $N; may Elune watch over us all.",
    isForever = false,
  },
  [592] = {
    id = 592,
    title = "Saving Yenniku",
    reqLevel = 30,
    questLevel = 46,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Kin'weelay",
    objectives = "Bring the Filled Soul Gem to Nimboya.",
    rewards = "5,050 XP",
    tip = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nThen, bring the gem to Nimboya.\n\nYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.",
    isForever = false,
  },
  [379] = {
    id = 379,
    title = "Slake That Thirst",
    reqLevel = 38,
    questLevel = 46,
    faction = "Horde",
    zone = "Tanaris",
    npc = "Chief Engineer Bilgewhizzle",
    objectives = "Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan.",
    rewards = "3,050 XP",
    tip = "You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ.\n\nNow... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you.",
    isForever = false,
  },
  [586] = {
    id = 586,
    title = "Speaking with Gan'zulah",
    reqLevel = 30,
    questLevel = 46,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Object: Bubbling Cauldron",
    objectives = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.\n\nBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.",
    rewards = "4,050 XP",
    tip = "<The head of Gan'zulah speaks.>\n\nCurse you!  And curse your ancestors!!\n\nOnly blood and revenge can cool my rage, so if that is your wish, then... do this:\n\nThrow yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can!\n\nMay he tear off your limbs and leave you to rot and be eaten by carrion.",
    isForever = false,
  },
  [2861] = {
    id = 2861,
    title = "Tabetha's Task",
    reqLevel = 40,
    questLevel = 46,
    faction = "Both",
    zone = "Azeroth",
    npc = "Ursyn Ghull",
    objectives = "Speak with Tabetha in Dustwallow Marsh.",
    rewards = "405 XP",
    tip = "Rumor is that Tabetha, a mage colleague who lives deep in Dustwallow Marsh, has a bone to pick with a certain sand troll in Zul'Farrak.  If you speak with Tabetha she can tell you more.\n\nAnd bring some friends with you, $N.  If Tabetha has you go to Zul'Farrak then you're not going to want to go alone.\n\nYou will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruin.",
    isForever = false,
  },
  [654] = {
    id = 654,
    title = "Tanaris Field Sampling",
    reqLevel = 38,
    questLevel = 46,
    faction = "Horde",
    zone = "Tanaris",
    npc = "Item: Model 4711-FTZ Power Source",
    objectives = "Acquire acceptable samples for 8 basilisks, 8 hyenas, and 8 scorpions.  Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out.",
    rewards = "4,050 XP",
    tip = "Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned.\n\nAccording to Chief Engineer Bilgewhizzle, you now have two hours to collect the data you need in the Tanaris desert.  If you do not collect it within two hours, all the data will be lost and you will need to buy another power source from him.\n\nReturn to him when you have completed the task.",
    isForever = false,
  },
  [2769] = {
    id = 2769,
    title = "The Brassbolts Brothers",
    reqLevel = 40,
    questLevel = 46,
    faction = "Alliance",
    zone = "Thousand Needles",
    npc = "Klockmort Spannerspan",
    objectives = "Speak with Wizzle Brassbolts in the Shimmering Flats.",
    rewards = "405 XP",
    tip = "Have you met the Brassbolts brothers?  They're over in the Shimmering Flats, in Kalimdor, racing their rocket car against the goblins.  They usually win which is no surprise--the goblin car blows up so much it barely ever crosses the finish line!\n\nBut even then, the Brassbolts brothers are always looking for new ways to make their car go faster, and Wizzle told me he needs a very rare component for his next experiment.\n\nHe probably needs help getting that part.  Speak to him and find out.",
    isForever = false,
  },
  [2821] = {
    id = 2821,
    title = "The Mark of Quality",
    reqLevel = 40,
    questLevel = 46,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Pratt McGrubben",
    objectives = "Bring 10 Thick Yeti Hides to Pratt McGrubben in Feathermoon Stronghold.",
    rewards = "4,050 XP",
    tip = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises.  Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides.  The Yeti are native to Feralas, with many found in Feral Scar Vale.  I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair to you, then we're in business.",
    isForever = false,
  },
  [2822] = {
    id = 2822,
    title = "The Mark of Quality",
    reqLevel = 40,
    questLevel = 46,
    faction = "Horde",
    zone = "Feralas",
    npc = "Jangdor Swiftstrider",
    objectives = "Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.",
    rewards = "4,050 XP",
    tip = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found west of here in Feral Scar Vale.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!",
    isForever = false,
  },
  [591] = {
    id = 591,
    title = "The Mind's Eye",
    reqLevel = 30,
    questLevel = 46,
    faction = "Horde",
    zone = "Stranglethorn Vale",
    npc = "Kin'weelay",
    objectives = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.",
    rewards = "5,050 XP",
    tip = "The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.",
    isForever = false,
  },
  [4135] = {
    id = 4135,
    title = "The Writhing Deep",
    reqLevel = 40,
    questLevel = 46,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Object: Large Leather Backpacks",
    objectives = "Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps.",
    rewards = "3,050 XP",
    tip = "Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.\n\nThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".\n\nIt would seem that you have located where Raschal ultimately w",
    isForever = false,
  },
  [2846] = {
    id = 2846,
    title = "Tiara of the Deep",
    reqLevel = 40,
    questLevel = 46,
    faction = "Both",
    zone = "Azeroth",
    npc = "Tabetha",
    objectives = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.",
    rewards = "6,050 XP • 65s",
    tip = "Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep.  And not only was it pretty--it held great power for those with the knowledge to use it.\n\nSo when word of the tiara reached the Hydromancer Velratha, she had to have it.  She sent agents to my home and they stole it while I was away.  The thieves!\n\nI want my tiara back!  Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her.  Return it to me and you'll earn my favor.",
    isForever = false,
  },
  [2781] = {
    id = 2781,
    title = "WANTED: Caliph Scorpidsting",
    reqLevel = 39,
    questLevel = 46,
    faction = "Both",
    zone = "Tanaris",
    npc = "Object: Wanted Poster",
    objectives = "Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.",
    rewards = "5,050 XP • 1g 30s",
    tip = "WANTED: Caliph Scorpidsting!\n\nThe Gadgetzan Water Company of Gadgetzan, Tanaris will pay a high bounty for the head of Caliph Scorpidsting, leader of the Wastewander outlaws.  His crimes include:\n\n1.  Murdering Gadgetzan Water Co. employees!\n2.Stealing Gadgetzan Water Co. resources!\n3.Seizing Gadgetzan Water Co. property!\n\nBring proof of Caliph Scorpidsting's demise to Chief Engineer Bilgewhizzle for an immediate reward!",
    isForever = false,
  },
  [2750] = {
    id = 2750,
    title = "A Bad Egg",
    reqLevel = 42,
    questLevel = 47,
    faction = "Both",
    zone = "Tanaris",
    npc = "Curgle Cranklehop",
    objectives = "- Bad Egg",
    rewards = "9s",
    tip = "",
    isForever = false,
  },
  [5536] = {
    id = 5536,
    title = "A Land Filled with Hatred",
    reqLevel = 45,
    questLevel = 47,
    faction = "Both",
    zone = "Azshara",
    npc = "Loh'atu",
    objectives = "Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale.",
    rewards = "4,200 XP • 70s",
    tip = "The satyr, a disfigured, evil aspect of the night elves, now infect the sacred lands once traveled by Cenarius. I cannot speak for the night elves when it comes to all the atrocities those demonic creatures have committed, but I have sworn an oath to the Earthmother to aid the elves in ridding the land of such a nuisance.\n\nI am sure you would prove yourself if you aided me in purging them.\n\nNortheast of here, you can find the Haldarr clan. Return to me after you've tested yourself against their ",
    isForever = false,
  },
  [3842] = {
    id = 3842,
    title = "A Short Incubation",
    reqLevel = 38,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Quentin",
    objectives = "Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.",
    rewards = "2,100 XP",
    tip = "The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.\n\nSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.\n\nI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here wi",
    isForever = false,
  },
  [3841] = {
    id = 3841,
    title = "An Orphan Looking For a Home",
    reqLevel = 38,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Kindal Moonweaver",
    objectives = "Speak to Quentin in Thousand Needles.",
    rewards = "1,050 XP",
    tip = "Oh, hello, $N. I'm so glad to see you again. How was your trip to Darnassus?\n\nWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.\n\nSay, would you want one for a pet? They look to hatch soon, so they'll need a good $Gfather:mother;. What do you say?\n\nIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more",
    isForever = false,
  },
  [2768] = {
    id = 2768,
    title = "Divino-matic Rod",
    reqLevel = 40,
    questLevel = 47,
    faction = "Both",
    zone = "Azeroth",
    npc = "Chief Engineer Bilgewhizzle",
    objectives = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.",
    rewards = "6,300 XP",
    tip = "Sergeant Bly stole from me!  He said he'd only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??\n\nFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west.  I bet you'll find him there.\n\nLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight.",
    isForever = false,
  },
  [2970] = {
    id = 2970,
    title = "Doling Justice",
    reqLevel = 38,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Jer'kai Moonweaver",
    objectives = "Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas.",
    rewards = "3,150 XP",
    tip = "As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.\n\nYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons.",
    isForever = false,
  },
  [2972] = {
    id = 2972,
    title = "Doling Justice",
    reqLevel = 38,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Jer'kai Moonweaver",
    objectives = "Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus.",
    rewards = "5,250 XP",
    tip = "Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.\n\nWe both thank you, $N.",
    isForever = false,
  },
  [3661] = {
    id = 3661,
    title = "Favored of Elune?",
    reqLevel = 42,
    questLevel = 47,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Erelas Ambersky",
    objectives = "Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.",
    rewards = "4,200 XP • 1g 35s",
    tip = "Wildkin are quite unpredictable creatures, $N. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.\n\nThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.\n\nRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?",
    isForever = false,
  },
  [2940] = {
    id = 2940,
    title = "Feralas: A History",
    reqLevel = 42,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Object: Feralas: A History",
    objectives = "Ask Daryn Lightwind if you may borrow her book.",
    rewards = "420 XP",
    tip = "This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.\n\nYou pick it up, but realize you should probably ask before borrowing it.",
    isForever = false,
  },
  [4297] = {
    id = 4297,
    title = "Food for Baby",
    reqLevel = 38,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Agnar Beastamer",
    objectives = "Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.",
    rewards = "4,200 XP",
    tip = "Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.\n\nI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatch",
    isForever = false,
  },
  [2969] = {
    id = 2969,
    title = "Freedom for All Creatures",
    reqLevel = 38,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Kindal Moonweaver",
    objectives = "Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.\n\nYou have 6 minutes before Kindal decides it is time to retreat and you fail the quest.",
    rewards = "3,150 XP",
    tip = "The filthy Grimtotem clan are capturing faerie dragons, $N. Jer'kai and I have no idea what they plan on doing with them, but they're obviously up to no good.\n\nWe're not powerful enough to fight our way into the camp and free the captured dragons, but perhaps with your help...\n\nIf you're willing, and you have some strong friends, release the creatures from their cage with this key and make sure they escape with their lives. I'll be by your side the entire time. Jer'kai will remain here.",
    isForever = false,
  },
  [3630] = {
    id = 3630,
    title = "Gnome Engineering",
    reqLevel = 30,
    questLevel = 47,
    faction = "Alliance",
    zone = "Engineering",
    npc = "Lilliam Sparkspindle",
    objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",
    rewards = "420 XP",
    tip = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n$N, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!",
    isForever = false,
  },
  [3632] = {
