    isForever = false,
  },
  [3634] = {
    id = 3634,
    title = "Gnome Engineering",
    reqLevel = 30,
    questLevel = 47,
    faction = "Alliance",
    zone = "Engineering",
    npc = "Tinkerwiz",
    objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",
    rewards = "420 XP",
    tip = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely often work.\n\n$N, read this manual.  If you wish to learn how to make metal paper weights, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing h",
    isForever = false,
  },
