  [3526] = {
    id = 3526,
    title = "Goblin Engineering",
    reqLevel = 30,
    questLevel = 47,
    faction = "Horde",
    zone = "Engineering",
    npc = "Graham Van Talen",
    objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
    rewards = "420 XP",
    tip = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n$N, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",
    isForever = false,
  },
  [3629] = {
    id = 3629,
    title = "Goblin Engineering",
    reqLevel = 30,
    questLevel = 47,
    faction = "Alliance",
    zone = "Engineering",
    npc = "Springspindle Fizzlegear",
    objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
    rewards = "420 XP",
    tip = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n$N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his ta",
    isForever = false,
  },
