  [3022] = {
    id = 3022,
    title = "Handle With Care",
    reqLevel = 42,
    questLevel = 47,
    faction = "Alliance",
    zone = "Tanaris",
    npc = "Curgle Cranklehop",
    objectives = "Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village.",
    rewards = "2,100 XP • 50s",
    tip = "$N, I can see you yearn to be dedicated to my worthwhile cause. Yes, of course, you can do something for me!\n\nTake this crate of eggs to Erelas Ambersky. He is a druid that cares for these eggs, helping them to hatch and then training the young hippogryphs. You will find him in Teldrassil, in a small village to the south called Rut'theran.",
    isForever = false,
  },
  [3124] = {
    id = 3124,
    title = "Hippogryph Muisek",
    reqLevel = 40,
    questLevel = 47,
    faction = "Horde",
    zone = "Feralas",
    npc = "Witch Doctor Uzer'i",
    objectives = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.",
    rewards = "4,200 XP",
    tip = "Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.\n\nHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.\n\nYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here.",
    isForever = false,
  },
  [2939] = {
    id = 2939,
    title = "In Search of Knowledge",
    reqLevel = 42,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Troyas Moonbreeze",
    objectives = "Talk to Daryn Lightwind in Rut'theran Village.",
    rewards = "420 XP",
    tip = "While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.\n\nSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.\n\nI have a colleague in Darnassus that may be able to tell us what this is, $N. Why don't you go talk to her and see if she can h",
    isForever = false,
  },
  [2995] = {
    id = 2995,
    title = "Lines of Communication",
    reqLevel = 42,
    questLevel = 47,
    faction = "Horde",
    zone = "Undercity",
    npc = "Oran Snakewrithe",
    objectives = "Oran Snakewrithe in Undercity wants you to travel to the Hinterlands and burn the Highvale Records, Highvale Report, and Highvale Notes.",
    rewards = "3,150 XP • 70s",
    tip = "The Quel'Danil Lodge is a center of communication for the high elves of the Hinterlands. Their ambassadors are working to establish relationships with other races, with whom they share their knowledge of the Witherbark trolls that inhabit the area in the southern Hinterlands. All of the documents regarding the communications are kept at the lodge.\n\nWe don't need the Highvale building alliances with others, $N.\n\nDestroy the Highvale documents.  We need to burn their lines of communication... lite",
    isForever = false,
  },
