  [2991] = {
    id = 2991,
    title = "Nekrum's Medallion",
    reqLevel = 40,
    questLevel = 47,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Thadius Grimshade",
    objectives = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.",
    rewards = "5,250 XP • 70s",
    tip = "I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.\n\nZul'Farrak is across the ocean to the west, in the desert of Tanaris.",
    isForever = false,
  },
  [82] = {
    id = 82,
    title = "Noxious Lair Investigation",
    reqLevel = 39,
    questLevel = 47,
    faction = "Both",
    zone = "Tanaris",
    npc = "Senior Surveyor Fizzledowser",
    objectives = "Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.",
    rewards = "3,150 XP • 50s",
    tip = "All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.\n\nLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!",
    isForever = false,
  },
  [8273] = {
