  [2993] = {
    id = 2993,
    title = "Return to the Hinterlands",
    reqLevel = 40,
    questLevel = 47,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Thadius Grimshade",
    objectives = "Speak with Gryphon Master Talonaxe.",
    rewards = "2,100 XP",
    tip = "Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.\n\nThere.  I have done my part.  I bid you fortune on your quest, $N.",
    isForever = false,
  },
  [2742] = {
    id = 2742,
    title = "Rin'ji is Trapped!",
    reqLevel = 42,
    questLevel = 47,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Rin'ji",
    objectives = "Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east.",
    rewards = "4,200 XP",
    tip = "Hey $r!\n\nRin'ji lost axe and was captured! Please, help Rin'ji escape. Me know that $r like you don't like Rin'ji's kind, but Rin'ji begs! Must get out of here!\n\nGot something for nice $r if $Ghe helps Rin'ji out of here:she helps Rin'ji out of here;...\n\nRin'ji is hiding something secret at the Overlook Cliffs.",
    isForever = false,
  },
  [2782] = {
    id = 2782,
    title = "Rin'ji's Secret",
    reqLevel = 42,
    questLevel = 47,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Object: Rin'ji's Secret",
    objectives = "Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity.",
    rewards = "2,100 XP",
    tip = "The tablet is covered with Witherbark troll markings. Rin'ji's secret truly is a mystery... \n\nIt's possible that you might have something quite valuable on your hands here. On the other hand, quite the opposite is also possible. A Witherbark troll in distress would probably do anything to find his way out of trouble...",
    isForever = false,
  },
  [3639] = {
    id = 3639,
    title = "Show Your Work",
    reqLevel = 30,
    questLevel = 47,
    faction = "Both",
    zone = "Engineering",
    npc = "Nixx Sprocketspring",
    objectives = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan.",
    rewards = "3,150 XP",
    tip = "As your mentor, I want samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is analyze them for ways to emphasize goblin-oriented techniques in your future efforts.  I need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!\n\nSubmit these items to me and I will issue you your own Goblin Engineer Membership Card; it is required for access to all goblin engineering tr",
    isForever = false,
  },
  [3641] = {
    id = 3641,
    title = "Show Your Work",
    reqLevel = 30,
    questLevel = 47,
    faction = "Alliance",
    zone = "Engineering",
    npc = "Tinkmaster Overspark",
    objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge.",
    rewards = "3,150 XP",
    tip = "As your mentor, I want some samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is to analyze your work for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and I will issue you your own Gnome Engineer Membership Card; it is required for access to all gnome engineering trainers!",
    isForever = false,
  },
  [3643] = {
    id = 3643,
    title = "Show Your Work",
    reqLevel = 30,
    questLevel = 47,
    faction = "Horde",
    zone = "Engineering",
    npc = "Oglethorpe Obnoticus",
    objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay.",
    rewards = "3,150 XP",
