    isForever = false,
  },
  [5535] = {
    id = 5535,
    title = "Spiritual Unrest",
    reqLevel = 45,
    questLevel = 47,
    faction = "Both",
    zone = "Azshara",
    npc = "Loh'atu",
    objectives = "Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara.",
    rewards = "4,200 XP • 50s",
    tip = "Long ago, the Highborne were some of the most powerful students of the arcane the night elves ever produced. The corruption that comes along with such studies caused much harm to night elf society and greatly affected all of Azeroth... as I'm sure you well know.\n\nI promised the Sentinels that I would release the spirits from their mortal bonds as I find them. If you would do the same, then I am sure I can reward you some.\n\nThe spirits haunt the Shadowsong Shrine to the northeast of here.",
    isForever = false,
  },
  [7731] = {
    id = 7731,
    title = "Stinglasher",
    reqLevel = 39,
    questLevel = 47,
    faction = "Horde",
    zone = "Feralas",
    npc = "Hadoken Swiftstrider",
    objectives = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.",
    rewards = "4,200 XP • 1g 35s",
    tip = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.\n\nThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!",
    isForever = false,
  },
  [3123] = {
    id = 3123,
    title = "Testing the Vessel",
    reqLevel = 40,
    questLevel = 47,
    faction = "Horde",
    zone = "Feralas",
    npc = "Witch Doctor Uzer'i",
    objectives = "Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.\n\nBring 10 Wildkin Muiseks and the Muisek Vessel to Witch Doctor Uzer'i in Feralas.",
    rewards = "4,200 XP",
    tip = "This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, $N. With it, you will have the power to shrink and capture a creature inside of it.\n\nTravel to the Hinterlands and look for creatures known as Wildkin that were once pets of the night elf goddess Elune. The vicious, primitive, or savage owlbeasts are your targets, $N. Kill 10, and use the muisek vessel to shrink and capture them before their spirits can escape.",
    isForever = false,
  },
  [2990] = {
    id = 2990,
    title = "Thadius Grimshade",
    reqLevel = 40,
    questLevel = 47,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Gryphon Master Talonaxe",
    objectives = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.",
    rewards = "2,100 XP",
    tip = "Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!\n\nAnd perhaps his talents can help us find Sharpbeak.\n\nThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.\n\nGood luck, $N.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep.",
    isForever = false,
  },
  [8551] = {
    id = 8551,
    title = "The Captain's Chest",
    reqLevel = 40,
    questLevel = 47,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Captain Hecklebury Smotts",
    objectives = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
    rewards = "3,150 XP",
    tip = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.",
    isForever = false,
  },
  [2992] = {
    id = 2992,
    title = "The Divination",
    reqLevel = 40,
    questLevel = 47,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Thadius Grimshade",
    objectives = "Wait until Grimshade performs the ritual of divination.",
    rewards = "1,050 XP",
    tip = "Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.\n\nThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes.",
    isForever = false,
  },
  [3002] = {
    id = 3002,
    title = "The Gordunni Orb",
    reqLevel = 38,
    questLevel = 47,
    faction = "Horde",
    zone = "Feralas",
    npc = "Rok Orhan",
    objectives = "Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar.",
    rewards = "2,100 XP",
    tip = "Although I know my enemy well, I am a warrior, $N. I cannot begin to tell you what this orb is capable of.\n\nI know of a mage in Orgrimmar that will be able to tell us more about the orb. Take it to him.",
    isForever = false,
  },
  [4451] = {
    id = 4451,
    title = "The Key to Freedom",
    reqLevel = 43,
    questLevel = 47,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Item: Grimesilt Outhouse Key",
    objectives = "Search Searing Gorge and find a use for the Grimesilt Outhouse Key you have found.",
    rewards = "5,250 XP",
    tip = "The small brass key looks simple enough.. The only thing that seems to make it stand out are some words scratched into the head of it:\n\n\"Dark Iron Outhouse - Do Not Duplicate.\"\n\nYou have no idea what it means or what it will lead to.",
    isForever = false,
  },
  [3843] = {
    id = 3843,
    title = "The Newest Member of the Family",
    reqLevel = 38,
    questLevel = 47,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Quentin",
    objectives = "Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.",
    rewards = "4,200 XP",
    tip = "A magnificent specimen, $N. If this creature survives gestation, then it'll be a healthy pet indeed!\n\nThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.\n\nBut hurry, $N, this egg is fragile and will not last long without proper care.",
    isForever = false,
  },
  [2278] = {
    id = 2278,
    title = "The Platinum Discs",
    reqLevel = 40,
    questLevel = 47,
    faction = "Both",
    zone = "Azeroth",
    npc = "Object: The Discs of Norgannon",
    objectives = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.",
    rewards = "4,200 XP",
    tip = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!",
    isForever = false,
  },
  [2279] = {
    id = 2279,
    title = "The Platinum Discs",
    reqLevel = 40,
    questLevel = 47,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Object: The Discs of Norgannon",
    objectives = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.",
    rewards = "5,250 XP",
    tip = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.",
    isForever = false,
  },
  [2280] = {
    id = 2280,
    title = "The Platinum Discs",
    reqLevel = 40,
    questLevel = 47,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Object: The Discs of Norgannon",
    objectives = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.",
    rewards = "5,250 XP",
    tip = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The sages of Thunder Bluff are such historians, known throughout the Horde; perhaps they can make good use of it.",
    isForever = false,
  },
  [2439] = {
    id = 2439,
    title = "The Platinum Discs",
    reqLevel = 40,
    questLevel = 47,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "High Explorer Magellas",
    objectives = "Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.",
    rewards = "420 XP",
    tip = "This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.\n\nAs for you, heroic $c, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!\n\nReturn to me directly when you are ready; there is much more to do for the Explorers' League!",
    isForever = false,
  },
  [2440] = {
    id = 2440,
    title = "The Platinum Discs",
    reqLevel = 40,
    questLevel = 47,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Sage Truthseeker",
    objectives = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.",
    rewards = "420 XP",
    tip = "I shall focus my energies on these discs; they will reveal their true workings to me in due time.\n\nAs for you $N, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.\n\nReturn to me soon, as I sense there is much more at hand for us to do regarding this find.",
    isForever = false,
  },
  [3638] = {
    id = 3638,
    title = "The Pledge of Secrecy",
    reqLevel = 30,
    questLevel = 47,
    faction = "Both",
    zone = "Engineering",
    npc = "Nixx Sprocketspring",
    objectives = "If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan.",
    rewards = "420 XP",
    tip = "Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a goblin engineer, that's that.  There is no access to gnome engineering at all.\n\nIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefull",
    isForever = false,
  },
  [3640] = {
    id = 3640,
    title = "The Pledge of Secrecy",
    reqLevel = 30,
    questLevel = 47,
    faction = "Alliance",
    zone = "Engineering",
    npc = "Tinkmaster Overspark",
    objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge.",
    rewards = "420 XP",
    tip = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",
    isForever = false,
  },
  [3642] = {
    id = 3642,
    title = "The Pledge of Secrecy",
    reqLevel = 30,
    questLevel = 47,
    faction = "Horde",
    zone = "Engineering",
    npc = "Oglethorpe Obnoticus",
    objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay.",
    rewards = "420 XP",
    tip = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",
    isForever = false,
  },
  [3527] = {
    id = 3527,
    title = "The Prophecy of Mosh'aru",
    reqLevel = 40,
    questLevel = 47,
    faction = "Both",
    zone = "Azeroth",
    npc = "Yeh'kinya",
    objectives = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.",
    rewards = "5,250 XP",
    tip = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.\n\nBring me the Mosh'aru tablets!\n\nThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\n\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\n\nWhen you have the tablets, bring them to m",
    isForever = false,
  },
  [8893] = {
    id = 8893,
    title = "The Super Egg-O-Matic",
    reqLevel = 42,
    questLevel = 47,
    faction = "Both",
    zone = "Tanaris",
    npc = "Object: Egg-O-Matic",
    objectives = "- Hippogryph Egg",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [7028] = {
    id = 7028,
    title = "Twisted Evils",
    reqLevel = 41,
    questLevel = 47,
    faction = "Both",
    zone = "Maraudon",
    npc = "Willow",
    objectives = "Collect 25 Theradric Crystal Carvings for Willow in Desolace.",
    rewards = "5,250 XP",
    tip = "The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it, $c. Relics of the old gods lie hidden behind the giant doors.\n\nIf you are willing to brave the twisted evils found in Maraudon, I believe I can make it worth your time. Collect the theradric crystal carvings you find, and return them to me.\n\nOnce I get the carvings, I will be able to... study them. These powers have been too long at re",
    isForever = false,
  },
  [7029] = {
    id = 7029,
    title = "Vyletongue Corruption",
    reqLevel = 41,
    questLevel = 47,
    faction = "Horde",
    zone = "Maraudon",
    npc = "Vark Battlescar",
    objectives = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.",
    rewards = "5,250 XP",
    tip = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, $N. Fill it at the orange crystal pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...",
    isForever = false,
  },
  [7041] = {
    id = 7041,
    title = "Vyletongue Corruption",
    reqLevel = 41,
    questLevel = 47,
    faction = "Alliance",
    zone = "Maraudon",
    npc = "Talendria",
    objectives = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.",
    rewards = "5,250 XP",
    tip = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, $N. Fill it at the corrupted orange pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you..",
    isForever = false,
  },
  [77] = {
    id = 77,
    title = "A Sticky Situation",
    reqLevel = 42,
    questLevel = 48,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Gilveradin Sunchaser",
    objectives = "Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock.",
    rewards = "4,400 XP",
    tip = "I possess original packaging materials for the ripple Dran Droffers seeks.  I will assist you in packaging the ripple for Malton's abrasive father... for a fee of two additional bottles of said ripple.  They are located in crates found in the abandoned Horde base near Skulk Rock.\n\nIt will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze.  Regardless, procure the ripple and return to me here for packaging.",
    isForever = false,
  },
  [7842] = {
    id = 7842,
    title = "Another Message to the Wildhammer",
    reqLevel = 44,
    questLevel = 48,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Otho Moji'ko",
    objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.\n\nGryphons are known to inhabit every region of the Hinterlands.",
    rewards = "5,450 XP",
    tip = "They say the Wildhammer and gryphon are as close to each other as troll and mate. Disgusting, but we be able to use this to our advantage, mon. We send them another message.\n\nKill all the gryphons you see in the Hinterlands, collect their feathers. From this we make the final message.",
    isForever = false,
  },
  [3201] = {
    id = 3201,
    title = "At Last!",
    reqLevel = 40,
    questLevel = 48,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Curator Thorius",
    objectives = "Take the Proof of Deed back to Mountaineer Pebblebitty.",
    rewards = "4,400 XP",
    tip = "I can't believe Pebblebitty doubted the authenticity of the horn. Between you and me, I think she's just jealous. I know she really wanted to kill that beast herself, what with the 'incident' and all.\n\nSo you need a proof of deed? After the contribution you just made to the museum, it won't be a problem.\n\n<Curator Thorius begins to fill out a large document.>\n\nThere we go! You can take that back to Pebblebitty.",
    isForever = false,
  },
  [7830] = {
    id = 7830,
    title = "Avenging the Fallen",
    reqLevel = 44,
    questLevel = 48,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Huntsman Markhor",
    objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.\n\nMarkhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.",
    rewards = "4,400 XP • 1g 40s",
    tip = "The filth that calls itself Wildhammer trains gryphon to slay troll. Horrible, I know, but worry not, justice will soon be meted out.\n\nFor now, I want you to focus on eradicating the elder gryphons of the region. They are known as Skylords.\n\nSlay one and return to me with its plume.",
    isForever = false,
  },
  [4298] = {
