  [7844] = {
    id = 7844,
    title = "Cannibalistic Cousins",
    reqLevel = 44,
    questLevel = 48,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Mystic Yayo'jin",
    objectives = "- Vilebranch Scalper x 30 - Vilebranch Soothsayer x 15",
    rewards = "4,400 XP, 1g 40s",
    tip = "Three different tribes of trolls inhabit the Hinterlands, $N. That is about as far as the similarities between the tribes extends: We are all trolls and we live in the Hinterlands.\n\nThe Vilebranch - aptly named - are a depraved lot; feeding on other trolls and humanoids.\n\nIf Zul'jin were here, he would have destroyed the whole lot of them with a flick of his wrist - alas, Zul'jin has not yet returned and we are left to our own devices.\n\nIt is up to you to destroy the filth of the region!",
    isForever = false,
  },
