  [485] = {
    id = 485,
    title = "Find OOX-09/HL!",
    reqLevel = 43,
    questLevel = 48,
    faction = "Both",
    zone = "The Hinterlands",
    npc = "Item: OOX-09/HL Distress Beacon",
    objectives = "Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock.",
    rewards = "4,400 XP",
    tip = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk ",
    isForever = false,
  },
  [351] = {
    id = 351,
    title = "Find OOX-17/TN!",
    reqLevel = 43,
    questLevel = 48,
    faction = "Both",
    zone = "Tanaris",
    npc = "Item: OOX-17/TN Distress Beacon",
    objectives = "Bring the distress beacon to Oglethorpe's homing robot.",
    rewards = "4,400 XP",
    tip = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!\"",
    isForever = false,
  },
  [3443] = {
    id = 3443,
    title = "Forging the Shaft",
    reqLevel = 40,
    questLevel = 48,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Kalaran Windblade",
    objectives = "- Thorium Plated Dagger x 8",
    rewards = "4,400 XP, 1g 40s",
    tip = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.\n\nThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft.",
    isForever = false,
  },
  [7721] = {
    id = 7721,
    title = "Fuel for the Zapping",
    reqLevel = 45,
    questLevel = 48,
    faction = "Both",
    zone = "Feralas",
    npc = "Zorbin Fandazzle",
    objectives = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.",
    rewards = "4,400 XP • 70s",
    tip = "If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say!\n\nFortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!",
    isForever = false,
  },
  [3161] = {
    id = 3161,
    title = "Gahz'ridian",
    reqLevel = 43,
    questLevel = 48,
    faction = "Both",
    zone = "Tanaris",
    npc = "Marvon Rivetseeker",
    objectives = "Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.",
    rewards = "4,400 XP",
    tip = "$N, I'm a scientist, but also a treasure hunter at heart!\n\nLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian\", after the hydra god.\n\nI did find some myself, but I'd like to have some more to study -- maybe you can find some?\n\nI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search beg",
    isForever = false,
  },
  [7816] = {
    id = 7816,
    title = "Gammerita, Mon!",
    reqLevel = 44,
    questLevel = 48,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Katoom the Angler",
    objectives = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.\n\nKatoom mentioned that Gammerita hangs out on the coast with the other turtles.",
    rewards = "4,400 XP • 1g 40s",
    tip = "Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.\n\nMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.\n\nFind Gammerita and get my lure out of her stomach.",
    isForever = false,
  },
  [7829] = {
    id = 7829,
    title = "Hunt the Savages",
    reqLevel = 44,
    questLevel = 48,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Huntsman Markhor",
    objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.\n\nMarkhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.",
    rewards = "4,400 XP • 1g 40s",
    tip = "Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts.\n\nKill every savage owlbeast you see, $r. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.",
    isForever = false,
  },
  [7733] = {
    id = 7733,
    title = "Improved Quality",
    reqLevel = 40,
    questLevel = 48,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Pratt McGrubben",
    objectives = "Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.",
    rewards = "4,400 XP • 70s",
    tip = "I have a lead on an even BETTER source of hides, if that's even possible to believe!  In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis.  They're much tougher than the ones you dealt with before, so if you're up for a bigger challenge you'd best be on your toes!\n\nI would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.",
    isForever = false,
  },
  [7734] = {
