    isForever = false,
  },
  [110] = {
    id = 110,
    title = "Insect Part Analysis",
    reqLevel = 39,
    questLevel = 48,
    faction = "Both",
    zone = "Tanaris",
    npc = "Senior Surveyor Fizzledowser",
    objectives = "Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.",
    rewards = "440 XP",
    tip = "I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.\n\nI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me.",
    isForever = false,
  },
  [113] = {
    id = 113,
    title = "Insect Part Analysis",
    reqLevel = 39,
    questLevel = 48,
    faction = "Both",
    zone = "Tanaris",
    npc = "Alchemist Pestlezugg",
    objectives = "Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan.  Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.",
    rewards = "440 XP • 70s",
    tip = "Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.\n\nHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!",
    isForever = false,
  },
  [7729] = {
    id = 7729,
    title = "JOB OPPORTUNITY: Culling the Competition",
    reqLevel = 45,
    questLevel = 48,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Object: Wanted/Missing/Lost & Found",
    objectives = "Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.",
    rewards = "4,400 XP • 2g 10s",
    tip = "Taskmaster Scrange is looking for a few good men and women to help 'cull the competition' in the Searing Gorge.\n\nIf you are interested in this position, venture out into the Searing Gorge and slaughter every Dark Iron Taskmaster and Dark Iron Slaver that you see.\n\nReturn to Taskmaster Scrange when your clothes are bloody enough.\n\nYou'll know when they're bloody enough so don't ask.",
    isForever = false,
  },
  [7841] = {
    id = 7841,
    title = "Message to the Wildhammer",
    reqLevel = 44,
    questLevel = 48,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Otho Moji'ko",
    objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.\n\nYou can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.",
    rewards = "4,400 XP",
    tip = "The Wildhammer be striking up deals with our enemies, forgin' new alliances. This time, they be workin' with the high elves, mon.\n\n<Otho spits.>\n\nWe be needin' to send those Wildhammer dwarves a message - a message in the blood of our enemies. Slaughter every Highvale high elf that you come across, leave their bodies as a warnin'.\n\nNever mess with trolls!",
    isForever = false,
  },
  [7738] = {
    id = 7738,
    title = "Perfect Yeti Hide",
    reqLevel = 40,
    questLevel = 48,
    faction = "Horde",
    zone = "Feralas",
    npc = "Item: Perfect Yeti Hide",
    objectives = "Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas.",
    rewards = "440 XP • 7s",
    tip = "You have found what may very well be a perfect yeti hide.  You easily note that it is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Jangdor Swiftstrider at Camp Mojache is in the market for yeti hides, this particular one may be of considerable interest to him.",
    isForever = false,
  },
