  [3182] = {
    id = 3182,
    title = "Proof of Deed",
    reqLevel = 40,
    questLevel = 48,
    faction = "Alliance",
    zone = "Loch Modan",
    npc = "Mountaineer Pebblebitty",
    objectives = "Take Margol's Gigantic Horn to Curator Thorius in Ironforge.",
    rewards = "4,400 XP, 1g 40s",
    tip = "You expect me to believe a story like that? The real horn would have had my broken axe head still lodged into its surface.\n\nListen, take that obvious fake to Curator Thorius in Ironforge. If he can validate your claim, you will receive a proof of deed. Bring that proof back to me and I'll give you the key to the Searing Gorge.\n\nGet going!",
    isForever = false,
  },
  [836] = {
    id = 836,
    title = "Rescue OOX-09/HL!",
    reqLevel = 43,
    questLevel = 48,
    faction = "Both",
    zone = "The Hinterlands",
    npc = "Homing Robot OOX-09/HL",
    objectives = "Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay.",
    rewards = "5,450 XP",
    tip = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the shoreline beyond Overlook Cliff!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely to the shore, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - ou",
    isForever = false,
  },
  [648] = {
    id = 648,
    title = "Rescue OOX-17/TN!",
    reqLevel = 43,
    questLevel = 48,
    faction = "Both",
    zone = "Tanaris",
    npc = "Homing Robot OOX-17/TN",
    objectives = "Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.",
    rewards = "5,450 XP",
    tip = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, Steamwheedle Port!  That should be a perfect place, and long enough, to get things on line!\"\n\n\"Escort it safely to the port, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"",
    isForever = false,
  },
  [2943] = {
    id = 2943,
    title = "Return to Troyas",
    reqLevel = 42,
