  [2845] = {
    id = 2845,
    title = "Wandering Shay",
    reqLevel = 44,
    questLevel = 49,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Shay Leafrunner",
    objectives = "Pick up Shay's Bell from the chest.\n\nEscort Shay Leafrunner to Rockbiter's camp.",
    rewards = "4,550 XP",
    tip = "Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.\n\nThere is one thing that will always work to get my attention, though.\n\nInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back.",
    isForever = false,
  },
  [2583] = {
    id = 2583,
    title = "A Boar's Vitality",
    reqLevel = 45,
    questLevel = 50,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Bloodmage Drazial",
    objectives = "- Blasted Boar Lung x 3 - Scorpok Pincer x 2 - Basilisk Brain",
    rewards = "4,700 XP",
    tip = "Within these blasted lands exists two species of boar: the ash-mane boar and the helboar.\n\nIt would appear that the stamina of these beasts renders them nearly immune to harm, as the other animals find them too difficult to kill and consequently, not worth the effort.\n\nWe need to perform further analysis, $N. Should you bring me three blasted boar lungs, two scorpok pincers, and one basilisk brain, I shall create a divine elixir from the residue of the assay. You will be my first test subject!",
    isForever = false,
  },
  [5066] = {
    id = 5066,
    title = "A Call to Arms: The Plaguelands!",
    reqLevel = 50,
    questLevel = 50,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Crier Goodman",
    objectives = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.",
    rewards = "470 XP",
    tip = "Hear ye, hear ye!  All heroes are called upon to heed these words!\n\nA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!\n\nHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!",
