  [2964] = {
    id = 2964,
    title = "A Future Task",
    reqLevel = 45,
    questLevel = 50,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Historian Karnik",
    objectives = "Speak with High Explorer Magellas in Ironforge.",
    rewards = "4,700 XP • 2g 20s",
    tip = "Well $n... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.\n\nThe High Explorer needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again aiding the League.",
    isForever = false,
  },
  [2968] = {
    id = 2968,
    title = "A Future Task",
    reqLevel = 45,
    questLevel = 50,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Nara Wildmane",
    objectives = "Speak with Sage Truthseeker in Thunder Bluff.",
    rewards = "4,700 XP • 2g 20s",
    tip = "Well $n... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.\n\nSage Truthseeker needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again heeding the call.",
    isForever = false,
  },
