  [793] = {
    id = 793,
    title = "Broken Alliances",
    reqLevel = 40,
    questLevel = 50,
    faction = "Horde",
    zone = "Badlands",
    npc = "Gorn",
    objectives = "Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.$b$bPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$b$bSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.",
    rewards = "5,900 XP",
    tip = "The Seal of the Earth is held by three runestones, held in the Pillars of Diamond, Opal, and Amethyst in Lethlor Ravine. Using the Sign of the Earth, you will be able to remove the runestones and unlock the Seal of the Earth.\n\nBe wary though, $n, the black drakes Blacklash and Hematus are not to be trifled with. See them dead and return their bindings to me.\n\nTo reach the ravine, travel to the far eastern part of the Badlands.  Be careful though, for the ravine is home to countless drakes.",
    isForever = false,
  },
  [3062] = {
    id = 3062,
    title = "Dark Heart",
    reqLevel = 45,
    questLevel = 50,
    faction = "Horde",
    zone = "Feralas",
    npc = "Talo Thornhoof",
    objectives = "Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.",
    rewards = "5,900 XP",
    tip = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her deat",
    isForever = false,
  },
  [7850] = {
    id = 7850,
    title = "Dark Vessels",
    reqLevel = 46,
    questLevel = 50,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Primal Torntusk",
    objectives = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.",
    rewards = "5,900 XP",
    tip = "The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx.\n\nThroughout Jintha'alor you will find dark vessels of tainted blood. The vessels radiate the foul magic of the faceless blood God, empowering the Vilebranch and also driving them to madness.\n\nSteal those vessels and return them to me so that I may remove the taint and ultimately loosen the grip of the blood God.",
    isForever = false,
  },
  [3321] = {
    id = 3321,
    title = "Did You Lose This?",
    reqLevel = 40,
    questLevel = 50,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Trenton Lighthammer",
    objectives = "Wait for Trenton to finish his work.",
    rewards = "7,100 XP",
    tip = "You have done much for the Order, $N. The sheer dedication it takes to get this far would have turned away any ordinary person. There is no doubt in my mind, or in the mind of Galvan, that you are one of us.\n\nWhich is why I think you deserve a little reward. It is nothing really, just a trinket. You may be familiar with its properties, as I do believe it is what brought you to us in the first place.",
    isForever = false,
  },
  [8410] = {
    id = 8410,
    title = "Elemental Mastery",
    reqLevel = 50,
    questLevel = 50,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Beram Skychaser",
    objectives = "Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher.",
    rewards = "3,800 XP",
    tip = "Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready.\n\nTo find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides.",
    isForever = false,
  },
  [618] = {
    id = 618,
    title = "Facing Negolash",
    reqLevel = 40,
    questLevel = 50,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Sprogger",
    objectives = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",
    rewards = "7,100 XP",
    tip = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!",
    isForever = false,
  },
