  [2770] = {
    id = 2770,
    title = "Gahz'rilla",
    reqLevel = 40,
    questLevel = 50,
    faction = "Both",
    zone = "Azeroth",
    npc = "Wizzle Brassbolts",
    objectives = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.",
    rewards = "7,100 XP • 75s",
    tip = "Deep in Zul'Farrak, the sand troll city in Tanaris, there is a sacred pool.  From that pool the trolls summon a huge beast!  Gahz'rilla!  He's so fierce that even his scales crackle with energy.  It's that energy I want to harness for my car!\n\nBring me the electrified scale of Gahz'rilla!\n\nBut the summoning of Gahz'rilla is a well-kept secret of the trolls.  To face him, you must first wrest the secret from them.",
    isForever = false,
  },
