  [3385] = {
    id = 3385,
    title = "The Undermarket",
    reqLevel = 46,
    questLevel = 50,
    faction = "Both",
    zone = "Herbalism",
    npc = "Nilith Lokrav",
    objectives = "- Trade Master Kovic - Clunk - Trader's Satchel",
    rewards = "4,700 XP",
    tip = "They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price.\n\nIt gets worse, $N. They have set up a base of operations here in the Searing Gorge. Trade Master Kovic is heading up the operation and has close ties with the Dark Iron dwarves of the region.\n\nWe must strike hard and send a message to their leadership. Slay Trade Master Kovic and his minion Clunk. Bring back his trader's satchel when the job is done.\n\nTo the Cauldr",
    isForever = false,
  },
  [3402] = {
    id = 3402,
    title = "The Undermarket",
    reqLevel = 43,
    questLevel = 50,
    faction = "Both",
    zone = "Herbalism",
    npc = "Nilith Lokrav",
    objectives = "Speak with Vizzklick in Gadgetzan.",
    rewards = "4,700 XP, 75s",
    tip = "I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.",
    isForever = false,
  },
  [3362] = {
    id = 3362,
    title = "Thistleshrub Valley",
    reqLevel = 45,
    questLevel = 50,
    faction = "Both",
    zone = "Tanaris",
    npc = "Tran'rek",
    objectives = "Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.",
    rewards = "4,700 XP • 75s",
    tip = "Have you ever seen Thistleshrub Valley? It's a mighty dangerous place, $N.\n\nThose strange beasts there, I don't trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that's what I think they were called...\n\nAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there's no way I'm going back there. But here's where you come in -- if you clear some of them out, I just might think about going back. What do you think, $N? Help me out?",
    isForever = false,
  },
  [1560] = {
    id = 1560,
    title = "Tooga's Quest",
    reqLevel = 40,
    questLevel = 50,
    faction = "Both",
    zone = "Tanaris",
    npc = "Tooga",
    objectives = "Show Tooga the way back to his wife, Torta.",
    rewards = "5,900 XP",
    tip = "I am so lost!\n\nMy wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere.\n\nWould you be so kind as to lead me back to Torta? She's waiting for me just south of Steamwheedle Port.",
    isForever = false,
  },
  [3126] = {
    id = 3126,
    title = "Treant Muisek",
    reqLevel = 40,
    questLevel = 50,
    faction = "Horde",
    zone = "Feralas",
    npc = "Witch Doctor Uzer'i",
    objectives = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.",
    rewards = "4,700 XP",
    tip = "The wandering forest walkers that can be found meandering through the forest are our next target, $N. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.",
    isForever = false,
  },
  [717] = {
    id = 717,
    title = "Tremors of the Earth",
    reqLevel = 40,
    questLevel = 50,
    faction = "Alliance",
    zone = "Badlands",
    npc = "Garek",
    objectives = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.$b$bPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$b$bSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.",
    rewards = "5,900 XP",
    tip = "It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor. That black dragons have taken up residence there, and that the ogres managed to steal the Sign indicates that more drastic measures will have to be taken.\n\nThe drakes' prison is maintained by three runestones that may only be retrieved using the Sign of the Earth. Those runestones can then be used to break the seal which imprisons them.\n\n$n... assure that their dreams are eternal.",
    isForever = false,
  },
  [3481] = {
    id = 3481,
    title = "Trinkets...",
    reqLevel = 40,
    questLevel = 50,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Object: Hoard of the Black Dragonflight",
    objectives = "Open the chest.",
    rewards = "470 XP",
    tip = "The chest appears locked.",
    isForever = false,
  },
  [3761] = {
    id = 3761,
    title = "Un'Goro Soil",
    reqLevel = 47,
    questLevel = 50,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Arch Druid Hamuul Runetotem",
    objectives = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.",
    rewards = "4,700 XP • 1g 45s",
    tip = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  The Cenarion Circle wants to study this soil in large quantities; go into the wilds of Un'Goro and acquire enough of it for our continued research.\n\nThe rich soil will stick out in piles from time to time, and some of the beasts might have usable samples on their being.  Take them all outside to Ghede; just look for the piles of dirt and the tauren barking orders.  He means well, just don't get him riled up though!",
    isForever = false,
  },
  [3764] = {
    id = 3764,
    title = "Un'Goro Soil",
    reqLevel = 47,
    questLevel = 50,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Arch Druid Fandral Staghelm",
    objectives = "Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.",
    rewards = "4,700 XP • 1g 45s",
    tip = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study.\n\nYou may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not",
    isForever = false,
  },
  [3063] = {
    id = 3063,
    title = "Vengeance on the Northspring",
    reqLevel = 45,
    questLevel = 50,
    faction = "Horde",
    zone = "Feralas",
    npc = "Talo Thornhoof",
    objectives = "Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers.",
    rewards = "3,550 XP • 55s",
    tip = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. $N, get my revenge.",
    isForever = false,
  },
  [2603] = {
    id = 2603,
    title = "Vulture's Vigor",
    reqLevel = 45,
    questLevel = 50,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Bloodmage Lynnore",
    objectives = "- Vulture Gizzard x 10 - Snickerfang Jowl x 2",
    rewards = "4,700 XP",
    tip = "Death does indeed have wings in these blasted lands, $r. I have witnessed the black slayers and bonepickers feasting upon the corpse of many a fallen explorer - sometimes feeding upon the most vile and disease ridden of carcasses. It is a wonder, then, how their internal systems overcome the pestilence that claims these lands.\n\nAssist me in my studies, $N! Gizzards I need! Two snickerfang jowls will also be required for the base of the concoction.\n\nYou shall be rewarded two-fold for your efforts",
    isForever = false,
  },
  [7701] = {
    id = 7701,
    title = "WANTED: Overseer Maltorius",
    reqLevel = 45,
    questLevel = 50,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Object: Wanted/Missing/Lost & Found",
    objectives = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\n\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.",
    rewards = "4,700 XP",
    tip = "By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed.\n\nSee Lookout Captan Lolo Longstriker fer the reward on this bounty.",
    isForever = false,
  },
  [3129] = {
    id = 3129,
    title = "Weapons of Spirit",
    reqLevel = 40,
    questLevel = 50,
    faction = "Horde",
    zone = "Feralas",
    npc = "Witch Doctor Uzer'i",
    objectives = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.",
    rewards = "4,700 XP",
    tip = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.",
    isForever = false,
  },
  [7601] = {
    id = 7601,
    title = "What Niby Commands",
    reqLevel = 50,
    questLevel = 50,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Niby the Almighty",
    objectives = "Speak with Impsy in Felwood.",
    rewards = "Experience & Faction Reputation",
    tip = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.\n\nMy imp, Impsy, shall set you on your way.",
    isForever = false,
  },
  [7722] = {
    id = 7722,
    title = "What the Flux?",
    reqLevel = 45,
    questLevel = 50,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Master Smith Burninate",
    objectives = "- Secret Plans: Fiery Flux",
    rewards = "4,700 XP, 75s",
    tip = "When that bastard, Maltorius, left our clan, he left with something more valuable than a pristine arcane crystal: Our recipe for fiery flux! I'd bet anything that the recipe was part of the deal in his new promotion amongst the Dark Irons.\n\nI want you to get our secret plans back, $N. I'm sure they're somewhere near Maltorius, deep inside the Slag Pit.",
    isForever = false,
  },
  [580] = {
    id = 580,
    title = "Whiskey Slim's Lost Grog",
    reqLevel = 40,
    questLevel = 50,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Whiskey Slim",
    objectives = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.",
    rewards = "4,700 XP",
    tip = "We was splicin' the mainbrace somethin' fierce off of the Overlook Cliffs, ol' Hinterlands just in the distance.  Thought the seas was goin' to swallow us whole.\n\nOl' Slim knows all about liquid courage!  Cap'n had a crate of Pupellyverbos Port we commandeered from a privateer en route to Stormwind.\n\nSo when that storm off of Hinterlands hit, I busted into the grog.  Big wave hit and tossed them bottles overboard.  Cap'n is goin' to give me a taste o' the cat if ye don't help me get 'em back tho",
    isForever = false,
  },
  [3884] = {
    id = 3884,
    title = "Williden's Journal",
    reqLevel = 48,
    questLevel = 50,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Item: A Mangled Journal",
    objectives = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.",
    rewards = "3,550 XP",
    tip = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.",
    isForever = false,
  },
  [6162] = {
    id = 6162,
    title = "A Husband's Last Battle",
    reqLevel = 46,
    questLevel = 51,
    faction = "Horde",
    zone = "Felwood",
    npc = "Dreka'Sur",
    objectives = "Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood.",
    rewards = "4,900 XP • 75s",
    tip = "My husband traveled Felwood for the honor of our clan, doing battle against the Shadow Council and other corrupt atrocities!\n\nAfter he escaped death numerous times, I received a letter from him saying that a druid asked him for help against a great befouled furbolg named Overlord Ror--the two were never heard from again.\n\nI want this Ror's clawed hand, $N. I want it to pay for leaving me a widow! I believe the creature is to the south... near the Ashenvale border.",
    isForever = false,
  },
  [7064] = {
    id = 7064,
    title = "Corruption of Earth and Seed",
    reqLevel = 45,
    questLevel = 51,
    faction = "Horde",
    zone = "Maraudon",
    npc = "Selendra",
    objectives = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.",
    rewards = "6,100 XP",
    tip = "Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship. The offspring of their time together became known to the people of Kalimdor as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now hold Zaetar's remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.",
    isForever = false,
  },
  [7065] = {
    id = 7065,
    title = "Corruption of Earth and Seed",
    reqLevel = 45,
    questLevel = 51,
    faction = "Alliance",
    zone = "Maraudon",
    npc = "Keeper Marandis",
    objectives = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.",
    rewards = "6,100 XP",
    tip = "In the depths of Maraudon lives a creature of chaos and evil, $N. Princess Theradras is an elemental force of earth related somehow to the Old Gods. Ages ago, she was sought out by Zaetar, first son of Cenarius. The offspring of their... relationship are the creatures known as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now Theradras keeps his remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Ston",
    isForever = false,
  },
  [626] = {
    id = 626,
    title = "Cortello's Riddle",
    reqLevel = 35,
    questLevel = 51,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Object: Musty Scroll",
    objectives = "Solve the riddle!",
    rewards = "6,100 XP",
    tip = "To Lordaeron! The great land of turmoil\nWhere brave soldiers with death do toil\nFind your way through the great unrest\nThere you will find the end to this quest\nAlong the coast of the Hinterlands, at the base of the great falls\nUnderneath the water there does your treasure call!",
    isForever = false,
  },
  [5155] = {
    id = 5155,
    title = "Forces of Jaedenar",
    reqLevel = 48,
    questLevel = 51,
    faction = "Both",
    zone = "Felwood",
    npc = "Greta Mosshoof",
    objectives = "Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.",
    rewards = "4,900 XP",
    tip = "If I am to trust you in this matter, you will first have to prove yourself.\n\nI must know that you are an enemy of the Shadow Council--the ones responsible for many evils here and abroad.\n\nTravel deeper into Felwood. To the west you will see a path leading to Jaedenar. It is there that the Council plots with the Burning Legion.\n\nEnter the depths of one of the corrupted Barrow Dens they inhabit and slay their kind. Return to me after you've done this. Then I will know you truly seek to help us.",
    isForever = false,
  },
  [3446] = {
    id = 3446,
    title = "Into the Depths",
    reqLevel = 46,
    questLevel = 51,
    faction = "Both",
    zone = "Sunken Temple",
    npc = "Marvon Rivetseeker",
    objectives = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.",
    rewards = "4,900 XP",
    tip = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple.",
    isForever = false,
  },
  [7862] = {
    id = 7862,
    title = "Job Opening: Guard Captain of Revantusk Village",
    reqLevel = 46,
    questLevel = 51,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Object: Call to Arms!",
    objectives = "You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.\n\nShould you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.",
    rewards = "6,100 XP • 2g 25s",
    tip = "With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open. If you are interested in becoming Captain of the Guard for Revantusk, complete the following tasks and submit your application to Primal Torntusk:\n\nExterminate Vilebranch Berserkers.\n\nExterminate Vilebranch Shadow Hunters.\n\nExterminate Vilebranch Blood Drinkers.\n\nExterminate Vilebranch Soul Eaters.",
    isForever = false,
  },
  [7845] = {
    id = 7845,
    title = "Kidnapped Elder Torntusk!",
    reqLevel = 46,
    questLevel = 51,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Primal Torntusk",
    objectives = "Primal Torntusk at Raventusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.\n\nYou have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands.",
    rewards = "4,900 XP",
    tip = "My mate was taken by Vilebranch savages in a bold midnight raid on our village. Our spies have told me that he is still alive and being held prisoner atop Jintha'alor. The Vile Priestess Hexx is said to be preparing him for a sacrifice to the faceless blood God, Hakkar.\n\nYou must save him, $N! Our village could not stand a loss this great.",
    isForever = false,
  },
  [630] = {
    id = 630,
    title = "Message in a Bottle",
    reqLevel = 45,
    questLevel = 51,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Princess Poobah",
    objectives = "Slay King Mukla and return to Princess Poobah with the Key to free her.",
    rewards = "7,350 XP",
    tip = "$N, I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain. If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.",
    isForever = false,
  },
  [7846] = {
    id = 7846,
    title = "Recover the Key!",
    reqLevel = 46,
    questLevel = 51,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Elder Torntusk",
    objectives = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torn'tusk when you have recovered the key.",
    rewards = "6,100 XP",
    tip = "The key to my bindings is held by Hitah'ya the Keeper. She is in the nearby cave. Be careful, $c, for she is guarded well.\n\nKill her and bring the key back to loosen my shackles. Only then will I be free to return home.",
    isForever = false,
  },
  [7847] = {
    id = 7847,
    title = "Return to Primal Torntusk",
    reqLevel = 46,
    questLevel = 51,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Elder Torntusk",
    objectives = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue.",
    rewards = "4,900 XP • 2g 25s",
    tip = "Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you.",
    isForever = false,
  },
  [3882] = {
    id = 3882,
    title = "Roll the Bones",
    reqLevel = 49,
    questLevel = 51,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Spark Nilminer",
    objectives = "Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.",
    rewards = "4,900 XP",
    tip = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well",
    isForever = false,
  },
  [3447] = {
    id = 3447,
    title = "Secret of the Circle",
    reqLevel = 46,
    questLevel = 51,
    faction = "Both",
    zone = "Sunken Temple",
    npc = "Object: Altar of Hakkar",
    objectives = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.",
    rewards = "6,100 XP",
    tip = "My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, $N. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...",
    isForever = false,
  },
  [7066] = {
    id = 7066,
    title = "Seed of Life",
    reqLevel = 45,
    questLevel = 51,
    faction = "Both",
    zone = "Maraudon",
    npc = "Zaetar's Spirit",
    objectives = "Seek out Remulos in Moonglade and give him the Seed of Life.",
    rewards = "6,100 XP • 1g 50s",
    tip = "The misbegotten centaur--my sons and daughters--have need of their father.\n\nLook around you--this place rings of hope and all that my father Cenarius preaches. It sprung from me! And I cannot take that away from them... not even for their crimes against me.\n\nBut there is one thing I would ask of you to ease my brother's mind. Take this... it is the first seed that fell from the life my remains nourished. Tell him my spirit remains here, and that I live on. I am sure he will understand.",
    isForever = false,
  },
  [4503] = {
    id = 4503,
    title = "Shizzle's Flyer",
    reqLevel = 49,
    questLevel = 51,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Shizzle",
    objectives = "Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge.",
    rewards = "4,900 XP",
    tip = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax and diemetradon would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?",
    isForever = false,
  },
  [614] = {
    id = 614,
    title = "The Captain's Chest",
    reqLevel = 35,
    questLevel = 51,
    faction = "Alliance",
    zone = "Stranglethorn Vale",
    npc = "Captain Hecklebury Smotts",
    objectives = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
    rewards = "3,150 XP",
    tip = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.",
    isForever = false,
  },
  [615] = {
    id = 615,
    title = "The Captain's Cutlass",
    reqLevel = 35,
    questLevel = 51,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Captain Hecklebury Smotts",
    objectives = "Speak with Sprogger.",
    rewards = "470 XP",
    tip = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the gian",
    isForever = false,
  },
  [3444] = {
    id = 3444,
    title = "The Stone Circle",
    reqLevel = 46,
    questLevel = 51,
    faction = "Both",
    zone = "Tanaris",
    npc = "Marvon Rivetseeker",
    objectives = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.",
    rewards = "4,900 XP",
    tip = "I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...\n\nRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you mo",
    isForever = false,
  },
  [3380] = {
    id = 3380,
    title = "The Sunken Temple",
    reqLevel = 46,
    questLevel = 51,
    faction = "Horde",
    zone = "Sunken Temple",
    npc = "Witch Doctor Uzer'i",
    objectives = "Find Marvon Rivetseeker in Tanaris.",
    rewards = "3,650 XP",
    tip = "There are restless spirits in this world, $N. There are spirits that have been tainted by their isolation, bound to an ancient evil...\n\nI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Ta",
    isForever = false,
  },
  [3445] = {
    id = 3445,
    title = "The Sunken Temple",
    reqLevel = 46,
    questLevel = 51,
    faction = "Alliance",
    zone = "Feralas",
    npc = "Angelas Moonbreeze",
    objectives = "Find Marvon Rivetseeker in Tanaris.",
    rewards = "3,650 XP",
    tip = "I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.\n\nGood luck finding him; he hasn't been heard from in some time.",
    isForever = false,
  },
  [7861] = {
    id = 7861,
    title = "Wanted: Vile Priestess Hexx and Her Minions",
    reqLevel = 46,
    questLevel = 51,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Object: Call to Arms!",
    objectives = "You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.\n\nVile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.",
    rewards = "6,100 XP • 2g 25s",
    tip = "By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice!\n\nA grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard.",
    isForever = false,
  },
  [9053] = {
    id = 9053,
    title = "A Better Ingredient",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Druid Class Quests",
    npc = "Torwa Pathfinder",
    objectives = "Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.",
    rewards = "6,350 XP",
    tip = "It is as I feared -- the toxin is simply too weak for such a powerful creature.\n\nIf we are to create a toxin of high enough potency, you must venture to the bottom of the Temple of Atal'Hakkar, unlock the secrets of the altar and recover a putrid vine from the guardian there.  The temple is dangerous, and it would behoove you to bring friends.\n\nReturn to me when this is done.",
    isForever = false,
  },
  [3941] = {
    id = 3941,
    title = "A Gnome's Assistance",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Linken",
    objectives = "Find J.D. Collie in the cave at Marshal's Refuge.",
    rewards = "1,250 XP",
    tip = "Thinking... Thinking... I know I came here for something important...\n\nI have an idea, $N. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.\n\nWhy don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!",
    isForever = false,
  },
  [3913] = {
    id = 3913,
    title = "A Grave Situation",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Gaeriyan",
    objectives = "Resurrect, then look for the gravestone that Gaeriyan told you to find.",
    rewards = "2,550 XP",
    tip = "If you return to the graveyard, $N, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it.\n\nPush on the stone, and you will learn of these secrets...",
    isForever = false,
  },
  [4512] = {
    id = 4512,
    title = "A Little Slime Goes a Long Way",
    reqLevel = 48,
    questLevel = 52,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Laris Geardawdle",
    objectives = "Bring 6 Filled Cursed Ooze Jars and 6 Filled Tainted Ooze Jars to Laris Geardawdle in Ironforge.",
    rewards = "6,350 XP • 75s",
    tip = "But the thing I've studied most is ooze. I know it sounds odd, but they're all over!\n\nI helped a lady in Menethil find her bag not too long ago--it was eaten by oozes. I've seen members of the Royal Apothecary Society from Undercity collecting samples of the stuff. I want to know why! Where does it come from?\n\nI've heard of more in Felwood. What I need are samples of the oozes there so I can further my research. I'll give you containers, you use them to collect a sample from the deceased creatur",
    isForever = false,
  },
  [4293] = {
    id = 4293,
    title = "A Sample of Slime...",
    reqLevel = 48,
    questLevel = 52,
    faction = "Horde",
    zone = "Undercity",
    npc = "Chemist Fuely",
    objectives = "Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely.",
    rewards = "5,100 XP • 60s",
    tip = "Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks.\n\nGather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.",
    isForever = false,
  },
  [8233] = {
    id = 8233,
    title = "A Simple Request",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Rogue Class Quests",
    npc = "Osborne the Night Man",
    objectives = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor.",
    rewards = "500 XP",
    tip = "Lord Jorach Ravenholdt has requested your presence.  The matter is secret, and I cannot say any more.\n\nRavenholdt Manor is located in the Hillsbrad Foothills -- look for a path in the mountains northwest of Durnhold Keep.",
    isForever = false,
  },
  [4142] = {
    id = 4142,
    title = "A Visit to Gregan",
    reqLevel = 47,
    questLevel = 52,
    faction = "Alliance",
    zone = "Un'Goro Crater",
    npc = "Muigin",
    objectives = "Take a Bloodpetal to Gregan Brewspewer in Feralas.",
    rewards = "3,800 XP",
    tip = "I'm not quite sure what to make of this, $N. The plants... they seem to have some minimal intelligence.\n\nI'm no expert, though. But, I do know someone that is!\n\nHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.\n\nI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.",
    isForever = false,
  },
  [3883] = {
    id = 3883,
    title = "Alien Ecology",
    reqLevel = 48,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Hol'anyee Marshal",
    objectives = "Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater.  Look for the chambers with the hanging larval spawns.\n\nBring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater.",
    rewards = "5,100 XP • 40s",
    tip = "Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why.\n\nIn their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!",
    isForever = false,
  },
  [3450] = {
    id = 3450,
    title = "An Easy Pickup",
    reqLevel = 45,
    questLevel = 52,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Tymor",
    objectives = "Speak to Xiggs Fuselighter in Ironforge.",
    rewards = "510 XP",
    tip = "I want the rubbings delivered to my tower, but there's no need to have you go all the way there. I'll just have them air-lifted out of Azshara.\n\nXiggs Fuselighter owes me a favor or two and will be in the area soon--he's signed on to patrol the coast. Speak to him before you leave. He can give you a flare gun to signal him with. When you have the rubbings, just head to wherever he tells you and then give them to him so he can get them to my tower safely. He should be in the hangar in the Militar",
    isForever = false,
  },
  [8419] = {
    id = 8419,
    title = "An Imp's Request",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Demisette Cloyce",
    objectives = "Bring a piece of felcloth to Impsy in Felwood.",
    rewards = "3,800 XP",
    tip = "$n, an imp in Felwood by the name of Impsy has requested your presence.  It is somewhat strange, as he has asked that you bring a piece of felcloth as a sign of good faith.  Considering the power you already wield as a warlock, I can only assume you know the satyrs of Felwood carry this felcloth.\n\nYou can find Impsy just north of the Bloodvenom Falls, which I've heard is quite lovely this time of year.",
    isForever = false,
  },
  [3564] = {
    id = 3564,
    title = "Andron's Payment to Jediga",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Andron Gant",
    objectives = "Deliver Andron's Note to Jediga in Azshara.",
    rewards = "3,800 XP • 75s",
    tip = "Here... take... <hic> this to Jediga. Good luck to ya!",
    isForever = false,
  },
  [3449] = {
    id = 3449,
    title = "Arcane Runes",
    reqLevel = 45,
    questLevel = 52,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Tymor",
    objectives = "Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up.",
    rewards = "2,550 XP",
    tip = "Magic was once as revered as Elune herself to some elves. Some of their most powerful mages created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places.\n\nI would very much like rubbings of these runes from the Ruins of Eldarath. I have a kit for you to make the rubbings with, but it will be up to you to find them. Be careful though, the Explorer's League isn't the only one interested in Eldarath.",
    isForever = false,
  },
  [5021] = {
    id = 5021,
    title = "Better Late Than Never",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Janice Felstone",
    objectives = "The ramblings of the ghostly woman indicated that she needed a package delivered.  She claimed that it was where her horse was.  As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible.",
    rewards = "2,550 XP",
    tip = "\"The package must be delivered... delivered before I'm trapped here!\"\n\nThe cries of a panicked woman feel almost like a whisper floating through the house.  Cowered in the upstairs corner is the apparition of a woman.  She does not seem to be fully cognizant of her surroundings, and she is only vaguely aware of you.\n\n\"Are you here to deliver my package?  Please, before it gets much worse!  I was going to ride out of here.  It should still be by my horse... or am I too late?\"",
    isForever = false,
  },
  [5022] = {
    id = 5022,
    title = "Better Late Than Never",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Object: Janice's Parcel",
    objectives = "Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone.  There is usually a census officer located in City Hall.",
    rewards = "2,550 XP",
    tip = "You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to an Emma Felstone of Stormwind; the delivery of the package is dated for well over four years ago.\n\nThough it is unclear if Emma Felstone is even alive, it is widely known that the Stormwind City Hall keep records on the populace of the city.  This is handled through the Royal Factors of the Stormwind Census.",
    isForever = false,
  },
  [5023] = {
    id = 5023,
    title = "Better Late Than Never",
    reqLevel = 50,
    questLevel = 52,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Object: Janice's Parcel",
    objectives = "Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone.  There is usually a census officer located near guild and tabard registration.",
    rewards = "2,550 XP",
    tip = "You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to a Jeremiah Felstone of Lordaeron; the delivery of the package is dated for well over four years ago.\n\nThough it is unclear if Jeremiah Felstone is even alive, it is widely known that the Undercity, formerly known as Lordaeron, keeps records on the populace of the city.  This is handled through the Royal Overseers of the Undercity Census.",
    isForever = false,
  },
  [8257] = {
    id = 8257,
    title = "Blood of Morphaz",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Priest Class Quests",
    npc = "Ogtinc",
    objectives = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows.",
    rewards = "6,350 XP • 1g 55s",
    tip = "Now the last part, the second cure.\n\nThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.\n\nA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood.",
    isForever = false,
  },
  [9052] = {
    id = 9052,
    title = "Bloodpetal Poison",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Druid Class Quests",
    npc = "Torwa Pathfinder",
    objectives = "Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater.",
    rewards = "5,100 XP",
    tip = "I would ask you to help me create a toxin of sorts, to pacify a great creature living here in the crater.  It is not deadly, and only the keen eyes of a $c can hope to collect the ingredients.\n\nYou can find the bloodcap mushrooms growing within the bloodpetal sprouts all across the crater.  Gorishi stings are from the insects inside and around the Slithering Scar, located in the southern part of the crater.",
    isForever = false,
  },
  [4300] = {
    id = 4300,
    title = "Bone-Bladed Weapons",
    reqLevel = 48,
    questLevel = 52,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Jes'rimon",
    objectives = "Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.",
    rewards = "5,100 XP • 40s",
    tip = "Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure.\n\nIn Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.",
    isForever = false,
  },
  [4726] = {
    id = 4726,
    title = "Broodling Essence",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Burning Steppes",
    npc = "Tinkee Steamboil",
    objectives = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.",
    rewards = "5,100 XP • 75s",
    tip = "I have been studying the dragonkin of the Burning Steppes for weeks, and I think I've finally had a breakthrough!  I created a device--I call it the Draco Incarcinatrix 900.  It can capture the essence of dragon whelp broodlings!\n\nOr, at least I think it can.\n\nHere, take the device and zap a broodling in the Burning Steppes with it.  While it's under the device's effects, defeat the broodling and its essence should be released.\n\nIf it is, then splendid!  Bring me back samples so I can study them",
    isForever = false,
  },
  [8254] = {
    id = 8254,
    title = "Cenarion Aid",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Priest Class Quests",
    npc = "Brother Joshua",
    objectives = "Seek out Ogtinc in Azshara.",
    rewards = "500 XP",
    tip = "It is the way of the divine to help those in need.  The how is insignificant -- only the why matters.\n\nThe Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.",
    isForever = false,
  },
  [8415] = {
    id = 8415,
    title = "Chillwind Point",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Lord Grayson Shadowbreaker",
    objectives = "Speak to Commander Ashlam Valorfist at Chillwind Camp.",
    rewards = "500 XP",
    tip = "Commander Ashlam Valorfist has sent out a call for a paladin of your purity and valor, $n.  You can find him at Chillwind Camp in the southern part of the Western Plaguelands.  Seek him and aid in his cause for the Light!",
    isForever = false,
  },
  [5092] = {
    id = 5092,
    title = "Clear the Way",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Commander Ashlam Valorfist",
    objectives = "Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.\n\nReturn to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.",
    rewards = "5,100 XP • 75s",
    tip = "With Andorhal's western and northern roads into the city well fortified, I'm looking to strike at it from the less defended eastern road.  The Scourge relies on the buffer of undead that infests Sorrow Hill as a first line of defense.  If we are to advance on Andorhal, we will need to do it through Sorrow Hill.\n\nYour first assignment will be to clear the way through Sorrow Hill.  Thin out the skeletons and ghouls that haunt the area; report back to me when this is done!",
    isForever = false,
  },
  [5157] = {
    id = 5157,
    title = "Collection of the Corrupt Water",
    reqLevel = 48,
    questLevel = 52,
    faction = "Both",
    zone = "Felwood",
    npc = "Greta Mosshoof",
    objectives = "Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.",
    rewards = "3,800 XP",
    tip = "Deep within Jaedenar lies Shadow Hold--the main fortress of their corruption and evil.\n\nThe Shadow Council has protective spells surrounding their lair in the form of braziers. If I am to find out any more information about our enemy through scrying, then those braziers must be extinguished. By doing so, I should be able to spy on the Council and find out who leads them.\n\nIf you can, take this canteen and fill it at the Moon Well in the center of Jaedenar. Return to me afterwards.",
    isForever = false,
  },
  [3981] = {
    id = 3981,
    title = "Commander Gor'shak",
    reqLevel = 48,
    questLevel = 52,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Galamav the Marksman",
    objectives = "Find Commander Gor'shak in Blackrock Depths.\n\nYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.",
    rewards = "5,100 XP",
    tip = "Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...\n\n<Galamav grimaces.>\n\nWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.\n\nIf he's still alive in the Depths, you'll have to find him.\n\nA trap you say? Well no kidding, numb hooves! That's why you're going!",
    isForever = false,
  },
  [8153] = {
    id = 8153,
    title = "Courser Antlers",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Hunter Class Quests",
    npc = "Ogtinc",
    objectives = "Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.",
    rewards = "5,100 XP",
    tip = "The courser wears the mightiest antlers in the known lands.  Such antlers are used to defend the courser, goring an attacker and often damaging the points.  Perfect, natural antlers are the sign of an animal spirit with supreme confidence.\n\nTo hold such antlers will bestow the same confidence in you.\n\nHunt the mosshoof courser, find the perfect antlers and bring them to me.",
    isForever = false,
  },
  [8413] = {
    id = 8413,
    title = "Da Voodoo",
    reqLevel = 50,
    questLevel = 52,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Bath'rah the Windwatcher",
    objectives = "Bring the voodoo feathers to Bath'rah the Windwatcher.",
    rewards = "6,350 XP • 1g 55s",
    tip = "The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right.\n\nThe trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem.",
    isForever = false,
  },
  [3801] = {
    id = 3801,
    title = "Dark Iron Legacy",
    reqLevel = 48,
    questLevel = 52,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Franclorn Forgewright",
    objectives = "Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major.",
    rewards = "510 XP",
    tip = "Greetings, $N. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.",
    isForever = false,
  },
  [3802] = {
    id = 3802,
    title = "Dark Iron Legacy",
    reqLevel = 48,
    questLevel = 52,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Franclorn Forgewright",
    objectives = "- Ironfel",
    rewards = "5,100 XP, 2g 30s",
    tip = "You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel.\n\nTake Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor.\n\nWhen this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever",
    isForever = false,
  },
  [3542] = {
    id = 3542,
    title = "Delivery to Andron Gant",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Jediga",
    objectives = "Bring the Tablet of Markri to Andron Gant in Undercity.",
    rewards = "2,550 XP • 60s",
    tip = "Andron Gant is my next contact. He usually holds himself up in the Undercity... right near the Apothecarium.\n\nHe was a little more loose-lipped when it came to speaking about what he wanted the Tablet for. Apparently some of the mages of Undercity are looking to study some of the arcane spells the highborne used. They think this tablet will help them. Markri was adept at summoning creatures; especially elementals.\n\nTake the Tablet of Markri and return to me for your part of the reward.",
    isForever = false,
  },
  [3561] = {
    id = 3561,
    title = "Delivery to Archmage Xylem",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Jediga",
    objectives = "Bring the Tablet of Sael'hai to Archmage Xylem in Azshara.",
    rewards = "2,550 XP • 40s",
    tip = "This final tablet goes to someone very dangerous, $N. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.\n\nArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.\n\nHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath",
    isForever = false,
  },
  [3541] = {
    id = 3541,
    title = "Delivery to Jes'rimon",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Jediga",
    objectives = "Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar.",
    rewards = "2,550 XP • 40s",
    tip = "I have a fence in Orgrimmar. He resides in The Drag. He's difficult to nail down if you don't know where to look, but if you go looking in one of the highest buildings there you should have no problem finding him.\n\nDo me a favor though, don't go shouting to all of Kalimdor that he's there and what his business is--it'd be bad for both of us.\n\nHe'll give us more than a fair price for the Tablet of Jin'yael. I'm not sure why, but you should have seen how excited he was to hear about its whereabout",
    isForever = false,
  },
  [3518] = {
    id = 3518,
    title = "Delivery to Magatha",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Jediga",
    objectives = "Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff.",
    rewards = "2,550 XP",
    tip = "The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.\n\nBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims.",
    isForever = false,
  },
  [8253] = {
    id = 8253,
    title = "Destroy Morphaz",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Archmage Xylem",
    objectives = "Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.",
    rewards = "6,350 XP • 1g 55s",
    tip = "There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz.\n\nYears ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality.\n\nYou must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach.",
    isForever = false,
  },
  [3906] = {
    id = 3906,
    title = "Disharmony of Flame",
    reqLevel = 48,
    questLevel = 52,
    faction = "Horde",
    zone = "Blackrock Mountain",
    npc = "Thunderheart",
    objectives = "- Overmaster Pyron",
    rewards = "5,100 XP, 1g 55s",
    tip = "The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.\n\nTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.\n\nEnd the disruption and return to me.",
    isForever = false,
  },
  [8414] = {
    id = 8414,
    title = "Dispelling Evil",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Commander Ashlam Valorfist",
    objectives = "Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands.",
    rewards = "5,100 XP",
    tip = "Greetings, $c.  Crusaders like you are a welcome sight in these desolate reaches.\n\nYour holy strength is needed to help fight the endless undead here.  We need you to collect a large number of scourgestones and bring them to High Priest Thel'danis.  The high priest can be found guarding Uther's Tomb in Sorrow Hill, not far from here.\n\nOnly one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven't already.",
    isForever = false,
  },
  [3821] = {
    id = 3821,
    title = "Dreadmaul Rock",
    reqLevel = 48,
    questLevel = 52,
    faction = "Horde",
    zone = "Badlands",
    npc = "Thal'trak Proudtusk",
    objectives = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.",
    rewards = "5,100 XP",
    tip = "Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.\n\nGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!\n\nI can't leave my post, $N, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.",
    isForever = false,
  },
  [6030] = {
    id = 6030,
    title = "Duke Nicholas Zverenhoff",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Winterspring",
    npc = "Gregor Greystone",
    objectives = "Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands.",
    rewards = "2,550 XP • 40s",
    tip = "A recluse medium found in these parts by the name of Umbranse has provided the Argent Dawn with quite a literary masterpiece... one that amounts to quite possibly the largest collection of jibber-jabber I've ever seen written.\n\nOne of the Dawn's most respected leaders, Duke Nicholas Zverenhoff, is a brilliant linguist.  Could you take this to him for me - for a reward, of course?  Light's Hope Chapel - that's where he's currently at, far in the eastern part of the Eastern Plaguelands.",
    isForever = false,
  },
  [8235] = {
    id = 8235,
    title = "Encoded Fragments",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Rogue Class Quests",
    npc = "Archmage Xylem",
    objectives = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara.",
    rewards = "5,100 XP • 75s",
    tip = "Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag.\n\nUnfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me.\n\nIf you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill the beasts of Azshara, since they have a tendency to pick up just about anything.",
    isForever = false,
  },
  [619] = {
    id = 619,
    title = "Enticing Negolash",
    reqLevel = 1,
    questLevel = 52,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Object: Ruined Lifeboat",
    objectives = "- Barbecued Buzzard Wing x 10 - Junglevine Wine x 5",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [3823] = {
    id = 3823,
    title = "Extinguish the Firegut",
    reqLevel = 48,
    questLevel = 52,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Oralius",
    objectives = "- Firegut Ogre Mage x 15 - Firegut Ogre x 7 - Firegut Brute x 7",
    rewards = "5,100 XP",
    tip = "We must strike at our enemies before they strike at us!\n\nI'll make this brief, soldier.\n\nThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.\n\nLeave your mark, $N. Cripple their forces and return to me when the job is done.\n\n<Oralius grabs at the air and makes a choking motion.>\n\nI WILL KILL YOU, WINKY!",
    isForever = false,
  },
  [8418] = {
    id = 8418,
    title = "Forging the Mightstone",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Commander Ashlam Valorfist",
    objectives = "Bring the voodoo feathers to Ashlam Valorfist.",
    rewards = "6,350 XP • 1g 55s",
    tip = "Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, $n.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself.\n\nIn the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil.",
    isForever = false,
  },
  [5050] = {
    id = 5050,
    title = "Good Luck Charm",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Ol' Emma",
    objectives = "Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm.",
    rewards = "2,550 XP",
    tip = "It would seem that I was wrong about you $N, and for that I owe you an apology.  My sister sent me a number of personal effects, including humorously enough the deed to the Felstone farm.  I think I'll pass on reclaiming it right now.\n\nIf my sister's spirit remains tethered to the farm and cannot rest, please... could you return this to her?  It is half of a good luck charm she had, with her husband having the other half.\n\nMaybe her knowing I have these things will now put her soul to rest.",
    isForever = false,
  },
  [5048] = {
    id = 5048,
    title = "Good Natured Emma",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Royal Factor Bathrilor",
    objectives = "Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her.",
    rewards = "5,100 XP",
    tip = "She's a tad ornery, and quite possibly out of her gourd... but the records indicate that Ol' Emma does fit the framework of who Emma Felstone might be.\n\nPerhaps you've seen Ol' Emma wander the city - she talks to herself, most often in nonsensical jibber-jabber.  Still, she doesn't hurt anything or anyone, so folks pretty much leave her be.\n\nAll things considered, I would say that Ol' Emma is in fact Emma Felstone.  You might try asking if her last name is indeed Felstone.",
    isForever = false,
  },
  [4143] = {
    id = 4143,
    title = "Haze of Evil",
    reqLevel = 47,
    questLevel = 52,
    faction = "Alliance",
    zone = "Un'Goro Crater",
    npc = "Gregan Brewspewer",
    objectives = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.",
    rewards = "5,100 XP • 75s",
    tip = "To tell you the truth, $N, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...\n\nAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.\n\nYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai Haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, $N!",
    isForever = false,
  },
  [8420] = {
    id = 8420,
    title = "Hot and Itchy",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Impsy",
    objectives = "Bring a piece of felcloth to Impsy in Felwood.",
    rewards = "3,800 XP",
    tip = "Maybe this sounds strange coming from an imp, but I'd like a pet of my own.  I really would.  It's just not fair that Niby gets me and I get nothing!\n\nIn fact, it doesn't even need to be a living pet.  I'd need something to start making it with, like some felcloth.  The satyrs here in Felwood sometimes have felcloth, so you'd just have to kill enough of them until you find some.  That doesn't sound so bad, does it?",
    isForever = false,
  },
  [8416] = {
    id = 8416,
    title = "Inert Scourgestones",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "High Priest Thel'danis",
    objectives = "Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point.",
    rewards = "2,550 XP",
    tip = "The evil has been purged from the stones, $n.\n\nI am aware of Commander Ashlam's plans, and he will require only a single inert stone.  Bring it to him so we may bathe the Scourge in righteous fire.",
    isForever = false,
  },
  [3844] = {
    id = 3844,
    title = "It's a Secret to Everybody",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Object: A Wrecked Raft",
    objectives = "Look around in the pond for a clue about who this wrecked raft may belong to.",
    rewards = "1,250 XP",
    tip = "A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.\n\nPerhaps a little exploration in the area might uncover more clues...",
    isForever = false,
  },
  [3845] = {
    id = 3845,
    title = "It's a Secret to Everybody",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Object: A Small Pack",
    objectives = "Examine the items inside the pack and bring them to their owner.",
    rewards = "5,100 XP",
    tip = "Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.\n\nThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.",
    isForever = false,
  },
  [3908] = {
    id = 3908,
    title = "It's a Secret to Everybody",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Linken",
    objectives = "Take Linken's Sword to Donova Snowden in Winterspring.",
    rewards = "5,100 XP",
    tip = "You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...\n\nThese items you brought to me, though... I am remembering something.\n\nMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!\n\nAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there.",
    isForever = false,
  },
  [3563] = {
    id = 3563,
    title = "Jes'rimon's Payment to Jediga",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Jes'rimon",
    objectives = "Deliver Jes'rimon's Note to Jediga in Azshara.",
    rewards = "3,800 XP • 60s",
    tip = "Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.\n\nYou tell her she come back to Orgrimmar fast and Jes'rimon make sure he take good care of her.\n\nTell her that, and maybe in the future I have need of your services again, $N.",
    isForever = false,
  },
  [4081] = {
    id = 4081,
    title = "KILL ON SIGHT: Dark Iron Dwarves",
    reqLevel = 48,
    questLevel = 52,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Object: WANTED",
    objectives = "- Anvilrage Guardsman x 15 - Anvilrage Warden x 10 - Anvilrage Footman x 5",
    rewards = "5,100 XP, 1g 55s",
    tip = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.\n\nAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.\n\nAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.",
    isForever = false,
  },
  [4145] = {
    id = 4145,
    title = "Larion and Muigin",
    reqLevel = 47,
    questLevel = 52,
    faction = "Horde",
    zone = "Un'Goro Crater",
    npc = "Larion",
    objectives = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.",
    rewards = "5,100 XP • 75s",
    tip = "See Muigin over there? It's HIS fault we're lost!\n\nI'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here!\n\nTo make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle.\n\nWhy don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.",
    isForever = false,
  },
  [3914] = {
    id = 3914,
    title = "Linken's Sword",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Object: A Conspicuous Gravestone",
    objectives = "Deliver Linken's Superior Sword to Linken in Un'Goro Crater.",
    rewards = "5,100 XP • 75s",
    tip = "After a strong flash of light, you are able to pick up the sword again. It has been transformed!",
    isForever = false,
  },
  [3562] = {
    id = 3562,
    title = "Magatha's Payment to Jediga",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Magatha Grimtotem",
    objectives = "Deliver Magatha's Note to Jediga in Azshara.",
    rewards = "3,800 XP • 60s",
    tip = "Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.\n\nGo swiftly, $N. Tell your master I will be awaiting her here.",
    isForever = false,
  },
  [8250] = {
    id = 8250,
    title = "Magecraft",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Maginor Dumas",
    objectives = "Seek out Sanath Lim-yo and gain passage to see Archmage Xylem.",
    rewards = "500 XP",
    tip = "Archmage Xylem has been asking around lately... for someone of your experience.\n\nIf you wish to seek him out, you can find him in Azshara.  His tower is built high atop the cliffs, and the only way up is a teleport spell invoked by his arrogant servant, Sanath Lim-yo.\n\nSanath makes camp below his master's tower.  To find him, travel to where Azshara's main road forks at the entrance to the Ruins of Eldarath.  From that spot, head directly north until you reach the cliffs.",
    isForever = false,
  },
  [8251] = {
    id = 8251,
    title = "Magic Dust",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Archmage Xylem",
    objectives = "Bring 10 Glittering Dust to Archmage Xylem.",
    rewards = "5,100 XP",
    tip = "The blood elves in Azshara have developed a method for pulverizing the magical items they acquire.  This glittering dust they produce differs from the components normally acquired by a disenchantment spell.\n\nWhen I sent my apprentice to trade for the dust, he was killed without hesitation.  For that, they must pay.\n\nThe time for talk is over, $N.  Find the blood elves along the cliffs of Azshara and use more \"persuasive\" methods to acquire their glittering dust.",
    isForever = false,
  },
  [4147] = {
    id = 4147,
    title = "Marvon's Workshop",
    reqLevel = 47,
    questLevel = 52,
    faction = "Horde",
    zone = "Un'Goro Crater",
    npc = "Larion",
    objectives = "Travel to Marvon Rivetseeker's workshop in Ratchet.",
    rewards = "2,550 XP",
    tip = "I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!\n\nI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!\n\nWe'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.",
    isForever = false,
  },
  [3912] = {
    id = 3912,
    title = "Meet at the Grave",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Donova Snowden",
    objectives = "Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.",
    rewards = "5,100 XP",
    tip = "This elixir will allow you to speak with one that you would not normally even see...\n\nTake the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed.\n\nIn your \"other\" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan.\n\nRemember, he will only speak to you in that form..",
    isForever = false,
  },
  [4141] = {
    id = 4141,
    title = "Muigin and Larion",
    reqLevel = 47,
    questLevel = 52,
    faction = "Alliance",
    zone = "Un'Goro Crater",
    npc = "Muigin",
    objectives = "Collect 15 Bloodpetals and return to Muigin.",
    rewards = "5,100 XP",
    tip = "See Larion over there? It's HIS fault we're here!\n\nI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.\n\nHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.\n\nFirst thing though, I'll need some samples to study. Do you think you could collect som",
    isForever = false,
  },
  [8255] = {
    id = 8255,
    title = "Of Coursers We Know",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Priest Class Quests",
    npc = "Ogtinc",
    objectives = "Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
    rewards = "5,100 XP",
    tip = "The mosshoof coursers of Azshara are magnificent animals who once lived in Felwood.  They naturally resist disease and poison, and were unaffected by the corruption there.  In their ancestral wisdom, they simply chose to leave that sickened place.\n\nIt saddens my heart, but I must ask you to hunt these mighty beasts for me.  Gather four courser glands as the first ingredient for a restorative salve -- a salve we will use to heal Felwood.",
    isForever = false,
  },
  [4262] = {
    id = 4262,
    title = "Overmaster Pyron",
    reqLevel = 48,
    questLevel = 52,
    faction = "Alliance",
    zone = "Blackrock Mountain",
    npc = "Jalinda Sprig",
    objectives = "Slay Overmaster Pyron and return to Jalinda Sprig.\n\nYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?",
    rewards = "5,100 XP • 1g 55s",
    tip = "The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.\n\n<Jalinda picks up some ashes from the ground and releases them into the air.>\n\nOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!\n\nHe guards the entrance at the Blackrock Quarry.",
    isForever = false,
  },
  [3448] = {
    id = 3448,
    title = "Passing the Burden",
    reqLevel = 45,
    questLevel = 52,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Historian Karnik",
    objectives = "Speak to Tymor in Ironforge.",
    rewards = "510 XP",
    tip = "I've recently been handed the responsibility of investigating Azshara--a once beautiful area the elves called home. This would be back when they practiced magic. It's now a more dangerous place than it is beautiful, but that doesn't stop us from turning over every stone for answers to our past.\n\nA companion of mine named Tymor offered to help me investigate the area since he takes a particular interest in such things.\n\nHe owns a small place to the right of the Hall of Mysteries here in the city.",
    isForever = false,
  },
  [3372] = {
    id = 3372,
    title = "Release Them",
    reqLevel = 40,
    questLevel = 52,
    faction = "Alliance",
    zone = "Searing Gorge",
    npc = "Dying Archaeologist",
    objectives = "- Mysterious Artifact",
    rewards = "5,100 XP",
    tip = "Release them, $r. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.\n\nThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight's Hammer guard a relic. Retrieve it and place it on the altar of Suntara.\n\n<The dying archaeologist collapses.>",
    isForever = false,
  },
  [3461] = {
    id = 3461,
    title = "Return to Tymor",
    reqLevel = 45,
    questLevel = 52,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Pilot Xiggs Fuselighter",
    objectives = "Return Tymor's Drawing Kit to him in Ironforge.",
    rewards = "7,600 XP",
    tip = "Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward. Just go knockin' and make sure he pays you good. This place ain't no picnic... that's for sure.\n\nThanks again for helping him out though, and good luck.\n\nOh, and I don't need the drawing kit. Why don't you just bring it back to Tymor when you go to see him?",
    isForever = false,
  },
  [3566] = {
    id = 3566,
    title = "Rise, Obsidion!",
    reqLevel = 45,
    questLevel = 52,
    faction = "Alliance",
    zone = "Searing Gorge",
    npc = "Dying Archaeologist",
    objectives = "- Head of Lathoric the Black - Heart of Obsidion",
    rewards = "7,600 XP, 1g 55s",
    tip = "It... It... It was all a trap.\n\nForgive... me.\n\nKill the bastard... Kill him for us... for Thorius.",
    isForever = false,
  },
  [8234] = {
    id = 8234,
    title = "Sealed Azure Bag",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Rogue Class Quests",
    npc = "Lord Jorach Ravenholdt",
    objectives = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara.",
    rewards = "5,100 XP • 60s",
    tip = "First things first.  What I've lost is a small blue bag, the contents of which are a private matter.\n\nDon't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever.\n\nI need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem.",
    isForever = false,
  },
  [5158] = {
    id = 5158,
    title = "Seeking Spiritual Aid",
    reqLevel = 48,
    questLevel = 52,
    faction = "Both",
    zone = "Felwood",
    npc = "Greta Mosshoof",
    objectives = "Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens.",
    rewards = "2,550 XP",
    tip = "Take the corrupt water to the Barrens, $N. South of Ratchet, hidden along the shore, is an old friend of mine, a shaman named Islen Waterseer. She is a powerful shaman who will help us. Her relationship with the spirits of water has always been strong. Our task being a noble one should be enough to persuade her and the spirits of water to aid us in this task.\n\nYou should find her at a small camp right along the water's edge. And, $N, ignore the pirates... they are but a nuisance and no threat to",
    isForever = false,
  },
  [3568] = {
    id = 3568,
    title = "Seeping Corruption",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Undercity",
    npc = "Chemist Cuely",
    objectives = "Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely.",
    rewards = "2,550 XP • 40s",
    tip = "See that tauren behind me--the one who looks like she's going to be ill at any moment? She was in Azshara recently. She claims she was wounded by some naga while making her way through the Ruins of Eldarath.\n\nAfter fighting off a few of them, she took a break on the beach and drank from one of the tide pools. Now she's feeling nauseous... among other things.\n\nI'd like to find out what she drank. Take this box, in it are some empty vials I labeled. Fill each at different pools and come back.",
    isForever = false,
  },
  [3569] = {
    id = 3569,
    title = "Seeping Corruption",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Undercity",
    npc = "Chemist Cuely",
    objectives = "Give Cuely's Elixir to Thersa Windsong in Undercity.",
    rewards = "510 XP",
    tip = "Give this to Thersa. Perhaps it will cure her... perhaps not. We really won't know until after she drinks it.",
    isForever = false,
  },
  [3570] = {
    id = 3570,
    title = "Seeping Corruption",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Undercity",
    npc = "Chemist Cuely",
    objectives = "Speak with Chemist Cuely in Undercity.",
    rewards = "5,100 XP • 75s",
    tip = "",
