  },
  [3463] = {
    id = 3463,
    title = "Set Them Ablaze!",
    reqLevel = 40,
    questLevel = 52,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Squire Maltrake",
    objectives = "- Western Tower Ablaze - Southern Tower Ablaze - Eastern Tower Ablaze - Northern Tower Ablaze",
    rewards = "7,600 XP, 2g 30s",
    tip = "Listen well, $N. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.\n\nWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.\n\nYou must enter each tower and use the Torch of Retribution within their fortifications. Beware the lookouts posted by the Dark Irons, $N.",
    isForever = false,
  },
  [3451] = {
    id = 3451,
    title = "Signal for Pickup",
    reqLevel = 45,
    questLevel = 52,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Xiggs Fuselighter",
    objectives = "Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge.",
    rewards = "510 XP",
    tip = "Ah, so Tymor sent you, huh? Yeah, I owe him a favor or two. What's that? Why, that little devil. Yeah, I can help him out with that. So you'll need a flare gun and a location... easy enough.\n\nThere's a small island off the southern peninsula of Azshara that we've made a landing pad on. You take this flare gun, and use it there. I'll see your signal and come by to pick up this... whatever it is he wants.",
    isForever = false,
  },
  [3483] = {
    id = 3483,
    title = "Signal for Pickup",
    reqLevel = 45,
    questLevel = 52,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Xiggs Fuselighter",
    objectives = "Speak with Xiggs Fuselighter in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [8412] = {
    id = 8412,
    title = "Spirit Totem",
    reqLevel = 50,
    questLevel = 52,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Bath'rah the Windwatcher",
    objectives = "Bring the pieces for the spirit totem to Bath'rah the Windwatcher.",
    rewards = "5,100 XP",
    tip = "The elemental spirits of this place don't be likin' me any more.\n\nYou know about the totems more than any, and I be needin' a spirit totem to protect me.  We already got the elements, now we need somethin' more with more nature.  More primal.\n\nIn the Western Plaguelands you can kill bears for claws and spiders for their eyes.  The carrion birds eat everything, so they might have either one.",
    isForever = false,
  },
  [3517] = {
    id = 3517,
    title = "Stealing Knowledge",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Jediga",
    objectives = "Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara.",
    rewards = "5,100 XP",
    tip = "I admit, $N, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.\n\nBefore I left, I did some research and you would be surprised how many valuable items are lying around.\n\nI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.\n\nThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more.",
    isForever = false,
  },
  [4661] = {
    id = 4661,
    title = "Testing for Corruption - Felwood",
    reqLevel = 48,
