  [8236] = {
    id = 8236,
    title = "The Azure Key",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Rogue Class Quests",
    npc = "Archmage Xylem",
    objectives = "Return the Azure Key to Lord Jorach Ravenholdt.",
    rewards = "6,350 XP • 75s",
    tip = "It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.\n\nThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.\n\nGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key.",
    isForever = false,
  },
  [6028] = {
    id = 6028,
    title = "The Everlook Report",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Gregor Greystone",
    objectives = "Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands.",
    rewards = "2,550 XP • 40s",
    tip = "I am looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Pureheart at Chillwind Camp; it's a ways from here, located along the southern fringe of the Western Plaguelands.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from her!",
    isForever = false,
  },
  [6029] = {
    id = 6029,
    title = "The Everlook Report",
    reqLevel = 50,
    questLevel = 52,
    faction = "Horde",
    zone = "Winterspring",
    npc = "Gregor Greystone",
    objectives = "Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands.",
    rewards = "2,550 XP • 40s",
    tip = "I'm looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Garush at the Bulwark; it's a ways from here, located along the western fringe of the Western Plaguelands, east of Tirisfal Glades.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from h",
    isForever = false,
  },
  [8232] = {
    id = 8232,
    title = "The Green Drake",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Hunter Class Quests",
    npc = "Ogtinc",
    objectives = "Bring the Tooth of Morphaz to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
    rewards = "6,350 XP",
    tip = "Now I set you on a dangerous hunt to slay the green drake, Morphaz, and bring his tooth to me.  Morphaz dwells deep in Temple of Atal'Hakkar, the entrance to which lies in Swamp of Sorrows.\n\nIf you wish to defeat him, you must not go alone.  This drake is an enemy of many -- seek others who wish to destroy him.\n\nThe drake's tooth represents the power a hunter will find in the company of others.  Bring it to me and you will have learned much.",
    isForever = false,
  },
  [8151] = {
    id = 8151,
    title = "The Hunter's Charm",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Hunter Class Quests",
    npc = "Holt Thunderhorn",
    objectives = "Speak to Ogtinc in Azshara.",
    rewards = "500 XP",
    tip = "Ogtinc of Azshara has sent out a call for seasoned hunters such as yourself.  He is a furbolg hunter who has left his tribe to aid the Cenarion Circle.  His teachings are meant to enrich the wisdom of others who share his craft, and guide them toward maintaining a balance.  You would do well to speak with him.\n\nOgtinc resides atop the cliffs of Azshara, northeast from the Ruins of Eldarath.",
    isForever = false,
  },
  [8256] = {
    id = 8256,
    title = "The Ichor of Undeath",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Priest Class Quests",
    npc = "Ogtinc",
    objectives = "Acquire an Ichor of Undeath for Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
    rewards = "5,100 XP",
    tip = "For this restorative salve, you must use a simple formula: one part poison, two parts cure.  You have acquired one cure, now you must gather the poison.\n\nPowerful undead, such as the lingering highborne who wander the Ruins of Eldarath, are sometimes so infused with evil that it coalesces into a sickly greenish goo.  To the living, this substance is known as ichor of undeath.\n\nDue to the potency of this vile element, I require only a single ichor.",
    isForever = false,
  },
  [5049] = {
    id = 5049,
    title = "The Jeremiah Blues",
    reqLevel = 50,
    questLevel = 52,
    faction = "Horde",
    zone = "Undercity",
    npc = "Royal Overseer Bauhaus",
    objectives = "Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone.  If he is, then perhaps he'd like the package Janice Felstone made for him.",
    rewards = "5,100 XP",
    tip = "From the evidence I am able to muster, the person you seek - and the intended recipient of the parcel - is Jeremiah Payson, the Undercity cockroach vendor.\n\nI've always been of the opinion that it takes a special gift to sell... cockroaches.  No doubt you are on quite the epic sojourn now, mighty $c.  I will leave you to your world-shaping endeavors.  Allow me, however, to be a part of your magnum opus and reveal that he is located near the bank, suitably groveling under one of the walkways.",
    isForever = false,
  },
  [104] = {
    id = 104,
    title = "The Sealed Gate of Gilneas",
    reqLevel = 50,
    questLevel = 52,
    faction = "Alliance",
    zone = "Silverpine Forest",
    npc = "Captain Grayson",
    objectives = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.",
    rewards = "1,550 XP",
    tip = "Pro-tip: Foreshadows the newly accessible Gilneas borderlands added in WoW: Forever.",
    isForever = true,
  },
  [8252] = {
    id = 8252,
    title = "The Siren's Coral",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Archmage Xylem",
    objectives = "Collect 6 Enchanted Coral and return them to Archmage Xylem.",
    rewards = "5,100 XP • 75s",
    tip = "Take a look around you.  The ruins and beaches are overrun with spitelash.  Recently, the wretched creatures have learned to recognize the rare components indigenous to Azshara.\n\nSpecifically, I speak of enchanted coral -- they are drawn to it by reasons unknown to me.  Now there is little coral left in the bay, and it is vital to my research.  I need you to separate some enchanted coral from the spitelash sirens and bring it to me.",
    isForever = false,
  },
  [4120] = {
    id = 4120,
    title = "The Strength of Corruption",
    reqLevel = 47,
    questLevel = 52,
    faction = "Horde",
    zone = "Feralas",
    npc = "Talo Thornhoof",
    objectives = "Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.",
    rewards = "5,100 XP",
    tip = "Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, $N.\n\nIn a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well.\n\nGo, $N. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.",
    isForever = false,
  },
  [3909] = {
    id = 3909,
    title = "The Videre Elixir",
    reqLevel = 47,
    questLevel = 52,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Donova Snowden",
    objectives = "Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.",
    rewards = "5,100 XP",
    tip = "Now, what's this? Linken... FORGOT?\n\nOh, I see... Lost his memory...\n\nWell, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult.\n\nListen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas.",
    isForever = false,
  },
  [4041] = {
    id = 4041,
    title = "The Videre Elixir",
    reqLevel = 47,
