  },
  [8421] = {
    id = 8421,
    title = "The Wrong Stuff",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Impsy",
    objectives = "Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.",
    rewards = "5,100 XP",
    tip = "Now that I have my felcloth, I can really begin making *my* pet.\n\nIt's going to need some eyes though.  Perhaps you could rip some rotting wood from the irontree folk for me, so I can carve out some lovely eyes.  They're up north in the Irontree Woods.\n\nI'll also need some bloodvenom essence to give it that new demon smell.  The tainted oozes carry the essence, and they hang out right here near Niby and me.",
    isForever = false,
  },
  [9063] = {
    id = 9063,
    title = "Torwa Pathfinder",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Druid Class Quests",
    npc = "Turak Runetotem",
    objectives = "Speak with Torwa Pathfinder in Un'Goro Crater.",
    rewards = "500 XP",
    tip = "A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him.\n\nThere is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by.",
    isForever = false,
  },
  [9051] = {
    id = 9051,
    title = "Toxic Test",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Druid Class Quests",
    npc = "Torwa Pathfinder",
    objectives = "Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task.",
    rewards = "5,100 XP",
    tip = "The toxin you helped me create is for a special purpose.  The great devilsaurs of the crater make it dangerous to hunt and difficult for me to survive.  Even if I possessed the necessary strength, killing a devilsaur simply allows another to move into its territory.\n\nTake this poisoned barb and stab it deep into a living devilsaur.  The toxin should pacify the creature, though I do not know how quickly...",
    isForever = false,
  },
  [8422] = {
    id = 8422,
    title = "Trolls of a Feather",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Impsy",
    objectives = "Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.",
    rewards = "6,350 XP • 1g 55s",
    tip = "My pet is almost done.  Now I just need something to stuff it with.\n\nOnly the voodoo feathers from the trolls in the sunken temple will do.  They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Kill them.  Kill them all.\n\nThis is no trivial task $n, so I'll make it worth your while by giving you something of Niby's -- he probably doesn't need it anyhow.",
    isForever = false,
  },
  [8425] = {
    id = 8425,
    title = "Voodoo Feathers",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Fallen Hero of the Horde",
    objectives = "Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.",
    rewards = "6,350 XP",
    tip = "Your honor has brought some peace to me.  It is only right that I offer you something in return.\n\nMy weapons and armor were splendid in life, and yet they are of no use to me now.  They would be better served in your possession.\n\nTravel to the sunken temple and destroy the troll guardians Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  They carry magic feathers that can reform my physical body long enough to grant you a reward.",
    isForever = false,
  },
  [8424] = {
    id = 8424,
    title = "War on the Shadowsworn",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Fallen Hero of the Horde",
    objectives = "Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde.",
    rewards = "3,150 XP",
    tip = "The continued presence of the shadowsworn in the Blasted Lands bring great pain to me.  Their dark rituals and spells cause agony unlike any I felt while alive.\n\nThrough you I can deliver my own message of pain.  Go forth and deliver my wrath.",
    isForever = false,
  },
  [8423] = {
    id = 8423,
    title = "Warrior Kinship",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Warrior Class Quests",
    npc = "Fallen Hero of the Horde",
    objectives = "Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde.",
    rewards = "5,100 XP",
    tip = "<The Hero looks you over.>\n\nYou are a $c, no doubt.  I would ask an honorable task of you, but I must test your strength.\n\nIt is said that Rexxar would measure the sharpness of his blades by killing a helboar with a single, swift strike.  Now I will measure your strength by killing them.",
    isForever = false,
  },
  [8231] = {
    id = 8231,
    title = "Wavethrashing",
    reqLevel = 50,
    questLevel = 52,
    faction = "Both",
    zone = "Hunter Class Quests",
    npc = "Ogtinc",
    objectives = "Bring 6 Wavethrasher Scales to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
    rewards = "5,100 XP",
    tip = "The wavethrasher is an amphibious beast living only here in Azshara.  They are powerful and resilient.\n\nThe tough, reflective scales from a wavethrasher mirror the strength of the hunter.\n\nTrack and hunt wavethrashers along the coast of Azshara, and bring me their scales.",
    isForever = false,
  },
  [3565] = {
    id = 3565,
    title = "Xylem's Payment to Jediga",
    reqLevel = 45,
    questLevel = 52,
    faction = "Horde",
    zone = "Azshara",
    npc = "Archmage Xylem",
    objectives = "Deliver Xylem's Note to Jediga in Azshara.",
    rewards = "3,800 XP • 60s",
    tip = "What is it? Oh yes, your payment. Of course.\n\nTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return.",
    isForever = false,
  },
  [4146] = {
    id = 4146,
    title = "Zapper Fuel",
    reqLevel = 47,
    questLevel = 52,
    faction = "Horde",
    zone = "Sunken Temple",
    npc = "Liv Rizzlefix",
    objectives = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.",
    rewards = "5,100 XP",
    tip = "You're in luck, $n! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.\n\nI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.",
    isForever = false,
  },
  [3504] = {
    id = 3504,
    title = "Betrayed",
    reqLevel = 44,
    questLevel = 53,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Belgrom Rockmaul",
    objectives = "Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara.",
    rewards = "2,650 XP",
    tip = "Betraying, thieving woman! That's what I call her--that's all she'll ever be!\n\nI may have made a grave mistake, $N. I trusted a blood elf. What's worse, I trusted a woman!\n\nShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who's the fool--she's killed them all.\n\nI want vengeance, $N, but I can't afford to send anyone else. Find Ag'tor at Valormok, north of the Haldarr Encampment. He'll tell you m",
    isForever = false,
  },
  [3505] = {
    id = 3505,
    title = "Betrayed",
    reqLevel = 44,
    questLevel = 53,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Ag'tor Bloodfist",
    objectives = "Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight.",
    rewards = "3,950 XP",
    tip = "I thought as much.\n\nWe start our crusade against her workers along the southern bluffs on the northern peninsula of Azshara. Kill them with bloody rage--let them know they've betrayed the wrong allies.\n\nDo not concern yourself with her yet--she spends most of her time with her bodyguards searching Azshara. It would be prudent after you've slain her workers to find her personal camp. Scouting out where we can attack her would be wise. Perhaps there is something there we can use to provoke her.",
    isForever = false,
  },
