  [4496] = {
    id = 4496,
    title = "Bungle in the Jungle",
    reqLevel = 50,
    questLevel = 53,
    faction = "Both",
    zone = "Tanaris",
    npc = "Alchemist Pestlezugg",
    objectives = "Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.",
    rewards = "5,250 XP",
    tip = "My research revealed to me that the silithid are like bees; destroy the queen of the hive, and the rest of should be thrown into disarray.  I'll brew a lure that we'll use to bring out the queen; once summoned, you'll take her down.\n\nFirst though, we need some reagents; we don't want you bungling into the jungle unprepared.  Go west to find the silithid hive in Un'Goro Crater and obtain a scent gland from one of the bugs.  I'll also need some samples of the native Un'Goro soil.",
    isForever = false,
  },
  [4243] = {
    id = 4243,
    title = "Chasing A-Me 01",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Karna Remtravel",
    objectives = "Find A-Me 01 in Un'Goro Crater.",
    rewards = "2,650 XP",
    tip = "Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her!\n\nCan you help me find",
    isForever = false,
  },
  [4244] = {
    id = 4244,
    title = "Chasing A-Me 01",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "A-Me 01",
    objectives = "Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.",
    rewards = "3,950 XP",
    tip = "A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, \"Replace Mithril Casing And Turn Power Off Then On.\"\n\nTaking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge.\n\nOnly trying it will tell.",
    isForever = false,
  },
  [4245] = {
    id = 4245,
    title = "Chasing A-Me 01",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "A-Me 01",
    objectives = "Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.",
    rewards = "6,550 XP • 1g 60s",
    tip = "Checking to see if you're prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the \"Off\" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the \"On\" position.\n\nThis is your last chance... are you sure this is what you want to do?",
    isForever = false,
  },
