  [4284] = {
    id = 4284,
    title = "Crystals of Power",
    reqLevel = 47,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "J.D. Collie",
    objectives = "Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.",
    rewards = "5,250 XP • 80s",
    tip = "I'm sure you've noticed 'em, $N. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?",
    isForever = false,
  },
  [3881] = {
    id = 3881,
    title = "Expedition Salvation",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Williden Marshal",
    objectives = "- Crate of Foodstuffs - Research Equipment",
    rewards = "5,250 XP, 40s",
    tip = "I don't know how you made it here, but you're a sight for sore eyes!  I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Our latest and greatest endeavor has met with what seems like countless disasters, the most serious of which being that we underestimated the savagery of Un'Goro Crater!\n\nAs we fled our base camps in the southwestern and northeastern parts of the crater, we left behind vital supplies.  You look like you're capable enough - can you help us by getting them back?",
    isForever = false,
  },
  [5218] = {
    id = 5218,
    title = "Felstone Field Cauldron",
    reqLevel = 50,
    questLevel = 53,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Object: Scourge Cauldron",
    objectives = "- Arcane Quickener - Osseous Agitator x 6 - Runecloth x 4",
    rewards = "530 XP",
    tip = "",
    isForever = false,
  },
  [3824] = {
    id = 3824,
    title = "Gor'tesh the Brute Lord",
    reqLevel = 48,
    questLevel = 53,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Oralius",
    objectives = "- Gor'tesh's Lopped Off Head",
    rewards = "5,250 XP",
    tip = "They're reeling I tell you! Our next strike must be decisive.\n\nThe brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres.\n\nBe warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock.\n\nYour orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done.\n\nSHUT UP, WINKY!",
    isForever = false,
  },
  [1446] = {
    id = 1446,
    title = "Jammal'an the Prophet",
    reqLevel = 38,
    questLevel = 53,
    faction = "Both",
    zone = "Sunken Temple",
    npc = "Atal'ai Exile",
    objectives = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.",
    rewards = "6,550 XP",
    tip = "My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be fr",
    isForever = false,
  },
  [3601] = {
    id = 3601,
    title = "Kim'jael Indeed!",
    reqLevel = 47,
    questLevel = 53,
    faction = "Both",
    zone = "Azshara",
    npc = "Kim'jael",
    objectives = "Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara.",
    rewards = "6,550 XP • 8s",
    tip = "Kim'jael indeed!! Do you know what Kim'jael means to the Blood elves, $N? Little rat... or something like that. The big bullies!\n\nThey hired me to help them scout the area looking for some sort of lost treasures. Of course I jumped aboard the moment they said \"treasure\" and the amount they were willing to pay, but of course, they turned on me and tried to kill me... ME!\n\nGoes to show you, you can't trust a Blood elf.\n\nThe problem is, they still have my equipment and I can't get it back. Help me ",
    isForever = false,
  },
  [5534] = {
    id = 5534,
    title = "Kim'jael's \"Missing\" Equipment",
    reqLevel = 47,
    questLevel = 53,
    faction = "Both",
    zone = "Azshara",
    npc = "Kim'jael",
    objectives = "Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara.",
    rewards = "6,550 XP • 1g 60s",
    tip = "What?! What?!\n\nThat wasn't good enough for you? You know how expensive those explosives are? They sell for... oh, nevermind. Fine, you want to make some real money? Cause that's how business is done: you prove you're a valuable employee and then you're rewarded adequately after you stick it out some.\n\nIf you're a \"valuable\" employee, then hit the Ruins of Eldarath and find me some rune that them Blood elves were lookin' for. The naga apparently have it in their possession.",
    isForever = false,
  },
  [3822] = {
    id = 3822,
    title = "Krom'Grul",
    reqLevel = 48,
    questLevel = 53,
    faction = "Horde",
    zone = "Burning Steppes",
    npc = "Sha'ni Proudtusk",
    objectives = "- Sha'ni's Nose-Ring",
    rewards = "5,250 XP",
    tip = "My whole platoon was captured, $N. All were slain - except me.\n\nTheir leader, Krom'Grul, wanted to save me for some sort of ritual.\n\nI was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery!\n\nFind Krom'Grul and kill him! Take my ring back to Thal'trak.\n\nAnd $N, tell him that we will meet again... in another life.",
    isForever = false,
  },
  [4321] = {
    id = 4321,
    title = "Making Sense of It",
    reqLevel = 47,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "J.D. Collie",
    objectives = "Speak with J.D. Collie in a moment.",
    rewards = "530 XP",
    tip = "The information you have given me about the pylons is very interesting...\n\nGive me a moment to do some calculations, $N. Speak to me again in a moment and I should be able to give you the answer we have been looking for.",
    isForever = false,
  },
  [4493] = {
    id = 4493,
    title = "March of the Silithid",
    reqLevel = 50,
    questLevel = 53,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Gracina Spiritmight",
    objectives = "Speak to Alchemist Pestlezugg in Gadgetzan.",
    rewards = "530 XP",
    tip = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.\n\nWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the si",
    isForever = false,
  },
  [4494] = {
    id = 4494,
    title = "March of the Silithid",
    reqLevel = 50,
    questLevel = 53,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Zilzibin Drumlore",
    objectives = "Speak to Alchemist Pestlezugg in Gadgetzan.",
    rewards = "530 XP",
    tip = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.\n\nWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the si",
    isForever = false,
  },
  [3825] = {
    id = 3825,
    title = "Ogre Head On A Stick = Party",
    reqLevel = 48,
    questLevel = 53,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Oralius",
    objectives = "- Gor'tesh Head Planted",
    rewards = "5,250 XP, 2g 40s",
    tip = "Just one last thing you must do, soldier.\n\nI've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work.\n\n<Oralius seems to be losing touch with reality.>",
    isForever = false,
  },
  [5217] = {
    id = 5217,
    title = "Return to Chillwind Camp",
    reqLevel = 50,
    questLevel = 53,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Object: Scourge Cauldron",
    objectives = "Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.",
    rewards = "2,650 XP • 80s",
    tip = "You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied.\n\nWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.",
    isForever = false,
  },
  [5230] = {
    id = 5230,
    title = "Return to the Bulwark",
    reqLevel = 50,
    questLevel = 53,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Object: Scourge Cauldron",
