    isForever = false,
  },
  [4136] = {
    id = 4136,
    title = "Ribbly Screwspigot",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Yuka Screwspigot",
    objectives = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",
    rewards = "2,650 XP • 60s",
    tip = "My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another.\n\nWell, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head.  I can't tell you how happy this makes the Screwspigots!  Our little Ribbly's finally worth something!\n\nBut now he's hiding out, deep in Blackrock Depths.  Please, find him and bring him to me!\n\nOr, if he won't come, then that's ok... just bring me his head",
    isForever = false,
  },
  [2994] = {
    id = 2994,
    title = "Saving Sharpbeak",
    reqLevel = 40,
    questLevel = 53,
    faction = "Alliance",
    zone = "The Hinterlands",
    npc = "Gryphon Master Talonaxe",
    objectives = "Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.",
    rewards = "7,350 XP • 2g 25s",
    tip = "We must save Sharpbeak!\n\nFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!",
    isForever = false,
  },
  [5096] = {
    id = 5096,
    title = "Scarlet Diversions",
    reqLevel = 50,
    questLevel = 53,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "High Executor Derrington",
    objectives = "Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.\n\nPlace the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands.",
    rewards = "5,250 XP • 80s",
    tip = "Before Andorhal, we must tackle the advancing Scarlet Crusade menace from Hearthglen.  They've made camp between Felstone Field and Dalson's Tears, making us risk conflict against both the Scourge and the Crusade at once.\n\nMy plan is to play them off of each other by sending you to destroy the command tent they've set up; use some Flame in a Bottle from this box of incendiaries.  Once razed, plant this Scourge banner by the tent.  With some luck, they'll ignore us and focus on the Scourge for ve",
    isForever = false,
  },
  [5216] = {
    id = 5216,
    title = "Target: Felstone Field",
    reqLevel = 50,
    questLevel = 53,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "High Priestess MacDonnell",
    objectives = "- Felstone Field Cauldron Key",
    rewards = "5,250 XP",
    tip = "Of the four cauldrons here in the west, the one located at Felstone Field may be the easiest one in obtaining access to.  The Scourge have greener troops positioned here, though they should not be underestimated.\n\nGo to Felstone Field, northwest of Andorhal, and engage the cauldron lord there.  We think it has a key that will unlock access to the cauldron.  When unlocked, use this bottle to obtain a sample of the poisons inside the cauldron; we'll need it for study in developing a counter agent.",
    isForever = false,
  },
  [5229] = {
    id = 5229,
    title = "Target: Felstone Field",
    reqLevel = 50,
    questLevel = 53,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Shadow Priestess Vandis",
    objectives = "- Felstone Field Cauldron Key",
    rewards = "5,250 XP",
    tip = "Of the four cauldrons in the Western Plaguelands, the one at Felstone Field may be the easiest one to gain access to.  The Scourge have greener troops positioned here, though they should not be underestimated.\n\nGo to Felstone Field, due east of here and northwest of Andorhal, and engage the cauldron lord there.  On it is a key that will unlock access to the cauldron.  When unlocked, use this bottle to get a sample of the cauldron's toxins; we'll need it for study in developing a counter agent.",
    isForever = false,
  },
  [4287] = {
    id = 4287,
    title = "The Eastern Pylon",
    reqLevel = 47,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "J.D. Collie",
    objectives = "Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.",
    rewards = "3,950 XP",
    tip = "During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, $N. I guess that they are quite large, with crystals lining their interiors.\n\nAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found\n\nSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?",
    isForever = false,
  },
  [4290] = {
    id = 4290,
    title = "The Fare of Lar'korwi",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Torwa Pathfinder",
    objectives = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.",
    rewards = "5,250 XP",
    tip = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nReturn to me afterwards.",
    isForever = false,
  },
  [3528] = {
    id = 3528,
    title = "The God Hakkar",
    reqLevel = 40,
    questLevel = 53,
    faction = "Both",
    zone = "Sunken Temple",
    npc = "Yeh'kinya",
    objectives = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.",
    rewards = "7,900 XP • 2g 40s",
    tip = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the egg of Hakkar.",
    isForever = false,
  },
  [4285] = {
    id = 4285,
    title = "The Northern Pylon",
    reqLevel = 47,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "J.D. Collie",
    objectives = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.",
    rewards = "3,950 XP",
    tip = "What could they be for? I can't get the thought out of my head!\n\nIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.\n\nAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, $N. I just know they exist.",
    isForever = false,
  },
  [4291] = {
    id = 4291,
    title = "The Scent of Lar'korwi",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Torwa Pathfinder",
    objectives = "Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.",
    rewards = "5,250 XP",
    tip = "I'm actually surprised he has not come for you yet, $N. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those gl",
    isForever = false,
  },
  [5215] = {
    id = 5215,
    title = "The Scourge Cauldrons",
    reqLevel = 50,
    questLevel = 53,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Commander Ashlam Valorfist",
    objectives = "Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands.",
    rewards = "530 XP",
    tip = "Within the lands of former Lordaeron are eight cauldrons - four here in the west, and four more ensconced in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.\n\nThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, High Priestess MacDonnell, will be your point on this assignment; she'll continue the briefing from here.",
    isForever = false,
  },
  [5228] = {
    id = 5228,
    title = "The Scourge Cauldrons",
    reqLevel = 50,
    questLevel = 53,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "High Executor Derrington",
    objectives = "Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands.",
    rewards = "530 XP",
    tip = "Within the lands of former Lordaeron are eight cauldrons - four in the west, and four more entrenched in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.\n\nThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, Shadow Priestess Vandis, will be your point on this assignment; she'll continue the briefing from here.",
    isForever = false,
  },
  [4288] = {
    id = 4288,
    title = "The Western Pylon",
    reqLevel = 47,
    questLevel = 53,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "J.D. Collie",
    objectives = "Discover the location of the Western Crystal Pylon.",
    rewards = "3,950 XP",
    tip = "My experiments so far have not yielded any positive results, $N. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.\n\nPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!\n\n$N, search the western area of the crater; a pylon is said to be somewhere in that area.",
    isForever = false,
  },
  [4324] = {
    id = 4324,
    title = "Yuka Screwspigot",
    reqLevel = 48,
    questLevel = 53,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Yorba Screwspigot",
    objectives = "Speak with Yuka Screwspigot in the Burning Steppes.",
    rewards = "Experience & Faction Reputation",
    tip = "Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands.\n\nSo, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.",
    isForever = false,
  },
  [4513] = {
    id = 4513,
    title = "A Little Slime Goes a Long Way",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Laris Geardawdle",
    objectives = "Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.\n\nIf you have trouble finding them, perhaps try to get more clues from Laris.",
    rewards = "6,800 XP • 40s",
    tip = "I'm going to need more samples, $N. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure. I do know that these are corrupt... just like Felwood. Which is what makes my realization so important. The oozes seem to adapt... to take on the aspects of the area they're in. I'll need to find samples that haven't been polluted. But where? Where?!\n\nBah! $N, take these containers just in case you find any on your own.",
    isForever = false,
  },
  [6605] = {
    id = 6605,
    title = "A Strange One",
    reqLevel = 49,
    questLevel = 54,
    faction = "Horde",
    zone = "Winterspring",
    npc = "Harlo Wigglesworth",
    objectives = "Speak with Winna Hazzard in Felwood.",
    rewards = "540 XP",
    tip = "I just got back from Felwood, $N. On my way through, I stopped at Bloodvenom Post and I met a very odd character... She seemed intent on one thing, and I suppose I could tell you what that is, but I think she'd like to explain it to you herself.\n\nIf you're interested, head to Bloodvenom Post in western Felwood and look for Winna Hazzard.\n\nWho knows, she might need your help...",
    isForever = false,
  },
  [4022] = {
    id = 4022,
    title = "A Taste of Flame",
    reqLevel = 52,
    questLevel = 54,
    faction = "Both",
    zone = "Burning Steppes",
    npc = "Cyrus Therepentous",
    objectives = "- Black Dragonflight Molt - Proof Presented",
    rewards = "5,450 XP",
    tip = "The flight is aware of your work in the Searing Gorge.\n\nShow it to me, $r. The molt, imbecile.",
    isForever = false,
  },
  [4023] = {
    id = 4023,
    title = "A Taste of Flame",
    reqLevel = 52,
    questLevel = 54,
    faction = "Both",
    zone = "Burning Steppes",
    npc = "Cyrus Therepentous",
    objectives = "Show Cyrus Therepentous proof of your worth.\n\nYou have a feeling that Cyrus already knows that you are unworthy.",
    rewards = "5,450 XP",
    tip = "You seek out the Flight? Present to me proof of your worth, mortal.",
    isForever = false,
  },
  [4242] = {
    id = 4242,
    title = "Abandoned Hope",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Marshal Windsor",
    objectives = "Give Marshal Maxwell the bad news.",
    rewards = "5,450 XP",
    tip = "Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.\n\nHe is a blind buffoon. Proof stands two feet away from him and he does not see.\n\nAs for my data, it's lost. Gone. Unrecoverable.\n\nShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.\n\nLeave me, $N.",
    isForever = false,
  },
  [4005] = {
    id = 4005,
    title = "Aquementas",
    reqLevel = 47,
    questLevel = 54,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Eridan Bluewind",
    objectives = "Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.\n\nUse the Book of Aquor to summon Aquementas.\n\nAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge.",
    rewards = "5,450 XP",
    tip = "Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.\n\nThe eastmost peninsula is the secret...\n\nFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.\n\nAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items.",
    isForever = false,
  },
  [4508] = {
    id = 4508,
    title = "Calm Before the Storm",
    reqLevel = 50,
    questLevel = 54,
    faction = "Alliance",
    zone = "Tanaris",
    npc = "Alchemist Pestlezugg",
    objectives = "Bring Pestlezugg's Un'Goro Report to Gracina Spiritmight in Darnassus.",
    rewards = "540 XP",
    tip = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.\n\nTake my latest report back to Gracina Spiritmight in Darnassus; she's still at the Temple of the Moon, is she not?  She's got friends who are Alliance bigwigs; if we can get them involved in this $N, then we just might make it out of this alive.",
    isForever = false,
  },
  [4509] = {
    id = 4509,
    title = "Calm Before the Storm",
    reqLevel = 50,
    questLevel = 54,
    faction = "Horde",
    zone = "Tanaris",
    npc = "Alchemist Pestlezugg",
    objectives = "Bring Pestlezugg's Un'Goro Report to Zilzibin Drumlore in Orgrimmar.",
    rewards = "540 XP",
    tip = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.\n\nTake my latest report back to Zilzibin Drumlore in Orgrimmar; he's still in his place on the upper part of the Drag, is he not?  He's got friends who are high within the Horde; if we can get them involved in this $N, then we just might make it out of this alive.",
    isForever = false,
  },
  [4510] = {
    id = 4510,
    title = "Calm Before the Storm",
    reqLevel = 50,
    questLevel = 54,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Gracina Spiritmight",
    objectives = "Bring the Bank Voucher to Idriana in the bank of Darnassus.",
    rewards = "8,150 XP",
    tip = "$N, your help has been immeasurable.  The time will come, no doubt, when I'll ask for your assistance against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.\n\nTake this note to Idriana at the bank.  She'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, brave $c.",
    isForever = false,
  },
  [4511] = {
    id = 4511,
    title = "Calm Before the Storm",
    reqLevel = 50,
    questLevel = 54,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Zilzibin Drumlore",
    objectives = "Bring the Bank Voucher to Karus in the bank of Orgrimmar.",
    rewards = "8,150 XP",
    tip = "$N, we could not have gotten this far without you.  The time will come soon, no doubt, when I'll ask for your help against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.\n\nTake this note to Karus at the bank.  He'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, mi",
    isForever = false,
  },
  [4809] = {
    id = 4809,
    title = "Chillwind Horns",
    reqLevel = 50,
    questLevel = 54,
    faction = "Both",
    zone = "Winterspring",
    npc = "Felnok Steelspring",
    objectives = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.",
    rewards = "5,450 XP",
    tip = "I have most of what Tinkee needs, but I'm missing one important component, and that's chillwind horns.  The horns of the chillwind chimaera in Winterspring are a concentrated source of cold, but only pristine, uncracked horns will do!  I'll need a supply of those to complete Tinkee's order.\n\nBring me the uncracked chillwind horns, and I'll prepare a package for Tinkee.",
    isForever = false,
  },
  [5159] = {
    id = 5159,
    title = "Cleansed Water Returns to Felwood",
    reqLevel = 48,
    questLevel = 54,
    faction = "Both",
    zone = "Felwood",
    npc = "Islen Waterseer",
    objectives = "Take the Purified Moon Well Water to Greta Mosshoof in Felwood.",
    rewards = "2,700 XP",
    tip = "Thank the spirits, $N. They are the ones that have come to your aid, not me.\n\nI give this purified water to you now. Please give my regards to Greta and my best wishes. She is tackling something greater than many of us... as I'm sure she will soon find out.\n\nThe Shadow Council is not a force to be trifled with, $N. Remember that.\n\nGo now. Take the water and return to Greta.",
    isForever = false,
  },
  [4506] = {
    id = 4506,
    title = "Corrupted Sabers",
    reqLevel = 49,
    questLevel = 54,
    faction = "Horde",
    zone = "Felwood",
    npc = "Winna Hazzard",
    objectives = "Take Winna's kitten to the corrupted moon well, release it, then bring it back to Winna.\n\nOnce you have returned to Winna, click on the cat to release it to Winna.",
    rewards = "5,450 XP • 60s",
    tip = "This corrupted water can be used to our advantage, $N. With just a small amount of the water, my kitten doubled in size, and seems to be stronger... somehow. These cats may prove useful...\n\nHere, $N. Take this cat carrier, and release the kitten inside next to the moonwell in the Ruins of Constellas. Heh, heh... I'm sure you'll be pleased with the results!\n\nReturn the cat to me, and I'm sure I can make it worth your time.",
    isForever = false,
  },
  [4182] = {
    id = 4182,
    title = "Dragonkin Menace",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Helendis Riverhorn",
    objectives = "- Black Broodling x 15 - Black Dragonspawn x 10 - Black Drake - Black Wyrmkin x 4",
    rewards = "5,450 XP, 1g 65s",
    tip = "Life in the Burning Steppes is rife with conflict.\n\nJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.\n\nEnough lamenting! We have a problem, $N. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.",
    isForever = false,
  },
  [4441] = {
    id = 4441,
    title = "Felbound Ancients",
    reqLevel = 49,
    questLevel = 54,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Eridan Bluewind",
    objectives = "Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.",
    rewards = "5,450 XP",
    tip = "The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves.\n\nThe satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related.\n\nWe must try to purify the flute, $N. Bring me blessed water from the Temple of the Moon in Darn",
    isForever = false,
  },
  [4808] = {
    id = 4808,
    title = "Felnok Steelspring",
    reqLevel = 50,
    questLevel = 54,
    faction = "Both",
    zone = "Burning Steppes",
    npc = "Tinkee Steamboil",
    objectives = "Give Tinkee's Letter to Felnok Steelspring.",
    rewards = "2,700 XP",
    tip = "I have another favor to ask of you.\n\nMy initial study of the essence you collected shows that it might be possible to freeze dragon whelp eggs and preserve them!  I want to test this theory, but first I need specially made engineering components.  My colleague, Felnok Steelspring, can make them.\n\nHere, take this letter to Felnok.  It tells him what I need.  You'll find Felnok in Winterspring, in the town of Everlook.",
    isForever = false,
  },
  [939] = {
    id = 939,
    title = "Flute of Xavaric",
    reqLevel = 49,
    questLevel = 54,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Item: Flute of Xavaric",
    objectives = "Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood.",
    rewards = "5,450 XP",
    tip = "You study the simple wooden flute you picked up after defeating Xavaric.\n\nThe knotted wood feels solid, but it seems as if the spirals and patterns in the surface begin to spin and move as you turn it over in your hands. Suddenly, you feel a sense of dread...\n\nYou shake your head, sure that your mind is playing tricks on you.\n\nIt's possible that other satyrs carry clues as to what you have found. Bring your findings to the druid, Eridan Bluewind, that lives in southern Felwood.",
    isForever = false,
  },
  [4906] = {
    id = 4906,
    title = "Further Corruption",
    reqLevel = 49,
    questLevel = 54,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Eridan Bluewind",
    objectives = "Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed.",
    rewards = "5,450 XP",
    tip = "A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood.\n\nXavathras and his minions were only part of a larger plan -- to cultivate a corrupted moonwell, and then provide the spoils to Xavaric.\n\nNow that Xavathras is out of the way, finish this task, $N. Head to the north and defeat Xavaric.",
    isForever = false,
  },
  [4082] = {
    id = 4082,
    title = "KILL ON SIGHT: High Ranking Dark Iron Officials",
    reqLevel = 50,
    questLevel = 54,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Object: KILL ON SIGHT",
    objectives = "- Anvilrage Medic x 10 - Anvilrage Soldier x 10 - Anvilrage Officer x 10",
    rewards = "5,450 XP, 1g 65s",
    tip = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!\n\nCompletion of this mission will result in a tribute.",
    isForever = false,
  },
  [3961] = {
    id = 3961,
    title = "Linken's Adventure",
    reqLevel = 47,
    questLevel = 54,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "J.D. Collie",
    objectives = "Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.",
    rewards = "2,700 XP",
    tip = "To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart.\n\nBring the totem to him. See if that helps him remember why he came here.",
    isForever = false,
  },
  [3942] = {
    id = 3942,
    title = "Linken's Memory",
    reqLevel = 47,
    questLevel = 54,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "J.D. Collie",
    objectives = "Find Eridan Bluewind in southern Felwood.",
    rewards = "5,450 XP",
    tip = "Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine.\n\nSomething he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think?\n\nI doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?",
    isForever = false,
  },
  [4241] = {
    id = 4241,
    title = "Marshal Windsor",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Marshal Maxwell",
    objectives = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\n\nYou recall Ragged John talking about Windsor being dragged off to a prison.",
    rewards = "5,450 XP",
    tip = "So that good for nothing coward says that Windsor is alive, eh?\n\nSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.\n\n<Maxwell laughs.>\n\nI bet you are getting tired of hearing that, aren't you?",
    isForever = false,
  },
  [4507] = {
    id = 4507,
    title = "Pawn Captures Queen",
    reqLevel = 50,
    questLevel = 54,
    faction = "Both",
    zone = "Tanaris",
    npc = "Alchemist Pestlezugg",
    objectives = "Defeat the Gorishi Hive Queen once she is summoned.\n\nBring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan.",
    rewards = "5,450 XP",
    tip = "Here's the lure.  Inside the hive network should be a crystal of some sort.  We think the silithid use the crystal as some sort of hive-wide attunement device.  As for where this crystal might be, I'd say try the hatcheries inside the hive.\n\nUsing the lure on the crystal should roust out the queen, but be warned - she will probably be protected by several guards.  Take out the queen and remove her brain.  As icky as that sounds, we desperately need to study it.  Good luck, $N!",
    isForever = false,
  },
  [4442] = {
    id = 4442,
    title = "Purified!",
    reqLevel = 49,
    questLevel = 54,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Eridan Bluewind",
    objectives = "Speak to Eridan again in a moment.",
    rewards = "5,450 XP",
    tip = "Using the water of Elune, I will attempt to purify the flute. We must end this suffering...\n\nMay Elune guide my hands and heart.\n\nSpeak with me again in a moment.",
    isForever = false,
  },
  [4810] = {
    id = 4810,
    title = "Return to Tinkee",
    reqLevel = 50,
    questLevel = 54,
    faction = "Both",
    zone = "Winterspring",
    npc = "Felnok Steelspring",
    objectives = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes.",
    rewards = "2,700 XP",
    tip = "Ok, everything is prepared and packed and ready for transport!  Good luck in your journey, and make sure you tell Tinkee that she owes me!",
    isForever = false,
  },
  [4504] = {
    id = 4504,
    title = "Super Sticky",
    reqLevel = 48,
    questLevel = 54,
    faction = "Both",
    zone = "Tanaris",
    npc = "Tran'rek",
    objectives = "Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan.",
    rewards = "5,450 XP • 1g 65s",
    tip = "I'm always looking for a quick way to earn a gold, $N. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nHead to the tar pits in northern Un'Goro Crater, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. Regular tar just simply isn't sticky enough.\n\nThe plant-like creatures contain chlorophyll in their skin, and mixed with the tar, it's super sticky!",
    isForever = false,
  },
  [4421] = {
    id = 4421,
    title = "The Corruption of the Jadefire",
    reqLevel = 49,
    questLevel = 54,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Eridan Bluewind",
    objectives = "Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.",
    rewards = "5,450 XP",
    tip = "Not many seek adventure here... Felwood's corruption is widespread and indiscriminate.\n\nAs part of the Emerald Circle, I seek to heal this land, but there are some that wish it to fester.\n\nThe ones I speak of are the Jadefire satyrs that dwell to the northwest of here, at the Ruins of Constellas. Led by a particularly cruel satyr named Xavathras, they continue to spread the disease to any creatures they encounter.\n\nWe must defend this land that was once ours. Defeat Xavathras and destroy his min",
    isForever = false,
  },
  [4002] = {
    id = 4002,
    title = "The Eastern Kingdom",
    reqLevel = 48,
    questLevel = 54,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Thrall",
    objectives = "Speak with Thrall if you are prepared to take on the mission he has planned.",
    rewards = "540 XP",
    tip = "You bring excellent information, $N.\n\nAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.\n\nThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!\n\nAre you prepared?",
    isForever = false,
  },
  [7201] = {
    id = 7201,
    title = "The Last Element",
    reqLevel = 48,
    questLevel = 54,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Shadowmage Vivian Lagrave",
    objectives = "- Essence of the Elements x 10",
    rewards = "5,450 XP, 2g 45s",
    tip = "There is work to be had for those venturing into the depths, $N.\n\nThe Dark Irons have mastered creation of extremely powerful golems.\n\nInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.\n\nJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the ",
    isForever = false,
  },
  [4201] = {
    id = 4201,
    title = "The Love Potion",
    reqLevel = 50,
    questLevel = 54,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Mistress Nagmara",
    objectives = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.",
    rewards = "5,450 XP • 80s",
    tip = "Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It's maddening!\n\nYou must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro.  You can place the water in this vial.\n\nPlease, $N, help a poor soul in her quest for happiness!",
    isForever = false,
  },
  [4061] = {
    id = 4061,
    title = "The Rise of the Machines",
    reqLevel = 52,
    questLevel = 54,
    faction = "Horde",
    zone = "Burning Steppes",
    npc = "Hierophant Theodora Mulvadania",
    objectives = "- Fractured Elemental Shard x 10",
    rewards = "5,450 XP, 1g 65s",
    tip = "The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, $N.\n\nYour first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin.",
    isForever = false,
  },
  [4062] = {
    id = 4062,
    title = "The Rise of the Machines",
    reqLevel = 52,
    questLevel = 54,
    faction = "Horde",
    zone = "Badlands",
    npc = "Hierophant Theodora Mulvadania",
    objectives = "Take the Elemental Shard Sample to Lotwil Veriatus.\n\nYou recall Theodora saying that Lotwil was stationed in a camp to the east.",
    rewards = "1,350 XP",
    tip = "G.L.A.\n\nThose are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank.\n\nTake this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search.",
    isForever = false,
  },
  [3701] = {
    id = 3701,
    title = "The Smoldering Ruins of Thaurissan",
    reqLevel = 50,
    questLevel = 54,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Royal Historian Archesonus",
    objectives = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.",
    rewards = "5,450 XP • 1g 65s",
    tip = "Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.\n\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, $N. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.",
    isForever = false,
  },
  [3702] = {
    id = 3702,
    title = "The Smoldering Ruins of Thaurissan",
    reqLevel = 50,
    questLevel = 54,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Royal Historian Archesonus",
    objectives = "Listen to Royal Historian Archesonus recant the history of Thaurissan.",
    rewards = "540 XP",
    tip = "Would you like to hear a brief history of the Dark Iron dwarves?",
    isForever = false,
  },
  [4183] = {
    id = 4183,
    title = "The True Masters",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Helendis Riverhorn",
    objectives = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon.",
    rewards = "4,100 XP",
    tip = "We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.\n\nIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.\n\nTake this letter to Magistrate Solomon. He will know what must be done.\n\n<Helendis hands you a sealed letter.",
    isForever = false,
  },
  [4184] = {
    id = 4184,
    title = "The True Masters",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Magistrate Solomon",
    objectives = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.\n\nBolvar resides in Stormwind Keep.",
    rewards = "4,100 XP",
    tip = "This is grim news, $N. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?\n\nYou must take this information to Highlord Bolvar Fordragon in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is",
    isForever = false,
  },
  [4185] = {
    id = 4185,
    title = "The True Masters",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Highlord Bolvar Fordragon",
    objectives = "- Advice from Lady Prestor",
    rewards = "540 XP",
    tip = "Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.\n\nSpeak with Lady Prestor, $N. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.",
    isForever = false,
  },
  [4186] = {
    id = 4186,
    title = "The True Masters",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Highlord Bolvar Fordragon",
    objectives = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire.",
    rewards = "5,450 XP",
    tip = "I am going to empower you as an acting deputy of Stormwind, $N.\n\nReturn to Magistrate Solomon in Lakeshire and deliver this decree.",
    isForever = false,
  },
  [4223] = {
    id = 4223,
    title = "The True Masters",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Magistrate Solomon",
    objectives = "Speak with Marshal Maxwell in the Burning Steppes.",
    rewards = "540 XP",
    tip = "<Magistrate Solomon sighs.>\n\nYou must return to the Burning Steppes, $N. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.",
    isForever = false,
  },
  [4224] = {
    id = 4224,
    title = "The True Masters",
    reqLevel = 48,
    questLevel = 54,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Marshal Maxwell",
    objectives = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.\n\nYou recall Marshal Maxwell telling you to search for him in a cave to the north.",
    rewards = "540 XP",
    tip = "What? You thought you were the first? How many soldiers must we lose before Stormwind acts?\n\nWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.\n\nWhat we need is that documentation. Speak with Ragged John, $N. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.",
    isForever = false,
  },
  [4984] = {
    id = 4984,
    title = "The Wildlife Suffers Too",
    reqLevel = 51,
    questLevel = 54,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Mulgris Deepriver",
    objectives = "- Diseased Wolf x 8",
    rewards = "4,100 XP",
    tip = "While there was little I could do alone to thwart the Scourge, I nevertheless came to these lands to try and heal the damage done to nature.  Animals suffer from the plague that continues to choke these lands, unable to find mercy and peace.  I ask for you to continue what I could not finish here.\n\nThere is no salvation for the suffering animals but a sweet and merciful release.  Seek out diseased wolves nearby and put them down.  Please $N, end their misery - doing so will surely soothe mine.",
    isForever = false,
  },
  [5051] = {
    id = 5051,
    title = "Two Halves Become One",
    reqLevel = 50,
    questLevel = 54,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Janice Felstone",
    objectives = "Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.\n\nGive the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands.",
    rewards = "5,450 XP",
    tip = "The ramblings of the poor ghost continue:\n\n\"I'm so cold, John.  Bring me your charm, and we'll be together!  Quickly John, before the plague comes to change us into hideous beasts!  I can't see you John... but I know you're near.  I feel you near me.\"\n\nPerhaps if the second half of the charm was found and reassembled, this would constitute what the spirit of Janice Felstone is seeking.",
    isForever = false,
  },
  [5156] = {
    id = 5156,
    title = "Verifying the Corruption",
    reqLevel = 48,
    questLevel = 54,
    faction = "Both",
    zone = "Felwood",
    npc = "Taronn Redfeather",
    objectives = "Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.",
    rewards = "6,800 XP • 1g 65s",
    tip = "To the north, along the east of the road in what's called Shatter Scar Vale, is an area where infernals were called down during the last great war--the craters still scar the land, as do the infernals themselves.\n\nI am curious about two things. First, are there still entropic elementals roaming the area? And second, are the craters still filled with the corrupt, fetid water that gathered there years ago? Will you help me and check, $N? Be careful though, the infernals destroy anything in their p",
    isForever = false,
  },
  [4505] = {
    id = 4505,
    title = "Well of Corruption",
    reqLevel = 49,
    questLevel = 54,
    faction = "Horde",
    zone = "Felwood",
    npc = "Winna Hazzard",
    objectives = "Collect a sample of corrupted water from the Jadefire Satyrs' moonwell and bring it to Winna Hazzard at Bloodvenom Post.",
    rewards = "5,450 XP",
    tip = "Some may say that I am exceptionally cruel... But truly, it is only a strong desire to see the Horde gain an advantage against the Alliance, in any way possible.\n\nMy newest interest is a moonwell at the Ruins of Constellas, south of here, tended by the Jadefire satyrs. The moonwell, once a symbol of renewal for the insufferable night elves, is now corrupted, and used to bring forth more satyrs.\n\nI have an idea, $N, and I'd like a sample of the water... for my little feline friend here.",
    isForever = false,
  },
  [3982] = {
    id = 3982,
    title = "What Is Going On?",
    reqLevel = 48,
    questLevel = 54,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Commander Gor'shak",
    objectives = "Defend Gor'shak.",
    rewards = "5,450 XP",
    tip = "I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.\n\n<Gor'shak whispers.>\n\nThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.\n\n<Gor'shak laughs.>\n\nShhh! Do you hear that? Guards coming! DEFEND YOURSELF!",
    isForever = false,
  },
  [4001] = {
    id = 4001,
    title = "What Is Going On?",
    reqLevel = 48,
    questLevel = 54,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Commander Gor'shak",
    objectives = "- Information Gathered from Kharan",
    rewards = "6,800 XP",
    tip = "So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.\n\nGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.\n\nThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!",
    isForever = false,
  },
  [4491] = {
    id = 4491,
    title = "A Little Help From My Friends",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Ringo",
    objectives = "Lead Ringo to Spraggle Frock at Marshal's Refuge.\n\nIf Ringo faints, use Spraggle's Canteen to revive him.",
    rewards = "5,650 XP",
    tip = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Refuge. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so if I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...",
    isForever = false,
  },
  [5901] = {
    id = 5901,
    title = "A Plague Upon Thee",
    reqLevel = 48,
    questLevel = 55,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Mickey Levine",
    objectives = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.",
    rewards = "5,650 XP • 85s",
    tip = "So, to bring pain and strife to the Scarlet Crusade, I want to take their precious lumber mill from them. I'm sure the loss of such a resource will cause them a great deal of harm in defending and rebuilding the town for their own reasons. Will you help me, $N?\n\nStart by taking this jar to Plaguewood in the Eastern Plaguelands. Fill it with the termites you find in their mounds throughout the woods. Come back when you have enough.",
    isForever = false,
  },
  [5902] = {
    id = 5902,
    title = "A Plague Upon Thee",
    reqLevel = 48,
    questLevel = 55,
    faction = "Horde",
    zone = "Tirisfal Glades",
    npc = "Mickey Levine",
    objectives = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.",
    rewards = "2,800 XP",
    tip = "Now that we have plenty of termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; someplace high, like on a crate or something.\n\nAfter you open it, the rest should take care of itself. Just come back here and I'll reward you for helping me.",
    isForever = false,
  },
  [5903] = {
    id = 5903,
    title = "A Plague Upon Thee",
    reqLevel = 48,
    questLevel = 55,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Nathaniel Dumah",
    objectives = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.",
    rewards = "5,650 XP • 85s",
    tip = "I've tried many times to rout out the Scarlet Crusade through force alone, but to no avail. So, as an alternative, I've decided to make their lives more difficult.\n\nIf you are willing to help, I want to infest that lumber mill with the most terrible species of termites ever found.\n\nIn Plaguewood, near the once-great Stratholme, there is a breed that survived the plague and the Scourge combined. Find their mounds and fill this jar with them, so we can prepare them to be unleashed on the Crusade.",
    isForever = false,
  },
  [5904] = {
    id = 5904,
    title = "A Plague Upon Thee",
    reqLevel = 48,
    questLevel = 55,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Nathaniel Dumah",
    objectives = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.",
    rewards = "2,800 XP",
    tip = "Now that we have the termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; find someplace suitable, like on a crate and then open it. The termites should do their work from there and make the mill useless to the Crusade.",
    isForever = false,
  },
  [6389] = {
    id = 6389,
    title = "A Plague Upon Thee",
    reqLevel = 48,
    questLevel = 55,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Object: Termite Barrel",
    objectives = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.",
    rewards = "5,650 XP • 85s",
    tip = "You look around the lumber mill for something suitable to open the barrel with. You find a crowbar that looks like it will do the trick.\n\nYou set your feet and pray that you'll be able to get out of the mill before the termites get to you.",
    isForever = false,
  },
