  [5202] = {
    id = 5202,
    title = "A Strange Red Key",
    reqLevel = 49,
    questLevel = 55,
    faction = "Both",
    zone = "Felwood",
    npc = "Item: Blood Red Key",
    objectives = "Search through Jaedenar to discover what the Blood Red Key is used for.",
    rewards = "5,650 XP",
    tip = "The small red key seems to be made of some kind of bone material. It is heavy in your hand, but appears very fragile. Why would a member of the Shadow Council have such a thing? Perhaps there is something within Jaedenar that this strange key unlocks.",
    isForever = false,
  },
  [7725] = {
    id = 7725,
    title = "Again With the Zapped Giants",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Feralas",
    npc = "Zorbin Fandazzle",
    objectives = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.",
    rewards = "560 XP • 21s",
    tip = "I know you've gathered residue for me already... but should you find yourself for want of an encore performance to a fun-time activity, I can always use more residue.\n\nWhile I can't offer nearly as much in the way of compensation again, I'll be more than happy to spread the good word of your service to all my goblin friends with ears.\n\nBelieve me $g sir : madam; when I say that these goblins have quite large ears.",
    isForever = false,
  },
  [8080] = {
    id = 8080,
    title = "Arathi Basin Resources!",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Sergeant Maclear",
    objectives = "Win the battle for Arathi Basin, get an Arathi Basin Mark of Honor, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "5,650 XP • 2g 50s",
    tip = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [7838] = {
