  [6164] = {
    id = 6164,
    title = "Augustus' Receipt Book",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Augustus the Touched",
    objectives = "Bring Augustus' Receipt Book to Augustus the Touched in Terrordale.",
    rewards = "1,400 XP",
    tip = "I'm ready for business!  What you do want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!",
    isForever = false,
  },
  [4501] = {
    id = 4501,
    title = "Beware of Pterrordax",
    reqLevel = 49,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Object: Beware of Pterrordax",
    objectives = "Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge.",
    rewards = "5,650 XP",
    tip = "Wanted: A skilled fighter to deal with the threat of the Pterrordax that inhabit the Un'Goro Crater. Their numbers are growing, and they are becoming a menace to travelers in the area.\n\nDecrease the population by slaying 10 pterrordax and 15 frenzied pterrordax.\n\nSpeak with Spraggle Frock after completing the task for a reward.",
    isForever = false,
  },
  [4101] = {
    id = 4101,
    title = "Cleansing Felwood",
    reqLevel = 48,
    questLevel = 55,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Arathandris Silversky",
    objectives = "Bring 15 Blood Amber to Arathandris Silversky in Felwood.",
    rewards = "5,650 XP",
    tip = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.",
    isForever = false,
  },
  [4102] = {
    id = 4102,
    title = "Cleansing Felwood",
    reqLevel = 48,
    questLevel = 55,
    faction = "Horde",
    zone = "Felwood",
    npc = "Maybess Riverbreeze",
    objectives = "Bring 15 Blood Amber to Maybess Riverbreeze in Felwood.",
    rewards = "5,650 XP",
    tip = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.",
    isForever = false,
  },
