  [8277] = {
    id = 8277,
    title = "Deadly Desert Venom",
    reqLevel = 54,
    questLevel = 55,
    faction = "Both",
    zone = "Silithus",
    npc = "Beetix Ficklespragg",
    objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task.",
    rewards = "5,650 XP • 85s",
    tip = "Beetix Ficklespragg at your service!  My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists.  Or used to, anyway.  He came back from his last trip with a strong poison running though his veins.\n\nI've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him.\n\nNoggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it.  Bring me some stingers and fangs and I'll try to make an antidote f",
    isForever = false,
  },
  [8470] = {
    id = 8470,
    title = "Deadwood Ritual Totem",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Felwood",
    npc = "Item: Deadwood Ritual Totem",
    objectives = "- Timbermaw Hold:",
    rewards = "5,650 XP, 85s",
    tip = "You have found one of the Deadwood furbolg's ritual totems.  The totem itself is of non-descript construction, but a palpable sense of despair emanates from it.  If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.",
    isForever = false,
  },
  [8461] = {
    id = 8461,
    title = "Deadwood of the North",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Azeroth",
    npc = "Nafien",
    objectives = "Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans.  Return to him in northern Felwood near the entrance to Timbermaw Hold.",
    rewards = "5,650 XP",
    tip = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.\n\nPlease, $N - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.",
    isForever = false,
  },
  [5211] = {
    id = 5211,
    title = "Defenders of Darrowshire",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Carlin Redpath",
    objectives = "Free 15 Darrowshire Spirits and return to Carlin Redpath.",
    rewards = "5,650 XP",
    tip = "Many of the defenders fell at the battle of Darrowshire.  And many roam again as the ghastly servants of the Scourge!  Find these poor souls and end their misery!\n\nHunt cannibal ghouls, gibbering ghouls and diseased flayers.  Many of these fiends were once the good folk of Darrowshire and destroying their forms now will set their souls free.\n\nYou will find them in Plaguewood and Corin's Crossing, and in other Scourge strongholds of Eastern Plaguelands.",
    isForever = false,
  },
  [5165] = {
    id = 5165,
    title = "Dousing the Flames of Protection",
    reqLevel = 48,
    questLevel = 55,
    faction = "Both",
    zone = "Felwood",
    npc = "Greta Mosshoof",
    objectives = "Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.",
    rewards = "5,650 XP",
    tip = "Now, you must return to Jaedenar. The braziers are more than likely spread throughout Shadow Hold. Douse each of their flames and the protections the Council has set up will fall for at least a short period of time. I will be waiting for that to happen. When it does, I will look deep within the Hold and try to find out who the head of this beast is. Then, and only then, will we see about attacking them directly.",
    isForever = false,
  },
  [5141] = {
    id = 5141,
    title = "Dragonscale Leatherworking",
    reqLevel = 40,
    questLevel = 55,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Peter Galen",
    objectives = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Peter Galen in Azshara.\n\nCompleting this quest will give you access to the Dragonscale Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
    rewards = "4,200 XP",
    tip = "Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.\n\nBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.",
    isForever = false,
  },
  [5145] = {
    id = 5145,
    title = "Dragonscale Leatherworking",
    reqLevel = 40,
    questLevel = 55,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Thorkaf Dragoneye",
    objectives = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands.\n\nCompleting this quest will give you access to the Dragonscale Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
    rewards = "4,200 XP",
    tip = "Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.\n\nBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.",
    isForever = false,
  },
