  [3371] = {
    id = 3371,
    title = "Dwarven Justice",
    reqLevel = 40,
    questLevel = 55,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Curator Thorius",
    objectives = "Return to the Searing Gorge and find Dorius's archaeology unit.",
    rewards = "5,650 XP",
    tip = "There is an empty, vacuous hole, where my heart used to be, $N. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.\n\nReturn to the Searing Gorge and fulfill his last request: Free his men. The Dark Iron dwarves force their slaves to work in a sweltering mine called the Slag Pits. Search there for Dorius' men.",
    isForever = false,
  },
  [5144] = {
    id = 5144,
    title = "Elemental Leatherworking",
    reqLevel = 40,
    questLevel = 55,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Sarah Tanner",
    objectives = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge.\n\nCompleting this quest will give you access to the Elemental Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
    rewards = "4,200 XP",
    tip = "Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.\n\nKnow this, $c: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.",
    isForever = false,
  },
  [5146] = {
    id = 5146,
    title = "Elemental Leatherworking",
    reqLevel = 40,
    questLevel = 55,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Brumn Winterhoof",
    objectives = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains.\n\nCompleting this quest will give you access to the Elemental Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
    rewards = "4,200 XP",
    tip = "Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.\n\nKnow this, $c: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.",
    isForever = false,
  },
  [3501] = {
    id = 3501,
    title = "Everything Counts In Large Amounts",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Kum'isha the Collector",
    objectives = "- Imperfect Draenethyst Fragment",
    rewards = "5,650 XP",
    tip = "Although you may never find a flawless sphere of draenethyst, you will undoubtedly uncover various imperfect fragments of the draenethyst in your exploration of these lands.\n\nWhile it is doubtful that Kum'isha will be able to use the flawed fragments to return home, the pieces may serve other, useful purposes for the draenei.\n\nReturn any piece of flawed draenethyst fragments that you may find and I shall reward you.",
    isForever = false,
  },
