  [974] = {
    id = 974,
    title = "Finding the Source",
    reqLevel = 51,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Krakle",
    objectives = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, right click the thermometer to check the temperature. Keep looking until you find the hottest one.",
    rewards = "5,650 XP",
    tip = "The hot springs here are a source of mystery to me. Where does the heat come from?\n\nLooking at how close the pools are to Fire Plume Ridge, I really wonder if the volcano might have something to do with it. I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest part. It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!",
    isForever = false,
  },
  [7602] = {
    id = 7602,
    title = "Flawless Fel Essence",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Impsy",
    objectives = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\n\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\n\nRecover the Flawless Fel Essences and return  to Impsy in Felwood.",
    rewards = "5,650 XP",
    tip = "If you're going to reanimate Kroshius, you're going to need Fel fire. I can make Fel fire but it's going to require some components.\n\nYou need to bring me flawless Fel essences from three distinct regions of the world.\n\nThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.\n\nBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshi",
    isForever = false,
  },
  [4126] = {
    id = 4126,
    title = "Hurley Blackbreath",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Ragnar Thunderbrew",
    objectives = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",
    rewards = "7,050 XP • 1g 65s",
    tip = "The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager.  The villains!  They don't deserve such a fine brew!\n\n$N, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!\n\nPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!",
    isForever = false,
  },
  [3512] = {
    id = 3512,
    title = "In Eranikus' Own Words",
    reqLevel = 48,
    questLevel = 55,
    faction = "Both",
    zone = "Swamp of Sorrows",
    npc = "Itharius",
    objectives = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.",
    rewards = "4,200 XP",
    tip = "$N, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us st",
    isForever = false,
  },
