  [7603] = {
    id = 7603,
    title = "Kroshius' Infernal Core",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Impsy",
    objectives = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\n\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.",
    rewards = "7,050 XP",
    tip = "Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal.\n\nAt this point, I fully expect him to kill you and your minion.\n\nIf by some miracle you happen to kill Kroshius, take his infernal core and return it to Niby.",
    isForever = false,
  },
  [2522] = {
    id = 2522,
    title = "Kum'isha's Endeavors",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Kum'isha the Collector",
    objectives = "Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.",
    rewards = "5,650 XP",
    tip = "Even though the portal conjuration was a failure, I remain hopeful that my next attempt will be successful.\n\nThe hope of the Draenei is as fervent as your greed for trinkets, $r. Go back out into these cursed lands and recover another flawless draenethyst sphere.\n\nOf course, the choice to take on this task is completely left to you *grin*.",
    isForever = false,
  },
  [4481] = {
    id = 4481,
    title = "Libram of Constitution",
