  [5142] = {
    id = 5142,
    title = "Little Pamela",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Marlene Redpath",
    objectives = "Find Pamela Redpath.",
    rewards = "2,800 XP",
    tip = "So many of us died at the battle of Darrowshire.  So many died... and worse.\n\nWhen the battle began I hid my niece Pamela, and I do not know what happened to her.  I am but a wandering spirit, but my heart still longs to know Pamela's fate.\n\nPlease, good $c.  Will you go to Darrowshire and search for her?  It is to the east, beyond Gahrron's Withering.",
    isForever = false,
  },
