  [4134] = {
    id = 4134,
    title = "Lost Thunderbrew Recipe",
    reqLevel = 50,
    questLevel = 55,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Shadowmage Vivian Lagrave",
    objectives = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.",
    rewards = "5,650 XP • 85s",
    tip = "It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.\n\nDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.\n\nAnd to find him, you may have to entice him by threatening his precious a",
    isForever = false,
  },
  [4492] = {
    id = 4492,
    title = "Lost!",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Spraggle Frock",
    objectives = "Find Ringo at Fire Plume Ridge.",
    rewards = "2,800 XP",
    tip = "You've got to help me, $N! My friend, Ringo left earlier to explore the volcano to the south of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!",
    isForever = false,
  },
  [7922] = {
    id = 7922,
    title = "Mark of Honor",
