  [4642] = {
    id = 4642,
    title = "Melding of Influences",
    reqLevel = 48,
    questLevel = 55,
    faction = "Horde",
    zone = "Undercity",
    npc = "Chemist Fuely",
    objectives = "Bring a Merged Ooze Sample to Chemist Fuely in Undercity.",
    rewards = "7,050 XP",
    tip = "Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely. When you get close enough, release the ooze in the case, and let us see what the two think of one another.\n\nAfter the experiment concludes, bring me a sample of whatever is left over. I will await you here in the Apothecarium.",
    isForever = false,
  },
