  [978] = {
    id = 978,
    title = "Moontouched Wildkin",
    reqLevel = 52,
    questLevel = 55,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Erelas Ambersky",
    objectives = "Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village.",
    rewards = "5,650 XP • 85s",
    tip = "Wildkin feathers from the Hinterlands appear to contain traces of magical qualities. These powers... they don't seem to be wielded by the creatures, it's more like they are simply inherent to the species -- part of their very essence.\n\nDuring my studies, I heard that a large population of wildkin inhabit the snowy lands of Winterspring. Could these creatures have the same powers? Please help me find an answer, $N. Go to Winterspring and gather feathers that have dropped to the ground, then retur",
    isForever = false,
  },
  [8081] = {
    id = 8081,
    title = "More Resource Crates",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
    rewards = "",
    tip = "War must be fought with soldiers, any soldier will tell you. They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important. There are key areas in the basin that hold essential resources. Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N. Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",
    isForever = false,
  },
  [8124] = {
    id = 8124,
    title = "More Resource Crates",
    reqLevel = 50,
    questLevel = 55,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Battleground Officer",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi. They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe. We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N. Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman. Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
