  [3502] = {
    id = 3502,
    title = "One Draenei's Junk...",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Kum'isha the Collector",
    objectives = "- Imperfect Draenethyst Fragment",
    rewards = "Experience & Faction Reputation",
    tip = "Well, after that display of voracious greed, I feel nauseous.\n\nRegardless, I shall not dwell too long on your material addiction.\n\nFor each imperfect draenethyst fragment you turn in, I shall reward you with more junk. My junk heap gets smaller while your junk heap gets larger. On Draenor we call this a 'win-win' situation.",
    isForever = false,
  },
  [5149] = {
    id = 5149,
    title = "Pamela's Doll",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Pamela Redpath",
    objectives = "Find Pamela's doll.",
    rewards = "2,800 XP",
    tip = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!\n\nBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!\n\nAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.\n\nWill you find my doll for me?",
    isForever = false,
  },
  [7876] = {
    id = 7876,
    title = "Quell the Silverwing Usurpers",
    reqLevel = 50,
    questLevel = 55,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Captain Shatterskull",
    objectives = "- Warsong Gulch Mark of Honor",
    rewards = "5,650 XP, 2g 50s",
    tip = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.",
    isForever = false,
  },
  [1123] = {
    id = 1123,
    title = "Rabine Saturna",
    reqLevel = 54,
    questLevel = 55,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Arch Druid Hamuul Runetotem",
    objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.",
    rewards = "1,400 XP",
    tip = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.\n\nI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, $N.  Good luck",
    isForever = false,
  },
  [6762] = {
    id = 6762,
    title = "Rabine Saturna",
    reqLevel = 54,
    questLevel = 55,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Mathrengyl Bearwalker",
    objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.",
    rewards = "1,400 XP",
    tip = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade.\n\nWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.",
    isForever = false,
  },
  [4128] = {
    id = 4128,
    title = "Ragnar Thunderbrew",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Enohar Thunderbrew",
    objectives = "Speak with Ragnar Thunderbrew.",
    rewards = "560 XP",
    tip = "Ho, $n.  I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale.  He's looking for stalwart adventurers, and willing to pay plenty.\n\nTalk to Ragnar if you're interested.  He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.",
    isForever = false,
  },
  [7726] = {
    id = 7726,
    title = "Refuel for the Zapping",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Feralas",
    npc = "Zorbin Fandazzle",
    objectives = "Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.",
    rewards = "560 XP • 21s",
    tip = "More work, you say?  Did my heroic mission of collecting bits of goo found inside elemental beings not slake your thirst for adventure?  Perhaps more of the same will vainly try to fill the bottomless well of questing you possess...\n\nOK, melodrama aside, I do need more water elemental cores.  I'm trying desperately to set up shop here, so the rewards won't be as great... but I promise you I'll tell everyone in earshot how you've helped me.  Trust me on this - I know people in the Cartel!",
    isForever = false,
  },
  [5203] = {
    id = 5203,
    title = "Rescue From Jaedenar",
    reqLevel = 49,
    questLevel = 55,
    faction = "Both",
    zone = "Felwood",
    npc = "Captured Arko'narin",
    objectives = "Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends.",
    rewards = "5,650 XP",
    tip = "But, as much as it pains me, there is one thing that must be done first: I have to find Trey's sword Lightforge and escape Shadow Hold to tell my superiors what's happening here. Can you help me, $N?\n\nOur equipment isn't far from here, and you've already proven you can survive the path to the top.\n\nAfter we escape, I'll head to Darnassus if you can find my friend Jessir near the Ashenvale border. She was to meet us at the Emerald Circle's camp near there.\n\nWhat do you say, $N? Can you help me ag",
    isForever = false,
  },
