  [6031] = {
    id = 6031,
    title = "Runecloth",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Azeroth",
    npc = "Meilosh",
    objectives = "Bring 30 Runecloth to Meilosh in Timbermaw Hold.",
    rewards = "5,650 XP",
    tip = "In Timbermaw, we are content.  We do not like strangers.  This is good for us, but it is bad for trade.\n\nNot long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak.  Runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing.\n\nWill you bring me runecloth?  If you bring me enough, then I will give you something in trade.",
    isForever = false,
  },
  [6032] = {
    id = 6032,
    title = "Sacred Cloth",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Azeroth",
    npc = "Meilosh",
    objectives = "Bring 2 Mooncloth to Meilosh in Timbermaw Hold.",
    rewards = "5,650 XP",
    tip = "Although the people of Timbermaw delight in the feel of runecloth, it is not sacred to us.  But mooncloth is sacred.\n\nBring me a small supply of this holy cloth, and I will teach you a secret fashioning technique.",
    isForever = false,
  },
