  [838] = {
    id = 838,
    title = "Scholomance",
    reqLevel = 55,
    questLevel = 55,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "High Executor Derrington",
    objectives = "Speak with Apothecary Dithers at the Bulwark, Western Plaguelands.",
    rewards = "560 XP",
    tip = "On the island of Caer Darrow lies Scholomance - a school that serves as a stronghold for the Scourge.  Our enemy dwells within, safely allowed to pursue research that strengthens their power.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nApothecary Dithers is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your value to me as someone who can get things done; I now entrust this task to you.  Speak with him on this matter.",
    isForever = false,
  },
  [5533] = {
    id = 5533,
    title = "Scholomance",
    reqLevel = 55,
    questLevel = 55,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Commander Ashlam Valorfist",
    objectives = "Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands.",
    rewards = "560 XP",
    tip = "On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil.  Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nAlchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your worth to me, and now I entrust this task to you.  Speak with him on this matter.",
    isForever = false,
  },
  [795] = {
    id = 795,
    title = "Seal of the Earth",
    reqLevel = 40,
    questLevel = 55,
    faction = "Horde",
