    isForever = false,
  },
  [8280] = {
    id = 8280,
    title = "Securing the Supply Lines",
    reqLevel = 54,
    questLevel = 55,
    faction = "Both",
    zone = "Silithus",
    npc = "Windcaller Proudhorn",
    objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers.",
    rewards = "5,650 XP • 85s",
    tip = "Cenarion Hold is a location of utmost strategic importance.  I'm convinced that while we hold it our victory over the silithid is guaranteed.  Provided our influx supplies can be maintained, that is.\n\nDesert worms have proven to be more of a threat to our supply caravans than even the silithid themselves.  Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers.  I need you to thin their numbers to ensure our supplies aren't jeopardized.",
    isForever = false,
  },
  [4084] = {
    id = 4084,
    title = "Silver Heart",
    reqLevel = 47,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Eridan Bluewind",
    objectives = "Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.",
    rewards = "5,450 XP",
    tip = "I do not know the one you speak of, $N.\n\nBut worry not; if your friend was on a journey to find me, I do know what it was he desired.\n\nIn the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...\n\nNone... except those with enough power to do so. I can teach you of this power, $N.\n\nFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then retur",
    isForever = false,
  },
  [5601] = {
    id = 5601,
    title = "Sister Pamela",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Jessica Redpath",
    objectives = "Find Pamela Redpath in Darrowshire.",
    rewards = "560 XP",
    tip = "I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire.\n\nDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.\n\nPlease, find her for me!",
    isForever = false,
  },
  [8462] = {
    id = 8462,
    title = "Speak to Nafien",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Felwood",
    npc = "Grazle",
    objectives = "Travel north along the main road in Felwood and speak with the furbolg named Nafien.  He stands guard outside the entrance to Timbermaw Hold.",
    rewards = "560 XP",
    tip = "Perhaps you are capable of handling a larger threat that we Timbermaw face.  You certainly have shown yourself capable here...\n\nAnother of my kind stands guard outside the entrance to Timbermaw Hold, along this road far to the north.  His name is Nafien; while he may appear to be a feral and unsavory beast, fear him not.  He only seeks aid against the malign forces that threaten our home.",
    isForever = false,
  },
  [8465] = {
    id = 8465,
    title = "Speak to Salfa",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Felwood",
    npc = "Nafien",
    objectives = "Travel through Timbermaw Hold and exit into Winterspring.  Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold.",
    rewards = "560 XP",
    tip = "The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.\n\nBe warned - if my kind inside considers you hostile or hated, they will attack.  Travel as quick as you can, avoiding conflict.  To kill a Timbermaw - even in self defense - will only alienate you f",
    isForever = false,
  },
  [2937] = {
    id = 2937,
    title = "Summoning Shadra",
    reqLevel = 40,
    questLevel = 55,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Master Gadrin",
    objectives = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill.",
    rewards = "8,450 XP",
    tip = "Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god.",
    isForever = false,
  },
  [8275] = {
    id = 8275,
    title = "Taking Back Silithus",
    reqLevel = 54,
    questLevel = 55,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Cenarion Emissary Jademoon",
    objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.",
    rewards = "2,800 XP",
    tip = "Attention, heroes of the Alliance!  The silithid menace has been left unchecked for too long.  Unfettered by any real opposition, they've been preparing all this time for a large-scale expansion.  \n\nCenarion Circle forces are gathering in Silithus to take the fight to these wretched creatures and all able-bodied adventurers are hereby called to join us!\n\nDon't wait until it's too late!  Aid us in the defense of Azeroth! Report to Windcaller Proudhorn at Cenarion Hold for specific instructions!",
    isForever = false,
  },
  [8276] = {
    id = 8276,
    title = "Taking Back Silithus",
    reqLevel = 54,
    questLevel = 55,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Cenarion Emissary Blackhoof",
    objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.",
    rewards = "2,800 XP",
    tip = "Attention, champions of the Horde!  There's a threat we've left unchallenged for too long.  Tremors in the earth near silithid hives all around Azeroth have alerted us to large movements in their numbers as they prepare for expansion.\n\nCenarion Circle forces are gathering in Silithus to take the fight to the silithid before it's too late!  No more shall they defile our lands!\n\nAll able-bodied combatants are to report to Windcaller Proudhorn at Cenarion Hold!  The silithid shall be vanquished!",
    isForever = false,
  },
  [7886] = {
    id = 7886,
    title = "Talismans of Merit",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to aid the cause and bring me more talismans of merit. Do this, and you will earn even more of our trust.",
    isForever = false,
  },
  [5219] = {
    id = 5219,
    title = "Target: Dalson's Tears",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "High Priestess MacDonnell",
    objectives = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.",
    rewards = "5,650 XP",
    tip = "One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  Well, we shall shed no tears this day as we thwart the Scourge and have them choke on their own fumes!\n\nGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you into the cauldron.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it use",
    isForever = false,
  },
  [5231] = {
    id = 5231,
    title = "Target: Dalson's Tears",
    reqLevel = 50,
    questLevel = 55,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Shadow Priestess Vandis",
    objectives = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.",
    rewards = "5,650 XP",
    tip = "One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  No tears will be shed this day, $c; we must strike at this cauldron and gain access to it!\n\nGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you inside the cauldron's innards.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it use",
    isForever = false,
  },
  [5222] = {
    id = 5222,
    title = "Target: Writhing Haunt",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "High Priestess MacDonnell",
    objectives = "Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.",
    rewards = "5,650 XP",
    tip = "Two cauldrons have been successfully opened; while you will be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!\n\nThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.\n\nGood hunting",
    isForever = false,
  },
  [5233] = {
    id = 5233,
    title = "Target: Writhing Haunt",
    reqLevel = 50,
    questLevel = 55,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Shadow Priestess Vandis",
    objectives = "- Writhing Haunt Cauldron Key",
    rewards = "5,650 XP",
    tip = "Two cauldrons have been successfully opened; while you'll be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!\n\nThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.\n\nGood hunting, ",
    isForever = false,
  },
  [4289] = {
    id = 4289,
    title = "The Apes of Un'Goro",
    reqLevel = 47,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Torwa Pathfinder",
    objectives = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.",
    rewards = "5,650 XP • 85s",
    tip = "This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin.\n\nIf you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength.",
    isForever = false,
  },
  [8105] = {
    id = 8105,
    title = "The Battle for Arathi Basin!",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Field Marshal Oslight",
    objectives = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.",
    rewards = "5,650 XP • 1g 65s",
    tip = "$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.",
    isForever = false,
  },
  [8120] = {
    id = 8120,
    title = "The Battle for Arathi Basin!",
    reqLevel = 50,
    questLevel = 55,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathmaster Dwire",
    objectives = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
    rewards = "5,650 XP • 1g 65s",
    tip = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, $N.  Report back to me when this task is compl",
    isForever = false,
  },
  [3373] = {
    id = 3373,
    title = "The Essence of Eranikus",
    reqLevel = 48,
    questLevel = 55,
    faction = "Both",
    zone = "Sunken Temple",
    npc = "Item: Essence of Eranikus",
    objectives = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.",
    rewards = "2,800 XP",
    tip = "As you touch the gem, a deep voice resonates in your mind.\n\n\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may",
    isForever = false,
  },
  [3374] = {
    id = 3374,
    title = "The Essence of Eranikus",
    reqLevel = 48,
    questLevel = 55,
    faction = "Both",
    zone = "Swamp of Sorrows",
    npc = "Item: Oathstone of Ysera's Dragonflight",
    objectives = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not.",
    rewards = "560 XP",
    tip = "You engage the Oathstone, and Itharius speaks directly to your mind through the stone.\n\n\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"\n\n\"Do this $N, and we will work together to redeem a soul worthy of redemption.\"",
    isForever = false,
  },
  [4123] = {
    id = 4123,
    title = "The Heart of the Mountain",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Maxwort Uberglint",
    objectives = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.",
    rewards = "5,650 XP • 85s",
    tip = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.",
    isForever = false,
  },
  [4301] = {
    id = 4301,
    title = "The Mighty U'cha",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Torwa Pathfinder",
    objectives = "Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.",
    rewards = "5,650 XP",
    tip = "While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.\n\nI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunt",
    isForever = false,
  },
  [1000] = {
    id = 1000,
    title = "The New Frontier",
    reqLevel = 54,
    questLevel = 55,
    faction = "Horde",
    zone = "Thunder Bluff",
    npc = "Bluff Runner Windstrider",
    objectives = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
    rewards = "560 XP",
    tip = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",
    isForever = false,
  },
  [1004] = {
    id = 1004,
    title = "The New Frontier",
    reqLevel = 54,
    questLevel = 55,
    faction = "Horde",
    zone = "Undercity",
    npc = "Harbinger Balthazad",
    objectives = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
    rewards = "560 XP",
    tip = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",
    isForever = false,
  },
