  [6761] = {
    id = 6761,
    title = "The New Frontier",
    reqLevel = 54,
    questLevel = 55,
    faction = "Alliance",
    zone = "Darnassus",
    npc = "Arch Druid Fandral Staghelm",
    objectives = "Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.",
    rewards = "560 XP",
    tip = "I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me.\n\nLet me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.\n\nI'll leave it to you to decide whether or not you're a fool.",
    isForever = false,
  },
  [980] = {
    id = 980,
    title = "The New Springs",
    reqLevel = 51,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Krakle",
    objectives = "Travel to Winterspring and speak with Donova Snowden.",
    rewards = "2,800 XP",
    tip = "Now, I've heard about other hot springs in a place called Winterspring, far to the north of here. The strange thing is, there are no volcanoes anywhere near them. Interesting, I know.\n\nWell, if you want to find out more, you should head to Winterspring and speak to a friend of mine. Her name is Donova Snowden, and she is currently staying by the hot springs there.\n\nThanks again for helping me with my thermometer! See you later!",
    isForever = false,
  },
  [4083] = {
    id = 4083,
    title = "The Spectral Chalice",
    reqLevel = 40,
    questLevel = 55,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Object: Spectral Chalice",
    objectives = "- Star Ruby x 2 - Gold Bar x 20 - Truesilver Bar x 10",
    rewards = "5,650 XP",
    tip = "",
    isForever = false,
  },
  [1125] = {
    id = 1125,
    title = "The Spirits of Southwind",
    reqLevel = 54,
    questLevel = 55,
    faction = "Both",
    zone = "Silithus",
    npc = "Layo Starstrike",
    objectives = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.",
    rewards = "5,650 XP",
    tip = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, $N.\n\nFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...\n\nThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed",
    isForever = false,
  },
  [2623] = {
    id = 2623,
    title = "The Swamp Talker",
    reqLevel = 45,
    questLevel = 55,
    faction = "Horde",
    zone = "Swamp of Sorrows",
    npc = "Bengor",
    objectives = "- Warchief's Orders",
    rewards = "5,650 XP",
    tip = "Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.\n\nMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....\n\n<Bengor passes out.>",
    isForever = false,
  },
  [2521] = {
    id = 2521,
    title = "To Serve Kum'isha",
    reqLevel = 45,
    questLevel = 55,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Kum'isha the Collector",
    objectives = "In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\n\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\n\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.",
    rewards = "8,450 XP",
    tip = "$R, can your miniscule brain comprehend the rarity of a flawless sphere of draenethyst? Draenei have spent lifetimes in search of just one of these crystals, only to meet horrible fates, their purpose unfulfilled.\n\nSo you stand before Kum'isha, knowing what Kum'isha has requested and still wish to assist? Very well, $r... At any time during your travels across these lands, should you find a flawless sphere of draenethyst, return it to me and I shall reward you with riches beyond your wildest dre",
    isForever = false,
  },
  [5143] = {
    id = 5143,
    title = "Tribal Leatherworking",
    reqLevel = 40,
    questLevel = 55,
    faction = "Alliance",
    zone = "Leatherworking",
    npc = "Caryssia Moonhunter",
    objectives = "Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.\n\nCompleting this quest will give you access to the Tribal Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.",
    rewards = "4,200 XP",
    tip = "To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.\n\nKnow this, $c: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.",
    isForever = false,
  },
  [5148] = {
    id = 5148,
    title = "Tribal Leatherworking",
    reqLevel = 40,
    questLevel = 55,
    faction = "Horde",
    zone = "Leatherworking",
    npc = "Se'Jib",
    objectives = "Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale.\n\nCompleting this quest will give you access to the Tribal Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.",
    rewards = "4,200 XP",
    tip = "To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.\n\nKnow this, $c: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.",
    isForever = false,
  },
  [7873] = {
    id = 7873,
    title = "Vanquish the Invaders!",
    reqLevel = 50,
    questLevel = 55,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Sentinel Farsong",
    objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
    rewards = "5,650 XP • 2g 50s",
    tip = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.",
    isForever = false,
  },
  [2938] = {
    id = 2938,
    title = "Venom to the Undercity",
    reqLevel = 40,
    questLevel = 55,
    faction = "Horde",
    zone = "The Hinterlands",
    npc = "Apothecary Lydon",
    objectives = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.",
    rewards = "8,450 XP • 2g 50s",
    tip = "The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!\n\nI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himse",
    isForever = false,
  },
  [4133] = {
    id = 4133,
    title = "Vivian Lagrave",
    reqLevel = 50,
    questLevel = 55,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Apothecary Zinge",
    objectives = "Speak with Shadowmaster Vivian Lagrave in Kargath.",
    rewards = "560 XP",
    tip = "Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.\n\nSpeak with Vivian.  She awaits you.",
    isForever = false,
  },
  [4502] = {
    id = 4502,
    title = "Volcanic Activity",
    reqLevel = 49,
    questLevel = 55,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Liv Rizzlefix",
    objectives = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet.",
    rewards = "5,650 XP • 85s",
    tip = "Being an apprentice to Marvon Rivetseeker, I've learned so much. But he's been gone for such a long time now, so I think I'm going to work on some experiments of my own.\n\nI've been reading about Un'Goro Crater most recently, and about the strange volcanic activity going on in the middle of the crater. I think a lot could be learned if I could just get some of the ash from the elementals there.\n\nDo you think you'd mind collecting some for me, if you are going that way?",
    isForever = false,
  },
  [1124] = {
    id = 1124,
    title = "Wasteland",
    reqLevel = 54,
    questLevel = 55,
    faction = "Both",
    zone = "Moonglade",
    npc = "Rabine Saturna",
    objectives = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.",
    rewards = "2,800 XP",
    tip = "West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.\n\nSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly.",
    isForever = false,
  },
  [5224] = {
    id = 5224,
    title = "Writhing Haunt Cauldron",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Object: Scourge Cauldron",
    objectives = "- Arcane Quickener - Somatic Intensifier x 5 - Runecloth x 4",
    rewards = "560 XP",
    tip = "",
    isForever = false,
  },
  [6021] = {
    id = 6021,
    title = "Zaeldarr the Outcast",
    reqLevel = 50,
    questLevel = 55,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Caretaker Alen",
    objectives = "Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.",
    rewards = "4,200 XP • 85s",
    tip = "Can you believe that, after all the trouble we have in the plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from the pit below, then take them back to their evil, dead troll hideout--the Undercroft to the west.\n\nGo there and take out Zaeldarr, $N.  I'm sick to death of his mischief!",
    isForever = false,
  },
  [4294] = {
    id = 4294,
    title = "... and a Batch of Ooze",
    reqLevel = 48,
    questLevel = 56,
    faction = "Horde",
    zone = "Undercity",
    npc = "Chemist Fuely",
    objectives = "Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely.",
    rewards = "5,800 XP • 65s",
    tip = "Have you heard of the Un'Goro Crater, $N? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.\n\nIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.\n\nI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.",
    isForever = false,
  },
  [4971] = {
    id = 4971,
    title = "A Matter of Time",
    reqLevel = 53,
    questLevel = 56,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Chromie",
    objectives = "Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.\n\nSlay 15 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.",
    rewards = "5,800 XP",
    tip = "Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal!  I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted.\n\nTemporal parasites - carrion that feed on the strands of time's altered flow - now infest the silos of Andorhal.  A blue pulse of distortion is their only visual marker.  They slow my auguries; please $N, help me by using this temporal displacer to root out these para",
    isForever = false,
  },
  [5153] = {
    id = 5153,
    title = "A Strange Historian",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Marlene Redpath",
    objectives = "Bring Joseph's Wedding Ring to Chromie.",
    rewards = "4,350 XP",
    tip = "I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.  Oh, he is doomed!\n\nBut perhaps we can change his fate.\n\nSearch the graves outside for Joseph's monument.  His body's not there, for it was trampled and destroyed years ago, but under the monument is his wedding ring.  Take that ring to Chromie... a strange gnome with very strange powers.\n\nChromie is staying in the ruined inn at the northwest corner of Andorhal.",
    isForever = false,
  },
  [5097] = {
    id = 5097,
    title = "All Along the Watchtowers",
    reqLevel = 50,
    questLevel = 56,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Commander Ashlam Valorfist",
    objectives = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\n\nOnce all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.",
    rewards = "5,800 XP • 85s",
    tip = "Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.\n\nYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them w",
    isForever = false,
  },
  [5098] = {
    id = 5098,
    title = "All Along the Watchtowers",
    reqLevel = 50,
    questLevel = 56,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "High Executor Derrington",
    objectives = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\n\nOnce all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands.",
    rewards = "5,800 XP • 85s",
    tip = "Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.\n\nYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them w",
    isForever = false,
  },
  [4261] = {
    id = 4261,
    title = "Ancient Spirit",
    reqLevel = 49,
    questLevel = 56,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Arei",
    objectives = "Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.",
    rewards = "7,300 XP",
    tip = "Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos...\n\nThe skull of Gul'dan ensured that none were spared here. All fell to the corruption.\n\nEven now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, $N, tell me you will lead an ancient spirit away from here, where I may finally rest.\n\nOnce I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east",
    isForever = false,
  },
  [3783] = {
    id = 3783,
    title = "Are We There, Yeti?",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Umi Rumplesnicker",
    objectives = "Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.",
    rewards = "4,350 XP • 85s",
    tip = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.",
    isForever = false,
  },
  [5152] = {
    id = 5152,
    title = "Auntie Marlene",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Pamela Redpath",
    objectives = "Speak with Marlene, south of the Ruins of Andorhal.",
    rewards = "2,900 XP",
    tip = "Oh, I'm so lonely!  Where is my family?  Auntie Marlene told me to stay here, but then she left and never came back!  And my dad... have you seen him?\n\nMaybe Auntie Marlene knows where he is.  She lives near Andorhal, in a house to the south.  I think it was on a hill... she said it was on a hill.\n\nPlease, $N.  You're my new friend!  Will you talk to my Auntie for me?",
    isForever = false,
  },
  [8469] = {
    id = 8469,
    title = "Beads for Salfa",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Felwood",
    npc = "Salfa",
    objectives = "- Winterfall Spirit Beads x 5",
    rewards = "580 XP",
    tip = "",
    isForever = false,
  },
  [3506] = {
    id = 3506,
    title = "Betrayed",
    reqLevel = 44,
    questLevel = 56,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Object: Kaldorei Tome of Summoning",
    objectives = "Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara.",
    rewards = "4,350 XP",
    tip = "A few more moments of thought brings a few ideas to mind, one of which brings a smile to your face: perhaps destroying the crystals would upset the blood elf responsible for the slaughter of so many orcs and the betrayal of Belgrom?\n\nYou continue to decipher more of the script and pictures and realize that one of the crystals is tied to the creator of the circle--the others are tied to something far more sinister.\n\nYou close the book and begin to decide which crystal to destroy.",
    isForever = false,
  },
  [3507] = {
    id = 3507,
    title = "Betrayed",
    reqLevel = 44,
    questLevel = 56,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Ag'tor Bloodfist",
    objectives = "Speak to Belgrom Rockmaul in Orgrimmar.",
    rewards = "7,300 XP",
    tip = "Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly.\n\nAh, this is indeed a good day. Thank you for your help, $N.",
    isForever = false,
  },
  [5543] = {
    id = 5543,
    title = "Blood Tinged Skies",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Tirion Fordring",
    objectives = "Slay 30 Plaguebats and return to Tirion Fordring.",
    rewards = "5,800 XP",
    tip = "Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.\n\nEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats.",
    isForever = false,
  },
  [5210] = {
    id = 5210,
    title = "Brother Carlin",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Chromie",
    objectives = "Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands.",
    rewards = "2,900 XP",
    tip = "The Annals of Darrowshire, through my magic, has gained pages at its end, and now it extends its history beyond the battle.  One of the extra passages tells of another Redpath, Carlin, who survived Joseph's betrayal.  Carlin's now in the Plaguelands to the east, at the Light's Hope Chapel.\n\nTake the book and speak with him.",
    isForever = false,
  },
  [5544] = {
    id = 5544,
    title = "Carrion Grubbage",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Tirion Fordring",
    objectives = "- Slab of Carrion Worm Meat x 15",
    rewards = "5,800 XP",
    tip = "My food supplies are running low, $r. I am ashamed to admit that I might not have enough food to share with you.\n\nCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!",
    isForever = false,
  },
  [4972] = {
    id = 4972,
    title = "Counting Out Time",
    reqLevel = 53,
    questLevel = 56,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Chromie",
    objectives = "Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city.  Return with them to Chromie in the Andorhal Inn, Western Plaguelands.",
    rewards = "5,800 XP",
    tip = "I need you to reach into the world beyond this room, $N.  Allow me to explain.\n\nYou see the difference in this room compared to the rest of Andorhal.  My dragonflight works in many different ways and in many different timelines.  To mend Andorhal's damage, I now act from a different timeline as not to overly contaminate it.  To continue this though I need time trinkets, ones trapped from when the plague hit.  Find them in lockboxes found in the ruined buildings that make up this once proud city.",
    isForever = false,
  },
  [4973] = {
    id = 4973,
    title = "Counting Out Time",
    reqLevel = 53,
    questLevel = 56,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Chromie",
    objectives = "Locate 5 Andorhal Watches amongst the rubble of the city, and return with them to Chromie in the Andorhal Inn, Western Plaguelands.",
    rewards = "580 XP",
    tip = "If you are willing to help once more, I can certainly use your assistance.  I'll gladly take more watches you might uncover from the ruins of Andorhal.  They certainly help me in maintaining a balance against whatever malign force is meddling with the timeline here.\n\nIn exchange for those watches, I'll give you another item that, in the future, I suspect you'll find quite the use for.",
    isForever = false,
  },
  [5542] = {
    id = 5542,
    title = "Demon Dogs",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Tirion Fordring",
    objectives = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.",
    rewards = "5,800 XP",
    tip = "If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'\n\nYou can start with the Plaguehounds and their runts.\n\nI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed.",
    isForever = false,
  },
  [3907] = {
    id = 3907,
    title = "Disharmony of Fire",
    reqLevel = 48,
    questLevel = 56,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Thunderheart",
    objectives = "- Lord Incendius - Tablet of Kurniya",
    rewards = "7,300 XP, 2g 55s",
    tip = "I can taste the foulness in the air that surrounds you, $N. There is another, hidden in the depths of Blackrock, who does control this foulness.\n\nThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.\n\nFind him and discover where his master hides. Return to me when you have collected this information.",
    isForever = false,
  },
  [4283] = {
    id = 4283,
    title = "FIFTY! YEP!",
    reqLevel = 50,
    questLevel = 56,
    faction = "Alliance",
    zone = "Burning Steppes",
    npc = "Oralius",
    objectives = "Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes.",
    rewards = "5,800 XP • 85s",
    tip = "I'm going to let you in on a little secret, soldier. Come a little closer.\n\nI'M THE ONLY SANE ONE HERE!\n\nLook at these people! Would you believe that they're all insane!? Well they are! NUTS! CRAZY!\n\n<Oralius lowers his voice.>\n\nLet's just keep that between me, you, and my pal Captain Winky.\n\n<Oralius grabs at the air and squeezes.>\n\nAnyhooooo... I'm collecting badges to go along with my ogre ear collection. Orc is the flavor of the day. Fifty. GO!\n\n<Oralius blows into a horn.>\n\nSHIP IT!",
    isForever = false,
  },
  [5084] = {
    id = 5084,
    title = "Falling to Corruption",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Donova Snowden",
    objectives = "Search the Deadwood furbolg camp in northern Felwood for a clue.",
    rewards = "4,350 XP",
    tip = "This greenish liquid... it reminds me a bit of the sludge I saw when traveling through Felwood. And I have seen some Winterfall Runners passing into Timbermaw... Perhaps these things have something to do with the flask you found, $N.\n\nThere is a large group of furbolg just past Timbermaw Hold, in Felwood. Called the Deadwood tribe, they have been corrupted and driven mad by the fel. Why don't you look around there and see if you can find any evidence of dealings between the Winterfall and the De",
    isForever = false,
  },
  [5246] = {
    id = 5246,
    title = "Fragments of the Past",
    reqLevel = 53,
    questLevel = 56,
    faction = "Alliance",
    zone = "Eastern Plaguelands",
    npc = "Aurora Skycaller",
    objectives = "Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.",
    rewards = "5,800 XP",
    tip = "I did not realize... Forgive my callous words, $c.\n\nThe mistakes of my ancestors are not what I wish to dwell on, but if your request is truly genuine, then I will help you.\n\n<Aurora examines the fragments.>\n\nI believe this is the Crystal of Zin-Malor, an artifact that can contain and control strong arcane forces. It could have been used for good, but the evil intentions of those that stole it caused it to shatter.\n\nGo to the Temple of Zin-Malor in Azshara - I can only hope the book is still the",
    isForever = false,
  },
  [4986] = {
    id = 4986,
    title = "Glyphed Oaken Branch",
    reqLevel = 51,
    questLevel = 56,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Mulgris Deepriver",
    objectives = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought.  Seek one of the druids there for assistance.",
    rewards = "5,800 XP",
    tip = "The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark.\n\nAs you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of the Teldrassil tree enters your mind - Darnassus specifically - and the words \"Cenarion Circle\" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.",
    isForever = false,
  },
  [4987] = {
    id = 4987,
    title = "Glyphed Oaken Branch",
    reqLevel = 51,
    questLevel = 56,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Mulgris Deepriver",
    objectives = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Thunder Bluff is the next step the tauren druid sought.  Seek one of the druids there for assistance.",
    rewards = "5,800 XP",
    tip = "The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark.\n\nAs you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of Thunder Bluff in Mulgore enters your mind - Elder Rise specifically - and the words \"Cenarion Circle\" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.",
    isForever = false,
  },
  [5168] = {
    id = 5168,
    title = "Heroes of Darrowshire",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Carlin Redpath",
    objectives = "Bring Davil's Libram and Redpath's Shield to Carlin Redpath.",
    rewards = "5,800 XP",
    tip = "The heroes of Darrowshire hold a place in my heart, and the book you brought me, the Annals of Darrowshire, tells their tales.\n\nIt tells of the paladin Davil Lightfire and how the Crusade took his libram to the town hall of Hearthglen.\n\nIts passages also speak of my brother, Captain Redpath.  After his betrayal, his shield was cracked and discarded and now lies in the most unlikely of places -- near the barn of Gahrron's Withering.\n\nGather these relics, $N.  For fate and tragedy surrounds them.",
    isForever = false,
  },
  [4263] = {
    id = 4263,
    title = "Incendius!",
    reqLevel = 48,
    questLevel = 56,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Jalinda Sprig",
    objectives = "- Lord Incendius",
    rewards = "5,800 XP, 85s",
    tip = "Are you sure Pyron said 'Incendius' when he died?\n\n<Jalinda swallows hard.>\n\nLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?\n\nDo you think you can handle another mission? I don't have anybody else to send, $N!\n\nWe will never get a team in if Incendius continues to raise Pyron from the ashes.\n\nYou'll have to find and destroy Lord Incendius!",
    isForever = false,
  },
  [3962] = {
    id = 3962,
    title = "It's Dangerous to Go Alone",
    reqLevel = 47,
    questLevel = 56,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Linken",
    objectives = "Travel to Fire Plume Ridge, south of Marshal's Refuge.\n\nFind Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.",
    rewards = "7,300 XP",
    tip = "$N, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step.\n\nBut I am no longer the hero... You are. All that you have done -- you must finish this now, not me.\n\nBlazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart.\n\nYou will want to bring others with you -- it's dangerous to go alone. Take this as my advice.",
    isForever = false,
  },
  [5085] = {
    id = 5085,
    title = "Mystery Goo",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Object: Deadwood Cauldron",
    objectives = "Report back to Donova Snowden with your findings.",
    rewards = "4,350 XP",
    tip = "The greenish substance inside the cauldron appears to be similar to what you found in the flask. This strange gooey stuff could be as corrupted as the furbolg that created it...\n\nIf the Winterfall furbolg are using it, does this mean that they will soon be as corrupted as the Deadwood tribe?\n\nIt would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron.",
    isForever = false,
  },
  [6804] = {
    id = 6804,
    title = "Poisoned Water",
    reqLevel = 55,
    questLevel = 56,
    faction = "Both",
    zone = "Azshara",
    npc = "Duke Hydraxis",
    objectives = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands.  Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.",
    rewards = "4,350 XP",
    tip = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!\n\nTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.\n\nDefeat the discordant surges and bring me their bracers of binding.",
    isForever = false,
  },
  [5742] = {
    id = 5742,
    title = "Redemption",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Tirion Fordring",
    objectives = "- Tirion's Tale",
    rewards = "580 XP",
    tip = "You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself.",
    isForever = false,
  },
  [5250] = {
    id = 5250,
    title = "Starfall",
    reqLevel = 53,
    questLevel = 56,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Daryn Lightwind",
    objectives = "Find Starfall in Winterspring and speak with Wynd Nightchaser.",
    rewards = "580 XP",
    tip = "In Winterspring, to the north of Felwood, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore.\n\nMy studies here keep me so busy that I have not had the opportunity to travel to Winterspring for some time. But there's no reason why you shouldn't travel there and study the ruins.\n\nWhile you're there, look for Wynd Nightchaser. He spends most of his time in Starfall and he knows a lot about the area.\n\nTell him that you are a student of mine...",
    isForever = false,
  },
  [4842] = {
    id = 4842,
    title = "Strange Sources",
    reqLevel = 51,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Donova Snowden",
    objectives = "Follow Donova Snowden's instructions, then report back.",
    rewards = "5,800 XP",
    tip = "To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs...\n\nWell, I think you'll want to see it for yourself. You'll need to travel the length of Winterspring, and head to the very south. When the air becomes thick and muggy, and the sky turns dark, you'll have found what I believe to be the source of the hot springs.\n\nHave a look. I'm sure you'll have many questions when you return.",
    isForever = false,
  },
  [5154] = {
    id = 5154,
    title = "The Annals of Darrowshire",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Chromie",
    objectives = "Bring the Annals of Darrowshire to Chromie in Andorhal.",
    rewards = "5,800 XP",
    tip = "To save Joseph Redpath, we must first discover his past.  We can learn this in the Annals of Darrowshire, a book held in the city hall of Andorhal.\n\nBring me that book.  We can then learn Joseph's fate, and with luck... change it!",
    isForever = false,
  },
  [4292] = {
    id = 4292,
    title = "The Bait for Lar'korwi",
    reqLevel = 48,
    questLevel = 56,
    faction = "Both",
    zone = "Un'Goro Crater",
    npc = "Torwa Pathfinder",
    objectives = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.",
    rewards = "7,300 XP",
    tip = "This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.",
    isForever = false,
  },
  [5961] = {
    id = 5961,
    title = "The Champion of the Banshee Queen",
    reqLevel = 54,
    questLevel = 56,
    faction = "Horde",
    zone = "Undercity",
    npc = "Lady Sylvanas Windrunner",
    objectives = "Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead.",
    rewards = "1,450 XP",
    tip = "It pleases me greatly to see the battle hardened join our cause. Our numbers grow in size and strength as each day passes. Perhaps you are prepared to test your mettle, $c?\n\nAmong the first of my champions was Nathanos, now known as the Blightcaller. Few exist with more dedication or vigor amidst our ranks.\n\nSeek him out in the Eastern Plaguelands. He resides at the Marris Stead; occasionally roaming the decimated wastes, slaying all Scourge and Alliance filth that cross his path.",
    isForever = false,
  },
  [4286] = {
    id = 4286,
    title = "The Good Stuff",
    reqLevel = 50,
    questLevel = 56,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Oralius",
    objectives = "- Dark Iron Fanny Pack x 20",
    rewards = "5,800 XP, 85s",
    tip = "Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky?\n\n<Oralius does his best impersonation of a pirate.>\n\nARRR MATEY! IT BE RIGHT!\n\nSee what I'm saying? You need to get in there and bring me back some samples of the good stuff.\n\nGet in there and shake your moneymaker!",
    isForever = false,
  },
  [5244] = {
    id = 5244,
    title = "The Ruins of Kel'Theril",
    reqLevel = 53,
    questLevel = 56,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Wynd Nightchaser",
    objectives = "Speak with Jaron Stoneshaper in Starfall Village.",
    rewards = "580 XP",
    tip = "The story behind Kel'Theril is one of a cursed race, bound to the place where they attempted an unfortunate ritual...\n\nThe highborne that you will find there once stole a sacred artifact, believing that they could siphon its power for themselves, becoming even more powerful. In their efforts, the relic shattered in a huge explosion, driving the pieces below the ice of the lake...\n\nSpeak with Jaron Stoneshaper if you'd like to learn more; he has recently visited the area and can tell you more.",
    isForever = false,
  },
  [4985] = {
    id = 4985,
    title = "The Wildlife Suffers Too",
    reqLevel = 51,
    questLevel = 56,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Mulgris Deepriver",
    objectives = "Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.",
    rewards = "4,350 XP",
    tip = "To the east of where we are, near where the Eastern Plaguelands begin, once proud and majestic grizzlies roamed the countryside.  The plague released by the Scourge has sundered these beasts too.  They wander the countryside, agonized by the stiffening of their muscles and the rotting of their fur and flesh.\n\nI ask of you to end their misery as well.  The only cure for their suffering is a swift death, one that must be ministered by your hand.",
    isForever = false,
  },
  [5082] = {
    id = 5082,
    title = "Threat of the Winterfall",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Donova Snowden",
    objectives = "Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.",
    rewards = "5,800 XP • 85s",
    tip = "I came to Winterspring to investigate the Frostfire Hot Springs. I've noticed that the water seems to have ...strange qualities. I haven't yet been able to discover the source, and to tell you the truth, I've had some difficulty lately, due to the Winterfall furbolg.\n\nThey seem to be drawn to the springs, just as I am. They have become extremely protective of the water, and won't let me come near the two larger springs to the north of here.\n\nI'd like to continue my studies, so won't you help me?",
    isForever = false,
  },
  [5249] = {
    id = 5249,
    title = "To Winterspring!",
    reqLevel = 53,
    questLevel = 56,
    faction = "Alliance",
    zone = "Felwood",
    npc = "Ivy Leafrunner",
    objectives = "Find Starfall Village in Winterspring and speak with Wynd Nightchaser.",
    rewards = "580 XP",
    tip = "In Winterspring, to the north of here, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore.\n\nWith all my work to do here in Felwood, I have not had the opportunity to travel to Winterspring. But there's no reason why you shouldn't!\n\nWhile you're there, look for Wynd Nightchaser. He spends most of his time in Starfall Village and he knows a lot about the area.",
    isForever = false,
  },
  [5086] = {
    id = 5086,
    title = "Toxic Horrors",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Donova Snowden",
    objectives = "Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.",
    rewards = "5,800 XP",
    tip = "I've studied the sample you returned with, and while I can't say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison.\n\nI believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors.\n\nCollect a few samples for me to compare, but be careful -- it's very dangerous there!",
    isForever = false,
  },
  [6603] = {
    id = 6603,
    title = "Trouble in Winterspring!",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Meggi Peppinrocker",
    objectives = "Find Donova Snowden near the hot springs in Winterspring.",
    rewards = "580 XP",
    tip = "There's trouble in Winterspring!\n\nWhy, sure, I spend some time out in the wilds and know about these things... I'm always mighty proud to say it. I consider the hours I spend out there in the hills to be golden. Help you cultivate quick reflexes, a cool head and a keen eye...\n\nIt takes judgement, brains and maturity to appreciate the wilderness in the way that I do.\n\nNow, what was I talking about?\n\nAh yes, trouble. See Donova Snowden at the hot springs and she can tell you more.",
    isForever = false,
  },
  [5245] = {
    id = 5245,
    title = "Troubled Spirits of Kel'Theril",
    reqLevel = 53,
    questLevel = 56,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Jaron Stoneshaper",
    objectives = "Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.",
    rewards = "5,800 XP",
    tip = "The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.\n\nIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.\n\nNow, I can't tell you a thing about what you find, but I do know of someone who might... Aurora Skycaller; she dwells near the Northpass Tower in the northern part of Eastern Plaguelands.",
    isForever = false,
  },
  [5241] = {
    id = 5241,
    title = "Uncle Carlin",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Pamela Redpath",
    objectives = "Find Carlin Redpath.",
    rewards = "2,900 XP",
    tip = "Sometimes, when it's nighttime, I can hear my Uncle Carlin crying.  It sounds like he's far away, to the east.\n\nI hope he's not crying for me!  $N, will you find my uncle and tell him I'm alright?\n\nIf you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!",
    isForever = false,
  },
  [6004] = {
    id = 6004,
    title = "Unfinished Business",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Kirsta Deepshadow",
    objectives = "Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.",
    rewards = "5,800 XP • 65s",
    tip = "I was sent as a scout to do some damage and gauge the strength of Hearthglen's defenses. Some people in the Alliance feel the little town has more than historical importance. It's not my job to question what that importance is, but regardless, I'm in no shape to continue until I rest up.\n\nIf you're willing, I'd pay handsomely for some help. Start south of here at their camp near the small bulwark they've set up. If you prove strong enough, maybe I could get your help with my main goal.",
    isForever = false,
  },
  [5054] = {
    id = 5054,
    title = "Ursius of the Shardtooth",
    reqLevel = 53,
    questLevel = 56,
    faction = "Horde",
    zone = "Winterspring",
    npc = "Storm Shadowhoof",
    objectives = "Storm Shadowhoof at Bloodvenom Post in Felwood wants you to kill Ursius.",
    rewards = "5,800 XP",
    tip = "In the snowy mountains of Winterspring, to the northwest, a skilled hunter stalks his prey... I speak of Ursius of the shardtooth bears, an agile and clever beast.\n\nI send you now against him. He roams the sloping hills to the northwest of Everlook. Find and hunt him, before he discovers your intent.\n\nAll that have gone up against Ursius have quickly found themselves to be the prey, and he, the hunter. Stay on your guard.",
    isForever = false,
  },
  [103] = {
    id = 103,
    title = "Whispers of the Stillglade",
    reqLevel = 54,
    questLevel = 56,
    faction = "Both",
    zone = "The Riverglades",
    npc = "Captain Grayson",
    objectives = "Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse.",
    rewards = "1,150 XP • 6s",
    tip = "Pro-tip: Keep an eye out for enemy faction players—the Riverglades is a contested open-world PvP hotbed in Forever.",
    isForever = true,
  },
  [4521] = {
    id = 4521,
    title = "Wild Guardians",
    reqLevel = 52,
    questLevel = 56,
    faction = "Horde",
    zone = "Felwood",
    npc = "Trull Failbane",
    objectives = "Trull Failbane in Felwood wants you to kill 15 Raging Owlbeasts and 15 Ragged Owlbeasts.",
    rewards = "5,800 XP • 85s",
    tip = "Winterspring lies just beyond Timbermaw, northeast of Felwood. Have you been there?\n\nI have heard that the area is laden with creatures called wildkin. These beasts have been known to guard secrets; secrets of the Night elves.\n\nWe must figure out what may be hidden in Winterspring.\n\nI have heard the ragged owlbeasts can be found just south of the road, and that there are others called raging owlbeasts that may be found in the center of Winterspring. Clear them out, and gain access to the land.",
    isForever = false,
  },
  [5083] = {
    id = 5083,
    title = "Winterfall Firewater",
    reqLevel = 52,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Item: Empty Firewater Flask",
    objectives = "Bring the Empty Firewater Flask to Donova Snowden in Winterspring.",
    rewards = "2,900 XP",
    tip = "This vial that you picked up from the Winterfall furbolg is empty, but you can detect a few drops of a strange green liquid inside; it almost glows.\n\nIs it something important?\n\nDonova Snowden would probably be able to tell you more, since she has been camped by the hot springs in Winterspring for some time now.",
    isForever = false,
  },
  [8471] = {
    id = 8471,
    title = "Winterfall Ritual Totem",
    reqLevel = 50,
    questLevel = 56,
    faction = "Both",
    zone = "Winterspring",
    npc = "Item: Winterfall Ritual Totem",
    objectives = "Take the Winterfall Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item.  The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.",
    rewards = "5,800 XP • 1g 70s",
    tip = "You have found one of the Winterfall furbolg's ritual totems.  The totem itself is of non-descript construction, but it seems to emanate an almost tangible sense of dread and despair.  If many of the Winterfall furbolgs do indeed carry these, it certainly would go a long way in explaining their current condition.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.",
    isForever = false,
  },
  [3382] = {
    id = 3382,
    title = "A Crew Under Fire",
    reqLevel = 48,
    questLevel = 57,
    faction = "Both",
    zone = "Azshara",
    npc = "Captain Vanessa Beltis",
    objectives = "Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive.",
    rewards = "600 XP",
    tip = "We were just off the coast looking for a safe haven to make anchor. The sun hadn't been down for more than an hour when they attacked... those damned naga!\n\nI'm not sure what they were looking for, but it's clear they didn't find it--they've already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.\n\nI'm sorry you've come along now, $N, but it's out of my hands.\n\nAre you ready for the fight of your life?",
    isForever = false,
  },
  [2801] = {
    id = 2801,
    title = "A Tale of Sorrow",
    reqLevel = 45,
    questLevel = 57,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Fallen Hero of the Horde",
    objectives = "Listen to the Fallen Hero of the Horde tell his story.",
    rewards = "600 XP",
    tip = "Before we may continue, you must hear my story.",
