  [7492] = {
    id = 7492,
    title = "Camp Mojache",
    reqLevel = 54,
    questLevel = 57,
    faction = "Horde",
    zone = "Dire Maul",
    npc = "Harbinger Balthazad",
    objectives = "Speak with Talo Thornhoof at Camp Mojache in Feralas.",
    rewards = "1,500 XP",
    tip = "Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.\n\nServe the Horde, $N.  Go to Camp Mojache in Feralas and speak with Talo.",
    isForever = false,
  },
  [8307] = {
    id = 8307,
    title = "Desert Recipe",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Cooking",
    npc = "Calandrath",
    objectives = "Look for information about cooking Sandworm Meat at the Twilight's Hammer camp west of Cenarion Hold.",
    rewards = "3,000 XP",
    tip = "Adapting to life in the desert has been difficult to say the least.  Not only do I miss the birds and trees of Auberdine but our food selection is severely limited by this arid environment.  I'm trying to learn about desert herbs, but there aren't many.\n\nI've seen Twilight's Hammer groups from the camp west of here hunt sandworms for food.  Sandworm meat is so bitter though, I can't imagine how they make it palatable.  Keep your eyes open if you go to their camp and let me know if you learn anyt",
    isForever = false,
  },
  [7494] = {
    id = 7494,
    title = "Feathermoon Stronghold",
    reqLevel = 54,
    questLevel = 57,
    faction = "Alliance",
    zone = "Dire Maul",
    npc = "Crier Goodman",
    objectives = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",
    rewards = "1,500 XP",
    tip = "$N!  Your aid is needed in Feralas!\n\nAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.\n\nLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.\n\nServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.",
    isForever = false,
  },
  [979] = {
    id = 979,
    title = "Find Ranshalla",
    reqLevel = 52,
    questLevel = 57,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Erelas Ambersky",
    objectives = "Find Ranshalla in eastern Winterspring.",
    rewards = "3,000 XP",
    tip = "Yes, yes, these feathers seem to hold the same magical enchantment that I noticed previously... While I am not certain what we might find, I urge you to continue searching for answers, $N.\n\nA colleague of mine recently traveled into Winterspring to observe the wildkin there, in their own habitat. Why don't you catch up with her and see what she has found?",
    isForever = false,
  },
  [5801] = {
    id = 5801,
    title = "Fire Plume Forged",
    reqLevel = 55,
    questLevel = 57,
    faction = "Alliance",
    zone = "Tanaris",
    npc = "Krinkle Goodsteel",
    objectives = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\n\nBring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands.",
    rewards = "4,500 XP",
    tip = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.\n\nTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.\n\nThat's it on my end.  To finish your key, you'll need to talk to Arbington ag",
    isForever = false,
  },
