  [5247] = {
    id = 5247,
    title = "Fragments of the Past",
    reqLevel = 53,
    questLevel = 57,
    faction = "Alliance",
    zone = "Eastern Plaguelands",
    npc = "Aurora Skycaller",
    objectives = "Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.",
    rewards = "6,000 XP",
    tip = "I will be able to help you, if recreating the artifact is truly what you wish to do.\n\nTo seal the pieces back together, I will need items with strong magical qualities. An enchanted thorium bar and five crystal restore... You'll also need to collect some water from what might seem an unlikely place... Find the dire pool along Eldreth Row at Dire Maul in Feralas, and fill this vial.\n\nWhile you are gone, I will attempt to glean from these pages the knowledge I need to repair the damage done to the",
    isForever = false,
  },
