  [1126] = {
    id = 1126,
    title = "Hive in the Tower",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Silithus",
    npc = "Layo Starstrike",
    objectives = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity.  Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.",
    rewards = "6,000 XP",
    tip = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.\n\nThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.",
    isForever = false,
  },
  [8317] = {
    id = 8317,
    title = "Kitchen Assistance",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Cooking",
    npc = "Calandrath",
    objectives = "Calandrath at Cenarion Hold needs a batch of 10 Smoked Desert Dumplings.",
    rewards = "3,000 XP • 1g 70s",
    tip = "That recipe sure will come in handy.  I'd better get to work so I can have some smoked desert dumplings ready for today.  I could use a hand in making some, I'll make it worth your while.",
    isForever = false,
  },
  [7488] = {
    id = 7488,
    title = "Lethtendris's Web",
    reqLevel = 54,
    questLevel = 57,
    faction = "Alliance",
    zone = "Dire Maul",
    npc = "Latronicus Moonspear",
    objectives = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",
    rewards = "7,550 XP • 1g 70s",
    tip = "The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!\n\nStop her, $N.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...",
    isForever = false,
  },
  [7489] = {
    id = 7489,
    title = "Lethtendris's Web",
    reqLevel = 54,
    questLevel = 57,
    faction = "Horde",
    zone = "Dire Maul",
    npc = "Talo Thornhoof",
    objectives = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.",
    rewards = "7,550 XP • 1g 70s",
    tip = "The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies.\n\nLethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for s",
    isForever = false,
  },
  [3141] = {
    id = 3141,
    title = "Loramus",
    reqLevel = 45,
    questLevel = 57,
    faction = "Both",
    zone = "Azshara",
    npc = "Loramus Thalipedes",
    objectives = "Listen to Loramus Thalipedes tell his story.",
    rewards = "600 XP",
    tip = "So you wish to battle demons? You would do well to listen to my tale.",
    isForever = false,
  },
  [5514] = {
    id = 5514,
    title = "Mold Rhymes With...",
    reqLevel = 55,
    questLevel = 57,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Apothecary Dithers",
    objectives = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.",
    rewards = "600 XP",
    tip = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an apothecary, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!",
    isForever = false,
  },
  [5538] = {
    id = 5538,
    title = "Mold Rhymes With...",
    reqLevel = 55,
    questLevel = 57,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Alchemist Arbington",
    objectives = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.",
    rewards = "600 XP",
    tip = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an alchemist, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!",
    isForever = false,
  },
  [8278] = {
    id = 8278,
    title = "Noggle's Last Hope",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Silithus",
    npc = "Beetix Ficklespragg",
    objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs.",
    rewards = "6,000 XP • 65s",
    tip = "Blasted!  The antidote didn't work.  Noggle must've been stung by one of the stronger creatures in the far south.\n\nI'm going to need you to go there and get me some more samples, $N.  The good news is that since their poison is stronger I won't require as many.  The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.",
    isForever = false,
  },
  [5781] = {
    id = 5781,
    title = "Of Forgotten Memories",
    reqLevel = 52,
    questLevel = 57,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Tirion Fordring",
    objectives = "- Taelan's Hammer",
    rewards = "6,000 XP",
    tip = "To help Taelan regain what he has lost, you must gather items from his past.\n\nThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.\n\nAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.\n\nYou must venture to the Undercroft and recover Taelan's hammer.",
    isForever = false,
  },
  [2783] = {
    id = 2783,
    title = "Petty Squabbles",
    reqLevel = 50,
    questLevel = 57,
    faction = "Alliance",
    zone = "Blasted Lands",
    npc = "Ambassador Ardalan",
    objectives = "Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp.",
    rewards = "4,500 XP",
    tip = "We fight the wrong enemy, $N.\n\nThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.\n\nDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.\n\nPut your differences aside, $N, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands.",
    isForever = false,
  },
  [5204] = {
    id = 5204,
    title = "Retribution of the Light",
    reqLevel = 49,
    questLevel = 57,
    faction = "Both",
    zone = "Felwood",
    npc = "Jessir Moonbow",
    objectives = "Return to Jaedenar and kill the succubus Rakaiah before finding the Remains of Trey Lightforge.",
    rewards = "4,500 XP",
    tip = "She would like to pretend that she's fine. She'd love for me to think that she's strong enough to deal with all of this on her own, but I know better than that. Trey's death and hearing the torture he was put through is going to haunt her for a long time, and there's nothing we can do to stop that. But we can give her some peace!\n\n$N, return to Shadow Hold, kill Trey's torturer and find his remains. There is no reason we can't tie off all these loose ends while Arko'narin mourns in her own priva",
    isForever = false,
  },
  [8313] = {
    id = 8313,
    title = "Sharing the Knowledge",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Cooking",
    npc = "Object: Sandy Cookbook",
    objectives = "Bring the Torn Recipe Page to Calandrath at the inn in Cenarion Hold.",
    rewards = "6,000 XP • 85s",
    tip = "While the recipe for cooking sandworm meat is legible, it contains references to herbs and spices you've never heard of.  Calandrath might have enough knowledge of the plants that grow in the desert to make sense of it.",
    isForever = false,
  },
  [964] = {
    id = 964,
    title = "Skeletal Fragments",
    reqLevel = 55,
    questLevel = 57,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Apothecary Dithers",
    objectives = "Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands.",
    rewards = "4,500 XP",
    tip = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.",
    isForever = false,
  },
  [5537] = {
    id = 5537,
    title = "Skeletal Fragments",
    reqLevel = 55,
    questLevel = 57,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Alchemist Arbington",
    objectives = "Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.",
    rewards = "4,500 XP",
    tip = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.",
    isForever = false,
  },
  [8281] = {
    id = 8281,
    title = "Stepping Up Security",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Silithus",
    npc = "Windcaller Proudhorn",
    objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers.",
    rewards = "6,000 XP • 1g 70s",
    tip = "Your performance has been truly exemplary so far, $N.  Our supply lines are not completely safe yet, however.  In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north.\n\nYou'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.",
    isForever = false,
  },
  [6805] = {
    id = 6805,
    title = "Stormers and Rumblers",
    reqLevel = 55,
    questLevel = 57,
    faction = "Both",
    zone = "Azshara",
    npc = "Duke Hydraxis",
    objectives = "Kill 15 Dust Stormers and 15 Desert Rumbers and then return to Duke Hydraxis in Azshara.",
    rewards = "6,000 XP",
    tip = "We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!\n\nFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.\n\nGo to the Crystal Vale in Silithus and defeat our enemies, then return to me.",
    isForever = false,
  },
  [5385] = {
    id = 5385,
    title = "The Remains of Trey Lightforge",
    reqLevel = 49,
    questLevel = 57,
    faction = "Both",
    zone = "Felwood",
    npc = "Remains of Trey Lightforge",
    objectives = "Return the Remains of Trey Lightforge to Jessir Moonbow in Felwood.",
    rewards = "7,550 XP • 22s",
    tip = "You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends.",
    isForever = false,
  },
  [2681] = {
    id = 2681,
    title = "The Stones That Bind Us",
    reqLevel = 45,
    questLevel = 57,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Fallen Hero of the Horde",
    objectives = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.",
    rewards = "7,550 XP",
    tip = "It will take more than you alone to overcome the forces of Razelikh and his subordinates.\n\nGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.\n\nFight hard and die with honor, $N.",
    isForever = false,
  },
  [6844] = {
    id = 6844,
    title = "Umber, Archivist",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Silithus",
    npc = "Layo Starstrike",
    objectives = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.",
    rewards = "3,000 XP",
    tip = "There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!\n\nTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do i",
    isForever = false,
  },
  [6845] = {
    id = 6845,
    title = "Uncovering Past Secrets",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Moonglade",
    npc = "Umber",
    objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.",
    rewards = "7,550 XP • 1g 70s",
    tip = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.\n\nIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, $N... that is, unless you want to be doused in honey.\n\nIt's happened, trust me.",
    isForever = false,
  },
  [1185] = {
    id = 1185,
    title = "Under the Chitin Was...",
    reqLevel = 54,
    questLevel = 57,
    faction = "Both",
    zone = "Moonglade",
    npc = "Umber",
    objectives = "Speak with Umber in Moonglade.",
    rewards = "3,000 XP",
    tip = "",
    isForever = false,
  },
  [6023] = {
    id = 6023,
    title = "Unfinished Business",
    reqLevel = 50,
    questLevel = 57,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Kirsta Deepshadow",
    objectives = "Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.",
    rewards = "6,000 XP • 65s",
    tip = "My real mission was to weaken the Scarlet Crusade's outlying forces and then infiltrate Hearthglen to gauge their numbers. I'm still in no shape to do it on my own, so perhaps I could ask you to aid me again, $N? From what information I gathered before being discovered, the Crusade has two important members that are the backbone of their forces outside the town: Huntsman Radley and Cavalier Durgen. Kill them, and we're making progress. They should be along Hearthglen Pass outside the town proper",
    isForever = false,
  },
  [5181] = {
    id = 5181,
    title = "Villains of Darrowshire",
    reqLevel = 50,
    questLevel = 57,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Carlin Redpath",
    objectives = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.",
    rewards = "6,000 XP",
    tip = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  His body was cast into a lake, northwest of Corin's Crossing, and his skull remains there.\n\nMarduk the Black was never defeated, but his fabled sword was shattered and lost.  It lies at the bottom of the gorge west of Corin's Crossing.\n\nRetrieve these items, $N.  I know not why, but I am certain their fate lies with you.",
    isForever = false,
  },
  [4902] = {
    id = 4902,
    title = "Wildkin of Elune",
    reqLevel = 52,
    questLevel = 57,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Erelas Ambersky",
    objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
    rewards = "6,000 XP",
    tip = "That's fascinating!\n\nI have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle. Explain to him what happened, just the same as you told me. I'm sure he will be just as interested!\n\nThis is important information, $N!",
    isForever = false,
  },
  [5087] = {
    id = 5087,
    title = "Winterfall Runners",
    reqLevel = 52,
    questLevel = 57,
    faction = "Both",
    zone = "Winterspring",
    npc = "Donova Snowden",
    objectives = "Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village.",
    rewards = "6,000 XP",
    tip = "Very interesting, $N...\n\nWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.\n\nWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their sh",
    isForever = false,
  },
  [4264] = {
    id = 4264,
    title = "A Crumpled Up Note",
    reqLevel = 50,
    questLevel = 58,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Item: A Crumpled Up Note",
    objectives = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.",
    rewards = "6,200 XP",
    tip = "The note has stains covering its surface. The text is barely legible, but you make out the following:\n\n...sweet irony...\n\n...the fall of the broken Alliance...\n\n...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...\n\n...Argelmach is almost done with the decryption of Windsor's notes.\n\nOur lord will rise from the depths and crush any that remain...\n\n-Emperor Dagran Thaurissan.",
    isForever = false,
  },
  [5242] = {
    id = 5242,
    title = "A Final Blow",
    reqLevel = 48,
    questLevel = 58,
    faction = "Both",
    zone = "Felwood",
    npc = "Greta Mosshoof",
    objectives = "Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.",
    rewards = "9,300 XP",
    tip = "Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside. The straight path down to the bottom is the only way... and I also know who you should seek out. His name is Fel'dan... Shadow Lord Fel'dan. He is the mortal in power down below... he is the head of the serpent. Kill him and his two succubus servants and return to me. Fel'dan is the one making pacts with the Legion. He must be",
    isForever = false,
  },
  [4282] = {
    id = 4282,
    title = "A Shred of Hope",
    reqLevel = 50,
    questLevel = 58,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Marshal Windsor",
    objectives = "Return Marshal Windsor's Lost Information.\n\nMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.",
    rewards = "6,200 XP • 90s",
    tip = "<Marshal Windsor shakes the note excitedly.>\n\nDo you realize what this means, $N?\n\nPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.\n\nI hope you are ready to battle.\n\nVenture forth and find these two villains! Destroy them and return my lost information.",
    isForever = false,
  },
  [4024] = {
    id = 4024,
    title = "A Taste of Flame",
    reqLevel = 52,
    questLevel = 58,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Cyrus Therepentous",
    objectives = "- Encased Fiery Essence",
    rewards = "6,200 XP, 2g 65s",
    tip = "I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.\n\nBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.\n\nUse the molt on his remains to safely extract the inner flame.\n\nSucceed and be rewarded.",
    isForever = false,
  },
  [977] = {
    id = 977,
    title = "Are We There, Yeti?",
    reqLevel = 52,
    questLevel = 58,
    faction = "Both",
    zone = "Winterspring",
    npc = "Umi Rumplesnicker",
    objectives = "Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook.",
    rewards = "4,650 XP • 90s",
    tip = "Now that I have what I need to cover the mechanical moving parts, I only need one other thing. Well, actually two. Two horns!\n\nThe ice thistle patriarchs and matriarchs have the largest horns, so of course, those are the ones I want. That type of yeti inhabits a cave to the southeast. There are plenty of them there; you shouldn't have any problem finding them.\n\nRemember, I only want the best looking ones -- no beat up or broken horns, please!",
    isForever = false,
  },
  [5163] = {
    id = 5163,
    title = "Are We There, Yeti?",
    reqLevel = 52,
    questLevel = 58,
    faction = "Both",
    zone = "Winterspring",
    npc = "Umi Rumplesnicker",
    objectives = "Take Umi's Mechanical Yeti and scare her friends with it:\n\nLegacki in Everlook (Winterspring)\nSprinkle in Gadgetzan (Tanaris)\nQuixxil in Marshal's Refuge (Un'Goro Crater)\n\nWhen you are done, bring the Mechanical Yeti back to Umi.",
    rewards = "7,750 XP • 90s",
    tip = "It's all ready, $N!\n\nNow, I sent some mail to my friends already, telling them that I have a surprise for them. This is where you come in!\n\nI'm going to give you my mechanical yeti, and you need to surprise them by paying each of my friends a visit, turning the yeti on and sending it towards them.\n\n Once you have shown Legacki in Everlook, Sprinkle in Gadgetzan, and Quixxil in Marshal's Refuge, come back and tell me what happened!\n\nPlease bring my yeti back to me then, too.",
    isForever = false,
  },
  [3602] = {
    id = 3602,
    title = "Azsharite",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Azshara",
    npc = "Loramus Thalipedes",
    objectives = "- Crystallized Azsharite x 20 - Crystallized Note - Crystallized Note",
    rewards = "7,750 XP, 2g 65s",
    tip = "The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.\n\nThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.\n\nYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal.",
    isForever = false,
  },
  [3508] = {
    id = 3508,
    title = "Breaking the Ward",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Azshara",
    npc = "Loramus Thalipedes",
    objectives = "Wait for Loramus to complete the enlightenment spell.",
    rewards = "3,100 XP",
    tip = "You are foolhardy, $N. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.\n\nTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.\n\nBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power.",
    isForever = false,
  },
  [5055] = {
    id = 5055,
    title = "Brumeran of the Chillwind",
    reqLevel = 53,
    questLevel = 58,
    faction = "Horde",
    zone = "Winterspring",
    npc = "Storm Shadowhoof",
    objectives = "Storm Shadowhoof at Bloodvenom Post in Felwood wants you to kill Brumeran.",
    rewards = "6,200 XP",
    tip = "Swift, and clever, Brumeran glides silently across the snowy landscape of southern Winterspring. But do not let her graceful appearance convince you that she is harmless. All that cross her pay considerably, and often with their own lives.\n\nSeek out Brumeran of the chillwind among the chimera. Defeat her, then return again to me.",
    isForever = false,
  },
  [8181] = {
    id = 8181,
    title = "Confront Yeh'kinya",
    reqLevel = 40,
    questLevel = 58,
    faction = "Both",
    zone = "Azeroth",
    npc = "Prospector Ironboot",
    objectives = "Speak with Yeh'kinya.",
    rewards = "6,200 XP",
    tip = "My delvings into the Mosh'aru Tablets bear grim news, $N.  Hakkar's true form, the god himself, can be born again through the very egg into which you captured him.  Yeh'kinya told you it was to contain his evil, but it is to recreate it!  The troll has led you astray!\n\nGo to Yeh'kinya and demand the egg from him.  Pray that it is not too late to stop Hakkar's return!",
    isForever = false,
  },
  [3625] = {
    id = 3625,
    title = "Enchanted Azsharite Fel Weaponry",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Galvan the Ancient",
    objectives = "- Weaponry Creation",
    rewards = "620 XP",
    tip = "$N, the creation of each weapon will take some time.\n\nAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!\n\nNow give me a moment to craft your weapon, $N.",
    isForever = false,
  },
  [5227] = {
