  [4122] = {
    id = 4122,
    title = "Grark Lorkrub",
    reqLevel = 52,
    questLevel = 58,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Lexlort",
    objectives = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.",
    rewards = "6,200 XP",
    tip = "I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.\n\nHe now sits in the Burning Steppes, safely under their protection - or so he thinks.\n\nTake these shackles, $N. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours.",
    isForever = false,
  },
  [5582] = {
    id = 5582,
    title = "Healthy Dragon Scale",
    reqLevel = 55,
    questLevel = 58,
    faction = "Both",
    zone = "Scholomance",
    npc = "Item: Healthy Dragon Scale",
    objectives = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.",
    rewards = "Experience & Faction Reputation",
    tip = "This is a scale shed from a plagued dragon hatchling.  But unlike the other pocked, oozing scales on the infant beast, this rare scale is healthy and unmarred.\n\nBetina Bigglezink will want a sample of this to study.",
    isForever = false,
  },
  [4322] = {
    id = 4322,
    title = "Jail Break!",
    reqLevel = 50,
    questLevel = 58,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Marshal Windsor",
    objectives = "- Jail Break!",
    rewards = "7,750 XP, 1g 75s",
    tip = "We need to get out of here, $N. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.",
    isForever = false,
  },
  [2721] = {
    id = 2721,
    title = "Kirith",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Fallen Hero of the Horde",
    objectives = "Find out what became of Lieutenant Kirith.",
    rewards = "6,200 XP",
    tip = "As one chapter of your adventure closes, another one begins, $N.\n\nOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.\n\nAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.",
    isForever = false,
  },
  [7623] = {
    id = 7623,
    title = "Lord Banehollow",
    reqLevel = 60,
    questLevel = 58,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Gorzeeki Wildeyes",
    objectives = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.\n\nUse the potions to travel through Jaedenar, and speak with Lord Banehollow.",
    rewards = "6,200 XP",
    tip = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!\n\nThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.\n\nBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you...",
    isForever = false,
  },
