  [7562] = {
    id = 7562,
    title = "Mor'zul Bloodbringer",
    reqLevel = 60,
    questLevel = 58,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Spackle Thornberry",
    objectives = "Speak with Mor'zul Bloodbringer in the Burning Steppes.",
    rewards = "625 XP",
    tip = "$N, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.\n\nThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes.\n\nGo, $N.  This quest will be perilous, but a Warlock of your stature does not shy from da",
    isForever = false,
  },
  [8282] = {
    id = 8282,
    title = "Noggle's Lost Satchel",
    reqLevel = 54,
    questLevel = 58,
    faction = "Both",
    zone = "Silithus",
    npc = "Noggle Ficklespragg",
    objectives = "Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold.",
    rewards = "6,200 XP",
    tip = "Where am I?  Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid.  In my rush to escape I walked right into a nest of stonelash flayers.\n\nThe satchel I was carrying had all sorts of rare reagents in it.  Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs.  I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents.\n\nI ran into Deathclasp in the southern mountain range, behind Bronzebeard's",
    isForever = false,
  },
  [5845] = {
    id = 5845,
    title = "Of Lost Honor",
    reqLevel = 52,
    questLevel = 58,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Tirion Fordring",
    objectives = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.",
    rewards = "6,200 XP",
    tip = "The Order of the Silver Hand was utterly decimated when Uther was slain.\n\nThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.\n\nWere any of the Order left alive, he thought - and did it matter?\n\nIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.\n\nYou must travel to Northdale and recover that symbol of lost honor.",
    isForever = false,
  },
  [5846] = {
    id = 5846,
    title = "Of Love and Family",
    reqLevel = 52,
    questLevel = 58,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Tirion Fordring",
    objectives = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.",
    rewards = "6,200 XP",
    tip = "When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.\n\nIf this painting still exists, you must find it.\n\nTravel to the ruined island of Caer Darrow and see if the painting or the artist rem",
    isForever = false,
  },
  [4132] = {
    id = 4132,
    title = "Operation: Death to Angerforge",
    reqLevel = 52,
    questLevel = 58,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Warlord Goretooth",
    objectives = "- General Angerforge",
    rewards = "7,750 XP, 2g 65s",
    tip = "You have done an exemplary job, $N. It is now time to send you on your last mission.\n\nGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.\n\nThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.",
    isForever = false,
  },
  [5529] = {
    id = 5529,
    title = "Plagued Hatchlings",
    reqLevel = 55,
    questLevel = 58,
    faction = "Both",
    zone = "Scholomance",
    npc = "Betina Bigglezink",
    objectives = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.",
    rewards = "6,200 XP • 90s",
    tip = "The Argent Dawn recently learned that the Scourge are creating their own plagued dragonflight!  We must stop them -- if the Scourge gain a force of dragons they'll sweep across Azeroth unchecked!\n\nTheir necromancers are breeding plagued dragons at the Scholomance, in the middle of Darrowmere Lake.\n\nGo to the Scholomance and kill as many hatchlings as you can... before they get any bigger!",
    isForever = false,
  },
  [4121] = {
    id = 4121,
    title = "Precarious Predicament",
    reqLevel = 52,
    questLevel = 58,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Grark Lorkrub",
    objectives = "- Thorium Shackles - Prisoner Transport",
    rewards = "7,750 XP, 2g 65s",
    tip = "Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?\n\nYou will be destroyed!",
    isForever = false,
  },
  [7441] = {
    id = 7441,
    title = "Pusillin and the Elder Azj'Tordin",
    reqLevel = 54,
    questLevel = 58,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Azj'Tordin",
    objectives = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\n\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.",
    rewards = "7,750 XP • 1g 75s",
    tip = "I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.\n\nI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.\n\nFind the imp, Pusillin, and recover my book.\n\nSearch the Warpwood Quarter of Dire Maul for Pusillin.",
    isForever = false,
  },
  [7563] = {
    id = 7563,
    title = "Rage of Blood",
    reqLevel = 60,
    questLevel = 58,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Mor'zul Bloodbringer",
    objectives = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.",
    rewards = "7,750 XP",
    tip = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.\n\nIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.\n\nTheir blood is what I need to ink your parchment.  Bring it to me.",
    isForever = false,
  },
  [5252] = {
    id = 5252,
    title = "Remorseful Highborne",
    reqLevel = 53,
    questLevel = 58,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Remorseful Highborne",
    objectives = "Speak with Wynd Nightchaser in Starfall Village, and ask about the proper place for the Crystal of Zin-Malor.",
    rewards = "4,650 XP",
    tip = "The... the crystal...\n\nThe highborne here are clouded by their own misssery...\n\nI am sorrrrrowful, but I realize the errorrrr of what happened so long ago. Even though there is no waaaay to change the past, I am now at peacccce knowing that you have recovered the crystal of Zin-Malor...\n\nYouuu must return it...\n\nIt muuuussst be returrrned.",
    isForever = false,
  },
  [5226] = {
    id = 5226,
    title = "Return to Chillwind Point",
    reqLevel = 50,
    questLevel = 58,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Object: Scourge Cauldron",
    objectives = "Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.",
    rewards = "3,100 XP • 90s",
    tip = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.",
    isForever = false,
  },
  [3626] = {
    id = 3626,
    title = "Return to the Blasted Lands",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Galvan the Ancient",
    objectives = "Return to the Fallen Hero of the Horde.",
    rewards = "1,550 XP",
    tip = "The hour of redemption is near, $N. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective.",
    isForever = false,
  },
  [5236] = {
    id = 5236,
    title = "Return to the Bulwark",
    reqLevel = 50,
    questLevel = 58,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Object: Scourge Cauldron",
    objectives = "Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.",
    rewards = "3,100 XP • 90s",
    tip = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.",
    isForever = false,
  },
  [5225] = {
    id = 5225,
    title = "Target: Gahrron's Withering",
    reqLevel = 50,
    questLevel = 58,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "High Priestess MacDonnell",
    objectives = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.",
    rewards = "6,200 XP",
    tip = "The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N.\n\nGahrron's Withering is due northeast of our position here, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the Light protect you in this dangerous mission, $c.",
    isForever = false,
  },
  [5235] = {
    id = 5235,
    title = "Target: Gahrron's Withering",
    reqLevel = 50,
    questLevel = 58,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Shadow Priestess Vandis",
    objectives = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.",
    rewards = "6,200 XP",
    tip = "The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N.\n\nGahrron's Withering is far to the east of the Bulwark, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the shadows cloak you in safety for this dangerous mission,",
    isForever = false,
  },
  [6026] = {
    id = 6026,
    title = "That's Asking A Lot",
    reqLevel = 54,
    questLevel = 58,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Smokey LaRue",
    objectives = "- Thorium Bar x 2 - Golden Rod - Hi-Explosive Bomb x 8 - Unstable Trigger x 8",
    rewards = "6,200 XP, 1g 75s",
    tip = "These here Argent Dawn people commissioned ol' Smokey to do a little demolition work for 'em. Smokey's mammy ain't raised no dummy. When gold coin is slapped on the table, Smokey's services are available. That's my motto!\n\nNow I'd be willing to split the commission with you if you're willing to do a little legwork. Here's the deal: I'm going to head over to Plaguewood and mark the buildings we need destroyed. You gather the components for the bombs. Meet back here when you've got everything. Dea",
    isForever = false,
  },
  [5253] = {
    id = 5253,
    title = "The Crystal of Zin-Malor",
    reqLevel = 53,
    questLevel = 58,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Wynd Nightchaser",
    objectives = "Deliver the Crystal of Zin-Malor to Arch Druid Fandral Staghelm in Darnassus.",
    rewards = "6,200 XP",
    tip = "Quite impressive, $N.\n\nThe crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded.\n\nSeek out Arch Druid Fandral Staghelm in Darnassus, and bring the crystal to him, $N. It should be in the hands of those that will not abuse its power. From the looks of it, only a handful of the strongest magic users would be able to control such a power.",
    isForever = false,
  },
  [4788] = {
    id = 4788,
    title = "The Final Tablets",
    reqLevel = 40,
    questLevel = 58,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Prospector Ironboot",
    objectives = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.",
    rewards = "7,750 XP",
    tip = "While I look over the third and fourth tablets of Mosh'aru, you must find the fifth and sixth!  It will not be easy, for they are held by the Smolderthorn trolls within Blackrock Spire.  The spire is a dark mountain of fire between the Burning Steppes and the Searing Gorge.\n\nGood luck, $N.  Blackrock Spire is no place for decent folk...",
    isForever = false,
  },
  [3621] = {
    id = 3621,
    title = "The Formation of Felbane",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Azshara",
    npc = "Loramus Thalipedes",
    objectives = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.",
    rewards = "4,650 XP",
    tip = "The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.\n\nIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.\n\nMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.",
    isForever = false,
  },
  [8182] = {
    id = 8182,
    title = "The Hand of Rastakhan",
    reqLevel = 40,
    questLevel = 58,
    faction = "Both",
    zone = "Tanaris",
    npc = "Prospector Ironboot",
    objectives = "Speak with Molthor in Stranglethorn.",
    rewards = "9,300 XP",
    tip = "$N, our worst fears have come.  Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute.  If he cannot be stopped now, then his new reign may spread across all of Azeroth!\n\nThere is a contingent of Zandalarian trolls who may help us stem this tide of darkness.  They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda.  Speak with their leader, Molthor, and pray he knows how to defeat Hakkar.",
    isForever = false,
  },
  [5065] = {
    id = 5065,
    title = "The Lost Tablets of Mosh'aru",
    reqLevel = 40,
    questLevel = 58,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Prospector Ironboot",
    objectives = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.",
    rewards = "7,750 XP",
    tip = "The troll with whom you spoke did not tell the truth.  The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend.  I have studied long, and found that there are six Tablets of Mosh'aru, not two!  Six!\n\nAnd I fear that we will not like what secrets the others hold..\n\nFind the third and fourth tablets of Mosh'aru.  They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me.",
    isForever = false,
  },
  [3509] = {
    id = 3509,
    title = "The Name of the Beast",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Azshara",
    npc = "Loramus Thalipedes",
    objectives = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.",
    rewards = "6,200 XP",
    tip = "There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.\n\nWhen such a weapon is forged, the demon and all under his command are vulnerable.\n\nA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.\n\nUndoubtedly, you will have to pay a price for such information.",
    isForever = false,
  },
  [3510] = {
    id = 3510,
    title = "The Name of the Beast",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Azshara",
    npc = "Lord Arkkoroc",
    objectives = "- Hetaera's Beaten Head - Hetaera's Bloodied Head - Hetaera's Bruised Head",
    rewards = "6,200 XP, 2g 65s",
    tip = "She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.\n\nFor that, you will be given the name that you seek and something else of equal importance.\n\nShe roams the clutch... Hetaera she is called.\n\n<Lord Arkkoroc points to the southwest.>\n\nGo!",
    isForever = false,
  },
  [3511] = {
    id = 3511,
    title = "The Name of the Beast",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Azshara",
    npc = "Lord Arkkoroc",
    objectives = "Take the temper back to Loramus Thalipedes.",
    rewards = "3,100 XP",
    tip = "As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.\n\nThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.\n\n<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>\n\nTake the temper back to Loramus along with the name of the beast: Rakh'likh.",
    isForever = false,
  },
  [4063] = {
    id = 4063,
    title = "The Rise of the Machines",
    reqLevel = 52,
    questLevel = 58,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Lotwil Veriatus",
    objectives = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",
    rewards = "6,200 XP • 2g 65s",
    tip = "This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him.\n\nHe was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice.\n\nIf this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.",
    isForever = false,
  },
  [8284] = {
    id = 8284,
    title = "The Twilight Mystery",
    reqLevel = 54,
    questLevel = 58,
    faction = "Both",
    zone = "Silithus",
    npc = "Geologist Larksbane",
    objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments.",
    rewards = "6,200 XP • 90s",
    tip = "A camp of Twilight's Hammer cultists once thrived northwest of here.  If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was.\n\nI've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful.  See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus.",
    isForever = false,
  },
  [6022] = {
    id = 6022,
    title = "To Kill With Purpose",
    reqLevel = 54,
    questLevel = 58,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.",
    rewards = "6,200 XP • 90s",
    tip = "You kill with purpose while you remain on my stead.\n\nYour first task is to feed my hounds.\n\nTake this mortar and pestle and travel to Corin's Crossing. Once there, you will find a robust selection of Scourge to slaughter. From their fresh carcasses I need living rot. Take that living rot and grind it up in the mortar, then let it sit to coagulate. Bring the coagulated rot back here.\n\nAnd imbecile, realize that living rot from the undead doesn't remain 'living' for very long. You must kill quickl",
    isForever = false,
  },
  [5248] = {
    id = 5248,
    title = "Tormented By the Past",
    reqLevel = 53,
    questLevel = 58,
    faction = "Alliance",
    zone = "Eastern Plaguelands",
    npc = "Aurora Skycaller",
    objectives = "Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you.",
    rewards = "4,650 XP",
    tip = "$N, I weep for what has happened in the past. Like this crystal, the elves, as a race, have been shattered. I do not know if the pieces will ever again be reunited into one, but my sorrow has been eased by being able to help you with this one small task. \n\nWe must not forget the past, $N...\n\nPlease take the Crystal of Zin-Malor back to Lake Kel'Theril. You must find a highborne spirit that realizes the error of what was done so long ago. Show the spirit that we have made things right again.",
    isForever = false,
  },
  [7624] = {
    id = 7624,
    title = "Ulathek the Traitor",
    reqLevel = 60,
    questLevel = 58,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Lord Banehollow",
    objectives = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar.",
    rewards = "6,200 XP",
    tip = "You wish to enter my good graces?  Then kill for me.\n\nMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...\n\nProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!",
    isForever = false,
  },
  [6042] = {
    id = 6042,
    title = "Un-Life's Little Annoyances",
    reqLevel = 54,
    questLevel = 58,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.",
    rewards = "6,200 XP • 90s",
    tip = "You cannot take two steps off of this farm without running into one of those obnoxious bats. I want to be able to take the hounds out and slaughter Scourge without being accosted by any damned, dirty bats. Obviously, I have better things to do with my time than mindlessly kill bats day in and day out. You, however, do not.\n\nWhat? Your training? This is your training! Now get out of my sight and don't come back until you've killed a fair number of those winged demons. Don't disappoint me.",
    isForever = false,
  },
  [6025] = {
    id = 6025,
    title = "Unfinished Business",
    reqLevel = 50,
    questLevel = 58,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Kirsta Deepshadow",
    objectives = "Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands.",
    rewards = "6,200 XP • 1g 75s",
    tip = "What? Really? You want to know more? But you've already done so much for me, $N. I couldn't possibly ask you to enter Hearthglen itself on my behalf.\n\nAre you sure, $N? Hearthglen is much more dangerous than the Pass--I cannot provide you any protection  or even information about what you might face.\n\nWell, if you really are willing to help, then enter the town and find a high place to gain a good view of the town. From there you can gauge their numbers and report them back to me. But be careful",
    isForever = false,
  },
  [6041] = {
    id = 6041,
    title = "When Smokey Sings, I Get Violent",
    reqLevel = 54,
    questLevel = 58,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Smokey LaRue",
    objectives = "Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.\n\nOnce you plant the bomb, leave the building and marvel at your handiwork.\n\nBy the way, Smokey's Special Compound is rather... unstable.",
    rewards = "6,200 XP • 2g 65s",
    tip = "While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished.\n\nHere's the plan: I'm going to give you ten sticks of my special compound. You're going to take them over to Plaguewood and plant them inside the Scourge structures that I've had marked for detonation.\n\n<Smokey snaps his fingers.>\n\nBing! It's just that easy.",
    isForever = false,
  },
  [4741] = {
    id = 4741,
    title = "Wild Guardians",
    reqLevel = 52,
    questLevel = 58,
    faction = "Horde",
    zone = "Felwood",
    npc = "Trull Failbane",
    objectives = "Trull Failbane in Felwood wants you to hunt 13 Moontouched Owlbeasts.",
    rewards = "6,200 XP • 90s",
    tip = "In the northern areas of Winterspring, the Wildkin grow even more ferocious. We must continue our measures there.\n\nHunt the moontouched owlbeasts in Winterspring, and explore the area they inhabit.\n\nThis is dangerous ground, but I know that you will be able to handle the challenge. Return to me after you have slain 13 of the wildkin.",
    isForever = false,
  },
  [7564] = {
    id = 7564,
    title = "Wildeyes",
    reqLevel = 60,
    questLevel = 58,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Mor'zul Bloodbringer",
    objectives = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes.",
    rewards = "3,100 XP",
    tip = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work.",
    isForever = false,
  },
  [8464] = {
    id = 8464,
    title = "Winterfall Activity",
    reqLevel = 45,
    questLevel = 58,
    faction = "Both",
    zone = "Azeroth",
    npc = "Salfa",
    objectives = "- Winterfall Shaman x 8 - Winterfall Den Watcher x 8 - Winterfall Ursa x 8",
    rewards = "6,200 XP",
    tip = "The Timbermaw tend to stay to themselves, $N.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.\n\nThe Winterfall tribe as of late has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nI must ask you to thin their numbers as to lessen the threat against us.  Seek them out in Winterfall Village, far to the east of here.",
    isForever = false,
  },
  [8429] = {
    id = 8429,
    title = "Battle of Warsong Gulch",
    reqLevel = 50,
    questLevel = 59,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "6,400 XP • 90s",
    tip = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!",
    isForever = false,
  },
  [8434] = {
    id = 8434,
    title = "Battle of Warsong Gulch",
    reqLevel = 50,
    questLevel = 59,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "3,200 XP",
    tip = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance. Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N! Come back to me with proof of serving the Horde in a worthy manner!",
    isForever = false,
  },
  [4982] = {
    id = 4982,
    title = "Bijou's Belongings",
    reqLevel = 55,
    questLevel = 59,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Bijou",
    objectives = "- Bijou's Belongings",
    rewards = "6,400 XP",
    tip = "At night when this place is lightly guarded, I sneak around the city, taking notes and writing down anything I see that could be of some strategic value to the K.E.F.\n\nLast night, however, things went dreadfully wrong. I stumbled across a tripwire and set off an alarm. I stashed my recon gear and ran for cover! Unfortunately, I can't get back to that gear. They've doubled and tripled up the patrols! All that information is lost.\n\nGet my belongings back and I'll return to the K.E.F. peacefully.",
    isForever = false,
  },
  [5001] = {
    id = 5001,
    title = "Bijou's Belongings",
    reqLevel = 55,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Bijou",
    objectives = "- Bijou's Belongings",
    rewards = "6,400 XP",
    tip = "Ordinarily I don't deal with $rs but it seems that I'm stuck between a troll and a hard place. You see, my mission here is one of utmost importance to the Horde. The information I've discovered, however, applies to the well being of the Alliance as well. Now believe me, I'm no Alliance sympathizer, but the Blackrock threat is bigger than just a bunch of orcs.\n\nYou help me out by finding my belongings and I'll help you out with some information that could prove useful to your kind.\n\nDeal?",
    isForever = false,
  },
  [4983] = {
    id = 4983,
    title = "Bijou's Reconnaissance Report",
    reqLevel = 55,
    questLevel = 59,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Bijou",
    objectives = "Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath.",
    rewards = "6,400 XP, 1g 80s",
    tip = "Take this report back to Lexlort. It will redeem my good name and will surely give the K.E.F. a strategic advantage in dealing with these orcs.\n\nCome with you? I've got way too much work to do. Get going, they need these reports as soon as possible!",
    isForever = false,
  },
  [8395] = {
    id = 8395,
    title = "Claiming Arathi Basin",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "6,400 XP • 90s",
    tip = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Bas",
    isForever = false,
  },
  [8397] = {
    id = 8397,
    title = "Claiming Arathi Basin",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "3,200 XP",
    tip = "Winning a war is about more than just outsmarting and outfighting your opponent. Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops. If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us! Now is the time to help the Alliance in Arathi Basin,",
    isForever = false,
  },
  [8438] = {
    id = 8438,
    title = "Conquering Arathi Basin",
    reqLevel = 50,
    questLevel = 59,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "6,400 XP • 90s",
    tip = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $N!",
    isForever = false,
  },
  [8442] = {
    id = 8442,
    title = "Conquering Arathi Basin",
    reqLevel = 50,
    questLevel = 59,
    faction = "Horde",
    zone = "Arathi Basin",
