  [4862] = {
    id = 4862,
    title = "En-Ay-Es-Tee-Why",
    reqLevel = 55,
    questLevel = 59,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Kibler",
    objectives = "- Spire Spider Egg x 15",
    rewards = "6,400 XP, 90s",
    tip = "Believe it or not, there are people out there willing to pay for the most vile of domesticated beast!\n\nI'd sent Bijou into the Spire to try and collect some of those spire spider eggs but I haven't heard from her in weeks. Maybe you can help me out?\n\nI'll tell you what, $N. Go to Blackrock Spire and collect some spire spider eggs for me. Bring them back here and not only will I give you a little cash, but I'll even domesticate one for you!",
    isForever = false,
  },
  [4861] = {
    id = 4861,
    title = "Enraged Wildkin",
    reqLevel = 53,
    questLevel = 59,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Jaron Stoneshaper",
    objectives = "Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring.",
    rewards = "3,200 XP",
    tip = "Hey there, $Glad:lass;! I was chased from my camp in southern Winterspring by some bloodthirsty wildkin! Well, I suppose I got too close to something the wildkin were guarding.\n\nI barely managed to get away safely; I fear a buddy of mine wasn't as lucky. Would you mind braving the wildkin and heading to the camp? I really need my supplies, and I'd also like to get back the amulet I unearthed yesterday at the dig site.",
    isForever = false,
  },
  [4863] = {
    id = 4863,
    title = "Enraged Wildkin",
    reqLevel = 53,
    questLevel = 59,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Object: Damaged Crate",
    objectives = "Find Jaron Stoneshaper's wrecked wagon.",
    rewards = "3,200 XP",
    tip = "Looking around, you don't see much that Jaron could want here. However, you do notice that the crate you found has been smashed open, almost as if this was what the wildkin were after...\n\nLooking to the east, you can barely make out an abandoned wagon. Perhaps you might find Jaron's things there. It's worth a look.",
    isForever = false,
  },
  [4864] = {
    id = 4864,
    title = "Enraged Wildkin",
    reqLevel = 53,
    questLevel = 59,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Object: Jaron's Wagon",
    objectives = "Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of.\n\nBring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring.",
    rewards = "6,400 XP • 90s",
    tip = "After inspecting the contents of the box, you decide that Jaron could make use of the tools and other items inside. However, there is no sign of the amulet.\n\nIt appears that the wildkin inhabit the lands to the north and east of here, so you decide that the next step is to face the creatures and reclaim the amulet from them.",
    isForever = false,
  },
  [6604] = {
    id = 6604,
    title = "Enraged Wildkin",
    reqLevel = 53,
    questLevel = 59,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Harlo Wigglesworth",
    objectives = "Speak with Jaron Stoneshaper at Starfall Village.",
    rewards = "640 XP",
    tip = "Have you noticed the abandoned camp to the south of here? It looks like the wildkin went crazy and destroyed just about everything they could find!\n\nI heard a rumor that one of the survivors of the attack is resting at Starfall Village, west of here. I'm sure curious about what happened... aren't you?",
    isForever = false,
  },
  [8402] = {
    id = 8402,
    title = "Fight for Warsong Gulch",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "6,400 XP • 90s",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
    isForever = false,
  },
  [8407] = {
    id = 8407,
    title = "Fight for Warsong Gulch",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "3,200 XP",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest. There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack. Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N! For the Alliance!",
    isForever = false,
  },
  [4901] = {
    id = 4901,
    title = "Guardians of the Altar",
    reqLevel = 52,
    questLevel = 59,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Ranshalla",
    objectives = "Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village.",
    rewards = "4,800 XP",
    tip = "At the very top of the ridge lies what I believe to be an altar of the goddess Elune. From what I can tell, we need to light the five torches in each cave, and then we will be able to access the altar directly.\n\nI transcribed some incantations carved into the stone in the ancient ruins of Kel'Theril, which I believe are the secret to unlocking the altar. I'll need your help to light each torch, while I recite the spell.\n\nIf we are successful, you'll be able to report our findings to Erelas!",
    isForever = false,
  },
  [4882] = {
    id = 4882,
    title = "Guarding Secrets",
    reqLevel = 52,
    questLevel = 59,
    faction = "Horde",
    zone = "Winterspring",
    npc = "Item: Blue-feathered Necklace",
    objectives = "Take the Blue-feathered Necklace to Trull Failbane at Bloodvenom Post.",
    rewards = "3,200 XP",
    tip = "You are unsure of the significance of the necklace that fell from the neck of the recently-slain wildkin. It glows brightly, slowly fading in and out.\n\nTrull Failbane might be able to tell you more, since his knowledge of the wildkin seems extensive. Perhaps you should ask him about it.",
    isForever = false,
  },
  [4883] = {
    id = 4883,
    title = "Guarding Secrets",
    reqLevel = 52,
    questLevel = 59,
    faction = "Horde",
    zone = "Winterspring",
    npc = "Trull Failbane",
    objectives = "Take the Blue-feathered Necklace to Nara Wildmane.",
    rewards = "6,400 XP",
    tip = "While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield. But I do believe I know of one that would be able to examine the necklace and most likely tell you what it is.\n\nNara Wildmane in Thunder Bluff is an expert in this field; see her. Good luck, $N.",
    isForever = false,
  },
  [5121] = {
    id = 5121,
    title = "High Chief Winterfall",
    reqLevel = 52,
    questLevel = 59,
    faction = "Both",
    zone = "Winterspring",
    npc = "Donova Snowden",
    objectives = "Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.",
    rewards = "6,400 XP",
    tip = "While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand.\n\nThe Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but I think that if their leader is slain, they will not get any worse.\n\nHead east to Winterfall Vill",
    isForever = false,
  },
  [4341] = {
    id = 4341,
    title = "Kharan Mighthammer",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "King Magni Bronzebeard",
    objectives = "Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.",
    rewards = "6,400 XP",
    tip = "You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!\n\n<The King sobs.>\n\nAnd now she's gone, $N!\n\nI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!\n\nKharan is supposedly being held prisoner there... find him! I want answers!",
    isForever = false,
  },
  [4342] = {
    id = 4342,
    title = "Kharan's Tale",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Kharan Mighthammer",
    objectives = "- Kharan's Tale",
    rewards = "1,600 XP",
    tip = "Please, hear me out before passing judgement!",
    isForever = false,
  },
  [4729] = {
    id = 4729,
    title = "Kibler's Exotic Pets",
    reqLevel = 55,
    questLevel = 59,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Kibler",
    objectives = "- Caged Worg Pup",
    rewards = "6,400 XP, 90s",
    tip = "You're probably wondering what I'm doing out here. Look at the cages! Ain't it obvious?\n\nI'm an animal lover, first and foremost, but a salesman by trade. I track down exotic animals for the rich and famous and domesticate the beasts so they behave as proper pets.\n\nNow you're probably wondering, \"What can I do for you, Kibler.\" The answer is simple: Take this here beast cage and find me some worg pups. For that, I'll domesticate a worg for you!",
    isForever = false,
  },
  [5002] = {
    id = 5002,
    title = "Message to Maxwell",
    reqLevel = 55,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Bijou",
    objectives = "Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell.",
    rewards = "6,400 XP • 1g 80s",
    tip = "I'm a goblin of my word, $r. Now listen closely:\n\nThese orcs are used primarily as beasts of burden and cannon fodder for the black dragonflight!\n\nTheir true leader is none other than Nefarian, brood of Deathwing. I've also discovered the location of Nefarian's subordinates in this part of the citadel.\n\nTake this map to Marshal Maxwell in the Burning Steppes. It has the location of these fiends marked for easy identification.",
    isForever = false,
  },
  [4981] = {
    id = 4981,
    title = "Operative Bijou",
    reqLevel = 55,
    questLevel = 59,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Lexlort",
    objectives = "Travel to Blackrock Spire and find out what happened to Bijou.",
    rewards = "6,400 XP",
    tip = "Never trust a goblin. That's what it comes down to, $N.\n\nBijou is her name - one of our slipperiest operatives. I found out she was working for some shady exotic pet dealer out of the Burning Steppes named Kibler, in essence, two timing us. Worse yet, she was using Horde funds to finance her operations.\n\nI want her brought back here alive.\n\nShe was last seen entering Blackrock Spire. Find her and bring her back.\n\nAnd $N, do not let her sweet talk you.",
    isForever = false,
  },
  [4701] = {
    id = 4701,
    title = "Put Her Down",
    reqLevel = 55,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Helendis Riverhorn",
    objectives = "- Halycon",
    rewards = "6,400 XP, 1g 80s",
    tip = "You have no doubt seen the worgs which the Blackrock orcs command.\n\nIt is curious - no matter how many we destroy, their numbers never dwindle. My scouts have reported that the worgs are bred, trained, and ultimately exported from Blackrock Spire: capital city of the Blackrock orcs. You must travel to Blackrock Spire and discover the source of this menace. Discover... and destroy.\n\nGood luck, $N. May Cenarius protect you...",
    isForever = false,
  },
  [8324] = {
    id = 8324,
    title = "Still Believing",
    reqLevel = 54,
    questLevel = 59,
    faction = "Both",
    zone = "Silithus",
    npc = "Hermit Ortell",
    objectives = "- Encrypted Twilight Text x 10",
    rewards = "45s",
    tip = "",
    isForever = false,
  },
  [4361] = {
    id = 4361,
    title = "The Bearer of Bad News",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Kharan Mighthammer",
    objectives = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.",
    rewards = "6,400 XP",
    tip = "You must take this information back to King Magni, $N. He will know what to do!",
    isForever = false,
  },
  [8285] = {
    id = 8285,
    title = "The Deserter",
    reqLevel = 54,
    questLevel = 59,
    faction = "Both",
    zone = "Silithus",
    npc = "Geologist Larksbane",
    objectives = "Take the restored tablet to Hermit Ortell in Silithus.",
    rewards = "4,800 XP",
    tip = "There are rumors of a Twilight's Hammer member called Ortell having deserted his sect.  Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit.  Perhaps you can enlist his help in deciphering the tablet.\n\nTake the restored tablet with you and seek out Ortell.",
    isForever = false,
  },
  [4362] = {
    id = 4362,
    title = "The Fate of the Kingdom",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "King Magni Bronzebeard",
    objectives = "- Emperor Dagran Thaurissan",
    rewards = "8,050 XP",
    tip = "It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.\n\nYou may be my last hope, $N. You must rescue my dear daughter, Moira!\n\nThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.\n\nAnd $N, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!",
    isForever = false,
  },
  [5123] = {
    id = 5123,
    title = "The Final Piece",
    reqLevel = 52,
    questLevel = 59,
    faction = "Both",
    zone = "Winterspring",
    npc = "Item: Crudely-written Log",
    objectives = "Bring the Crudely-written Log to Donova Snowden in Winterspring.",
    rewards = "3,200 XP",
    tip = "The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them.\n\nBut perhaps Donova will be able to tell you what it says...",
    isForever = false,
  },
  [4724] = {
    id = 4724,
    title = "The Pack Mistress",
    reqLevel = 55,
    questLevel = 59,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Galamav the Marksman",
    objectives = "Slay Halycon, pack mistress of the Bloodaxe worg.",
    rewards = "6,400 XP • 1g 80s",
    tip = "Some say the worg controlled by the Blackrock orcs are the creation of a supernatural force. Others say they are not true worg but instead a breed of demon dog, granted to the orcs by a fallen pit lord.\n\nThe truth is far less contrived but every bit as frightening. The worg of Blackrock come from Halycon and her mate. Halycon is the gigantic den mother of the worg. Her mate? Nobody has ever lived to tell the tale of that one.\n\nStrike at the heart of the worg. Destroy Halycon... and $N, watch you",
    isForever = false,
  },
  [4363] = {
    id = 4363,
    title = "The Princess's Surprise",
    reqLevel = 50,
    questLevel = 59,
    faction = "Alliance",
    zone = "Blackrock Depths",
    npc = "Princess Moira Bronzebeard",
    objectives = "Return to Ironforge and speak with King Magni Bronzebeard.",
    rewards = "9,650 XP • 2g 65s",
    tip = "Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!\n\n<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>\n\nReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.\n\nWhether he approves or not, it shall be.",
    isForever = false,
  },
  [4003] = {
    id = 4003,
    title = "The Royal Rescue",
    reqLevel = 48,
    questLevel = 59,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Thrall",
    objectives = "- Emperor Dagran Thaurissan",
    rewards = "8,050 XP",
    tip = "This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.\n\nPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.\n\nDO NOT HARM HER!",
    isForever = false,
  },
  [8323] = {
    id = 8323,
    title = "True Believers",
    reqLevel = 54,
    questLevel = 59,
    faction = "Both",
    zone = "Silithus",
    npc = "Hermit Ortell",
    objectives = "Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts",
    rewards = "6,400 XP • 90s",
    tip = "Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you.\n\nMy former organization has a secret encoded bulletin they circulate on a monthly basis.\n\nIf they make any progress searching for me or if they call off the search, word will be published on the True Believer.\n\nAlthough this information is obviously valuable to me, the publication contains other useful information that I can share.  Bring me any encoded texts you find on Twilight's Hammer member",
    isForever = false,
  },
  [8283] = {
    id = 8283,
    title = "Wanted - Deathclasp, Terror of the Sands",
    reqLevel = 54,
    questLevel = 59,
    faction = "Both",
    zone = "Silithus",
    npc = "Object: Wanted Poster: Deathclasp",
    objectives = "Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard.",
    rewards = "8,050 XP • 1g 80s",
    tip = "The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity.  She presents a great threat to patrols and expeditions in the southern regions.  Individuals participating in her destruction will be remunerated handsomely.  Inquire with Captain Vish Kozus, at the top of the Cenarion Hold Watchtower, regarding a reward.",
    isForever = false,
  },
  [4721] = {
    id = 4721,
    title = "Wild Guardians",
    reqLevel = 52,
    questLevel = 59,
    faction = "Horde",
    zone = "Felwood",
    npc = "Trull Failbane",
    objectives = "Trull Failbane in Felwood wants you to hunt 10 Berserk Owlbeasts in Winterspring.",
    rewards = "6,400 XP • 1g 80s",
    tip = "Runners have returned from Winterspring with reports that there is a series of small caves in the southern area of Winterspring. It seems that there are wildkin situated in the area around these caves. If there is something valuable that they are guarding, I believe that this is the place we will find it.\n\nYou will find these to be more of a challenge than the previous types, $N. The creatures seem to have gone mad from exposure to the very thing that they strive to protect.",
    isForever = false,
  },
  [5128] = {
    id = 5128,
    title = "Words of the High Chief",
    reqLevel = 52,
    questLevel = 59,
    faction = "Both",
    zone = "Winterspring",
    npc = "Donova Snowden",
    objectives = "Take the Crudely-written Log to Kelek Skykeeper in southern Felwood.",
    rewards = "6,400 XP",
    tip = "The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper.\n\nHe is part of a group known as the Emerald Circle, druids that are committed to their work in Felwood, healing the land from the corruption.\n\nKelek has much experience with the furbolgs in Felwood, and may be able to tell you more about the log.\n\nThank you, again, $N.",
    isForever = false,
  },
