  [8240] = {
    id = 8240,
    title = "A Bijou for Zanza",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Vinchaxa",
    objectives = "Destroy any one of the Hakkari Bijous found in Zul'Gurub at the Altar of Zanza on Yojamba Isle.  When done, speak with Vinchaxa nearby.",
    rewards = "6,600 XP • 1g 80s",
    tip = "The destruction of the various Hakkari Bijous is of grave importance to us, so much so that we welcome outsiders of the tribe to do so for themselves!\n\nTake any one of the bijous that you find in Zul'Gurub to the Altar of Zanza and destroy it.  For this one time alone, I will give you an additional Honor Token from our tribe; this is above and beyond what you would normally receive.\n\nWitness for yourself the blessings of Zanza!",
    isForever = false,
  },
  [7604] = {
