  [7486] = {
    id = 7486,
    title = "A Hero's Reward",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azshara",
    npc = "Duke Hydraxis",
    objectives = "Claim your reward from Hydraxis' Coffer.",
    rewards = "9,950 XP",
    tip = "$N, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.\n\nGo, $N.  Claim your reward.",
    isForever = false,
  },
  [9248] = {
    id = 9248,
    title = "A Humble Offering",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Aurel Goldleaf",
    objectives = "- Abyssal Scepter - Cenarion Circle:",
    rewards = "Experience & Faction Reputation",
    tip = "Ishnu-alah, $r. Show me proof of the demise of a Lord of the Abyssal Council and I shall reward you with an item that should aid you in your battles against the Qiraji.",
    isForever = false,
  },
  [9319] = {
    id = 9319,
    title = "A Light in Dark Places",
    reqLevel = 50,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Quest Event / Discovery",
    objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.",
    rewards = "4,950 XP",
    tip = "We are not the only ones who celebrate this holiday, $n. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.\n\nIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.",
    isForever = false,
  },
  [9386] = {
    id = 9386,
    title = "A Light in Dark Places",
    reqLevel = 50,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Quest Event / Discovery",
    objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.",
    rewards = "Experience & Faction Reputation",
    tip = "An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.\n\nSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, $n.",
    isForever = false,
  },
  [6606] = {
    id = 6606,
    title = "A Little Luck",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Harlo Wigglesworth",
    objectives = "Speak with Witch Doctor Mau'ari in Orgrimmar.",
    rewards = "660 XP",
    tip = "We can always use a little luck, eh? A small advantage is all it takes to turn things in your favor...\n\nI happened to make the acquaintance of a rather eccentric witch doctor some time back. She made me a lucky charm... for a price. Believe me, though, it was well worth it!\n\nMaybe you'd be interested in one of your own? Find Witch Doctor Mau'ari in Everlook. I'm not giving mine up!",
    isForever = false,
  },
  [8519] = {
    id = 8519,
    title = "A Pawn on the Eternal Board",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Object: Crystalline Tear",
    objectives = "- The War of the Shifting Sands",
    rewards = "6,600 XP",
    tip = "As you regain your composure and focus your gaze, you notice that something stirs within the crystal. Upon closer inspection, you realize that you are looking into the past... a memory... long forgotten.",
    isForever = false,
  },
  [8925] = {
    id = 8925,
    title = "A Portable Power Source",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Mux Manascrambler",
    objectives = "Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan.",
    rewards = "6,600 XP • 90s",
    tip = "Next we shall need to find a stable and portable source of energy to keep the ectoplasm active.  I've heard rumors of a mighty elemental called Magma Lord Bokk, whose heart is a powerful magma core - an endless supply of heat!\n\nIt's said he can be found in the Burning Steppes, south of Blackrock Mountain.  Bring the magma core to me and we shall have enough juice to power the extra-dimensional ghost revealer!",
    isForever = false,
  },
  [7635] = {
    id = 7635,
    title = "A Proper String",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Hunter Class Quests",
    npc = "Stoma the Ancient",
    objectives = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.",
    rewards = "9,950 XP",
    tip = "Vartrus may offer you the stave to create a bow of Ancients but only I can enchant the string required to complete the bow.\n\nIt is a simple task, puny one. Slay a mature black dragon and remove the sinew from its bones. Return that sinew to me and I shall enchant the material into an almost indestructible bow string.",
    isForever = false,
  },
  [5527] = {
    id = 5527,
    title = "A Reliquary of Purity",
    reqLevel = 56,
    questLevel = 60,
    faction = "Both",
    zone = "Moonglade",
    npc = "Rabine Saturna",
    objectives = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village.  If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.",
    rewards = "6,600 XP",
    tip = "The first step is to find a container capable of holding an extremely corruptible substance without the handler suffering ill effects.  There is only one sort device I am aware of that could possibly contain something as vile as the Felvine: a Reliquary of Purity.\n\nDeep in the wasteland of Silithus is the remnants of the night elf village known as Southwind.  I know one was there many, many years ago.  If we are to succeed, I need you to scour those ruins in the hopes of reclaiming it.",
    isForever = false,
  },
  [8928] = {
    id = 8928,
    title = "A Shifty Merchant",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Mux Manascrambler",
    objectives = "Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan.",
    rewards = "3,300 XP",
    tip = "The core will provide us with enough juice to power our device; now we just have to build a rod that can channel that energy without melting.\n\nI met an imp in Winterspring that sold all manner of exotic goods.  He had an elemental rod that would do perfectly.  I'm kicking myself in the head right now for not having bought it.\n\nHe lives inside a cave in the entrance to Darkwhisper Gorge.  Sneak in there and try to find him.\n\nMake sure he only charges you forty gold; that's the price he quoted me!",
    isForever = false,
  },
  [6984] = {
    id = 6984,
    title = "A Smokywood Pastures Thank You!",
    reqLevel = 30,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Kaymard Copperpinch",
    objectives = "Speak with Great-father Winter in Orgrimmar.",
    rewards = "4,950 XP",
    tip = "We at Smokywood Pastures appreciate the recovery of the stolen treats, $N.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!\n\nPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",
    isForever = false,
  },
  [7045] = {
    id = 7045,
    title = "A Smokywood Pastures Thank You!",
    reqLevel = 30,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Wulmort Jinglepocket",
    objectives = "Speak with Greatfather Winter in Ironforge.",
    rewards = "4,950 XP",
    tip = "We at Smokywood Pastures appreciate the recovery of the stolen treats, $N.  For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself!\n\nPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",
    isForever = false,
  },
  [8922] = {
    id = 8922,
    title = "A Supernatural Device",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Tanaris",
    npc = "Deliana",
    objectives = "Bring the Sealed Blood Container to Mux Manascrambler inside Gadgetzan in Tanaris.",
    rewards = "6,600 XP",
    tip = "I must find a way to speak with Anthion Harmon... or more specifically, his ghost!\n\nI know of an engineer with a queer interest in the supernatural.  He claims he can build a machine that allows him to speak with the dead!\n\nThe blood you collected was intended for him; travel to Gadgetzan and bring it to him as payment for his services!",
    isForever = false,
  },
  [8923] = {
    id = 8923,
    title = "A Supernatural Device",
    reqLevel = 58,
    questLevel = 60,
    faction = "Horde",
    zone = "Tanaris",
    npc = "Mokvar",
    objectives = "Take the Sealed Venom Container to Mux Manascrambler in Gadgetzan.",
    rewards = "6,600 XP",
    tip = "You must be quite brave to have stuck around after that.  That or I've piqued your interest with the piece of armor I gave you.  There is more from where that came from, if you're still interested in aiding me.\n\nThe venom samples you collected are for an acquaintance of mine, Mux Manascrambler, an engineer with an interest in the supernatural.  His latest project consists of a device that allows you to communicate with the dead!  My last hope is to contact Anthion and find out more about my situ",
    isForever = false,
  },
  [8287] = {
    id = 8287,
    title = "A Terrible Purpose",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Hermit Ortell",
    objectives = "Take the Decoded Tablet Parchment to Commander Mar'alith.",
    rewards = "6,600 XP • 1g 80s",
    tip = "Ok, here we are... a pretty valuable chunk of information, I must say!  I've seen the Cenarion Circle forces arrive at Silithus.  They plan to drive the Twilight's Hammer out, don't they?  This will help.  \n\nTake this parchment to their leader, Commander Mar'alith.  Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!",
    isForever = false,
  },
