  [171] = {
    id = 171,
    title = "A Warden of the Alliance",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Watcher Callahan",
    objectives = "Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District.",
    rewards = "1,650 XP",
    tip = "You have been so very kind to me, $N.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.  I don't wanna be sad about what's happened to me and all - my folks always told me to rise above anything bad that happens.  You know, when I grow up I wanna be a hero... just like you.\n\nI'm sad to say this, but it's time for me to go home.  Let's go back and I'll tell the matron what an awesome person you are!",
    isForever = false,
  },
  [5502] = {
    id = 5502,
    title = "A Warden of the Horde",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Orcish Orphan",
    objectives = "Return your ward to the Orgrimmar orphanage by handing in the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor.",
    rewards = "1,650 XP",
    tip = "You have been so very kind to me, $N.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.  I won't be sad about what's happened to me - my parents always told me to rise above anything bad that happens.  I'll be a hero... just like you.\n\nI'm sad to say this, but it's time for me to go home.  Let's go back and I'll tell the matron what an awesome person you are!",
    isForever = false,
  },
