  [5263] = {
    id = 5263,
    title = "Above and Beyond",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Duke Nicholas Zverenhoff",
    objectives = "- Head of Baron Rivendare",
    rewards = "8,300 XP",
    tip = "You display a natural aptitude for destruction and you follow orders. It is rare to see the two coexist. I am beginning to think that you may make an excellent vehicle of divine justice.\n\n<Zverenhoff clasps his hands together in front of his face.>\n\nKel'Thuzad's errand boy rules over Stratholme. Prove to me that you are a champion - my champion. Destroy Baron Rivendare and return to me with his head.",
    isForever = false,
  },
  [8361] = {
    id = 8361,
    title = "Abyssal Contacts",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Bor Wildmane",
    objectives = "Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.",
    rewards = "6,600 XP • 90s",
    tip = "We've seen the Twilight's Hammer cultists performing rituals to summon powerful elemental nobles.  We don't know if these are the beings the cultists worship or if they act as intermediaries to even more powerful forces.  One thing is for sure: they are receiving orders from these elementals.\n\nI want you to find a way to contact an Abyssal Templar and give it a proper beating!  Nothing throws the troops in disarray like taking out the chain of command.  Bring back proof while you're at it.",
    isForever = false,
  },
