  [6823] = {
    id = 6823,
    title = "Agent of Hydraxis",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azshara",
    npc = "Duke Hydraxis",
    objectives = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.",
    rewards = "9,950 XP",
    tip = "If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.\n\nThe campaign will be long, but if you persevere then your glory and honor will be great.",
    isForever = false,
  },
  [211] = {
    id = 211,
    title = "Alas, Andorhal",
    reqLevel = 50,
    questLevel = 60,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Commander Ashlam Valorfist",
    objectives = "Bring Araj's Phylactery Shard to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.",
    rewards = "8,300 XP",
    tip = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nInside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully.\n\nDestroy Araj, $N, and bring me a shard from his phylactery as proof!",
    isForever = false,
  },
  [9338] = {
    id = 9338,
    title = "Allegiance to Cenarion Circle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Windcaller Kaldon",
    objectives = "- Cenarion Combat Badge - Cenarion Logistics Badge - Cenarion Tactical Badge",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [7362] = {
    id = 7362,
    title = "Ally of the Tauren",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "You have been tasked with slaying opposing gnome players in Alterac Valley.\n\nKill a gnome and return to Ravak Grimtotem at Frostwolf Keep with a Tuft of Gnome Hair.",
    rewards = "6,600 XP, 1g 80s",
    tip = "The Elder Crone has sent me to this warzone to research the other races. More specifically, I am to collect gnome samples. Magatha is primarily interested in their survivability. Aye, the gnomes - while pitifully weak and miniscule - exude great resilience both in and out of combat.\n\nFortunately for you, I am looking for ruffians to do Magatha's bidding. Return to me with tufts of gnome hair and you shall be known to the tauren as an ally.",
    isForever = false,
  },
  [7081] = {
    id = 7081,
    title = "Alterac Valley Graveyards",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Sergeant Durgen Stormpike",
    objectives = "Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",
    rewards = "6,600 XP",
    tip = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, $N, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.",
    isForever = false,
  },
  [8905] = {
    id = 8905,
    title = "An Earnest Proposition",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Deliana",
    objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge.",
    rewards = "6,600 XP",
    tip = "Well met, $c.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while",
    isForever = false,
  },
