  [8303] = {
    id = 8303,
    title = "Anachronos",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Baristolth of the Shifting Sands",
    objectives = "Seek out Anachronos at the Caverns of Time in Tanaris.",
    rewards = "Experience & Faction Reputation",
    tip = "It is time, $N.\n\nI must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master.",
    isForever = false,
  },
  [7643] = {
    id = 7643,
    title = "Ancient Equine Spirit",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Lord Grayson Shadowbreaker",
    objectives = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it.",
    rewards = "4,950 XP",
    tip = "Your barding needs a special form of blessing, one from an appropriate spirit.  In Dire Maul is such a spirit, the Ancient Equine Spirit.  It is currently held by a corrupt treant, Tendris Warpwood.  Pass judgment upon this foul beast, $N.\n\nKnow this - freedom alone is not enough.  You must soothe the spirit before receiving its blessing.  For that, special horse feed is needed.  Travel to Southshore first and speak with Merideth Carlson on this... and prepare for more sacrifice.",
    isForever = false,
  },
  [7634] = {
    id = 7634,
    title = "Ancient Sinew Wrapped Lamina",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Hunter Class Quests",
    npc = "Hastat the Ancient",
    objectives = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.",
    rewards = "9,950 XP",
    tip = "Greetings, $c. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.\n\nWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.\n\nReturn here with sinew from an adult blue dragon and this quiver shall be yours.",
    isForever = false,
  },
  [8192] = {
    id = 8192,
    title = "Animist's Caress",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Zul'Gurub",
    npc = "Zanza the Restless",
    objectives = "Bring me all three and I will create a powerful enchantment for you!",
    rewards = "Experience & Faction Reputation",
    tip = "Zanza can create the ancient troll enchantments with the right components. The first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo.\n\nBring me these things and I will create a powerful enchantment for you!",
    isForever = false,
  },
  [8948] = {
    id = 8948,
    title = "Anthion's Old Friend",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Anthion Harmon",
    objectives = "Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul.",
    rewards = "6,600 XP",
    tip = "Theldren is not one to willingly participate in a fair fight.  I've shaped this banner to display his family colors.\n\nWith some additional sorcery, this banner shall provoke him in a way he won't be able to resist.\n\nAn old acquaintance of mine named Falrin knows the exact procedure required.  He has a particular way of... aggravating people.  You shall find him at the library in Dire Maul.",
    isForever = false,
  },
  [8951] = {
    id = 8951,
    title = "Anthion's Parting Words",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Anthion Harmon",
    objectives = "Return to Deliana in Ironforge with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders.",
    rewards = "9,950 XP",
    tip = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",
    isForever = false,
  },
