  [9024] = {
    id = 9024,
    title = "Aristan's Hunch",
    reqLevel = 1,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Aristan Mottar",
    objectives = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Morgan Pestle in the Trade District of Stormwind.",
    rewards = "Experience & Faction Reputation",
    tip = "I've got it! Have you smelled the new fragrance on the wind? The new colognes and perfumes that have come into fashion? Our guards wouldn't neglect their duties so easily.\n\nThat is, unless their thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to Morgan Pestle, and tell him my suspicions. I will reimburse you for their purchase when you return.",
    isForever = false,
  },
