  [6601] = {
    id = 6601,
    title = "Ascension...",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Emberstrife",
    objectives = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.",
    rewards = "4,950 XP",
    tip = "From the skulls of our enemies is shaped a medallion. You know this medallion, yesss? You have no doubt seen it worn by your elders.\n\nTake it, whelp. Return to the Spire and present it to General Drakkisath. The General will place the final enchantment upon the medallion, attuning the trinket to your spirit.\n\nYou will wear the finished medallion as a badge of honor, symbolizing your ascension to one of our most guarded ranks: Guardian to the brood mother.\n\nGo!",
    isForever = false,
  },
  [9257] = {
    id = 9257,
    title = "Atiesh, Greatstaff of the Guardian",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Mining",
    npc = "Anachronos",
    objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",
    rewards = "14,300 XP",
    tip = "This final task will be the most difficult of all, $N. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return t",
    isForever = false,
  },
