  [9251] = {
    id = 9251,
    title = "Atiesh, the Befouled Greatstaff",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Mining",
    npc = "Anachronos",
    objectives = "Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh.",
    rewards = "6,600 XP",
    tip = "You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, $N. I only do as I must.\n\nKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.\n\nAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.\n\nShould you succeed in recovering the pieces, return them to me.",
    isForever = false,
  },
  [7848] = {
    id = 7848,
    title = "Attunement to the Core",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Molten Core",
    npc = "Lothos Riftwaker",
    objectives = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.",
    rewards = "6,600 XP",
    tip = "Rifts stir, tear, and collapse all around us, $r. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the po",
    isForever = false,
  },
  [106] = {
    id = 106,
    title = "Attunement to the Temporal Rift",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
