    isForever = true,
  },
  [8331] = {
    id = 8331,
    title = "Aurel Goldleaf",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Huum Wildmane",
    objectives = "Speak with Aurel Goldleaf in Cenarion Hold.",
    rewards = "650 XP",
    tip = "$N, although we had hoped the Twilight's Hammer's operations in Silithus were slowing... we were, regrettably, mistaken.  Through continued forays against the cult, we have learned that an even darker power, the Abyssal Council, controls the Hammer through the arcane wind stones dotted amongst the cult's camps.  Your next action, $N, will be against the Abyssal Council.\n\nSpeak with the craftsman Aurel Goldleaf, in the eastern section of Cenarion Hold.  Her skill will be needed for this next gamb",
    isForever = false,
  },
