  [4621] = {
    id = 4621,
    title = "Avast Ye, Admiral!",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "Fleet Master Firallon",
    objectives = "Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale.",
    rewards = "9,950 XP",
    tip = "Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o' plunder.  Were ye to put a knife to Fleet Master Seahorn, we'd ne'er run afoul of a Booty Bay's vessel.  Were ye to put a knife to Baron Revilgaz, we'd ne'er face the law on their terms.\n\nIf ye are to be an honorary admiral amongst us - yes, ADMIRAL, you'll puts a knife to both of 'em as I've says.  Go now $g lad : lass;, and return to me once ye does the",
    isForever = false,
  },
  [1036] = {
    id = 1036,
    title = "Avast Ye, Scallywag",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stranglethorn Vale",
    npc = "\"Pretty Boy\" Duncan",
    objectives = "Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.",
    rewards = "650 XP",
    tip = "$N... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty $g men : women; just like you for a special mission.\n\nIf you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.",
    isForever = false,
  },
  [8627] = {
    id = 8627,
    title = "Avenger's Breastplate",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ahn'Qiraj",
    npc = "Vethsera",
    objectives = "Bring the the Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",
    isForever = false,
  },
  [8628] = {
    id = 8628,
    title = "Avenger's Crown",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ahn'Qiraj",
    npc = "Andorgos",
    objectives = "Bring Vek'lor's Diadem, 2 Idols of Rebirth, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, $N.  I will give you a headpiece of unmatched power.",
    isForever = false,
  },
  [8655] = {
    id = 8655,
    title = "Avenger's Greaves",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ahn'Qiraj",
    npc = "Kandrostrasz",
    objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs and 5 Clay Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",
    rewards = "9,950 XP",
    tip = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of dominance and other minor components and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.",
    isForever = false,
  },
  [8629] = {
    id = 8629,
    title = "Avenger's Legguards",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ahn'Qiraj",
    npc = "Kandrostrasz",
    objectives = "Bring the Skin of the Great Sandworm, 2 Idols of Strife, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",
    isForever = false,
  },
  [8630] = {
    id = 8630,
    title = "Avenger's Pauldrons",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ahn'Qiraj",
    npc = "Andorgos",
    objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of Life, 5 Crystal Scarabs and 5 Gold Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",
    isForever = false,
  },
  [8737] = {
    id = 8737,
    title = "Azure Templar",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Item: Tactical Task Briefing I",
    objectives = "Summon and slay an Azure Templar and report back to Bor Wildmane in Cenarion Hold.  You must also bring Tactical Task Briefing I in order to complete this quest.",
    rewards = "650 XP",
    tip = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Azure Templar and report to Bor Wildmane.",
    isForever = false,
  },
  [8575] = {
    id = 8575,
    title = "Azuregos's Magical Ledger",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azshara",
    npc = "Item: Magical Ledger",
    objectives = "Deliver Azuregos's Magical Ledger to Narain Soothfancy in Tanaris.",
    rewards = "6,600 XP",
    tip = "You cannot understand a single word on this ledger. You don't even know what language it is written in!",
    isForever = false,
  },
  [8997] = {
    id = 8997,
    title = "Back to the Beginning",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Bodley",
    objectives = "Speak with Deliana at The High Seat in Ironforge.",
    rewards = "650 XP",
    tip = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Deliana in Ironforge and tell her what's happened.",
    isForever = false,
  },
  [8998] = {
