  [5341] = {
    id = 5341,
    title = "Barov Family Fortune",
    reqLevel = 52,
    questLevel = 60,
    faction = "Horde",
    zone = "Scholomance",
    npc = "Alexi Barov",
    objectives = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.",
    rewards = "6,600 XP • 1g 80s",
    tip = "Within the Scholomance lays the Barov family fortune. I, Alexi Barov, am one of the last two remaining heirs of the house Barov. My brother, Weldon, is the other.\n\nWeldon, the miserable coward, fled during the war and thus retained his worthless existence as a human.\n\nHe now searches for the deeds so that he may claim the fortune for his own. Recover the deeds before my brother does and I shall make you wealthy beyond your wildest dreams!",
    isForever = false,
  },
  [5343] = {
    id = 5343,
    title = "Barov Family Fortune",
    reqLevel = 52,
    questLevel = 60,
    faction = "Alliance",
    zone = "Scholomance",
    npc = "Weldon Barov",
    objectives = "- The Deed to Brill - The Deed to Caer Darrow - The Deed to Southshore - The Deed to Tarren Mill",
    rewards = "6,600 XP, 1g 80s",
    tip = "My dear brother Alexi. What a fool I was to spare his life. I looked into the face of the enemy, one of the undead, and let him live.\n\n<Weldon spits.>\n\nHe now searches for MY inheritance. This simply cannot happen.\n\nFind my family's deeds before that vile retch gets his boney hands upon them and I shall reward you with vast riches. They lay in the ruins of the Scholomance. Make haste!",
    isForever = false,
  },
  [8430] = {
    id = 8430,
    title = "Battle of Warsong Gulch",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "6,600 XP • 90s",
    tip = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!",
    isForever = false,
  },
  [8435] = {
