  [7626] = {
    id = 7626,
    title = "Bell of Dethmoora",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Mor'zul Bloodbringer",
    objectives = "Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes.",
    rewards = "6,600 XP",
    tip = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.\n\nMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki.",
    isForever = false,
  },
