  [9117] = {
    id = 9117,
    title = "Belt of Faith",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Father Inigo Montoy",
    objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make a Belt of Faith if you bring him the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth.",
    rewards = "Experience & Faction Reputation",
    tip = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    isForever = false,
  },
  [5531] = {
    id = 5531,
    title = "Betina Bigglezink",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Scholomance",
    npc = "Leonid Barthalomew the Revered",
    objectives = "Bring the Frozen Eggs to Betina Bigglezink.",
    rewards = "1,650 XP",
    tip = "The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.\n\nNow, it is time we ended their research.\n\nTake the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow.",
    isForever = false,
  },
  [7892] = {
