    isForever = false,
  },
  [9131] = {
    id = 9131,
    title = "Binding the Dreadnaught",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Korfax, Champion of the Light",
    objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants 30 Dark Iron Scraps.",
    rewards = "6,600 XP",
    tip = "Have you ever seen Dreadnaught armor, $c? No, of course you haven't. You're still a $g boy:girl; - a tyke. Let me tell you, it is glorious.\n\nYou're probably asking yourself what any of this has to do with you, right? I'll tell you what, scrub; I need Dark Iron scraps and I'm willing to pay to get my hands on as many as possible.\n\nI need the scraps to put together sets of Dreadnaught for our champions. Bring me scraps and get paid.",
    isForever = false,
  },
  [9118] = {
    id = 9118,
    title = "Bindings of Faith",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Father Inigo Montoy",
    objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make Bindings of Faith if you bring him the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal.",
    rewards = "Experience & Faction Reputation",
    tip = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    isForever = false,
  },
  [7761] = {
    id = 7761,
    title = "Blackhand's Command",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Item: Blackhand's Command",
    objectives = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\n\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.",
    rewards = "6,600 XP",
    tip = "Imbecile,\n\nI hold very little faith in your ability to prevent outsiders from accessing the master's lair. In the very likely event of your death, this orb has its own failsafe built in to prevent outsiders from teleporting directly into Blackwing.\n\nOnly those with the Mark of Drakkisath branded upon their hand may make use of this orb. Thankfully, Drakkisath is not nearly as incompetent as you, Quartermaster. He guards the brand himself!\n\n-Warchief Rend Blackhand\n\nP.S. Destroy this letter, idio",
    isForever = false,
  },
  [8711] = {
    id = 8711,
    title = "Blade of Eternal Justice",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ahn'Qiraj",
    npc = "Warden Haro",
    objectives = "Bring 1 Qiraji Spiked Hilt, 2  Amber Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",
    isForever = false,
  },
