  [7644] = {
    id = 7644,
    title = "Blessed Arcanite Barding",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Ancient Equine Spirit",
    objectives = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",
    rewards = "Experience & Faction Reputation",
    tip = "As the barding rests on the back of the Ancient Equine Spirit, it glows ever so slightly.  The air is thick with power for a brief moment, and then the barding disappears from the back of the horse and is now secure in your backpack.\n\nIt would seem that the barding has been blessed.  As per Lord Shadowbreaker's instructions, you should now return with it to him in Stormwind.",
    isForever = false,
  },
  [6602] = {
    id = 6602,
    title = "Blood of the Black Dragon Champion",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Rexxar",
    objectives = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.",
    rewards = "9,950 XP",
    tip = "How would you feel about paying a visit to the General? No illusions, this time.\n\nCeremony? A pretty word to describe the bloodletting that amuses the Black Dragonflight.\n\nAll this amulet requires is the blood of General Drakkisath. Primitive security. There are other ways to receive the General's blood.\n\nGo to Blackrock Spire and kill Drakkisath. Return with his blood and I will activate the key to Onyxia's lair.",
    isForever = false,
  },
