  [8960] = {
    id = 8960,
    title = "Bodley's Unfortunate Fate",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Blackrock Mountain",
    npc = "Deliana",
    objectives = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire.",
    rewards = "1,650 XP",
    tip = "So we need to recover the rest of the medallion?  Finding Bodley's going to be a bit of a headache.  He went back to Blackrock Mountain to attempt to re-enter Blackrock Spire and never came back.\n\nI'd suggest taking the goblin's ghost revealing device with you, as I fear the worst might have happened.",
    isForever = false,
  },
  [9032] = {
    id = 9032,
    title = "Bodley's Unfortunate Fate",
    reqLevel = 58,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Mountain",
    npc = "Mokvar",
    objectives = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire.",
    rewards = "1,650 XP",
    tip = "The medallion contained Valthalak's soul?  It's no surprise it was guarded by such a powerful curse.\n\nLocating Bodley presents a bit of a problem.  Last time I heard of him, he was preparing to venture back into Blackrock Spire.  He was never heard of again.\n\nSeek him out in Blackrock Mountain, though I'm afraid to say he's probably dead by now.  I suggest taking the goblin's device with you, friend.",
    isForever = false,
  },
  [9665] = {
    id = 9665,
    title = "Bolstering Our Defenses",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Emmisary Gormok",
    objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.",
    rewards = "6,600 XP • 90s",
    tip = "Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.\n\nIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.",
    isForever = false,
  },
