  [8349] = {
    id = 8349,
    title = "Bor Wildmane",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Aurel Goldleaf",
    objectives = "Speak with Bor Wildmane in Cenarion Hold.",
    rewards = "650 XP",
    tip = "Now that you have a medallion and can summon an Abyssal Duke, speak with Bor Wildmane.  He will set you on a task against the Abyssal Council.\n\nGood luck, $N.  And if you ever need more medallions, return to me.",
    isForever = false,
  },
  [8351] = {
    id = 8351,
    title = "Bor Wishes to Speak",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Aurel Goldleaf",
    objectives = "Speak with Bor Wildmane in Cenarion Hold.",
    rewards = "650 XP",
    tip = "Now that you can disguise yourself as a ruling member of the Twilight Council, I am certain Bor Wildmane will want to speak with you.  Go see him, and prepare yourself for a very difficult mission...",
    isForever = false,
  },
  [8308] = {
    id = 8308,
    title = "Brann Bronzebeard's Lost Letter",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Item: Brann Bronzebeard's Lost Letter",
    objectives = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus.",
    rewards = "8,300 XP",
    tip = "To Whom It May Concern:\n\nIf you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow.\n\nFound information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it.\n\nTake this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs.\n\n-Brann Bronzebeard, Explorer Extreme\n\nP.S. Watch out for crazy Old God worshipping night elf.",
    isForever = false,
  },
  [8310] = {
    id = 8310,
    title = "Breaking the Code",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Frankal Stonebridge",
    objectives = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task.",
    rewards = "8,300 XP • 1g 80s",
    tip = "I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! What do I need? Glad you asked! I need brains! More specifically, a brain from each silithid type that inhabit the hives. Bring me brains and Rutgar's work might not be for naught.",
    isForever = false,
  },
  [5068] = {
    id = 5068,
    title = "Breastplate of Bloodthirst",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Object: Malyfous's Catalogue",
    objectives = "In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.\n\nYou will also be required to pay 50 gold pieces for the crafting of the item.",
    rewards = "Experience & Faction Reputation",
    tip = "It is said that only one Breastplate of Bloodthirst has ever been created and that it was made for the legendary assassin, Garona. Whether this world will ever see another is doubtful.\n\nRegardless! Our master crafters can reproduce the item given the necessary components:\n\n*The pristine hide of the Beast.\n\n*Frayed abomination stitchings.\n\n*Arcanite bars.\n\n*The skin of shadow.\n\nBEHOLD!",
    isForever = false,
  },
  [5166] = {
    id = 5166,
    title = "Breastplate of the Chromatic Flight",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Object: Catalogue of the Wayward",
    objectives = "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':\n\n1 Chromatic Carapace.\n\n10 Brilliant Chromatic Scales.\n\n10 Blood of Heroes.\n\n10 Frayed Abomination Stitchings.",
    rewards = "9,950 XP",
    tip = "The forging of a powerful breastplate to protect against the unrelenting attacks of the chromatic flight is one built upon irony.\n\nThe scales of the very beasts we battle must be sewn to the pristine carapace of an elder chromatic drake or dragon. None are known to exist at this time and we should hope that none will ever exist.\n\nLastly, perhaps the most difficult of all components: the blood of heroes.\n\nThe Sculptor must ultimately forge this creation.",
    isForever = false,
  },
  [8726] = {
    id = 8726,
    title = "Brightspear the Elder",
    reqLevel = 1,
