    isForever = false,
  },
  [7281] = {
    id = 7281,
    title = "Brotherly Love",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Commander Louis Philips",
    objectives = "- Commander Karl Philips",
    rewards = "6,600 XP",
    tip = "Tragic... My brother faces me on the field of battle: A commander for the Stormpike.\n\nOf the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways...\n\nDeep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier.\n\nAnd soldier, do not go alone.",
    isForever = false,
  },
  [7282] = {
    id = 7282,
    title = "Brotherly Love",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Commander Karl Philips",
    objectives = "- Commander Louis Philips",
    rewards = "6,600 XP",
    tip = "He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen.\n\nVenture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.",
    isForever = false,
  },
  [8801] = {
    id = 8801,
    title = "C'Thun's Legacy",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Item: Eye of C'Thun",
    objectives = "Take the Eye of C'Thun to Caelastrasz in the Temple of Ahn'Qiraj.",
    rewards = "9,950 XP",
    tip = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, has been destroyed.\n\nAs you look at the remnants of the colossal abomination your heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around you.\n\nYou have done what was thought to be impossible.\n\nYou grab at an eye stalk of the fiend, stowing it safely in your pack.\n\nTake the Eye of C'Thun to the dragons in the next chamber.",
    isForever = false,
  },
  [975] = {
    id = 975,
    title = "Cache of Mau'ari",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Witch Doctor Mau'ari",
    objectives = "Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm.",
    rewards = "Experience & Faction Reputation",
    tip = "Now, before I give ya dis charm, I better explain how ta use it.\n\nIf you carry da charm with ya, you'll find dat certain items will drop from creatures ya fight. If you don't have da charm with you, you won't find them. Understand?\n\nYou'll know these special items by the name -- they be called E'ko. If you find any of these items, just bring dem to ol' Mau'ari, and she help ya out.\n\nWait here while I fix your charm.",
    isForever = false,
  },
  [925] = {
    id = 925,
    title = "Cairne's Hoofprint",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Orcish Orphan",
    objectives = "Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward.",
    rewards = "650 XP",
    tip = "They say that Cairne Bloodhoof is one of the greatest heroes the Horde has ever seen.  When I grow up, I wanna be a hero of the Horde too!\n\nDo you know Cairne, $N?  Could you do me a favor, please?  Could you get his hoofprint for me?  I dunno how to ask him, and he'd probably be too busy for someone like me... but you!  You're an adventurer just like he is!  I bet he'd give you his hoofprint easy!\n\nPlease?",
    isForever = false,
  },
