  [5063] = {
    id = 5063,
    title = "Cap of the Scarlet Savant",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Object: Malyfous's Catalogue",
    objectives = "In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread. \n\nYou will also be required to pay 50 gold pieces for the crafting of the item.",
    rewards = "Experience & Faction Reputation",
    tip = "A finer cap you may never see. From the pristine hide of the beast, our expert crafters will create the most phenomenal hat a prestidigitator could ever hope to don!\n\nFifty gold pieces along with the listed items and your head shall be graced with the Cap of the Scarlet Savant:\n\n*The pristine hide of the Beast.\n\n*Frayed abomination stitchings.\n\n*Arcane crystals.\n\n*Enchanted scarlet thread.\n\nBEHOLD!",
    isForever = false,
  },
  [8695] = {
    id = 8695,
    title = "Cape of Eternal Justice",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ahn'Qiraj",
    npc = "Keyl Swiftclaw",
    objectives = "Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.",
    isForever = false,
  },
  [7122] = {
    id = 7122,
    title = "Capture a Mine",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Sergeant Durgen Stormpike",
    objectives = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",
    rewards = "6,600 XP",
    tip = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!",
    isForever = false,
  },
  [7124] = {
