  [8353] = {
    id = 8353,
    title = "Chicken Clucking for a Mint",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Innkeeper Firebrew",
    objectives = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!",
    rewards = "Experience & Faction Reputation",
    tip = "Ah, trick-or-treating for a sick child, are we?  I was going to say, you're a little old to be rummaging about for candies...\n\nWell, for my treat - an Ironforge Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me!\n\nWell $c, are you up to the challenge or not?!  Time to earn your treat!",
    isForever = false,
  },
  [8354] = {
