  },
  [172] = {
    id = 172,
    title = "Children's Week",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Ambassador Berrybuck",
    objectives = "Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.",
    rewards = "2,350 XP, 25s",
    tip = "You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.\n\nBy all means $N - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.",
    isForever = false,
  },
