  [8396] = {
    id = 8396,
    title = "Claiming Arathi Basin",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "6,600 XP • 90s",
    tip = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Bas",
    isForever = false,
  },
  [8398] = {
    id = 8398,
    title = "Claiming Arathi Basin",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "3,300 XP",
    tip = "Winning a war is about more than just outsmarting and outfighting your opponent. Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops. If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us! Now is the time to help the Alliance in Arathi Basin,",
    isForever = false,
  },
