  [5893] = {
    id = 5893,
    title = "Coldtooth Supplies",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Frostwolf Quartermaster",
    objectives = "Bring 10 Coldtooth Supplies to the Horde Quatermaster in Frostwolf Keep.",
    rewards = "Experience & Faction Reputation",
    tip = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens...\n\nBut we still need our supplies, $N!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...",
    isForever = false,
  },
  [6982] = {
    id = 6982,
    title = "Coldtooth Supplies",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Stormpike Quartermaster",
    objectives = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.",
    rewards = "Experience & Faction Reputation",
    tip = "The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.\n\nEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.\n\nGood luck, $N.  The mine is to the distant south, deep in Horde territory.",
    isForever = false,
  },
  [7642] = {
    id = 7642,
    title = "Collection of Goods",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Grimand Elmore",
    objectives = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind.",
    rewards = "1,650 XP",
    tip = "You'll need four things for the barding - runecloth for the lining, arcanite bars for the plating, Arthas' Tears for the spiritual attunement, and Stratholme holy water for the spiritual imbuement.  Actually, you need five things... gold for my fee.  That fee includes all labor as well as a handcrafted saddle and stirrups.\n\nOnce you've got all that, I'll be able to finish your barding.  Until then, there are some things I can get started on for you while you assemble your collection of goods.",
    isForever = false,
  },
  [8962] = {
    id = 8962,
    title = "Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.",
    isForever = false,
  },
  [8963] = {
    id = 8963,
    title = "Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.",
    isForever = false,
  },
  [8964] = {
    id = 8964,
    title = "Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.",
    isForever = false,
  },
  [8965] = {
    id = 8965,
    title = "Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.",
    isForever = false,
  },
  [8371] = {
    id = 8371,
    title = "Concerted Efforts",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Alterac Valley Mark of Honor, 3 Arathi Basin Mark of Honor and 3 Warsong Gulch Mark of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "8,300 XP • 2g 70s",
    tip = "We're not fighting isolated battles against the Horde anymore, $g lad:lass;.\n\nVictory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, losing any given battle could give the advantage to our opponent somewhere else around the world.\n\nThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  $N, come back to me after you've served against the Horde at all of our active battleground",
    isForever = false,
  },
  [8385] = {
    id = 8385,
    title = "Concerted Efforts",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Alterac Valley Mark of Honor, 3 Arathi Basin Mark of Honor and 3 Warsong Gulch Mark of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "6,600 XP",
    tip = "Ah, $N. I hope you continue to lend your experience to the different battlefronts. A lot of our lads and lasses in the field look up to seasoned veterans like you.",
    isForever = false,
  },
  [8439] = {
    id = 8439,
    title = "Conquering Arathi Basin",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "6,600 XP • 90s",
    tip = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $N!",
    isForever = false,
  },
  [8443] = {
    id = 8443,
    title = "Conquering Arathi Basin",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "3,300 XP",
    tip = "Our conflict with the Alliance has escalated to a true war. No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple. Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going. Help the Defilers maintain the flow of resources we need, $N!",
    isForever = false,
  },
  [8562] = {
    id = 8562,
    title = "Conqueror's Breastplate",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Vethsera",
    objectives = "Bring the the Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",
    isForever = false,
  },
  [8561] = {
    id = 8561,
    title = "Conqueror's Crown",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Andorgos",
    objectives = "Bring Vek'nilash's Circlet, 2 Idols of the Sun, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, $N.  I will give you a headpiece of unmatched power.",
    isForever = false,
  },
  [8559] = {
    id = 8559,
    title = "Conqueror's Greaves",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Kandrostrasz",
    objectives = "Bring the Qiraji Bindings of Command, 2 Idols of War, 5 Ivory Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",
    rewards = "9,950 XP",
    tip = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.",
    isForever = false,
  },
  [8560] = {
    id = 8560,
    title = "Conqueror's Legguards",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Kandrostrasz",
    objectives = "Bring Ouro's Intact Hide, 2 Idols of Death, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",
    isForever = false,
  },
  [8544] = {
    id = 8544,
    title = "Conqueror's Spaulders",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Andorgos",
    objectives = "Bring the Qiraji Bindings of Command, 2 Idols of Night, 5 Stone Scarabs and 5 Clay Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",
    isForever = false,
  },
  [9317] = {
    id = 9317,
    title = "Consecrated Sharpening Stones",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
