  [8115] = {
    id = 8115,
    title = "Control Five Bases",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Field Marshal Oslight",
    objectives = "Control 5 bases in Arathi Basin at the same time, then return to Field Marshal Oslight at Refuge Pointe.",
    rewards = "9,950 XP • 2g 70s",
    tip = "$N, battling for the resources of Arathi Basin is a bloody undertaking.  Your services to the League of Arathor are as needed as they are appreciated.\n\nAnd we have one more task for you.\n\nThe League wishes to make one strong push against the Defilers' occupation of Arathi Basin.  We want them driven out of every strategic point on the battlefield!\n\nIt will not be easy, but if anyone can get it done, it is you.",
    isForever = false,
  },
  [8114] = {
    id = 8114,
    title = "Control Four Bases",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Arathi Basin",
    npc = "Field Marshal Oslight",
    objectives = "Enter Arathi Basin, capture and control four bases at the same time, and then return to Field Marshal Oslight at Refuge Pointe.",
    rewards = "9,950 XP • 2g 70s",
    tip = "$N, you have taken the battle of Arathi Basin to our enemies and earned great honors in that field of battle.  You have shown us your worth as a $c, and you have shown our enemies that we will not submit to their villainy!\n\nBecause of your proven value to us, I have a difficult task for you.  I want you to take and hold at least four of the bases in Arathi Basin.  If you can do that, then we will not only secure critical resources, we will show the Horde our dominance!\n\nGo, $N, and good fortune.",
    isForever = false,
  },
