  [5307] = {
    id = 5307,
    title = "Corruption",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Seril Scourgebane",
    objectives = "Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane.",
    rewards = "8,300 XP",
    tip = "If I am short with you, it is for a reason. The plans for the creation of the great blade, Corruption, have been stolen by the Black Guard: Elite skeletal units of Baron Rivendare.\n\nYes, Baron Rivendare of Stratholme.\n\nThe Black Guard swordsmith now guards those plans with his... undeath.\n\nSlay him and return proof of this deed and I shall grant you the knowledge required to create a blazing rapier!",
    isForever = false,
  },
