  [1658] = {
    id = 1658,
    title = "Crashing the Wickerman Festival (PvP)",
    reqLevel = 25,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Sergeant Hartman",
    objectives = "Locate the Forsaken's Wickerman Festival in Tirisfal Glade.  Return to Sergeant Hartman in Southshore once you've done so.",
    rewards = "6,600 XP • 90s",
    tip = "I need brave individuals to head up to Tirisfal Glade and check out the Wickerman Festival.  I'm not going to lie - heading up there will be dangerous.  The guards at the festival will be exceptionally vicious.  Still, we need to know how big the festival is this year, and how much trouble the Forsaken are going to cause us during Hallow's End.\n\nIf you're up for it, head to Tirisfal and scout out the festival.  Return to me with the information, and I'll make sure you're well compensated.",
    isForever = false,
  },
  [8537] = {
