    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Huntsman Leopold",
    objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make Cryptstalker Boots if you bring him the following: 1 Desecrated Boots, 12 Wartorn Chain Scraps, 1 Arcanite Bar and 3 Nexus Crystals.",
    rewards = "Experience & Faction Reputation",
