  [7386] = {
    id = 7386,
    title = "Crystal Cluster",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Arch Druid Renferal",
    objectives = "null",
    rewards = "Experience & Faction Reputation",
    tip = "There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf's storm crystals.\n\nThe Circle accepts such offerings, $N.",
