  [8299] = {
    id = 8299,
    title = "Cut Arathor Supply Lines",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathstalker Mortis",
    objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
    rewards = "6,600 XP • 2g 70s",
    tip = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",
    isForever = false,
  },
  [9378] = {
    id = 9378,
    title = "DND FLAG The Dread Citadel - Naxxramas",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Quest Event / Discovery",
    objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.",
    rewards = "",
    tip = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.",
    isForever = false,
  },
  [8709] = {
    id = 8709,
    title = "Dagger of Veiled Shadows",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Warden Haro",
    objectives = "Bring 1 Qiraji Spiked Hilt, 2  Vermillion Idols, 5 Gold Scarabs and 5 Clay Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",
    isForever = false,
  },
  [8357] = {
    id = 8357,
    title = "Dancing for Marzipan",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Innkeeper Saelienne",
    objectives = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!",
    rewards = "Experience & Faction Reputation",
    tip = "Even though you're trick-or-treating for a sick child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!",
    isForever = false,
  },
  [8360] = {
    id = 8360,
    title = "Dancing for Marzipan",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Innkeeper Pala",
    objectives = "Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!",
    rewards = "Experience & Faction Reputation",
    tip = "Even though you're trick-or-treating for a sick child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!",
