  },
  [8903] = {
    id = 8903,
    title = "Dangerous Love",
    reqLevel = 1,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Aristan Mottar",
    objectives = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind.",
    rewards = "Experience & Faction Reputation",
    tip = "There's something unnatural about this epidemic of love. It's not proper, it's an eyesore, and at worst, it could be a threat to the the safety of the Alliance itself.\n\nJust think: what if the guards have been taken in by this strange affliction? Something must be done.\n\nGo to one of the guards here in Stormwind and see if they've been caught up in this foolishness.",
    isForever = false,
  },
  [8904] = {
    id = 8904,
    title = "Dangerous Love",
    reqLevel = 1,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Fenstad Argyle",
    objectives = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.",
    rewards = "Experience & Faction Reputation",
    tip = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.",
    isForever = false,
  },
