    title = "Defiler's Advanced Care Package",
    reqLevel = 45,
    questLevel = 60,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Rutherford Twing",
    objectives = "- The Defilers:",
    rewards = "650 XP",
