  [7367] = {
    id = 7367,
    title = "Defusing the Threat",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Stormpike Explosives Expert",
    objectives = "Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete.",
    rewards = "6,600 XP • 57s 30c",
    tip = "The Frostwolf have their front lines and bases booby trapped, $c. You have to watch your step when invading enemy territory.\n\nIf you want to make a solid strike against them, you must destroy their source of anti personnel munitions - I'm talking about their explosives expert. If you kill him, you are safe to disarm the mines. As long as he is kept down, the mines will also stay down.\n\nYou will probably find him in a tower near the Iceblood Garrison. Good luck!",
    isForever = false,
  },
  [7368] = {
    id = 7368,
    title = "Defusing the Threat",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Frostwolf Explosives Expert",
    objectives = "Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete.",
    rewards = "6,600 XP",
    tip = "I know all about landmines. I'm the one that lays all the mines on the front lines here, after all.\n\nIf you want to defuse the Stormpike mine fields, all you have to do is kill their explosives expert. That dwarven coward is no doubt hiding in the first tower on the Field of Strife. Take him out and those landmines won't come back after they've been disarmed.\n\nIf you do happen to kill him, come back here and let me know. No good deed should go unrewarded.",
    isForever = false,
  },
  [4765] = {
    id = 4765,
    title = "Delivery to Ridgewell",
    reqLevel = 57,
    questLevel = 60,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Mayara Brightwing",
    objectives = "Bring Ridgewell's Crate to Remington Ridgewell in Stormwind.",
    rewards = "6,600 XP • 2g 70s",
    tip = "I have packaged Doomriggers Clasp into a crate, suitable for shipment to Stormwind.  $N, you have been extremely helpful -- can I ask you for one last favor?\n\nDeliver the crate to Count Remington Ridgewell.  You will find him in the Keep of Stormwind.  I am sure he'll be very pleased to see what you have for him.",
    isForever = false,
  },
  [8497] = {
    id = 8497,
    title = "Desert Survival Kits",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Silithus",
    npc = "Item: Logistics Task Briefing I",
    objectives = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing I in order to complete this quest.",
    rewards = "650 XP",
    tip = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.",
    isForever = false,
  },
