  [4764] = {
    id = 4764,
    title = "Doomrigger's Clasp",
    reqLevel = 57,
    questLevel = 60,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Mayara Brightwing",
    objectives = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.",
    rewards = "1,650 XP",
    tip = "There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune.  It was where the Dark Iron dwarves kept their relics, trophies and objects of art.\n\nThat was long ago.  It is said the hall has collapsed and is now used for... less savory tasks.  But I believe some old dwarven relics may still be found there.\n\nOne such relic is Doomrigger's clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it.\n\nThat clasp, $N, is your g",
    isForever = false,
  },
  [7628] = {
    id = 7628,
    title = "Doomsday Candle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Mor'zul Bloodbringer",
    objectives = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes.",
    rewards = "6,600 XP",
    tip = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!\n\nContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes.",
    isForever = false,
  },
  [910] = {
    id = 910,
    title = "Down at the Docks",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Orcish Orphan",
    objectives = "Take your ward to the docks of Ratchet in the Barrens.",
    rewards = "650 XP",
    tip = "I have heard tales of the mighty ships that sail between Ratchet and Booty Bay!  That would be so cool to sail on the ocean and fight in many great sea battles.  Maybe I will be a mighty Horde sailor when I grow up!  Yeah!\n\nWould you take me to see the Ratchet docks, please?  I promise I won't get into the water or cause any trouble - I just want to see the big boats and smell the salty sea water!  Yeah!",
    isForever = false,
  },
  [8597] = {
    id = 8597,
    title = "Draconic for Dummies",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Narain Soothfancy",
    objectives = "Find Narain Soothfancy's book, buried on an island in the South Seas.",
    rewards = "6,600 XP",
    tip = "I knew that book would come in handy some day! Thankfully, I had the wit and foresight to stow it somewhere safe.\n\nDon't worry, it's in a place that nobody could ever hope to find it! I needed a gyrocopter just to get there the first time. Unfortunately I crashed it on the beach on my way back. It was through that accident that I gained these super-gnomish psychic powers!\n\nLook for my crashed gyrocopter somewhere on Land's End Beach and swim south from there! You'll know the spot when you see it",
    isForever = false,
  },
  [6502] = {
    id = 6502,
    title = "Drakefire Amulet",
    reqLevel = 50,
    questLevel = 60,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Haleh",
    objectives = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.",
    rewards = "8,300 XP",
    tip = "It is a piece of the dragon; a scale - enchanted and transformed. Whole, it could have granted access to the beast's lair. Shattered, it is useless.\n\nIt is possible to repair the item, but to do so would require the blood of a black dragon champion. There is one... He is known as General Drakkisath, ruler of the dragonspawn armies of Nefarian. Perhaps you have heard of him?\n\nReturn with his blood, $r, and I shall enchant the fragment into something that will grant you access to Onyxia's lair.",
    isForever = false,
  },
  [8557] = {
