  [8332] = {
    id = 8332,
    title = "Dukes of the Council",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Aurel Goldleaf",
    objectives = "Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.",
    rewards = "6,600 XP",
    tip = "We think it is possible to use a wind stone to ambush a duke of the Abyssal Council.  To do this, however, one must commune through the wind stone, and convince the council you are a middle ranked leader of the Twilight's Hammer.  \n\nSuch a gambit requires a replica of the cult's medallion of station.  I can create the medallion, but I will need a large brilliant shard, and crests worn by the Abyssal Templar.\n\nBring these to me and I will do the rest.",
    isForever = false,
  },
  [6135] = {
    id = 6135,
    title = "Duskwing, Oh How I Hate Thee...",
    reqLevel = 56,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "- Patch of Duskwing's Fur",
    rewards = "6,600 XP, 90s",
    tip = "Up until now, you have completed the missions I have assigned; even if not in the most timely manner.\n\nI suppose you think that you are ready for a challenge. Yes... Yes, imbecile, perhaps you are ready for a more involved set of missions.\n\nThe albino demon bat, Duskwing, roams the countryside just north of here. Track him down and destroy him. Return to me with a patch of his white fur and you shall be rewarded.",
    isForever = false,
  },
  [7165] = {
    id = 7165,
    title = "Earned Reverence",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Warmaster Laggrond",
    objectives = "- Frostwolf Insignia Rank 3",
    rewards = "8,300 XP",
    tip = "I must know, $N. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard.\n\nPresent your insignia!",
    isForever = false,
  },
  [7170] = {
