  [8536] = {
    id = 8536,
    title = "Earthen Templar",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Item: Tactical Task Briefing III",
    objectives = "Summon and slay an Earthen Templar and report back to Bor Wildmane in Cenarion Hold.  You must also bring Tactical Task Briefing III in order to complete this quest.",
    rewards = "650 XP",
    tip = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Earthen Templar and report to Bor Wildmane.",
    isForever = false,
  },
  [9072] = {
    id = 9072,
    title = "Earthshatter Boots",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Rimblat Earthshatter",
    objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make Earthshatter Boots if you bring him the following: 1 Desecrated Boots, 12 Wartorn Chain Scraps, 1 Arcanite Bar and 3 Nexus Crystals.",
    rewards = "Experience & Faction Reputation",
    tip = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.",
    isForever = false,
  },
