  [8634] = {
    id = 8634,
    title = "Enigma Boots",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Kandrostrasz",
    objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of the Sun, 5 Silver Scarabs and 5 Crystal Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",
    rewards = "9,950 XP",
    tip = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.",
    isForever = false,
  },
  [8632] = {
    id = 8632,
    title = "Enigma Circlet",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Andorgos",
    objectives = "Bring Vek'nilash's Circlet, 2 Idols of Night, 5 Bronze Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, $N.  I will give you a headpiece of unmatched power.",
    isForever = false,
  },
  [8631] = {
    id = 8631,
    title = "Enigma Leggings",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Kandrostrasz",
    objectives = "Bring Ouro's Intact Hide, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",
    isForever = false,
  },
  [8633] = {
    id = 8633,
    title = "Enigma Robes",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Vethsera",
    objectives = "Bring the Husk of the Old God, 2 Idols of the Sun, 5 Gold Scarabs and 5 Clay Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",
    isForever = false,
  },
  [8625] = {
    id = 8625,
    title = "Enigma Shoulderpads",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Andorgos",
    objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of Death, 5 Stone Scarabs and 5 Bronze Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",
    isForever = false,
  },
  [9301] = {
    id = 9301,
    title = "Envelope from the Front",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: A Bloodstained Envelope",
    objectives = "Take the Bloodstained Envelope to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "3,300 XP",
    tip = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...",
    isForever = false,
  },
  [9228] = {
