  [8733] = {
    id = 8733,
    title = "Eranikus, Tyrant of the Dream",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Sunken Temple",
    npc = "Malfurion Stormrage",
    objectives = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.",
    rewards = "6,600 XP",
    tip = "This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.\n\nTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.\n\n<Malfurion sighs.>\n\nA fall from grace a thousand years in the making...",
    isForever = false,
  },
