  [6821] = {
    id = 6821,
    title = "Eye of the Emberseer",
    reqLevel = 56,
    questLevel = 60,
    faction = "Both",
    zone = "Azshara",
    npc = "Duke Hydraxis",
    objectives = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.",
    rewards = "8,300 XP",
    tip = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?\n\nThat is your new task.\n\nHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth.",
    isForever = false,
  },
  [9310] = {
