  [8187] = {
    id = 8187,
    title = "Falcon's Call",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Zul'Gurub",
    npc = "Zanza the Restless",
    objectives = "Bring me all three and I will create a powerful enchantment for you!",
    rewards = "Experience & Faction Reputation",
    tip = "Zanza can create the ancient troll enchantments with the right components. The first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo.\n\nBring me these things and I will create a powerful enchantment for you!",
    isForever = false,
  },
  [7301] = {
    id = 7301,
    title = "Fallen Sky Lords",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Commander Duffy",
    objectives = "Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission.",
    rewards = "6,600 XP",
    tip = "We got them held prisoner, $r. I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them.\n\nSearch Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.",
    isForever = false,
  },
  [7302] = {
    id = 7302,
    title = "Fallen Sky Lords",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Commander Mulfort",
    objectives = "Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission.",
    rewards = "6,600 XP",
    tip = "Our air support is in shambles, $N. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue!\n\nGuse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker.\n\nThat's all the information I have. Move out! Search through the areas thoroughly.",
    isForever = false,
  },
  [8949] = {
    id = 8949,
    title = "Falrin's Vendetta",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Falrin Treeshaper",
    objectives = "Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul.",
    rewards = "6,600 XP",
    tip = "Yes, it is true that I am familiar with this enchantment you require, $c.  Yet I'm not one to give out favors freely, even if you were sent here by an old friend.\n\nI hold nothing but hatred and contempt for our brutish ogre neighbors.  And not only them, I hate the followers of Omokk just as much as I hate those that follow King Gordok.\n\nI want you to kill them.  Kill lots of them!  Bring me the beads they carry around their neck as proof of your work.  Do this and we shall talk about your reque",
    isForever = false,
  },
