  [7361] = {
    id = 7361,
    title = "Favor Amongst the Darkspear",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "You have been tasked with slaying opposing night elf players in Alterac Valley.\n\nKill a night elf and return to Najak Hexxen at Frostwolf Keep with a Severed Night Elf Head.",
    rewards = "6,600 XP, 1g 80s",
    tip = "<Najak snarls.>\n\nBefore the night elves existed there was troll. It was from troll that the night elves came.\n\nTheir mutinous attacks against my people will not be tolerated. Staghelm seeks to wipe us out - to leave no trace of those that bore him and his ilk. It will not happen!\n\nFor every night elf that you slay and decapitate, Najak will grant you favor amongst the Darkspear. Word of your deeds will be spread across Kalimdor and the Eastern Kingdoms. Go now and serve the Darkspear!",
    isForever = false,
  },
  [8979] = {
    id = 8979,
    title = "Fenstad's Hunch",
    reqLevel = 1,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Fenstad Argyle",
    objectives = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium.",
    rewards = "Experience & Faction Reputation",
    tip = "I believe I know the cause of this recent behavior. Have you smelled the new fragrance on the wind, over the stink of the canals? The new colognes and perfumes that have come into fashion?\n\nOur thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to my friend, Apothecary Zinge. The Royal Apothecary Society will find the truth.\n\n I will reimburse you for their purchase when you return.",
    isForever = false,
  },
