  [5124] = {
    id = 5124,
    title = "Fiery Plate Gauntlets",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Malyfous Darkhammer",
    objectives = "- Unfired Plate Gauntlets - Enchanted Thorium Bar x 6 - Essence of Fire x 2 - Star Ruby x 4",
    rewards = "8,300 XP",
    tip = "By Thaurissan's beard!\n\nWhere did you find them?\n\nMore importantly, are you willing to part with them? Naturally, I would pay you for such a noble gesture.\n\nI'll tell you what, $N. If you give me those unfired gauntlets, I will teach you how to make a set all your own. All you need to do is collect the parts for me so that I may narrow down the exact recipe.\n\nDo we have a deal??\n\nHere's the list of what I need, I'll front the non-enchanted thorium myself since you're supplying the gauntlets.",
    isForever = false,
  },
  [8403] = {
    id = 8403,
    title = "Fight for Warsong Gulch",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "6,600 XP • 90s",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
    isForever = false,
  },
  [8408] = {
    id = 8408,
    title = "Fight for Warsong Gulch",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "3,300 XP",
    tip = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest. There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack. Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N! For the Alliance!",
    isForever = false,
  },
  [8994] = {
    id = 8994,
    title = "Final Preparations",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "We're nearly there, $c. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.\n\nTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.\n\nGood luck, $N!",
    isForever = false,
  },
  [5861] = {
    id = 5861,
    title = "Find Myranda",
    reqLevel = 52,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Tirion Fordring",
    objectives = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift.",
    rewards = "4,950 XP",
    tip = "$N, you have done all that I have asked thus far. Only one step remains in your quest of redemption.\n\nYou must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight.\n\nThere is only one way in which to deliver my message and that is through a guise of deception.\n\nTo the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you.",
    isForever = false,
  },
  [5047] = {
    id = 5047,
    title = "Finkle Einhorn, At Your Service!",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Finkle Einhorn",
    objectives = "Talk to Malyfous Darkhammer in Everlook.",
    rewards = "6,600 XP",
    tip = "You'll find Malyfous Darkhammer in Everlook, $c. Tell him that 'Finkle is A-OK' and that the suit works perfectly.\n\nThen hand him this:\n\n<Finkle hands you a glowing piece of flesh.>\n\nI snatched it from the beast's innards during my 'vacation.'\n\nI bet Malyfous could give you a fairly accurate assessment of what he can do with parts from a monster like this!\n\nOh, I suppose you don't know where Everlook is, do you? To Winterspring, $g fella:lady;!",
    isForever = false,
  },
  [8877] = {
