  [8356] = {
    id = 8356,
    title = "Flexing for Nougat",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Innkeeper Allison",
    objectives = "- Flex for Innkeeper Allison",
    rewards = "Experience & Faction Reputation",
    tip = "That's an... interesting costume you have on.  Even though you're being nice and helping a sick child trick-or-treat this year, I'm afraid I'm going to have to ask you perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong $g man : woman;!\n\nWhen and only when you flex, I'll give you some tasty Stormwind Nougat.  It's a great Hallow's End treat.",
    isForever = false,
  },
  [8359] = {
    id = 8359,
    title = "Flexing for Nougat",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Innkeeper Gryshka",
    objectives = "Do a flex emote at Innkeeper Gryshka, and in exchange you'll receive Orgrimmar Nougat!",
    rewards = "Experience & Faction Reputation",
    tip = "That's an... interesting costume you have on.  Even though you're being nice and helping a sick child trick-or-treat this year, I'm afraid I'm going to have to ask you perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong $g man : woman;!\n\nWhen and only when you flex, I'll give you some tasty Orgrimmar Nougat.  It's a great Hallow's End treat.",
    isForever = false,
  },
  [6184] = {
    id = 6184,
    title = "Flint Shadowmore",
    reqLevel = 56,
    questLevel = 60,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Master Mathias Shaw",
    objectives = "Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore.",
    rewards = "4,950 XP",
    tip = "The only information we have thus far, then, is that Nathanos Marris may have been slain by this Blightcaller. We assume the Blightcaller is the same fiend that disposed of my agents.\n\nFlint Shadowmore, another SI:7 operative, is stationed at the Alliance encampment of Chillwind Point in the Western Plaguelands. Seek him out; he will debrief you on the current situation in the Plagues and give you an assignment.\n\nGood luck, $N.",
    isForever = false,
  },
  [8596] = {
    id = 8596,
    title = "Footwraps of the Oracle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Kandrostrasz",
    objectives = "Bring the Qiraji Bindings of Command, 2 Idols of Death, 5 Bronze Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",
    rewards = "9,950 XP",
    tip = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.",
    isForever = false,
  },
  [7491] = {
    id = 7491,
    title = "For All To See",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Thrall",
    objectives = "Seek out Overlord Runthak in the Valley of Strength.",
    rewards = "9,950 XP",
    tip = "Overlord Runthak awaits your arrival in the Valley of Strength.\n\n<Thrall salutes you.>\n\nDo not keep your public waiting, hero.",
    isForever = false,
  },
  [8367] = {
    id = 8367,
    title = "For Great Honor",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Alterac Valley Marks of Honor, 3 Arathi Basin Marks of Honor and 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "8,300 XP • 2g 70s",
    tip = "Serving the Horde in one of the great battles against the Alliance is a source of great honor! The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters. We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war.\n\nGo forth and crush the Alliance in Arathi Basin, Alterac Valley, Eye of the Storm and Warsong Gulch! For Honor! For the Horde!",
    isForever = false,
  },
  [8388] = {
    id = 8388,
    title = "For Great Honor",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Alterac Valley Marks of Honor, 3 Arathi Basin Marks of Honor and 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "6,600 XP",
    tip = "Many brave fighters look up to you, $N. You continue to be an example for all in the fight against the Alliance. What news do you bring from your journeys?",
    isForever = false,
  },
  [4974] = {
    id = 4974,
    title = "For The Horde!",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Thrall",
    objectives = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.",
    rewards = "9,950 XP • 2g 70s",
    tip = "Rend dares make such grand claims because of the protection he is afforded by the black flight.\n\nYou, $N, will find a way to pass through the Halls of Ascension. You will then find 'Warchief' Rend Blackhand and you will destroy him - FOR THE HORDE!\n\n<Thrall slams a fist down upon his throne.>\n\nThe next time you return to my chambers, you will hold his head high in triumph and then you shall present it to your Warchief. Do this and be honored as a hero of the Horde.",
    isForever = false,
  },
  [7507] = {
