  [8309] = {
    id = 8309,
    title = "Glyph Chasing",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Rutgar Glyphshaper",
    objectives = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.\n\nUse the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.",
    rewards = "8,800 XP • 1g 80s",
    tip = "After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals.\n\nWe must get a rubbing from crystals in all three hives. If we can get those rubbings, we might be able to make sense of this madness.\n\nTake this transcription set  and hit those hives, $N. Don't come back until you've gotten copies from each hive.",
    isForever = false,
  },
  [7364] = {
    id = 7364,
    title = "Gnomeregan Bounty",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "You have been tasked with slaying opposing tauren players in Alterac Valley.\n\nKill a tauren and return to Dirk Swindle at Dun'Baldar with a  Tauren Hoof.",
    rewards = "6,600 XP, 1g 80s",
    tip = "The High Tinkerer himself has sent me to this field of battle to defend my gnomish brothers and sisters. We have received word that the tauren are singling out and slaying gnomes. Worst of all, they are removing tufts of glorious gnome hair from the corpses of the fallen. These atrocities must be stopped. We must reciprocate!\n\nI want them de-hoofed, $c. Bring me their hooves! Show yourself as an ally of the gnomes.",
    isForever = false,
  },
  [8343] = {
