  [6961] = {
    id = 6961,
    title = "Great-father Winter is Here!",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Kaymard Copperpinch",
    objectives = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.",
    rewards = "660 XP",
    tip = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",
    isForever = false,
  },
