  [8238] = {
    id = 8238,
    title = "Gurubashi, Vilebranch, and Witherbark Coins",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Vinchaxa",
    objectives = "- Gurubashi Coin - Vilebranch Coin - Witherbark Coin",
    rewards = "Experience & Faction Reputation",
    tip = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Some are sought after by my compatriots for various armors they offer Zandalar heroes.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.",
    isForever = false,
  },
  [8311] = {
    id = 8311,
    title = "Hallow's End Treats for Jesper!",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Jesper",
    objectives = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge.  Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.",
    rewards = "1,650 XP",
    tip = "I want to go trick-or-treating, but I can't because I'm sick.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a little gnome named Talvash in Ironforge is handing out candy as well.  When you have all the candy, bring them back to me here!",
    isForever = false,
  },
  [8312] = {
    id = 8312,
    title = "Hallow's End Treats for Spoops!",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Spoops",
    objectives = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik in Sen'jin Village.  Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Spoops at the Orgrimmar Orphanage with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.",
    rewards = "1,650 XP",
    tip = "I want to go trick-or-treating, but I can't because I'm sick.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a troll named Kali Remik in Sen'jin Village is handing out candy as well.  When you have all the candy, bring them back to me here!",
    isForever = false,
  },
  [6024] = {
    id = 6024,
    title = "Hameya's Plea",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Object: Torn Scroll",
    objectives = "Kill Infiltrator Hameya.  Use his key on the Mound of Dirt behind the Undercroft.",
    rewards = "6,600 XP • 90s",
    tip = "Kill me.  Before it's too late.\n\nI am Hameya.  While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed.  We are infected.\n\nI can feel the lich's words now, urging me to reach Zul'Mashar and infect more of my people.  I cannot resist, and so I wrote this scroll before my will left me.\n\nI buried a chest in dirt next to a wagon behind this crypt, but only my key will open it.  I have the key.  If you want my treasure, then find me.\n\nKill me.  Before it's too late.",
    isForever = false,
  },
  [8706] = {
    id = 8706,
    title = "Hammer of the Gathering Storm",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Ahn'Qiraj",
    npc = "Warden Haro",
    objectives = "Bring 1 Qiraji Spiked Hilt, 2  Amber Idols, 5 Ivory Scarabs and 5 Bronze Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",
    isForever = false,
  },
