  [6824] = {
    id = 6824,
    title = "Hands of the Enemy",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azshara",
    npc = "Duke Hydraxis",
    objectives = "Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.",
    rewards = "9,950 XP",
    tip = "$N, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.\n\nBut its success would further our war efforts tremendously and... it was deemed worth risking you.\n\nWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!\n\nThis task will take every resource you possess, $N, but if you can do it then the Firelords will be dealt a terrible blow.",
    isForever = false,
  },
