  [8739] = {
    id = 8739,
    title = "Hive'Ashi Scout Report",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Item: Tactical Task Briefing VIII",
    objectives = "Contact Cenarion Scout Jalia inside Hive'Ashi and return the Hive'Ashi Scout Report to Windcaller Proudhorn at Cenarion Hold.  You must also bring Tactical Task Briefing VIII in order to complete this quest.",
    rewards = "650 XP",
    tip = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Jalia has been watching the silithid movements at Hive'Ashi for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, $N.",
    isForever = false,
  },
