  [8535] = {
    id = 8535,
    title = "Hoary Templar",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Item: Tactical Task Briefing IV",
    objectives = "- Hoary Templar",
    rewards = "650 XP",
    tip = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy a Hoary Templar and report to Bor Wildmane.",
