  [6183] = {
    id = 6183,
    title = "Honor the Dead",
    reqLevel = 56,
    questLevel = 60,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Master Mathias Shaw",
    objectives = "Speak with Mathias Shaw again if you wish to accept his task.",
    rewards = "660 XP",
    tip = "Five of my best field agents were assigned the Marris case. One returned, only to end up dead in his sleep three days later.\n\nWhat little information we did manage to get out of him was incoherent gibberish. We made out two words: \"Nathanos\", and \"Blightcaller.\"\n\nI do not have the available manpower to continue this investigation and Ravenholdt will not assist us. We must get to the bottom of this; if only to provide closure to the families of the deceased. Will you help?",
    isForever = false,
  },
  [7164] = {
    id = 7164,
    title = "Honored Amongst the Clan",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Warmaster Laggrond",
    objectives = "- Frostwolf Insignia Rank 2",
    rewards = "6,600 XP",
    tip = "It is good to see you again, $C. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, $N. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.",
    isForever = false,
  },
  [7169] = {
    id = 7169,
    title = "Honored Amongst the Guard",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Lieutenant Haggerdin",
    objectives = "- Stormpike Insignia Rank 2",
    rewards = "6,600 XP",
    tip = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.",
    isForever = false,
  },
  [8149] = {
    id = 8149,
    title = "Honoring a Hero",
    reqLevel = 30,
    questLevel = 60,
    faction = "Both",
    zone = "Seasonal Events",
    npc = "Wagner Hammerstrike",
    objectives = "Travel to Uther's Tomb in Western Plaguelands and use Uther's Tribute at his statue, and then return to Wagner Hammerstrike outside Ironforge before the Harvest Festival is over.",
    rewards = "6,600 XP",
    tip = "During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Alliance acknowledges many heroes, but none weave a more tragic tale than that of Uther Lightbringer.\n\nHelp us honor Uther by taking this offering to his tomb in the Western Plaguelands.  Place it at his statue, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Uther his tribute.",
    isForever = false,
  },
  [8150] = {
    id = 8150,
    title = "Honoring a Hero",
    reqLevel = 30,
    questLevel = 60,
    faction = "Both",
    zone = "Seasonal Events",
    npc = "Javnir Nashak",
    objectives = "Travel to Grom's Monument in the Demon Fall Canyon of Ashenvale and use Grom's Tribute at the base of the monument.  Return to Javnir Nashak outside Orgrimmar before the Harvest Festival is over.",
    rewards = "6,600 XP",
    tip = "During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Horde acknowledges many heroes, but none exemplify strength and sacrifice more than Grom Hellscream.\n\nHelp us honor Grom by taking this offering to his monument in the Demon Fall Canyon of Ashenvale.  Place it at the base, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Grom his tribute.",
    isForever = false,
  },
  [8190] = {
    id = 8190,
    title = "Hoodoo Hex",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Zul'Gurub",
    npc = "Zanza the Restless",
    objectives = "Bring me all three and I will create a powerful enchantment for you!",
    rewards = "Experience & Faction Reputation",
    tip = "Zanza can create the ancient troll enchantments with the right components. The first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo.\n\nBring me these things and I will create a powerful enchantment for you!",
    isForever = false,
  },
  [5103] = {
    id = 5103,
    title = "Hot Fiery Death",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Object: Human Remains",
    objectives = "Someone in this world must know what to do with these gauntlets. Good luck!",
    rewards = "6,600 XP",
    tip = "The only thing that remains of this human are some charred bones. He seems to have died within arms reach of what he was after - unfired plate gauntlets.\n\nPerhaps you should grab the gauntlets and get out of the fire?",
    isForever = false,
  },
  [5243] = {
    id = 5243,
    title = "Houses of the Holy",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Leonid Barthalomew the Revered",
    objectives = "- Stratholme Holy Water x 5",
    rewards = "6,600 XP, 1g 80s",
    tip = "I look at my undeath as a malady, $r. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?\n\nI am revered by my colleagues because of the sacrifices I have made, but the accolades mean nothing to me.\n\nIf you are interested in assisting the Argent Dawn, then a job I can offer.\n\nVenture to Stratholme and recover our surplus of holy water. Search the supply crates.",
    isForever = false,
  },
  [8924] = {
    id = 8924,
    title = "Hunting for Ectoplasm",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Mux Manascrambler",
    objectives = "Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands.  Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan.",
    rewards = "6,600 XP • 90s",
    tip = "A fine piece of engineering, if I do say so myself!  You will need to travel a bit, I'm afraid, in order to find the incorporeal undead we require.\n\nYou see, different climates lend different consistencies to the spectral fabric of the dead.  The tortured night elves of Silithus, the spirits of the highborne from Winterspring and the ghosts and banshees of the Eastern Plaguelands should give us the different types of ectoplasm we need.  Be sure to place the distiller nearby before you harvest th",
    isForever = false,
  },
  [8970] = {
    id = 8970,
    title = "I See Alcaz Island In Your Future...",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Bodley",
    objectives = "Gather 20 Bloodkelp from the Strashaz naga and then return to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "As I was saying, $c, in my living years I flirted with becoming a diviner. But, there really wasn't as much profit in it as you might imagine, mostly because it's dangerous and the reagents are rare and expensive. However, I do know enough to be able to pinpoint the final piece of the amulet, and the spirit of my former comrade along with it.\n\nThis is where you come in, $N. I need you to go to Alcaz Island off the coast of Dustwallow Marsh and collect Bloodkelp from the Strashaz naga that live t",
    isForever = false,
  },
