  [8789] = {
    id = 8789,
    title = "Imperial Qiraji Armaments",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Arygos",
    objectives = "Arygos in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring him Imperial Qiraji Armaments and 3 Elementium Ore.",
    rewards = "Experience & Faction Reputation",
    tip = "We have not sat idly by for a millennium, $N.\n\nWe have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery.\n\nWeaknesses exist and we know how to use those weaknesses to our advantage.\n\nFind and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.",
    isForever = false,
  },
  [8790] = {
    id = 8790,
    title = "Imperial Qiraji Regalia",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Merithra of the Dream",
    objectives = "- Imperial Qiraji Regalia - Elementium Ore x 3",
    rewards = "Experience & Faction Reputation",
    tip = "Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal.\n\nFind and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power.",
    isForever = false,
  },
  [7241] = {
    id = 7241,
    title = "In Defense of Frostwolf",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Frostwolf Ambassador Rokhstrom",
    objectives = "Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains.",
    rewards = "6,600 XP",
    tip = "The drums of war sound off in a distant land, $c. The favored clan of your Warchief is under attack from the nefarious Stormpike Guard of Ironforge.\n\nBy the looks of you, I can discern that you are indeed battle hardy and prepared to take on the cause of the Frostwolf.\n\nIt is you who must now take the next step in your evolution.\n\nNorth of Tarren Mill, in Alterac,  you will find the entrance to Alterac Valley. It is there that you will find Warmaster Laggrond. Hurry $c, for the battle is upon us",
    isForever = false,
  },
  [5944] = {
    id = 5944,
    title = "In Dreams",
    reqLevel = 52,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Highlord Taelan Fordring",
    objectives = "Escort Taelan Fordring out of Hearthglen.",
    rewards = "9,950 XP",
    tip = "For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become? It has been decades, yet the memories of my father; those precious memories, they are what have kept me alive.\n\nI have dreams, stranger. In these dreams my father is with me. He stands proudly at my side as I am inducted into the Order. We battle legion of Scourge, side by side. We bring honor to the Alliance, to Lordaeron.\n\nI want not to dream anymore.\n\nTake me to",
    isForever = false,
  },
  [8929] = {
    id = 8929,
    title = "In Search of Anthion",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Eastern Plaguelands",
    npc = "Deliana",
    objectives = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.",
    rewards = "6,600 XP",
    tip = "Well, nothing left for us to do but try out the goblin's invention.  Word has it that Anthion was mowed down by the undead legions of Stratholme as he tried to enter its gates.\n\nTry using the device there and find out whatever Anthion knew.",
    isForever = false,
  },
  [8930] = {
    id = 8930,
    title = "In Search of Anthion",
    reqLevel = 58,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Mokvar",
    objectives = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.",
    rewards = "6,600 XP",
    tip = "Very well, $N.  All that remains is to put the goblin's invention to the test.  Word has it that Anthion was slain by the undead legions of Stratholme as he tried to enter its gates.\n\nTry using the device there and see if, indeed, you can speak with the dead!",
    isForever = false,
  },
  [8355] = {
    id = 8355,
    title = "Incoming Gumdrop",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Talvash del Kissel",
    objectives = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!",
    rewards = "Experience & Faction Reputation",
    tip = "A trick-or-treater!  Huzzah!\n\nWell now, even though you're doing something noble and collecting candies for a sick child, I can't let you off the hook that easily.  I have a yummy Gnomeregan Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, $c!",
    isForever = false,
  },
  [8358] = {
    id = 8358,
    title = "Incoming Gumdrop",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Kali Remik",
    objectives = "Do a train emote at Kali Remik, and in exchange you'll receive a Darkspear Gumdrop!",
    rewards = "Experience & Faction Reputation",
    tip = "A trick-or-treater!  Yeah mon!\n\nWell now, even though you're doing something noble and collecting candies for a sick child, I can't let you off the hook that easily.  I have a yummy Darkspear Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, $c!",
    isForever = false,
  },
  [8306] = {
    id = 8306,
    title = "Into The Maw of Madness",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Commander Mar'alith",
    objectives = "- The Fate of Mistress Natalia Mar'alith",
    rewards = "9,950 XP, 1g 80s",
    tip = "I need you to venture into Hive'Regal and find what became of my dearest Natalia, $N. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves. They might be able to give you some tips on dealing with the silithid that inhabit that hive.\n\nAnd $N, if she truly is as mad as they say... do what you must.\n\n<Commander Mar'alith turns away from you.>",
    isForever = false,
  },
  [8369] = {
    id = 8369,
    title = "Invaders of Alterac Valley",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Alterac Valley Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "8,300 XP • 1g 80s",
    tip = "Listen up, $N.  No matter what you might have heard about the battle raging in Alterac Valley, one thing remains true: the Stormpike Expedition invaded Frostwolf Territory.  The day we allow the Alliance to invade Horde lands without a forceful response is the day I hang up my axe and live the rest of my life in shame.  Go forth and expel the invaders!",
    isForever = false,
  },
  [8387] = {
    id = 8387,
    title = "Invaders of Alterac Valley",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Horde Warbringer",
    objectives = "Bring 3 Alterac Valley Marks of Honor to a Horde Warbringer outside the battlegrounds.",
    rewards = "3,300 XP",
    tip = "The battle for Alterac rages on! You must return to Alterac Valley and once more drive the invaders out of Frostwolf territory, $N!",
    isForever = false,
  },
