  [5892] = {
    id = 5892,
    title = "Irondeep Supplies",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Stormpike Quartermaster",
    objectives = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.",
    rewards = "Experience & Faction Reputation",
    tip = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep.\n\nWe need the supplies in Irondeep, $N.  Enter the mine and bring me a load of them.",
    isForever = false,
  },
  [6985] = {
    id = 6985,
    title = "Irondeep Supplies",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Frostwolf Quartermaster",
    objectives = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.",
    rewards = "Experience & Faction Reputation",
    tip = "The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!\n\nBe wary, $N.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.",
    isForever = false,
  },
