  [5384] = {
    id = 5384,
    title = "Kirtonos the Herald",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Scholomance",
    npc = "Eva Sarkhoff",
    objectives = "- Kirtonos the Herald",
    rewards = "8,300 XP",
    tip = "This is it, $N.\n\n<Eva points to the vial inside the bag.>\n\nThe blood of innocents. The purest blood, used to appease Krastinov's master.\n\nIt is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed.\n\nTake the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.\n\nShould you succeed, you will earn more than just our gratitude.",
    isForever = false,
  },
  [7202] = {
    id = 7202,
    title = "Korrak the Bloodrager",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Lieutenant Haggerdin",
    objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.",
    rewards = "9,950 XP",
    tip = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.",
    isForever = false,
  },
  [7382] = {
    id = 7382,
    title = "Korrak the Everliving",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.\n\nReturn the Skull of Korrak to Lieutenant Haggerdin in the Hillsbrad Foothills.",
    rewards = "",
    tip = "There's something not quite right about all of this... Did anybody think to burn Korrak's corpse? Those trolls will stop at nothing to revive their fallen leader - as blue skinned pagan man-beasts often do.\n\nJust keep your eyes out, $N. Don't be alarmed if Korrak makes a surprise appearance; and if he does, I want him executed - his corpse burned to ashes.\n\nFor good measure, lop off his head and bring me his skull before you ignite the lifeless mass.",
    isForever = false,
  },
  [5515] = {
    id = 5515,
    title = "Krastinov's Bag of Horrors",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Scholomance",
    npc = "Eva Sarkhoff",
    objectives = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.",
    rewards = "6,600 XP",
    tip = "A great weight has been lifted from our hearts, $N, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.\n\nBefore you may face Kirtonos, however, you must first secure a method in which to summon him.\n\nIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.\n\nFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.",
    isForever = false,
  },
  [8710] = {
    id = 8710,
    title = "Kris of Unspoken Names",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Warden Haro",
    objectives = "Bring 1 Qiraji Ornate Hilt, 2  Onyx Idols, 5 Gold Scarabs and 5 Clay Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",
    isForever = false,
  },
