  [7166] = {
    id = 7166,
    title = "Legendary Heroes",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Warmaster Laggrond",
    objectives = "- Frostwolf Insignia Rank 4",
    rewards = "9,950 XP",
    tip = "Your radiate command and power, shaman. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.",
