  [9112] = {
    id = 9112,
    title = "Leggings of Faith",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Father Inigo Montoy",
    objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make Leggings of Faith if you bring him the following: 1 Desecrated Leggings, 20 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.",
    rewards = "Experience & Faction Reputation",
    tip = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    isForever = false,
  },
  [5167] = {
    id = 5167,
    title = "Legplates of the Chromatic Defier",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Object: Catalogue of the Wayward",
    objectives = "To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':\n\n1 Chromatic Carapace.\n\n10 Brilliant Chromatic Scales.\n\n10 Blood of Heroes.\n\n5 Skin of Shadow.",
    rewards = "9,950 XP",
    tip = "The carapace of a mature chromatic drake is needed to form the foundation of the leggings. Brilliant chromatic scales are then layered upon the wire frame and enchanted in the blood of heroes. Finally, the supple skin of shadow must be applied to the inner greaves.",
    isForever = false,
  },
  [5522] = {
    id = 5522,
    title = "Leonid Barthalomew",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Burning Steppes",
    npc = "Tinkee Steamboil",
    objectives = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.",
    rewards = "4,950 XP",
    tip = "I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.\n\nLeonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.\n\nThat hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master comm",
    isForever = false,
  },
  [9295] = {
    id = 9295,
    title = "Letter from the Front",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: A Torn Letter",
    objectives = "Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "3,300 XP",
    tip = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...",
    isForever = false,
  },
  [7484] = {
    id = 7484,
    title = "Libram of Focus",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Lorekeeper Lydros",
    objectives = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.",
    rewards = "1,650 XP",
    tip = "This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old.\n\nThose among you who are more magically inclined might find this item interesting.\n\nThe Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession.\n\nBring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.",
    isForever = false,
  },
  [7485] = {
    id = 7485,
    title = "Libram of Protection",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Lorekeeper Lydros",
    objectives = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.",
    rewards = "1,650 XP",
    tip = "He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.\n\nBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.\n\nOh, and check the north",
    isForever = false,
  },
  [7483] = {
    id = 7483,
    title = "Libram of Rapidity",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Lorekeeper Lydros",
    objectives = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.",
    rewards = "1,650 XP",
    tip = "Master Winthalus lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...\n\nRegardless, if you are interested, you will need to present the Libram along with some basic reagents.\n\nHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!\n\n<Lydros shrugs.>",
    isForever = false,
  },
