  [7638] = {
    id = 7638,
    title = "Lord Grayson Shadowbreaker",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Duthorian Rall",
    objectives = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.",
    rewards = "650 XP",
    tip = "The time has come, $N, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.\n\nSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.\n\nI wish you the best in this trial.  For the Light, noble $G brother : sister;!",
    isForever = false,
  },
  [5264] = {
    id = 5264,
    title = "Lord Maxwell Tyrosus",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Duke Nicholas Zverenhoff",
    objectives = "Speak with Lord Maxwell Tyrosus. He is inside the church.",
    rewards = "6,600 XP",
    tip = "I am about to bestow a great honor upon you, $N.\n\nLord Maxwell wishes to reward you for your service to the Argent Dawn!\n\nIt has been years since Maxwell has granted audience to outsiders.",
    isForever = false,
  },
  [1800] = {
    id = 1800,
    title = "Lordaeron Throne Room",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Orcish Orphan",
    objectives = "- - Go to the old Lordaeron Throne Room that lies just before descending into the Undercity.",
    rewards = "650 XP",
    tip = "The orphan matrons at my home tell mighty stories of battle and lore at night if we are good and do our chores.  One story was about how Lordaeron fell, and about how the evil Arthas took his own father's life to become ruler.\n\nHe had no honor, $N!  When I grow up and become a mighty Horde warrior, my blade will be guided by honor - never evil!\n\nWould you take me to see the throne room, please?  It is just before where you would go down into the Undercity.",
    isForever = false,
  },
  [8341] = {
    id = 8341,
    title = "Lords of the Council",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Aurel Goldleaf",
    objectives = "Bring 5 Large Brilliant Shards and 3 Abyssal Signets to Aurel Goldleaf in Cenarion Hold.",
    rewards = "6,600 XP",
    tip = "Lords of the Abyssal Council can only be summoned through the greater wind stones, and only the top ranking members of the Twilight's Council may speak to them.  But... I have found a way to upgrade your disguise and fool the Abyssal Lords!\n\nThe disguise calls for a ring of lordship, worn only by the highest members of the cult.  I will craft one for you if you can bring me large brilliant shards and abyssal signets.",
    isForever = false,
  },
  [8599] = {
    id = 8599,
    title = "Love Song for Narain",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Meridith the Mermaiden",
    objectives = "Take Meridith's Love Letter to Narain Soothfancy in Tanaris.",
    rewards = "3,300 XP",
    tip = "It isn't often that I get visitors. As a matter of fact, the last time I had a visitor was when I rescued that dear, sweet gnome from the wreckage of the crashed flying machine.\n\n<Meridith gazes into nothingness, lost in a memory.>\n\nDo you know him? Narain? Narain Soothfancy? Oh it would mean so much to me if somebody would deliver a message to him for me. I must tell him how I feel! I know it's love! I just know it!\n\nCould you possibly deliver a message to Narain? I would be forever indebted to",
    isForever = false,
  },
  [969] = {
    id = 969,
    title = "Luck Be With You",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Witch Doctor Mau'ari",
    objectives = "Collect 10 Frostmaul Shards for Witch Doctor Mau'ari in Orgrimmar.",
    rewards = "6,600 XP • 90s",
    tip = "Ah, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows!\n\nTo da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality.\n\nBring back 4 frostmaul shards, and my lucky charm will be yours.",
    isForever = false,
  },
  [8867] = {
    id = 8867,
    title = "Lunar Fireworks",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Lunar Festival Harbinger",
    objectives = "Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.",
    rewards = "Experience & Faction Reputation",
    tip = "Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil.\n\nWe celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks!\n\nFor a small donation you can purchase colorful rockets from our vendor.  Try using some of the launchers around here, $N.",
    isForever = false,
  },
  [8708] = {
    id = 8708,
    title = "Mace of Unending Life",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Warden Haro",
    objectives = "Bring 1 Qiraji Ornate Hilt, 2  Jasper Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",
    isForever = false,
  },
