  [5206] = {
    id = 5206,
    title = "Marauders of Darrowshire",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Carlin Redpath",
    objectives = "Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands.",
    rewards = "6,600 XP",
    tip = "Chromie said the relics you gathered are reagents to a powerful spell, and one more is required: skulls from the scourge who took part in the battle of Darrowshire.\n\nTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.\n\nGo, $N.  You'll find scourge champions in the Noxious Glade to the north and the Fungal Vale to the west.",
    isForever = false,
  },
  [8293] = {
    id = 8293,
    title = "Mark of Honor",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Warsong Mark of Honor for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to rage against the Silverwing Sentinels! Bring me more marks of honor!",
    isForever = false,
  },
  [6847] = {
    id = 6847,
    title = "Master Ryson's All Seeing Eye",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Syndicate Master Ryson",
    objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!",
    rewards = "Experience & Faction Reputation",
    tip = "Your war in the heart of Alterac means nothing to the Syndicate, $c. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>",
    isForever = false,
  },
  [6848] = {
    id = 6848,
    title = "Master Ryson's All Seeing Eye",
    reqLevel = 51,
    questLevel = 60,
