  [7667] = {
    id = 7667,
    title = "Material Assistance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Sagorne Creststrider",
    objectives = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond.",
    rewards = "4,950 XP",
    tip = "$N, there is a pressing matter I hope you can help with... both materially and spiritually.  Allow me to explain.\n\nWithin the depths of the Scholomance in Lordaeron is a chamber called the Great Ossuary.  I need to complete a device that would pierce the shadows of this horrid room.  To finish what I have started, I need two diamonds: an Azerothian and a Pristine Black.  These are not trivial items, I know - I just don't have the resources myself.\n\nCould you provide me with one of each?",
    isForever = false,
  },
  [5081] = {
    id = 5081,
    title = "Maxwell's Mission",
    reqLevel = 55,
    questLevel = 60,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Marshal Maxwell",
    objectives = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.",
    rewards = "8,300 XP • 1g 80s",
    tip = "This information fills in the gaps to our otherwise impeccable intelligence of Blackrock Spire.\n\nThe attack must be decisive, $N.\n\nFirst their war master, the troll Voone, must be destroyed. Without his battle plans, the Blackrock orcs will be thrown into chaos.\n\nYou must then take out the ogre Highlord, Omokk. The cowardly ogres of Blackrock are powerless without his leadership.\n\nLastly, the overlord of the citadel: Wyrmthalak. With Wyrmthalak dead, their central command unit is without a condu",
    isForever = false,
  },
  [4766] = {
    id = 4766,
    title = "Mayara Brightwing",
    reqLevel = 57,
    questLevel = 60,
    faction = "Alliance",
    zone = "Blackrock Spire",
    npc = "Count Remington Ridgewell",
    objectives = "Speak with Mayara Brightwing in the Burning Steppes.",
    rewards = "660 XP",
    tip = "An agent of mine, Mayara Brightwing, was sent to the Burning Steppes to scout the ruined city of Thaurissan.  That destroyed city of the Dark Iron dwarves may hide objects of great value... objects that would fit nicely into our family museum.\n\nMayara says she found something and will need aid in retrieving it, but it is not in Thaurissan.  Instead, a foray into Blackrock Spire will be required.\n\nI do not know the details, but if interested then speak with Mayara in the Burning Steppes.",
    isForever = false,
  },
  [8995] = {
    id = 8995,
    title = "Mea Culpa, Lord Valthalak",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.",
    rewards = "9,950 XP",
    tip = "All is now ready, $N.\n\nWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.\n\nOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.\n\nGood luc",
    isForever = false,
  },
