  [5463] = {
    id = 5463,
    title = "Menethil's Gift",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Leonid Barthalomew the Revered",
    objectives = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.",
    rewards = "6,600 XP",
    tip = "I watched as the human, Ras Frostwhisper, pledged his undying soul to the Lich King. He drew the dagger to his own throat and with a smile, cut from ear to ear. His body collapsed inside the borders of the pentagram. The Lich King stood over the fallen mage and with a single motion, Ras Frostwhisper the lich, was born.\n\n<Leonid gazes at the ground and then looks up at you.>\n\nYes, $r, I remember. What you seek has a name - Menethil's Gift: The ground blessed by the Lich King - holy ground to Scou",
    isForever = false,
  },
  [5464] = {
    id = 5464,
    title = "Menethil's Gift",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Object: Menethil's Gift",
    objectives = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.",
    rewards = "8,300 XP",
    tip = "The soul of the fallen clings to that which represents its former life and transforms the item into a soulbound keepsake. You pick the item up and place it in your pack.",
    isForever = false,
  },
  [8746] = {
    id = 8746,
    title = "Metzen the Reindeer",
    reqLevel = 40,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Kaymard Copperpinch",
    objectives = "Find Metzen the Reindeer.  Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Kaymard Copperpinch in Orgrimmar once Metzen is freed.",
    rewards = "4,950 XP",
    tip = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!",
    isForever = false,
  },
  [8762] = {
    id = 8762,
    title = "Metzen the Reindeer",
    reqLevel = 40,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Wulmort Jinglepocket",
    objectives = "Find Metzen the Reindeer.  Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Wulmort Jinglepocket in Ironforge once Metzen is freed.",
    rewards = "4,950 XP",
    tip = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Greatfather Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!",
    isForever = false,
  },
  [9302] = {
    id = 9302,
    title = "Missive from the Front",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
