  [8985] = {
    id = 8985,
    title = "More Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.",
    isForever = false,
  },
  [8986] = {
    id = 8986,
    title = "More Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Sili",
    isForever = false,
  },
  [8987] = {
    id = 8987,
    title = "More Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "- Brilliant Sword of Zealotry",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.",
    isForever = false,
  },
  [8988] = {
    id = 8988,
    title = "More Components of Importance",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.",
    isForever = false,
  },
