  [9025] = {
    id = 9025,
    title = "Morgan's Discovery",
    reqLevel = 1,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Morgan Pestle",
    objectives = "Return to Aristan Mottar outside the bank in Stormwind's Trade District.",
    rewards = "Experience & Faction Reputation",
    tip = "Well, I'll be. It looks like Aristan might be on to something after all. I found traces of substances used in love potions and insidious mind-altering draughts.\n\nIt isn't unheard of for perfumes to have some of them, but a few of the ingredients I detected... Smells funny.",
    isForever = false,
  },
