  [4866] = {
    id = 4866,
    title = "Mother's Milk",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Ragged John",
    objectives = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.",
    rewards = "9,950 XP • 1g 80s",
    tip = "It's probably one of the most potent poisons in the world, $r!\n\nI've overheard the Blackrock speaking about its lethality in my jaunts into the Spire. They call it 'Mother's Milk', named after Mother Smolderweb, the big nasty spider in the Skitterweb cave.\n\nNow here's what I need from you: A live sample of the Milk, flowing through YOUR veins. Just bringing me the gland won't be enough! Get her to poison you and come back to me!\n\nThen... I get to milk ya!\n\n<Rubs his hands together in anticipatio",
    isForever = false,
  },
  [8227] = {
    id = 8227,
    title = "Nat's Measuring Tape",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Object: Battered Tackle Box",
    objectives = "Return Nat's Measuring Tape to Nat Pagle in Dustwallow Marsh.",
    rewards = "650 XP",
    tip = "Amongst the shattered fishing lures and tackle is a rolled, silken measuring tape.  Attached to the tape is a label that reads:\n\n\"Nat Pagle, Dustwallow Marsh.\"",
    isForever = false,
  },
  [6146] = {
    id = 6146,
    title = "Nathanos' Ruse",
    reqLevel = 56,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar.",
    rewards = "6,600 XP",
    tip = "I have made some adjustments to this command. Should our little ruse work, they will expose the Scarlet Oracle and we shall strike!\n\nNow pay attention, $c. You are to deliver this command to the Crusader Lord, Valdelmar.\n\nHow? You are going to hand it to him, imbecile.\n\nTake the command and this rotten apple to Tyr's Hand. When you cross into the city, eat the apple. You will transform into something more... palatable to the humans. Take the command and hand it to the Crusader Lord, Valdelmar.",
    isForever = false,
  },
  [8730] = {
    id = 8730,
    title = "Nefarius's Corruption",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Blackwing Lair",
    npc = "Vaelastrasz the Corrupt",
    objectives = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.",
    rewards = "9,950 XP",
    tip = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?\n\n<Vaelastrasz coughs weakly.>\n\nNe... Nefarius now holds the scepter shard.\n\nTime is of the essence. Nefarius plans to destroy the shard. You must hurry!",
    isForever = false,
  },
  [8584] = {
    id = 8584,
    title = "Never Ask Me About My Business",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Narain Soothfancy",
    objectives = "Narain Soothfancy in Tanaris wants you to speak with Dirge Quikcleave in Gadgetzan.",
    rewards = "650 XP",
    tip = "If there is one thing that you should know about me, it is this: NEVER ask me about my business! I work with things you simply cannot understand. Like for example: Do you know what a psychotronic muzzledorf is? Of course you don't! And that's why we leave the planning to me and the fetching to you.\n\nAs I said earlier, if this is going to work, we're going to need a 500 pound chicken.\n\nHead to Gadgetzan and speak with Dirge Quikcleave - he'll get you started on finding a suitable specimen.",
    isForever = false,
  },
