  [6569] = {
    id = 6569,
    title = "Oculus Illusions",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Myranda the Hag",
    objectives = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.",
    rewards = "6,600 XP",
    tip = "So the $r wishes to become one of the Black Flight, eh?\n\nThe creation of the illusion you require is trivial, but the components required for the divination are quite difficult to obtain. The Warchief has entrusted you with this mission, so Myranda must assume you as capable.\n\nTravel to the upper citadel of Blackrock Spire and slay enough of the black dragonspawn to fill up one of your packs with their eyes.\n\nReturn to Myranda when you have gathered enough of the reagent.",
    isForever = false,
  },
  [5848] = {
    id = 5848,
    title = "Of Love and Family",
    reqLevel = 52,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Artist Renfray",
    objectives = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\n\nReturn the painting to Tirion Fordring.",
    rewards = "6,600 XP",
    tip = "The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.\n\nAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.\n\nTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'\n\nMay the Light guide your actions.",
    isForever = false,
  },
  [9233] = {
    id = 9233,
    title = "Omarion's Handbook",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Item: Omarion's Handbook",
    objectives = "Take Omarion's Handbook to Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "Experience & Faction Reputation",
    tip = "Wilhelm,\n\nIf you are reading this, I have perished - finally. I want you to know that my dying thoughts revolved around you and your ineptitude when it comes to tradeskills. Unfortunately, the bearer of this handbook is in even worse shape than you in regards to crafting.\n\nAbout the book: These are the rest of my recipes. Make the bearer of this book whatever they request. I'm sure you will charge a hefty fee for your services because you are, after all, a bastard.\n\nIn Disdain,\n\nOmarion",
    isForever = false,
  },
