  [8288] = {
    id = 8288,
    title = "Only One May Rise",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Blackwing Lair",
    npc = "Baristolth of the Shifting Sands",
    objectives = "Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.",
    rewards = "6,600 XP",
    tip = "There is no time to waste! A hero must be found! The task I give will require an army to complete but only one may rise from the throng of would be champions to take on the burden and responsibility of an ally of the Brood.\n\nWithin the lair of the Lord of Blackrock is a most cruel beast. The Broodlord Lashlayer guards the Halls of Strife, blocking the way into Nefarian's inner sanctum. Slay the foul aberration and return his head to me. Do this and you may begin the next step of your journey.",
    isForever = false,
  },
  [6187] = {
    id = 6187,
    title = "Order Must Be Restored",
    reqLevel = 56,
    questLevel = 60,
    faction = "Alliance",
    zone = "Eastern Plaguelands",
    npc = "Highlord Bolvar Fordragon",
    objectives = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.\n\nKeep your wits about you, <player>. The Horde will defend the ranger lord with their very lives.",
    rewards = "9,950 XP",
    tip = "Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?\n\nNathanos' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.\n\nAnd now... the champion of the Forsaken.\n\nNo. This cannot be. Order must be restored.\n\nGather an army, $N. Return to the Plagues with your army and destroy the Blightcaller.\n\nI wish you luck, $N. Truly, you will need it for this battle.",
    isForever = false,
  },
  [7868] = {
