  },
  [9300] = {
    id = 9300,
    title = "Page from the Front",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: A Ragged Page",
    objectives = "Take the Ragged Page to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "3,300 XP",
    tip = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...",
    isForever = false,
  },
  [8074] = {
    id = 8074,
    title = "Paragons of Power: The Augur's Belt",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Maywiki of Zuldazar",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Maywiki of Zuldazar: 5 Skullsplitter Coins, 5 Gurubashi Coins, 2 Purple Hakkari Bijous, and a Primal Hakkari Girdle.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Augurs know the mojo of the elements, mon.  They use it as a means to guide the tribe to glory.  In the dark days after the Gurubashi Empire ripped itself up, our augurs led us to our safe haven in the South Seas.  They've also led us back here to the Vale, right back to the heart of evil brewin' in Zul'Gurub.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!",
    isForever = false,
  },
  [8056] = {
    id = 8056,
    title = "Paragons of Power: The Augur's Bracers",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Maywiki of Zuldazar",
    objectives = "Bring Maywiki of Zuldazar a Primal Hakkari Armsplint.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The augurs of our tribe are revered for their gifts of the divine sight, ya mon.  They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people.  As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this for us, and I'll give ya some bracers that our augurs prize above all ot",
    isForever = false,
  },
  [8075] = {
    id = 8075,
    title = "Paragons of Power: The Augur's Hauberk",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Maywiki of Zuldazar",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Maywiki of Zuldazar: 5 Witherbark Coins, 5 Hakkari Coins, 2 Gold Hakkari Bijous, and a Primal Hakkari Tabard.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The augurs of the Zandalar all wear a distinctive chest piece called a hauberk.  It's fitted with the finest of silks and cloths, interwoven with strong chain.  It's a symbol of not only their divinity, but also of their authority, mon.  It's never wise to cross one whose life is devoted to speakin' with the spirits...\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya one of the finest hauberks our augurs would ever hope to w",
    isForever = false,
  },
  [8070] = {
    id = 8070,
    title = "Paragons of Power: The Confessor's Bindings",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Al'tabim the All-Seeing: 5 Hakkari Coins, 5 Zulian Coins, 2 Orange Hakkari Bijous, and a Primal Hakkari Sash.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe.  It was then that the confessors amongst us arose, preserving the tribe by banishing out those who would destroy their own kind.  They not only keep us in tune with the spirits, but they also preserve the flesh.\n\nGo forth into Zul'Gurub and witness first hand the depravity of Hakkar and the Gurubashi.  Wrest the Paragons of Power that we seek from them; success will be rewarded",
    isForever = false,
  },
  [8071] = {
    id = 8071,
    title = "Paragons of Power: The Confessor's Mantle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Al'tabim the All-Seeing: 5 Razzashi Coins, 5 Witherbark Coins, 2 Bronze Hakkari Bijous, and a Primal Hakkari Aegis.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe.  These mantles are woven with powerful mojo that aids them in judging those who would threaten our tribe.  As a priest, you too must spend your time judging those worthy and not; such a mantle would definitely be a blessing to you.\n\nIn exchange for fighting Hakkar's minions in Zul'Gurub and bringing me the Paragons of Power I seek, I will give you a mantle worthy of our finest confessors.",
    isForever = false,
  },
  [8061] = {
    id = 8061,
    title = "Paragons of Power: The Confessor's Wraps",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "We Zandalar invest power in those who speak with the authority of divinity.  Our priests are more than just healers - they are our confessors.  Evil comes both from outside threats - such as Hakkar - and from within the tribe.  Our confessors act as the judges amongst us, preserving us from the same evil that devoured the Gurubashi from inside itself.\n\nGo to Zul'Gurub and bring back the Paragons of Power from the Gurubashi.  Learn what it means to be the confessor, and preserve us from evil.",
    isForever = false,
  },
  [8076] = {
    id = 8076,
    title = "Paragons of Power: The Demoniac's Mantle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Al'tabim the All-Seeing: 5 Witherbark Coins, 5 Hakkari Coins, 2 Orange Hakkari Bijous, and a Primal Hakkari Sash.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The demoniac seeks to embody power outright, not just possess it.  More than one of our demoniacs has lost a fight with a demon; with our enemies threatening us - especially in Zul'Gurub - the power that a demoniac is able to unleash on our foes is worth the sacrifice.  Our survival depends on crushing those who would destroy us; the fall of the Gurubashi Empire taught us this.\n\nTravel to Zul'Gurub and gain the Paragons of Power we need.  Do this, and a valuable demoniac item shall be yours.",
    isForever = false,
  },
  [8077] = {
    id = 8077,
    title = "Paragons of Power: The Demoniac's Robes",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Al'tabim the All-Seeing: 5 Skullsplitter Coins, 5 Bloodscalp Coins, 2 Silver Hakkari Bijous, and a Primal Hakkari Kossack.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The ultimate symbol of power amongst the tribe is the garb we wear in battle.  A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric.  The visage of the robe is said to instill fear into the minds of all who see it... especially the demons that the demoniac will eventually dominate.\n\nFrom Zul'Gurub, you must bring me a very specific set of the Paragons of Power.  It will be difficult... but your success will assure you of acquiring a robe for yourself.",
    isForever = false,
  },
  [8059] = {
    id = 8059,
    title = "Paragons of Power: The Demoniac's Wraps",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further.  Through an ancient and arcane ritual, they allow a demon to enter their being.  Rather than let it possess them though, they enslave the demon from the inside, absorbing the power of the beast for their own command.  It is a feat few are ever able to master.\n\nFor you to learn of the power of the demoniac, I must have Paragons of Power from Zul'Gurub.  Go there and retrieve that which we seek.",
    isForever = false,
  },
  [8064] = {
    id = 8064,
    title = "Paragons of Power: The Haruspex's Belt",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Maywiki of Zuldazar",
    objectives = "Bring Maywiki of Zuldazar a Primal Hakkari Sash.  Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Honored with Zandalar.",
    rewards = "6,600 XP",
    tip = "We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around.  Still, a haruspex is the one of us most in tune with nature, and rightly so.  To give up the ghost of a beastie is to know what it is to be one of them.  That is the real power of nature.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub, proving yourself to us.  Do this, and I'll give ya a powerful item - a belt used by many of the Zandalar's haruspices.\n\nStrong mojo, ya mon!",
    isForever = false,
  },
  [8057] = {
    id = 8057,
    title = "Paragons of Power: The Haruspex's Bracers",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Maywiki of Zuldazar",
    objectives = "Bring Maywiki of Zuldazar a Primal Hakkari Stanchion.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "A haruspex is a key member of our tribe; you'll be wise to listen to their portents.  By communion with animals and givin' them up to the spirits when needed, they give us divine guidance.  In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and I'll give ya bracers that any haruspex of the Zandalar would want.",
    isForever = false,
  },
  [8065] = {
    id = 8065,
    title = "Paragons of Power: The Haruspex's Tunic",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Maywiki of Zuldazar",
    objectives = "Bring Maywiki of Zuldazar a Primal Hakkari Tabard.  Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Revered with Zandalar.",
    rewards = "6,600 XP",
    tip = "The ultimate symbol of a haruspex's power is what they wear, $N.  Of these, the tunic symbolizes the connection between themselves and the divine wisdom they seek.  It often weaves parts of the beasties they sacrifice into the tunic; this reminds them of the connection they have to their gifts.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and a tunic seeping with the true power of a haruspex is yours.",
    isForever = false,
  },
  [8068] = {
    id = 8068,
    title = "Paragons of Power: The Illusionist's Mantle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Al'tabim the All-Seeing: 5 Gurubashi Coins, 5 Razzashi Coins, 2 Orange Hakkari Bijous, and a Primal Hakkari Shawl.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Magic is a raw, primal force to be shaped by those strong enough to do it.  Mojo is our extension of this power; one such potent manipulation of it is in the form of illusion.  How can one truly hope to win against a foe that is not even really there?  We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe.\n\nTake the needed Paragons of Power from Zul'Gurub - for this, honor from the tribe and a powerful mantle used by our best illusionists will be your",
    isForever = false,
  },
  [8069] = {
    id = 8069,
    title = "Paragons of Power: The Illusionist's Robes",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Al'tabim the All-Seeing: 5 Sandfury Coins, 5 Zulian Coins, 2 Silver Hakkari Bijous, and a Primal Hakkari Kossack.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The tribe acknowledges station and power through what we wear.  Our vestments are made from the finest of materials, and interwoven with the mojo we use to make us powerful.  Illusionists are no exception; their robes are said to embody the essence of illusion in their look.  Legend states that their ancient robes never looked the same twice.\n\nI will give you an illusionist's robe, $N... but earn your place of reverence among the tribe first!  Bring me the Paragons of Power from Zul'Gurub!",
    isForever = false,
  },
  [8060] = {
    id = 8060,
    title = "Paragons of Power: The Illusionist's Wraps",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Al'tabim the All-Seeing",
    objectives = "Bring Al'tabim the All-Seeing Primal Hakkari Bindings.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Mages in our tribe are known as illusionists.  They employ powerful mojo in their incantations, often befuddling and confusing the tribe's enemies!\n\n<Al'tabim laughs wickedly.>\n\nIt is quite the sight to see a powerful illusionist at work, bringing our enemies to their knees from their own madness!\n\nFor you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power.  For this, I will give you arm wraps our illusionists use to weave their spells.",
    isForever = false,
  },
  [8063] = {
    id = 8063,
    title = "Paragons of Power: The Madcap's Bracers",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Falthir the Sightless",
    objectives = "Bring Falthir the Sightless a Primal Hakkari Armsplint.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The madcaps of Zandalar are similar to rogues, but above all else they embrace madness... chaos... the unpredictability of existence.  A terror to behold on the battlefield, they sowed the seeds of confusion and mayhem amongst our enemies in the savage times after the tribes splintered.  We would not be here today without them.\n\nBring to me the Paragons of Power from Zul'Gurub that I seek, and I will grant you the first of the madcap's prized armors.  Embrace the madness!",
    isForever = false,
  },
  [8072] = {
    id = 8072,
    title = "Paragons of Power: The Madcap's Mantle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Falthir the Sightless",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: 5 Zulian Coins, 5 Razzashi Coins, 2 Purple Hakkari Bijous, and a Primal Hakkari Girdle.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "One of Zandalar's legendary madcaps was Khar'vaxal the Cracked.  Legend states that when facing the enemies of the tribe for the first time, Kar'xavan used his mantle specifically woven with \"the weave of madness\".  His form was shrouded not only by the mantle, but also with the blinding speed of his twin daggers.  Madcaps today cherish their mantle as a sign of their place in the tribe.\n\nBring to me the Paragons of Power I seek, and such a mantle will be yours to weave madness unto your own ene",
    isForever = false,
  },
  [8073] = {
    id = 8073,
    title = "Paragons of Power: The Madcap's Tunic",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Falthir the Sightless",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: 5 Hakkari Coins, 5 Skullsplitter Coins, 2 Gold Hakkari Bijous, and a Primal Hakkari Aegis.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "My eyes failed me long ago, but I do not miss them.  Even in a tribe such as ours - where one's vestments convey station and purpose - the most potent of garb exudes power that simple eyes cannot see.  The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel.\n\nThe Paragons of Power I need lie in Zul'Gurub; bring me what I seek, and I will reward you with your own legendary tunic... one befitting a weaver of madness.",
    isForever = false,
  },
  [8066] = {
    id = 8066,
    title = "Paragons of Power: The Predator's Belt",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Falthir the Sightless",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: 5 Razzashi Coins, 5 Hakkari Coins, 2 Green Hakkari Bijous, and a Primal Hakkari Shawl.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "A predator knows how to stalk their prey, but a successful one knows how to strike at it once they have closed ranks.  You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators.\n\nBring me choice parts of the Paragons of Power from within Zul'Gurub.  My reward will be the power that the trinkets yield, while yours will be the Zandalar predator's belt - equipment well worth the trade.",
    isForever = false,
  },
  [8062] = {
    id = 8062,
    title = "Paragons of Power: The Predator's Bracers",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Falthir the Sightless",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Bindings.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe.  Hunters claim to be much like our tribe's predators - to seek the hunt is to embody the essence of the predator, yes.  Your hunt in Zul'Gurub, however, will show us how you truly rate amongst our finest predators.\n\nBring to me a sampling of the Paragons of Power from within Zul'Gurub.  Do so, and you'll take first steps in becoming the penultimate predator.",
    isForever = false,
  },
  [8067] = {
    id = 8067,
    title = "Paragons of Power: The Predator's Mantle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Falthir the Sightless",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: 5 Zulian Coins, 5 Gurubashi Coins, 2 Silver Hakkari Bijous, and a Primal Hakkari Aegis.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "We Zandalar prize what we wear as a symbol of accomplishment.  You don't need to be able to see what one wears to be able to sense what emanates from it - power transcends sight.  The garments of the Zandalar predator are like this, and most cherished by them is the mantle they wear.  It helps to obfuscate them from view... and to make their presence known when they wish it.\n\nThe Paragons of Power await your retrieval in Zul'Gurub.  Bring me what I seek, and the predator's mantle shall be yours.",
    isForever = false,
  },
  [8058] = {
    id = 8058,
    title = "Paragons of Power: The Vindicator's Armguards",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Jin'rokh the Breaker",
    objectives = "Bring Jin'rokh the Breaker a Primal Hakkari Armsplint.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Vengeance is power.  The Zandalar vindicator is such power.  The tribe has many enemies.  The vindicator exacts retribution on them.  No crime against us is unpunished.  The vindicator delivers this punishment.  Our enemies fear our vengeance.  They should.  They forever will.\n\nBecome one of our vindicators.  Seek the Paragons of Power inside Zul'Gurub.  Slay the minions of Hakkar and claim vengeance in the tribe's name.  You will be rewarded.",
    isForever = false,
  },
  [8078] = {
    id = 8078,
    title = "Paragons of Power: The Vindicator's Belt",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Jin'rokh the Breaker",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Jin'rokh the Breaker: 5 Vilebranch Coins, 5 Skullsplitter Coins, 2 Green Hakkari Bijous, and a Primal Hakkari Girdle.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The ultimate vengeance waits within Zul'Gurub.  Hakkar must not rise again.  Hakkar destroyed the Gurubashi Empire from within.  No sacrifice was enough.  The trolls are a shadow of former glories.  I know this is because of Hakkar.\n\nBecome the vindicator you were meant to be.  Wreak havoc on the minions of evil.  Zul'Gurub must taste Zandalar vengeance.  Bring me proof in the Paragons of Power.  You will receive the vindicator's belt.  You will receive real power.\n\nGo.",
    isForever = false,
  },
  [8079] = {
    id = 8079,
    title = "Paragons of Power: The Vindicator's Breastplate",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Jin'rokh the Breaker",
    objectives = "Bring the following Paragons of Power from Zul'Gurub to Jin'rokh the Breaker: 5 Bloodscalp Coins, 5 Sandfury Coins, 2 Bronze Hakkari Bijous, and a Primal Hakkari Kossack.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "The vindicator's symbol of power is the breastplate.  It is forged with powerful mojo.  It is trusted only to those we revere.  It is the Zandalar symbol of vengeance.\n\nTo become a vindicator is to become vengeance.  Take the Paragons of Power we need from Zul'Gurub.  Bring them to us.  We will take the mojo stolen from us.  We will make the minions of Hakkar pay.  We will reward you with the vindicator's breastplate.\n\nGo.  Be our vengeance, $N.",
    isForever = false,
  },
  [5057] = {
    id = 5057,
    title = "Past Endeavors",
    reqLevel = 53,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Storm Shadowhoof",
    objectives = "Bring Storm Shadowhoof's Marker to Melor Stonehoof in Thunder Bluff.",
    rewards = "3,300 XP",
    tip = "Before you spoke to me, $N, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a $c, and I now know these things to be the truth.\n\nThose that excel as you do are worthy of recognition. Take this marker to a friend of mine in Thunder Bluff named Melor Stonehoof. I'm sure he will remember you, and what you accomplished so long ago. Speak to him of you recent victories, and do not ever forget what you have accomplished today.",
    isForever = false,
  },
  [9109] = {
    id = 9109,
    title = "Plagueheart Belt",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Mataus the Wrathcaster",
    objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands will make a Plagueheart Belt if you bring him the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth.",
    rewards = "Experience & Faction Reputation",
    tip = "I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.\n\nAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die; but I've already explained this...",
    isForever = false,
  },
