  [8946] = {
    id = 8946,
    title = "Proof of Life",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Ysida Harmon",
    objectives = "Bring Ysida's Locket to Anthion Harmon in Eastern Plaguelands.",
    rewards = "6,600 XP",
    tip = "It is the cruelest of fates that my beloved has perished while trying to rescue me.  Yet, you claim to possess the ability to converse with him.\n\nBring him this locket as proof that I am well.  He must not linger in this world; my heart would not be able to bear it.\n\nFarewell, $N.  I shall be in your debt always.",
    isForever = false,
  },
  [8191] = {
    id = 8191,
    title = "Prophetic Aura",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
