  [7161] = {
    id = 7161,
    title = "Proving Grounds",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Warmaster Laggrond",
    objectives = "Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner. Return the Frostwolf Banner to Warmaster Laggrond.",
    rewards = "6,600 XP",
    tip = "Hail, $c. It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns...\n\nAll newcomers to the Valley must first complete the rite of battle.\n\nDeep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.",
    isForever = false,
  },
  [7162] = {
    id = 7162,
    title = "Proving Grounds",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Lieutenant Haggerdin",
    objectives = "Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner. Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains.",
    rewards = "6,600 XP",
    tip = "You've arrived just in time, $c. These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority.\n\nBefore you make your way to the field of battle, you will want to join the rank of Stormpike.\n\nSouthwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner. Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.",
    isForever = false,
  },
  [8294] = {
    id = 8294,
    title = "Quell the Silverwing Usurpers",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Warsong Gulch",
    npc = "Captain Shatterskull",
    objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
    rewards = "6,600 XP • 2g 70s",
    tip = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.",
    isForever = false,
  },
  [8671] = {
    id = 8671,
    title = "Ragetotem the Elder",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Elder Ragetotem",
    objectives = "Speak with Elder Ragetotem in Azeroth.",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [7002] = {
    id = 7002,
    title = "Ram Hide Harnesses",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Frostwolf Wolf Rider Commander",
    objectives = "null",
    rewards = "Experience & Faction Reputation",
    tip = "While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.\n\nYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!\n\nSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!",
    isForever = false,
  },
  [7026] = {
    id = 7026,
    title = "Ram Riding Harnesses",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Stormpike Ram Rider Commander",
    objectives = "null",
    rewards = "Experience & Faction Reputation",
    tip = "The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.\n\nWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.\n\nYou must strike at our enemy's base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!",
    isForever = false,
  },
  [9230] = {
    id = 9230,
    title = "Ramaladni's Icy Grasp",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Korfax, Champion of the Light",
    objectives = "- Frozen Rune - Blue Sapphire - Arcanite Bar",
    rewards = "Experience & Faction Reputation",
    tip = "Fixing this band may prove to be quite challenging, $N. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory.",
    isForever = false,
  },
  [5981] = {
    id = 5981,
    title = "Rampaging Giants",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Rivern Frostwind",
    objectives = "Rivern Frostwind wants you to kill 4 Frostmaul Giants and 4 Frostmaul Preservers.",
    rewards = "Experience & Faction Reputation",
    tip = "Around 4,000 years ago, Tyrande Whisperwind saved the life of the frostsaber queen, at the hands of rampaging giants. Since then, the frostsabers have been allies of the night elves.\n\nThese same giants that once were a danger to the frostsabers, still exist not too far from here. They are called the frostmaul, and they have taken over the large valley to the south.\n\nProve your loyalty to the frostsabers; kill these giants in the name of the frostsaber queen, Shy-Rotam!",
    isForever = false,
  },
  [6163] = {
    id = 6163,
    title = "Ramstein",
    reqLevel = 56,
    questLevel = 60,
    faction = "Horde",
    zone = "Stratholme",
    npc = "Nathanos Blightcaller",
    objectives = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.",
    rewards = "6,600 XP • 1g 80s",
    tip = "I was overwhelmed. On this very stead, I stood... held my ground in defense of Lordaeron. The farm and all on it were waylaid by a gigantic wave of Scourge.\n\nThe wretch. The filth. It hovered above me, entrails hanging from its gaping chest cavity.\n\nI woke as Scourge. For so long I was helpless. My mind had coalesced with the Lich King's.\n\nShe came for me... somewhere, somehow, I knew she would. Free.\n\nAnd now, I must have my vengeance - my vengeance on that which took from me my life. Destroy i",
    isForever = false,
  },
  [9047] = {
    id = 9047,
    title = "Redemption Boots",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Commander Eligor Dawnbringer",
    objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Boots if you bring him the following: 1 Desecrated Boots, 12 Wartorn Plate Scraps, 2 Arcanite Bars and 3 Cured Rugged Hides.",
    rewards = "Experience & Faction Reputation",
