  [8375] = {
    id = 8375,
    title = "Remember Alterac Valley!",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Alterac Valley Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "8,300 XP • 1g 80s",
    tip = "Make no mistake about it, $N.  The Horde is quite right when they say Alterac Valley is Frostwolf Territory.\n\nYou see, the Stormpike Expedition arrived as peaceful visitors to the area in search of ore and relics.  The Frostwolves reacted with the most brutal and uncivilized act of aggression the Alliance has experienced.\n\nLet us never forget the brave dwarves that perished in that cowardly unannounced attack.  Go now, $c, do your part in the battle for Alterac Valley.  For the Alliance!",
    isForever = false,
  },
  [8383] = {
    id = 8383,
    title = "Remember Alterac Valley!",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Alliance Brigadier General",
    objectives = "Bring 3 Alterac Valley Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
    rewards = "3,300 XP",
    tip = "The Battle in Alterac Valley rages on, $N! Have you done your part as of late, $N?",
    isForever = false,
  },
  [9416] = {
    id = 9416,
    title = "Report to General Kirika",
    reqLevel = 53,
    questLevel = 60,
    faction = "Horde",
    zone = "Silithus",
    npc = "Scout Bloodfist",
    objectives = "Speak with General Kirika at the Horde encampment near Hive'Regal.",
    rewards = "Experience & Faction Reputation",
    tip = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.",
    isForever = false,
  },
  [9415] = {
    id = 9415,
    title = "Report to Marshal Bluewall",
    reqLevel = 53,
    questLevel = 60,
    faction = "Alliance",
    zone = "Silithus",
    npc = "Rifleman Torrig",
    objectives = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",
    rewards = "Experience & Faction Reputation",
    tip = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.",
    isForever = false,
  },
  [8242] = {
    id = 8242,
    title = "Restoring Fiery Flux Supplies via Heavy Leather",
    reqLevel = 45,
    questLevel = 60,
    faction = "Both",
    zone = "Searing Gorge",
    npc = "Master Smith Burninate",
    objectives = "- Incendosaur Scale x 2 - Heavy Leather x 10 - Coal",
    rewards = "Experience & Faction Reputation",
    tip = "Let's not waste more of my precious time with jibber jabber, $R. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Heavy Leather.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.",
    isForever = false,
  },
