  [8996] = {
    id = 8996,
    title = "Return to Bodley",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Spirit of Lord Valthalak",
    objectives = "Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning.",
    rewards = "650 XP",
    tip = "I will ignore your impertinence this time, $c, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, $r, you have shown courage where those that stole from me did not, and probably never could!\n\nReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now.",
    isForever = false,
  },
  [5941] = {
    id = 5941,
    title = "Return to Chromie",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Carlin Redpath",
    objectives = "Take the Bundle of Relics to Chromie in Andorhal.",
    rewards = "3,300 XP",
    tip = "You have gathered many relics of the battle of Darrowshire.  Each time you returned with more, my heart yearned for my village... yearned to protect it from its fate.\n\nI know that cannot be, but Chromie, that strange gnome in Andorhal, tells me it is possible.  She says you can save Darrowshire!\n\nShe asked me to gather together the relics, and to have you bring them to her.  She said that she awaits you in the ruined inn of Andorhal.",
    isForever = false,
  },
  [8977] = {
    id = 8977,
    title = "Return to Deliana",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Mux Manascrambler",
    objectives = "Bring the Extra-Dimensional Ghost Revealer  to Deliana in Ironforge.",
    rewards = "6,600 XP",
    tip = "It's been great working with you, $N.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!",
