  [9115] = {
    id = 9115,
    title = "Sandals of Faith",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Father Inigo Montoy",
    objectives = "- Desecrated Sandals - Wartorn Cloth Scrap x 12 - Mooncloth x 2 - Cured Rugged Hide x 3",
    rewards = "Experience & Faction Reputation",
    tip = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    isForever = false,
  },
  [8239] = {
    id = 8239,
    title = "Sandfury, Skullsplitter, and Bloodscalp Coins",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Vinchaxa",
    objectives = "- Sandfury Coin - Skullsplitter Coin - Bloodscalp Coin",
    rewards = "Experience & Faction Reputation",
    tip = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Some are sought after by my compatriots for various armors they offer Zandalar heroes.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.",
    isForever = false,
  },
  [9136] = {
    id = 9136,
    title = "Savage Flora",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Rayne",
    objectives = "- Savage Frond x 30",
    rewards = "6,600 XP",
    tip = "I make a special type of armor for the brave heroes that enter Naxxramas known as Dreamwalker. They are able to provide me with most of the materials I require but I am always looking for those able to retrieve savage fronds from the flora of our world.\n\nYou may think of this job as beneath you, but without the fronds, the armor could not be made.\n\nI am also in a unique position to pay you with an insignia of your choice as both the Dawn and the Crusade supply me with funds.",
    isForever = false,
  },
  [9137] = {
    id = 9137,
    title = "Savage Fronds",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Rayne",
    objectives = "- Savage Frond x 30",
    rewards = "9s",
    tip = "",
    isForever = false,
  },
  [8999] = {
