  [5862] = {
    id = 5862,
    title = "Scarlet Subterfuge",
    reqLevel = 52,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Myranda the Hag",
    objectives = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.\n\nHearthglen is to the north, Taelan should be inside of Mardenholde Keep.",
    rewards = "6,600 XP",
    tip = "I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations.\n\nShould you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time.\n\nSpeak to me again when you are ready.",
    isForever = false,
  },
  [8352] = {
    id = 8352,
    title = "Scepter of the Council",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Bor Wildmane",
    objectives = "Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.",
    rewards = "10,550 XP • 2g 70s",
    tip = "Huum and I were just talking about you.  He tells me you're just about ready to try your hand at fighting an Abyssal Lord!\n\nI must tell you this is a very dangerous endeavor.  You'd better bring backup.  And I don't mean one or two of your friends, I'm talking about a top-notch, battle-ready fighting force.  If your friends are as good as you, you might even defeat it!\n\nIf you do - and I'll want evidence, as always - I'll give you a truly great reward.",
    isForever = false,
  },
  [9419] = {
    id = 9419,
    title = "Scouring the Desert",
    reqLevel = 55,
    questLevel = 60,
    faction = "Alliance",
    zone = "Silithus",
    npc = "Marshal Bluewall",
    objectives = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",
    rewards = "6,600 XP",
    tip = "We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.",
    isForever = false,
  },
  [9422] = {
    id = 9422,
    title = "Scouring the Desert",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Silithus",
    npc = "General Kirika",
    objectives = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.",
    rewards = "6,600 XP",
    tip = "For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.",
    isForever = false,
  },
  [8578] = {
    id = 8578,
    title = "Scrying Goggles? No Problem!",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Molten Core",
    npc = "Narain Soothfancy",
    objectives = "Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris.",
    rewards = "8,300 XP",
    tip = "<You hear a sigh of relief escape the crate.>\n\nYou just want his scrying goggles? Great! That will be no problem... Just give me a minute to... Hey! Where the... Dagnabbit!\n\nWell, there's some bad news and some worse news. The bad news is that I lost the goggles. The worse news is that I lost them when I was nosing around in the Molten Core last month. Yep, the Molten Core... I guess that concludes our business! Bye!",
    isForever = false,
  },
  [8779] = {
    id = 8779,
    title = "Scrying Materials",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Silithus",
    npc = "Item: Logistics Task Briefing V",
    objectives = "Bring 1 Large Brilliant Shard, 1 Large Radiant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing V in order to complete this quest.",
    rewards = "650 XP",
    tip = "Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research.\n\nPlease gather these materials and deliver them to her directly so that she may continue her research.",
    isForever = false,
  },
  [8807] = {
    id = 8807,
    title = "Scrying Materials",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Silithus",
    npc = "Item: Logistics Task Briefing V",
    objectives = "Bring 1 Large Brilliant Shard, 1 Large Radiant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing V in order to complete this quest.",
    rewards = "650 XP",
    tip = "Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research.\n\nPlease gather these materials and deliver them to her directly so that she may continue her research.",
    isForever = false,
  },
  [8712] = {
    id = 8712,
    title = "Scythe of the Unseen Path",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Warden Haro",
    objectives = "Bring 1 Qiraji Spiked Hilt, 2 Azure Idols, 5 Silver Scarabs and 5 Bone Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",
    isForever = false,
  },
  [4742] = {
    id = 4742,
    title = "Seal of Ascension",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Vaelan",
    objectives = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\n\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe.",
    rewards = "8,300 XP",
    tip = "As you can see, the unadorned seal has three empty sockets. Each of those sockets must be filled with a gemstone representing the leadership's command. Finally, Overlord Wyrmthalak, master of the lower citadel, must forge the seal in the flames of the Black Dragonflight.\n\nUnderstand this, mortal: the chance that one of the three generals of the lower citadel would carry a gemstone at any given time is rare. You must be vigilant in your quest. Remain determined!",
    isForever = false,
  },
  [4743] = {
    id = 4743,
    title = "Seal of Ascension",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Vaelan",
    objectives = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\n\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!",
    rewards = "9,950 XP",
    tip = "Few of the black dragonkin, outside of those in the upper citadel, have the ability to forge the seal with their own flaming breath. Wyrmthalak is one such dragonkin, but his will is unbreakable.\n\nYou must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find an ancient drake known as Emberstrife. You must break his will, $N. Break it and use this orb on his weakened form. You will have scant seconds to control his mind and fan the flames that will forge the seal.",
    isForever = false,
  },
  [8318] = {
    id = 8318,
    title = "Secret Communication",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Bor Wildmane",
    objectives = "Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold.",
    rewards = "6,600 XP • 1g 80s",
    tip = "Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them.  I want you to bring me a stack of them, $c.\n\nI can't figure out what the gibberish means, but that's not the point!  These papers are how their different groups communicate secretly.  The more texts we take out of circulation, the less they can communicate!",
    isForever = false,
  },
  [8857] = {
    id = 8857,
    title = "Secrets of the Colossus - Ashi",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Colossus Researcher Nestor",
    objectives = "Take the Colossus of Ashi's Husk to Oglethorpe Obnoticus in Booty Bay.",
    rewards = "9,950 XP, 2g 70s",
    tip = "I'm looking for battle hardened adventurers willing and able to get a fresh husk sample from the fallen Colossus of Ashi to Oglethorpe in Booty Bay. No, no, I wouldn't want you to go anywhere near that thing's corpse. Just take one of my samples and make it snappy. These things are no good to him rotten!",
    isForever = false,
  },
  [8858] = {
    id = 8858,
    title = "Secrets of the Colossus - Regal",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Colossus Researcher Eazel",
    objectives = "Take the Colossus of Regal's Husk to Overseer Oilfist in Searing Gorge.",
    rewards = "9,950 XP, 2g 70s",
    tip = "There ain't nothin' I'd like more than to stuff this bug husk down Oilfist's fat face... Cept, I'm stuck here collectin' samples from that overgrown cockroach. I'll be here 'till the wee mornin' hours given the size o' that thing.\n\nTake this here sample to Oilfist fer me and do it fast, $c. He's payin' BIG!\n\nYar, Thorium Point - it be in the Searin' Gorge.",
    isForever = false,
  },
  [8859] = {
    id = 8859,
    title = "Secrets of the Colossus - Zora",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Colossus Researcher Sophia",
    objectives = "Take the Colossus of Zora's Husk to Lord Maxwell Tyrosus at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "9,950 XP, 2g 70s",
    tip = "My servants were nearly killed in their efforts to recover this sample. You absolutely must hurry! Lord Maxwell Tyrosus eagerly awaits a fresh husk sample. He believes that the secrets of this Colossus could help us in the war against the Scourge!\n\nWhy are you still here!? To Light's Hope! Yes, you will be rewarded handsomely for your efforts...",
    isForever = false,
  },
  [8784] = {
    id = 8784,
    title = "Secrets of the Qiraji",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Item: Ancient Qiraji Artifact",
    objectives = "Take the Ancient Qiraji Artifact to the dragons hiding near the entrance of the temple.",
    rewards = "Experience & Faction Reputation",
    tip = "You have discovered an ancient Qiraji artifact! Perhaps one of the dragons near the entrance of the temple would have a use for this relic.",
    isForever = false,
  },
