  [9085] = {
    id = 9085,
    title = "Shadows of Doom",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Commander Thomas Helleran",
    objectives = "Go to a summoning circle and kill a Shadow of Doom, then return to Commander Thomas Helleran at Light's Hope Chapel in Eastern Plaguelands.",
    rewards = "Experience & Faction Reputation",
    tip = "After you bring down the defenses of the Scourge summoning circles that have appeared in the zones under attack, you will be able to confront the acolytes who protect them.\n\nIn truth, these are not men. They are shadows, some of the Lich King's most frightening creatures. They can be revealed using the necrotic runes they carry, and then destroyed with magic or strength of arms.",
    isForever = false,
  },
  [5526] = {
    id = 5526,
    title = "Shards of the Felvine",
    reqLevel = 56,
    questLevel = 60,
    faction = "Both",
    zone = "Moonglade",
    npc = "Rabine Saturna",
    objectives = "Find the Felvine in Dire Maul and acquire a shard from it.  Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper.  Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.",
    rewards = "8,300 XP",
    tip = "Your knowledge of Eldre'Thalas - Dire Maul - in Feralas will now come into play, $N.  In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion.  Go there with all due haste and brave whatever challenges await you.\n\nThe Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin.  When he falls, capture whatever essence of the Felvine you can.  Seal it in the Reliquary, and bring it to me.\n\nGood luck, and Cenarion's speed.",
    isForever = false,
  },
  [4803] = {
