  [9114] = {
    id = 9114,
    title = "Shoulderpads of Faith",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Father Inigo Montoy",
    objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make Shoulderpads of Faith if you bring him the following: 1 Desecrated Shoulderpads, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides.",
    rewards = "Experience & Faction Reputation",
    tip = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    isForever = false,
  },
  [8689] = {
    id = 8689,
    title = "Shroud of Infinite Wisdom",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Keyl Swiftclaw",
    objectives = "Bring 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.",
    isForever = false,
  },
  [8694] = {
