  [8446] = {
    id = 8446,
    title = "Shrouded in Nightmare",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Epic Quests",
    npc = "Item: Nightmare Engulfed Object",
    objectives = "Find someone capable of deciphering the meaning behind the Nightmare Engulfed Object.\n\nPerhaps a druid of great power could assist you.",
    rewards = "9,950 XP",
    tip = "Corruption seeps from this object.\n\nThere may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.",
    isForever = false,
  },
  [5056] = {
    id = 5056,
    title = "Shy-Rotam",
    reqLevel = 53,
    questLevel = 60,
    faction = "Horde",
    zone = "Winterspring",
    npc = "Storm Shadowhoof",
    objectives = "Storm Shadowhoof at Bloodvenom Post in Felwood wants you to defeat Shy-Rotam.",
    rewards = "8,300 XP",
    tip = "In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam. Defeating the matriarch of the frostsabers would grant you much respect in the eyes of your fellow $r.\n\nGo again to the harsh wilds, and once there, gather sacred meat from the frostsabers. Find the stone of Shy-Rotam, and place it there. Placing the meat of her kin before her will summon Shy-Rotam, in anger.\n\nBe ready for her fury, and defeat her",
    isForever = false,
  },
  [8558] = {
    id = 8558,
    title = "Sickle of Unyielding Strength",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Warden Haro",
    objectives = "Bring 1 Qiraji Spiked Hilt, 2  Alabaster Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",
    isForever = false,
  },
  [8556] = {
    id = 8556,
    title = "Signet of Unyielding Strength",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Windcaller Yessendra",
    objectives = "Bring 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest.",
    rewards = "6,600 XP",
    tip = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, $c.",
    isForever = false,
  },
  [8348] = {
    id = 8348,
    title = "Signet of the Dukes",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Bor Wildmane",
    objectives = "Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.",
    rewards = "8,800 XP • 1g 80s",
    tip = "Huum tells me you've figured out how to summon the Abyssal Dukes!  That's quite an accomplishment.\n\nYou know what else would be quite the accomplishment?  Smashing up one of those things really good.  That'll cause an impression on their underlings, if you know what I mean.  Bring back its signet as proof of the deed.",
    isForever = false,
  },
