  [7221] = {
    id = 7221,
    title = "Speak with Prospector Stonehewer",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "Speak with Prospector Stonehewer in the Dun Baldar garrison.",
    rewards = "Experience & Faction Reputation",
    tip = "Ah, $N, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!\n\nSpeak with Prospector Stonehewer in Dun Baldar.  She's recruiting for a vital mission into enemy territory.  You'll find Stonehewer in the bottom of the Dun Baldar garrison.\n\nAnd keep an eye out as you go through Dun Baldar.  There's plenty to do for a hardworking $c who's not afraid to get $ghis:her; hands dirty.",
    isForever = false,
  },
  [7222] = {
    id = 7222,
    title = "Speak with Voggah Deathgrip",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "Speak with Voggah in Frostwolf Keep.",
    rewards = "Experience & Faction Reputation",
    tip = "A $c?  Good!  We are glad to see you in Alterac, $N.  Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!\n\nSpeak with Voggah Deathgrip.  He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!\n\nYou will find Voggah in Frostwolf Keep.",
    isForever = false,
  },
  [7123] = {
    id = 7123,
    title = "Speak with our Quartermaster",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Jotek",
    objectives = "Speak with the Frostwolf Quartermaster.",
    rewards = "650 XP",
    tip = "$N, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.",
    isForever = false,
  },
