  [1687] = {
    id = 1687,
    title = "Spooky Lighthouse",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Human Orphan",
    objectives = "- - Go to the Westfall Lighthouse.",
    rewards = "650 XP",
    tip = "Sometimes late at night, our matrons at the orphanage will tell us spooky stories.  Those RULE!  There's one about a ghost that haunts a lighthouse in Westfall.  They say he was a pirate captain who had his ship taken from him by other pirates.  Wow!\n\nCould you please take me to the lighthouse in Westfall?  I wanna see if the ghost of that captain is there!  I promise to stay close to you; I won't run off or anything!",
    isForever = false,
  },
