  [7583] = {
    id = 7583,
    title = "Suppression",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Daio the Decrepit",
    objectives = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\n\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\n\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.",
    rewards = "6,600 XP",
    tip = "The prison is ready. Now for the most difficult portion of this task.\n\nYou must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison.\n\nBe warned! A Doomguard is a cunning and lethal adversary and will seek to destroy you as you begin the ritual of imprisonment. It will flail wildly in its attempts to escape imprisonment.\n\nIt will focus on nothing but you, $N. Because of this, I must recommend that you take companions capable of keeping you alive!",
    isForever = false,
  },
  [5305] = {
    id = 5305,
    title = "Sweet Serenity",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Lilith the Lithe",
    objectives = "- Crimson Hammersmith's Apron",
    rewards = "8,300 XP",
    tip = "Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall reward you with the knowledge required to create an enchanted battlehammer!",
    isForever = false,
  },
  [8869] = {
    id = 8869,
    title = "Sweet Serenity",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Blacksmithing",
    npc = "Quest Event / Discovery",
    objectives = "- Crimson Hammersmith's Apron",
    rewards = "Experience & Faction Reputation",
    tip = "Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall train you to become a hammersmith.\n\nUnderstand this: Once you have chosen the path of the hammersmith, the paths of the swordsmith and axesmith will no longer be available.",
    isForever = false,
  },
  [8185] = {
    id = 8185,
    title = "Syncretist's Sigil",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Zul'Gurub",
    npc = "Zanza the Restless",
    objectives = "- Primal Hakkari Idol - Punctured Voodoo Doll",
    rewards = "Experience & Faction Reputation",
    tip = "Zanza can create the ancient troll enchantments with the right components. The first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo.\n\nBring me these things and I will create a powerful enchantment for you!",
    isForever = false,
  },
