  [8122] = {
    id = 8122,
    title = "Take Five Bases",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathmaster Dwire",
    objectives = "Hold five bases in Arathi Basin at the same time, then return to Deathmaster Dwire in Hammerfall.",
    rewards = "9,950 XP • 2g 70s",
    tip = "It is difficult to see, so deep we are in the conflict, but our spies report a weakening in the League of Arathor's resolve.  We must use this window and strike a brutal blow against them!  Return to Arathi Basin and throw yourself against our foes.  Curse them and kill them and control all five strategic bases!  Send their soldiers screaming and bleeding from the front lines, with stories of your cruelty on their mewling lips.\n\nDo this, and score a great victory for the Defilers.",
    isForever = false,
  },
  [8121] = {
    id = 8121,
    title = "Take Four Bases",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Arathi Basin",
    npc = "Deathmaster Dwire",
    objectives = "Hold four bases at the same time in Arathi Basin, and then return to Deathmaster Dwire in Hammerfall.",
    rewards = "9,950 XP • 2g 70s",
    tip = "$N, as the battles over Arathi Basin rage, news of your actions have reached many ears.  You are highly regarded among us, which gives me confidence that you will accomplish the mission I now have for you.\n\nIt is time to send a message to the League of Arathor.  We must show them that their holdings in Arathi Basin are tenuous and quickly lost.  We will show them this by holding, all at once, four strategic points in Arathi Basin.\n\nSucceed in this, $N, and earn great respect among the Defilers.",
    isForever = false,
  },
  [8292] = {
    id = 8292,
    title = "Talismans of Merit",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Battleground Officer",
    objectives = "You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward.",
    rewards = "",
    tip = "You have proven your value to our efforts in Warsong Gulch. Continue to aid the cause and bring me more talismans of merit. Do this, and you will earn even more of our trust.",
    isForever = false,
  },
  [8770] = {
