  [5213] = {
    id = 5213,
    title = "The Active Agent",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Betina Bigglezink",
    objectives = "- Scourge Data",
    rewards = "6,600 XP",
    tip = "You will have to delve deeper into Stratholme, $N.\n\nBeyond the first gates you will find the ziggurats. We know that the Scourge draws great power from these structures. Search the Ziggurats and return with any information that you may discover.",
    isForever = false,
  },
  [8052] = {
