  },
  [8509] = {
    id = 8509,
    title = "The Alliance Needs Arthas' Tears!",
    reqLevel = 34,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sergeant Major Germaine",
    objectives = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "I'll keep it simple and to the point, $c. The Alliance needs to collect a large quantity of Arthas' Tears for the Ahn'Qiraj war effort. Don't ask me what for; I'm just following orders. But I'd like you to gather up as many of the herbs as you can and bring them back to me here. Are you willing to do that?",
    isForever = false,
  },
  [8492] = {
    id = 8492,
    title = "The Alliance Needs Copper Bars!",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sergeant Stonebrow",
    objectives = "Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "Hey there, $c, you look fit enough to contribute to the war effort! We need all of the help that we can get here to put together the materiel needed for the Ahn'Qiraj War and it's your lucky day.\n\nI'm collecting copper bars in stacks of twenty. It's for a worthy cause, what do you say? Do you think you could help out the Alliance?",
    isForever = false,
  },
  [8494] = {
    id = 8494,
    title = "The Alliance Needs Iron Bars!",
    reqLevel = 40,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Corporal Carnes",
    objectives = "Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "Well hello there, $g Mr. : Ms.; Fancypants, aren't you a sight for sore eyes. In case you hadn't heard while you were out there \"adventuring\", the Alliance has been gearing up for a war in Ahn'Qiraj and is in need of iron bars... a whole mess of 'em. Bring them to me in stacks of twenty. We can count on you, right, $c?",
    isForever = false,
  },
  [8511] = {
    id = 8511,
    title = "The Alliance Needs Light Leather!",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Bonnie Stoneflayer",
    objectives = "Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "We Stoneflayers have a long history of being skinners, $c. That's why the Alliance has asked my family to help out with the collection of light leather for the Ahn'Qiraj war effort. I'm here to see to it that the leather is tanned correctly for whatever they want to put it to use for. But we need your help.\n\nSince I have to be here doing that, I need you to go out and collect the skins, returning them to me here. What do you say, $g lad : lass;, will you give it a go?",
    isForever = false,
  },
  [8512] = {
    id = 8512,
    title = "The Alliance Needs Light Leather!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Bonnie Stoneflayer",
    objectives = "Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Good to see you again $N. It does appear that we need more light leather for the creation of the various war materiel. If you could bring me a stack of ten that would be just perfect.",
    isForever = false,
  },
  [8517] = {
    id = 8517,
    title = "The Alliance Needs Linen Bandages!",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sentinel Silversky",
    objectives = "Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "The war at Ahn'Qiraj is going to be long and bloody. It is a very wise thing that the Alliance is doing by enlisting the aid of you, and those like you, to build up the materiel necessary before plunging headlong into conflict.\n\nI have been asked to head up the collection of linen bandages for the war, and I am hoping that you are going to assist me in amassing as many as we need. It is no light matter, but at least the linen bandages are the least difficult to create. Are you with us, $c?",
    isForever = false,
  },
  [8513] = {
    id = 8513,
    title = "The Alliance Needs Medium Leather!",
    reqLevel = 52,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Private Porter",
    objectives = "Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "Yes $g sir : ma'am;, I have been charged with collecting and tracking all of the medium leather gathered for the war effort. If you have the wherewithal to gather medium leather, from whatever source, then please bring them to me here. I sure would appreciate a hand with this if you can spare the time.",
    isForever = false,
  },
  [8510] = {
    id = 8510,
    title = "The Alliance Needs More Arthas' Tears!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sergeant Major Germaine",
    objectives = "Bring 20 arthas' tears to Sergeant Major Germaine at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Ok, so it looks like I still need more Arthas' Tears. I would imagine that you will be able to find them in the general location that you gathered them up for me last time. The quicker we get these, the faster we can start up the offensive against the forces at Ahn'Qiraj.\n\nYou gonna help us out again $c?",
    isForever = false,
  },
  [8493] = {
    id = 8493,
    title = "The Alliance Needs More Copper Bars!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sergeant Stonebrow",
    objectives = "Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Back again $c? Outstanding! We still need more stacks of copper bars if you can procure them for the Ahn'Qiraj war effort.  Will you help us out?",
    isForever = false,
  },
  [8495] = {
    id = 8495,
    title = "The Alliance Needs More Iron Bars!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Corporal Carnes",
    objectives = "Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Back so soon? Stop making me re-evaluate my low opinion of you $c, you're making me feel all gooey inside. So, as you can tell we still don't have enough iron bars for all of the weapons, armor, steam tanks and whatnot that need building for the bug hunt. Think you have it in you to bring back another stack of twenty iron bars in between all of those trips to Zul'Gurub, or wherever it is that you kids hang out these days?",
    isForever = false,
  },
  [8518] = {
    id = 8518,
    title = "The Alliance Needs More Linen Bandages!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sentinel Silversky",
    objectives = "Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Ever am I amazed by the selflessness exhibited when so many would instead turn to selfishness instead. $C, I am still in need of a number of linen bandages before my assignment here is fulfilled. Will you aid me once more in the collection of those bandages?",
    isForever = false,
  },
  [8514] = {
    id = 8514,
    title = "The Alliance Needs More Medium Leather!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Private Porter",
    objectives = "Bring 10 medium leather to Private Porter at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Yes $g sir : ma'am;, looks like we've collected $2063w pieces of medium leather to date. I know it's a lot to ask, but if you're still willing, I could use your help in attempting to put a dent in the rest of my quota.",
    isForever = false,
  },
  [8506] = {
    id = 8506,
    title = "The Alliance Needs More Purple Lotus!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Master Nightsong",
    objectives = "Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Welcome back $c. Our collection grows, but even now we have a need for additional purple lotus. If it is still within your power to gather more of the herb, I entreat you to do so and return them to me here.",
    isForever = false,
  },
  [8525] = {
    id = 8525,
    title = "The Alliance Needs More Rainbow Fin Albacore!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Slicky Gastronome",
    objectives = "Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "What! You again? Well I'll be a monkey's uncle... except that I'm a gnome. Slicky Gastronome to be precise! So you're back to help out again eh? Well, I can't say as I blame you. Don't you just love the smell of all of that food? <drool>\n\nEnough loitering! Get out there and bring me back more rainbow fin albacore!",
    isForever = false,
  },
  [8527] = {
    id = 8527,
    title = "The Alliance Needs More Roast Raptor!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sarah Sadwhistle",
    objectives = "Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Hi again $c. I can tell you're very excited about all of this. So I suppose you want to bring me another twenty roast raptor. Great. Well you do that. I guess I'll see you when you get back.",
    isForever = false,
  },
  [8523] = {
    id = 8523,
    title = "The Alliance Needs More Runecloth Bandages!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Keeper Moonshade",
    objectives = "Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "So it is that we come to discuss pressing matters yet again $c. Once more I thank you for your previous efforts; it is not everyone who would give so selflessly. But there is still more work to do.\n\n$N, will you once more collect runecloth bandages and return them to me here?",
    isForever = false,
  },
  [8521] = {
    id = 8521,
    title = "The Alliance Needs More Silk Bandages!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Nurse Stonefield",
    objectives = "Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "It is very kind of you to offer to help me again $c. It looks like we've collected $2082w silk bandages, so we'll need more.",
    isForever = false,
  },
  [8529] = {
    id = 8529,
    title = "The Alliance Needs More Spotted Yellowtail!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Huntress Swiftriver",
    objectives = "Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "If you're still willing I'd like to send you back out to bring in another haul of spotted yellowtail, $N. I'd imagine with the expertise you gained the first time out that this catch should be much faster and easier. Are you game?",
    isForever = false,
  },
  [8504] = {
    id = 8504,
    title = "The Alliance Needs More Stranglekelp!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Private Draxlegauge",
    objectives = "Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Well hello again there... what was it? Ah yes, $N! Come to see if I still need more stranglekelp have you? Well, it's your lucky day, because the answer to that very important question is a very affirmative YES! Think you could gather up twenty more?",
    isForever = false,
  },
  [8516] = {
    id = 8516,
    title = "The Alliance Needs More Thick Leather!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Marta Finespindle",
    objectives = "Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "Yep, the stack's still not high enough. $N, we still haven't reached our goal of $2071w thick leather. Just think of all the things that we can make with all of that leather! All kinds of armor and weapons. Stuff for inside the steam tanks and rifle scopes! Engineering goggles, and I bet if it ends up that we collect too much we could give the rest to the Horde for their zeppelins!\n\nYou gonna bring me back some more thick leather?",
    isForever = false,
  },
  [8500] = {
    id = 8500,
    title = "The Alliance Needs More Thorium Bars!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Alliance",
    zone = "Battlegrounds",
    npc = "Dame Twinbraid",
    objectives = "Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh.",
    rewards = "Experience & Faction Reputation",
    tip = "It is so good to see you again $N. I hope that you've been doing well. It's true that we are still in need of thorium bars. If you have them to spare I am collecting them for the Ahn'Qiraj war effort.",
    isForever = false,
  },
  [8505] = {
    id = 8505,
    title = "The Alliance Needs Purple Lotus!",
    reqLevel = 37,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Master Nightsong",
    objectives = "Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "$C, the purple lotus is a flower with a plentitude of uses. I am here at the request of the Alliance as an authority on those applications, to preserve the herbs collected and to ensure that their war effort acquires enough purple lotus to sustain whatever function they plan for it.\n\nI would like for you to travel out into the world and return to me with some of these flowers. Is that something that you can do?",
    isForever = false,
  },
  [8524] = {
    id = 8524,
    title = "The Alliance Needs Rainbow Fin Albacore!",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Slicky Gastronome",
    objectives = "Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "Hey there, friend! If I were to say to you, 'Don't you think that soldiers should have food to eat like anyone else?', you would of course reply, 'yes'. I agree with you 110%! I'm glad we're in accord. All I need for you to do is to head out there, fish up a whole bunch of raw rainbow fin albacore, and then cook it all up and bring it back to me right here. Mmm, mmm, I can taste it already.",
    isForever = false,
  },
  [8526] = {
    id = 8526,
    title = "The Alliance Needs Roast Raptor!",
    reqLevel = 33,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sarah Sadwhistle",
    objectives = "Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "Oh, how's it going, $c? I see that you're interested in maybe gathering up food for the coming war at Ahn'Qiraj? Somehow my dad thought that it would be a good learning experience for me if I were to volunteer to help out here. Big mistake. I don't even like to eat meat.\n\nAnyway, if you feel like it, you could bring me back a lot of roast raptor. Apparently that's what all of the soldiers are going to want.",
    isForever = false,
  },
  [8522] = {
    id = 8522,
    title = "The Alliance Needs Runecloth Bandages!",
    reqLevel = 56,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Keeper Moonshade",
    objectives = "Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "Argue the merits of the war if you will, $c, but it has already been set in motion. Look around you at your family and friends, and then ask yourself what it is that you can do to see to it that if they are involved, they will have every advantage to survive the conflagration.\n\nTo that end, I am collecting runecloth bandages here from whatever source. Would you like to make a donation?",
    isForever = false,
  },
  [8520] = {
    id = 8520,
    title = "The Alliance Needs Silk Bandages!",
    reqLevel = 43,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Nurse Stonefield",
    objectives = "Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "With the Ahn'Qiraj War looming we need to do everything that we can to see to it that our soldiers have everything that they need. We're doing just that right here. For my part I've been placed in charge of seeing to it that we collect enough silk bandages.\n\nDo you think you can help me out, $c?",
    isForever = false,
  },
  [8528] = {
    id = 8528,
    title = "The Alliance Needs Spotted Yellowtail!",
    reqLevel = 42,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Huntress Swiftriver",
    objectives = "Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "It may not seem heroic to gather up cooked fish, but do not underestimate the value of preparation, young $c. Soldiers need to eat like anyone else, and we're here to do our part to make sure they have what they need once the war in Ahn'Qiraj commences.\n\nAccordingly, I am stockpiling spotted yellowtail, a versatile source of sustenance that stores well and can be used in many different dishes. It also doesn't have the odor of some other saltwater fish. Are you willing to aid me in this endeavor?",
    isForever = false,
  },
  [8503] = {
    id = 8503,
    title = "The Alliance Needs Stranglekelp!",
    reqLevel = 37,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Private Draxlegauge",
    objectives = "Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "So, $c, did I already tell you about all of the fabulous uses stranglekelp has? I did? Oh well... in any case we need a lot of it, and when I say a lot, I mean A LOT! Do you think that you could help us out? I know that it means going without all of those wonderful things that you can make with it, but it's for a good cause!",
    isForever = false,
  },
  [8515] = {
    id = 8515,
    title = "The Alliance Needs Thick Leather!",
    reqLevel = 44,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Marta Finespindle",
    objectives = "Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "Oh boy, this is going to be great! $C, the Ahn'Qiraj war effort is in full swing, and I've been put in charge of keeping track of all of the thick leather that comes in. We'll make tons of things with it, but first we need to get a ton of it. And I mean that literally! That's where you come in.\n\nSo, do you think you can go out there and bring me back a nice, fat stack of thick leather? Do yah, do yah?!",
    isForever = false,
  },
  [8499] = {
    id = 8499,
    title = "The Alliance Needs Thorium Bars!",
    reqLevel = 48,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Dame Twinbraid",
    objectives = "Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge.",
    rewards = "Experience & Faction Reputation",
    tip = "It is very kind of you to inquire about the needs that the Alliance has. In addition to all of the other collection efforts underway, we are in need of a great quantity of thorium bars, which is the task that I am in charge of. The thorium will be used in the creation of many different things for the war, foremost of which is the construction of a battalion of steam tanks to be airlifted into Silithus as soon as they are completed. Can you aid us in this endeavor, $c?",
    isForever = false,
  },
  [8795] = {
    id = 8795,
    title = "The Alliance Needs Your Help!",
    reqLevel = 49,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Master Sergeant Maclure",
    objectives = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.",
    rewards = "660 XP",
    tip = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, $c? Will you help out with the vital preparations?",
    isForever = false,
  },
  [8796] = {
    id = 8796,
    title = "The Alliance Needs Your Help!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Quest Event / Discovery",
    objectives = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.",
    rewards = "660 XP",
    tip = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, $c? Will you help out with the vital preparations?",
    isForever = false,
  },
  [8797] = {
    id = 8797,
