    tip = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, $c? Will you help out with the vital preparations?",
    isForever = false,
  },
  [7632] = {
    id = 7632,
    title = "The Ancient Leaf",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Hunter Class Quests",
    npc = "Item: Ancient Petrified Leaf",
    objectives = "Find the owner of the Ancient Petrified Leaf. Good luck, <player>; It's a big world.",
    rewards = "9,950 XP",
    tip = "The epidermis of the leaf glows a bright green. The surface is extremely rugose, exposing several veins and wrinkles.\n\nIf you had to take a guess, you would say this leaf came from something ancient and powerful.\n\nMaybe you should find the original owner of this leaf?",
    isForever = false,
  },
  [7500] = {
    id = 7500,
    title = "The Arcanist's Cookbook",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Item: The Arcanist's Cookbook",
    objectives = "Return the book to its rightful owners.",
    rewards = "7,050 XP",
    tip = "The tome carries the mark of the Athenaeum.",
    isForever = false,
  },
  [7366] = {
    id = 7366,
    title = "The Archbishop's Mercy",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "You have been tasked with slaying opposing Forsaken players in Alterac Valley.\n\nKill a Forsaken and return to Commander Karl Philips (who wanders between the lumber mill and the mine) with a Forsaken Heart.",
    rewards = "6,600 XP, 1g 80s",
    tip = "The Archbishop is as kind as he is wise. For a man to look mercifully on such a wretched lot...\n\n<Commander Philips shakes his head in disbelief.>\n\nToo kind... Just too kind.\n\nThe Archbishop asks that we take pity on the undead and grant them swift and permanent deaths. For this grand display of mercy, we merely require their black, disease ridden hearts.\n\nBring me the hearts of the Forsaken so that they may be ceremoniously incinerated at the Cathedral of Light. Make haste, $N!",
    isForever = false,
  },
  [5251] = {
    id = 5251,
    title = "The Archivist",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Duke Nicholas Zverenhoff",
    objectives = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.",
    rewards = "8,300 XP • 1g 80s",
    tip = "Anything taken to an extreme is hazardous to our world, $N. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?\n\nBlasphemers, one and all!\n\nOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded.",
    isForever = false,
  },
  [5265] = {
    id = 5265,
    title = "The Argent Hold",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Lord Maxwell Tyrosus",
    objectives = "Open the Argent Hold and claim your reward.",
    rewards = "9,950 XP • 2g 70s",
    tip = "Through the years the Argent Hold has remained locked. None have been worthy to reach inside and take from it the power of the Argent Dawn - until today.\n\nThe Argent Hold is now open to you, $N.",
    isForever = false,
  },
  [7622] = {
    id = 7622,
    title = "The Balance of Light and Shadow",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Priest Class Quests",
    npc = "Eris Havenfire",
    objectives = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain.",
    rewards = "9,950 XP",
    tip = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.\n\nThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.\n\nEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, $N.",
    isForever = false,
  },
  [7142] = {
    id = 7142,
    title = "The Battle for Alterac",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Voggah Deathgrip",
    objectives = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike.  Then, return to Voggah Deathgrip in the Alterac Mountains.",
    rewards = "9,950 XP",
    tip = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, $N, and then return to me.",
    isForever = false,
  },
  [7141] = {
    id = 7141,
    title = "The Battle of Alterac",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Prospector Stonehewer",
    objectives = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains.",
    rewards = "9,950 XP",
    tip = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.",
    isForever = false,
  },
  [5721] = {
    id = 5721,
    title = "The Battle of Darrowshire",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Chromie",
    objectives = "Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.",
    rewards = "8,300 XP",
    tip = "Now, $N, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.",
    isForever = false,
  },
  [6186] = {
    id = 6186,
    title = "The Blightcaller Cometh",
    reqLevel = 56,
    questLevel = 60,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Flint Shadowmore",
    objectives = "Return to Stormwind and inform Highlord Bolvar Fordragon of the fate of Nathanos Marris.",
    rewards = "6,600 XP",
    tip = "<The blood appears to have completely drained from Flint's face.>\n\nNa... Nathanos did this? Nathanos is the Blightcaller?\n\nWhy? He was... was so noble - a ranger lord respected by all. The only human ever allowed to train under the high elves. Now a ruthless agent of the Forsaken?\n\nI... I am sorry to ask this of you, $N, but Highlord Fordragon must be informed of this turn of events at once. Please, return to Stormwind and deliver the news.",
    isForever = false,
  },
  [1479] = {
    id = 1479,
    title = "The Bough of the Eternals",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Human Orphan",
    objectives = "Take the orphan to the bank of Darnassus.  The bank itself is hollowed out of a tree known as the Bough of the Eternals.",
    rewards = "650 XP",
    tip = "I've heard stories about how the night elves have their bank in a tree - one that looks like a bear!  That's so cool!  Night elves are neat how they like nature and stuff, but bears are just totally awesome!\n\nWould you take me to see the bear-tree in Darnassus, please?  There's a boat that will take us close to there, and it shouldn't take very long.  Please, please, please!",
    isForever = false,
  },
  [8484] = {
    id = 8484,
    title = "The Brokering of Peace",
    reqLevel = 45,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Item: Timbermaw Offering of Peace",
    objectives = "Bring the Timbermaw Offering of Peace to King Magni Bronzebeard in Ironforge.",
    rewards = "9,950 XP",
    tip = "Your deeds go beyond the tale of a simple hero, $N.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the dwarven king that resides in a mountain of iron; I believe you call this city Ironforge.  In times past, he had tried to make contact with us on behalf of his Alliance.  It is now only fitting to acknowledge you as the key in your Alliance's efforts in brokering peace.",
    isForever = false,
  },
  [8485] = {
    id = 8485,
    title = "The Brokering of Peace",
    reqLevel = 45,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Gorn One Eye",
    objectives = "Bring the Timbermaw Offering of Peace to Thrall in Orgrimmar.",
    rewards = "9,950 XP",
    tip = "Your deeds go beyond the tale of a simple hero, $N.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the orcish warchief that resides in the lands of Durotar; I believe you call this city Orgrimmar.  In times past, he had tried to make contact with us on behalf of his Horde.  It is now only fitting to acknowledge you as the key in your Horde's efforts in brokering peace.",
    isForever = false,
  },
  [6144] = {
    id = 6144,
    title = "The Call to Command",
    reqLevel = 56,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "Travel to the Undercity and speak with Varimathras.",
    rewards = "660 XP",
    tip = "The order has come down, $c. Varimathras himself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to Varimathras. Do not embarrass me, $c!",
    isForever = false,
  },
  [8315] = {
    id = 8315,
    title = "The Calling",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Geologist Larksbane",
    objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.\n\nYou have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.\n\nAssemble an army for this task, <player>!",
    rewards = "9,950 XP",
    tip = "The glyphs illustrate an emissary of the Qiraji meeting with three silithid at the bones of a large dragon. Above the glyphs is what I can only assume to be a code of some sort. This code might very well be the key to summoning the emissary.\n\nI will create a copy of the glyph code that you must use in the sand at the Bones of Grakkarond. If I am right, the Overlords will come thinking that new data is ready for transmission. Strike them down and confront the emissary. He holds the key to the cry",
    isForever = false,
  },
  [9015] = {
    id = 9015,
    title = "The Challenge",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Depths",
    npc = "Falrin Treeshaper",
    objectives = "Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone.  Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet.",
    rewards = "6,600 XP",
    tip = "Heed me well, $N.  For the banner to work in the desired way, you will need to step into the Ring of the Law in Blackrock Depths.  Allow yourself to be sentenced by High Justice Grimstone and place the banner firmly on the ground in a sign of defiance.\n\nYour victim will not be able to restrain himself and shall enter the fray filled with a desire to fight you.  Once you obtain that which you seek, go back to Anthion.",
    isForever = false,
  },
  [8741] = {
    id = 8741,
    title = "The Champion Returns",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Moonglade",
    npc = "Keeper Remulos",
    objectives = "Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris.",
    rewards = "6,600 XP",
    tip = "The keeper awaits your return, $N. Take the green scepter shard to Anachronos at the Caverns of Time.",
    isForever = false,
  },
  [6567] = {
    id = 6567,
    title = "The Champion of the Horde",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Thrall",
    objectives = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas.",
    rewards = "3,300 XP",
    tip = "I have received word from one of my champions that a way into the lair of the dragon may exist. You are to seek him out.\n\nRexxar wanders the desert wasteland of Desolace, traveling between Stonetalon and Feralas. He awaits your arrival.",
    isForever = false,
  },
  [8766] = {
    id = 8766,
    title = "The Changing of Paths - Conqueror No More",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Anachronos",
    objectives = "- Signet Ring of the Bronze Dragonflight - Bone Scarab x 15 - Ivory Scarab x 15 - Stone Scarab x 15",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [8765] = {
    id = 8765,
    title = "The Changing of Paths - Invoker No More",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
