  [6136] = {
    id = 6136,
    title = "The Corpulent One",
    reqLevel = 56,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.",
    rewards = "6,600 XP • 90s",
    tip = "Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor. Borelgore has been known to devour others who tried to hunt him.",
    isForever = false,
  },
  [2743] = {
    id = 2743,
    title = "The Cover of Darkness",
    reqLevel = 45,
    questLevel = 60,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Spirit of Kirith",
    objectives = "Return to the Fallen Hero of the Horde with your findings.",
    rewards = "3,300 XP",
    tip = "Let us not mince words, $r; my time here is limited.\n\nYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.\n\n<Kirith grins.>\n\nYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.\n\nReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.",
    isForever = false,
  },
  [6145] = {
    id = 6145,
    title = "The Crimson Courier",
    reqLevel = 56,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Varimathras",
    objectives = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\n\nTake the command to Nathanos Blightcaller for further instruction.",
    rewards = "6,600 XP",
    tip = "Just as the body cannot survive without the head, the head cannot survive without the body. The defenses of the Scarlet Crusade's command inside Stratholme are almost impenetrable. We must, instead, cut the body out from under the head.\n\nMy Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, $r! Find the Crimson Courier and recover that report. Return it to Natha",
    isForever = false,
  },
  [7905] = {
    id = 7905,
    title = "The Darkmoon Faire",
    reqLevel = 6,
    questLevel = 60,
    faction = "Alliance",
    zone = "Ironforge",
    npc = "Melnan Darkstone",
    objectives = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival.",
    rewards = "660 XP",
    tip = "The Darkmoon Faire is coming!  Be sure to experience all the wonders and excitement of it when it comes to town!\n\nIf you act right now, you can redeem this voucher for free prize tickets!  Just hand your voucher to Gelvas Grimgate located inside the carnival.\n\nRight now, the Faire is outside Goldshire, in the Elwynn Forest.  Don't miss out!  Go today!",
    isForever = false,
  },
  [7926] = {
    id = 7926,
    title = "The Darkmoon Faire",
    reqLevel = 6,
    questLevel = 60,
    faction = "Horde",
    zone = "Orgrimmar",
    npc = "Kruban Darkblade",
    objectives = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival.",
    rewards = "660 XP",
    tip = "The Darkmoon Faire is coming!  Be sure to experience all the wonders and excitement of it when it comes to town!\n\nIf you act right now, you can redeem this voucher for free prize tickets!  Just hand your voucher to Gelvas Grimgate located inside the carnival.\n\nRight now, the Faire is just outside Thunder Bluff, in Mulgore.  Don't miss out!  Go today!",
    isForever = false,
  },
  [8258] = {
    id = 8258,
    title = "The Darkreaver Menace",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Shaman Class Quests",
    npc = "Sagorne Creststrider",
    objectives = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth spirits you must fight.  Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.\n\nBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.",
    rewards = "9,950 XP",
    tip = "Death Knight Darkreaver lords over the Great Ossuary in the Scholomance.  He threatens to twist the spirit realm to do his own bidding, and he must be stopped!  This is where the scryer you helped make comes into play.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions.  Defeat the spirits and the death knight himself will appear.  $N, bring me his head!  Only his demise will reverse the damage done to the spirit realm!",
    isForever = false,
  },
  [4768] = {
    id = 4768,
    title = "The Darkstone Tablet",
    reqLevel = 57,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Shadowmage Vivian Lagrave",
    objectives = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.",
    rewards = "8,300 XP • 2g 70s",
    tip = "The Darkstone Tablet holds the writings of the long-dead dwarf Urheld Darkstone.  An alchemist of great skill, he was thought insane by his contemporaries and, hence, did not share his research.\n\nBut he did etch it onto tablets, and I believe one such tablet lies in Blackrock Spire, in a chamber once named the Hall of Fortune.  I know not what it is now called, for few enter Blackrock and return.\n\nBut if you are willing to brave its dangers and return to me with the tablet, your reward will be g",
    isForever = false,
  },
  [5127] = {
    id = 5127,
    title = "The Demon Forge",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Lorax",
    objectives = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\n\nYou must also find the Unforged Rune Covered Breastplate.\n\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.",
    rewards = "8,300 XP",
    tip = "Lorax makes deals, he does not accept them from insignificant mortals.\n\nA deal I shall make with you, however... take this pike, it is imbued with powerful Fel energies. When you find Goraluk Anvilcrack, slay him and drive this pike through his dying heart. His soul he bartered, his soul I shall have. Return the pike and return the breastplate that the thief stole and I shall teach you what it is that he was to learn.",
    isForever = false,
  },
  [2744] = {
    id = 2744,
    title = "The Demon Hunter",
    reqLevel = 45,
    questLevel = 60,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Fallen Hero of the Horde",
    objectives = "Speak with Loramus Thalipedes in Azshara.",
    rewards = "6,600 XP",
    tip = "The triad is protected by Razelikh.\n\nIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.\n\nThere is one who may be able to assist you further, $N. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the isl",
    isForever = false,
  },
  [7646] = {
    id = 7646,
    title = "The Divination Scryer",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Lord Grayson Shadowbreaker",
    objectives = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",
    rewards = "3,300 XP",
    tip = "We now must assemble a Divination Scryer - this will begin the trial that will allow you to redeem the fallen charger.  Your scryer, actually, is almost done.  The exorcism censer used in Terrordale is the catalyst for it, and I will fashion a suitable housing for the device.\n\nThe last components needed, though, are two diamonds.  They must be as juxtaposed in brilliance as they are in purpose - an Azerothian and a Pristine Black.  These two will be the beacon by which the scryer will pierce the",
    isForever = false,
  },
  [6501] = {
    id = 6501,
    title = "The Dragon's Eye",
    reqLevel = 50,
    questLevel = 60,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Highlord Bolvar Fordragon",
    objectives = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.",
    rewards = "6,600 XP",
    tip = "A fragment of the shattered medallion is all that I can offer.\n\nYou must find another of dragon blood willing to assist you in forging a new key. Once you secure this key, you must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find her lair, $N.\n\nWhere to find other flights willing to help? Sadly, I do not know... They are said to exist. Some may even work and live among us, disguised as one of the humanoid races. I wish you luck.",
    isForever = false,
  },
  [9121] = {
    id = 9121,
    title = "The Dread Citadel - Naxxramas",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Archmage Angela Dosantos",
    objectives = "- Arcane Crystal x 5 - Nexus Crystal x 2 - Righteous Orb - Argent Dawn: - Money:60",
    rewards = "Experience & Faction Reputation",
    tip = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via arcane cloaking - an old cantrip of the Kirin Tor with a few modifications of my own. Since your dedication to the cause of the Dawn is somewhat lacking, $N, the price will be high. You may decline and choose to return when you are revered or exalted for a d",
    isForever = false,
  },
  [9122] = {
    id = 9122,
    title = "The Dread Citadel - Naxxramas",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Archmage Angela Dosantos",
    objectives = "- Arcane Crystal x 2 - Nexus Crystal - Argent Dawn: - Money:30",
    rewards = "Experience & Faction Reputation",
    tip = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly. Since your dedication to the cause of the Dawn is admirable, we are willing to incur some of those costs.",
    isForever = false,
  },
  [9123] = {
    id = 9123,
    title = "The Dread Citadel - Naxxramas",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Archmage Angela Dosantos",
    objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.",
    rewards = "Experience & Faction Reputation",
    tip = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.",
    isForever = false,
  },
  [5462] = {
    id = 5462,
    title = "The Dying, Ras Frostwhisper",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Magistrate Marduke",
    objectives = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.",
    rewards = "4,950 XP",
    tip = "Upon tainted soil, the keepsake must be attuned.\n\nIt is rumored that Stratholme is where Frostwhisper succumbed to the Lich King. Upon those bloodied grounds he gave his life - freely and with motive - to become one of the undying.\n\nIt is those grounds that must be found.\n\nThere is one, an undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the cause of the Argent Dawn. Find him: Leonid Barthalomew the Revered. He may know more. Seek out Light's Hope, $N.",
    isForever = false,
  },
  [6185] = {
    id = 6185,
    title = "The Eastern Plagues",
    reqLevel = 56,
    questLevel = 60,
    faction = "Alliance",
    zone = "Eastern Plaguelands",
    npc = "Flint Shadowmore",
    objectives = "Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.",
    rewards = "8,300 XP",
    tip = "As I said, your first mission is one of reconnaissance. Nothing fancy, $N. You must travel to the Eastern Plaguelands and look for any clues as to this Blightcaller.\n\nBe on the lookout for information about our missing operatives. We have to assume that they are dead and if they are dead, they must have a corpse... somewhere.\n\n<Flint swallows hard.>\n\nAll SI:7 agents carry this insignia.\n\n<Flint shows you his SI:7 insignia.>\n\nBring any of those that you may find back to me.",
    isForever = false,
  },
  [8921] = {
    id = 8921,
    title = "The Ectoplasmic Distiller",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Mux Manascrambler",
    objectives = "Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.",
    rewards = "6,600 XP",
    tip = "Ah, you're in need of my latest project... the extra-dimensional ghost revealer!  Unfortunately I've run out of funds and manpower.\n\nYou're willing to help?  Excellent!  Our first task is to build a device to harvest the very fabric of death!  Building an ectoplasmic distiller won't be an easy task, $N.\n\nI'll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I'll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter.",
    isForever = false,
  },
  [9128] = {
    id = 9128,
    title = "The Elemental Equation",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Archmage Angela Dosantos",
    objectives = "- Core of Elements x 30",
    rewards = "6,600 XP",
    tip = "Greetings, adventurer! Are you interested in some work? I pay those under my employ with insignias. These insignias can be used at the Quartermaster to purchase items of power.\n\nAll I need you to do is bring me as many core of elements as you can carry. The more the better!\n\nYou'll find them on elementals of varying shapes and sizes that exist across our world.",
    isForever = false,
  },
  [7506] = {
    id = 7506,
    title = "The Emerald Dream...",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Item: The Emerald Dream",
    objectives = "Return the book to its rightful owners.",
    rewards = "7,050 XP",
    tip = "The tome carries the mark of the Athenaeum.",
    isForever = false,
  },
  [7167] = {
    id = 7167,
    title = "The Eye of Command",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Warmaster Laggrond",
    objectives = "- Frostwolf Insignia Rank 5",
    rewards = "9,950 XP",
    tip = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander $N.\n\n<Warmaster Laggrond salutes>",
    isForever = false,
  },
  [7172] = {
    id = 7172,
    title = "The Eye of Command",
    reqLevel = 51,
    questLevel = 60,
    faction = "Both",
    zone = "Alterac Valley",
    npc = "Lieutenant Haggerdin",
    objectives = "- Stormpike Insignia Rank 5",
    rewards = "9,950 XP",
    tip = "It is good to see you again, $C. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, $N. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.",
    isForever = false,
  },
