  [9120] = {
    id = 9120,
    title = "The Fall of Kel'Thuzad",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Item: The Phylactery of Kel'Thuzad",
    objectives = "Take the Phylactery of Kel'Thuzad to Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "9,950 XP",
    tip = "The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason.\n\nSomeone at Light's Hope will pay you hugely for this artifact. Who cares if Kel'Thuzad regenerates to full power?",
    isForever = false,
  },
  [8791] = {
    id = 8791,
    title = "The Fall of Ossirian",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ruins of Ahn'Qiraj",
    npc = "Item: Head of Ossirian the Unscarred",
    objectives = "Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus.",
    rewards = "9,950 XP",
    tip = "A terrible menace has been laid to rest. The cruel Ossirian has been vanquished.\n\nThe denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.",
    isForever = false,
  },
  [9229] = {
    id = 9229,
    title = "The Fate of Ramaladni",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Korfax, Champion of the Light",
    objectives = "Enter Naxxramas and uncover the Fate of Ramaladni.",
    rewards = "Experience & Faction Reputation",
    tip = "Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.\n\nUnderstand this, $N, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.\n\nEnter Naxxramas and find what became of Ramaladni.",
    isForever = false,
  },
  [7061] = {
    id = 7061,
    title = "The Feast of Winter Veil",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Sagorne Creststrider",
    objectives = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff.",
    rewards = "650 XP",
    tip = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Cairne Bloodhoof in Thunder Bluff.  I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.",
    isForever = false,
  },
  [7063] = {
    id = 7063,
    title = "The Feast of Winter Veil",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Historian Karnik",
    objectives = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge.",
    rewards = "650 XP",
    tip = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to King Magni Bronzebeard.  I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.",
    isForever = false,
  },
  [9367] = {
    id = 9367,
    title = "The Festival of Fire",
    reqLevel = 1,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Quest Event / Discovery",
    objectives = "- Flame of Stormwind - Flame of Ironforge - Flame of Darnassus",
    rewards = "Experience & Faction Reputation",
    tip = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!",
    isForever = false,
  },
  [9368] = {
    id = 9368,
    title = "The Festival of Fire",
    reqLevel = 1,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Festival Talespinner",
    objectives = "Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.",
    rewards = "660 XP",
    tip = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!",
    isForever = false,
  },
  [6182] = {
    id = 6182,
    title = "The First and the Last",
    reqLevel = 56,
    questLevel = 60,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Highlord Bolvar Fordragon",
    objectives = "Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks.",
    rewards = "660 XP",
    tip = "Nathanos Marris was the first and last of the human ranger lords. A disciple of Sylvanas Windrunner, now the Banshee Queen of the Forsaken.\n\nWe had thought that Nathanos had been killed in action in the defense of Lordaeron five years ago. Although his corpse was never recovered, it was assumed that he did not make it out of the Eastern Plaguelands.\n\nMathias Shaw has been investigating the disappearance and may have some new information. Report to him at once. He resides in Old Town, at the Barr",
    isForever = false,
  },
  [5212] = {
    id = 5212,
    title = "The Flesh Does Not Lie",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Betina Bigglezink",
    objectives = "- Plagued Flesh Sample x 20",
    rewards = "6,600 XP, 1g 80s",
    tip = "The Forsaken apothecaries are not the only beings in this world schooled in the sciences.\n\nI have been studying the plague for years, $r. We had previously thought that the potency of the plague was dwindling, but what I have discovered here in the Plaguelands is startling. The plague seems to be growing in strength!\n\nI need to run more tests! The most potent source of the plague is from the tainted flesh of the most recently infected. Travel to Stratholme and bring me samples, $N.",
    isForever = false,
  },
  [7508] = {
    id = 7508,
    title = "The Forging of Quel'Serrar",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Lorekeeper Lydros",
    objectives = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.",
    rewards = "Experience & Faction Reputation",
    tip = "If you wish to take on this task, present Lydros with the dull blade.",
    isForever = false,
  },
  [7509] = {
    id = 7509,
    title = "The Forging of Quel'Serrar",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Onyxia's Lair",
    npc = "Lorekeeper Lydros",
    objectives = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.",
    rewards = "9,950 XP",
    tip = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade",
    isForever = false,
  },
  [8538] = {
    id = 8538,
    title = "The Four Dukes",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Item: Tactical Task Briefing V",
    objectives = "Find a way to summon and slay the Duke of Cynders, the Duke of Fathoms, the Duke of Zephyrs and the Duke of Shards and report back to Commander Mar'alith in Cenarion Hold.  You must also bring Tactical Task Briefing V in order to complete this quest.",
    rewards = "650 XP",
    tip = "The links between the Twilight's Hammer and the Abyssal Council are proving to be more important than we had expected.\n\nWe believe the elemental nobles known as the Abyssal Dukes are one of the primary force organizing the Twilight's Hammer cultists.  Find a way to lure the four Abyssal Dukes into our plane of existence and destroy them!\n\nYour dedication and prowess in past assignments have led us to choose you for this particular assignment.  We are certain you will succeed in this endeavor.",
    isForever = false,
  },
  [8728] = {
    id = 8728,
    title = "The Good News and The Bad News",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Narain Soothfancy",
    objectives = "Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires.",
    rewards = "6,600 XP",
    tip = "Well that took a little longer than expected. Now let me see what this ledger says.\n\n<Narain silently reads the ledger, periodically mumbling under his breath.>\n\n The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.\n\nThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.\n\nBring me what I need and I will craft the buoy.",
    isForever = false,
  },
  [5518] = {
    id = 5518,
    title = "The Gordok Ogre Suit",
    reqLevel = 56,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Knot Thimblejack",
    objectives = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack.  He is currently chained inside the Gordok wing of Dire Maul.",
    rewards = "6,600 XP",
    tip = "If you're going to fight the king of this dump - and I think that's what you're bound to do - then you're going to need to get by Captain Kromcrush.  Now, you can get by him by killing him, sure.  You might actually want to leave him alive.\n\nHow, you ask?  Since I've been here, I think I know how to make an ogre suit that will last just long enough to fool these bozos.  The only problem is stability - ten minutes tops.  Bring me what I need, and I'll make you one.  I'm not going anywhere...",
    isForever = false,
  },
