  [7082] = {
    id = 7082,
    title = "The Graveyards of Alterac",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Corporal Teeka Bloodsnarl",
    objectives = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",
    rewards = "6,600 XP",
    tip = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, $N, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.",
    isForever = false,
  },
  [5214] = {
    id = 5214,
    title = "The Great Fras Siabi",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Smokey LaRue",
    objectives = "- Grimm's Premium Tobacco",
    rewards = "8,300 XP",
    tip = "Terrible thing... what happened to Fras. You see, the town was sacked and Fras didn't want to leave his precious goods behind. The last thing I remember him saying was, 'I'll burn every last leaf before they get their damned, dirty hands on them!'\n\nI may love a good stogie but I'm no fool. I left Fras and his delightful store that day. I assume he went down in flames but if there's a chance that even one box of his famous tobacco is still intact...\n\nWhat do you say, $N? Find a box for ol' Smokey",
    isForever = false,
  },
  [27] = {
    id = 27,
    title = "The Great Masquerade",
    reqLevel = 54,
    questLevel = 60,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Turak Runetotem",
    objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
    rewards = "115 XP",
    tip = "Pro-tip: Let Highlord Bolvar Fordragon tank the elite dragonkin guards inside Stormwind Keep!",
    isForever = false,
  },
  [6403] = {
    id = 6403,
    title = "The Great Masquerade",
    reqLevel = 50,
    questLevel = 60,
    faction = "Alliance",
    zone = "Stormwind City",
    npc = "Reginald Windsor",
    objectives = "Follow Reginald Windsor through Stormwind. Protect him from harm!",
    rewards = "9,950 XP",
    tip = "It has been quite the adventure, friend. I owe you a great debt of gratitude. Perhaps, when all is said and done...\n\nAs you have no doubt ascertained by now, Lady Prestor is Onyxia: Brood of Deathwing, twin to the tyrant of the Spire, Nefarian.\n\nFor too long she has held our kingdom in her captivating gaze. Even the Highlord is controlled by her trickery - a puppet. It all ends today... The spell will be broken.\n\nWorry not, for together, we shall be victorious!\n\nAre you ready?",
    isForever = false,
  },
