  [8763] = {
    id = 8763,
    title = "The Hero of the Day",
    reqLevel = 40,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Wulmort Jinglepocket",
    objectives = "Bring 1 Deeprock Salt and 5 gold coins to any Holly Preserver machine, upon which you will receive 5 Preserved Holly.",
    rewards = "Experience & Faction Reputation",
    tip = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep",
    isForever = false,
  },
  [8799] = {
    id = 8799,
    title = "The Hero of the Day",
    reqLevel = 40,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Kaymard Copperpinch",
    objectives = "Bring 1 Deeprock Salt and 5 gold coins to the Holly Preserver machine, upon which you will receive 5 Preserved Holly.",
    rewards = "Experience & Faction Reputation",
    tip = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep",
    isForever = false,
  },
  [8048] = {
