  [8615] = {
    id = 8615,
    title = "The Horde Needs Baked Salmon!",
    reqLevel = 20,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Chief Sharpclaw",
    objectives = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "The Ahn'Qiraj war effort is an immense undertaking, $c. All of the materials being gathered here, whether it is metal for weapons, or food to eat, are all as important as the other. For, if you haven't eaten in days you will not have the strength to lift your axe when it matters.\n\nThus, we gather what food we can. I am collecting baked salmon, a dish that was chosen both for its sustenance and its ability to keep well. Can you aid me with this task, $c?",
    isForever = false,
  },
  [8532] = {
    id = 8532,
    title = "The Horde Needs Copper Bars!",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Miner Cromwell",
    objectives = "Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "So glad that you've decided to help out here. Not everyone would, so I need to make sure you understand what it is that I need. Copper bars, not copper ore. We don't have the time or people to do all of the smelting ourselves, so if you would be so kind as to take care of that, your efforts will be duly noted. Is that something that you can handle, $c?",
    isForever = false,
  },
  [8580] = {
    id = 8580,
    title = "The Horde Needs Firebloom!",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Batrider Pele'keiki",
    objectives = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Hey, $c. Ya you, mon! There be a whole mess of firebloom the Horde thinkin' they need for this Ahn'Qiraj war effort. Maybe they put it in nice things that go boom? Maybe they give it to the Alliance as fuel for their steam tanks? Who knows? Not Pele'keiki!\n\nPele'keiki know this though... he know you gonna help him out and bring back lots of the firebloom, right, mon?",
    isForever = false,
  },
  [8588] = {
    id = 8588,
    title = "The Horde Needs Heavy Leather!",
    reqLevel = 53,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Skinner Jamani",
    objectives = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Since we're preparing for war, it might be best if we get all of the goods we need first, don't you think, mon? One of the staples of the war materiel that we're producing is heavy leather. We'll use it for just about everything, from reinforcement to armor, and good old plain tarps too.\n\nBut first we need to get our hands on more of it. That's your job, $c. Sharpen your knife and bring me back a bundle. Then we'll talk further.",
    isForever = false,
  },
  [8611] = {
    id = 8611,
    title = "The Horde Needs Lean Wolf Steaks!",
    reqLevel = 49,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Bloodguard Rawtar",
    objectives = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "I'm not standing here just to get a nice tan, $c. There are war preparations to be made. If we're going to crush those bugs at Ahn'Qiraj then we need to be ready, and that includes food too!\n\nThey have me gathering and salting lean wolf steaks here for the upcoming war. But since I need to stay here to take care of all of this, I need you to go out, kill some wolves and then cook up the meat into lean wolf steaks and bring them back to me here. You got all that?",
    isForever = false,
  },
  [8607] = {
    id = 8607,
    title = "The Horde Needs Mageweave Bandages!",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Lady Callow",
    objectives = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "I trust that you are speaking to me because you are going to help with the collection I have been entrusted to? Good! By whatever means, and I do mean whatever, I wish for you to gather up a good number of mageweave bandages. Fresh would be nice, but not absolutely necessary. Return them to me here, $c, and I will personally see to it that you are properly rewarded.",
    isForever = false,
  },
  [8545] = {
    id = 8545,
    title = "The Horde Needs Mithril Bars!",
    reqLevel = 52,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Senior Sergeant T'kelah",
    objectives = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "$C, the war it is comin' and the only thing we can do is prepare for it. That be where you and I can help each other, mon. Ya see, they put me in charge of collectin' all the mithril bars we be needin' ta build for all the things we gonna need. An I still be needin' more!\n\nSo, I be hopin' that you can get out there an mine us up some mithril, then smelt it into bars. Sound like something you can do for us?",
    isForever = false,
  },
  [8616] = {
    id = 8616,
    title = "The Horde Needs More Baked Salmon!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Chief Sharpclaw",
    objectives = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "The last batch of baked salmon that you donated to the war effort looked very delicious, $C. I must admit that I was tempted to take a few for myself. As you can tell, we have not yet reached our quota here. I am hoping you have returned because you have another stack of baked salmon with you",
    isForever = false,
  },
  [8533] = {
    id = 8533,
    title = "The Horde Needs More Copper Bars!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Miner Cromwell",
    objectives = "Bring 20 copper bars to Miner Cromwell in Durotar.",
    rewards = "Experience & Faction Reputation",
    tip = "Back so soon? You'll be a real miner in no time $c. So, you already know the drill; I need you to go out, mine up a mess of copper ore, smelt it into bars and bring it back to me here. I know that's something you're capable of, the question is, are you willing?",
    isForever = false,
  },
  [8581] = {
    id = 8581,
    title = "The Horde Needs More Firebloom!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Batrider Pele'keiki",
    objectives = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Pele'keiki know you come to help. Bring many firebloom and make him very happy. Pele'keiki might make big bombs with firebloom. Drop them on insects from his bat over Ahn'Qiraj when war come. But Pele'keiki need more firebloom, $C!\n\nYou gonna bring Pele'keiki that firebloom, real quick now. Come back with at least as much as last time, and Pele'keiki be pleased.",
    isForever = false,
  },
  [8589] = {
    id = 8589,
    title = "The Horde Needs More Heavy Leather!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Skinner Jamani",
    objectives = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "It's true, $C, I still need more heavy leather. The requests from the generals and their quartermasters seem endless. And that's nothing compared to what the zeppelin masters are asking for!\n\nI need to get my quota collected on the double. Baekun, bring me more stacks of heavy leather as soon as you can!",
    isForever = false,
  },
  [8612] = {
    id = 8612,
    title = "The Horde Needs More Lean Wolf Steaks!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Bloodguard Rawtar",
    objectives = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "As you can see, $C, we still need to pack away more food for the soldiers. I don't know if you've ever been in a war before, but once you get past the initial shock of the battlefield, you can get pretty hungry. You did a good job last time, so I expect that you'll do as well, if not a little quicker, in getting me another stack of those lean wolf steaks.",
    isForever = false,
  },
  [8608] = {
    id = 8608,
    title = "The Horde Needs More Mageweave Bandages!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Lady Callow",
    objectives = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "You returned? Interesting. As you can see I am still collecting for the Ahn'Qiraj 'war effort'. Which means that I need you to once again go out and collect a stack of mageweave bandages for me. I look forward to your return, $C.",
    isForever = false,
  },
  [8546] = {
    id = 8546,
    title = "The Horde Needs More Mithril Bars!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Senior Sergeant T'kelah",
    objectives = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Yup, I be glad you're here, mon. You helped me before, and now I need your help again. We still lookin' ta bring in more mithril bars for the war effort; gonna build lots of armor and weapons and things to go squish them bugs at Ahn'Qiraj.\n\nSo if you be a true friend, you bring me back more stacks of mithril bars. I take all you got until we hit our quota. You have some for me now?",
    isForever = false,
  },
  [8583] = {
    id = 8583,
    title = "The Horde Needs More Purple Lotus!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Apothecary Jezel",
    objectives = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "In fact it does appear that we are in need of even more purple lotus, $C. While my own studies have yet to determine a new useful application for the herb, there are tried and true methodologies yet to be employed.\n\nI need you to once again go out into the field and collect at least twenty purple lotus samples. Return them to me here.",
    isForever = false,
  },
  [8601] = {
    id = 8601,
    title = "The Horde Needs More Rugged Leather!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Doctor Serratus",
    objectives = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Preparations for the impending war at Ahn'Qiraj are proceeding, $C. However, to ensure that we do not fall behind, or at least that I am not the one that causes us to fall behind, I want for you to bring back another stack of rugged leather. Your prompt attention to this matter will be greatly appreciated, $N.",
    isForever = false,
  },
  [8610] = {
    id = 8610,
    title = "The Horde Needs More Runecloth Bandages!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Stoneguard Clayhoof",
    objectives = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Ever does the time grow nearer when we shall launch ourselves headlong into the conflagration at Ahn'Qiraj, priest. But first we must gather our strength and prepare so that we can survive the onslaught of the insects and their masters.\n\nIf you are here again, then surely you wish to make another contribution of runecloth bandages to the war effort? Please do so as soon as you can and return to me once more.",
    isForever = false,
  },
  [8614] = {
    id = 8614,
    title = "The Horde Needs More Spotted Yellowtail!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Fisherman Lin'do",
    objectives = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "So as you can see, we still be needin' a lot of the fishies. The combatants in the upcomin' Ahn'Qiraj War gonna be needin' a lot to eat, so I needin' to get all the spotted yellowtail that I can. You catch 'em, cook 'em, and bringin' 'em back to me here, and I be givin' you thanks, and the thanks of the Horde.",
    isForever = false,
  },
  [8591] = {
    id = 8591,
    title = "The Horde Needs More Thick Leather!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sergeant Umala",
    objectives = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Druid, as you can see I still need to gather up more thick leather. Once again I ask your help with this task, and promise that if you complete it, you will be recognized for your efforts.\n\nTime is of the essence! Return to me with the thick leather so that we can finish our preparations and go to war, hero!",
    isForever = false,
  },
  [8543] = {
    id = 8543,
    title = "The Horde Needs More Tin Bars!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Grunt Maug",
    objectives = "Bring 20 tin bars to Grunt Maug in Durotar.",
    rewards = "Experience & Faction Reputation",
    tip = "Very good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, which means I'm going to get angry if you don't start bringing in the goods faster. Maybe I can just practice on you instead.\n\nHar! Maybe not, 'cuz then who would bring me back the tin bars?",
    isForever = false,
  },
  [8605] = {
    id = 8605,
    title = "The Horde Needs More Wool Bandages!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Healer Longrunner",
    objectives = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Good to see you again, $C. We are still working on preparations here for the war effort, and I can still use all of the help that you can give in gathering up wool bandaging. Any assistance at all will be greatly appreciated. I only hope that our efforts will be good enough. I've lost too many noble souls on the battlefields of yesterday to not do everything in my power to see to it that doesn't happen again.",
    isForever = false,
  },
  [8549] = {
    id = 8549,
    title = "The Horde Needs Peacebloom!",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Herbalist Proudfeather",
    objectives = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "It is said that every generation must face a defining trial. I fear the Ahn'Qiraj War will be the crucible in which our mettle is tested. So we prepare, and in so doing find what we are made of.\n\nI have volunteered to help the Horde by gathering as much peacebloom as possible, so that it can be made into potions for the war. I hope that you are here to lend me your aid. If so, then I need you to bring back to me a good quantity of the herb. Will you assist me, $c?",
    isForever = false,
  },
  [8550] = {
    id = 8550,
    title = "The Horde Needs Peacebloom!",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Herbalist Proudfeather",
    objectives = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Hello again, Abyssmal. I am glad that you wish to speak to me once more concerning our neverending need for peacebloom. The war effort continues, and with it our production of potions and elixirs to aid in the battles to come. Will you help us again, $C? I am in need of the same amount of peacebloom as before, so if you can gather it up and return it to me here I would be most grateful. Of course, if you already have it on your person, I will be more than happy to accept it from you now",
    isForever = false,
  },
  [8582] = {
    id = 8582,
    title = "The Horde Needs Purple Lotus!",
    reqLevel = 50,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Apothecary Jezel",
    objectives = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "The purple lotus, $c, is a reagent in a great many potions, elixirs and oils, some of which will be of use to us at Ahn'Qiraj. We're going to need to create an immense number of those potions for the war effort. And I'm going to experiment to find more uses for the lotus as well. But to do all of that I'm going to need a great quantity of the flower.\n\nThat's where you come in. Go out into the field and collect up as many purple lotuses as you can. Is this something that you are willing to do for",
    isForever = false,
  },
  [8600] = {
    id = 8600,
    title = "The Horde Needs Rugged Leather!",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Doctor Serratus",
    objectives = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "I find that the fit of the knife in your palm is more important than the edge on it. Even the dullest blade can be made to cut if pressure is being properly applied through it, wouldn't you agree, $c? But you and I don't have such problems as we maintain the sharpest of edges, yes? \n\nWell, no matter, I have a task for you. In service to the Horde, and to do your part for the Ahn'Qiraj war effort, I want you to return to me with a number of rugged leather skins. This is something that you will do",
    isForever = false,
  },
  [8609] = {
    id = 8609,
    title = "The Horde Needs Runecloth Bandages!",
    reqLevel = 59,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Stoneguard Clayhoof",
    objectives = "- Runecloth Bandage x 20",
    rewards = "Experience & Faction Reputation",
    tip = "It appears inevitable that the Horde and Alliance are on a collision course for war at Ahn'Qiraj. Surprisingly, it is not a war with each other, but rather with the silithid, and whatever force controls them. Also surprisingly, both sides are doing their part to gather the resources necessary to wage a successful war.\n\nI am collecting runecloth bandages to distribute to the soldiers, but I won't be successful without assistance, hopefully yours. Is this something that you can aid me with, $c?",
    isForever = false,
  },
  [8613] = {
    id = 8613,
    title = "The Horde Needs Spotted Yellowtail!",
    reqLevel = 52,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Fisherman Lin'do",
    objectives = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "It be a nice day for fishin', don't'cha think mon? Good thing, cuz I be needin' a lot of fish it lookin' like. The Horde, they askin' me to be in charge of collectin' a ton of the spotted yellowtail for them. They say they needin' it for the war they getting' ready for at Ahn'Qiraj. I say to them I do the best I can. So I be needin' to get some help. You gonna be helpin' me, $c?",
    isForever = false,
  },
  [8590] = {
    id = 8590,
    title = "The Horde Needs Thick Leather!",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Sergeant Umala",
    objectives = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "I'm glad that you decided to speak to me about this, $c. It looks like the Horde's preparations for the upcoming Ahn'Qiraj War are in full swing. But you and I still need to do our part.\n\nI've been asked to collect a great number of thick leather skins for use in all manner of war materiel, and I need you to help me by going out there and gathering them up. There's honor and the gratitude of the Horde in it for you should you decide to help. Will you?",
    isForever = false,
  },
  [8542] = {
    id = 8542,
    title = "The Horde Needs Tin Bars!",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Grunt Maug",
    objectives = "- Tin Bar x 20",
    rewards = "Experience & Faction Reputation",
    tip = "Lok'tar, $r, I'm sure you already know that we're going to war at Ahn'Qiraj with the insects. But first the Warchief has decided that we're going to do something called 'prepare'. Though I'd rather be sharpening weapons and hammering armor into shape, I'm proud to have been chosen to be in charge of tin bar collection here. But I cannot do that without your help.\n\nSo I need you to go out and make tin bars and bring them back to me here. I think I'm going to need more than I can count.",
    isForever = false,
  },
  [8604] = {
    id = 8604,
    title = "The Horde Needs Wool Bandages!",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Battlegrounds",
    npc = "Healer Longrunner",
    objectives = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
    rewards = "Experience & Faction Reputation",
    tip = "Greetings, $c. In preparation for the war at Ahn'Qiraj, I am here coordinating the Horde's efforts at gathering wool bandages. Unfortunately, out in the field, our soldiers cannot afford to rely upon the presence of a healer to keep them alive. Trust me, I know first hand. Thus, we're putting together all of these first aid kits for them.\n\nIf you have the time, I need many wool bandages. Return them to me here and I will see to it that you are properly rewarded.",
    isForever = false,
  },
  [8792] = {
    id = 8792,
    title = "The Horde Needs Your Help!",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Battlegrounds",
    npc = "Senior Sergeant Taiga",
    objectives = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
    rewards = "660 XP",
    tip = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, $c? Will you help out with the vital preparations?",
    isForever = false,
  },
  [8793] = {
    id = 8793,
    title = "The Horde Needs Your Help!",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Battlegrounds",
    npc = "Quest Event / Discovery",
    objectives = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
    rewards = "660 XP",
    tip = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, $c? Will you help out with the vital preparations?",
    isForever = false,
  },
  [8794] = {
