  [7363] = {
    id = 7363,
    title = "The Human Condition",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "You have been tasked with slaying opposing human players in Alterac Valley.\n\nKill a human and return to Commander Louis Philips (who wanders between the front lines and Frostwolf keep) with a  Human Bone Chip.\n\nA cure for the human condition is close at hand!",
    rewards = "6,600 XP, 1g 80s",
    tip = "Humans are so utterly detestable.\n\n<Commander Philips grimaces.>\n\nWhile it is true that I am a soldier of Frostwolf, I remain a servant of Sylvanas.\n\nDuring my tour of duty, I do extra work on the side for the Dark Apothecaries of the Undercity.\n\nI have been tasked with collecting human bone chips that are to be used in curing the human condition.\n\nI am authorized to pass that task on to my subordinates.\n\nFind them. Kill them. Return their bone chips to me.",
    isForever = false,
  },
  [5461] = {
    id = 5461,
    title = "The Human, Ras Frostwhisper",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Magistrate Marduke",
    objectives = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.",
    rewards = "6,600 XP",
    tip = "The undead fear life just as the living fear death. It is not unusual for a sentient undead being to completely destroy all remnants of his or her previous life after having turned.\n\nUnfortunately, in order to create an artifact capable of reverting Ras Frostwhisper to a mortal, we must have a keepsake from his years among the living.\n\nYou must venture to the ruined city of Stromgarde, Frostwhisper's home, and search for such an item. May luck be with you, $N.",
    isForever = false,
  },
  [9211] = {
    id = 9211,
    title = "The Ice Guard",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Mataus the Wrathcaster",
    objectives = "- Insignia of the Crusade x 10 - Money:30",
    rewards = "Experience & Faction Reputation",
    tip = "Ah, the Ice Guard. It is a thin sheen of protective magic that covers certain pieces of equipment. Those that do battle with creatures of frost and ice will gain increased protection from their attacks by using the Ice Guard.\n\nAs with all things the Wrathcaster creates, there is a price - a price that I will not lower, regardless of how much you whimper. Interested?",
    isForever = false,
  },
  [8950] = {
    id = 8950,
    title = "The Instigator's Enchantment",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Falrin Treeshaper",
    objectives = "Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards.",
    rewards = "6,600 XP",
    tip = "I can place the enchantment you require on the banner quite easily, $N.  Unfortunately I don't have the materials I need as it is very rarely that someone asks for this sort of charm.\n\nI will require the essence of one of the Eldreth ghosts that haunt these halls, a handful of Scholomance dark runes and some large brilliant shards.  Bring me these reagents and I shall perform this task for you.",
    isForever = false,
  },
  [8778] = {
    id = 8778,
    title = "The Ironforge Brigade Needs Explosives!",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Silithus",
    npc = "Item: Logistics Task Briefing IV",
    objectives = "Bring 6 Oils of Immolation, 5 Goblin Rocket Fuel and 10 Dense Blasting Powder to Arcanist Nozzlespring near Hive'Zora in Silithus.  You must also bring Logistics Task Briefing IV in order to complete this quest.",
    rewards = "650 XP",
    tip = "The Ironforge Brigade has put in an unusual request for highly... volatile... components.  Gather them and bring them to Mr. Nozzlespring from the Ironforge Brigade.",
    isForever = false,
  },
  [8585] = {
    id = 8585,
    title = "The Isle of Dread!",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Dirge Quikcleave",
    objectives = "- Lakmaeran's Carcass - Chimaerok Tenderloin x 20",
    rewards = "6,600 XP",
    tip = "Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken.\n\nHead to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you'll need to get your hands on some chimaerok tenderloin.\n\nDo this and you'll have your 500 pound chicken and a little something extr",
    isForever = false,
  },
  [8104] = {
