  [9247] = {
    id = 9247,
    title = "The Keeper's Call",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: A Letter from the Keeper of the Rolls",
    objectives = "Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "660 XP",
    tip = "$N,\n\nIn times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need.\n\n$N, please report to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.",
    isForever = false,
  },
  [5505] = {
