  [5342] = {
    id = 5342,
    title = "The Last Barov",
    reqLevel = 52,
    questLevel = 60,
    faction = "Horde",
    zone = "Western Plaguelands",
    npc = "Alexi Barov",
    objectives = "Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.\n\nBe warned, Weldon will probably be well protected by Alliance scum.",
    rewards = "8,300 XP • 1g 80s",
    tip = "Naturally, with my brother still alive, there may be some contention as to the primary beneficiary of the family's fortune. This cannot be.\n\nA low down guttersnipe like you isn't above a little cold-blooded murder, I hope.\n\nIt's a simple task and one that I expect you will complete; that is, if you wish to claim your reward.\n\nWeldon sits under Alliance protection at Chillwind Camp, to the east. Slay him, return his head.\n\n<Alexi yawns.>\n\nHurry along now.",
    isForever = false,
  },
  [5344] = {
    id = 5344,
    title = "The Last Barov",
    reqLevel = 52,
    questLevel = 60,
    faction = "Alliance",
    zone = "Western Plaguelands",
    npc = "Weldon Barov",
    objectives = "Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.\n\nBe warned, Alexi will probably be well protected by Horde filth.",
    rewards = "8,300 XP • 1g 80s",
    tip = "With the deeds recovered, there is but one thing left to do. Alexi must be killed. With him dead, I need not ever worry about an unscrupulous gang of mercenaries seeking my head.\n\nIt's a simple task. Alexi hides under the protection of the Horde - at the Bulwark.\n\nNo, I do not expect you to just walk up and kill him, I want his head! How you get it... well, that part is up to you. That type of behavior is below one of my noble upbringing.",
    isForever = false,
  },
  [8966] = {
    id = 8966,
    title = "The Left Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front ",
    isForever = false,
  },
  [8967] = {
    id = 8967,
    title = "The Left Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and hi",
    isForever = false,
  },
  [8968] = {
    id = 8968,
    title = "The Left Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the left piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.",
    isForever = false,
  },
  [8969] = {
    id = 8969,
    title = "The Left Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Scholomance",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "Now we have what we need, so it's time to discuss who it is that you'll be summoning.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.",
    isForever = false,
  },
  [7181] = {
    id = 7181,
    title = "The Legend of Korrak",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Warmaster Laggrond",
    objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Warmaster Laggrond.",
    rewards = "9,950 XP",
    tip = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!",
    isForever = false,
  },
  [5466] = {
    id = 5466,
    title = "The Lich, Ras Frostwhisper",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Scholomance",
    npc = "Magistrate Marduke",
    objectives = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",
    rewards = "9,950 XP",
    tip = "There is but one task remaining, $N. Confront the lich, Ras Frostwhisper, in his lair.\n\nUse the power of the keepsake against the beast -  be unrelenting in your actions!  Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!\n\nWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head.",
    isForever = false,
  },
  [7501] = {
    id = 7501,
    title = "The Light and How To Swing It",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Item: The Light and How to Swing It",
    objectives = "Return the book to its rightful owners.",
    rewards = "7,050 XP",
    tip = "The tome carries the mark of the Athenaeum.",
    isForever = false,
  },
  [7781] = {
