  [8870] = {
    id = 8870,
    title = "The Lunar Festival",
    reqLevel = 1,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Lunar Festival Emissary",
    objectives = "Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge.  You can also talk to Lunar Festival Harbingers in other capital cities.",
    rewards = "Experience & Faction Reputation",
    tip = "It's that time of the year, $N!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.",
    isForever = false,
