  [7461] = {
    id = 7461,
    title = "The Madness Within",
    reqLevel = 56,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Shen'dralar Ancient",
    objectives = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.",
    rewards = "10,250 XP",
    tip = "Have you heard enough? Are you a $g man:woman; of action?\n\nThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.",
    isForever = false,
  },
