  [5160] = {
    id = 5160,
    title = "The Matron Protectorate",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Awbee",
    objectives = "Travel to Winterspring and find Haleh. Give her Awbee's scale.",
    rewards = "6,600 XP",
    tip = "Travel to Kalimdor, $r. Our flight makes its home in the frigid landscape of Winterspring. Once you reach Winterspring, find the caves of Mazthoril.\n\nUpon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to Haleh, our matron protectorate.\n\nGive her the scale so that she may scry what it is I have seen and felt, here in this doomed place.",
    isForever = false,
  },
  [5122] = {
    id = 5122,
    title = "The Medallion of Faith",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Aurius",
    objectives = "- Medallion of Faith",
    rewards = "Experience & Faction Reputation",
    tip = "",
    isForever = false,
  },
  [8742] = {
    id = 8742,
    title = "The Might of Kalimdor",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Anachronos",
    objectives = "Speak with Anachronos in Tanaris.",
    rewards = "9,950 XP",
    tip = "A thousand years has passed and just as it was fated, one stands before me. One who shall lead their people to a new age.\n\nThe Old God trembles, $N. Oh yes, it fears your faith. Shatter the prophecy of C'Thun.\n\nIt knows you come, champion - and with you comes the might of Kalimdor. You have only to let me know when you are prepared and I shall grant you The Scepter of the Shifting Sands.",
    isForever = false,
  },
  [6822] = {
    id = 6822,
    title = "The Molten Core",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Azshara",
    npc = "Duke Hydraxis",
    objectives = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.",
    rewards = "9,950 XP",
    tip = "$n, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, $N.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live.",
    isForever = false,
  },
  [8736] = {
    id = 8736,
    title = "The Nightmare Manifests",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Moonglade",
    npc = "Keeper Remulos",
    objectives = "- The Redemption of Eranikus",
    rewards = "9,950 XP",
    tip = "We must use restraint against Eranikus. We are to redeem him not destroy him.\n\nTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.\n\nBe on guard! You and your allies are our only hope.",
    isForever = false,
  },
  [8735] = {
    id = 8735,
    title = "The Nightmare's Corruption",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Moonglade",
    npc = "Keeper Remulos",
    objectives = "- Fragment of the Nightmare's Corruption - Fragment of the Nightmare's Corruption - Fragment of the Nightmare's Corruption - Fragment of the Nightmare's Corruption",
    rewards = "6,600 XP",
    tip = "You must travel to the four dream portals of Azeroth. From each you must draw a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will hold such fragments. Return to me when you have gathered these fragments.",
    isForever = false,
  },
  [8620] = {
    id = 8620,
    title = "The Only Prescription",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Narain Soothfancy",
    objectives = "Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.",
    rewards = "6,600 XP",
    tip = "I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero?\n\nThe note I received stated that the only known copy of \"Draconic for Dummies: Volume II\" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me.",
    isForever = false,
  },
  [9232] = {
    id = 9232,
    title = "The Only Song I Know...",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Naxxramas",
    npc = "Craftsman Wilhelm",
    objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.",
    rewards = "Experience & Faction Reputation",
    tip = "You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?\n\n<Wilhelm sighs.>\n\nBah, what choice do I got? You're the best I can do; I may as well help you.\n\nOmarion left me with one recipe. It's the only song I know... I can make a few variations of these pants; you just gotta supply the materials.",
    isForever = false,
  },
  [8785] = {
    id = 8785,
    title = "The Orgrimmar Legion Needs Mojo!",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Silithus",
    npc = "Item: Logistics Task Briefing IV",
    objectives = "Bring 6 Powerful Mojo, 6 Flasks of Big Mojo and 8 Oils of Immolation to Shadow Priestess Shai near Hive'Regal in Silithus.  You must also bring Logistics Task Briefing IV in order to complete this quest.",
    rewards = "650 XP",
    tip = "The Orgrimmar Legion has put in a request for several unusual ingredients.  Given their current performance in Silithus, we'd like to comply with their request as soon as possible.  Gather the materials and bring them to the troll called Shai.",
    isForever = false,
  },
