  [9023] = {
    id = 9023,
    title = "The Perfect Poison",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Dirk Thunderwood",
    objectives = "Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.",
    rewards = "6,600 XP",
    tip = "My brother and I run the poison operations out of the manor Ravenholdt.\n\nLord Ravenholdt tasked me to track down a new and extremely effective poison compound that can be crafted from the venom sacs of the inhabitants of Zul'Gurub and the Ruins of Ahn'Qiraj.\n\nThere are two particularly venomous beasts residing in those blasted ruins that possess what it is that we might be looking for, $c. Bring me a venom sac from the beasts Kurinnaxx and Venoxis and we would be eternally grateful.",
    isForever = false,
  },
  [8373] = {
    id = 8373,
    title = "The Power of Pine",
    reqLevel = 25,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Sergeant Hartman",
    objectives = "Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore.  Return to Sergeant Hartman in Southshore when you're done.",
    rewards = "1,650 XP",
    tip = "The thing I hate the most about Hallow's End are the stink bombs the Forsaken use on Southshore.  Who knew that celebrating liberation would have to involve such a smelly mess?\n\nDuring Hallow's End, use this cleaner to remove any nasty stink bombs the Horde may drop here in the village.  It uses the power of pine to fight funky smells.\n\nDo your part to keep Southshore clean, and I'll give you some Hallow's End treats I'm sure you'll enjoy.  We have a deal?",
    isForever = false,
  },
  [4004] = {
    id = 4004,
    title = "The Princess Saved?",
    reqLevel = 48,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Depths",
    npc = "Princess Moira Bronzebeard",
    objectives = "Return to Thrall!",
    rewards = "9,950 XP, 2g 70s",
    tip = "You have slain my husband, $r! My child will be born into this world without a father.\n\n<Princess Moira points directly at you.>\n\nI assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act.\n\n<You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.>\n\nLeave me be, $r. I am certain your warchief will be eager to hear the results of his meddling.",
    isForever = false,
  },
  [7581] = {
    id = 7581,
    title = "The Prison's Bindings",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Daio the Decrepit",
    objectives = "- Satyr Blood x 15",
    rewards = "6,600 XP",
    tip = "You must retrieve bindings for the prison of the Doomguard from lesser demons.\n\nThe blood of the Wildspawn satyr that occupy Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.",
    isForever = false,
  },
  [7582] = {
    id = 7582,
    title = "The Prison's Casing",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Daio the Decrepit",
    objectives = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task.",
    rewards = "6,600 XP",
    tip = "The Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as Tears of the Hederine.\n\nNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.\n\nTravel to Darkwhisper Gorge in Winterspring and recover the Tears.",
    isForever = false,
  },
