  [6133] = {
    id = 6133,
    title = "The Ranger Lord's Behest",
    reqLevel = 54,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.\n\nYou must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.",
    rewards = "6,600 XP • 90s",
    tip = "The high elves of the Quel'Lithien lodge possesses something that belongs to me, $c: A document detailing my life as a mortal.\n\nBefore you ask; no, you most certainly are not privy to such information. Just do as I tell you, worm: Recover the registry.\n\nAnd imbecile, be sure to leave as much strife and grief as possible in your wake. Leave them suffering...",
    isForever = false,
  },
  [6964] = {
    id = 6964,
    title = "The Reason for the Season",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Furmund",
    objectives = "Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.",
    rewards = "650 XP",
    tip = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider.  I'm sure he'll be surprised that someone cares about history rather than getting presents.",
    isForever = false,
  },
  [7062] = {
    id = 7062,
    title = "The Reason for the Season",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Goli Krumn",
    objectives = "Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil.",
    rewards = "650 XP",
    tip = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorer's League.  I'm sure he'll be surprised that someone cares about history rather than getting presents.",
    isForever = false,
  },
  [5281] = {
    id = 5281,
    title = "The Restless Souls",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Caretaker Alen",
    objectives = "Find Egan. You only know that he was last seen around Stratholme.",
    rewards = "6,600 XP",
    tip = "There are those that died tragically in the fall of Stratholme. Many took their own lives, opting to hurl themselves into the myriad flames of the smoldering city rather than become one of the Scourge.\n\nThey now walk the streets of Stratholme as restless spirits.\n\nWe must aid them, $N!\n\nI have an associate named Egan who has been doing miraculous work with ghosts and souls. Seek him out. He walks the eastern Plaguelands, near Stratholme, testing his innovations.",
    isForever = false,
  },
  [5282] = {
    id = 5282,
    title = "The Restless Souls",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Egan",
    objectives = "- Souls Freed x 15",
    rewards = "8,300 XP, 1g 80s",
    tip = "I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done. I am, however, no zealot. There are those, like the Scarlet Crusade, who would sooner destroy the innocent undead than lend them even an ounce of compassion.\n\nWhich brings me to this: My blaster. It will unchain the tortured souls from Stratholme.\n\nUse it on the ghosts that haunt the ransacked streets. Free their souls.",
    isForever = false,
  },
  [7381] = {
    id = 7381,
    title = "The Return of Korrak",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Battleground Officer",
    objectives = "Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.\n\nReturn the Skull of Korrak to Warmaster Laggrond in the Hillsbrad Foothills.",
    rewards = "",
    tip = "While it is true that Korrak has been slain, one question remains: Will he remain dead? Trolls are notorious for their other-worldly tribal magics. I would not be surprised if the fallen leader was raised from the dead to once more rule over his clan.\n\nYou know what to do should this ever occur.\n\n<Warmaster Laggrond makes a cutting motion across his neck with his index finger.>\n\nAnd  this time, I want his skull. Just keep your eyes peeled, soldier.\n\nDismissed!",
    isForever = false,
  },
  [8989] = {
    id = 8989,
    title = "The Right Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front ",
    isForever = false,
  },
  [8990] = {
    id = 8990,
    title = "The Right Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and hi",
    isForever = false,
  },
  [8991] = {
    id = 8991,
    title = "The Right Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the right piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.",
    isForever = false,
  },
  [8992] = {
    id = 8992,
    title = "The Right Piece of Lord Valthalak's Amulet",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Scholomance",
    npc = "Bodley",
    objectives = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.",
    rewards = "8,300 XP",
    tip = "Now we have what we need, so it's time to discuss who it is that you'll be summoning next.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.",
    isForever = false,
  },
  [8481] = {
    id = 8481,
    title = "The Root of All Evil",
    reqLevel = 45,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Gorn One Eye",
    objectives = "Plant the Demon Summoning Torch in the mouth of High Chief Winterfall's cave in the Winterfall furbolg village.  Defeat the demon and retrieve the Essence of Xandivious for Gorn One Eye in Timbermaw Hold.",
    rewards = "6,600 XP",
    tip = "$N, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them!\n\nTake this torch to the mouth of High Chief Winterfall's personal cave and plant it there.  Doing so will force the demon to reveal itself and investigate.  This is when you and your allies must strike it down!  Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold.",
    isForever = false,
  },
  [9210] = {
    id = 9210,
    title = "The Savage Guard - Arcanum of Focus",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Zul'Gurub",
    npc = "Zanza the Restless",
    objectives = "- Arcanum of Focus",
    rewards = "Experience & Faction Reputation",
    tip = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.",
    isForever = false,
  },
