  [8802] = {
    id = 8802,
    title = "The Savior of Kalimdor",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Caelestrasz",
    objectives = "Take the Eye of C'Thun to Anachronos at the Caverns of Time.",
    rewards = "9,950 XP",
    tip = "To the Caverns of Time you go, $G Lord:Lady; $N. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection.",
    isForever = false,
  },
  [6148] = {
    id = 6148,
    title = "The Scarlet Oracle, Demetria",
    reqLevel = 56,
    questLevel = 60,
    faction = "Horde",
    zone = "Eastern Plaguelands",
    npc = "Nathanos Blightcaller",
    objectives = "- Demetria",
    rewards = "8,300 XP, 1g 80s",
    tip = "Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge.\n\nWhile this ruse was successful in exposing her, if she truly does possess psychic powers, she will undoubtedly be expecting some sort of trouble. You are going to provide that 'trouble.'\n\nTrack down the Oracle and terminate her. They should be moving out of Tyr's Hand as we speak. Make me proud, w",
    isForever = false,
  },
  [9213] = {
    id = 9213,
    title = "The Shadow Guard",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Mataus the Wrathcaster",
    objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.",
    rewards = "Experience & Faction Reputation",
    tip = "A creation of genius! Much like the Ice Guard, the Shadow Guard employs a thin sheen of protective magic that covers certain pieces of equipment. And like the Ice Guard, the Shadow Guard is going to cost you a good amount of money.\n\n<Mataus holds his hand out and rubs his fingers together.>\n\nInterested?",
    isForever = false,
  },
  [8984] = {
    id = 8984,
    title = "The Source Revealed",
    reqLevel = 1,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Mara Rennick",
    objectives = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor.",
    rewards = "Experience & Faction Reputation",
    tip = "Look, the actions of a rogue apothecary are not my concern. If he's undermining our efforts, then let me be the first to point you in the right direction\n\nIf he's innocent, then he's got nothing to hide, right?\n\nI purchased the goods from Apothecary Staffron Lerent. He's working in a secluded area past Ravenholdt Manor in the hills over Hillsbrad. To be honest with you, I thought he was a little odd.",
    isForever = false,
  },
  [9028] = {
    id = 9028,
    title = "The Source Revealed",
    reqLevel = 1,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Evert Sorisam",
    objectives = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills behind Ravenholdt Manor.",
    rewards = "Experience & Faction Reputation",
    tip = "What? Treason? No, no. I assure you, my intentions are completely harmless.\n\nIs it so wrong to help those who wish to ease the painful ritual of courtship? Come, that is no crime.\n\nAnd to prove that I mean no harm, I will even tell you my source.\n\nThey were shipped to me by a Staffron Lerent, an apothecary of some sort. I never spoke with him.\n\nOur goblin middle man said that he worked in the foothills over Hillsbrad past that mysterious Ravenholdt Manor. I wish you luck in finding him.",
    isForever = false,
  },
  [7261] = {
    id = 7261,
    title = "The Sovereign Imperative",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Lieutenant Rotimer",
    objectives = "Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.\n\nFor the glory of Bronzebeard!",
    rewards = "6,600 XP",
    tip = "We are fighting a brutal battle in the valleys of Alterac. The cannibalistic Winterax trolls attack us from one side and the savage Frostwolf Clan from the other. Both must be exterminated in the name of King Magni Bronzebeard! The taking, culling, and turning of that land is a sovereign and territorial imperative to the kingdom of Ironforge.\n\nAlas, soldiers do not grow on trees! Report to Lieutenant Haggerdin outside Alterac Valley to begin your tour of duty and honor amongst the Stormpike.",
    isForever = false,
  },
  [1558] = {
    id = 1558,
    title = "The Stonewrought Dam",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Azeroth",
    npc = "Human Orphan",
    objectives = "Take the orphan to the Stonewrought Dam in Loch Modan.  You should take him to the middle of the dam so he can see out over the giant waterfall.",
    rewards = "650 XP",
    tip = "Ironforge is where all the dwarves and gnomes live.  Near there is a place called Loch Modan, and the dwarves built a HUGE dam there.  They say it's one of the biggest things anyone's ever made.  Wow!\n\nCould you take me to Loch Modan and see the dam there, please?  I think it is the Stone... um... Stonewrench Dam?  Stonewrought?  It's big - that's for sure.  I'd like to look out over the big waterfall.  I promise I won't lean over too far!",
    isForever = false,
  },
  [2741] = {
    id = 2741,
    title = "The Super Egg-O-Matic",
    reqLevel = 42,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Object: Egg-O-Matic",
    objectives = "- Hippogryph Egg",
    rewards = "4,200 XP",
    tip = "",
    isForever = false,
  },
  [6585] = {
    id = 6585,
    title = "The Test of Skulls, Axtroz",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Emberstrife",
    objectives = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.",
    rewards = "6,600 XP",
    tip = "It was over the mountains of Grim Batol that our Father raged against the combined might of the Aspects. The cowardly act of the betrayer, Alexstrasza, bought the other Aspects enough time to escape from Father's wrath.\n\nSssuch a shameful act...\n\nThe Red Flight now guards Grim Batol, their lieutenant, Axtroz, must be destroyed. Return the skull of Axtroz to me. For Father, whelp!",
    isForever = false,
  },
  [6584] = {
    id = 6584,
    title = "The Test of Skulls, Chronalis",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Emberstrife",
    objectives = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.",
    rewards = "6,600 XP",
    tip = "The time watchers, children of Nozdormu - Lord of the Centuriesss...\n\nIt is three that guard the Caverns of Time, but only one that holds the interests of the Black Flight: The Time Shifter, Chronalis, favored drakeling of Nozdormu.\n\nSsstrike at this champion, a blow to make even the stoic sands of time weep. Return to me with his skull.",
    isForever = false,
  },
  [6582] = {
    id = 6582,
    title = "The Test of Skulls, Scryer",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Emberstrife",
    objectives = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\n\nYou know that Scryer can be found in Winterspring.",
    rewards = "6,600 XP",
    tip = "We are Deathwing's children, whelp. Our dominance over the lesser Aspects must be enforced.\n\nIf you are truly worthy of ascension, the lesser dragonflight will wilt in your presence.\n\nFind their champions and lay waste to them in the name of our Father!\n\nTravel to Winterspring and track down the mighty blue drake, Scryer. Crush him and any of the Blue Flight that stand in your path. Tear out his skull and return it to me.",
    isForever = false,
  },
  [6583] = {
    id = 6583,
    title = "The Test of Skulls, Somnus",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Dustwallow Marsh",
    npc = "Emberstrife",
    objectives = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.",
    rewards = "6,600 XP",
    tip = "Just as our Father crushes the Aspects themselves, so too must we strive to bring chaos and destruction to their children.\n\nYou must test your battle prowess against the sleepless dreamers: The children of the Green Flight.\n\nTravel to the Swamp of Sorrows and track down Somnus, drake champion of the Green Flight. Let flow your hatred; dominate the insect... Return to me with his skull...",
    isForever = false,
  },
  [6568] = {
    id = 6568,
    title = "The Testament of Rexxar",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Desolace",
    npc = "Rexxar",
    objectives = "Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands.",
    rewards = "4,950 XP",
    tip = "Illusion and disguise. That is how you will fool the Black Dragonflight, and gain what you seek.\n\nThough I could teach you something of the skills of deception, you need the help of a master.\n\nI know of one who could do this. In the Western Plaguelands, you will find Myranda the Hag, once a master illusionist of Lordaeron. She has helped us in the past, and if she believes the cause worthy, she may help you.\n\nTake this message to her.",
    isForever = false,
  },
  [7462] = {
