  [5262] = {
    id = 5262,
    title = "The Truth Comes Crashing Down",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Stratholme",
    npc = "Item: Head of Balnazzar",
    objectives = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.",
    rewards = "8,300 XP",
    tip = "You try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation.\n\nThe Grand Crusader of the Scarlet Crusade a demon? And not just any demon but brother to Varimathras, arch lord of the Undercity?\n\nYou carefully stow the severed head of the dreadlord into your pack. Surely, none would believe the tale you would tell without proof.\n\nDuke Nicholas Zverenhoff must be told at once!",
    isForever = false,
  },
  [8279] = {
    id = 8279,
    title = "The Twilight Lexicon",
    reqLevel = 54,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Hermit Ortell",
    objectives = "Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus.",
    rewards = "8,300 XP • 90s",
    tip = "The Twilight's Hammer are not kind to those that leave their ranks.  They hunt me to this day like I'm some sort of beast!  Needless to say, an enemy of theirs is a friend of mine!\n\nTo decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon.  It's such an important tool that they keep its three chapters in different locations!  The officers entrusted with the Lexicon are known as Twilight Keepers, look for them at the Twilight's Hammer camps.",
    isForever = false,
  },
  [8829] = {
    id = 8829,
    title = "The Ultimate Deception",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Item: Logistics Task Briefing XI",
    objectives = "- Skin of Shadow - Frayed Abomination Stitching x 3 - Twilight Cultist Robe",
    rewards = "650 XP",
    tip = "The Twilight's Hammer operates through innumerable layers of secrecy and deceit.  While their actions are carried out in our world, they are planned in a place we have not yet been able to reach.\n\nWe've come to believe that the stones the Twilight's Hammer uses to summon their superiors allow for two-way transportation.  To attempt to use them in this manner, we must replicate - to every last detail - a twilight emissary's robe.\n\nGather the necessary materials and bring them to Aurel Goldleaf, $",
    isForever = false,
  },
  [8119] = {
    id = 8119,
    title = "The Unmarred Vision of Voodress",
    reqLevel = 60,
    questLevel = 60,
    faction = "Horde",
    zone = "Zul'Gurub",
    npc = "Maywiki of Zuldazar",
    objectives = "- Vision of Voodress",
    rewards = "6,600 XP",
