  [7641] = {
    id = 7641,
    title = "The Work of Grimand Elmore",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "Lord Grayson Shadowbreaker",
    objectives = "Speak with Grimand Elmore in Stormwind's Dwarven District.",
    rewards = "650 XP",
    tip = "A paladin's charger is nothing more than a pack animal without proper barding for it.  The barding used by your charger not only needs to be of the finest materials possible, but because of the circumstances involved it must also be sufficiently attuned to the spirit realm.\n\nFirst things first, $N - let's get your barding made.  In Stormwind's Dwarven District is one of the finest craftsmen living today, Grimand Elmore.  His work will not be cheap, but his quality is what we seek.  Speak with hi",
    isForever = false,
  },
  [7883] = {
