  [8729] = {
    id = 8729,
    title = "The Wrath of Neptulon",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Azshara",
    npc = "Narain Soothfancy",
    objectives = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.",
    rewards = "9,950 XP",
    tip = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.\n\nAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.\n\nLook for a swirling maelstrom, most likely cluttered with wreckage.\n\nBy the by, I hope you have friends.\n\nNow if you somehow miraculously succeed, take the scepter shard to Anachronos.",
    isForever = false,
  },
  [9141] = {
    id = 9141,
    title = "They Call Me \"The Rooster\"",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Dispatch Commander Metz",
    objectives = "- Argent Dawn Valor Token",
    rewards = "3,300 XP",
    tip = "You want a writ? What? Do you expect me to hand you a highly sought after work order just for showing up? I think not, scrub. Crafters from around the world bid for jobs here at the front lines.\n\nIf you want a work order, you'll have to show me that you're willing to bleed for the cause. Bring me a valor token and we'll talk.\n\nAnd there's only one way to get your grubby little scrub mitts on those - get to killin'.",
    isForever = false,
  },
  [8850] = {
