  [8961] = {
    id = 8961,
    title = "Three Kings of Flame",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Mountain",
    npc = "Bodley",
    objectives = "Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain.",
    rewards = "6,600 XP",
    tip = "In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.\n\nThere are three nobles of fire, Lord Incedius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire and The Duke of Cynders in Silithus, with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the Argent Dawn if you are honored by ",
    isForever = false,
  },
  [7786] = {
    id = 7786,
    title = "Thunderaan the Windseeker",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Mining",
    npc = "Highlord Demitrian",
    objectives = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus.",
    rewards = "9,950 XP",
    tip = "I have told you all that I know, $N. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form.\n\nDo this and gain the blessing of Thunderaan.",
    isForever = false,
  },
