  [8592] = {
    id = 8592,
    title = "Tiara of the Oracle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Andorgos",
    objectives = "Bring Vek'nilash's Circlet, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, $N.  I will give you a headpiece of unmatched power.",
    isForever = false,
  },
  [4907] = {
    id = 4907,
    title = "Tinkee Steamboil",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Blackrock Spire",
    npc = "Felnok Steelspring",
    objectives = "Speak with Tinkee Steamboil.",
    rewards = "660 XP",
    tip = "Hi, $N.  Remember Tinkee Steamboil?  Well, she remembers you!  She sent me a message to keep an eye out for you, because... she needs your help again.  I think it has something to do with her studies on dragons.\n\nYou should speak to her in the Burning Steppes, at the Flame Crest.",
    isForever = false,
  },
  [7639] = {
    id = 7639,
    title = "To Show Due Judgment",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Paladin Class Quests",
    npc = "High Priest Rohan",
    objectives = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",
    rewards = "650 XP",
    tip = "With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.\n\nReturn now to Lord Grayson Shadowbreaker in Stormwind, $N.  Your quest continues with him.",
    isForever = false,
  },
