  [7101] = {
    id = 7101,
    title = "Towers and Bunkers",
    reqLevel = 51,
    questLevel = 60,
    faction = "Horde",
    zone = "Alterac Valley",
    npc = "Corporal Teeka Bloodsnarl",
    objectives = "Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",
    rewards = "6,600 XP",
    tip = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!",
    isForever = false,
  },
  [7102] = {
    id = 7102,
    title = "Towers and Bunkers",
    reqLevel = 51,
    questLevel = 60,
    faction = "Alliance",
    zone = "Alterac Valley",
    npc = "Sergeant Durgen Stormpike",
    objectives = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",
    rewards = "6,600 XP",
    tip = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!",
    isForever = false,
  },
  [8982] = {
    id = 8982,
    title = "Tracing the Source",
    reqLevel = 1,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Fenstad Argyle",
    objectives = "Speak with Innkeeper Norman in the Undercity.",
    rewards = "Experience & Faction Reputation",
    tip = "We must find who the supplier is. I noticed Apothecary Katrina with a bottle of the perfume tucked in her pack. She told me that she purchased it from Norman, the innkeeper.",
    isForever = false,
  },
  [8983] = {
    id = 8983,
    title = "Tracing the Source",
    reqLevel = 1,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Innkeeper Norman",
    objectives = "Speak with Mara Rennick at the tailor's shop in the Undercity's Mage Quarter.",
    rewards = "Experience & Faction Reputation",
    tip = "Something's wrong with my product? Well, I've never seen so many people wanting something so badly.\n\nI bought my supply from a merchant named Mara Rennick. She's new in town.\n\nShe mentioned she had some goods she had to deliver to the tailor in the Mage Quarter.",
    isForever = false,
  },
  [9026] = {
    id = 9026,
    title = "Tracing the Source",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Seasonal Events",
    npc = "Aristan Mottar",
    objectives = "Speak with Innkeeper Allison at The Gilded Rose in Stormwind's Trade District.",
    rewards = "Experience & Faction Reputation",
    tip = "We've got to find the source. I've seen a lot more people than usual - guards included - going in and out of The Gilded Rose. Talk to Allison. If she's selling them, she can tell you where they came from.",
    isForever = false,
  },
  [9027] = {
