  [6962] = {
    id = 6962,
    title = "Treats for Great-father Winter",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Great-father Winter",
    objectives = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Orgrimmar.",
    rewards = "1,650 XP",
    tip = "Hey, can you do Great-father Winter a favor, um, little $g boy : girl;?\n\nNot to needlessly talk about myself in the third person, but Great-father Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Great-father and fetch some for me?",
    isForever = false,
