  [7025] = {
    id = 7025,
    title = "Treats for Greatfather Winter",
    reqLevel = 10,
    questLevel = 60,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Greatfather Winter",
    objectives = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.",
    rewards = "1,650 XP",
    tip = "Hey, can you do Greatfather Winter a favor, um, little $g boy : girl;?\n\nNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?",
    isForever = false,
