  [8734] = {
    id = 8734,
    title = "Tyrande and Remulos",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Teldrassil",
    npc = "Forest Wisp",
    objectives = "Travel to the Moonglade and speak to Keeper Remulos.",
    rewards = "1,650 XP",
    tip = "Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.\n\nNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.\n\nWe all wish you great luck.",
    isForever = false,
  },
  [9153] = {
    id = 9153,
    title = "Under the Shadow",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Commander Thomas Helleran",
    objectives = "Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "Experience & Faction Reputation",
    tip = "The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses.\n\nOnly through our combined efforts will they be turned away.\n\nThe necropolises are supported by magical circles at various points in the invaded areas. We have determined that destroying the mindless hordes that surround these circles will destroy their defenses.",
    isForever = false,
  },
  [1318] = {
    id = 1318,
    title = "Unfinished Gordok Business",
    reqLevel = 56,
    questLevel = 60,
    faction = "Both",
    zone = "Dire Maul",
    npc = "Quest Event / Discovery",
    objectives = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",
    rewards = "8,250 XP",
    tip = "Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!",
    isForever = false,
  },
