  [3627] = {
    id = 3627,
    title = "Uniting the Shattered Amulet",
    reqLevel = 45,
    questLevel = 60,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Fallen Hero of the Horde",
    objectives = "- Amulet of Allistarj - Amulet of Grol - Amulet of Sevine",
    rewards = "8,300 XP",
    tip = "To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.\n\nGo $N! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!",
