  [8314] = {
    id = 8314,
    title = "Unraveling the Mystery",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Rutgar Glyphshaper",
    objectives = "Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus.",
    rewards = "5,300 XP",
    tip = "We're on the verge of a breakthrough, $N! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid.\n\nUnfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals.\n\nTake the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help.",
    isForever = false,
  },
  [4867] = {
