  [8883] = {
    id = 8883,
    title = "Valadar Starsong",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Lunar Festival Harbinger",
    objectives = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.",
    rewards = "650 XP",
    tip = "Now that you have your Lunar Festival invitation, you may travel to Moonglade!  There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration.\n\nTravel to Moonglade through the greater moonlight and speak with Valadar Starsong; see what prizes you might gain during the festival!",
    isForever = false,
  },
  [8291] = {
    id = 8291,
    title = "Vanquish the Invaders!",
    reqLevel = 60,
    questLevel = 60,
    faction = "Alliance",
    zone = "Warsong Gulch",
    npc = "Sentinel Farsong",
    objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Silverwing Talisman of Merit, and return to Sentinel Farsong at the Silverwing Grove.",
    rewards = "6,600 XP • 2g 70s",
    tip = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.",
    isForever = false,
  },
  [8603] = {
    id = 8603,
    title = "Vestments of the Oracle",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Ahn'Qiraj",
    npc = "Vethsera",
    objectives = "Bring the the Husk of the Old God, 2 Idols of Death, 5 Stone Scarabs and 5 Crystal Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",
    rewards = "9,950 XP",
    tip = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",
    isForever = false,
  },
  [8572] = {
    id = 8572,
    title = "Veteran's Battlegear",
