  [4769] = {
    id = 4769,
    title = "Vivian Lagrave and the Darkstone Tablet",
    reqLevel = 57,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Apothecary Zinge",
    objectives = "Speak with Shadowmage Vivian Lagrave.",
    rewards = "660 XP",
    tip = "Vivian Lagrave sent me word from Kargath, in the Badlands.  Through her studies, she believes there is an ancient text within Blackrock Spire that would benefit our research.  To confirm this, she will need someone to extract the text from the spire.  No easy task.\n\nIf interested, then speak with Vivian in Kargath.",
