    title = "Volunteer's Battlegear",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Vargus",
    objectives = "Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus.  You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest.",
    rewards = "3,300 XP",
    tip = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $N.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.",
    isForever = false,
  },
  [8321] = {
    id = 8321,
    title = "Vyral the Vile",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Huum Wildmane",
    objectives = "Bring Vyral's Signet Ring to Huum Wildmane in Cenarion Hold.",
    rewards = "6,600 XP • 90s",
    tip = "We have discovered another base of operations for the Twilight's Hammer.  It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus.  The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat.  When you have done this, bring me his signet ring.\n\nFortune to you, $N.  The horrors of Twilight's Run are formidable indeed.",
    isForever = false,
  },
  [8447] = {
