  [9362] = {
    id = 9362,
    title = "Warlord Krellian",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Mage Class Quests",
    npc = "Archmage Xylem",
    objectives = "Retrieve the Prismatic Shell for Archmage Xylem.  The Archmage resides in a tower atop the cliffs of Azshara.",
    rewards = "6,600 XP",
    tip = "There isn't much time, $n!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.",
    isForever = false,
  },
  [4903] = {
    id = 4903,
    title = "Warlord's Command",
    reqLevel = 55,
    questLevel = 60,
    faction = "Horde",
    zone = "Blackrock Spire",
    npc = "Item: Warlord Goretooth's Command",
    objectives = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",
    rewards = "8,300 XP • 1g 80s",
    tip = "By order of Warlord Goretooth, the following inhabitants of Blackrock Spire must be destroyed:\n\nThe rotund menace, Highlord Omokk.\n\nThe cruel and ruthless troll, War Master Voone.\n\nOverlord Wyrmthalak, taskmaster of the lesser city.\n\nYou will also be required to return any important documents that you may find.\n\nSucceed and be honored.\n\nFail and be forgotten.",
    isForever = false,
  },
  [8286] = {
    id = 8286,
    title = "What Tomorrow Brings",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Silithus",
    npc = "Baristolth of the Shifting Sands",
    objectives = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.",
    rewards = "6,600 XP",
    tip = "The embrace of death had all but overcome my being when he intervened. He breathed only once upon my maimed body and then waited patiently for the sands of time to cleanse my wounds.\n\n\"Forever you will remain if you must\", he said, and with those words I was bound as a Watcher.\n\nLook now to the desert. The second war is upon us. You must seek out the resting place of the Bronze. Venture to the Caverns of Time and see if the master has returned. I must be sure before I am able to proceed.",
    isForever = false,
  },
