  [5201] = {
    id = 5201,
    title = "Winterfall Intrusion",
    reqLevel = 58,
    questLevel = 60,
    faction = "Alliance",
    zone = "Winterspring",
    npc = "Rivern Frostwind",
    objectives = "Rivern Frostwind wants you to slay 5 Winterfall Shaman and 5 Winterfall Ursa.",
    rewards = "Experience & Faction Reputation",
    tip = "My presence goes unnoticed by most, $N. However, there is an annoyance that seems firmly rooted here in Winterspring: the Winterfall furbolg.\n\nAlthough I have never directly attacked the furbolg, they seem crazed, fearful of anything in their path. I have watched them slay countless creatures that had the misfortune to simply be in the wrong place at the wrong time.\n\nI am weary of their meddling -- please, help me by fighting back. Slay the furbolg and keep them away from Frostsaber Rock.",
    isForever = false,
  },
  [8674] = {
    id = 8674,
    title = "Winterhoof the Elder",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Elder Winterhoof",
