  },
  [5161] = {
    id = 5161,
    title = "Wrath of the Blue Flight",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Winterspring",
    npc = "Haleh",
    objectives = "Speak with Haleh if you wish to continue.",
    rewards = "660 XP",
    tip = "We understand what the cursed brood of Deathwing attempts to do and we know that it cannot be allowed.\n\nBecause of the protection Blackrock mountain affords Nefarian, it has become increasingly difficult for us to intercede.\n\nWe can, however, empower you, mortal - should you so choose.\n\nThe path before you is one full of peril. You must decide whether to accept our help. Ponder this and speak with me again when a decision has been made.",
    isForever = false,
  },
  [5162] = {
    id = 5162,
    title = "Wrath of the Blue Flight",
    reqLevel = 57,
    questLevel = 60,
    faction = "Both",
    zone = "Western Plaguelands",
    npc = "Haleh",
    objectives = "Speak with Jeziba in the Plaguelands. He resides in Andorhal.",
    rewards = "6,600 XP",
    tip = "It is the arcane that I control and the arcane which will send you to your next destination.\n\nWhen you are ready, the journey will begin. To the Plaguelands you will go and to Jeziba you will speak.\n\nHe is a mortal as wise as the ancients and as patient as the immovable earth. Find him in Andorhal.",
    isForever = false,
  },
  [9165] = {
    id = 9165,
    title = "Writ of Safe Passage",
    reqLevel = 55,
    questLevel = 60,
    faction = "Both",
    zone = "Eastern Plaguelands",
    npc = "Guard Didier",
    objectives = "Deliver the signed Writ of Safe Passage to Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands.",
    rewards = "Experience & Faction Reputation",
    tip = "Without the help of adventurers, my caravan would have never made it! Scourge were coming out of the woodwork to try and stop us from getting here.\n\n<Guard Didier wipes his brow.>\n\nNow we need to wait here for Field Marshal Chambers to arrive. He'll sign your writ of safe passage to take back to Dispatch Commander Metz at Light's Hope Chapel.\n\nAnd $N, watch what you say around Chambers. He's the 'bite off your head and spit down your wind pipe' type of guy - except that he'll actually do it...",
    isForever = false,
  },
  [7625] = {
    id = 7625,
    title = "Xorothian Stardust",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Warlock Class Quests",
    npc = "Lord Banehollow",
    objectives = "Purchase Xorothian Stardust from Ur'dan.  Bring it to Gorzeeki Wildeyes in the Burning Steppes.",
    rewards = "6,600 XP",
    tip = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?\n\nVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price.",
    isForever = false,
  },
  [3628] = {
    id = 3628,
    title = "You Are Rakh'likh, Demon",
    reqLevel = 45,
    questLevel = 60,
    faction = "Both",
    zone = "Blasted Lands",
    npc = "Fallen Hero of the Horde",
    objectives = "- Severed Horn of the Defiler",
    rewards = "9,950 XP, 2g 70s",
    tip = "Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, $N. Use it on the Altar of the Defiler.\n\nShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.",
    isForever = false,
  },
  [915] = {
    id = 915,
    title = "You Scream, I Scream...",
    reqLevel = 10,
    questLevel = 60,
    faction = "Horde",
    zone = "Azeroth",
    npc = "Orcish Orphan",
    objectives = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
    rewards = "650 XP",
    tip = "ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule and Foror's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!\n\nI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule and Foror's Strawberry Ice Cream on top??!?!",
    isForever = false,
  },
  [4822] = {
