  [7937] = {
    id = 7937,
    title = "Your Fortune Awaits You...",
    reqLevel = 10,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: Sayge's Fortune #23",
    objectives = "Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune.",
    rewards = "660 XP",
    tip = "\"Your fortune awaits you in Eastvale.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest.  Focusing closer in on the image, you see a haystack that sits next to a stable.",
    isForever = false,
  },
  [7938] = {
    id = 7938,
    title = "Your Fortune Awaits You...",
    reqLevel = 10,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Item: Sayge's Fortune #24",
    objectives = "Travel to the Deadmines in Westfall and seek out your fortune.",
    rewards = "660 XP",
    tip = "\"Your fortune awaits you inside the Deadmines.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Deadmines inside Westfall's ruined hamlet of Moonbrook.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the mines itself.  Stepping through it, a strange chest appears out from nowhere.",
    isForever = false,
  },
  [7944] = {
