  [8980] = {
    id = 8980,
    title = "Zinge's Assessment",
    reqLevel = 1,
    questLevel = 60,
    faction = "Both",
    zone = "Seasonal Events",
    npc = "Apothecary Zinge",
    objectives = "Return to Fenstad Argyle outside the bank in the Undercity.",
    rewards = "Experience & Faction Reputation",
    tip = "This is unexpected. It looks like Fenstad might be on to something after all. I found traces of substances used in mind control potions.\n\nIt isn't unheard of for perfumes to have some of this, but a few of the ingredients I detected... This is serious alchemy, along the abilities of a member of the Royal Apothecary Society.",
    isForever = false,
  },
  [8195] = {
    id = 8195,
    title = "Zulian, Razzashi, and Hakkari Coins",
    reqLevel = 58,
    questLevel = 60,
    faction = "Both",
    zone = "Azeroth",
    npc = "Vinchaxa",
    objectives = "- Zulian Coin - Razzashi Coin - Hakkari Coin",
    rewards = "Experience & Faction Reputation",
    tip = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Some are sought after by my compatriots for various armors they offer Zandalar heroes.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.",
    isForever = false,
  },
  [8598] = {
    id = 8598,
    title = "rAnS0m",
    reqLevel = 60,
    questLevel = 60,
    faction = "Both",
    zone = "Tanaris",
    npc = "Object: Freshly Dug Dirt",
    objectives = "Return the Ransom Letter to Narain Soothfancy in Tanaris.",
    rewards = "3,300 XP",
    tip = "<The text on this note is made up of various typefaces glued onto the parchment's surface.>\n\nWe've got your precious book, gnome. If you ever want to see it again, you'll do exactly as we ask.\n\n<A detailed set of instructions is listed, spanning 3 pages.>\n\nBring the money and come alone!",
    isForever = false,
  },
  [8053] = {
    id = 8053,
    title = "Paragons of Power: The Freethinker's Armguards",
    reqLevel = 60,
    questLevel = 61,
    faction = "Both",
    zone = "Azeroth",
    npc = "Jin'rokh the Breaker",
    objectives = "Bring Jin'rokh the Breaker Primal Hakkari Bindings.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "You are a heathen.  Heathens have a place in the tribe.  Heathens are freethinkers of Zandalar.  Freethinkers do not fear oppression.  Freethinkers die for what they believe in.  We know you would die for what you believe in.  This earns our acknowledgement.  This earns you a chance to prove yourself further.\n\nWe must have the Paragons of Power.  Go to Zul'Gurub.  Kill the minions of Hakkar.  Return when you have what I seek.  Claim the first battle gear of a Zandalar freethinker.\n\nGo.",
    isForever = false,
  },
  [8054] = {
    id = 8054,
    title = "Paragons of Power: The Freethinker's Belt",
    reqLevel = 60,
    questLevel = 61,
    faction = "Both",
    zone = "Azeroth",
    npc = "Jin'rokh the Breaker",
    objectives = "Bring Jin'rokh the Breaker a Primal Hakkari Shawl.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Your beliefs are alien to us, heathen.  Ancient Zandalar were once branded as heretics.  This was when the Gurubashi Empire was strong.  Heathens dared to challenge the priest of Hakkar.  Heathens then were hunted and killed as vermin.  Those heathens never wavered in their fight against the Blood God.  We honor the price they paid.  They are the freethinkers.\n\nDestroy the minions of Hakkar in Zul'Gurub.  Bring me the Paragons of Power I seek.  Success will be greatly rewarded.\n\nGo.",
    isForever = false,
  },
  [8055] = {
    id = 8055,
    title = "Paragons of Power: The Freethinker's Breastplate",
    reqLevel = 60,
    questLevel = 61,
    faction = "Both",
    zone = "Azeroth",
    npc = "Jin'rokh the Breaker",
    objectives = "Bring Jin'rokh the Breaker a Primal Hakkari Tabard.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",
    rewards = "6,600 XP",
    tip = "Battle gear gives you power in the tribe.  The freethinkers are honored in this way.  They are zealots.  They imbue their breastplates with powerful mojo.  If their beliefs falter in the face of the enemy, their breastplate will not.\n\nYou must be revered amongst us to possess such a breastplate.  Go to Zul'Gurub.  Take the Paragons of Power I need.  Take the Paragons most painfully from the fools inside.  Bring them to me.  Prove your worth as a freethinker once and for all.",
    isForever = false,
  },
  [8860] = {
    id = 8860,
    title = "New Year Celebrations!",
    reqLevel = 60,
    questLevel = 70,
    faction = "Alliance",
    zone = "Seasonal Events",
    npc = "Wonderform Operator",
    objectives = "Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.",
    rewards = "9s",
    tip = "Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they'll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Allison in Stormwind needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!\n\nThanks, $N!  Innkeeper Allison is in the Gilded Rose, in the Trade District of Stormwind.",
    isForever = false,
  },
  [8861] = {
    id = 8861,
    title = "New Year Celebrations!",
    reqLevel = 60,
    questLevel = 70,
    faction = "Horde",
    zone = "Seasonal Events",
    npc = "Wonderform Operator",
    objectives = "Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.",
    rewards = "9s",
    tip = "Thunder Bluff is holding a celebration for the new year!  All day you'll find free booze there, and at night they'll put on a firework show!\n\nIt should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!\n\nThanks, $N!  Innkeeper Pala is in the inn near the bridge to Hunter's Rise.",
    isForever = false,
  },
}

