ForeverGuide_Data.Attunements = {
  ["onyxia"] = {
    ["title"] = "Onyxia's Lair Attunement Guide",
    ["alliance"] = "1. Start with 'Dragonkin Menace' in Morgan's Vigil (Burning Steppes).\n2. Complete Marshal Windsor quest chain in Blackrock Depths (jailbreak escort).\n3. Bring Windsor to Stormwind Keep to unmask Lady Katrana Prestor as Onyxia.\n4. Slay General Drakkisath in UBRS for the Blood of the Black Dragon Champion to forge your Drakefire Amulet.",
    ["horde"] = "1. Start with 'Warlord's Command' in Kargath (Badlands).\n2. Slay Overlord Wyrmthalak (LBRS) and return to Thrall in Orgrimmar.\n3. Meet Rexxar roaming Desolace / Feralas border.\n4. Journey to Dustwallow Marsh to consult Myranda the Hag.\n5. Slay General Drakkisath in UBRS and return to Rexxar for the Drakefire Amulet.",
    ["tip"] = "You MUST have the Drakefire Amulet in your inventory to pass through the instance portal in Dustwallow Marsh!",
  },
  ["molten core"] = {
    ["title"] = "Molten Core Attunement (Attunement to the Core)",
    ["guide"] = "1. Speak to Lothos Riftwaker stationed outside Blackrock Mountain (level 55+).\n2. Enter Blackrock Depths and navigate through the Lyceum to the Molten Core threshold.\n3. Loot the 'Core Fragment' from the stalagmite next to the entrance portal.\n4. Return to Lothos Riftwaker to complete the quest.",
    ["tip"] = "Once completed, you can click on Lothos Riftwaker directly to teleport your entire raid into Molten Core without walking through BRD!",
  },
  ["blackwing lair"] = {
    ["title"] = "Blackwing Lair Attunement (Blackhand's Command)",
    ["guide"] = "1. Kill the Scarshield Quartermaster right outside the UBRS/LBRS hallway in Blackrock Mountain.\n2. Loot 'Blackhand's Command' and read the letter to accept the quest.\n3. Enter Upper Blackrock Spire (UBRS) and slay General Drakkisath.\n4. Click the 'Orb of Ascension' located directly behind General Drakkisath's throne.",
    ["tip"] = "Once attuned, you can touch the golden Orb of Command at the end of the Blackrock Mountain hallway to teleport straight into BWL.",
  },
  ["temporal rift"] = {
    ["title"] = "The Temporal Rift Raid Attunement (WoW: Forever)",
    ["guide"] = "1. Speak to Watcher Leor at the Blasted Lands Redoubt (62, 38) at Level 60.\n2. Infiltrate the sealed perimeter around the Unopened Dark Portal.\n3. Slay 3 Chronomantic Rift-stalkers to gather Temporal Shards.\n4. Forge your Temporal Chronometer to attune your character to the alternate timeline.",
    ["tip"] = "The Temporal Rift is Forever's flagship 20-player raid tier featuring the 'Signet of the Unopened Portal' horizontal tier set.",
  },
  ["verdant scar"] = {
    ["title"] = "The Verdant Scar Raid Attunement (Mount Hyjal - WoW Forever)",
    ["guide"] = "1. Reach Honored reputation with the **Cenarion Circle** at Nordrassil Sanctuary in Mount Hyjal (52, 28).\n2. Accept 'Whispers Beneath the World Tree' from Archdruid Hamuul / Keeper Remulos.\n3. Enter **Roots of Nordrassil** (5-man dungeon) and cleanse the 3 Emerald Boughs.\n4. Defeat the Corrupted Satyr Lord to forge the **Bough of Nordrassil** raid key.",
    ["tip"] = "Only one raid member per 40-man group needs the Bough of Nordrassil to open the Emerald Bramble gate into The Verdant Scar.",
  },
  ["ubrs"] = {
    ["title"] = "Upper Blackrock Spire (UBRS) Attunement (Seal of Ascension)",
    ["guide"] = "1. Speak to Vaelan (disguised in the upper LBRS ramparts near Halycon's lair) to accept 'Seal of Ascension'.\n2. Farm LBRS bosses for the 3 gemstones: **Gemstone of Spirestone** (Highlord Omokk), **Gemstone of Smolderthorn** (War Master Voone), and **Gemstone of Bloodaxe** (Overlord Wyrmthalak).\n3. Travel to Dustwallow Marsh (Wyrmbog) and use the Unforged Seal + Draconic Energy on Emberstrife (at 10% HP, Mind Control him to breath on the seal).\n4. Return to Vaelan in LBRS to receive the permanent **Seal of Ascension** ring.",
    ["tip"] = "Only one player in the 10-man UBRS raid needs the Seal of Ascension in their bags to unlock the door!",
  },
  ["aq40"] = {
    ["title"] = "Temple & Ruins of Ahn'Qiraj (AQ20 / AQ40) Gate & Scepter Guide",
    ["guide"] = "1. **Raid Entry:** No personal key is required once the Gates of Ahn'Qiraj have been opened on the realm.\n2. **Scepter of the Shifting Sands (Scarab Lord Chain):** Start with 'What Tomorrow Brings' from Baristolth of the Shifting Sands in Cenarion Hold.\n3. Slay Broodlord Lashlayer in BWL for his head, farm 42,000 Silithid Carapace Fragments to reach Neutral with Brood of Nozdormu, and forge the Blue, Green, and Red Scepter Shards.",
    ["tip"] = "Once inside AQ40, loot a Qiraji Resonating Crystal (Blue, Green, Yellow, or Red) from trash packs for an instant-summon bug mount inside the temple!",
  },
  ["zg"] = {
    ["title"] = "Zul'Gurub (ZG) Entry & Yojamba Isle Attunement Guide",
    ["guide"] = "1. **Raid Entry:** Zul'Gurub requires **no personal attunement key** — any Level 60 player in a raid group can enter the eastern Stranglethorn Vale portal (53, 17).\n2. **Yojamba Isle Faction Hub:** Sail or swim to **Yojamba Isle** in northwestern Stranglethorn Vale (15, 16) before your first run to pick up the **Zandalar Tribe** starter quests and class armor token quests.\n3. **Edge of Madness Summon:** Bring an Alchemist with 300 skill and *Gurubashi Mojo Madness* (plus Massive Mojo and Black Lotus) to summon the rotating Edge of Madness bosses.",
    ["tip"] = "Always destroy at least 1 Primal Hakkari Bijou at the Zanza Altar inside ZG to unlock your Zandalar Signet shoulder enchant quest!",
  },
  ["karazhan crypts"] = {
    ["title"] = "Karazhan Crypts Attunement (Deadwind Pass - WoW Forever)",
    ["guide"] = "1. Speak to **Archmage Alturus** outside the Karazhan tower in Deadwind Pass (47, 75) at Level 58+.\n2. Complete 'Echoes of the Guardian' by recovering 3 Ley-Touched Fragments from Morgan's Plot and the Vice catacombs.\n3. Slay the Dark Rider Envoy at the master cellar gate to forge the **Key to the Lower Crypts**.",
    ["tip"] = "Only one party member needs the Key to the Lower Crypts (or a Rogue with 300 Lockpicking) to open the iron crypt grate behind Karazhan.",
  },
  ["naxxramas"] = {
    ["title"] = "Naxxramas Attunement (The Dread Citadel - Naxxramas)",
    ["guide"] = "1. Reach Level 60 and at least **Honored** reputation with the **Argent Dawn**.\n2. Speak to **Archmage Angela Dosantos** at Light's Hope Chapel in Eastern Plaguelands.\n3. Turn in the required materials based on your Argent Dawn reputation:\n   • **Honored:** 5 Righteous Orbs, 2 Arcane Crystals, 1 Nexus Crystal, and 60 Gold\n   • **Revered:** 2 Righteous Orbs, 1 Arcane Crystal, and 30 Gold\n   • **Exalted:** Absolutely FREE! (No materials or gold required)",
    ["tip"] = "Grind Scholomance/Stratholme scourge stones or farm cauldron quests to reach Exalted and save valuable crafting materials!",
  },
}

